def entrance_angled(angle, method='Idelchik'):
    if method is None:
        method = 'Idelchik'
    if method == 'Idelchik':
        cos_term = cos(radians(angle))
        return 0.57 + cos_term * (0.2 * cos_term + 0.3)
    else:
        raise ValueError('Specified method not recognized; methods are %s' % entrance_angled_methods)

def list_from_args(args):
    if not args:
        return []
    arg_type = type(args[0])
    is_list = arg_type in LIST_TYPES
    same_type = all([isinstance(arg, arg_type) for arg in args])
    if not same_type:
        raise Exception('Expected uniform arguments of same type !')
    if is_list:
        args_lists = map(list, args)
        flattened_args = sum(args_lists, [])
        return flattened_args
    return list(args)

