def merge_attributes(attr1, attr2):
    new_d = copy.deepcopy(attr1)
    new_d.update(attr2)
    for (k, v) in new_d.items():
        if not isinstance(v, list):
            new_d[k] = [v]
    for (k, v) in six.iteritems(attr1):
        if k in attr2:
            if not isinstance(v, list):
                v = [v]
            new_d[k].extend(v)
    return dict(((k, sorted(set(v))) for (k, v) in new_d.items()))

def query(self, logLevel='WARNING', source='ALL', startTime=None, endTime=None, logCodes=None, users=None, messageCount=1000):
    url = self._url + '/query'
    filter_value = {'codes': [], 'users': [], 'source': '*'}
    if source.lower() == 'all':
        filter_value['source'] = '*'
    else:
        filter_value['source'] = [source]
    params = {'f': 'json', 'level': logLevel}
    if not startTime is None and isinstance(startTime, datetime):
        params['startTime'] = startTime.strftime('%Y-%m-%dT%H:%M:%S')
    if not endTime is None and isinstance(endTime, datetime):
        params['endTime'] = startTime.strftime('%Y-%m-%dT%H:%M:%S')
    if not logCodes is None:
        filter_value['codes'] = logCodes.split(',')
    if not users is None:
        filter_value['users'] = users.split(',')
    if messageCount is None:
        params['pageSize'] = 1000
    elif isinstance(messageCount, (int, long, float)):
        params['pageSize'] = int(messageCount)
    else:
        params['pageSize'] = 1000
    params['filter'] = filter_value
    return self._get(url=url, param_dict=params, securityHandler=self._securityHandler, proxy_url=self._proxy_url, proxy_port=self._proxy_port)

