def skip_id3(fileobj):
    while True:
        idata = fileobj.read(10)
        try:
            (id3, insize) = struct.unpack('>3sxxx4s', idata)
        except struct.error:
            (id3, insize) = (b'', 0)
        insize = BitPaddedInt(insize)
        if id3 == b'ID3' and insize > 0:
            fileobj.seek(insize, 1)
        else:
            fileobj.seek(-len(idata), 1)
            break

def read_FITS_cols(infile, cols=None):
    with fits.open(infile, memmap=False) as ftab:
        extnum = 0
        extfound = False
        for extn in ftab:
            if 'tfields' in extn.header:
                extfound = True
                break
            extnum += 1
        if not extfound:
            print('ERROR: No catalog table found in ', infile)
            raise ValueError
        if _is_str_none(cols[0]) is None:
            cols = ftab[extnum].data.names
        outarr = [ftab[extnum].data.field(c) for c in cols]
    return outarr

