def format_v1_score_response(response, limit_to_model=None):
    response_doc = defaultdict(dict)
    for (rev_id, rev_scores) in response.scores.items():
        for (model_name, score) in rev_scores.items():
            response_doc[rev_id][model_name] = score
    for (rev_id, rev_errors) in response.errors.items():
        for (model_name, error) in rev_errors.items():
            response_doc[rev_id][model_name] = util.format_error(error)
    if limit_to_model is not None:
        return util.jsonify({rev_id: model_scores[limit_to_model] for (rev_id, model_scores) in response_doc.items()})
    else:
        return util.jsonify(response_doc)

def add_beacon(self, name, beacon_data):
    data = {}
    data[name] = beacon_data
    if name in self._get_beacons(include_opts=False):
        comment = 'Cannot update beacon item {0}, because it is configured in pillar.'.format(name)
        complete = False
    else:
        if name in self.opts['beacons']:
            comment = 'Updating settings for beacon item: {0}'.format(name)
        else:
            comment = 'Added new beacon item: {0}'.format(name)
        complete = True
        self.opts['beacons'].update(data)
    evt = salt.utils.event.get_event('minion', opts=self.opts)
    evt.fire_event({'complete': complete, 'comment': comment, 'beacons': self.opts['beacons']}, tag='/salt/minion/minion_beacon_add_complete')
    return True

def _step(self, theme, direction):
    if not self.themes:
        self.reload()
    key = (theme.source, theme.name)
    for (i, val) in enumerate(self.themes):
        if (val.source, val.name) == key:
            index = i
            break
    else:
        self.themes.insert(0, theme)
        index = 0
    index = (index + direction) % len(self.themes)
    new_theme = self.themes[index]
    return new_theme

def page(self, course, msgs=None):
    msgs = msgs if msgs else []
    user_input = self.get_input()
    (data, classroom) = self.get_submissions(course, user_input)
    if len(data) == 0 and (not self.show_collapse(user_input)):
        msgs.append(_('No submissions found'))
    classrooms = self.user_manager.get_course_aggregations(course)
    users = self.get_users(course)
    tasks = course.get_tasks()
    statistics = None
    if user_input.stat != 'no_stat':
        statistics = compute_statistics(tasks, data, True if 'with_pond_stat' == user_input.stat else False)
    if 'csv' in web.input():
        return make_csv(data)
    if 'download' in web.input():
        web.header('Content-Type', 'application/x-gzip', unique=True)
        web.header('Content-Disposition', 'attachment; filename="submissions.tgz"', unique=True)
        aggregations = dict([(username, aggregation if course.use_classrooms() or username in aggregation['groups'][0]['students'] else None) for aggregation in classroom for username in aggregation['students']])
        download_type = web.input(download_type=self._valid_formats[0]).download_type
        if download_type not in self._valid_formats:
            download_type = self._valid_formats[0]
        return self.submission_manager.get_submission_archive(data, list(reversed(download_type.split('/'))), aggregations)
    if user_input.limit != '' and user_input.limit.isdigit():
        data = data[:int(user_input.limit)]
    if len(data) > self._trunc_limit:
        msgs.append(_('The result contains more than {0} submissions. The displayed submissions are truncated.\n').format(self._trunc_limit))
        data = data[:self._trunc_limit]
    return self.template_helper.get_renderer().course_admin.submissions(course, tasks, users, classrooms, data, statistics, user_input, self._allowed_sort, self._allowed_sort_name, self._valid_formats, msgs, self.show_collapse(user_input))

