def norm_join(prefix, suffix):
    if prefix is None and suffix is None:
        return '.'
    if prefix is None:
        return os.path.normpath(suffix)
    if suffix is None:
        return os.path.normpath(prefix)
    return os.path.normpath(os.path.join(prefix, suffix))

