def persistent_entropy(dgms, keep_inf=False, val_inf=None, normalize=False):
    if isinstance(dgms, list) == False:
        dgms = [dgms]
    if keep_inf == False:
        dgms = [dgm[dgm[:, 1] != np.inf] for dgm in dgms]
    if keep_inf == True:
        if val_inf != None:
            dgms = [np.where(dgm == np.inf, val_inf, dgm) for dgm in dgms]
        else:
            raise Exception('Remember: You need to provide a value to infinity bars if you want to keep them.')
    ps = []
    for dgm in dgms:
        l = dgm[:, 1] - dgm[:, 0]
        if all(l > 0):
            L = np.sum(l)
            p = l / L
            E = -np.sum(p * np.log(p))
            if normalize == True:
                E = E / np.log(len(l))
            ps.append(E)
        else:
            raise Exception('A bar is born after dying')
    return np.array(ps)

def number(digit):
    spoken = str(digit)
    if spoken.startswith('8') or spoken[:len(spoken) % 3] == '11':
        article = 'an '
    else:
        article = 'a '
    if spoken.endswith('1') and spoken != '11':
        suffix = 'st'
    elif spoken.endswith('2') and spoken != '12':
        suffix = 'nd'
    elif spoken.endswith('3') and spoken != '13':
        suffix = 'rd'
    else:
        suffix = 'th'
    if digit > 999:
        prefix = len(spoken) % 3
        separated = spoken[:prefix]
        for n in range(prefix, len(spoken), 3):
            separated += ',' + spoken[n:n + 3]
        spoken = separated
    return article + spoken + suffix

def from_line(cls, name, comes_from=None):
    url = None
    name = name.strip()
    req = None
    path = os.path.normpath(os.path.abspath(name))
    link = None
    if is_url(name):
        link = Link(name)
    elif os.path.isdir(path) and (os.path.sep in name or name.startswith('.')):
        if not is_installable_dir(path):
            raise InstallationError("Directory %r is not installable. File 'setup.py' not found.", name)
        link = Link(path_to_url(name))
    elif is_archive_file(path):
        if not os.path.isfile(path):
            logger.warn('Requirement %r looks like a filename, but the file does not exist', name)
        link = Link(path_to_url(name))
    if link and req is None:
        url = link.url_fragment
        req = link.egg_fragment
        if link.scheme == 'file' and re.search('\\.\\./', url):
            url = path_to_url(os.path.normpath(os.path.abspath(link.path)))
    else:
        req = name
    return cls(req, comes_from, url=url)

