def expandvars(self, text, environ=None, cache=None):
    if not environ:
        environ = os.environ
    if not text:
        return ''
    cache = cache or {}
    output = nstr(text)
    keys = re.findall('\\$(\\w+)|\\${(\\w+)\\}|\\%(\\w+)\\%', text)
    for (first, second, third) in keys:
        repl = ''
        key = ''
        if first:
            repl = '$%s' % first
            key = first
        elif second:
            repl = '${%s}' % second
            key = second
        elif third:
            repl = '%%%s%%' % third
            key = third
        else:
            continue
        value = environ.get(key)
        if value:
            if key not in cache:
                cache[key] = value
                value = self.expandvars(value, environ, cache)
            else:
                err = '%s environ variable causes an infinite loop.' % key
                logger.warning(err)
                value = cache[key]
        else:
            value = repl
        output = output.replace(repl, value)
    return os.path.expanduser(output)

