def update(self, data):
    if data is None:
        return
    for (key, value) in sorted(data.items()):
        if key.startswith('/'):
            name = key.lstrip('/')
            match = re.search('([^/]+)(/.*)', name)
            if match:
                name = match.groups()[0]
                value = {match.groups()[1]: value}
            self.child(name, value)
        else:
            self.data[key] = value
    log.debug("Data for '{0}' updated.".format(self))
    log.data(pretty(self.data))

