def recarrayisin(X, Y, weak=True):
    if weak and set(X.dtype.names) != set(Y.dtype.names) or (not weak and X.dtype.names != Y.dtype.names):
        return np.zeros((len(X),), bool)
    else:
        if X.dtype.names != Y.dtype.names:
            Y = np.rec.fromarrays([Y[a] for a in X.dtype.names], names=X.dtype.names)
        NewX = np.array([str(l) for l in X])
        NewY = np.array([str(l) for l in Y])
        NewY.sort()
        return isin(NewX, NewY)

