    _AddAnalysis(accum, 'FlowAccumulation(dem, method={method}, exponent={exponent}, weights={weights}, in_place={in_place})'.format(method=method, exponent=exponent, weights='None' if weights is None else 'weights', in_place=in_place))
    if method in facc_methods:
        facc_methods[method](dem.wrap(), accumw)
    elif method in facc_methods_exponent:
        if exponent is None:
            raise Exception('FlowAccumulation method "' + method + '" requires an exponent!')
        facc_methods_exponent[method](dem.wrap(), accumw, exponent)
    else:
        raise Exception('Invalid FlowAccumulation method. Valid methods are: ' + ', '.join(list(facc_methods.keys()) + list(facc_methods_exponent.keys())))
    accum.copyFromWrapped(accumw)
    return accum

def loads(data, validate=False, **kwargs):
    d = json.loads(data, **kwargs)
    content_spec = d['content-spec']
    Payload = CONTENT_SPECS[content_spec]
    payload = Payload.load(d)
    if validate:
        errors = payload.problems()
        if errors:
            raise ValidationError(errors)
    return payload

def run_loop(name, train_input_fn, eval_input_fn, model_column_fn, build_estimator_fn, flags_obj, tensors_to_log, early_stop=False):
    model_helpers.apply_clean(flags.FLAGS)
    model = build_estimator_fn(model_dir=flags_obj.model_dir, model_type=flags_obj.model_type, model_column_fn=model_column_fn, inter_op=flags_obj.inter_op_parallelism_threads, intra_op=flags_obj.intra_op_parallelism_threads)
    run_params = {'batch_size': flags_obj.batch_size, 'train_epochs': flags_obj.train_epochs, 'model_type': flags_obj.model_type}
    benchmark_logger = logger.get_benchmark_logger()
    benchmark_logger.log_run_info('wide_deep', name, run_params, test_id=flags_obj.benchmark_test_id)
    loss_prefix = LOSS_PREFIX.get(flags_obj.model_type, '')
    tensors_to_log = {k: v.format(loss_prefix=loss_prefix) for (k, v) in tensors_to_log.items()}
    train_hooks = hooks_helper.get_train_hooks(flags_obj.hooks, model_dir=flags_obj.model_dir, batch_size=flags_obj.batch_size, tensors_to_log=tensors_to_log)
    for n in range(flags_obj.train_epochs // flags_obj.epochs_between_evals):
        model.train(input_fn=train_input_fn, hooks=train_hooks)
        results = model.evaluate(input_fn=eval_input_fn)
        tf.logging.info('Results at epoch %d / %d', (n + 1) * flags_obj.epochs_between_evals, flags_obj.train_epochs)
        tf.logging.info('-' * 60)
        for key in sorted(results):
            tf.logging.info('%s: %s' % (key, results[key]))
        benchmark_logger.log_evaluation_result(results)
        if early_stop and model_helpers.past_stop_threshold(flags_obj.stop_threshold, results['accuracy']):
            break
    if flags_obj.export_dir is not None:
        export_model(model, flags_obj.model_type, flags_obj.export_dir, model_column_fn)

def build(algo, init):
    x = theano.shared(np.array(init, FLOAT), name='x')
    n = 0.1 * RandomStreams().normal((len(init) - 1,))
    monitors = []
    if len(init) == 2:
        monitors.extend([('x', x[:-1].sum()), ('y', x[1:].sum())])
    return downhill.build(algo, loss=(n + 100 * (x[1:] - x[:-1] ** 2) ** 2 + (1 - x[:-1]) ** 2).sum(), params=[x], monitors=monitors, monitor_gradients=True)

