def score(self, X, design, scan_onsets=None):
    assert X.ndim == 2 and X.shape[1] == self.beta_.shape[1], 'The shape of X is not consistent with the shape of data used in the fitting step. They should have the same number of voxels'
    assert scan_onsets is None or (scan_onsets.ndim == 1 and 0 in scan_onsets), 'scan_onsets should either be None or an array of indices If it is given, it should include at least 0'
    if scan_onsets is None:
        scan_onsets = np.array([0], dtype=int)
    else:
        scan_onsets = np.int32(scan_onsets)
    ll = self._score(Y=X, design=design, beta=self.beta_, scan_onsets=scan_onsets, beta0=self.beta0_, rho_e=self.rho_, sigma_e=self.sigma_, rho_X0=self._rho_X0_, sigma2_X0=self._sigma2_X0_)
    ll_null = self._score(Y=X, design=None, beta=None, scan_onsets=scan_onsets, beta0=self.beta0_, rho_e=self.rho_, sigma_e=self.sigma_, rho_X0=self._rho_X0_, sigma2_X0=self._sigma2_X0_)
    return (ll, ll_null)

