def from_array(a, mode=None, info={}):
    info = dict(info)
    match = RegexModeDecode.match(mode)
    if not match:
        raise Error("mode string should be 'RGB' or 'L;16' or similar.")
    (mode, bitdepth) = match.groups()
    if bitdepth:
        bitdepth = int(bitdepth)
    if 'greyscale' in info:
        if bool(info['greyscale']) != ('L' in mode):
            raise ProtocolError("info['greyscale'] should match mode.")
    info['greyscale'] = 'L' in mode
    alpha = 'A' in mode
    if 'alpha' in info:
        if bool(info['alpha']) != alpha:
            raise ProtocolError("info['alpha'] should match mode.")
    info['alpha'] = alpha
    if bitdepth:
        if info.get('bitdepth') and bitdepth != info['bitdepth']:
            raise ProtocolError('bitdepth (%d) should match bitdepth of info (%d).' % (bitdepth, info['bitdepth']))
        info['bitdepth'] = bitdepth
    (width, height) = check_sizes(info.get('size'), info.get('width'), info.get('height'))
    if width:
        info['width'] = width
    if height:
        info['height'] = height
    if 'height' not in info:
        try:
            info['height'] = len(a)
        except TypeError:
            raise ProtocolError("len(a) does not work, supply info['height'] instead.")
    planes = len(mode)
    if 'planes' in info:
        if info['planes'] != planes:
            raise Error("info['planes'] should match mode.")
    (a, t) = itertools.tee(a)
    row = next(t)
    del t
    testelement = row
    if 'width' not in info:
        width = len(row) // planes
        info['width'] = width
    if 'bitdepth' not in info:
        try:
            dtype = testelement.dtype
        except AttributeError:
            try:
                bitdepth = 8 * testelement.itemsize
            except AttributeError:
                bitdepth = 8
        else:
            if dtype.kind == 'b':
                bitdepth = 1
            else:
                bitdepth = 8 * dtype.itemsize
        info['bitdepth'] = bitdepth
    for thing in ['width', 'height', 'bitdepth', 'greyscale', 'alpha']:
        assert thing in info
    return Image(a, info)

def export_curves_stats(self, aids, key):
    oq = self.dstore['oqparam']
    stats = oq.hazard_stats().items()
    stat2idx = {stat[0]: s for (s, stat) in enumerate(stats)}
    if 'loss_curves-stats' in self.dstore:
        dset = self.dstore['loss_curves-stats']
        data = dset[aids]
        if key == 'stats':
            return {stat[0]: data[:, s] for (s, stat) in enumerate(stats)}
        else:
            return {key: data[:, stat2idx[key]]}
    elif 'curves-stats' in self.dstore:
        dset = self.dstore['curves-stats']
        data = dset[aids]
        if key == 'stats':
            return {stat[0]: data[:, s] for (s, stat) in enumerate(stats)}
        else:
            return {key: data[:, stat2idx[key]]}
    else:
        raise KeyError('no loss curves in %s' % self.dstore)

def read_df_or_series_from_csv(desired_type: Type[pd.DataFrame], file_path: str, encoding: str, logger: Logger, **kwargs) -> pd.DataFrame:
    if desired_type is pd.Series:
        if 'index_col' not in kwargs.keys():
            one_col_df = pd.read_csv(file_path, encoding=encoding, index_col=0, **kwargs)
        else:
            one_col_df = pd.read_csv(file_path, encoding=encoding, **kwargs)
        if one_col_df.shape[1] == 1:
            return one_col_df[one_col_df.columns[0]]
        else:
            raise Exception('Cannot build a series from this csv: it has more than two columns (one index + one value). Probably the parsing chain $read_df_or_series_from_csv => single_row_or_col_df_to_series$will work, though.')
    else:
        return pd.read_csv(file_path, encoding=encoding, **kwargs)

