def is_executable_file(path):
    fpath = os.path.realpath(path)
    if not os.path.isfile(fpath):
        return False
    mode = os.stat(fpath).st_mode
    if mode & stat.S_IROTH and mode & stat.S_IXOTH:
        return True
    user_gids = os.getgroups() + [os.getgid()]
    if os.stat(fpath).st_gid in user_gids and mode & stat.S_IRGRP and mode & stat.S_IXGRP:
        return True
    user_gids = os.getgroups() + [os.getgid()]
    if os.stat(fpath).st_uid == os.geteuid() and mode & stat.S_IRUSR and mode & stat.S_IXUSR:
        return True
    return False

