def decodeUcs2(byteIter, numBytes):
    userData = []
    i = 0
    try:
        while i < numBytes:
            userData.append(unichr(next(byteIter) << 8 | next(byteIter)))
            i += 2
    except StopIteration:
        pass
    return ''.join(userData)

