def from_kwargs(cls, **kwargs):
    arrays = []
    names = []
    for (p, vals) in kwargs.items():
        if not isinstance(vals, numpy.ndarray):
            if not isinstance(vals, list):
                vals = [vals]
            vals = numpy.array(vals)
        arrays.append(vals)
        names.append(p)
    return cls.from_arrays(arrays, names=names)

