def handle_wsgi_error(environ, exc):
    if isinstance(exc, tuple):
        exc_info = exc
        exc = exc[1]
    else:
        exc_info = True
    request = wsgi_request(environ)
    request.cache.handle_wsgi_error = True
    old_response = request.cache.pop('response', None)
    response = request.response
    if old_response:
        response.content_type = old_response.content_type
    logger = request.logger
    if isinstance(exc, HTTPError):
        response.status_code = exc.code or 500
    else:
        response.status_code = getattr(exc, 'status', 500)
    response.headers.update(getattr(exc, 'headers', None) or ())
    status = response.status_code
    if status >= 500:
        logger.critical('%s - @ %s.\n%s', exc, request.first_line, dump_environ(environ), exc_info=exc_info)
    else:
        log_wsgi_info(logger.warning, environ, response.status, exc)
    if has_empty_content(status, request.method) or status in REDIRECT_CODES:
        response.content_type = None
        response.content = None
    else:
        request.cache.pop('html_document', None)
        renderer = environ.get('error.handler') or render_error
        try:
            content = renderer(request, exc)
        except Exception:
            logger.critical('Error while rendering error', exc_info=True)
            response.content_type = 'text/plain'
            content = 'Critical server error'
        if content is not response:
            response.content = content
    return response

def guess_worker_impl(link):
    worker_impls = []
    task = link.task
    name = link.name
    errors = []
    if task['payload'].get('image'):
        worker_impls.append('docker-worker')
    if task['provisionerId'] in link.context.config['scriptworker_provisioners']:
        worker_impls.append('scriptworker')
    if task['workerType'] in link.context.config['scriptworker_worker_types']:
        worker_impls.append('scriptworker')
    if task['payload'].get('mounts') is not None:
        worker_impls.append('generic-worker')
    if task['payload'].get('osGroups') is not None:
        worker_impls.append('generic-worker')
    if task.get('tags', {}).get('worker-implementation', {}):
        worker_impls.append(task['tags']['worker-implementation'])
    for scope in task['scopes']:
        if scope.startswith('docker-worker:'):
            worker_impls.append('docker-worker')
    if not worker_impls:
        errors.append("guess_worker_impl: can't find a worker_impl for {}!\n{}".format(name, task))
    if len(set(worker_impls)) > 1:
        errors.append('guess_worker_impl: too many matches for {}: {}!\n{}'.format(name, set(worker_impls), task))
    raise_on_errors(errors)
    log.debug('{} {} is {}'.format(name, link.task_id, worker_impls[0]))
    return worker_impls[0]

