def __add_loaded_module(self, event):
    lpBaseOfDll = event.get_module_base()
    hFile = event.get_file_handle()
    if lpBaseOfDll not in self.__moduleDict:
        fileName = event.get_filename()
        if not fileName:
            fileName = None
        if hasattr(event, 'get_start_address'):
            EntryPoint = event.get_start_address()
        else:
            EntryPoint = None
        aModule = Module(lpBaseOfDll, hFile, fileName=fileName, EntryPoint=EntryPoint, process=self)
        self._add_module(aModule)
    else:
        aModule = self.get_module(lpBaseOfDll)
        if not aModule.hFile and hFile not in (None, 0, win32.INVALID_HANDLE_VALUE):
            aModule.hFile = hFile
        if not aModule.process:
            aModule.process = self
        if aModule.EntryPoint is None and hasattr(event, 'get_start_address'):
            aModule.EntryPoint = event.get_start_address()
        if not aModule.fileName:
            fileName = event.get_filename()
            if fileName:
                aModule.fileName = fileName

def _do_join_packet(self, packet, ip, port):
    self.debug('()')
    device_id = packet.header.device_id
    key = u'{}:{}'.format(ip, port)
    if device_id == Id.REQUEST:
        device_id = self._new_device_id(key)
    client = self._clients.get(device_id, {})
    data = {}
    if packet.payload:
        try:
            data = packet.payload
        except:
            data = {}
    client['device_id'] = device_id
    client['key'] = key
    people = []
    try:
        for (index, person_dict) in enumerate(data['people']):
            person = Person()
            person.from_dict(person_dict)
            person.id = u'{}.{}'.format(device_id, person.id)
            people.append(person)
        self.changer.on_person_new(people)
    except:
        self.exception('Failed to update people')
        return
    client['people'] = people
    client_dict = dict(client)
    del client_dict['people']
    self._send_packet(ip, port, APPConfigMessage(payload=client_dict))
    self._clients[device_id] = client
    self._key2deviceId[key] = device_id

def ExpandGlobs(path, opts=None):
    precondition.AssertType(path, Text)
    if not path:
        raise ValueError('Path is empty')
    if not _IsAbsolutePath(path, opts):
        raise ValueError("Path '%s' is not absolute" % path)
    if opts is not None and opts.pathtype == rdf_paths.PathSpec.PathType.REGISTRY:
        (root_dir, tail) = path.replace('\\', '/').lstrip('/').split('/', 1)
        components = list(ParsePath(tail, opts=opts))
    else:
        (drive, tail) = os.path.splitdrive(path)
        root_dir = os.path.join(drive, os.path.sep).upper()
        components = list(ParsePath(tail[1:], opts=opts))
    return _ExpandComponents(root_dir, components)

