def join_header_words(lists):
    headers = []
    for pairs in lists:
        attr = []
        for (k, v) in pairs:
            if v is not None:
                if not re.search('^\\w+$', v):
                    v = HEADER_JOIN_ESCAPE_RE.sub('\\\\\\1', v)
                    v = '"%s"' % v
                k = '%s=%s' % (k, v)
            attr.append(k)
        if attr:
