    return len(self.picard_rrbs_metrics)

def next(self):
    options = {}
    if self._buffer_size:
        options['read_buffer_size'] = self._buffer_size
    if self._account_id:
        options['_account_id'] = self._account_id
    while True:
        filename = self._next_file()
        if filename is None:
            raise StopIteration()
        if self._path_filter and (not self._path_filter.accept(self._slice_ctx, filename)):
            continue
        try:
            start_time = time.time()
            handle = cloudstorage.open(filename, **options)
            self._slice_ctx.incr(self.COUNTER_IO_READ_MSEC, int(time.time() - start_time) * 1000)
            self._slice_ctx.incr(self.COUNTER_FILE_READ)
            return handle
        except cloudstorage.NotFoundError:
            logging.warning('File %s may have been removed. Skipping file.', filename)
            self._slice_ctx.incr(self.COUNTER_FILE_MISSING)

def _load_dataset_clipping(self, dataset_dir, epsilon):
    self.dataset_max_clip = {}
    self.dataset_min_clip = {}
    self._dataset_image_count = 0
    for fname in os.listdir(dataset_dir):
        if not fname.endswith('.png'):
            continue
        image_id = fname[:-4]
        image = np.array(Image.open(os.path.join(dataset_dir, fname)).convert('RGB'))
        image = image.astype('int32')
        self._dataset_image_count += 1
        self.dataset_max_clip[image_id] = np.clip(image + epsilon, 0, 255).astype('uint8')
        self.dataset_min_clip[image_id] = np.clip(image - epsilon, 0, 255).astype('uint8')

