            val = self.__min
        if self.__max is not None and val > self.__max:
            self.is_valid = False
            val = self.__max
    except:
        self.is_valid = False
    self.__bound_val = self.__val = val
    (fgcol, bgcol) = (self.fgcol_valid, self.bgcol_valid)
