def circuit_to_latex(circ: Circuit, qubits: Qubits=None, document: bool=True) -> str:
    if qubits is None:
        qubits = circ.qubits
    N = len(qubits)
    qubit_idx = dict(zip(qubits, range(N)))
    layers = _display_layers(circ, qubits)
    layer_code = []
    code = ['\\lstick{' + str(q) + '}' for q in qubits]
    layer_code.append(code)

    def _two_qubit_gate(top, bot, label):
        if bot - top == 1:
            code_top = '\\multigate{1}{%s}' % label
            code_bot = '\\ghost{%s}' % label
        else:
            code_top = '\\sgate{%s}{%s}' % (label, str(bot - top))
            code_bot = '\\gate{%s}' % label
        return (code_top, code_bot)
    for layer in layers.elements:
        code = ['\\qw'] * N
        assert isinstance(layer, Circuit)
        for gate in layer:
            idx = [qubit_idx[q] for q in gate.qubits]
            name = gate.name
            if isinstance(gate, I):
                pass
            elif len(idx) == 1 and name in ['X', 'Y', 'Z', 'H', 'T', 'S']:
                code[idx[0]] = '\\gate{' + gate.name + '}'
            elif isinstance(gate, S_H):
                code[idx[0]] = '\\gate{S^\\dag}'
            elif isinstance(gate, T_H):
                code[idx[0]] = '\\gate{T^\\dag}'
            elif isinstance(gate, RX):
                theta = _latex_format(gate.params['theta'])
                code[idx[0]] = '\\gate{R_x(%s)}' % theta
            elif isinstance(gate, RY):
                theta = _latex_format(gate.params['theta'])
                code[idx[0]] = '\\gate{R_y(%s)}' % theta
            elif isinstance(gate, RZ):
                theta = _latex_format(gate.params['theta'])
                code[idx[0]] = '\\gate{R_z(%s)}' % theta
            elif isinstance(gate, TX):
                t = _latex_format(gate.params['t'])
                code[idx[0]] = '\\gate{X^{%s}}' % t
            elif isinstance(gate, TY):
                t = _latex_format(gate.params['t'])
                code[idx[0]] = '\\gate{Y^{%s}}' % t
            elif isinstance(gate, TZ):
                t = _latex_format(gate.params['t'])
                code[idx[0]] = '\\gate{Z^{%s}}' % t
            elif isinstance(gate, TH):
                t = _latex_format(gate.params['t'])
                code[idx[0]] = '\\gate{H^{%s}}' % t
            elif isinstance(gate, CNOT):
                code[idx[0]] = '\\ctrl{' + str(idx[1] - idx[0]) + '}'
                code[idx[1]] = '\\targ'
            elif isinstance(gate, XX):
                label = 'X\\!X^{%s}' % _latex_format(gate.params['t'])
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, YY):
                label = 'Y\\!Y^{%s}' % _latex_format(gate.params['t'])
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, ZZ):
                label = 'Z\\!Z^{%s}' % _latex_format(gate.params['t'])
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, CPHASE):
                theta = _latex_format(gate.params['theta'])
                label = '\\text{CPHASE}({%s})' % theta
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, PSWAP):
                theta = _latex_format(gate.params['theta'])
                label = '\\text{PSWAP}({%s})' % theta
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, CZ):
                code[idx[0]] = '\\ctrl{' + str(idx[1] - idx[0]) + '}'
                code[idx[1]] = '\\ctrl{' + str(idx[0] - idx[1]) + '}'
            elif isinstance(gate, SWAP):
                code[idx[0]] = '\\qswap \\qwx[' + str(idx[1] - idx[0]) + ']'
                code[idx[1]] = '\\qswap'
            elif isinstance(gate, CAN):
                tx = _latex_format(gate.params['tx'])
                ty = _latex_format(gate.params['ty'])
                tz = _latex_format(gate.params['tz'])
                label = '{\\text{CAN}(%s, %s, %s)}' % (tx, ty, tz)
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, ISWAP):
                label = '{ \\text{iSWAP}}'
                top = min(idx)
                bot = max(idx)
                (code[top], code[bot]) = _two_qubit_gate(top, bot, label)
            elif isinstance(gate, CCNOT):
                code[idx[0]] = '\\ctrl{' + str(idx[1] - idx[0]) + '}'
                code[idx[1]] = '\\ctrl{' + str(idx[2] - idx[1]) + '}'
                code[idx[2]] = '\\targ'
            elif isinstance(gate, CSWAP):
                code[idx[0]] = '\\ctrl{' + str(idx[1] - idx[0]) + '}'
                code[idx[1]] = '\\qswap \\qwx[' + str(idx[2] - idx[1]) + ']'
                code[idx[2]] = '\\qswap'
            elif isinstance(gate, P0):
                code[idx[0]] = '\\push{\\ket{0}\\!\\!\\bra{0}} \\qw'
            elif isinstance(gate, P1):
                code[idx[0]] = '\\push{\\ket{1}\\!\\!\\bra{1}} \\qw'
            elif isinstance(gate, Reset):
                for i in idx:
                    code[i] = '\\push{\\rule{0.1em}{0.5em}\\, \\ket{0}\\,} \\qw'
            elif isinstance(gate, Measure):
                code[idx[0]] = '\\meter'
            else:
                raise NotImplementedError(str(gate))
        layer_code.append(code)
    code = ['\\qw'] * N
    layer_code.append(code)
    latex_lines = [''] * N
    for (line, wire) in enumerate(zip(*layer_code)):
        latex = '& ' + ' & '.join(wire)
        if line < N - 1:
            latex += ' \\\\'
        latex_lines[line] = latex
    latex_code = _QCIRCUIT % '\n'.join(latex_lines)
    if document:
        latex_code = _DOCUMENT_HEADER + latex_code + _DOCUMENT_FOOTER
    return latex_code

def _parse(self, source, accept_encoded_idn, only_icann=False):
    publicsuffix = set()
    maxlabel = 0
    section_is_icann = None
    if isinstance(source, decodablestr):
        source = source.splitlines()
    ln = 0
    for line in source:
        ln += 1
        if only_icann:
            ul = u(line).rstrip()
            if ul == '// ===BEGIN ICANN DOMAINS===':
                section_is_icann = True
                continue
            elif ul == '// ===END ICANN DOMAINS===':
                section_is_icann = False
                continue
            if not section_is_icann:
                continue
        s = u(line).lower().split(' ')[0].rstrip()
        if s == '' or s.startswith('//'):
            continue
        maxlabel = max(maxlabel, s.count('.') + 1)
        publicsuffix.add(s)
        if accept_encoded_idn:
            e = encode_idn(s.lstrip('!'))
            if s[0] == '!':
                publicsuffix.add('!' + e)
            else:
                publicsuffix.add(e)
    self._publicsuffix = frozenset(publicsuffix)
    self._maxlabel = maxlabel

