def _initialize_splittable_and_unsplittable_dims(self, default_splittability, exception_dims_iterable=None):
    default_dims = set()
    exception_dims = set()
    if exception_dims_iterable:
        exception_dims.update(exception_dims_iterable)
    for t in itertools.chain(self.inputs, self.outputs):
        for dim_name in t.shape.dimension_names:
            if dim_name not in exception_dims:
                default_dims.add(dim_name)
    if default_splittability == 'splittable':
        return (frozenset(default_dims), frozenset(exception_dims))
    elif default_splittability == 'unsplittable':
        return (frozenset(exception_dims), frozenset(default_dims))
    else:
        raise ValueError('default_splittability should be either "splittable" or "unsplittable" but was {}'.format(default_splittability))

def make_attribute(key, value, doc_string=None):
    attr = AttributeProto()
    attr.name = key
    if doc_string:
        attr.doc_string = doc_string
    is_iterable = isinstance(value, collections.Iterable)
    bytes_or_false = _to_bytes_or_false(value)
    if isinstance(value, float):
        attr.f = value
        attr.type = AttributeProto.FLOAT
    elif isinstance(value, numbers.Integral):
        attr.i = cast(int, value)
        attr.type = AttributeProto.INT
    elif bytes_or_false:
        assert isinstance(bytes_or_false, bytes)
        attr.s = bytes_or_false
        attr.type = AttributeProto.STRING
    elif isinstance(value, TensorProto):
        attr.t.CopyFrom(value)
        attr.type = AttributeProto.TENSOR
    elif isinstance(value, GraphProto):
        attr.g.CopyFrom(value)
        attr.type = AttributeProto.GRAPH
    elif is_iterable:
        byte_array = [_to_bytes_or_false(v) for v in value]
        if all((isinstance(v, float) for v in value)):
            attr.floats.extend(value)
            attr.type = AttributeProto.FLOATS
        elif all((isinstance(v, numbers.Integral) for v in value)):
            attr.ints.extend((int(v) for v in value))
            attr.type = AttributeProto.INTS
        elif all(byte_array):
            attr.strings.extend(cast(List[bytes], byte_array))
            attr.type = AttributeProto.STRINGS
        elif all((isinstance(v, TensorProto) for v in value)):
            attr.tensors.extend(value)
            attr.type = AttributeProto.TENSORS
        elif all((isinstance(v, GraphProto) for v in value)):
            attr.graphs.extend(value)
            attr.type = AttributeProto.GRAPHS
        else:
            raise ValueError('You passed in an iterable attribute but I cannot figure out its applicable type.')
    else:
        raise ValueError('Value "{}" is not valid attribute data type.'.format(value))
    return attr

