def ensure_virtualenv(three=None, python=None, site_packages=False, pypi_mirror=None):
    from .environments import PIPENV_USE_SYSTEM

    def abort():
        sys.exit(1)
    global USING_DEFAULT_PYTHON
    if not project.virtualenv_exists:
        try:
            ensure_environment()
            python = ensure_python(three=three, python=python)
            if python is not None and (not isinstance(python, six.string_types)):
                python = python.path.as_posix()
            if PIPENV_USE_SYSTEM:
                click.echo(crayons.red('You are attempting to re–create a virtualenv that Pipenv did not create. Aborting.'))
                sys.exit(1)
            do_create_virtualenv(python=python, site_packages=site_packages, pypi_mirror=pypi_mirror)
        except KeyboardInterrupt:
            cleanup_virtualenv(bare=False)
            sys.exit(1)
    elif python or three is not None or site_packages is not False:
        USING_DEFAULT_PYTHON = False
        python = ensure_python(three=three, python=python)
        if python is not None and (not isinstance(python, six.string_types)):
            python = python.path.as_posix()
        click.echo(crayons.red('Virtualenv already exists!'), err=True)
        if 'VIRTUAL_ENV' in os.environ:
            if not (PIPENV_YES or click.confirm('Remove existing virtualenv?', default=True)):
                abort()
        click.echo(crayons.normal(fix_utf8('Removing existing virtualenv…'), bold=True), err=True)
        cleanup_virtualenv(bare=True)
        ensure_virtualenv(three=three, python=python, site_packages=site_packages, pypi_mirror=pypi_mirror)

