def score(self, X, design, scan_onsets=None):
    X = self._check_data_GBRSA(X, for_fit=False)
    scan_onsets = self._check_scan_onsets_GBRSA(scan_onsets, X)
    design = self._check_design_GBRSA(design, X)
    assert len(X) == self.n_subj_
    ll = [None] * self.n_subj_
    ll_null = [None] * self.n_subj_
    for subj in np.arange(self.n_subj_):
        if X[subj] is not None:
            ll[subj] = self._score(Y=X[subj], design=design[subj], beta=self.beta_[subj], scan_onsets=scan_onsets[subj], beta0=self.beta0_[subj], rho_e=self.rho_[subj], sigma_e=self.sigma_[subj], rho_X0=self._rho_X0_[subj], sigma2_X0=self._sigma2_X0_[subj])
            ll_null[subj] = self._score(Y=X[subj], design=None, beta=None, scan_onsets=scan_onsets[subj], beta0=self.beta0_[subj], rho_e=self.rho_[subj], sigma_e=self.sigma_[subj], rho_X0=self._rho_X0_[subj], sigma2_X0=self._sigma2_X0_[subj])
    return (ll, ll_null)

