        raise ValueError('A frequency of {} was found which is greater than the maximum allowable value of max_freq = {} (did you supply frequency values in Hz?)'.format(frequencies.max(), max_freq))
    if (np.abs(frequencies) < min_freq).any():
        raise ValueError('A frequency of {} was found which is less than the minimum allowable value of min_freq = {} (did you supply frequency values in Hz?)'.format(frequencies.min(), min_freq))
