def zhang_huang_solar(alt, cloud_cover, relative_humidity, dry_bulb_present, dry_bulb_t3_hrs, wind_speed, irr_0=1355):
    (C0, C1, C2, C3, C4, C5, D_COEFF, K_COEFF) = (0.5598, 0.4982, -0.6762, 0.02842, -0.00317, 0.014, -17.853, 0.843)
    glob_ir = 0
    if alt > 0:
        sin_alt = math.sin(math.radians(alt))
        (cc, rh, n_temp, n3_temp, w_spd) = (cloud_cover / 10.0, relative_humidity, dry_bulb_present, dry_bulb_t3_hrs, wind_speed)
        glob_ir = (irr_0 * sin_alt * (C0 + C1 * cc + C2 * cc ** 2 + C3 * (n_temp - n3_temp) + C4 * rh + C5 * w_spd) + D_COEFF) / K_COEFF
        if glob_ir < 0:
            glob_ir = 0
    return glob_ir

def attempt_advance(self, blocksize, timeout=10):
