        return DataBuffer.advance(self, blocksize)
    except RuntimeError:
        if lal.GPSTimeNow() > timeout + self.raw_buffer.end_time:
            DataBuffer.null_advance(self, blocksize)
            return None
        else:
            time.sleep(1)
            return self.attempt_advance(blocksize, timeout=timeout)

