def rejection_sample(n_samples, pool_size, rng_state):
    result = np.empty(n_samples, dtype=np.int64)
    for i in range(n_samples):
        reject_sample = True
        while reject_sample:
            j = tau_rand_int(rng_state) % pool_size
            for k in range(i):
                if j == result[k]:
                    break
            else:
                reject_sample = False
        result[i] = j
    return result

def _parse_seq_body(line):
    line = line.rstrip('*')
    if '{()' in line:
        (head, _rest) = line.split('{()', 1)
    else:
        _rest = line.split('{(', 1)[1]
        (head, _rest) = _rest.split(')', 1)
    if '()}' in _rest:
        (molseq, tail) = _rest.split('()}', 1)
    else:
        (molseq, _rest) = _rest.split('(', 1)
        tail = _rest.split(')}', 1)[0]
    return (head, molseq, tail)

def describe_underlying_workflow(self, region, describe_output=None):
    assert describe_output is None or describe_output.get('class', '') == 'globalworkflow'
    if region is None:
        raise DXError('DXGlobalWorkflow: region must be provided to get an underlying workflow')
    if region in self._workflow_desc_by_region:
        return self._workflow_desc_by_region[region]
    if not describe_output:
        describe_output = self.describe()
    if region not in describe_output['regionalOptions'].keys():
        raise DXError('DXGlobalWorkflow: the global workflow {} is not enabled in region {}'.format(self.get_id(), region))
    underlying_workflow_id = describe_output['regionalOptions'][region]['workflow']
    dxworkflow = dxpy.DXWorkflow(underlying_workflow_id)
    dxworkflow_desc = dxworkflow.describe()
    self._workflow_desc_by_region = dxworkflow_desc
    return dxworkflow_desc

def currentFolder(self, value):
    if value is not None and value.lower() == self._currentFolder['title']:
        return
    if value is None:
        self._location = self.root
        self._currentFolder = {'title': 'root', 'id': None, 'created': None, 'username': None}
        self.__init()
    elif value == '/' or value.lower() == 'root':
        self.location = self.root
        self._currentFolder = {'title': 'root', 'id': None, 'created': None, 'username': None}
        self.__init()
    else:
        for folder in self.folders:
            if 'title' in folder:
                if folder['title'].lower() == value.lower():
                    self._location = '%s/%s' % (self.root, folder['id'])
                    self._currentFolder = folder
                    self.__init(folder['title'])
                    break

