def get_connected_components(graph):
    list_of_components = []
    component = []
    unreached = set(graph.get_all_node_ids())
    to_explore = deque()
    while len(unreached) > 0:
        if len(to_explore) == 0:
            n = unreached.pop()
            unreached.add(n)
            to_explore.append(n)
            component = []
            list_of_components.append(component)
        while len(to_explore) > 0:
            n = to_explore.pop()
            if n in unreached:
                component.append(n)
                unreached.remove(n)
                nodes = graph.neighbors(n)
                for n in nodes:
                    if n in unreached:
                        to_explore.append(n)
    return list_of_components

