def run(cmd, stdout=None, stderr=None, **kwargs):
    devnull = None
    try:
        stdoutfilter = None
        stderrfilter = None
        wantstdout = False
        wantstderr = False
        if stdout is False:
            devnull = open('/dev/null', 'w')
            stdout = devnull
        elif stdout is True:
            stdout = subprocess.PIPE
            wantstdout = True
        elif callable(stdout):
            stdoutfilter = partial(stdout)
            stdout = subprocess.PIPE
        else:
            assert stdout is None, 'Invalid stdout %r' % stdout
        if stderr is False:
            if devnull is None:
                devnull = open('/dev/null', 'w')
            stderr = devnull
        elif stderr is True:
            stderr = subprocess.PIPE
            wantstderr = True
        elif stderr == 'STDOUT':
            stderr = subprocess.STDOUT
        elif callable(stderr):
            stderrfilter = partial(stderr)
            stderr = subprocess.PIPE
        else:
            assert stderr is None, 'Invalid stderr %r' % stderr
        if (stdoutfilter or stderrfilter) and asyncio:
            (exitcode, out, err) = _runasync(stdoutfilter, stderrfilter, cmd, stdout=stdout, stderr=stderr, **kwargs)
            if not wantstdout:
                out = None
            if not wantstderr:
                err = None
            return (exitcode, out, err)
        proc = subprocess.Popen(cmd, stdout=stdout, stderr=stderr, **kwargs)
        (out, err) = proc.communicate()
        if not wantstdout:
            if stdoutfilter:
                stdoutfilter(out, True)
            out = None
        if not wantstderr:
            if stderrfilter:
                stderrfilter(err, True)
            err = None
        return (proc.returncode, out, err)
    finally:
        if devnull is not None:
            devnull.close()

