def _objectify(self, node, binding, depth, path):
    if binding.is_object:
        obj = {'$schema': binding.path}
        for (s, p, o) in self.graph.triples((node, None, None)):
            prop = binding.get_property(p)
            if prop is None or depth <= 1 or o in path:
                continue
            if depth <= 2 and (prop.is_array or prop.is_object):
                continue
            sub_path = path.union([node])
            value = self._objectify(o, prop, depth - 1, sub_path)
            if prop.is_array and prop.name in obj:
                obj[prop.name].extend(value)
            else:
                obj[prop.name] = value
        return obj
    elif binding.is_array:
        for item in binding.items:
            return [self._objectify(node, item, depth, path)]
    else:
        return node.toPython()

def pnl_lifo(self):
    X = dict(zip(self.target.code, [LifoQueue() for i in range(len(self.target.code))]))
    pair_table = []
    for (_, data) in self.target.history_table_min.iterrows():
        while True:
            if X[data.code].qsize() == 0:
                X[data.code].put((data.datetime, data.amount, data.price))
                break
            else:
                l = X[data.code].get()
                if l[1] * data.amount < 0:
                    if abs(l[1]) > abs(data.amount):
                        temp = (l[0], l[1] + data.amount, l[2])
                        X[data.code].put_nowait(temp)
                        if data.amount < 0:
                            pair_table.append([data.code, data.datetime, l[0], abs(data.amount), data.price, l[2]])
                            break
                        else:
                            pair_table.append([data.code, l[0], data.datetime, abs(data.amount), l[2], data.price])
                            break
                    elif abs(l[1]) < abs(data.amount):
                        data.amount = data.amount + l[1]
                        if data.amount < 0:
                            pair_table.append([data.code, data.datetime, l[0], l[1], data.price, l[2]])
                        else:
                            pair_table.append([data.code, l[0], data.datetime, l[1], l[2], data.price])
                    elif data.amount < 0:
                        pair_table.append([data.code, data.datetime, l[0], abs(data.amount), data.price, l[2]])
                        break
                    else:
                        pair_table.append([data.code, l[0], data.datetime, abs(data.amount), l[2], data.price])
                        break
                else:
                    X[data.code].put_nowait(l)
                    X[data.code].put_nowait((data.datetime, data.amount, data.price))
                    break
    pair_title = ['code', 'sell_date', 'buy_date', 'amount', 'sell_price', 'buy_price']
    pnl = pd.DataFrame(pair_table, columns=pair_title).set_index('code')
    pnl = pnl.assign(unit=pnl.code.apply(lambda x: self.market_preset.get_unit(x)), pnl_ratio=pnl.sell_price / pnl.buy_price - 1, sell_date=pd.to_datetime(pnl.sell_date), buy_date=pd.to_datetime(pnl.buy_date))
    pnl = pnl.assign(pnl_money=(pnl.sell_price - pnl.buy_price) * pnl.amount * pnl.unit, hold_gap=abs(pnl.sell_date - pnl.buy_date), if_buyopen=pnl.sell_date - pnl.buy_date > datetime.timedelta(days=0))
    pnl = pnl.assign(openprice=pnl.if_buyopen.apply(lambda pnl: 1 if pnl else 0) * pnl.buy_price + pnl.if_buyopen.apply(lambda pnl: 0 if pnl else 1) * pnl.sell_price, opendate=pnl.if_buyopen.apply(lambda pnl: 1 if pnl else 0) * pnl.buy_date.map(str) + pnl.if_buyopen.apply(lambda pnl: 0 if pnl else 1) * pnl.sell_date.map(str), closeprice=pnl.if_buyopen.apply(lambda pnl: 0 if pnl else 1) * pnl.buy_price + pnl.if_buyopen.apply(lambda pnl: 1 if pnl else 0) * pnl.sell_price, closedate=pnl.if_buyopen.apply(lambda pnl: 0 if pnl else 1) * pnl.buy_date.map(str) + pnl.if_buyopen.apply(lambda pnl: 1 if pnl else 0) * pnl.sell_date.map(str))
    return pnl.set_index('code')

def _pki_minions(self):
    minions = []
    pki_cache_fn = os.path.join(self.opts['pki_dir'], self.acc, '.key_cache')
    try:
        os.makedirs(os.path.dirname(pki_cache_fn))
    except OSError:
        pass
    try:
        if self.opts['key_cache'] and os.path.exists(pki_cache_fn):
            log.debug('Returning cached minion list')
            if six.PY2:
                with salt.utils.files.fopen(pki_cache_fn) as fn_:
                    return self.serial.load(fn_)
            else:
                with salt.utils.files.fopen(pki_cache_fn, mode='rb') as fn_:
                    return self.serial.load(fn_)
        else:
            for fn_ in salt.utils.data.sorted_ignorecase(os.listdir(os.path.join(self.opts['pki_dir'], self.acc))):
                if not fn_.startswith('.') and os.path.isfile(os.path.join(self.opts['pki_dir'], self.acc, fn_)):
                    minions.append(fn_)
        return minions
    except OSError as exc:
        log.error('Encountered OSError while evaluating minions in PKI dir: %s', exc)
        return minions

def set_mules_params(self, mules=None, touch_reload=None, harakiri_timeout=None, farms=None, reload_mercy=None, msg_buffer=None, msg_buffer_recv=None):
    farms = farms or []
    next_mule_number = 1
    farm_mules_count = 0
    for farm in farms:
        if isinstance(farm.mule_numbers, int):
            farm.mule_numbers = list(range(next_mule_number, next_mule_number + farm.mule_numbers))
            next_mule_number = farm.mule_numbers[-1] + 1
        farm_mules_count += len(farm.mule_numbers)
        self._set('farm', farm, multi=True)
    if mules is None and farm_mules_count:
        mules = farm_mules_count
    if isinstance(mules, int):
        self._set('mules', mules)
    elif isinstance(mules, list):
        for mule in mules:
            self._set('mule', mule, multi=True)
    self._set('touch-mules-reload', touch_reload, multi=True)
    self._set('mule-harakiri', harakiri_timeout)
    self._set('mule-reload-mercy', reload_mercy)
    self._set('mule-msg-size', msg_buffer)
    self._set('mule-msg-recv-size', msg_buffer_recv)
    return self._section

