    pages = self.pages
    if pages[0].compression == 1:
        return
    pages = sorted(pages, key=lambda p: p._offsetscounts[0][0])
    npages = len(pages) - 1
    for (i, page) in enumerate(pages):
        if page.index % 2:
            continue
        (offsets, bytecounts) = page._offsetscounts
        if i < npages:
            lastoffset = pages[i + 1]._offsetscounts[0][0]
        else:
            lastoffset = min(offsets[-1] + 2 * bytecounts[-1], self._fh.size)
        for j in range(len(bytecounts) - 1):
            bytecounts[j] = offsets[j + 1] - offsets[j]
        bytecounts[-1] = lastoffset - offsets[-1]

def write(self, fh, deparsed=None):
    if type(fh) is str:
        fh = codecs.open(fh, 'w', 'utf-8')
    if deparsed is None:
        deparsed = self.deparse()
    fh.write('// Written by rivescript.deparse()\n')
    fh.write('! version = 2.0\n\n')
    for kind in ['global', 'var', 'sub', 'person', 'array']:
        if len(deparsed['begin'][kind].keys()) == 0:
            continue
        for var in sorted(deparsed['begin'][kind].keys()):
            data = deparsed['begin'][kind][var]
            if type(data) not in [str, text_type]:
                needs_pipes = False
                for test in data:
                    if ' ' in test:
                        needs_pipes = True
                        break
                if needs_pipes:
                    data = self._write_wrapped('|'.join(data), sep='|')
                else:
                    data = ' '.join(data)
            fh.write('! {kind} {var} = {data}\n'.format(kind=kind, var=var, data=data))
        fh.write('\n')
    if len(deparsed['begin']['triggers']):
        fh.write('> begin\n\n')
        self._write_triggers(fh, deparsed['begin']['triggers'], indent='\t')
        fh.write('< begin\n\n')
    topics = ['random']
    topics.extend(sorted(deparsed['topics'].keys()))
    done_random = False
    for topic in topics:
        if topic not in deparsed['topics']:
            continue
        if topic == 'random' and done_random:
            continue
        if topic == 'random':
            done_random = True
        tagged = False
        data = deparsed['topics'][topic]
        if topic != 'random' or len(data['includes']) or len(data['inherits']):
            tagged = True
            fh.write('> topic ' + topic)
            if data['inherits']:
                fh.write(' inherits ' + ' '.join(sorted(data['inherits'].keys())))
            if data['includes']:
                fh.write(' includes ' + ' '.join(sorted(data['includes'].keys())))
            fh.write('\n\n')
        indent = '\t' if tagged else ''
        self._write_triggers(fh, data['triggers'], indent=indent)
        if tagged:
            fh.write('< topic\n\n')
    return True

