def vrf_max_paths(self, **kwargs):
    afi = kwargs.pop('afi', 'ipv4')
    vrf = kwargs.pop('vrf', 'default')
    get_config = kwargs.pop('get', False)
    callback = kwargs.pop('callback', self._callback)
    if afi not in ['ipv4', 'ipv6']:
        raise AttributeError('Invalid AFI.')
    if 'ipv4' in afi:
        if not get_config:
            args = dict(af_vrf_name=vrf, rbridge_id=kwargs.pop('rbridge_id', '1'), load_sharing_value=kwargs.pop('paths', '8'))
        else:
            args = dict(af_vrf_name=vrf, rbridge_id=kwargs.pop('rbridge_id', '1'), load_sharing_value='')
        max_paths = getattr(self._rbridge, 'rbridge_id_router_router_bgp_address_family_ipv4_ipv4_unicast_af_vrf_maximum_paths_load_sharing_value')
    elif 'ipv6' in afi:
        if not get_config:
            args = dict(af_ipv6_vrf_name=vrf, rbridge_id=kwargs.pop('rbridge_id', '1'), load_sharing_value=kwargs.pop('paths', '8'))
        else:
            args = dict(af_ipv6_vrf_name=vrf, rbridge_id=kwargs.pop('rbridge_id', '1'), load_sharing_value='')
        max_paths = getattr(self._rbridge, 'rbridge_id_router_router_bgp_address_family_ipv6_ipv6_unicast_af_ipv6_vrf_maximum_paths_load_sharing_value')
    config = max_paths(**args)
    if get_config:
        output = callback(config, handler='get_config')
        if output.data.find('.//{*}load-sharing-value') is not None:
            max_path = output.data.find('.//{*}load-sharing-value').text
            result = {'vrf': vrf, 'max_path': max_path}
            return result
        else:
            return None
    if kwargs.pop('delete', False):
        config.find('.//*load-sharing-value').set('operation', 'delete')
    return callback(config)

