def convert_text(text, input_format='markdown', output_format='panflute', standalone=False, extra_args=None):
    if input_format == 'panflute':
        if not isinstance(text, Doc):
            tmp_doc = convert_text('', standalone=True)
            api_version = tmp_doc.api_version
            if isinstance(text, Element):
                text = [text]
            text = Doc(*text, api_version=api_version)
        with io.StringIO() as f:
            dump(text, f)
            text = f.getvalue()
    in_fmt = 'json' if input_format == 'panflute' else input_format
    out_fmt = 'json' if output_format == 'panflute' else output_format
    if extra_args is None:
        extra_args = []
    if standalone:
        extra_args.append('--standalone')
    out = inner_convert_text(text, in_fmt, out_fmt, extra_args)
    if output_format == 'panflute':
        out = json.loads(out, object_pairs_hook=from_json)
        if standalone:
            if not isinstance(out, Doc):
                (metadata, items) = out
                out = Doc(*items, metadata=metadata)
        elif isinstance(out, Doc):
            out = out.content.list
        else:
            out = out[1]
    return out

def _calculate_solar_geometry(self, datetime):
    month = datetime.month
    day = datetime.day
    hour = datetime.hour
    minute = datetime.minute
    year = 2016 if self.is_leap_year else 2017

    def find_fraction_of_24(hour, minute):
        return round((minute + hour * 60) / 1440.0, 2)

    def days_from_010119(year, month, day):
        years = range(1900, year)

        def is_leap_year(year):
            return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        days_in_year = []
        for item in years:
            if is_leap_year(item):
                days_in_year.append(366)
            else:
                days_in_year.append(365)
        days_in_precending_years = 0
        for days in days_in_year:
            days_in_precending_years += days
        if is_leap_year(year):
            month_dict = {1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
        else:
            month_dict = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
        'Making the total of all the days in preceding months            in the same year'
        keys = tuple(month_dict.keys())
        days_in_precending_months = 0
        for i in range(month - 1):
            days_in_precending_months += month_dict[keys[i]]
        return days_in_precending_years + days_in_precending_months + day + 1
    julian_day = days_from_010119(year, month, day) + 2415018.5 + find_fraction_of_24(hour, minute) - float(self.time_zone) / 24
    julian_century = (julian_day - 2451545) / 36525
    geom_mean_long_sun = (280.46646 + julian_century * (36000.76983 + julian_century * 0.0003032)) % 360
    geom_mean_anom_sun = 357.52911 + julian_century * (35999.05029 - 0.0001537 * julian_century)
    eccent_orbit = 0.016708634 - julian_century * (4.2037e-05 + 1.267e-07 * julian_century)
    sun_eq_of_ctr = math.sin(math.radians(geom_mean_anom_sun)) * (1.914602 - julian_century * (0.004817 + 1.4e-05 * julian_century)) + math.sin(math.radians(2 * geom_mean_anom_sun)) * (0.019993 - 0.000101 * julian_century) + math.sin(math.radians(3 * geom_mean_anom_sun)) * 0.000289
    sun_true_long = geom_mean_long_sun + sun_eq_of_ctr
    sun_app_long = sun_true_long - 0.00569 - 0.00478 * math.sin(math.radians(125.04 - 1934.136 * julian_century))
    mean_obliq_ecliptic = 23 + (26 + (21.448 - julian_century * (46.815 + julian_century * (0.00059 - julian_century * 0.001813))) / 60) / 60
    oblique_corr = mean_obliq_ecliptic + 0.00256 * math.cos(math.radians(125.04 - 1934.136 * julian_century))
    sol_dec = math.degrees(math.asin(math.sin(math.radians(oblique_corr)) * math.sin(math.radians(sun_app_long))))
    var_y = math.tan(math.radians(oblique_corr / 2)) * math.tan(math.radians(oblique_corr / 2))
    eq_of_time = 4 * math.degrees(var_y * math.sin(2 * math.radians(geom_mean_long_sun)) - 2 * eccent_orbit * math.sin(math.radians(geom_mean_anom_sun)) + 4 * eccent_orbit * var_y * math.sin(math.radians(geom_mean_anom_sun)) * math.cos(2 * math.radians(geom_mean_long_sun)) - 0.5 * var_y ** 2 * math.sin(4 * math.radians(geom_mean_long_sun)) - 1.25 * eccent_orbit ** 2 * math.sin(2 * math.radians(geom_mean_anom_sun)))
    return (sol_dec, eq_of_time)

