def isqrt(n):
    if n == 0:
        return (n, 1)
    if n < 0:
        raise ValueError('math domain error')
    (a, b, c) = (1, n, 1)

    def divisors():
        yield 2
        yield 3
        k = 5
        while k * k <= b:
            yield k
            k += 2
            yield k
            k += 4
    for k in divisors():
        (d, m) = divmod(b, k * k)
        while m == 0:
            a *= k
            b = d
            (d, m) = divmod(b, k * k)
        if b % k == 0:
            b //= k
            c *= k
        k += 1
    return (a, b * c)

def phi5_plaintext_cleanup(text, rm_punctuation=False, rm_periods=False):
    remove_comp = regex.compile('-\\n|«|»|\\<|\\>|\\.\\.\\.|‘|’|_|{.+?}|\\(.+?\\)|\\(|\\)|“|#|%|⚔|&|=|/|\\\\|〚|†|『|⚖|–|˘|⚕|☾|◌|◄|►|⌐|⌊|⌋|≈|∷|≈|∞|”|[0-9]')
    text = remove_comp.sub('', text)
    new_text = None
    if rm_punctuation:
        new_text = ''
        punctuation = [',', ';', ':', '"', "'", '?', '-', '!', '*', '[', ']', '{', '}']
        if rm_periods:
            punctuation += ['.']
        for char in text:
            if bytes(char, 'utf-8') == b'\xcc\x81':
                pass
            elif char in punctuation:
                pass
            else:
                new_text += char
    if new_text:
        text = new_text
    replace_comp = regex.compile('\\n')
    text = replace_comp.sub(' ', text)
    comp_space = regex.compile('\\s+')
    text = comp_space.sub(' ', text)
    return text

