                fp.write(block)
                file_size += len(block)
        logger.info('Download finished, size is %d bytes.', file_size)
    return file_size

def pp(el, preString=''):
    tab = ' ' * 4
    if isinstance(el, dict):
        keys = list(el.keys())
        keys.sort()
        for key in keys:
            val = el[key]
            if isinstance(val, dict) or isinstance(val, list):
                print('%s%s :' % (preString, key))
                pp(val, preString + tab)
            else:
                print('%s%s  =  %s' % (preString, key, val))
    elif isinstance(el, list):
        print(preString + tab + '[')
        preString += tab
        for _ in el:
            if isinstance(_, dict):
                print(preString + tab + '{')
                pp(_, preString + tab * 2)
                print(preString + tab + '}')
            elif isinstance(_, list):
                print(preString + tab + '[')
                pp(_, preString + tab)
                print(preString + tab + ']')
            else:
                pp(_, preString + tab)
        print(preString + ']')
    else:
        print(preString + str(el))

def summary(args):
    from jcvi.formats.base import SetFile
    from jcvi.formats.bed import BedSummary
    from jcvi.utils.table import tabulate
    p = OptionParser(summary.__doc__)
    p.add_option('--isoform', default=False, action='store_true', help='Find longest isoform of each id')
    p.add_option('--ids', help='Only include features from certain IDs')
    (opts, args) = p.parse_args(args)
    if len(args) != 1:
        sys.exit(not p.print_help())
    (gff_file,) = args
    ids = opts.ids
    if ids:
        ids = SetFile(ids)
        logging.debug('Total ids loaded: {0}'.format(len(ids)))
        if opts.isoform:
            pids = set()
            gff = Gff(gff_file)
            for g in gff:
                if g.type != 'mRNA':
                    continue
                if g.parent not in ids:
                    continue
                if 'longest' not in g.attributes:
                    pids = set((x + '.1' for x in ids))
                    break
                if g.attributes['longest'][0] == '0':
                    continue
                pids.add(g.id)
            ids = pids
            logging.debug('After checking longest: {0}'.format(len(ids)))
        gff = Gff(gff_file)
        for g in gff:
            if g.name in ids:
                ids.add(g.id)
        logging.debug('Total ids including aliases: {0}'.format(len(ids)))
    gff = Gff(gff_file)
    beds = defaultdict(list)
    for g in gff:
        if ids and (not (g.id in ids or g.name in ids or g.parent in ids)):
            continue
        beds[g.type].append(g.bedline)
    table = {}
    for (type, bb) in sorted(beds.items()):
        bs = BedSummary(bb)
        table[type, 'Features'] = bs.nfeats
        table[type, 'Unique bases'] = bs.unique_bases
        table[type, 'Total bases'] = bs.total_bases
    print(tabulate(table), file=sys.stdout)

