def compress_repr(self) -> Optional[str]:
    if not hasattr(self, 'value'):
        return '?'
    if not self:
        return f"{self.NDIM * '['}{self.NDIM * ']'}"
    unique = numpy.unique(self[self.mask])
    if sum(numpy.isnan(unique)) == len(unique.flatten()):
        unique = numpy.array([numpy.nan])
    else:
        unique = self.revert_timefactor(unique)
    if len(unique) == 1:
        return objecttools.repr_(unique[0])
    return None

def _scapy_read_frame(self):
    from pcapkit.toolkit.scapy import ipv4_reassembly, ipv6_reassembly, packet2chain, packet2dict, tcp_reassembly, tcp_traceflow
    packet = next(self._extmp)
    self._frnum += 1
    self._proto = packet2chain(packet)
    if self._flag_v:
        print(f' - Frame {self._frnum:>3d}: {self._proto}')
    frnum = f'Frame {self._frnum}'
    if not self._flag_q:
        info = packet2dict(packet)
        if self._flag_f:
            ofile = self._ofile(f'{self._ofnm}/{frnum}.{self._fext}')
            ofile(info, name=frnum)
        else:
            self._ofile(info, name=frnum)
    if self._flag_d:
        self._frame.append(packet)
    if self._ipv4:
        (flag, data) = ipv4_reassembly(packet, count=self._frnum)
        if flag:
            self._reasm[0](data)
    if self._ipv6:
        (flag, data) = ipv6_reassembly(packet, count=self._frnum)
        if flag:
            self._reasm[1](data)
    if self._tcp:
        (flag, data) = tcp_reassembly(packet, count=self._frnum)
        if flag:
            self._reasm[2](data)
    if self._flag_t:
        (flag, data) = tcp_traceflow(packet, count=self._frnum)
        if flag:
            self._trace(data)
    return packet

