def _parse_output(self, xml_response):
    count = 0
    xml_dict = {}
    resp_message = None
    xml_start_pos = []
    for m in re.finditer('\\<\\?xml', xml_response):
        xml_start_pos.append(m.start())
    while count < len(xml_start_pos):
        if count == len(xml_start_pos) - 1:
            result = xml_response[xml_start_pos[count]:]
        else:
            start = xml_start_pos[count]
            end = xml_start_pos[count + 1]
            result = xml_response[start:end]
        result = result.strip()
        message = etree.fromstring(result)
        resp = self._validate_message(message)
        if hasattr(resp, 'tag'):
            xml_dict = self._elementtree_to_dict(resp)
        elif resp is not None:
            resp_message = resp
        count = count + 1
    if xml_dict:
        return xml_dict
    elif resp_message is not None:
        return resp_message

def names2dnsrepr(x):
    if type(x) is str:
        if x and x[-1] == '\x00':
            return x.encode('ascii')
        x = [x.encode('ascii')]
    elif type(x) is bytes:
        if x and x[-1] == 0:
            return x
        x = [x]
    res = []
    for n in x:
        if type(n) is str:
            n = n.encode('ascii')
        termin = b'\x00'
        if n.count(b'.') == 0:
            termin += bytes([0])
        n = b''.join(map(lambda y: chr(len(y)).encode('ascii') + y, n.split(b'.'))) + termin
        res.append(n)
    return b''.join(res)

