def session(self):
    if self._session is None:
        self._session = requests.Session()
        log.debug('Connecting to {0}'.format(self.auth_url))
        if not self.ssl_verify:
            requests.packages.urllib3.disable_warnings(InsecureRequestWarning)
        if self.auth_type == 'basic':
            basic_auth = (self.auth_username, self.auth_password)
            response = self._session.get(self.auth_url, auth=basic_auth, verify=self.ssl_verify)
        else:
            gssapi_auth = HTTPSPNEGOAuth(mutual_authentication=DISABLED)
            response = self._session.get(self.auth_url, auth=gssapi_auth, verify=self.ssl_verify)
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as error:
            log.error(error)
            raise ReportError('Jira authentication failed. Try kinit.')
    return self._session

def call(cls, method, *args, **kwargs):
    api = None
    empty_key = kwargs.pop('empty_key', False)
    try:
        api = cls.get_api_connector()
        apikey = cls.get('api.key')
        if not apikey and (not empty_key):
            cls.echo("No apikey found, please use 'gandi setup' command")
            sys.exit(1)
    except MissingConfiguration:
        if api and empty_key:
            apikey = ''
        elif not kwargs.get('safe'):
            cls.echo("No configuration found, please use 'gandi setup' command")
            sys.exit(1)
        else:
            return []
    cls.debug('calling method: %s' % method)
    for arg in args:
        cls.debug('with params: %r' % arg)
    try:
        resp = api.request(method, apikey, *args, **{'dry_run': kwargs.get('dry_run', False), 'return_dry_run': kwargs.get('return_dry_run', False)})
        cls.dump('responded: %r' % resp)
        return resp
    except APICallFailed as err:
        if kwargs.get('safe'):
            return []
        if err.code == 530040:
            cls.echo("Error: It appears you haven't purchased any credits yet.\nPlease visit https://www.gandi.net/credit/buy to learn more and buy credits.")
            sys.exit(1)
        if err.code == 510150:
            cls.echo("Invalid API key, please use 'gandi setup' command.")
            sys.exit(1)
        if isinstance(err, DryRunException):
            if kwargs.get('return_dry_run', False):
                return err.dry_run
            else:
                for msg in err.dry_run:
                    cls.echo(msg['reason'])
                    cls.echo('\t' + ' '.join(msg['attr']))
                sys.exit(1)
        error = UsageError(err.errors)
        setattr(error, 'code', err.code)
        raise error

def GetApprovalForObject(object_urn, token=None, username=''):
    if token is None:
        raise access_control.UnauthorizedAccess('No token given, cannot authenticate.')
    if not username:
        username = token.username
    approvals_root_urn = aff4.ROOT_URN.Add('ACL').Add(object_urn.Path()).Add(username)
    children_urns = list(aff4.FACTORY.ListChildren(approvals_root_urn))
    if not children_urns:
        raise access_control.UnauthorizedAccess('No approval found for user %s' % utils.SmartStr(username), subject=object_urn)
    last_error = None
    approvals = aff4.FACTORY.MultiOpen(children_urns, mode='r', aff4_type=Approval, age=aff4.ALL_TIMES, token=token)
    for approval in approvals:
        try:
            test_token = access_control.ACLToken(username=username, reason=approval.Get(approval.Schema.REASON))
            approval.CheckAccess(test_token)
            return test_token
        except access_control.UnauthorizedAccess as e:
            last_error = e
    if last_error:
        raise access_control.UnauthorizedAccess(last_error, subject=object_urn)
    else:
        raise access_control.UnauthorizedAccess("Couldn't open any of %d approvals for user %s" % (len(children_urns), utils.SmartStr(username)), subject=object_urn)

