def history(zpool=None, internal=False, verbose=False):
    ret = OrderedDict()
    flags = []
    if verbose:
        flags.append('-l')
    if internal:
        flags.append('-i')
    res = __salt__['cmd.run_all'](__utils__['zfs.zpool_command'](command='history', flags=flags, target=zpool), python_shell=False)
    if res['retcode'] != 0:
        return __utils__['zfs.parse_command_result'](res)
    else:
        pool = 'unknown'
        for line in res['stdout'].splitlines():
            if line.startswith('History for'):
                pool = line[13:-2]
                ret[pool] = OrderedDict()
            else:
                if line == '':
                    continue
                log_timestamp = line[0:19]
                log_command = line[20:]
                ret[pool][log_timestamp] = log_command
    return ret

def get_merged_params(self, supplied_params=None):
    supplied_params = supplied_params or {}
    empty_params = {param: supplied_params[param] for param in supplied_params if supplied_params[param] in (None, '')}
    if empty_params:
        warnings.warn('The {path} endpoint was called with empty parameters: {empty_params}'.format(path=self.path, empty_params=empty_params), RuntimeWarning, stacklevel=5)
    unfulfilled_params = {param for param in self.required_params if param not in supplied_params and param not in self.default_params}
    if unfulfilled_params:
        raise UnfulfilledParameterException(self.path, unfulfilled_params)
    merged_params = self.default_params.copy()
    merged_params.update(supplied_params)
    return merged_params

def consume(fmt, data, names):
