def _get_headers(self, resource):
    if type(resource) == file:
        resource.seek(0)
        reader = csv.reader(resource)
    elif isinstance(resource, basestring):
        result = six.moves.urllib.parse.urlparse(resource)
        if result.scheme in ['http', 'https']:
            with closing(requests.get(resource, stream=True)) as response:
                header_row = response.iter_lines().next()
        else:
            with open(resource) as resource_file:
                reader = csv.reader(resource_file)
                header_row = reader.next()
        reader = csv.reader(cStringIO.StringIO(header_row))
    else:
        raise IOError('Resource type not supported')
    return reader.next()

async def revoke(self, user_id, *permissions):
    prefix = f'{self._prefix_perm}/{user_id}/'
    perm_names = [str(p) for p in permissions]
    checkings = [KV.delete.txn(prefix + p, b'\x00', prev_kv=True) for p in perm_names]
    (success, response) = await self._client.txn(compare=[], success=checkings)
    if not success:
        errmsg = f"无法取消用户({user_id})的权限: {{{', '.join(perm_names)}}}"
        raise Unprocessable(errmsg)
    if logger.isEnabledFor(logging.DEBUG):
        (revoked, ignored) = (set(), set())
        for (i, item) in enumerate(response):
            if item:
                revoked.add(perm_names[i])
            else:
                ignored.add(perm_names[i])
        logger.debug(f"撤销用户({user_id})权限({', '.join(revoked)}), 忽略并无此授权({', '.join(ignored)})")

