def serializable(wrapped):

    @wraps(wrapped)
    def wrapper(*args, **kwargs):
        should_serialize = kwargs.pop('serialize', False)
        result = wrapped(*args, **kwargs)
        return serialize(result) if should_serialize else result
    if hasattr(wrapped, 'decorators'):
        wrapper.decorators = wrapped.decorators
        wrapper.decorators.append('serializable')
    else:
        wrapper.decorators = ['serializable']
    return wrapper

def getargspec(method):
    argspec = _getargspec(method)
    args = argspec[0]
    if args and args[0] == 'self':
        return argspec
    if hasattr(method, '__func__'):
        method = method.__func__
    func_closure = six.get_function_closure(method)
    if not func_closure:
        return argspec
    closure = None
    func_closure = filter(lambda c: six.callable(c.cell_contents) and hasattr(c.cell_contents, '__code__'), func_closure)
    func_closure = sorted(func_closure, key=lambda c: 'self' in c.cell_contents.__code__.co_varnames, reverse=True)
    closure = func_closure[0]
    method = closure.cell_contents
    return getargspec(method)

