def get_render(self, context):
    actual_form = self.form.resolve(context)
    attrs = {}
    if self.helper is not None:
        helper = self.helper.resolve(context)
        if not isinstance(helper, FormHelper):
            raise TypeError('helper object provided to uni_form tag must be a uni_form.helpers.FormHelper object.')
        attrs = helper.get_attributes()
    else:
        helper = None
    is_formset = isinstance(actual_form, BaseFormSet)
    response_dict = self.get_response_dict(attrs, context, is_formset)
    if helper and helper.layout:
        if not is_formset:
            actual_form.form_html = helper.render_layout(actual_form, context)
        else:
            forloop = ForLoopSimulator(actual_form)
            for form in actual_form.forms:
                context.update({'forloop': forloop})
                form.form_html = helper.render_layout(form, context)
                forloop.iterate()
    if is_formset:
        response_dict.update({'formset': actual_form})
    else:
        response_dict.update({'form': actual_form})
    return Context(response_dict)

def update_template_component(component, custom_template_dir=None, hazard=None, exposure=None):
    copy_component = deepcopy(component)
    default_component_keys = []
    for component in copy_component['components']:
        default_component_keys.append(component['key'])
    if not custom_template_dir:
        custom_template_dir = join(QgsApplication.qgisSettingsDirPath(), 'inasafe')
    for component in copy_component['components']:
        if not component.get('template'):
            continue
        template_format = splitext(component['template'])[-1][1:]
        if template_format != QgisComposerComponentsMetadata.OutputFormat.QPT:
            continue
        qpt_file_name = component['template'].split('/')[-1]
        custom_qpt_path = join(custom_template_dir, qpt_file_name)
        if exists(custom_qpt_path):
            component['template'] = custom_qpt_path
    if exists(custom_template_dir) and hazard and exposure:
        for filename in listdir(custom_template_dir):
            (file_name, file_format) = splitext(filename)
            if file_format[1:] != QgisComposerComponentsMetadata.OutputFormat.QPT:
                continue
            if hazard['key'] in file_name and exposure['key'] in file_name:
                from safe.definitions.reports.components import map_report_component_boilerplate
                hazard_exposure_component = deepcopy(map_report_component_boilerplate)
                pdf_output_file = '{file_name}.pdf'.format(file_name=file_name)
                qpt_output_file = '{file_name}.qpt'.format(file_name=file_name)
                hazard_exposure_component['key'] = file_name
                hazard_exposure_component['template'] = join(custom_template_dir, filename)
                hazard_exposure_component['output_path']['template'] = qpt_output_file
                hazard_exposure_component['output_path']['map'] = pdf_output_file
                copy_component['components'].append(hazard_exposure_component)
                new_component = [component for component in copy_component['components'] if component['key'] not in default_component_keys]
                copy_component['components'] = new_component
    return copy_component

