def _convert_errors(func):
    cast_Invalid = lambda e: Invalid(u'{message}, expected {expected}'.format(message=e.message, expected=e.expected) if e.expected != u'-none-' else e.message, e.path, six.text_type(e))

    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except good.SchemaError as e:
            raise SchemaError(six.text_type(e))
        except good.MultipleInvalid as ee:
            raise MultipleInvalid([cast_Invalid(e) for e in ee])
        except good.Invalid as e:
            raise MultipleInvalid([cast_Invalid(e)])
    return wrapper

def browse(self, wait=True, tempname='/tmp/seltable'):
    import os
    if os.system('test `which casabrowser`x != x') == 0:
        waitstr1 = ''
        waitstr2 = 'foreground ...'
        if not wait:
            waitstr1 = ' &'
            waitstr2 = 'background ...'
        if self.iswritable():
            six.print_('Flushing data and starting casabrowser in the ' + waitstr2)
        else:
            six.print_('Starting casabrowser in the ' + waitstr2)
        self.flush()
        self.unlock()
        if os.system('test -e ' + self.name() + '/table.dat') == 0:
            os.system('casabrowser ' + self.name() + waitstr1)
        elif len(tempname) > 0:
            six.print_('  making a persistent copy in table ' + tempname)
            self.copy(tempname)
            os.system('casabrowser ' + tempname + waitstr1)
            if wait:
                from casacore.tables import tabledelete
                six.print_('  finished browsing')
                tabledelete(tempname)
            else:
                six.print_(" after browsing use tabledelete('" + tempname + "') to delete the copy")
        else:
            six.print_('Cannot browse because the table is in memory only')
            six.print_('You can browse a (shallow) persistent copy ' + 'of the table like: ')
            six.print_("   t.browse(True, '/tmp/tab1')")
    else:
        try:
            import wxPython
        except ImportError:
            six.print_('casabrowser nor wxPython can be found')
            return
        from wxPython.wx import wxPySimpleApp
        import sys
        app = wxPySimpleApp()
        from wxtablebrowser import CasaTestFrame
        frame = CasaTestFrame(None, sys.stdout, self)
        frame.Show(True)
        app.MainLoop()

