    download_file_maybe_extract(url=url, directory=directory, check_files=check_files)
    ret = []
    splits = [dir_ for (requested, dir_) in [(train, train_directory), (test, test_directory)] if requested]
    for split_directory in splits:
        full_path = os.path.join(directory, extracted_name, split_directory)
        examples = []
        for sentiment in sentiments:
            for filename in glob.iglob(os.path.join(full_path, sentiment, '*.txt')):
                with open(filename, 'r', encoding='utf-8') as f:
                    text = f.readline()
                examples.append({'text': text, 'sentiment': sentiment})
        ret.append(Dataset(examples))
    if len(ret) == 1:
        return ret[0]
    else:
        return tuple(ret)

def proportions(self, axis=None, weighted=True, include_transforms_for_dims=None, include_mr_cat=False, prune=False):
    table = self._measure(weighted).raw_cube_array
    num = self._apply_subtotals(self._apply_missings(table), include_transforms_for_dims)
    proportions = num / self._denominator(weighted, include_transforms_for_dims, axis)
    if not include_mr_cat:
        proportions = self._drop_mr_cat_dims(proportions)
    arr = self.as_array(prune=prune, include_transforms_for_dims=include_transforms_for_dims)
    if isinstance(arr, np.ma.core.MaskedArray):
        proportions = np.ma.masked_array(proportions, arr.mask)
    return proportions

