def find_stress(self, word):
    syllabifier = Syllabifier()
    if type(word) is str:
        word = syllabifier.syllabify(word)
    syllables_stress = []
    for (i, syllable) in enumerate(word):
        if len(syllable) == 1:
            if self._is_circumflex_vowel(syllable):
                syllables_stress.append((syllable, 'Ultraheavy'))
                continue
        elif len(syllable) == 2:
            if self._is_consonant(syllable[0]) and self._is_circumflex_vowel(syllable[1]):
                syllables_stress.append((syllable, 'Ultraheavy'))
                continue
            if (self._is_macron_vowel(syllable[0]) or self._is_circumflex_vowel(syllable[0])) and self._is_consonant(syllable[1]):
                syllables_stress.append((syllable, 'Ultraheavy'))
                continue
        elif len(syllable) == 3:
            if self._is_macron_vowel(syllable[1]) or self._is_circumflex_vowel(syllable[1]):
                syllables_stress.append((syllable, 'Ultraheavy'))
                continue
        if len(syllable) == 1:
            if self._is_macron_vowel(syllable):
                syllables_stress.append((syllable, 'Heavy'))
                continue
        elif len(syllable) == 2:
            if self._is_consonant(syllable[0]) and self._is_macron_vowel(syllable[1]):
                syllables_stress.append((syllable, 'Heavy'))
                continue
            if self._is_short_vowel(syllable[0]) and self._is_consonant(syllable[1]):
                syllables_stress.append((syllable, 'Heavy'))
                continue
        elif len(syllable) == 3:
            if self._is_short_vowel(syllable[1]):
                syllables_stress.append((syllable, 'Heavy'))
                continue
        if len(syllable) == 1:
            if self._is_short_vowel(syllable):
                syllables_stress.append((syllable, 'Light'))
                continue
        elif len(syllable) == 2:
            if self._is_consonant(syllable[0]) and self._is_short_vowel(syllable[1]):
                syllables_stress.append((syllable, 'Light'))
                continue
    syllables_stress = syllables_stress[::-1]
    syllables = []
    found_stress = 0
    for (i, syllable) in enumerate(syllables_stress):
        if found_stress:
            syllables.append(syllable[0])
            continue
        elif syllable[1] == 'Ultraheavy' and i == 0:
            syllables.append('[{}]'.format(syllable[0]))
            found_stress = 1
            continue
        elif syllable[1] in ['Ultraheavy', 'Heavy'] and i > 0:
            syllables.append('[{}]'.format(syllable[0]))
            found_stress = 1
            continue
        elif syllable[1] == 'Heavy' and i == 0:
            syllables.append(syllable[0])
            continue
        elif syllable[1] == 'Light':
            syllables.append(syllable[0])
            continue
    syllables = syllables[::-1]
    if not found_stress:
        syllables[0] = '[{}]'.format(syllables[0])
    return syllables

def compute_savings_list(self, graph):
    savings_list = {}
    for (i, j) in graph.edges():
        if repr(i) < repr(j):
            t = (i, j)
        else:
            t = (j, i)
        if i == graph.depot() or j == graph.depot():
            continue
        savings_list[t] = graph.distance(graph.depot(), i) + graph.distance(graph.depot(), j) - graph.distance(i, j)
    sorted_savings_list = sorted(list(savings_list.items()), key=operator.itemgetter(1), reverse=True)
    return [nodes for (nodes, saving) in sorted_savings_list]

def _r1_scandinavian(self, word, vowels):
    r1 = ''
    for i in range(1, len(word)):
        if word[i] not in vowels and word[i - 1] in vowels:
            if len(word[:i + 1]) < 3 and len(word[:i + 1]) > 0:
                r1 = word[3:]
            elif len(word[:i + 1]) >= 3:
                r1 = word[i + 1:]
            else:
                return word
            break
    return r1

def _convert_listlike_datetimes(arg, box, format, name=None, tz=None, unit=None, errors=None, infer_datetime_format=None, dayfirst=None, yearfirst=None, exact=None):
    from pandas import DatetimeIndex
    from pandas.core.arrays import DatetimeArray
    from pandas.core.arrays.datetimes import maybe_convert_dtype, objects_to_datetime64ns
    if isinstance(arg, (list, tuple)):
        arg = np.array(arg, dtype='O')
    if is_datetime64tz_dtype(arg):
        if not isinstance(arg, (DatetimeArray, DatetimeIndex)):
            return DatetimeIndex(arg, tz=tz, name=name)
        if tz == 'utc':
            arg = arg.tz_convert(None).tz_localize(tz)
        return arg
    elif is_datetime64_ns_dtype(arg):
        if box and (not isinstance(arg, (DatetimeArray, DatetimeIndex))):
            try:
                return DatetimeIndex(arg, tz=tz, name=name)
            except ValueError:
                pass
        return arg
    elif unit is not None:
        if format is not None:
            raise ValueError('cannot specify both format and unit')
        arg = getattr(arg, 'values', arg)
        result = tslib.array_with_unit_to_datetime(arg, unit, errors=errors)
        if box:
            if errors == 'ignore':
                from pandas import Index
                result = Index(result, name=name)
                try:
                    return result.tz_localize(tz)
                except AttributeError:
                    return result
            return DatetimeIndex(result, tz=tz, name=name)
        return result
    elif getattr(arg, 'ndim', 1) > 1:
        raise TypeError('arg must be a string, datetime, list, tuple, 1-d array, or Series')
    orig_arg = arg
    (arg, _) = maybe_convert_dtype(arg, copy=False)
    arg = ensure_object(arg)
    require_iso8601 = False
    if infer_datetime_format and format is None:
        format = _guess_datetime_format_for_array(arg, dayfirst=dayfirst)
    if format is not None:
        format_is_iso8601 = _format_is_iso(format)
        if format_is_iso8601:
            require_iso8601 = not infer_datetime_format
            format = None
    tz_parsed = None
    result = None
    if format is not None:
        try:
            if format == '%Y%m%d':
                try:
                    orig_arg = ensure_object(orig_arg)
                    result = _attempt_YYYYMMDD(orig_arg, errors=errors)
                except (ValueError, TypeError, tslibs.OutOfBoundsDatetime):
                    raise ValueError("cannot convert the input to '%Y%m%d' date format")
            if result is None:
                try:
                    (result, timezones) = array_strptime(arg, format, exact=exact, errors=errors)
                    if '%Z' in format or '%z' in format:
                        return _return_parsed_timezone_results(result, timezones, box, tz, name)
                except tslibs.OutOfBoundsDatetime:
                    if errors == 'raise':
                        raise
                    elif errors == 'coerce':
                        result = np.empty(arg.shape, dtype='M8[ns]')
                        iresult = result.view('i8')
                        iresult.fill(tslibs.iNaT)
                    else:
                        result = arg
                except ValueError:
                    if not infer_datetime_format:
                        if errors == 'raise':
                            raise
                        elif errors == 'coerce':
                            result = np.empty(arg.shape, dtype='M8[ns]')
                            iresult = result.view('i8')
                            iresult.fill(tslibs.iNaT)
                        else:
                            result = arg
        except ValueError as e:
            try:
                (values, tz) = conversion.datetime_to_datetime64(arg)
                return DatetimeIndex._simple_new(values, name=name, tz=tz)
            except (ValueError, TypeError):
                raise e
    if result is None:
        assert format is None or infer_datetime_format
        utc = tz == 'utc'
        (result, tz_parsed) = objects_to_datetime64ns(arg, dayfirst=dayfirst, yearfirst=yearfirst, utc=utc, errors=errors, require_iso8601=require_iso8601, allow_object=True)
    if tz_parsed is not None:
        if box:
            return DatetimeIndex._simple_new(result, name=name, tz=tz_parsed)
        else:
            result = [Timestamp(ts, tz=tz_parsed).to_pydatetime() for ts in result]
            return np.array(result, dtype=object)
    if box:
        if is_datetime64_dtype(result):
            return DatetimeIndex(result, tz=tz, name=name)
        elif is_object_dtype(result):
            from pandas import Index
            return Index(result, name=name)
    return result

