def _get_ndarray_inputs(arg_key, args, arg_names, allow_missing):
    arg_handles = []
    arg_arrays = []
    if isinstance(args, list):
        if len(args) != len(arg_names):
            raise ValueError('Length of %s does not match the number of arguments' % arg_key)
        for narr in args:
            if narr is None and allow_missing:
                arg_handles.append(None)
            elif not isinstance(narr, NDArray):
                raise TypeError('Only accept list of NDArrays or dict of str to NDArray')
            else:
                arg_handles.append(narr.handle)
        arg_arrays = args
    elif isinstance(args, dict):
        for name in arg_names:
            if name in args:
                narr = args[name]
                if not isinstance(narr, NDArray):
                    raise TypeError('Only accept list of NDArrays or dict of str to NDArray')
                arg_handles.append(narr.handle)
                arg_arrays.append(narr)
            elif allow_missing:
                arg_handles.append(None)
                arg_arrays.append(None)
            else:
                raise ValueError('key `%s` is missing in `%s`' % (name, arg_key))
    else:
        raise TypeError('Only accept list of NDArrays or dict of str to NDArray')
    return (c_array(NDArrayHandle, arg_handles), arg_arrays)

def get_string_relative(strings: Sequence[str], prefix1: str, delta: int, prefix2: str, ignoreleadingcolon: bool=False, stripwhitespace: bool=True) -> Optional[str]:
    for firstline in range(0, len(strings)):
        if strings[firstline].find(prefix1) == 0:
            secondline = firstline + delta
            if secondline < 0 or secondline >= len(strings):
                continue
            if strings[secondline].find(prefix2) == 0:
                s = strings[secondline][len(prefix2):]
                if stripwhitespace:
                    s = s.strip()
                if ignoreleadingcolon:
                    f = s.find(':')
                    if f != -1:
                        s = s[f + 1:].strip()
                    if stripwhitespace:
                        s = s.strip()
                if len(s) == 0:
                    return None
                return s
    return None

