def grab_collisions(self, coords):
    collisions = []
    top_left = self.pixels_to_tiles(coords)
    collisions.append(self.tiles[top_left.Y][top_left.X])
    tile_width = int(self.spritesheet[0].width)
    tile_height = int(self.spritesheet[0].width)
    x_aligned = int(coords.X) & tile_width - 1
    y_aligned = int(coords.Y) & tile_height - 1
    if x_aligned > 0:
        if self.is_valid_tile(top_left.X + 1, top_left.Y):
            collisions.append(self.tiles[top_left.Y][top_left.X + 1])
    if y_aligned > 0:
        if self.is_valid_tile(top_left.X, top_left.Y + 1):
            collisions.append(self.tiles[top_left.Y + 1][top_left.X])
        if x_aligned > 0:
            if self.is_valid_tile(top_left.X + 1, top_left.Y + 1):
                collisions.append(self.tiles[top_left.Y + 1][top_left.X + 1])
    return collisions

def on_auth(self, f, connection, address):
    if f.is_success():
        self.logger.info('Authenticated with %s', f.result(), extra=self._logger_extras)
        with self._new_connection_mutex:
            self.connections[connection.endpoint] = f.result()
            try:
                self._pending_connections.pop(address)
            except KeyError:
                pass
        for (on_connection_opened, _) in self._connection_listeners:
            if on_connection_opened:
                on_connection_opened(f.result())
        return f.result()
    else:
        self.logger.debug('Error opening %s', connection, extra=self._logger_extras)
        with self._new_connection_mutex:
            try:
                self._pending_connections.pop(address)
            except KeyError:
                pass
        six.reraise(f.exception().__class__, f.exception(), f.traceback())

