def to_json(self):
    path = self.path
    if self.conflict_type in ('REORDER', 'SET_FIELD'):
        op = 'replace'
    elif self.conflict_type in ('MANUAL_MERGE', 'ADD_BACK_TO_HEAD'):
        op = 'add'
        path += ('-',)
    elif self.conflict_type == 'REMOVE_FIELD':
        op = 'remove'
    else:
        raise ValueError('Conflict Type %s can not be mapped to a json-patch operation' % conflict_type)
    json_pointer = '/' + '/'.join((str(el) for el in path))
    conflict_values = force_list(self.body)
    conflicts = []
    for value in conflict_values:
        if value is not None or self.conflict_type == 'REMOVE_FIELD':
            conflicts.append({'path': json_pointer, 'op': op, 'value': value, '$type': self.conflict_type})
    return json.dumps(conflicts)

def FilterCollection(aff4_collection, offset, count=0, filter_value=None):
    if offset < 0:
        raise ValueError('Offset needs to be greater than or equal to zero')
    if count < 0:
        raise ValueError('Count needs to be greater than or equal to zero')
    count = count or sys.maxsize
    if filter_value:
        index = 0
        items = []
        for item in aff4_collection.GenerateItems():
            serialized_item = item.SerializeToString()
            if re.search(re.escape(filter_value), serialized_item, re.I):
                if index >= offset:
                    items.append(item)
                index += 1
                if len(items) >= count:
                    break
    else:
        items = list(itertools.islice(aff4_collection.GenerateItems(offset), count))
    return items

