def image_list(self, lookup='all'):
    data = {}
    lookups = self.lookup_providers(lookup)
    if not lookups:
        return data
    for (alias, driver) in lookups:
        fun = '{0}.avail_images'.format(driver)
        if fun not in self.clouds:
            log.debug("The '%s' cloud driver defined under '%s' provider alias is unable to get the images information", driver, alias)
            continue
        if alias not in data:
            data[alias] = {}
        try:
            with salt.utils.context.func_globals_inject(self.clouds[fun], __active_provider_name__=':'.join([alias, driver])):
                data[alias][driver] = self.clouds[fun]()
        except Exception as err:
            log.error("Failed to get the output of '%s()': %s", fun, err, exc_info_on_loglevel=logging.DEBUG)
    return data

