def dictPromise(m):
    ret = Promise()

    def handleSuccess(v, ret):
        for p in m.values():
            if not p.isFulfilled():
                return
        value = {}
        for k in m:
            value[k] = m[k].value
        ret.fulfill(value)
    for p in m.values():
        p.addCallback(lambda v: handleSuccess(v, ret))
        p.addErrback(lambda r: ret.reject(r))
    handleSuccess(None, ret)
    return ret

def __solve_for_scalar(expr, vars):
    var = solve(expr, vars).value
    try:
        scalar = repeated.getvalue(var)
    except TypeError:
        raise errors.EfilterTypeError(root=expr, query=expr.source, message="Wasn't expecting more than one value here. Got %r." % (var,))
    if isinstance(scalar, row_tuple.RowTuple):
        try:
            return scalar.get_singleton()
        except ValueError:
            raise errors.EfilterTypeError(root=expr, query=expr.source, message='Was expecting a scalar value here. Got %r.' % (scalar,))
    else:
        return scalar

