        data['split_text'] = self.wrap_text(data['text'], width=n_cols - 2)
        data['n_rows'] = len(data['split_title'] + data['split_text']) + 5
        data['h_offset'] = 0
    else:
        data = self._comment_data[index]
        indent_level = min(data['level'], self.max_indent_level)
