        aq = self.model.aq.find_aquifer_data(x, y)
    qxqy = self.disvecinf(x, y, aq)
    qx = np.sum(qxqy[0, :, np.newaxis, :] * aq.eigvec, 2).T
    qy = np.sum(qxqy[1, :, np.newaxis, :] * aq.eigvec, 2).T
    return np.array((qx[layers], qy[layers]))

