def get_fd_from_freqtau(template=None, **kwargs):
    input_params = props(template, freqtau_required_args, **kwargs)
    (f_0, tau) = lm_freqs_taus(**input_params)
    lmns = input_params['lmns']
    for lmn in lmns:
        if int(lmn[2]) == 0:
            raise ValueError('Number of overtones (nmodes) must be greater than zero.')
    inc = input_params.pop('inclination', None)
    delta_f = input_params.pop('delta_f', None)
    f_lower = input_params.pop('f_lower', None)
    f_final = input_params.pop('f_final', None)
    if not delta_f:
        delta_f = lm_deltaf(tau, lmns)
    if not f_final:
        f_final = lm_ffinal(f_0, tau, lmns)
    if not f_lower:
        f_lower = delta_f
    kmax = int(f_final / delta_f) + 1
    outplustilde = FrequencySeries(zeros(kmax, dtype=complex128), delta_f=delta_f)
    outcrosstilde = FrequencySeries(zeros(kmax, dtype=complex128), delta_f=delta_f)
    for lmn in lmns:
        (l, m, nmodes) = (int(lmn[0]), int(lmn[1]), int(lmn[2]))
        (hplustilde, hcrosstilde) = get_fd_lm(freqs=f_0, taus=tau, l=l, m=m, nmodes=nmodes, inclination=inc, delta_f=delta_f, f_lower=f_lower, f_final=f_final, **input_params)
        outplustilde.data += hplustilde.data
        outcrosstilde.data += hcrosstilde.data
    return (outplustilde, outcrosstilde)

def mercator_transform(data, lat_bounds, origin='upper', height_out=None):
    import numpy as np

    def mercator(x):
        return np.arcsinh(np.tan(x * np.pi / 180.0)) * 180.0 / np.pi
    array = np.atleast_3d(data).copy()
    (height, width, nblayers) = array.shape
    lat_min = max(lat_bounds[0], -85.05112877980659)
    lat_max = min(lat_bounds[1], 85.05112877980659)
    if height_out is None:
        height_out = height
    if origin == 'upper':
        array = array[::-1, :, :]
    lats = lat_min + np.linspace(0.5 / height, 1.0 - 0.5 / height, height) * (lat_max - lat_min)
    latslats = mercator(lat_min) + np.linspace(0.5 / height_out, 1.0 - 0.5 / height_out, height_out) * (mercator(lat_max) - mercator(lat_min))
    out = np.zeros((height_out, width, nblayers))
    for i in range(width):
        for j in range(nblayers):
            out[:, i, j] = np.interp(latslats, mercator(lats), array[:, i, j])
    if origin == 'upper':
        out = out[::-1, :, :]
    return out

