    for (current_path, directories, files) in os.walk(local_path):
        try:
            ftp.listdir(remote_path)
        except IOError:
            ftp.mkdir(remote_path)
        for filename in files:
            ftp.put(os.path.join(current_path, filename), remote_path + filename)
