def apply_T12(word):
    WORD = word
    offset = 0
    for vv in new_vv(WORD):
        seq = vv.group(1)
        if not is_diphthong(seq) and (not is_long(seq)):
            i = vv.start(1) + 1 + offset
            WORD = WORD[:i] + '.' + WORD[i:]
            offset += 1
    RULE = ' T2' if word != WORD else ''
    return (WORD, RULE)

def VariablesValues(self, variables, t):
    if (t < self.te) | (t > 0):
        i = t // self.ts
        ti = self.ts * i
        if type(variables) == list:
            values = []
            for variable in variables:
                values.append(variables.values[i] * ((ti - t) / self.ts + 1) + variables.values[i + 1] * (t - ti) / self.ts)
            return values
        else:
            return variables.values[i] * ((ti - t) / self.ts + 1) + variables.values[i + 1] * (t - ti) / self.ts
    else:
        raise ValueError

