                logger.error('Error processing subsets: %s for subset %s' % (subset.get_type(), subsetname))
    return df.join(DataFrame(subset_ids))

def sign(self, msg):
    if self.__signingkey is None:
        raise KeyTypeError('Wrong key type for operation')
    sig = ffi.new(C_SIGNATURE)
    lib.ed25519_SignMessage(sig, self.__signingkey, ffi.NULL, msg, len(msg))
    return ffi.get_bytes(sig)

def write(self, filename=None):
    file_data = list(self.__data__)
    for structure in self.__structures__:
        struct_data = list(structure.__pack__())
        offset = structure.get_file_offset()
        file_data[offset:offset + len(struct_data)] = struct_data
    if hasattr(self, 'VS_VERSIONINFO'):
        if hasattr(self, 'FileInfo'):
            for entry in self.FileInfo:
                if hasattr(entry, 'StringTable'):
                    for st_entry in entry.StringTable:
                        for (key, entry) in st_entry.entries.items():
                            offsets = st_entry.entries_offsets[key]
                            lengths = st_entry.entries_lengths[key]
                            if len(entry) > lengths[1]:
                                l = list()
                                for (idx, c) in enumerate(entry):
                                    if ord(c) > 256:
                                        l.extend([chr(ord(c) & 255), chr((ord(c) & 65280) >> 8)])
                                    else:
                                        l.extend([chr(ord(c)), '\x00'])
                                file_data[offsets[1]:offsets[1] + lengths[1] * 2] = l
                            else:
                                l = list()
                                for (idx, c) in enumerate(entry):
                                    if ord(c) > 256:
                                        l.extend([chr(ord(c) & 255), chr((ord(c) & 65280) >> 8)])
                                    else:
                                        l.extend([chr(ord(c)), '\x00'])
                                file_data[offsets[1]:offsets[1] + len(entry) * 2] = l
                                remainder = lengths[1] - len(entry)
                                file_data[offsets[1] + len(entry) * 2:offsets[1] + lengths[1] * 2] = [u'\x00'] * remainder * 2
    new_file_data = ''.join([chr(ord(c)) for c in file_data])
    if filename:
        f = file(filename, 'wb+')
        f.write(new_file_data)
        f.close()
    else:
        return new_file_data

def _aix_memdata():
    grains = {'mem_total': 0, 'swap_total': 0}
    prtconf = salt.utils.path.which('prtconf')
    if prtconf:
        for line in __salt__['cmd.run'](prtconf, python_shell=True).splitlines():
            comps = [x for x in line.strip().split(' ') if x]
            if len(comps) > 2 and 'Memory' in comps[0] and ('Size' in comps[1]):
                grains['mem_total'] = int(comps[2])
                break
    else:
        log.error("The 'prtconf' binary was not found in $PATH.")
    swap_cmd = salt.utils.path.which('swap')
    if swap_cmd:
        swap_data = __salt__['cmd.run']('{0} -s'.format(swap_cmd)).split()
        try:
            swap_total = (int(swap_data[-2]) + int(swap_data[-6])) * 4
        except ValueError:
            swap_total = None
        grains['swap_total'] = swap_total
    else:
        log.error("The 'swap' binary was not found in $PATH.")
    return grains

