def set_font(path, columns=None, rows=None, columnFirst=False, greyscale=False, altLayout=False):
    FONT_LAYOUT_ASCII_INCOL = 1
    FONT_LAYOUT_ASCII_INROW = 2
    FONT_TYPE_GREYSCALE = 4
    FONT_LAYOUT_TCOD = 8
    global _fontinitialized
    _fontinitialized = True
    flags = 0
    if altLayout:
        flags |= FONT_LAYOUT_TCOD
    elif columnFirst:
        flags |= FONT_LAYOUT_ASCII_INCOL
    else:
        flags |= FONT_LAYOUT_ASCII_INROW
    if greyscale:
        flags |= FONT_TYPE_GREYSCALE
    if not _os.path.exists(path):
        raise TDLError('Font %r not found.' % _os.path.abspath(path))
    path = _os.path.abspath(path)
    imgSize = _getImageSize(path)
    if imgSize:
        (fontWidth, fontHeight) = (None, None)
        (imgWidth, imgHeight) = imgSize
        match = _re.match('.*?([0-9]+)[xX]([0-9]+)', _os.path.basename(path))
        if match:
            (fontWidth, fontHeight) = match.groups()
            (fontWidth, fontHeight) = (int(fontWidth), int(fontHeight))
            (estColumns, remC) = divmod(imgWidth, fontWidth)
            (estRows, remR) = divmod(imgHeight, fontHeight)
            if remC or remR:
                _warnings.warn('Font may be incorrectly formatted.')
            if not columns:
                columns = estColumns
            if not rows:
                rows = estRows
        else:
            if columns and rows:
                (fontWidth, remC) = divmod(imgWidth, columns)
                (fontHeight, remR) = divmod(imgHeight, rows)
                if remC or remR:
                    _warnings.warn('Font may be incorrectly formatted.')
            if not (columns and rows):
                raise TDLError('%s has no font size in filename' % _os.path.basename(path))
        if columns and rows:
            if fontWidth * columns != imgWidth or fontHeight * rows != imgHeight:
                _warnings.warn('set_font parameters are set as if the image size is (%d, %d) when the detected size is actually (%i, %i)' % (fontWidth * columns, fontHeight * rows, imgWidth, imgHeight))
    else:
        _warnings.warn('%s is probably not an image.' % _os.path.basename(path))
    if not (columns and rows):
        raise TDLError('Can not auto-detect the tileset of %s' % _os.path.basename(path))
    _lib.TCOD_console_set_custom_font(_encodeString(path), flags, columns, rows)

def inttoptr(self, typ):
    if not isinstance(self.type, types.IntType):
        raise TypeError("can only call inttoptr() on integer constants, not '%s'" % (self.type,))
    if not isinstance(typ, types.PointerType):
        raise TypeError("can only inttoptr() to pointer type, not '%s'" % (typ,))
    op = 'inttoptr ({0} {1} to {2})'.format(self.type, self.get_reference(), typ)
    return FormattedConstant(typ, op)

def cached_per_instance():

    def cache_fun(fun):
        argspec = inspect2.getfullargspec(fun)
        arg_names = argspec.args[1:] + argspec.kwonlyargs
        kwargs_defaults = get_kwargs_defaults(argspec)
        cache = {}

        def cache_key(args, kwargs):
            return get_args_tuple(args, kwargs, arg_names, kwargs_defaults)

        def clear_cache(instance_key, ref):
            del cache[instance_key]

        @functools.wraps(fun)
        def new_fun(self, *args, **kwargs):
            instance_key = id(self)
            if instance_key not in cache:
                ref = weakref.ref(self, functools.partial(clear_cache, instance_key))
                cache[instance_key] = (ref, {})
            instance_cache = cache[instance_key][1]
            k = cache_key(args, kwargs)
            if k not in instance_cache:
                instance_cache[k] = fun(self, *args, **kwargs)
            return instance_cache[k]
        new_fun.__cached_per_instance_cache__ = cache
        return new_fun
    return cache_fun

