def validate_voicing(ref_voicing, est_voicing):
    if ref_voicing.size == 0:
        warnings.warn('Reference voicing array is empty.')
    if est_voicing.size == 0:
        warnings.warn('Estimated voicing array is empty.')
    if ref_voicing.sum() == 0:
        warnings.warn('Reference melody has no voiced frames.')
    if est_voicing.sum() == 0:
        warnings.warn('Estimated melody has no voiced frames.')
    if ref_voicing.shape[0] != est_voicing.shape[0]:
        raise ValueError('Reference and estimated voicing arrays should be the same length.')
    for voicing in [ref_voicing, est_voicing]:
        if np.logical_and(voicing != 0, voicing != 1).any():
            raise ValueError('Voicing arrays must be boolean.')

def find_ngam(model):
    atp_adp_conv_rxns = helpers.find_converting_reactions(model, ('MNXM3', 'MNXM7'))
    id_of_main_compartment = helpers.find_compartment_id_in_model(model, 'c')
    reactants = {helpers.find_met_in_model(model, 'MNXM3', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM2', id_of_main_compartment)[0]}
    products = {helpers.find_met_in_model(model, 'MNXM7', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM1', id_of_main_compartment)[0], helpers.find_met_in_model(model, 'MNXM9', id_of_main_compartment)[0]}
    candidates = [rxn for rxn in atp_adp_conv_rxns if rxn.reversibility is False and set(rxn.reactants) == reactants and (set(rxn.products) == products)]
    buzzwords = ['maintenance', 'atpm', 'requirement', 'ngam', 'non-growth', 'associated']
    refined_candidates = [rxn for rxn in candidates if any((string in filter_none(rxn.name, '').lower() for string in buzzwords))]
    if refined_candidates:
        return refined_candidates
    else:
        return candidates

def _set_contents(self, force=False):
    if self.children is None:
        self._parse_children()
    contents = BytesIO()
    for (index, info) in enumerate(self._fields):
        child = self.children[index]
        if child is None:
            child_dump = b''
        elif child.__class__ == tuple:
            if force:
                child_dump = self._lazy_child(index).dump(force=force)
            else:
                child_dump = child[3] + child[4] + child[5]
        else:
            child_dump = child.dump(force=force)
        if info[2] and 'default' in info[2]:
            default_value = info[1](**info[2])
            if default_value.dump() == child_dump:
                continue
        contents.write(child_dump)
    self._contents = contents.getvalue()
