def range_request(numbytes):
    if numbytes <= 0 or numbytes > 100 * 1024:
        response = Response(headers={'ETag': 'range%d' % numbytes, 'Accept-Ranges': 'bytes'})
        response.status_code = 404
        response.data = 'number of bytes must be in the range (0, 102400]'
        return response
    params = CaseInsensitiveDict(request.args.items())
    if 'chunk_size' in params:
        chunk_size = max(1, int(params['chunk_size']))
    else:
        chunk_size = 10 * 1024
    duration = float(params.get('duration', 0))
    pause_per_byte = duration / numbytes
    request_headers = get_headers()
    (first_byte_pos, last_byte_pos) = get_request_range(request_headers, numbytes)
    range_length = last_byte_pos + 1 - first_byte_pos
    if first_byte_pos > last_byte_pos or first_byte_pos not in xrange(0, numbytes) or last_byte_pos not in xrange(0, numbytes):
        response = Response(headers={'ETag': 'range%d' % numbytes, 'Accept-Ranges': 'bytes', 'Content-Range': 'bytes */%d' % numbytes, 'Content-Length': '0'})
        response.status_code = 416
        return response

    def generate_bytes():
        chunks = bytearray()
        for i in xrange(first_byte_pos, last_byte_pos + 1):
            chunks.append(ord('a') + i % 26)
            if len(chunks) == chunk_size:
                yield bytes(chunks)
                time.sleep(pause_per_byte * chunk_size)
                chunks = bytearray()
        if chunks:
            time.sleep(pause_per_byte * len(chunks))
            yield bytes(chunks)
    content_range = 'bytes %d-%d/%d' % (first_byte_pos, last_byte_pos, numbytes)
    response_headers = {'Content-Type': 'application/octet-stream', 'ETag': 'range%d' % numbytes, 'Accept-Ranges': 'bytes', 'Content-Length': str(range_length), 'Content-Range': content_range}
    response = Response(generate_bytes(), headers=response_headers)
    if first_byte_pos == 0 and last_byte_pos == numbytes - 1:
        response.status_code = 200
    else:
        response.status_code = 206
    return response

def normalize_map_between(dictionary, norm_min, norm_max):
    if len(dictionary) < 2:
        return {}
    values = list(dictionary.values())
    norm_range = norm_max - norm_min
    map_min = min(values)
    map_range = max(values) - map_min
    range_factor = norm_range / float(map_range)
    normalized_map = {}
    for (key, value) in dictionary.items():
        normalized_map[key] = norm_min + (value - map_min) * range_factor
    return normalized_map

