def _reldiff(a, b):
    a = float(a)
    b = float(b)
    aa = abs(a)
    ba = abs(b)
    if a == 0.0 and b == 0.0:
        return 0.0
    elif a == 0 or b == 0.0:
        return float('inf')
    return abs(a - b) / min(aa, ba)

def get_entries(self, chemsys_formula_id_criteria, compatible_only=True, inc_structure=None, property_data=None, conventional_unit_cell=False, sort_by_e_above_hull=False):
    params = ['run_type', 'is_hubbard', 'pseudo_potential', 'hubbards', 'potcar_symbols', 'oxide_type']
    props = ['energy', 'unit_cell_formula', 'task_id'] + params
    if sort_by_e_above_hull:
        if property_data and 'e_above_hull' not in property_data:
            property_data.append('e_above_hull')
        elif not property_data:
            property_data = ['e_above_hull']
    if property_data:
        props += property_data
    if inc_structure:
        if inc_structure == 'initial':
            props.append('initial_structure')
        else:
            props.append('structure')
    if not isinstance(chemsys_formula_id_criteria, dict):
        criteria = MPRester.parse_criteria(chemsys_formula_id_criteria)
    else:
        criteria = chemsys_formula_id_criteria
    data = self.query(criteria, props)
    entries = []
    for d in data:
        d['potcar_symbols'] = ['%s %s' % (d['pseudo_potential']['functional'], l) for l in d['pseudo_potential']['labels']]
        data = {'oxide_type': d['oxide_type']}
        if property_data:
            data.update({k: d[k] for k in property_data})
        if not inc_structure:
            e = ComputedEntry(d['unit_cell_formula'], d['energy'], parameters={k: d[k] for k in params}, data=data, entry_id=d['task_id'])
        else:
            prim = d['initial_structure'] if inc_structure == 'initial' else d['structure']
            if conventional_unit_cell:
                s = SpacegroupAnalyzer(prim).get_conventional_standard_structure()
                energy = d['energy'] * (len(s) / len(prim))
            else:
                s = prim.copy()
                energy = d['energy']
            e = ComputedStructureEntry(s, energy, parameters={k: d[k] for k in params}, data=data, entry_id=d['task_id'])
        entries.append(e)
    if compatible_only:
        from pymatgen.entries.compatibility import MaterialsProjectCompatibility
        entries = MaterialsProjectCompatibility().process_entries(entries)
    if sort_by_e_above_hull:
        entries = sorted(entries, key=lambda entry: entry.data['e_above_hull'])
    return entries

