def _moving_average(data, wind_size=3):
    wind_size = int(wind_size)
    ret = numpy.cumsum(data, dtype=float)
    ret[wind_size:] = ret[wind_size:] - ret[:-wind_size]
    return numpy.concatenate((numpy.zeros(wind_size - 1), ret[wind_size - 1:] / wind_size))

def integrate_converge(self, crit=0.0001, verbose=True):
    for (varname, value) in self.state.items():
        value_old = copy.deepcopy(value)
        self.integrate_years(1, verbose=False)
        while np.max(np.abs(value_old - value)) > crit:
            value_old = copy.deepcopy(value)
            self.integrate_years(1, verbose=False)
    if verbose == True:
        print('Total elapsed time is %s years.' % str(self.time['days_elapsed'] / const.days_per_year))

