def download_yield_bytes(url, chunk_size=1024 * 1024 * 10):
    response = requests.get(url, stream=True)
    response.raise_for_status()
    total_length = response.headers.get('content-length')
    if total_length is not None:
        total_length = float(total_length)
        length_str = '{0:.2f}Mb '.format(total_length / (1024 * 1024))
    else:
        length_str = ''
    print('Yielding {0:s} {1:s}'.format(url, length_str))
    for chunk in response.iter_content(chunk_size=chunk_size):
        yield chunk
    response.close()

def conj(self, out=None):
    if self.space.is_real:
        if out is None:
            return self
        else:
            out[:] = self
            return out
    if not is_numeric_dtype(self.space.dtype):
        raise NotImplementedError('`conj` not defined for non-numeric dtype {}'.format(self.dtype))
    if out is None:
        return self.space.element(self.data.conj())
    else:
        if out not in self.space:
            raise LinearSpaceTypeError('`out` {!r} not in space {!r}'.format(out, self.space))
        self.data.conj(out.data)
        return out

