        value = self._config[attr_name]
        attr_type = attr_config.attr_type
        if attr_type:
            if value:
                if issubclass(attr_type, list):
                    if issubclass(attr_type, NamedTupleList):
                        d[attr_name] = [i._asdict() for i in value]
                    else:
