def get_request(self):
    (client_socket, client_address) = self.socket.accept()
    if ssl is not None and self.cert_file:
        context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
        try:
            context.verify_mode = ssl.CERT_REQUIRED
            context.load_cert_chain(certfile=self.cert_file, keyfile=self.key_file, password=self.key_password)
            if self.ca_file:
                context.load_verify_locations(self.ca_file)
            else:
                context.load_default_certs(ssl.Purpose.CLIENT_AUTH)
        except Exception as ex:
            _logger.error('Error setting up the SSL context: %s', ex)
            raise
        try:
            client_stream = context.wrap_socket(client_socket, server_side=True)
        except ssl.SSLError as ex:
            _logger.warning('Error during SSL handshake with %s: %s', client_address, ex)
            raise
    else:
        client_stream = client_socket
    return (client_stream, client_address)

