        (tag, original, loc) = (displayable(tag), displayable(original), int(loc))
        if '{' not in tag:
            out = ['[' + tag + ']']
            add_line_col = True
            if tokens is not None:
                if isinstance(tokens, Exception):
                    msg = displayable(str(tokens))
                    if '{' in msg:
                        (head, middle) = msg.split('{', 1)
                        (middle, tail) = middle.rsplit('}', 1)
                        msg = head + '{...}' + tail
                    out.append(msg)
                    add_line_col = False
                elif len(tokens) == 1 and isinstance(tokens[0], str):
                    out.append(ascii(tokens[0]))
                else:
                    out.append(ascii(tokens))
            if add_line_col:
                out.append('(line:' + str(lineno(loc, original)) + ', col:' + str(col(loc, original)) + ')')
            if extra is not None:
                out.append('from ' + ascii(extra))
            printerr(*out)

def from_files(cls, directory: str) -> 'Vocabulary':
    logger.info('Loading token dictionary from %s.', directory)
    with codecs.open(os.path.join(directory, NAMESPACE_PADDING_FILE), 'r', 'utf-8') as namespace_file:
        non_padded_namespaces = [namespace_str.strip() for namespace_str in namespace_file]
    vocab = cls(non_padded_namespaces=non_padded_namespaces)
    for namespace_filename in os.listdir(directory):
        if namespace_filename == NAMESPACE_PADDING_FILE:
            continue
        if namespace_filename.startswith('.'):
            continue
        namespace = namespace_filename.replace('.txt', '')
        if any((namespace_match(pattern, namespace) for pattern in non_padded_namespaces)):
            is_padded = False
        else:
            is_padded = True
        filename = os.path.join(directory, namespace_filename)
        vocab.set_from_file(filename, is_padded, namespace=namespace)
    return vocab

