        raise ValueError('Either use "all" or use list of terms from this {0} list \n.'.format(energyTerms))
    (segments, errors, energies) = ([], OrderedDict(), OrderedDict())
    for name in which:
        energies[name] = []
        errors[name] = []
    for s in range(bp[0], bp[1]):
        if s + span - 1 > bp[1]:
            break
        (time, energy_t) = self.getLocalDeformationEnergy([s, s + span - 1], complexDna, freeDnaFrames=freeDnaFrames, boundDnaFrames=boundDnaFrames, helical=helical, unit=unit, which=which)
        error_t = dnaMD.get_error(time, list(energy_t.values()), len(which), err_type=err_type, tool=tool)
        for i in range(len(which)):
            en_t = np.mean(energy_t[which[i]])
            energies[which[i]].append(en_t)
            errors[which[i]].append(error_t[i])
        segments.append('{0}-{1}'.format(s, s + span - 1))
    if outFile is not None:
        with open(outFile, 'w') as fout:
            fout.write('#bps')
            for name in which:
                fout.write(', {0}, {0}-error'.format(name))
            fout.write('\n')
            for s in range(len(segments)):
                fout.write('{0}'.format(segments[s]))
                for name in which:
                    fout.write(', {0:.5f}, {1:.5f}'.format(energies[name][s], errors[name][s]))
                fout.write('\n')
    return (segments, energies, errors)

def strip_callables(row):
    callables = []
    to_delete = []
    to_add = []
    for (columns, value) in row.items():
        if isinstance(value, tuple):
            (initial, fn) = value
        else:
            initial = NOTHING
            fn = value
        if callable(fn) or inspect.isgenerator(fn):
            lgr.debug('Using %r as the initial value for columns %r in row %r', initial, columns, row)
            if not isinstance(columns, tuple):
                columns = (columns,)
            else:
                to_delete.append(columns)
            for column in columns:
                to_add.append((column, initial))
            callables.append((columns, fn))
    for (column, value) in to_add:
        row[column] = value
    for multi_columns in to_delete:
        del row[multi_columns]
    return callables

def cooccurrence(corpus_or_featureset, featureset_name=None, min_weight=1, edge_attrs=['ayjid', 'date'], filter=None):
    if not filter:
        filter = lambda f, v, c, dc: dc >= min_weight
    featureset = _get_featureset(corpus_or_featureset, featureset_name)
    if type(corpus_or_featureset) in [Corpus, StreamingCorpus]:
        attributes = {i: {a: corpus_or_featureset.indices_lookup[i][a] for a in edge_attrs} for i in corpus_or_featureset.indexed_papers.keys()}
    c = lambda f: featureset.count(f)
    dc = lambda f: featureset.documentCount(f)
    attributes = {}
    if type(featureset) is FeatureSet:
        select = lambda feature: [f for (f, v) in feature if filter(f, v, c(f), dc(f))]
    elif type(featureset) is StructuredFeatureSet:
        select = lambda feature: [f for f in feature if filter(f, feature.count(f), c(f), dc(f))]
    pairs = Counter()
    eattrs = defaultdict(dict)
    nattrs = defaultdict(dict)
    nset = set()
    for (paper, feature) in featureset.iteritems():
        if len(feature) == 0:
            continue
        selected = select(feature)
        nset |= set(selected)
        for combo in combinations(selected, 2):
            combo = tuple(sorted(combo))
            pairs[combo] += 1
            if paper in attributes:
                eattrs[combo] = attributes[paper]
    for n in list(nset):
        nattrs[n]['count'] = featureset.count(n)
        nattrs[n]['documentCount'] = featureset.documentCount(n)
    return _generate_graph(nx.Graph, pairs, edge_attrs=eattrs, node_attrs=nattrs, min_weight=min_weight)

