def requires(self):
    if self.asm in arch.zx48k.backend.ASMS:
        return ALL_REGS
    if self.inst == '#pragma':
        tmp = self.__instr.split(' ')[1:]
        if tmp[0] != 'opt':
            return
        if tmp[1] == 'require':
            return set(flatten_list([single_registers(x.strip(', \t\r')) for x in tmp[2:]]))
        return set([])
    result = set([])
    i = self.inst
    o = [x.lower() for x in self.opers]
    if i in ['ret', 'pop', 'push']:
        result.add('sp')
    if self.condition_flag is not None or i in ['sbc', 'adc']:
        result.add('f')
    for O in o:
        if '(hl)' in O:
            result.add('h')
            result.add('l')
        if '(de)' in O:
            result.add('d')
            result.add('e')
        if '(bc)' in O:
            result.add('b')
            result.add('c')
        if '(sp)' in O:
            result.add('sp')
        if '(ix' in O:
            result.add('ixh')
            result.add('ixl')
        if '(iy' in O:
            result.add('iyh')
            result.add('iyl')
    if i in ['ccf']:
        result.add('f')
    elif i in {'rra', 'rla', 'rrca', 'rlca'}:
        result.add('a')
        result.add('f')
    elif i in ['xor', 'cp']:
        if o[0] != 'a':
            result.add('a')
            if o[0][0] != '(' and (not is_number(o[0])):
                result = result.union(single_registers(o))
    elif i in ['or', 'and']:
        result.add('a')
        if o[0][0] != '(' and (not is_number(o[0])):
            result = result.union(single_registers(o))
    elif i in {'adc', 'sbc', 'add', 'sub'}:
        if len(o) == 1:
            if i not in ('sub', 'sbc') or o[0] != 'a':
                result.add('a')
            if o[0][0] != '(' and (not is_number(o[0])):
                result = result.union(single_registers(o))
        elif o[0] != o[1] or i in ('add', 'adc'):
            result = result.union(single_registers(o))
        if i in ['adc', 'sbc']:
            result.add('f')
    elif i in {'daa', 'rld', 'rrd', 'neg', 'cpl'}:
        result.add('a')
    elif i in {'rl', 'rr', 'rlc', 'rrc'}:
        result = result.union(single_registers(o) + ['f'])
    elif i in {'sla', 'sll', 'sra', 'srl', 'inc', 'dec'}:
        result = result.union(single_registers(o))
    elif i == 'djnz':
        result.add('b')
    elif i in {'ldir', 'lddr', 'ldi', 'ldd'}:
        result = result.union(['b', 'c', 'd', 'e', 'h', 'l'])
    elif i in {'cpi', 'cpd', 'cpir', 'cpdr'}:
        result = result.union(['a', 'b', 'c', 'h', 'l'])
    elif i == 'ld' and (not is_number(o[1])):
        result = result.union(single_registers(o[1]))
    elif i == 'ex':
        if o[0] == 'de':
            result = result.union(['d', 'e', 'h', 'l'])
        elif o[1] == '(sp)':
            result = result.union(['h', 'l'])
        else:
            result = result.union(['a', 'f', "a'", "f'"])
    elif i == 'exx':
        result = result.union(['b', 'c', 'd', 'e', 'h', 'l'])
    elif i == 'push':
        result = result.union(single_registers(o))
    elif i in {'bit', 'set', 'res'}:
        result = result.union(single_registers(o[1]))
    elif i == 'out':
        result.add(o[1])
        if o[0] == '(c)':
            result.add('c')
    elif i == 'in':
        if o[1] == '(c)':
            result.add('c')
    elif i == 'im':
        result.add('i')
    result = list(result)
    return result

