    (field, address, pack_chars) = self._get_struct_field_and_address(struct_name, field_name)
    length = struct.calcsize(pack_chars)
    data = self.read(address, length, x, y, p)
    unpacked = struct.unpack(pack_chars, data)
    if field.length == 1:
        return unpacked[0]
    else:
        return unpacked

def dbscan(points, eps, minpts):
    next_label = 0
    n = len(points)
    labels = [None] * n
    distance_matrix = compute_distance_matrix(points)
    neighbors = [get_neighbors(distance_matrix, i, eps) for i in range(n)]
    for i in range(n):
        if labels[i] is not None:
            continue
        if len(neighbors[i]) < minpts:
            continue
        labels[i] = next_label
        candidates = [i]
        while len(candidates) > 0:
            c = candidates.pop()
            for j in neighbors[c]:
                if labels[j] is None:
                    labels[j] = next_label
                    if len(neighbors[j]) >= minpts:
                        candidates.append(j)
        next_label += 1
    return labels

