def getlist(self, key, type_=None):
    try:
        rv = dict.__getitem__(self, key)
    except KeyError:
        return []
    if type_ is None:
        return list(rv)
    result = []
    for item in rv:
        try:
            result.append(type_(item))
        except ValueError:
            pass
    return result

def _bootstrapped_fit_iter(fitter_args_kargs, n=None, datalist=None, pdatalist=None, **kargs):
    (fitter, args, okargs) = fitter_args_kargs
    for k in okargs:
        if k not in kargs:
            kargs[k] = okargs[k]
    if 'p0' not in kargs:
        kargs['p0'] = args['p0']
    if datalist is not None:
        pdatalist = (MultiFitter.process_data(d, args['models']) for d in datalist)
    elif pdatalist is None:
        pdata = args['pdata']
        if pdata is None:
            pdata = MultiFitter.process_data(args['data'], args['models'])
        pdatalist = gvar.bootstrap_iter(pdata, n)
    i = 0
    for pdata in pdatalist:
        i += 1
        if n is not None and i > n:
            break
        fit = fitter(pdata=pdata, prior=args['prior'], **kargs)
        yield fit

