def task_percentages(data, n_tasks=9):
    pdata = deepcopy(data)
    for i in range(len(data)):
        for j in range(len(data[0])):
            percentages = [0.0] * n_tasks
            for k in range(len(data[i][j])):
                b_ind = data[i][j][k].find('b')
                for l in range(b_ind + 1, len(data[i][j][k])):
                    percentages[l - 2] += int(data[i][j][k][l])
            for p in range(len(percentages)):
                percentages[p] /= len(data[i][j])
            pdata[i][j] = percentages
    return pdata

def check_with_pyflakes(source_code, filename=None):
    try:
        if filename is None:
            filename = '<string>'
        try:
            source_code += '\n'
        except TypeError:
            source_code += to_binary_string('\n')
        import _ast
        from pyflakes.checker import Checker
        try:
            tree = compile(source_code, filename, 'exec', _ast.PyCF_ONLY_AST)
        except SyntaxError as value:
            if value.text is None:
                results = []
            else:
                results = [(value.args[0], value.lineno)]
        except (ValueError, TypeError):
            results = []
        else:
            w = Checker(tree, filename)
            w.messages.sort(key=lambda x: x.lineno)
            results = []
            coding = encoding.get_coding(source_code)
            lines = source_code.splitlines()
            for warning in w.messages:
                if 'analysis:ignore' not in to_text_string(lines[warning.lineno - 1], coding):
                    results.append((warning.message % warning.message_args, warning.lineno))
    except Exception:
        results = []
        if DEBUG_EDITOR:
            traceback.print_exc()
    return results

def copyKeyMultipart(srcBucketName, srcKeyName, srcKeyVersion, dstBucketName, dstKeyName, sseAlgorithm=None, sseKey=None, copySourceSseAlgorithm=None, copySourceSseKey=None):
    s3 = boto3.resource('s3')
    dstBucket = s3.Bucket(oldstr(dstBucketName))
    dstObject = dstBucket.Object(oldstr(dstKeyName))
    copySource = {'Bucket': oldstr(srcBucketName), 'Key': oldstr(srcKeyName)}
    if srcKeyVersion is not None:
        copySource['VersionId'] = oldstr(srcKeyVersion)
    destEncryptionArgs = {}
    if sseKey is not None:
        destEncryptionArgs.update({'SSECustomerAlgorithm': sseAlgorithm, 'SSECustomerKey': sseKey})
    copyEncryptionArgs = {}
    if copySourceSseKey is not None:
        copyEncryptionArgs.update({'CopySourceSSECustomerAlgorithm': copySourceSseAlgorithm, 'CopySourceSSECustomerKey': copySourceSseKey})
    copyEncryptionArgs.update(destEncryptionArgs)
    dstObject.copy(copySource, ExtraArgs=copyEncryptionArgs)
    info = boto3.client('s3').head_object(Bucket=dstObject.bucket_name, Key=dstObject.key, **destEncryptionArgs)
    return info.get('VersionId', None)

def get_total_memory():
    if platform.system() != 'Linux':
        return None
    with open('/proc/meminfo', 'r') as in_file:
        for line in in_file:
            info = line.split()
            if info[0] == 'MemTotal:' and info[-1] == 'kB':
                memory_mb = int(int(info[1]) / 1024)
                return memory_mb
    return None

