def _get_modules_map(self, path=None):
    paths = {}
    root = ansible.modules.__path__[0]
    if not path:
        path = root
    for p_el in os.listdir(path):
        p_el_path = os.path.join(path, p_el)
        if os.path.islink(p_el_path):
            continue
        if os.path.isdir(p_el_path):
            paths.update(self._get_modules_map(p_el_path))
        else:
            if any((p_el.startswith(elm) for elm in ['__', '.'])) or not p_el.endswith('.py') or p_el in ansible.constants.IGNORE_FILES:
                continue
            p_el_path = p_el_path.replace(root, '').split('.')[0]
            als_name = p_el_path.replace('.', '').replace('/', '', 1).replace('/', '.')
            paths[als_name] = p_el_path
    return paths

def upload(self, filepath, service_path, remove=False):
    local = OSFS(os.path.dirname(filepath))
    if self.fs.hassyspath(service_path) and self.fs.getsyspath(service_path) == local.getsyspath(os.path.basename(filepath)):
        if remove:
            os.remove(filepath)
        return
    if not self.fs.isdir(fs.path.dirname(service_path)):
        self.fs.makedir(fs.path.dirname(service_path), recursive=True, allow_recreate=True)
    if remove:
        fs.utils.movefile(local, os.path.basename(filepath), self.fs, service_path)
    else:
        fs.utils.copyfile(local, os.path.basename(filepath), self.fs, service_path)

