def cmdline_generator(param_iter, PathToBin=None, PathToCmd=None, PathsToInputs=None, PathToOutput=None, PathToStderr='/dev/null', PathToStdout='/dev/null', UniqueOutputs=False, InputParam=None, OutputParam=None):
    if not PathsToInputs:
        raise ValueError('No input file(s) specified.')
    if not PathToOutput:
        raise ValueError('No output file specified.')
    if not isinstance(PathsToInputs, list):
        PathsToInputs = [PathsToInputs]
    if PathToBin is None:
        PathToBin = ''
    if PathToCmd is None:
        PathToCmd = ''
    if PathToStdout is None:
        stdout_ = ''
    else:
        stdout_ = '> "%s"' % PathToStdout
    if PathToStderr is None:
        stderr_ = ''
    else:
        stderr_ = '2> "%s"' % PathToStderr
    if OutputParam is None:
        output = '> "%s"' % PathToOutput
        stdout_ = ''
    else:
        output_param = param_iter.AppParams[OutputParam]
        output_param.on('"%s"' % PathToOutput)
        output = str(output_param)
        output_param.off()
    output_count = 0
    base_command = ' '.join([PathToBin, PathToCmd])
    for params in param_iter:
        for inputfile in PathsToInputs:
            cmdline = [base_command]
            cmdline.extend(sorted(filter(None, map(str, params.values()))))
            if InputParam is None:
                input = '< "%s"' % inputfile
            else:
                input_param = params[InputParam]
                input_param.on('"%s"' % inputfile)
                input = str(input_param)
                input_param.off()
            cmdline.append(input)
            if UniqueOutputs:
                cmdline.append(''.join([output, str(output_count)]))
                output_count += 1
            else:
                cmdline.append(output)
            cmdline.append(stdout_)
            cmdline.append(stderr_)
            yield ' '.join(cmdline)

def array(a, dtype: type=None, **kwargs) -> np.ndarray:
    if not isinstance(a, collections.Sized) and (not getattr(a, '__array_interface__', False)):
        a = list(a)
    if np.int_ == np.int32 and dtype is None and is_listy(a) and len(a) and isinstance(a[0], int):
        dtype = np.int64
    return np.array(a, dtype=dtype, **kwargs)

def send_message(self, body, to, quiet=False, html_body=None):
    if to.get('MUTED'):
        to['QUEUED_MESSAGES'].append(body)
    else:
        if not quiet:
            logger.info('message on %s to %s: %s' % (self.name, to['JID'], body))
        message = xmpp.protocol.Message(to=to['JID'], body=body, typ='chat')
        if html_body:
            html = xmpp.Node('html', {'xmlns': 'http://jabber.org/protocol/xhtml-im'})
            html.addChild(node=xmpp.simplexml.XML2Node("<body xmlns='http://www.w3.org/1999/xhtml'>" + html_body.encode('utf-8') + '</body>'))
            message.addChild(node=html)
        self.client.send(message)

def _check_log_scale(base, sides, scales, coord):

    def is_log(trans):
        return trans.__class__.__name__.startswith('log') and hasattr(trans, 'base')
    (base_x, base_y) = (base, base)
    x_is_log = is_log(scales.x.trans)
    y_is_log = is_log(scales.y.trans)
    if isinstance(coord, coord_flip):
        (x_is_log, y_is_log) = (y_is_log, x_is_log)
    if 't' in sides or 'b' in sides:
        if base_x is None:
            base_x = scales.x.trans.base
        if not x_is_log:
            warnings.warn('annotation_logticks for x-axis which does not have a log scale. The logticks may not make sense.', PlotnineWarning)
        elif x_is_log and base_x != scales.x.trans.base:
            warnings.warn('The x-axis is log transformed in base {} ,but the annotation_logticks are computed in base {}'.format(base_x, scales.x.trans.base), PlotnineWarning)
    if 'l' in sides or 'r' in sides:
        if base_y is None:
            base_y = scales.y.trans.base
        if not y_is_log:
            warnings.warn('annotation_logticks for y-axis which does not have a log scale. The logticks may not make sense.', PlotnineWarning)
        elif y_is_log and base_y != scales.x.trans.base:
            warnings.warn('The y-axis is log transformed in base {} ,but the annotation_logticks are computed in base {}'.format(base_y, scales.x.trans.base), PlotnineWarning)
    return (base_x, base_y)

