def lcopt_bw2_forwast_setup(use_autodownload=True, forwast_path=None, db_name=FORWAST_PROJECT_NAME, overwrite=False):
    if use_autodownload:
        forwast_filepath = forwast_autodownload(FORWAST_URL)
