def isChar(ev):
    text = ev.text()
    if len(text) != 1:
        return False
    if ev.modifiers() not in (Qt.ShiftModifier, Qt.KeypadModifier, Qt.NoModifier):
        return False
    asciiCode = ord(text)
    if asciiCode <= 31 or asciiCode == 127:
        return False
    if text == ' ' and ev.modifiers() == Qt.ShiftModifier:
        return False
    return True

