def spinn5_eth_coords(width, height, root_x=0, root_y=0):
    root_x %= 12
    root_x %= 12
    w = (width + 11) // 12 * 12
    h = (height + 11) // 12 * 12
    for x in range(0, w, 12):
        for y in range(0, h, 12):
            for (dx, dy) in ((0, 0), (4, 8), (8, 4)):
                nx = (x + dx + root_x) % w
                ny = (y + dy + root_y) % h
                if nx < width and ny < height:
                    yield (nx, ny)

