    toRemoveOutputFile = None
    try:
        toRemoveOutputFile = open(outPrefix + '.snp_to_remove', 'w')
    except IOError:
        msg = "%(outPrefix)s.snp_to_remove: can't write file" % locals()
        raise ProgramError(msg)
    toRemoveOutputFileExplanation = None
    try:
        toRemoveOutputFileExplanation = open(outPrefix + '.snp_to_remove.explanation', 'w')
        (print >> toRemoveOutputFileExplanation, '\t'.join(['Name', 'Reason', 'Alleles 1', 'Alleles 2']))
    except IOError:
        msg = "%(outPrefix)s.snp_to_remove: can't write file" % locals()
        raise ProgramError(msg)
    for snpName in goldAlleles.iterkeys():
        alleles1 = goldAlleles[snpName]
        alleles2 = sourceAlleles[snpName]
        if len(alleles1) == 2 and len(alleles2) == 2:
            if {'A', 'T'} == alleles1 and {'A', 'T'} == alleles2 or ({'C', 'G'} == alleles1 and {'C', 'G'} == alleles2):
                (print >> toRemoveOutputFile, snpName)
                (print >> toRemoveOutputFileExplanation, '\t'.join([snpName, 'Undetermined', ''.join(alleles1), ''.join(alleles2)]))
            elif alleles1 != alleles2:
                if flipGenotype(alleles1) == alleles2:
                    (print >> toFlipOutputFile, snpName)
                else:
                    (print >> toRemoveOutputFile, snpName)
                    (print >> toRemoveOutputFileExplanation, '\t'.join([snpName, 'Invalid', ''.join(alleles1), ''.join(alleles2)]))
        else:
            (print >> toRemoveOutputFile, snpName)
            tmp_allele1 = ''.join(alleles1)
