        self.push(self.inventory, region, dest)
        if self.nested_groups:
            self.push_group(self.inventory, 'regions', region)
    if self.group_by_availability_zone:
        self.push(self.inventory, instance.availability_zone, dest)
        if self.nested_groups:
            if self.group_by_region:
                self.push_group(self.inventory, region, instance.availability_zone)
            self.push_group(self.inventory, 'zones', instance.availability_zone)
    if self.group_by_instance_type:
        type_name = self.to_safe('type_' + instance.instance_class)
        self.push(self.inventory, type_name, dest)
        if self.nested_groups:
            self.push_group(self.inventory, 'types', type_name)
    if self.group_by_vpc_id and instance.subnet_group and instance.subnet_group.vpc_id:
        vpc_id_name = self.to_safe('vpc_id_' + instance.subnet_group.vpc_id)
        self.push(self.inventory, vpc_id_name, dest)
        if self.nested_groups:
            self.push_group(self.inventory, 'vpcs', vpc_id_name)
    if self.group_by_security_group:
        try:
            if instance.security_group:
                key = self.to_safe('security_group_' + instance.security_group.name)
                self.push(self.inventory, key, dest)
                if self.nested_groups:
                    self.push_group(self.inventory, 'security_groups', key)
        except AttributeError:
            self.fail_with_error('\n'.join(['Package boto seems a bit older.', 'Please upgrade boto >= 2.3.0.']))
    if self.group_by_rds_engine:
        self.push(self.inventory, self.to_safe('rds_' + instance.engine), dest)
        if self.nested_groups:
            self.push_group(self.inventory, 'rds_engines', self.to_safe('rds_' + instance.engine))
    if self.group_by_rds_parameter_group:
        self.push(self.inventory, self.to_safe('rds_parameter_group_' + instance.parameter_group.name), dest)
        if self.nested_groups:
            self.push_group(self.inventory, 'rds_parameter_groups', self.to_safe('rds_parameter_group_' + instance.parameter_group.name))
    self.push(self.inventory, 'rds', dest)
    self.inventory['_meta']['hostvars'][dest] = self.get_host_info_dict_from_instance(instance)

def dropna(self, axis=0, how='any', inplace=False):
    axis = self._get_axis_number(axis)
    values = self.values
    mask = notna(values)
    for ax in reversed(sorted(set(range(self._AXIS_LEN)) - {axis})):
        mask = mask.sum(ax)
    per_slice = np.prod(values.shape[:axis] + values.shape[axis + 1:])
    if how == 'all':
        cond = mask > 0
    else:
        cond = mask == per_slice
    new_ax = self._get_axis(axis)[cond]
    result = self.reindex_axis(new_ax, axis=axis)
    if inplace:
        self._update_inplace(result)
    else:
        return result

def set_state(self, state):
    if state == self._state:
        return
    elif state not in self._STATES.keys():
        raise ValueError('Invalid state {}'.format(state))
    if self.is_waiting_to_stop and state not in [self.STATE_STOPPING, self.STATE_STOPPED]:
        LOGGER.warning('Attempt to set invalid state while waiting to shutdown: %s ', self._STATES[state])
        return
    elif self.is_stopping and state != self.STATE_STOPPED:
        LOGGER.warning('Attempt to set invalid post shutdown state: %s', self._STATES[state])
        return
    elif self.is_running and state not in [self.STATE_ACTIVE, self.STATE_IDLE, self.STATE_SLEEPING, self.STATE_STOP_REQUESTED, self.STATE_STOPPING]:
        LOGGER.warning('Attempt to set invalid post running state: %s', self._STATES[state])
        return
    elif self.is_sleeping and state not in [self.STATE_ACTIVE, self.STATE_IDLE, self.STATE_STOP_REQUESTED, self.STATE_STOPPING]:
        LOGGER.warning('Attempt to set invalid post sleeping state: %s', self._STATES[state])
        return
    LOGGER.debug('State changed from %s to %s', self._STATES[self._state], self._STATES[state])
    self._state = state

def set_logging_level(args):
    root_logger = logging.getLogger()
    level = logging.INFO
    logging.getLogger('requests.packages.urllib3').setLevel(logging.WARNING)
    if 'verbose' in args and args.verbose is not None:
        logging.getLogger('requests.packages.urllib3').setLevel(0)
        if args.verbose > 1:
            level = 5
        elif args.verbose > 0:
            level = logging.DEBUG
        else:
            logging.critical('verbose is an unexpected value. (%s) exiting.', args.verbose)
            sys.exit(2)
    elif 'quiet' in args and args.quiet is not None:
        if args.quiet > 1:
            level = logging.ERROR
        elif args.quiet > 0:
            level = logging.WARNING
        else:
            logging.critical('quiet is an unexpected value. (%s) exiting.', args.quiet)
    if level is not None:
        root_logger.setLevel(level)
    if args.silence_urllib3:
        requests.packages.urllib3.disable_warnings()

