def absent(name, purge=False, force=False):
    ret = {'name': name, 'changes': {}, 'result': True, 'comment': ''}
    lusr = __salt__['user.info'](name)
    if lusr:
        if __opts__['test']:
            ret['result'] = None
            ret['comment'] = 'User {0} set for removal'.format(name)
            return ret
        beforegroups = set(salt.utils.user.get_group_list(name))
        ret['result'] = __salt__['user.delete'](name, purge, force)
        aftergroups = set([g for g in beforegroups if __salt__['group.info'](g)])
        if ret['result']:
            ret['changes'] = {}
            for g in beforegroups - aftergroups:
                ret['changes']['{0} group'.format(g)] = 'removed'
            ret['changes'][name] = 'removed'
            ret['comment'] = 'Removed user {0}'.format(name)
        else:
            ret['result'] = False
            ret['comment'] = 'Failed to remove user {0}'.format(name)
        return ret
    ret['comment'] = 'User {0} is not present'.format(name)
    return ret

def status_bar(python_input):
    TB = 'class:status-toolbar'

    @if_mousedown
    def toggle_paste_mode(mouse_event):
        python_input.paste_mode = not python_input.paste_mode

    @if_mousedown
    def enter_history(mouse_event):
        python_input.enter_history()

    def get_text_fragments():
        python_buffer = python_input.default_buffer
        result = []
        append = result.append
        append((TB, ' '))
        result.extend(get_inputmode_fragments(python_input))
        append((TB, ' '))
        append((TB, '%i/%i ' % (python_buffer.working_index + 1, len(python_buffer._working_lines))))
        app = get_app()
        if not python_input.vi_mode and app.current_buffer == python_input.search_buffer:
            append((TB, '[Ctrl-G] Cancel search [Enter] Go to this position.'))
        elif bool(app.current_buffer.selection_state) and (not python_input.vi_mode):
            append((TB, '[Ctrl-W] Cut [Meta-W] Copy [Ctrl-Y] Paste [Ctrl-G] Cancel'))
        else:
            result.extend([(TB + ' class:key', '[F3]', enter_history), (TB, ' History ', enter_history), (TB + ' class:key', '[F6]', toggle_paste_mode), (TB, ' ', toggle_paste_mode)])
