                append((TB + ' class:paste-mode-on', 'Paste mode (on)', toggle_paste_mode))
            else:
                append((TB, 'Paste mode', toggle_paste_mode))
        return result
    return ConditionalContainer(content=Window(content=FormattedTextControl(get_text_fragments), style=TB), filter=~is_done & renderer_height_is_known & Condition(lambda : python_input.show_status_bar and (not python_input.show_exit_confirmation)))

