def _parse_tree_dump(text_dump):
    result = None
    stack = []
    for line in text_dump.split('\n'):
        if line:
            (depth, node) = _parse_dump_line(line)
            if depth == 0:
                assert not stack
                result = node
                stack.append(node)
            elif depth > len(stack):
                raise ValueError('Unexpected dump structure')
            else:
                if depth < len(stack):
                    stack = stack[:depth]
                stack[-1].setdefault('children', []).append(node)
                stack.append(node)
    return result

