def match_tree(sentence, pattern):
    if not verify_pattern(pattern):
        raise PatternSyntaxException(pattern)

    def _match_node(t, p):
        pat_node = p.pop(0) if p else ''
        return not pat_node or (_match_token(t, pat_node, False) and _match_edge(t.children, p))

    def _match_edge(edges, p):
        pat_edge = p.pop(0) if p else ''
        if not pat_edge:
            return True
        elif not edges:
            return False
        else:
            for t in edges:
                if _match_token(t, pat_edge, True) and _match_node(t, list(p)):
                    return True
                elif pat_edge == '**' and _match_edge(t.children, ['**'] + p):
                    return True
        return False
    return _match_node(sentence.root, pattern.split('/'))

def _features_without_strokes(self, hwr_obj):
    x = []
    for point in hwr_obj.get_pointlist()[0]:
        if len(x) >= 3 * self.points_per_stroke or (len(x) >= 2 * self.points_per_stroke and (not self.pen_down)):
            break
        x.append(point['x'])
        x.append(point['y'])
        if self.pen_down:
            if 'pen_down' not in point:
                logging.error('The ConstantPointCoordinates(strokes=0) feature should only be used after SpaceEvenly preprocessing step.')
            else:
                x.append(int(point['pen_down']))
    if self.pen_down:
        while len(x) != 3 * self.points_per_stroke:
            x.append(self.fill_empty_with)
    else:
        while len(x) != 2 * self.points_per_stroke:
            x.append(self.fill_empty_with)
    return x

def _update_states(self, final_states: RnnStateStorage, restoration_indices: torch.LongTensor) -> None:
    new_unsorted_states = [state.index_select(1, restoration_indices) for state in final_states]
    if self._states is None:
        self._states = tuple((state.data for state in new_unsorted_states))
    else:
        current_state_batch_size = self._states[0].size(1)
        new_state_batch_size = final_states[0].size(1)
        used_new_rows_mask = [(state[0, :, :].sum(-1) != 0.0).float().view(1, new_state_batch_size, 1) for state in new_unsorted_states]
        new_states = []
        if current_state_batch_size > new_state_batch_size:
            for (old_state, new_state, used_mask) in zip(self._states, new_unsorted_states, used_new_rows_mask):
                masked_old_state = old_state[:, :new_state_batch_size, :] * (1 - used_mask)
                old_state[:, :new_state_batch_size, :] = new_state + masked_old_state
                new_states.append(old_state.detach())
        else:
            new_states = []
            for (old_state, new_state, used_mask) in zip(self._states, new_unsorted_states, used_new_rows_mask):
                masked_old_state = old_state * (1 - used_mask)
                new_state += masked_old_state
                new_states.append(new_state.detach())
        self._states = tuple(new_states)

def list_input_endpoints(kwargs=None, conn=None, call=None):
    if call != 'function':
        raise SaltCloudSystemExit('The list_input_endpoints function must be called with -f or --function.')
    if kwargs is None:
        kwargs = {}
    if 'service' not in kwargs:
        raise SaltCloudSystemExit('A service name must be specified as "service"')
    if 'deployment' not in kwargs:
        raise SaltCloudSystemExit('A deployment name must be specified as "deployment"')
    path = 'services/hostedservices/{0}/deployments/{1}'.format(kwargs['service'], kwargs['deployment'])
    data = query(path)
    if data is None:
        raise SaltCloudSystemExit('There was an error listing endpoints with the {0} service on the {1} deployment.'.format(kwargs['service'], kwargs['deployment']))
    ret = {}
    for item in data:
        if 'Role' in item:
            role = item['Role']
            if not isinstance(role, dict):
                return ret
            input_endpoint = role['ConfigurationSets']['ConfigurationSet'].get('InputEndpoints', {}).get('InputEndpoint')
            if not input_endpoint:
                continue
            if not isinstance(input_endpoint, list):
                input_endpoint = [input_endpoint]
            for endpoint in input_endpoint:
                ret[endpoint['Name']] = endpoint
            return ret
    return ret

