def sample(net: BayesNet, sample_from: Iterable[Vertex], sampling_algorithm: PosteriorSamplingAlgorithm=None, draws: int=500, drop: int=0, down_sample_interval: int=1, plot: bool=False, ax: Any=None) -> sample_types:
    sample_from = list(sample_from)
    id_to_label = __check_if_vertices_are_labelled(sample_from)
    if sampling_algorithm is None:
        sampling_algorithm = MetropolisHastingsSampler(proposal_distribution='prior', latents=sample_from)
    vertices_unwrapped: JavaList = k.to_java_object_list(sample_from)
    probabilistic_model = ProbabilisticModel(net) if isinstance(sampling_algorithm, MetropolisHastingsSampler) or isinstance(sampling_algorithm, ForwardSampler) else ProbabilisticModelWithGradient(net)
    network_samples: JavaObject = sampling_algorithm.get_sampler().getPosteriorSamples(probabilistic_model.unwrap(), vertices_unwrapped, draws).drop(drop).downSample(down_sample_interval)
    if __all_scalar(sample_from):
        vertex_samples = __create_single_indexed_samples(network_samples, vertices_unwrapped, id_to_label)
    else:
        vertex_samples = __create_multi_indexed_samples(vertices_unwrapped, network_samples, id_to_label)
    if plot:
        traceplot(vertex_samples, ax=ax)
    return vertex_samples

