def escape(url):
    if salt.utils.platform.is_windows():
        return url
    scheme = urlparse(url).scheme
    if not scheme:
        if url.startswith('|'):
            return url
        else:
            return '|{0}'.format(url)
    elif scheme == 'salt':
        (path, saltenv) = parse(url)
        if path.startswith('|'):
            return create(path, saltenv)
        else:
            return create('|{0}'.format(path), saltenv)
    else:
        return url

def upgrade(bin_env=None, user=None, cwd=None, use_vt=False):
    ret = {'changes': {}, 'result': True, 'comment': ''}
    cmd = _get_pip_bin(bin_env)
    cmd.extend(['install', '-U'])
    old = list_(bin_env=bin_env, user=user, cwd=cwd)
    cmd_kwargs = dict(cwd=cwd, use_vt=use_vt)
    if bin_env and os.path.isdir(bin_env):
        cmd_kwargs['env'] = {'VIRTUAL_ENV': bin_env}
    errors = False
    for pkg in list_upgrades(bin_env=bin_env, user=user, cwd=cwd):
        if pkg == 'salt':
            if salt.utils.platform.is_windows():
                continue
        result = __salt__['cmd.run_all'](cmd + [pkg], **cmd_kwargs)
        if result['retcode'] != 0:
            errors = True
        if 'stderr' in result:
            ret['comment'] += result['stderr']
    if errors:
        ret['result'] = False
    _clear_context(bin_env)
    new = list_(bin_env=bin_env, user=user, cwd=cwd)
    ret['changes'] = salt.utils.data.compare_dicts(old, new)
    return ret

def sort_and_distribute(array, splits=2):
    if not isinstance(array, (list, tuple)):
        raise TypeError('array must be a list')
    if not isinstance(splits, int):
        raise TypeError('splits must be an integer')
    remaining = sorted(array)
    if sys.version_info < (3, 0):
        myrange = xrange(splits)
    else:
        myrange = range(splits)
    groups = [[] for i in myrange]
    while len(remaining) > 0:
        for i in myrange:
            if len(remaining) > 0:
                groups[i].append(remaining.pop(0))
    return groups

