def _correct_dims(data):
    if not hasattr(data, 'dims'):
        raise TypeError("Data must have a 'dims' attribute.")
    data = data.copy()
    if 'y' not in data.dims or 'x' not in data.dims:
        if data.ndim != 2:
            raise ValueError("Data must have a 'y' and 'x' dimension")
        if 'y' not in data.dims:
            old_dim = [d for d in data.dims if d != 'x'][0]
            data = data.rename({old_dim: 'y'})
        if 'x' not in data.dims:
            old_dim = [d for d in data.dims if d != 'y'][0]
            data = data.rename({old_dim: 'x'})
    if 'bands' not in data.dims:
        if data.ndim <= 2:
            data = data.expand_dims('bands')
            data['bands'] = ['L']
        else:
            raise ValueError("No 'bands' dimension provided.")
    return data

def get_thumbnailer(obj, relative_name=None):
    if hasattr(obj, 'easy_thumbnails_thumbnailer'):
        return obj.easy_thumbnails_thumbnailer
    if isinstance(obj, Thumbnailer):
        return obj
    elif isinstance(obj, FieldFile):
        if not relative_name:
            relative_name = obj.name
        return ThumbnailerFieldFile(obj.instance, obj.field, relative_name)
    source_storage = None
    if isinstance(obj, six.string_types):
        relative_name = obj
        obj = None
    if not relative_name:
        raise ValueError('If object is not a FieldFile or Thumbnailer instance, the relative name must be provided')
    if isinstance(obj, File):
        obj = obj.file
    if isinstance(obj, Storage) or obj == default_storage:
        source_storage = obj
        obj = None
    return Thumbnailer(file=obj, name=relative_name, source_storage=source_storage, remote_source=obj is not None)

def generateZipFile(self, outpath='.'):
    fname = self.installName() + '.zip'
    outfile = os.path.abspath(os.path.join(outpath, fname))
    if os.path.exists(outfile):
        try:
            os.remove(outfile)
        except OSError:
            log.warning('Could not remove zipfile: %s', outfile)
            return False
    zfile = zipfile.ZipFile(outfile, 'w')
    if os.path.isfile(self.sourcePath()):
        zfile.write(self.sourcePath(), os.path.basename(self.sourcePath()))
    else:
        basepath = os.path.abspath(os.path.join(self.sourcePath(), '..'))
        baselen = len(basepath) + 1
        for (root, folders, filenames) in os.walk(basepath):
            if '.svn' in root or '.git' in root:
                continue
            part = root[baselen:].split(os.path.sep)[0]
            if part in ('build', 'dist') or part.endswith('.egg-info'):
                continue
            for filename in filenames:
                ext = os.path.splitext(filename)[1]
                if ext in self.ignoreFileTypes():
                    continue
                arcroot = root[baselen:].replace('\\', '/')
                arcname = os.path.join(arcroot, filename)
                log.info('Archiving %s...', arcname)
                zfile.write(os.path.join(root, filename), arcname)
    zfile.close()
    return True

