def get_string(self, offset=0):
    if not self.has_space(offset=offset):
        return ''
    string = self.string
    pos = self.pos + offset
    for (i, char) in enumerate(string[pos:]):
        if char.isspace():
            return string[pos:pos + i]
    else:
        return string[pos:]

