def _par_read(dirname, compressed=True):
    templates = []
    if compressed:
        arc = tarfile.open(dirname, 'r:*')
        members = arc.getmembers()
        _parfile = [member for member in members if member.name.split(os.sep)[-1] == 'template_parameters.csv']
        if len(_parfile) == 0:
            arc.close()
            raise MatchFilterError('No template parameter file in archive')
        parfile = arc.extractfile(_parfile[0])
    else:
        parfile = open(dirname + '/' + 'template_parameters.csv', 'r')
    for line in parfile:
        t_in = Template()
        for key_pair in line.rstrip().split(','):
            if key_pair.split(':')[0].strip() == 'name':
                t_in.__dict__[key_pair.split(':')[0].strip()] = key_pair.split(':')[-1].strip()
            elif key_pair.split(':')[0].strip() == 'filt_order':
                try:
                    t_in.__dict__[key_pair.split(':')[0].strip()] = int(key_pair.split(':')[-1])
                except ValueError:
                    pass
            else:
                try:
                    t_in.__dict__[key_pair.split(':')[0].strip()] = float(key_pair.split(':')[-1])
                except ValueError:
                    pass
        templates.append(t_in)
    parfile.close()
    if compressed:
        arc.close()
    return templates

def align_options(options):
    l = 0
    for opt in options:
        if len(opt[0]) > l:
            l = len(opt[0])
    s = []
    for opt in options:
        s.append('  {0}{1}  {2}'.format(opt[0], ' ' * (l - len(opt[0])), opt[1]))
    return '\n'.join(s)

def make_plot(fnames=[], name=[], dims=None, plot_method=None, output=None, project=None, engine=None, formatoptions=None, tight=False, rc_file=None, encoding=None, enable_post=False, seaborn_style=None, output_project=None, concat_dim=get_default_value(xr.open_mfdataset, 'concat_dim'), chname={}):
    if project is not None and (name != [] or dims is not None):
        warn('The `name` and `dims` parameter are ignored if the `project` parameter is set!')
    if rc_file is not None:
        rcParams.load_from_file(rc_file)
    if dims is not None and (not isinstance(dims, dict)):
        dims = dict(chain(*map(six.iteritems, dims)))
    if len(output) == 1:
        output = output[0]
    if not fnames and (not project):
        raise ValueError('Either a filename or a project file must be provided if the output parameter is set!')
    elif project is None and plot_method is None:
        raise ValueError('A plotting method must be provided if the output parameter is set and not the project!')
    if seaborn_style is not None:
        import seaborn as sns
        sns.set_style(seaborn_style)
    import psyplot.project as psy
    if project is not None:
        fnames = [s.split(',') for s in fnames]
        chname = dict(chname)
        single_files = (l[0] for l in fnames if len(l) == 1)
        alternative_paths = defaultdict(lambda : next(single_files, None))
        alternative_paths.update([l for l in fnames if len(l) == 2])
        p = psy.Project.load_project(project, alternative_paths=alternative_paths, engine=engine, encoding=encoding, enable_post=enable_post, chname=chname)
        if formatoptions is not None:
            p.update(fmt=formatoptions)
        p.export(output, tight=tight)
    else:
        pm = getattr(psy.plot, plot_method, None)
        if pm is None:
            raise ValueError('Unknown plot method %s!' % plot_method)
        kwargs = {'name': name} if name else {}
        p = pm(fnames, dims=dims or {}, engine=engine, fmt=formatoptions or {}, mf_mode=True, concat_dim=concat_dim, **kwargs)
        p.export(output, tight=tight)
    if output_project is not None:
        p.save_project(output_project)
    return

