def grab(self, monitor):
    if isinstance(monitor, tuple):
        monitor = {'left': monitor[0], 'top': monitor[1], 'width': monitor[2] - monitor[0], 'height': monitor[3] - monitor[1]}
    (srcdc, memdc) = (MSS.srcdc, MSS.memdc)
    (width, height) = (monitor['width'], monitor['height'])
    if (self._bbox['height'], self._bbox['width']) != (height, width):
        self._bbox = monitor
        self._bmi.bmiHeader.biWidth = width
        self._bmi.bmiHeader.biHeight = -height
        self._data = ctypes.create_string_buffer(width * height * 4)
        if MSS.bmp:
            self.gdi32.DeleteObject(MSS.bmp)
        MSS.bmp = self.gdi32.CreateCompatibleBitmap(srcdc, width, height)
        self.gdi32.SelectObject(memdc, MSS.bmp)
    self.gdi32.BitBlt(memdc, 0, 0, width, height, srcdc, monitor['left'], monitor['top'], SRCCOPY | CAPTUREBLT)
    bits = self.gdi32.GetDIBits(memdc, MSS.bmp, 0, height, self._data, self._bmi, DIB_RGB_COLORS)
    if bits != height:
        raise ScreenShotError('gdi32.GetDIBits() failed.')
    return self.cls_image(bytearray(self._data), monitor)

def _handle_enum(self, node, scope, ctxt, stream):
    self._dlog('handling enum')
    if node.type is None:
        enum_cls = fields.Int
    else:
        enum_cls = self._handle_node(node.type, scope, ctxt, stream)
    enum_vals = {}
    curr_val = enum_cls()
    curr_val._pfp__value = -1
    for enumerator in node.values.enumerators:
        if enumerator.value is not None:
            curr_val = self._handle_node(enumerator.value, scope, ctxt, stream)
        else:
            curr_val = curr_val + 1
        curr_val._pfp__freeze()
        enum_vals[enumerator.name] = curr_val
        enum_vals[fields.PYVAL(curr_val)] = enumerator.name
        scope.add_local(enumerator.name, curr_val)
    if node.name is not None:
        enum_cls = EnumDef(node.name, enum_cls, enum_vals)
        scope.add_type_class(node.name, enum_cls)
    else:
        enum_cls = EnumDef('enum_' + enum_cls.__name__, enum_cls, enum_vals)
    return enum_cls

