    if len(required) > 0:
        required_named = parser.add_argument_group('required named arguments')
    for arg in args:
        try:
            argdata = copy.deepcopy(argument_data[arg])
        except KeyError:
            print("Skipping undefined pypiper argument: '{}'".format(arg))
            continue
        if isinstance(argdata, dict):
            short_opt = None
        else:
            try:
                (short_opt, argdata) = argdata
            except ValueError:
                raise TypeError('Option name must map to dict or two-tuple (short name and dict) of argument command-line argument specification data.')
        argdata['required'] = arg in required
        long_opt = '--{}'.format(arg)
        opts = (short_opt, long_opt) if short_opt else (long_opt,)
        if arg in required:
            required_named.add_argument(*opts, **argdata)
        else:
            parser.add_argument(*opts, **argdata)
    return parser

def decorate_with_validators(func, func_signature=None, **validators):
    for (arg_name, validator) in validators.items():
        if not isinstance(validator, list):
            validators[arg_name] = [validator]
    if hasattr(func, '__wrapped__') and hasattr(func.__wrapped__, '__validators__'):
        for (arg_name, validator) in validators.items():
            for v in validator:
                if arg_name in func.__wrapped__.__validators__:
                    func.__wrapped__.__validators__[arg_name].append(v)
                else:
                    func.__wrapped__.__validators__[arg_name] = [v]
        return func
    else:
        if hasattr(func, '__validators__'):
            raise ValueError('Function ' + str(func) + ' already has a defined __validators__ attribute, valid8 decorators can not be applied on it')
        else:
            try:
                func.__validators__ = validators
            except AttributeError:
                raise ValueError("Error - Could not add validators list to function '%s'" % func)
        func_signature = func_signature or signature(func)

        @wraps(func)
        def validating_wrapper(*args, **kwargs):
            apply_on_each_func_args_sig(func, args, kwargs, func_signature, func_to_apply=_assert_input_is_valid, func_to_apply_params_dict=func.__validators__)
            res = func(*args, **kwargs)
            if _OUT_KEY in func.__validators__:
                for validator in func.__validators__[_OUT_KEY]:
                    validator.assert_valid(res)
            return res
        return validating_wrapper

