def query_mongo(database_name, collection_name, query={}, include_num_results='0', skip=0, sort=None, limit=getattr(settings, 'MONGO_LIMIT', 200), cast_strings_to_integers=False, return_keys=()):
    l = []
    response_dict = {}
    try:
        mongodb_client_url = getattr(settings, 'MONGODB_CLIENT', 'mongodb://localhost:27017/')
        mc = MongoClient(mongodb_client_url, document_class=OrderedDict)
        db = mc[str(database_name)]
        collection = db[str(collection_name)]
        if cast_strings_to_integers:
            query = cast_number_strings_to_integers(query)
        if return_keys:
            return_dict = {}
            for k in return_keys:
                return_dict[k] = 1
            mysearchresult = collection.find(query, return_dict).skip(skip).limit(limit)
        else:
            mysearchresult = collection.find(query).skip(skip).limit(limit)
        if sort:
            mysearchresult.sort(sort)
        response_dict['code'] = 200
        if include_num_results == '1':
            response_dict['num_results'] = response_dict['num_results'] = int(mysearchresult.count(with_limit_and_skip=False))
        if include_num_results == '2':
            response_dict['num_results'] = response_dict['num_results'] = int(mysearchresult.count(with_limit_and_skip=True))
        response_dict['type'] = 'search-results'
        for d in mysearchresult:
            d['id'] = d['_id'].__str__()
            del d['_id']
            l.append(d)
        response_dict['results'] = l
    except:
        print('Error reading from Mongo')
        print(str(sys.exc_info()))
        response_dict['num_results'] = 0
        response_dict['code'] = 500
        response_dict['type'] = 'Error'
        response_dict['results'] = []
        response_dict['message'] = str(sys.exc_info())
    return response_dict

