def _mean_var(vals, pmf):
    mean = np.sum(vals * pmf)
    var = np.sum(vals ** 2 * pmf) - mean ** 2
    return (mean, var)

def __continued_query(self, query_params):
    query_params.update(self.__title_query_param)
    last_continue = {}
    prop = query_params.get('prop', None)
    while True:
        params = query_params.copy()
        params.update(last_continue)
        request = _wiki_request(params)
        if 'query' not in request:
            break
        pages = request['query']['pages']
        if 'generator' in query_params:
            for datum in pages.values():
                yield datum
        else:
            for datum in pages[self.pageid][prop]:
                yield datum
        if 'continue' not in request:
            break
        last_continue = request['continue']

def tokenize_akkadian_signs(word):
    word_signs = []
    sign = ''
    language = word[1]
    determinative = False
    for char in word[0]:
        if determinative is True:
            if char == '}':
                determinative = False
                if len(sign) > 0:
                    word_signs.append((sign, 'determinative'))
                sign = ''
                language = word[1]
                continue
            else:
                sign += char
                continue
        elif language == 'akkadian':
            if char == '{':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                determinative = True
                continue
            elif char == '_':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                language = 'sumerian'
                continue
            elif char == '-':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                language = word[1]
                continue
            else:
                sign += char
        elif language == 'sumerian':
            if char == '{':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                determinative = True
                continue
            elif char == '_':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                language = word[1]
                continue
            elif char == '-':
                if len(sign) > 0:
                    word_signs.append((sign, language))
                sign = ''
                language = word[1]
                continue
            else:
                sign += char
    if len(sign) > 0:
        word_signs.append((sign, language))
    return word_signs

def ticks(cls, request, length: (Ptypes.path, Integer('Duration of the stream, in seconds.')), style: (Ptypes.path, String('Tick style.', enum=['compact', 'extended']))) -> [(200, 'Ok', TickStream), (400, 'Invalid parameters')]:
    try:
        length = int(length)
        style = cls._styles[style]
    except (ValueError, KeyError):
        Respond(400)

    def vetinari_clock():
        start = time()
        while time() - start <= length:
            sleep(randint(25, 400) / 100)
            yield strftime(style, localtime())
    Respond(200, vetinari_clock())

