def get_bibtex(self):
    if self.aggregationType != 'Journal':
        raise ValueError('Only Journal articles supported.')
    year = self.coverDate[0:4]
    first = self.title.split()[0].title()
    last = self.title.split()[-1].title()
    key = ''.join([self.authors[0].surname, year, first, last])
    authors = ' and '.join(['{} {}'.format(a.given_name, a.surname) for a in self.authors])
    if self.pageRange:
        pages = self.pageRange
    elif self.startingPage:
        pages = '{}-{}'.format(self.startingPage, self.endingPage)
    else:
        pages = '-'
    bib = '@article{{{key},\n  author = {{{auth}}},\n  title = {{{{{title}}}}},\n  journal = {{{jour}}},\n  year = {{{year}}},\n  volume = {{{vol}}},\n  number = {{{number}}},\n  pages = {{{pages}}}'.format(key=key, auth=authors, title=self.title, year=year, jour=self.publicationName, vol=self.volume, number=self.issueIdentifier, pages=pages)
    if self.doi:
        bib += ',\n  doi = {{{}}}'.format(self.doi)
    bib += '}'
    return bib

def deserialize_transactions(self, transactions=None, deserialize_only=None):
    if not self.allow_self and transactions.filter(producer=socket.gethostname()).exists():
        raise TransactionDeserializerError(f'Not deserializing own transactions. Got allow_self=False, hostname={socket.gethostname()}')
    for transaction in transactions:
        json_text = self.aes_decrypt(cipher_text=transaction.tx)
        json_text = self.custom_parser(json_text)
        deserialized = next(self.deserialize(json_text=json_text))
        if not deserialize_only:
            if transaction.action == DELETE:
                deserialized.object.delete()
            else:
                self.save(obj=deserialized.object, m2m_data=deserialized.m2m_data)
            transaction.is_consumed = True
            transaction.save()

