def update(self, data):
    for character in data:
        if PY3:
            ch = character
        else:
            ch = ord(character)
        self.count += 1
        if self.lastch[1] > -1:
            self.acc[self.tran3(ch, self.lastch[0], self.lastch[1], 0)] += 1
        if self.lastch[2] > -1:
            self.acc[self.tran3(ch, self.lastch[0], self.lastch[2], 1)] += 1
            self.acc[self.tran3(ch, self.lastch[1], self.lastch[2], 2)] += 1
        if self.lastch[3] > -1:
            self.acc[self.tran3(ch, self.lastch[0], self.lastch[3], 3)] += 1
            self.acc[self.tran3(ch, self.lastch[1], self.lastch[3], 4)] += 1
            self.acc[self.tran3(ch, self.lastch[2], self.lastch[3], 5)] += 1
            self.acc[self.tran3(self.lastch[3], self.lastch[0], ch, 6)] += 1
            self.acc[self.tran3(self.lastch[3], self.lastch[2], ch, 7)] += 1
        self.lastch = [ch] + self.lastch[:3]

def mp_iuwt_decomposition(in1, scale_count, scale_adjust, store_smoothed, core_count):
    wavelet_filter = 1.0 / 16 * np.array([1, 4, 6, 4, 1])
    C0 = in1
    detail_coeffs = np.empty([scale_count - scale_adjust, in1.shape[0], in1.shape[1]])
    if scale_adjust > 0:
        for i in range(0, scale_adjust):
            C0 = mp_a_trous(C0, wavelet_filter, i, core_count)
    for i in range(scale_adjust, scale_count):
        C = mp_a_trous(C0, wavelet_filter, i, core_count)
        C1 = mp_a_trous(C, wavelet_filter, i, core_count)
        detail_coeffs[i - scale_adjust, :, :] = C0 - C1
        C0 = C
    if store_smoothed:
        return (detail_coeffs, C0)
    else:
        return detail_coeffs

