def commuting_sets_by_indices(pauli_sums, commutation_check):
    assert isinstance(pauli_sums, list)
    group_inds = []
    group_terms = []
    for (i, pauli_sum) in enumerate(pauli_sums):
        for (j, term) in enumerate(pauli_sum):
            if len(group_inds) == 0:
                group_inds.append([(i, j)])
                group_terms.append([term])
                continue
            for (k, group) in enumerate(group_terms):
                if commutation_check(group, term):
                    group_inds[k] += [(i, j)]
                    group_terms[k] += [term]
                    break
            else:
                group_inds.append([(i, j)])
                group_terms.append([term])
    return group_inds

def do_check(vext_files):
    import vext
    all_specs = set(vext.gatekeeper.spec_files_flat())
    if vext_files == ['*']:
        vext_files = all_specs
    unknown_specs = set(vext_files) - all_specs
    for fn in unknown_specs:
        print('%s is not an installed vext file.' % fn, file=sys.stderr)
    if unknown_specs:
        return False
    check_passed = True
    for fn in [join(vext.gatekeeper.spec_dir(), fn) for fn in vext_files]:
        f = open_spec(open(fn))
        modules = f.get('test_import', [])
        for (success, module) in vext.gatekeeper.test_imports(modules):
            if not success:
                check_passed = False
            line = 'import %s: %s' % (module, '[success]' if success else '[failed]')
            print(line)
        print('')
    return check_passed

