def adjust_debt(self, delta, new_collateral_ratio=None, account=None, target_collateral_ratio=None):
    if not account:
        if 'default_account' in self.blockchain.config:
            account = self.blockchain.config['default_account']
    if not account:
        raise ValueError('You need to provide an account')
    account = Account(account, full=True, blockchain_instance=self.blockchain)
    symbol = delta['symbol']
    asset = Asset(symbol, full=True, blockchain_instance=self.blockchain)
    if not asset.is_bitasset:
        raise ValueError('%s is not a bitasset!' % symbol)
    bitasset = asset['bitasset_data']
    backing_asset_id = bitasset['options']['short_backing_asset']
    current_debts = self.list_debt_positions(account)
    if not new_collateral_ratio and symbol not in current_debts:
        new_collateral_ratio = bitasset['current_feed']['maintenance_collateral_ratio'] / 1000
    elif not new_collateral_ratio and symbol in current_debts:
        new_collateral_ratio = current_debts[symbol]['ratio']
    collateral_asset = Asset(backing_asset_id, blockchain_instance=self.blockchain)
    settlement_price = Price(bitasset['current_feed']['settlement_price'], blockchain_instance=self.blockchain)
    if symbol in current_debts:
        amount_of_collateral = (float(current_debts[symbol]['debt']) + float(delta['amount'])) * new_collateral_ratio / float(settlement_price)
        amount_of_collateral -= float(current_debts[symbol]['collateral'])
    else:
        amount_of_collateral = float(delta['amount']) * new_collateral_ratio / float(settlement_price)
    fundsNeeded = amount_of_collateral + float(self.returnFees()['call_order_update']['fee'])
    fundsHave = account.balance(collateral_asset['symbol']) or 0
    if fundsHave <= fundsNeeded:
        raise ValueError('Not enough funds available. Need %f %s, but only %f %s are available' % (fundsNeeded, collateral_asset['symbol'], fundsHave, collateral_asset['symbol']))
    payload = {'fee': {'amount': 0, 'asset_id': '1.3.0'}, 'delta_debt': {'amount': int(float(delta) * 10 ** asset['precision']), 'asset_id': asset['id']}, 'delta_collateral': {'amount': int(float(amount_of_collateral) * 10 ** collateral_asset['precision']), 'asset_id': collateral_asset['id']}, 'funding_account': account['id'], 'extensions': {}}
    if target_collateral_ratio:
        payload['extensions'].update(dict(target_collateral_ratio=int(target_collateral_ratio * 100)))
    op = operations.Call_order_update(**payload)
    return self.blockchain.finalizeOp(op, account['name'], 'active')

def update(self, value):
    if value <= 0.1:
        value = 0
    assert 0 <= value <= self.maxval
    self.currval = value
    if not self._need_update() or self.finished:
        return
    if not self.start_time:
        self.start_time = time.time()
    self.seconds_elapsed = time.time() - self.start_time
    self.prev_percentage = self.percentage()
    if value != self.maxval:
        self.fd.write(self._format_line() + '\r')
    else:
        self.finished = True
        self.fd.write(self._format_line() + '\n')

def parse_value_reference(parser, event, node):
    (next_event, next_node) = six.next(parser)
    if _is_start(next_event, next_node, 'CLASSPATH'):
        result = parse_classpath(parser, next_event, next_node)
    elif _is_start(next_event, next_node, 'LOCALCLASSPATH'):
        result = parse_localclasspath(parser, next_event, next_node)
    elif _is_start(next_event, next_node, 'CLASSNAME'):
        result = parse_classname(parser, next_event, next_node)
    elif _is_start(next_event, next_node, 'INSTANCEPATH'):
        result = parse_instancepath(parser, next_event, next_node)
    elif _is_start(next_event, next_node, 'LOCALINSTANCEPATH'):
        result = parse_localinstancepath(parser, next_event, next_node)
    elif _is_start(next_event, next_node, 'INSTANCENAME'):
        result = parse_instancename(parser, next_event, next_node)
    else:
        raise ParseError('Expecting (CLASSPATH | LOCALCLASSPATH | CLASSNAME | INSTANCEPATH | LOCALINSTANCEPATH | INSTANCENAME)')
    _get_end_event(parser, 'VALUE.REFERENCE')
    return result

def _check_keyserver(location):
    protocols = ['hkp://', 'hkps://', 'http://', 'https://', 'ldap://', 'mailto:']
    for proto in protocols:
        if location.startswith(proto):
            url = location.replace(proto, str())
            (host, slash, extra) = url.partition('/')
            if extra:
                log.warn("URI text for %s: '%s'" % (host, extra))
            log.debug("Got host string for keyserver setting: '%s'" % host)
            host = _fix_unsafe(host)
            if host:
                log.debug("Cleaned host string: '%s'" % host)
                keyserver = proto + host
                return keyserver
            return None

