def circleconvert(amount, currentformat, newformat):
    if currentformat.lower() == newformat.lower():
        return amount
    if currentformat.lower() == 'radius':
        if newformat.lower() == 'diameter':
            return amount * 2
        elif newformat.lower() == 'circumference':
            return amount * 2 * math.pi
        raise ValueError('Invalid new format provided.')
    elif currentformat.lower() == 'diameter':
        if newformat.lower() == 'radius':
            return amount / 2
        elif newformat.lower() == 'circumference':
            return amount * math.pi
        raise ValueError('Invalid new format provided.')
    elif currentformat.lower() == 'circumference':
        if newformat.lower() == 'radius':
            return amount / math.pi / 2
        elif newformat.lower() == 'diameter':
            return amount / math.pi

def pauli_expectation(self, prep_prog, pauli_terms):
    is_pauli_sum = False
    if isinstance(pauli_terms, PauliSum):
        (progs, coeffs) = pauli_terms.get_programs()
        is_pauli_sum = True
    else:
        coeffs = [pt.coefficient for pt in pauli_terms]
        progs = [pt.program for pt in pauli_terms]
    bare_results = self.expectation(prep_prog, progs)
    results = [c * r for (c, r) in zip(coeffs, bare_results)]
    if is_pauli_sum:
        return sum(results)
    return results

