def pass_local_client(method=None, clean=None, up_to_date=None, commit=None, ignore_std_streams=True, lock=None):
    if method is None:
        return functools.partial(pass_local_client, clean=clean, up_to_date=up_to_date, commit=commit, ignore_std_streams=ignore_std_streams, lock=lock)

    def new_func(*args, **kwargs):
        ctx = click.get_current_context()
        client = ctx.ensure_object(LocalClient)
        stack = contextlib.ExitStack()
        if get_git_isolation():
            client = stack.enter_context(client.worktree())
        transaction = client.transaction(clean=clean, up_to_date=up_to_date, commit=commit, ignore_std_streams=ignore_std_streams)
        stack.enter_context(transaction)
        if lock or (lock is None and commit):
            stack.enter_context(client.lock)
        with stack:
            result = ctx.invoke(method, client, *args, **kwargs)
        return result
    return functools.update_wrapper(new_func, method)

