def acl_required(permission, context):

    def decorator(func):

        @wraps(func)
        async def wrapper(*args):
            request = args[-1]
            if callable(context):
                context = context()
            if await get_permitted(request, permission, context):
                return await func(*args)
            raise web.HTTPForbidden()
        return wrapper
    return decorator

