    filename = os.path.abspath(filename)
    elements = filename.split(os.path.sep)
    modname = []
    while elements:
        modname.append(elements[-1])
        del elements[-1]
        if not os.path.exists(os.path.sep.join(elements + ['__init__.py'])):
