def register_handle(self, handle, location, checksum=None, additional_URLs=None, overwrite=False, **extratypes):
    LOGGER.debug('register_handle...')
    if overwrite == False:
        handlerecord_json = self.retrieve_handle_record_json(handle)
        if handlerecord_json is not None:
            msg = 'Could not register handle'
            LOGGER.error(msg + ', as it already exists.')
            raise HandleAlreadyExistsException(handle=handle, msg=msg)
    list_of_entries = []
    adminentry = self.__create_admin_entry(self.__handleowner, self.__HS_ADMIN_permissions, self.__make_another_index(list_of_entries, hs_admin=True), handle)
    list_of_entries.append(adminentry)
    entry_URL = self.__create_entry('URL', location, self.__make_another_index(list_of_entries, url=True))
    list_of_entries.append(entry_URL)
    if checksum is not None:
        entryChecksum = self.__create_entry('CHECKSUM', checksum, self.__make_another_index(list_of_entries))
        list_of_entries.append(entryChecksum)
    if extratypes is not None:
        for (key, value) in extratypes.items():
            entry = self.__create_entry(key, value, self.__make_another_index(list_of_entries))
            list_of_entries.append(entry)
    if additional_URLs is not None and len(additional_URLs) > 0:
        for url in additional_URLs:
            self.__add_URL_to_10320LOC(url, list_of_entries, handle)
    op = 'registering handle'
    (resp, put_payload) = self.__send_handle_put_request(handle, list_of_entries, overwrite=overwrite, op=op)
    resp_content = decoded_response(resp)
    if hsresponses.was_handle_created(resp) or hsresponses.handle_success(resp):
        LOGGER.info('Handle registered: ' + handle)
        return json.loads(resp_content)['handle']
    elif hsresponses.is_temporary_redirect(resp):
        oldurl = resp.url
        newurl = resp.headers['location']
        raise GenericHandleError(operation=op, handle=handle, response=resp, payload=put_payload, msg='Temporary redirect from ' + oldurl + ' to ' + newurl + '.')
    elif hsresponses.handle_not_found(resp):
        raise GenericHandleError(operation=op, handle=handle, response=resp, payload=put_payload, msg='Could not create handle. Possibly you used HTTP instead of HTTPS?')
    else:
        raise GenericHandleError(operation=op, handle=handle, reponse=resp, payload=put_payload)

def indent(self, text, n_indents=1, skipping=False):
    lines = text.splitlines()
    space = self.TEMPLATES.get(self.target_language).get('indent', ' ')
    if len(lines) == 1:
        if skipping:
            return text.strip()
        return n_indents * space + text.strip()
    indented_lines = []
    for (idx, line) in enumerate(lines):
        if skipping and idx is 0:
            indented_lines.append(line)
        else:
            line = n_indents * space + line
            indented_lines.append(line)
    indented_text = '\n'.join(indented_lines)
    return indented_text

def _out_of_date(func, *args, **kwargs):
    storage_directory = os.path.join(tempfile.gettempdir(), 'jobstamps')
    stamp_input = ''.join([func.__name__] + [repr(v) for v in args] + [repr(kwargs[k]) for k in sorted(kwargs.keys())]).encode('utf-8')
    dependencies = kwargs.pop('jobstamps_dependencies', None) or list()
    expected_output_files = kwargs.pop('jobstamps_output_files', None) or list()
    cache_output_directory = kwargs.pop('jobstamps_cache_output_directory', None) or storage_directory
    method_class = _determine_method(kwargs.pop('jobstamps_method', None))
    stamp_file_name = os.path.join(cache_output_directory, hashlib.md5(stamp_input).hexdigest())
    detail = _OutOfDateActionDetail(stamp=stamp_file_name, dependencies=dependencies, method=method_class(stamp_file_name), kwargs=kwargs)
    if os.environ.get('JOBSTAMPS_DISABLED', None):
        return ('JOBSTAMPS_DISABLED', detail)
    _safe_mkdir(cache_output_directory)
    if not os.path.isdir(cache_output_directory):
        raise IOError('{} exists and is not a directory.'.format(cache_output_directory))
    if not os.path.exists(stamp_file_name):
        return (stamp_file_name, detail)
    for expected_output_file in expected_output_files:
        if not os.path.exists(expected_output_file):
            return (expected_output_file, detail)
    for dependency in dependencies:
        if not os.path.exists(dependency) or not detail.method.check_dependency(dependency):
            return (dependency, detail)
    return (None, detail)

def fieldAlphaHistogram(self, name, q='*:*', fq=None, nbins=10, includequeries=True):
    oldpersist = self.persistent
    self.persistent = True
    bins = []
    qbin = []
    fvals = []
    try:
        fvals = self.fieldValues(name, q, fq, maxvalues=-1)
        nvalues = len(fvals[name]) / 2
        if nvalues < nbins:
            nbins = nvalues
        if nvalues == nbins:
            for i in range(0, nbins):
                bin = [fvals[name][i * 2], fvals[name][i * 2], 0]
                binq = '%s:%s' % (name, self.prepareQueryTerm(name, bin[0]))
                qbin.append(binq)
                bins.append(bin)
        else:
            delta = nvalues / nbins
            if delta == 1:
                for i in range(0, nbins - 2):
                    bin = [fvals[name][i * 2], fvals[name][i * 2], 0]
                    binq = '%s:%s' % (name, self.prepareQueryTerm(name, bin[0]))
                    qbin.append(binq)
                    bins.append(bin)
                term = fvals[name][(nbins - 1) * 2]
                bin = [term, fvals[name][(nvalues - 1) * 2], 0]
                binq = '%s:[%s TO *]' % (name, self.prepareQueryTerm(name, term))
                qbin.append(binq)
                bins.append(bin)
            else:
                coffset = 0.0
                delta = float(nvalues) / float(nbins)
                for i in range(0, nbins):
                    idxl = int(coffset) * 2
                    idxu = int(coffset + delta) * 2 - 2
                    bin = [fvals[name][idxl], fvals[name][idxu], 0]
                    binq = ''
                    try:
                        if i == 0:
                            binq = '%s:[* TO %s]' % (name, self.prepareQueryTerm(name, bin[1]))
                        elif i == nbins - 1:
                            binq = '%s:[%s TO *]' % (name, self.prepareQueryTerm(name, bin[0]))
                        else:
                            binq = '%s:[%s TO %s]' % (name, self.prepareQueryTerm(name, bin[0]), self.prepareQueryTerm(name, bin[1]))
                    except Exception:
                        self.logger.exception('Exception 1 in fieldAlphaHistogram:')
                    qbin.append(binq)
                    bins.append(bin)
                    coffset = coffset + delta
        params = {'q': q, 'rows': '0', 'facet': 'true', 'facet.field': name, 'facet.limit': '1', 'facet.mincount': 1, 'wt': 'python'}
        request = urllib.parse.urlencode(params, doseq=True)
        for sq in qbin:
            try:
                request = request + '&%s' % urllib.parse.urlencode({'facet.query': self.encoder(sq)[0]})
            except Exception:
                self.logger.exception('Exception 2 in fieldAlphaHistogram')
        rsp = self.doPost(self.solrBase + '', request, self.formheaders)
        data = eval(rsp.read())
        for i in range(0, len(bins)):
            v = data['facet_counts']['facet_queries'][qbin[i]]
            bins[i][2] = v
            if includequeries:
                bins[i].append(qbin[i])
    finally:
        self.persistent = oldpersist
        if not self.persistent:
            self.conn.close()
    return bins

def acr(tree, df, prediction_method=MPPA, model=F81, column2parameters=None, force_joint=True):
    for c in df.columns:
        df[c] = df[c].apply(lambda _: '' if pd.isna(_) else _.encode('ASCII', 'replace').decode())
    columns = preannotate_tree(df, tree)
    name_tree(tree)
    collapse_zero_branches(tree, features_to_be_merged=df.columns)
    (avg_br_len, num_nodes, num_tips) = get_tree_stats(tree)
    logging.getLogger('pastml').debug('\n=============ACR===============================')
    column2parameters = column2parameters if column2parameters else {}

    def _work(args):
        return reconstruct_ancestral_states(*args, avg_br_len=avg_br_len, num_nodes=num_nodes, num_tips=num_tips, force_joint=force_joint)
    prediction_methods = value2list(len(columns), prediction_method, MPPA)
    models = value2list(len(columns), model, F81)

    def get_states(method, model, column):
        df_states = [_ for _ in df[column].unique() if pd.notnull(_) and _ != '']
        if not is_ml(method) or model not in {HKY, JTT}:
            return np.sort(df_states)
        states = HKY_STATES if HKY == model else JTT_STATES
        if not set(df_states) & set(states):
            raise ValueError('The allowed states for model {} are {}, but your annotation file specifies {} as states in column {}.'.format(model, ', '.join(states), ', '.join(df_states), column))
        state_set = set(states)
        df[column] = df[column].apply(lambda _: _ if _ in state_set else '')
        return states
    with ThreadPool() as pool:
        acr_results = pool.map(func=_work, iterable=((tree, column, get_states(method, model, column), method, model, column2parameters[column] if column in column2parameters else None) for (column, method, model) in zip(columns, prediction_methods, models)))
    result = []
    for acr_res in acr_results:
        if isinstance(acr_res, list):
            result.extend(acr_res)
        else:
            result.append(acr_res)
    return result

def _calculate_values_to_forecast(self, timeSeries):
    if self._forecastUntil is None:
        return
    if not timeSeries.is_sorted():
        raise ValueError('timeSeries has to be sorted.')
    if not timeSeries.is_normalized():
        raise ValueError('timeSeries has to be normalized.')
    timediff = timeSeries[-1][0] - timeSeries[-2][0]
    forecastSpan = self._forecastUntil - timeSeries[-1][0]
    self.set_parameter('valuesToForecast', int(forecastSpan / timediff) + 1)

