def normalize(self, bias_range=1, poly_range=None, ignored_terms=None):

    def parse_range(r):
        if isinstance(r, Number):
            return (-abs(r), abs(r))
        return r
    if ignored_terms is None:
        ignored_terms = set()
    else:
        ignored_terms = {asfrozenset(term) for term in ignored_terms}
    if poly_range is None:
        (linear_range, poly_range) = (bias_range, bias_range)
    else:
        linear_range = bias_range
    (lin_range, poly_range) = map(parse_range, (linear_range, poly_range))
    lmin = lmax = 0
    pmin = pmax = 0
    for (term, bias) in self.items():
        if term in ignored_terms:
            continue
        if len(term) == 1:
            lmin = min(bias, lmin)
            lmax = max(bias, lmax)
        elif len(term) > 1:
            pmin = min(bias, pmin)
            pmax = max(bias, pmax)
    inv_scalar = max(lmin / lin_range[0], lmax / lin_range[1], pmin / poly_range[0], pmax / poly_range[1])
    if inv_scalar != 0:
        self.scale(1 / inv_scalar, ignored_terms=ignored_terms)

def parse_embeddedObject(self, val):
    if type(val) == list:
        return [self.parse_embeddedObject(obj) for obj in val]
    if val is None:
        return None
    tup_tree = xml_to_tupletree_sax(val, 'embedded object', self.conn_id)
    if name(tup_tree) == 'INSTANCE':
        return self.parse_instance(tup_tree)
    if name(tup_tree) == 'CLASS':
        return self.parse_class(tup_tree)
    raise CIMXMLParseError(_format('Invalid top-level element {0!A} in embedded object value', name(tup_tree)), conn_id=self.conn_id)

def find_item_in_path_by_type(self, si, path, obj_type):
    if obj_type is None:
        return None
    search_index = si.content.searchIndex
    sub_folder = si.content.rootFolder
    if path is None or not path:
        return sub_folder
    paths = path.split('/')
    for currPath in paths:
        if currPath is None or not currPath:
            continue
        manage = search_index.FindChild(sub_folder, currPath)
        if isinstance(manage, obj_type):
            return manage
    return None

def strip_project_url(url):
    m = re.match('(?:[^:]+://)?(.*)', url)
    if m:
        url = m.group(1)
    if url.endswith('.git'):
        (url, _, _) = url.rpartition('.')
    if url.endswith('-distgit'):
        (url, _, _) = url.rpartition('-')
    if url.startswith('openstack/'):
        (_, _, url) = url.partition('/')
    return url

