def get_ext_outputs(self):
    all_outputs = []
    ext_outputs = []
    paths = {self.bdist_dir: ''}
    for (base, dirs, files) in sorted_walk(self.bdist_dir):
        for filename in files:
            if os.path.splitext(filename)[1].lower() in NATIVE_EXTENSIONS:
                all_outputs.append(paths[base] + filename)
        for filename in dirs:
            paths[os.path.join(base, filename)] = paths[base] + filename + '/'
    if self.distribution.has_ext_modules():
        build_cmd = self.get_finalized_command('build_ext')
        for ext in build_cmd.extensions:
            if isinstance(ext, Library):
                continue
            fullname = build_cmd.get_ext_fullname(ext.name)
            filename = build_cmd.get_ext_filename(fullname)
            if not os.path.basename(filename).startswith('dl-'):
                if os.path.exists(os.path.join(self.bdist_dir, filename)):
                    ext_outputs.append(filename)
    return (all_outputs, ext_outputs)

def installOffering(self, offering):
    for off in self._siteStore.query(InstalledOffering, InstalledOffering.offeringName == offering.name):
        raise OfferingAlreadyInstalled(off)

    def siteSetup():
        for (requiredInterface, requiredPowerup) in offering.siteRequirements:
            if requiredInterface is not None:
                nn = requiredInterface(self._siteStore, None)
                if nn is not None:
                    continue
            if requiredPowerup is None:
                raise NotImplementedError('Interface %r required by %r but not provided by %r' % (requiredInterface, offering, self._siteStore))
            self._siteStore.findOrCreate(requiredPowerup, lambda p: installOn(p, self._siteStore))
        ls = self._siteStore.findOrCreate(userbase.LoginSystem)
        substoreItem = substore.SubStore.createNew(self._siteStore, ('app', offering.name + '.axiom'))
        ls.addAccount(offering.name, None, None, internal=True, avatars=substoreItem)
        from xmantissa.publicweb import PublicWeb
        PublicWeb(store=self._siteStore, application=substoreItem, prefixURL=offering.name)
        ss = substoreItem.open()

        def appSetup():
            for pup in offering.appPowerups:
                installOn(pup(store=ss), ss)
        ss.transact(appSetup)
        io = InstalledOffering(store=self._siteStore, offeringName=offering.name, application=substoreItem)
        from xmantissa import webtheme
        webtheme.theThemeCache.emptyCache()
        return io
    return self._siteStore.transact(siteSetup)

