def manage_process(self, *args):
    process_name = args[0]
    try:
        box_config = self.bc_dao.get_one([self.box_id, process_name])
        if not box_config.is_on:
            if box_config.pid is not None:
                self._kill_process(box_config)
            return
        if not box_config.pid or not psutil.pid_exists(box_config.pid):
            self._start_process(box_config)
        elif box_config.pid and psutil.pid_exists(box_config.pid):
            self._poll_process(box_config)
    except Exception as e:
        self.logger.error('Exception: {0}'.format(e), exc_info=True)

def _match_directories(self, entries, root, regex_string):
    self.log(u'Matching directory names in paged hierarchy')
    self.log([u"Matching within '%s'", root])
    self.log([u"Matching regex '%s'", regex_string])
    regex = re.compile('' + regex_string)
    directories = set()
    root_len = len(root)
    for entry in entries:
        if entry.startswith(root):
            self.log([u"Examining '%s'", entry])
            entry = entry[root_len + 1:]
            entry_splitted = entry.split(os.sep)
            if len(entry_splitted) >= 2 and re.match(regex, entry_splitted[0]) is not None:
                directories.add(entry_splitted[0])
                self.log([u"Match: '%s'", entry_splitted[0]])
            else:
                self.log([u"No match: '%s'", entry])
    return sorted(directories)

def __parse_identities(self, aliases, email_to_employer):
    self.__parse_aliases_stream(aliases)
    self.__parse_email_to_employer_stream(email_to_employer)
    for (alias, email) in self.__raw_aliases.items():
        uid = self._identities.get(email, None)
        if not uid:
            uid = UniqueIdentity(uuid=email)
            e = re.match(self.EMAIL_ADDRESS_REGEX, email, re.UNICODE)
            if e:
                identity = Identity(email=email, source=self.source)
            else:
                identity = Identity(username=email, source=self.source)
            uid.identities.append(identity)
            self._identities[email] = uid
        e = re.match(self.EMAIL_ADDRESS_REGEX, alias, re.UNICODE)
        if e:
            identity = Identity(email=alias, source=self.source)
        else:
            identity = Identity(username=alias, source=self.source)
        uid.identities.append(identity)
    for email in self.__raw_identities:
        if email in self._identities:
            uid = self._identities[email]
        elif email in self.__raw_aliases:
            canonical = self.__raw_aliases[email]
            uid = self._identities[canonical]
        else:
            uid = UniqueIdentity(uuid=email)
            identity = Identity(email=email, source=self.source)
            uid.identities.append(identity)
            self._identities[email] = uid
        enrs = self.__raw_identities[email]
        enrs.sort(key=lambda r: r[1])
        start_date = MIN_PERIOD_DATE
        for rol in enrs:
            name = rol[0]
            org = self._organizations.get(name, None)
            if not org:
                org = Organization(name=name)
                self._organizations[name] = org
            end_date = rol[1]
            enrollment = Enrollment(start=start_date, end=end_date, organization=org)
            uid.enrollments.append(enrollment)
            if end_date != MAX_PERIOD_DATE:
                start_date = end_date

def from_exception(exc, uuid=None):
    if not isinstance(exc, Error):
        exc = Error(code=500, message=str(exc))
    return Result(uuid=exc.extra.get('uuid', uuid or random_uuid()), retcode=exc.code, stderr=exc.message, retval=dict(error=ErrorSchema().dump(exc)))

def start_ray_process(command, process_type, env_updates=None, cwd=None, use_valgrind=False, use_gdb=False, use_valgrind_profiler=False, use_perftools_profiler=False, use_tmux=False, stdout_file=None, stderr_file=None):
    valgrind_env_var = 'RAY_{}_VALGRIND'.format(process_type.upper())
    if os.environ.get(valgrind_env_var) == '1':
        logger.info("Detected environment variable '%s'.", valgrind_env_var)
        use_valgrind = True
    valgrind_profiler_env_var = 'RAY_{}_VALGRIND_PROFILER'.format(process_type.upper())
    if os.environ.get(valgrind_profiler_env_var) == '1':
        logger.info("Detected environment variable '%s'.", valgrind_profiler_env_var)
        use_valgrind_profiler = True
    perftools_profiler_env_var = 'RAY_{}_PERFTOOLS_PROFILER'.format(process_type.upper())
    if os.environ.get(perftools_profiler_env_var) == '1':
        logger.info("Detected environment variable '%s'.", perftools_profiler_env_var)
        use_perftools_profiler = True
    tmux_env_var = 'RAY_{}_TMUX'.format(process_type.upper())
    if os.environ.get(tmux_env_var) == '1':
        logger.info("Detected environment variable '%s'.", tmux_env_var)
        use_tmux = True
    gdb_env_var = 'RAY_{}_GDB'.format(process_type.upper())
    if os.environ.get(gdb_env_var) == '1':
        logger.info("Detected environment variable '%s'.", gdb_env_var)
        use_gdb = True
    if sum([use_gdb, use_valgrind, use_valgrind_profiler, use_perftools_profiler]) > 1:
        raise ValueError("At most one of the 'use_gdb', 'use_valgrind', 'use_valgrind_profiler', and 'use_perftools_profiler' flags can be used at a time.")
    if env_updates is None:
        env_updates = {}
    if not isinstance(env_updates, dict):
        raise ValueError("The 'env_updates' argument must be a dictionary.")
    modified_env = os.environ.copy()
    modified_env.update(env_updates)
    if use_gdb:
        if not use_tmux:
            raise ValueError("If 'use_gdb' is true, then 'use_tmux' must be true as well.")
        gdb_init_path = '/tmp/ray/gdb_init_{}_{}'.format(process_type, time.time())
        ray_process_path = command[0]
        ray_process_args = command[1:]
        run_args = ' '.join(["'{}'".format(arg) for arg in ray_process_args])
        with open(gdb_init_path, 'w') as gdb_init_file:
            gdb_init_file.write('run {}'.format(run_args))
        command = ['gdb', ray_process_path, '-x', gdb_init_path]
    if use_valgrind:
        command = ['valgrind', '--track-origins=yes', '--leak-check=full', '--show-leak-kinds=all', '--leak-check-heuristics=stdstring', '--error-exitcode=1'] + command
    if use_valgrind_profiler:
        command = ['valgrind', '--tool=callgrind'] + command
    if use_perftools_profiler:
        modified_env['LD_PRELOAD'] = os.environ['PERFTOOLS_PATH']
        modified_env['CPUPROFILE'] = os.environ['PERFTOOLS_LOGFILE']
    if use_tmux:
        command = ['tmux', 'new-session', '-d', '{}'.format(' '.join(command))]
    process = subprocess.Popen(command, env=modified_env, cwd=cwd, stdout=stdout_file, stderr=stderr_file)
    return ProcessInfo(process=process, stdout_file=stdout_file.name if stdout_file is not None else None, stderr_file=stderr_file.name if stderr_file is not None else None, use_valgrind=use_valgrind, use_gdb=use_gdb, use_valgrind_profiler=use_valgrind_profiler, use_perftools_profiler=use_perftools_profiler, use_tmux=use_tmux)

def load(self, service_name, api_version=None, cached=True):
    if cached:
        if service_name in self._loaded_data:
            if api_version in self._loaded_data[service_name]:
                return self._loaded_data[service_name][api_version]
    data = {}
    options = self.get_available_options(service_name)
    (match, version) = self.get_best_match(options, service_name, api_version=api_version)
    with open(match, 'r') as json_file:
        data = json.load(json_file)
        data['__file__'] = match
        data['api_version'] = version
    if cached:
        self._loaded_data.setdefault(service_name, {})
        self._loaded_data[service_name][api_version] = data
    return data

def apply(self):
    if self.__closed:
        raise MigrationSessionError("Can't apply applied session")
    try:
        while self._to_apply:
            self.__apply(migration=self._to_apply.pop(0))
    except:
        raise
    finally:
        self.__closed = True

def ecliptic_xyz(self, epoch=None):
    if epoch is None:
        vector = _ECLIPJ2000.dot(self.position.au)
        return Distance(vector)
    position_au = self.position.au
    if isinstance(epoch, Time):
        pass
    elif isinstance(epoch, float):
        epoch = Time(None, tt=epoch)
    elif epoch == 'date':
        epoch = self.t
    else:
        raise ValueError('the epoch= must be a Time object, a floating point Terrestrial Time (TT), or the string "date" for epoch-of-date')
    (oblm, oblt, eqeq, psi, eps) = epoch._earth_tilt
    e = oblt * DEG2RAD
    rotation = einsum('ij...,jk...->ik...', rot_x(-e), epoch.M)
    position_au = einsum('ij...,j...->i...', rotation, position_au)
    return Distance(position_au)

def _separate_header_and_content(self, text_lines):
    no_more_header = False
    expr_metadata = re.compile('^#\\+[a-zA-Z]+:.*')
    header = []
    content = []
    for line in text_lines:
        metadata = expr_metadata.match(line)
        if metadata and (not no_more_header):
            header.append(line)
        else:
            no_more_header = True
            content.append(line)
    return (header, content)

