def data_boundaries(self, boundary=None, region=None, decode_geom=False, timespan=None, include_nonclipped=False):
    if isinstance(region, str):
        try:
            geom_type = self._geom_type(region)
            if geom_type in ('point', 'line'):
                bounds = '(SELECT ST_ConvexHull(ST_Collect(the_geom)) FROM {table})'.format(table=region)
            else:
                bounds = '(SELECT ST_Union(the_geom) FROM {table})'.format(table=region)
        except CartoException:
            regionsearch = '"geom_tags"::text ilike \'%{}%\''.format(get_countrytag(region))
            bounds = 'ST_MakeEnvelope(-180.0, -85.0, 180.0, 85.0, 4326)'
    elif isinstance(region, collections.Iterable):
        if len(region) != 4:
            raise ValueError('`region` should be a list of the geographic bounds of a region in the following order: western longitude, southern latitude, eastern longitude, and northern latitude. For example, Switerland fits in ``[5.9559111595,45.8179931641,10.4920501709,47.808380127]``.')
        bounds = 'ST_MakeEnvelope({0}, {1}, {2}, {3}, 4326)'.format(*region)
    elif region is None:
        bounds = 'ST_MakeEnvelope(-180.0, -85.0, 180.0, 85.0, 4326)'
    else:
        raise ValueError('`region` must be a str, a list of two lng/lat pairs, or ``None`` (which defaults to the world)')
    if include_nonclipped:
        clipped = None
    else:
        clipped = "(geom_id ~ '^us\\.census\\..*_clipped$' OR geom_id !~ '^us\\.census\\..*')"
    if boundary is None:
        regionsearch = locals().get('regionsearch')
        filters = ' AND '.join((r for r in [regionsearch, clipped] if r))
        query = utils.minify_sql(('SELECT *', 'FROM OBS_GetAvailableGeometries(', '  {bounds}, null, null, null, {timespan})', '{filters}')).format(bounds=bounds, timespan=utils.pgquote(timespan), filters='WHERE {}'.format(filters) if filters else '')
        return self.fetch(query, decode_geom=True)
    query = utils.minify_sql(('SELECT the_geom, geom_refs', 'FROM OBS_GetBoundariesByGeometry(', '    {bounds},', '    {boundary},', '    {time})')).format(bounds=bounds, boundary=utils.pgquote(boundary), time=utils.pgquote(timespan))
    return self.fetch(query, decode_geom=decode_geom)

