def sign_plot(x, g=None, flat=False, labels=True, cmap=None, cbar_ax_bbox=None, ax=None, **kwargs):
    try:
        del kwargs['cbar'], kwargs['vmin'], kwargs['vmax'], kwargs['center']
    except:
        pass
    if isinstance(x, DataFrame):
        df = x.copy()
    else:
        x = np.array(x)
        g = g or np.arange(x.shape[0])
        df = DataFrame(x, index=g, columns=g)
    dtype = df.values.dtype
    if not np.issubdtype(dtype, np.integer) and flat:
        raise ValueError('X should be a sign_array or DataFrame of integer values')
    elif not np.issubdtype(dtype, np.floating) and (not flat):
        raise ValueError('X should be an array or DataFrame of float p values')
    if not cmap and flat:
        cmap = ['1', '#fbd7d4', '#1a9641']
    elif not cmap and (not flat):
        cmap = ['1', '#fbd7d4', '#005a32', '#238b45', '#a1d99b']
    if flat:
        g = heatmap(df, vmin=-1, vmax=1, cmap=ListedColormap(cmap), cbar=False, ax=ax, **kwargs)
        if not labels:
            g.set_xlabel('')
            g.set_ylabel('')
        return g
    else:
        df[(x <= 0.001) & (x >= 0)] = 1
        df[(x <= 0.01) & (x > 0.001)] = 2
        df[(x <= 0.05) & (x > 0.01)] = 3
        df[x > 0.05] = 0
        np.fill_diagonal(df.values, -1)
        if len(cmap) != 5:
            raise ValueError('Cmap list must contain 5 items')
        g = heatmap(df, vmin=-1, vmax=3, cmap=ListedColormap(cmap), center=1, cbar=False, ax=ax, **kwargs)
        if not labels:
            g.set_xlabel('')
            g.set_ylabel('')
        cbar_ax = g.figure.add_axes(cbar_ax_bbox or [0.95, 0.35, 0.04, 0.3])
        cbar = ColorbarBase(cbar_ax, cmap=ListedColormap(cmap[2:] + [cmap[1]]), boundaries=[0, 1, 2, 3, 4])
        cbar.set_ticks(np.linspace(0.5, 3.5, 4))
        cbar.set_ticklabels(['p < 0.001', 'p < 0.01', 'p < 0.05', 'NS'])
        cbar.outline.set_linewidth(1)
        cbar.outline.set_edgecolor('0.5')
        cbar.ax.tick_params(size=0)
        return (g, cbar)

def _create_matrix(self, sentences, threshold, tf_metrics, idf_metrics):
    sentences_count = len(sentences)
    matrix = numpy.zeros((sentences_count, sentences_count))
    degrees = numpy.zeros((sentences_count,))
    for (row, (sentence1, tf1)) in enumerate(zip(sentences, tf_metrics)):
        for (col, (sentence2, tf2)) in enumerate(zip(sentences, tf_metrics)):
            matrix[row, col] = self.cosine_similarity(sentence1, sentence2, tf1, tf2, idf_metrics)
            if matrix[row, col] > threshold:
                matrix[row, col] = 1.0
                degrees[row] += 1
            else:
                matrix[row, col] = 0
    for row in range(sentences_count):
        for col in range(sentences_count):
            if degrees[row] == 0:
                degrees[row] = 1
            matrix[row][col] = matrix[row][col] / degrees[row]
    return matrix

