def create_property(self, model, name, description=None, property_type=PropertyType.CHAR_VALUE, default_value=None, unit=None, options=None):
    if model.category != Category.MODEL:
        raise IllegalArgumentError('The model should be of category MODEL')
    if not property_type.endswith('_VALUE'):
        warnings.warn('Please use the `PropertyType` enumeration to ensure providing correct values to the backend.', UserWarning)
        property_type = '{}_VALUE'.format(property_type.upper())
    if property_type not in PropertyType.values():
        raise IllegalArgumentError("Please provide a valid propertytype, please use one of `enums.PropertyType`. Got: '{}'".format(property_type))
    if property_type in (PropertyType.REFERENCE_VALUE, PropertyType.REFERENCES_VALUE) and isinstance(default_value, (list, tuple)) and default_value:
        default_value = default_value[0]
    data = {'name': name, 'part': model.id, 'description': description or '', 'property_type': property_type.upper(), 'value': default_value, 'unit': unit or '', 'options': options or {}}
    response = self._request('POST', self._build_url('properties'), json=data)
    if response.status_code != requests.codes.created:
        raise APIError('Could not create property')
    prop = Property.create(response.json()['results'][0], client=self)
    model.properties.append(prop)
    return prop

def flatten_comments(comments, root_level=0):
    stack = comments[:]
    for item in stack:
        item.nested_level = root_level
    (retval, parent_candidates) = ([], {})
    while stack:
        item = stack.pop(0)
        if isinstance(item, praw.objects.MoreComments) and item.count == 0:
            continue
        if item.parent_id:
            parent = parent_candidates.get(item.parent_id[3:])
            if parent:
                item.nested_level = parent.nested_level + 1
        if hasattr(item, 'replies'):
            for n in item.replies:
                n.nested_level = item.nested_level + 1
            stack[0:0] = item.replies
        parent_candidates[item.id] = item
        retval.append(item)
    return retval

