def execute_status(args, root_dir=None):
    status = command_factory('status')({}, root_dir=root_dir)
    if status['status'] == 'running':
        status['status'] = Color('{autogreen}' + '{}'.format(status['status']) + '{/autogreen}')
    elif status['status'] in ['paused']:
        status['status'] = Color('{autoyellow}' + '{}'.format(status['status']) + '{/autoyellow}')
    print('Daemon: {}\n'.format(status['status']))
    data = status['data']
    if isinstance(data, str):
        print(data)
    elif isinstance(data, dict):
        formatted_data = []
        formatted_data.append(['Index', 'Status', 'Code', 'Command', 'Path', 'Start', 'End'])
        for (key, entry) in sorted(data.items(), key=operator.itemgetter(0)):
            formatted_data.append(['#{}'.format(key), entry['status'], '{}'.format(entry['returncode']), entry['command'], entry['path'], entry['start'], entry['end']])
        table = AsciiTable(formatted_data)
        table.outer_border = False
        table.inner_column_border = False
        terminal_width = terminal_size()
        customWidth = table.column_widths
        if reduce(lambda a, b: a + b, table.column_widths) + 10 > terminal_width[0]:
            left_space = math.floor((terminal_width[0] - customWidth[0] - customWidth[1] - customWidth[2] - customWidth[5] - customWidth[6] - 14) / 2)
            if customWidth[3] < left_space:
                customWidth[4] = 2 * left_space - customWidth[3]
            elif customWidth[4] < left_space:
                customWidth[3] = 2 * left_space - customWidth[4]
            else:
                customWidth[3] = left_space
                customWidth[4] = left_space
        for (i, entry) in enumerate(table.table_data):
            for (j, string) in enumerate(entry):
                max_width = customWidth[j]
                wrapped_string = '\n'.join(wrap(string, max_width))
                if j == 1:
                    if wrapped_string == 'done' or wrapped_string == 'running' or wrapped_string == 'paused':
                        wrapped_string = Color('{autogreen}' + '{}'.format(wrapped_string) + '{/autogreen}')
                    elif wrapped_string in ['queued', 'stashed']:
                        wrapped_string = Color('{autoyellow}' + '{}'.format(wrapped_string) + '{/autoyellow}')
                    elif wrapped_string in ['failed', 'stopping', 'killing']:
                        wrapped_string = Color('{autored}' + '{}'.format(wrapped_string) + '{/autored}')
                elif j == 2:
                    if wrapped_string == '0' and wrapped_string != 'Code':
                        wrapped_string = Color('{autogreen}' + '{}'.format(wrapped_string) + '{/autogreen}')
                    elif wrapped_string != '0' and wrapped_string != 'Code':
                        wrapped_string = Color('{autored}' + '{}'.format(wrapped_string) + '{/autored}')
                table.table_data[i][j] = wrapped_string
        print(table.table)
    print('')

def decay_indexpointer(self):
    a_iso_to_plot = self.a_iso_to_plot
    isotope_to_plot = self.isotope_to_plot
    z_iso_to_plot = self.z_iso_to_plot
    el_iso_to_plot = self.el_iso_to_plot
    abunds = self.abunds
    isom = self.isom
    (z_db, a_db, el_db, stable_a_db, logic_db, charge_from_element_name) = self._read_isotopedatabase()
    beta = np.sign(stable_a_db - a_db)
    decay_index_pointer = np.zeros(len(isotope_to_plot), dtype='int') - 1
    idp_to_stables_in_isostoplot = []
    for i in range(len(isotope_to_plot)):
        element_name = isotope_to_plot[i].split('-')[0]
        try:
            stable_a = stable_a_db[np.where(el_db == element_name)][0]
        except IndexError:
            print("Can't find element " + element_name + ' in isotopedatabase.txt')
        if a_iso_to_plot[i] <= 209 and stable_a <= 209:
            stable_mass_numbers = self.stable_el[self.stable_names.index(element_name)][1:]
            iso_db_index_range_el = np.where(el_db == element_name)
            beta_for_this_species = int(beta[iso_db_index_range_el][np.where(a_db[iso_db_index_range_el] == a_iso_to_plot[i])])
            if beta_for_this_species == 0:
                beta_for_this_species = -1
            if a_iso_to_plot[i] in stable_mass_numbers:
                decay_index_pointer[i] = i
                idp_to_stables_in_isostoplot.append(i)
            elif a_iso_to_plot[i] == 8:
                decay_index_pointer[i] = isotope_to_plot.index('He-4')
            else:
                found_decay_target = False
                i_search = -1 * beta_for_this_species
                while not found_decay_target:
                    try:
                        try_target_el = self.stable_names[charge_from_element_name[element_name] + i_search]
                    except TypeError:
                        print('Maybe information about species ' + isotope_to_plot[i] + ' is not available in isotopedatabase.txt')
                        decay_index_pointer[i] = -1
                        break
                    try:
                        stable_mass_numbers = self.stable_el[self.stable_names.index(try_target_el)][1:]
                    except ValueError:
                        print('Can not find decay target for ' + isotope_to_plot[i])
                    if a_iso_to_plot[i] in stable_mass_numbers:
                        ind_range = np.where(np.array(el_iso_to_plot) == try_target_el)[0]
                        if a_iso_to_plot[i] in np.array(a_iso_to_plot)[ind_range]:
                            this_ind = ind_range[np.where(np.array(a_iso_to_plot)[ind_range] == a_iso_to_plot[i])[0]]
                            decay_index_pointer[i] = this_ind
                        else:
                            print('It seems unstable species ' + isotope_to_plot[i] + ' wants to decay to ' + try_target_el + '-' + str(a_iso_to_plot[i]) + ', however this species is not in this run.' + ' This points to an inconsistency in the network build. Here we will ignore the abundance of ' + isotope_to_plot[i] + '.')
                            decay_index_pointer[i] = -1
                        found_decay_target = True
                    else:
                        i_search += -1 * beta_for_this_species
    if self.debug:
        print('Decay rules:')
        for i in range(len(isotope_to_plot)):
            if decay_index_pointer[i] >= 0:
                print(isotope_to_plot[i] + ' -> ' + isotope_to_plot[decay_index_pointer[i]])
    ind_tmp = idp_to_stables_in_isostoplot
    self.decay_idp = decay_index_pointer
    self.idp_to_stables_in_isostoplot = ind_tmp

def diagonalize_collision_matrix(collision_matrices, i_sigma=None, i_temp=None, pinv_solver=0, log_level=0):
    start = time.time()
    shape = collision_matrices.shape
    if len(shape) == 6:
        size = shape[2] * shape[3]
        assert size == shape[4] * shape[5]
    elif len(shape) == 8:
        size = np.prod(shape[2:5])
        assert size == np.prod(shape[5:8])
    elif len(shape) == 2:
        size = shape[0]
        assert size == shape[1]
    solver = _select_solver(pinv_solver)
    if solver in [1, 2]:
        if log_level:
            routine = ['dsyev', 'dsyevd'][solver - 1]
            sys.stdout.write('Diagonalizing by lapacke %s... ' % routine)
            sys.stdout.flush()
        import phono3py._phono3py as phono3c
        w = np.zeros(size, dtype='double')
        if i_sigma is None:
            _i_sigma = 0
        else:
            _i_sigma = i_sigma
        if i_temp is None:
            _i_temp = 0
        else:
            _i_temp = i_temp
        phono3c.diagonalize_collision_matrix(collision_matrices, w, _i_sigma, _i_temp, 0.0, (solver + 1) % 2, 0)
    elif solver == 3:
        if log_level:
            sys.stdout.write('Diagonalizing by np.linalg.eigh... ')
            sys.stdout.flush()
        col_mat = collision_matrices[i_sigma, i_temp].reshape(size, size)
        (w, col_mat[:]) = np.linalg.eigh(col_mat)
    elif solver == 4:
        if log_level:
            sys.stdout.write('Diagonalizing by scipy.linalg.lapack.dsyev... ')
            sys.stdout.flush()
        import scipy.linalg
        col_mat = collision_matrices[i_sigma, i_temp].reshape(size, size)
        (w, _, info) = scipy.linalg.lapack.dsyev(col_mat.T, overwrite_a=1)
    elif solver == 5:
        if log_level:
            sys.stdout.write('Diagonalizing by scipy.linalg.lapack.dsyevd... ')
            sys.stdout.flush()
        import scipy.linalg
        col_mat = collision_matrices[i_sigma, i_temp].reshape(size, size)
        (w, _, info) = scipy.linalg.lapack.dsyevd(col_mat.T, overwrite_a=1)
    if log_level:
        print('[%.3fs]' % (time.time() - start))
        sys.stdout.flush()
    return w

