def get_path(num):
    num = int(num)
    dig_len = len(str(num))
    paths = []
    for i in range(dig_len - 2):
        divisor = 10 ** (dig_len - i - 1)
        paths.append('{}-{}'.format(num // divisor * divisor, (num // divisor + 1) * divisor - 1))
    return '/'.join(paths)

def do_group_by(self, element, decl, pseudo):
    sort_css = groupby_css = flags = ''
    if ',' in decl.value:
        if decl.value.count(',') == 2:
            (sort_css, groupby_css, flags) = map(serialize, split(decl.value, ','))
        else:
            (sort_css, groupby_css) = map(serialize, split(decl.value, ','))
    else:
        sort_css = serialize(decl.value)
    if groupby_css.strip() == 'nocase':
        flags = groupby_css
        groupby_css = ''
    sort = css_to_func(sort_css, flags, self.css_namespaces, self.state['lang'])
    groupby = css_to_func(groupby_css, flags, self.css_namespaces, self.state['lang'])
    step = self.state[self.state['current_step']]
    target = self.current_target()
    target.sort = sort
    target.lang = self.state['lang']
    target.isgroup = True
    target.groupby = groupby
    for (pos, action) in enumerate(reversed(step['actions'])):
        if action[0] == 'target' and action[1].tree == element.etree_element:
            action[1].sort = sort
            action[1].isgroup = True
            action[1].groupby = groupby
            break

def _build_message_headers(self):
    basic_deliver = self._inbound.pop(0)
    if not isinstance(basic_deliver, specification.Basic.Deliver):
        LOGGER.warning('Received an out-of-order frame: %s was expecting a Basic.Deliver frame', type(basic_deliver))
        return None
    content_header = self._inbound.pop(0)
    if not isinstance(content_header, ContentHeader):
        LOGGER.warning('Received an out-of-order frame: %s was expecting a ContentHeader frame', type(content_header))
        return None
    return (basic_deliver, content_header)

