def _init_file_logger(logger, level, log_path, log_size, log_count):
    if level not in [logging.NOTSET, logging.DEBUG, logging.INFO, logging.WARNING, logging.ERROR, logging.CRITICAL]:
        level = logging.DEBUG
    for h in logger.handlers:
        if isinstance(h, logging.handlers.RotatingFileHandler):
            if h.level == level:
                return
    fh = logging.handlers.RotatingFileHandler(log_path, maxBytes=log_size, backupCount=log_count)
    fh.setLevel(level)
    fh.setFormatter(_formatter)
    logger.addHandler(fh)

def FileHashIndexQuery(self, subject, target_prefix, limit=100):
    if isinstance(limit, (tuple, list)):
        (start, length) = limit
    else:
        start = 0
        length = limit
    prefix = (DataStore.FILE_HASH_TEMPLATE % target_prefix).lower()
    results = self.ResolvePrefix(subject, prefix, limit=limit)
    for (i, (_, hit, _)) in enumerate(results):
        if i < start:
            continue
        if i >= start + length:
            break
        yield rdfvalue.RDFURN(hit)

