def fire_event(self, event_name, wait=False, *args, **kwargs):
    tasks = []
    event_method_name = 'on_' + event_name
    for plugin in self._plugins:
        event_method = getattr(plugin.object, event_method_name, None)
        if event_method:
            try:
                task = self._schedule_coro(event_method(*args, **kwargs))
                tasks.append(task)

                def clean_fired_events(future):
                    try:
                        self._fired_events.remove(task)
                    except (KeyError, ValueError):
                        pass
                task.add_done_callback(clean_fired_events)
            except AssertionError:
                self.logger.error("Method '%s' on plugin '%s' is not a coroutine" % (event_method_name, plugin.name))
    self._fired_events.extend(tasks)
    if wait:
        if tasks:
            yield from asyncio.wait(tasks, loop=self._loop)

def validation_scatter(self, log_lam, b, masks, pre_v, gp, flux, time, med):
    self.lam[b] = 10 ** log_lam
    scatter = [None for i in range(len(masks))]
    for i in range(len(masks)):
        model = self.cv_compute(b, *pre_v[i])
        try:
            (gpm, _) = gp.predict(flux - model - med, time[masks[i]])
        except ValueError:
            return 1e+30
        fdet = (flux - model)[masks[i]] - gpm
        scatter[i] = 1000000.0 * (1.4826 * np.nanmedian(np.abs(fdet / med - np.nanmedian(fdet / med))) / np.sqrt(len(masks[i])))
    return np.max(scatter)

def _locate(self, minimum_version=None, maximum_version=None, jdk=False):
    for location in itertools.chain(self._distribution_environment.jvm_locations):
        try:
            dist = Distribution(home_path=location.home_path, bin_path=location.bin_path, minimum_version=minimum_version, maximum_version=maximum_version, jdk=jdk)
            dist.validate()
            logger.debug('Located {} for constraints: minimum_version {}, maximum_version {}, jdk {}'.format(dist, minimum_version, maximum_version, jdk))
            return dist
        except (ValueError, Distribution.Error) as e:
            logger.debug('{} is not a valid distribution because: {}'.format(location.home_path, str(e)))
            pass
    if minimum_version is not None and maximum_version is not None and (maximum_version < minimum_version):
        error_format = 'Pants configuration/options led to impossible constraints for {} distribution: minimum_version {}, maximum_version {}'
    else:
        error_format = 'Failed to locate a {} distribution with minimum_version {}, maximum_version {}'
    raise self.Error(error_format.format('JDK' if jdk else 'JRE', minimum_version, maximum_version))

