def call(self, method, args=None):
    message = SoapMessage(endpoint=self.endpoint, method=method, parameters=[] if args is None else args, http_headers=self.http_headers, soap_action='http://www.sonos.com/Services/1.1#{0}'.format(method), soap_header=self.get_soap_header(), namespace=self.namespace, timeout=self.timeout)
    try:
        result_elt = message.call()
    except SoapFault as exc:
        if 'Client.TokenRefreshRequired' in exc.faultcode:
            log.debug('Token refresh required. Trying again')
            self._cached_soap_header = None
            auth_token = exc.detail.findtext('.//authToken')
            private_key = exc.detail.findtext('.//privateKey')
            self.music_service.account.oa_device_id = auth_token
            self.music_service.account.key = private_key
            message = SoapMessage(endpoint=self.endpoint, method=method, parameters=args, http_headers=self.http_headers, soap_action='http://www.sonos.com/Services/1.1#{0}'.format(method), soap_header=self.get_soap_header(), namespace=self.namespace, timeout=self.timeout)
            result_elt = message.call()
        else:
            raise MusicServiceException(exc.faultstring, exc.faultcode)
    result = list(parse(XML.tostring(result_elt), process_namespaces=True, namespaces={'http://www.sonos.com/Services/1.1': None}).values())[0]
    return result if result is not None else {}

