        d = -0.5
    S = np.zeros_like(vs30)
    for i in range(vs30.size):
        if mmi_mean[i] <= 7.0:
            S[i] += c1
        elif mmi_mean[i] > 7 and mmi_mean[i] < 9.5:
            S[i] += c1 - d * (mmi_mean[i] - 7.0)
        else:
            S[i] += c2
    return S

