def _get_baremetal_connections(self, port, only_active_switch=False, from_segment=False):
    connections = []
    is_native = False if self.trunk.is_trunk_subport(port) else True
    all_link_info = port[bc.portbindings.PROFILE]['local_link_information']
    for link_info in all_link_info:
        (intf_type, port) = nexus_help.split_interface_name(link_info['port_id'])
        switch_info = self._get_baremetal_switch_info(link_info)
        if not switch_info:
            continue
        switch_ip = switch_info['switch_ip']
        if not self._switch_defined(switch_ip):
            continue
        if only_active_switch and (not self.is_switch_active(switch_ip)):
            continue
        ch_grp = 0
        if not from_segment:
            try:
                reserved = nxos_db.get_switch_if_host_mappings(switch_ip, nexus_help.format_interface_name(intf_type, port))
                if reserved[0].ch_grp > 0:
                    ch_grp = reserved[0].ch_grp
                    (intf_type, port) = nexus_help.split_interface_name('', ch_grp)
            except excep.NexusHostMappingNotFound:
                pass
        connections.append((switch_ip, intf_type, port, is_native, ch_grp))
    return connections

def from_arrays(cls, name, verts, normals, n_verts=3):
    wavefront_str = 'o {name}\n'.format(name=name)
    for vert in verts:
        wavefront_str += 'v {0} {1} {2}\n'.format(*vert)
    wavefront_str += 'vt 1.0 1.0\n'
    for norm in normals:
        wavefront_str += 'vn {0} {1} {2}\n'.format(*norm)
    for (wall_idx, vert_indices) in enumerate(grouper(n_verts, range(1, len(verts) + 1))):
        face_str = 'f '
        for idx in vert_indices:
            face_str += '{v}/1/{n} '.format(v=idx, n=wall_idx + 1)
        wavefront_str += face_str + '\n'
    return WavefrontWriter(string=wavefront_str)

