def compute_bin_edges(features, num_bins, edge_range, trim_outliers, trim_percentile, use_orig_distr=False):
    if use_orig_distr:
        print('Using original distribution (without histogram) to compute edge weights!')
        edges = None
        return edges
    if edge_range is None:
        if trim_outliers:
            edges_of_edges = np.array([np.percentile(features, trim_percentile), np.percentile(features, 100 - trim_percentile)])
        else:
            edges_of_edges = np.array([np.min(features), np.max(features)])
    else:
        edges_of_edges = edge_range
    edges = np.linspace(edges_of_edges[0], edges_of_edges[1], num=num_bins, endpoint=True)
    return edges

def optgroups(self, name, value, attrs=None):
    default = (None, [], 0)
    groups = [default]
    has_selected = False
    selected_choices = {str(v) for v in value}
    if not self.is_required and (not self.allow_multiple_selected):
        default[1].append(self.create_option(name, '', '', False, 0))
    if not isinstance(self.choices, ModelChoiceIterator):
        return super(ModelSelect2Mixin, self).optgroups(name, value, attrs=attrs)
    selected_choices = {c for c in selected_choices if c not in self.choices.field.empty_values}
    field_name = self.choices.field.to_field_name or 'pk'
    query = Q(**{'%s__in' % field_name: selected_choices})
    for obj in self.choices.queryset.filter(query):
        option_value = self.choices.choice(obj)[0]
        option_label = self.label_from_instance(obj)
        selected = str(option_value) in value and (has_selected is False or self.allow_multiple_selected)
        if selected is True and has_selected is False:
            has_selected = True
        index = len(default[1])
        subgroup = default[1]
        subgroup.append(self.create_option(name, option_value, option_label, selected_choices, index))
    return groups

