    def tmpl_cubert(x):
        return x ** (1.0 / 3.0) if x >= 0 else -(-x) ** (1.0 / 3.0)

    def tmpl_pow(x, y):
        return math.pow(x, y)
    try:
        import jinja2
    except ImportError:
        raise GeomdlException("Please install 'jinja2' package to use templated input: pip install jinja2")
    fsrc = file_src.replace('{%', '<%').replace('%}', '%>').replace('{{', '<{').replace('}}', '}>')
    env = jinja2.Environment(loader=jinja2.BaseLoader(), trim_blocks=True, block_start_string='<%', block_end_string='%>', variable_start_string='<{', variable_end_string='}>').from_string(fsrc)
    template_funcs = dict(knot_vector=utilities.generate_knot_vector, sqrt=tmpl_sqrt, cubert=tmpl_cubert, pow=tmpl_pow)
    for (k, v) in template_funcs.items():
        env.globals[k] = v
    return env.render()

