def pad(lines, delim):
    chunks = []
    for i in range(len(lines)):
        line = lines[i]
        sections = line.split(delim)
        for j in range(len(sections)):
            if len(chunks) <= j:
                chunks.append([])
            chunks[j].append(sections[j])
    '\n\tCalculates & Stores the max length of chunks\n\t'
    max_lengths = []
    for i in range(len(chunks)):
        _max = max([len(j) for j in chunks[i]])
        max_lengths.append(_max)
    '\n\tPads the children of chunks according to the chunk\'s max length" \t'
    for i in range(len(chunks)):
        for j in range(len(chunks[i])):
            chunks[i][j] += (max_lengths[i] - len(chunks[i][j])) * ' '
    new_lines = ['' for i in range(len(lines))]
    for i in range(len(chunks)):
        for j in range(len(chunks[i])):
            new_lines[j] += chunks[i][j]
    return new_lines

