def wait(object_ids, num_returns=1, timeout=None):
    worker = global_worker
    if isinstance(object_ids, ObjectID):
        raise TypeError('wait() expected a list of ray.ObjectID, got a single ray.ObjectID')
    if not isinstance(object_ids, list):
        raise TypeError('wait() expected a list of ray.ObjectID, got {}'.format(type(object_ids)))
    if isinstance(timeout, int) and timeout != 0:
        logger.warning("The 'timeout' argument now requires seconds instead of milliseconds. This message can be suppressed by passing in a float.")
    if timeout is not None and timeout < 0:
        raise ValueError("The 'timeout' argument must be nonnegative. Received {}".format(timeout))
    if worker.mode != LOCAL_MODE:
        for object_id in object_ids:
            if not isinstance(object_id, ObjectID):
                raise TypeError('wait() expected a list of ray.ObjectID, got list containing {}'.format(type(object_id)))
    worker.check_connected()
    with profiling.profile('ray.wait'):
        if worker.mode == LOCAL_MODE:
            return (object_ids[:num_returns], object_ids[num_returns:])
        if len(object_ids) == 0:
            return ([], [])
        if len(object_ids) != len(set(object_ids)):
            raise Exception('Wait requires a list of unique object IDs.')
        if num_returns <= 0:
            raise Exception('Invalid number of objects to return %d.' % num_returns)
        if num_returns > len(object_ids):
            raise Exception('num_returns cannot be greater than the number of objects provided to ray.wait.')
        timeout = timeout if timeout is not None else 10 ** 6
        timeout_milliseconds = int(timeout * 1000)
        (ready_ids, remaining_ids) = worker.raylet_client.wait(object_ids, num_returns, timeout_milliseconds, False, worker.current_task_id)
        return (ready_ids, remaining_ids)

