def inverse(self):
    op = self
    scaling = getattr(self.domain, 'cell_volume', 1.0)

    class FlatteningOperatorInverse(Operator):

        def __init__(self):
            super(FlatteningOperatorInverse, self).__init__(op.range, op.domain, linear=True)

        def _call(self, x):
            return np.reshape(x.asarray(), self.range.shape, order=op.order)

        def adjoint(self):
            return scaling * op

        def inverse(self):
            return op

        def __repr__(self):
            return '{!r}.inverse'.format(op)

        def __str__(self):
            return repr(self)
    return FlatteningOperatorInverse()

