def gauss_fit_log(X, Y):
    X = np.asarray(X)
    Y = np.asarray(Y)
    Data = np.log(Y)
    D = [(Data * X ** i).sum() for i in range(3)]
    X = [(X ** i).sum() for i in range(5)]
    num = D[0] * (X[1] * X[4] - X[2] * X[3]) + D[1] * (X[2] ** 2 - X[0] * X[4]) + D[2] * (X[0] * X[3] - X[1] * X[2])
    den = 2 * (D[0] * (X[1] * X[3] - X[2] ** 2) + D[1] * (X[1] * X[2] - X[0] * X[3]) + D[2] * (X[0] * X[2] - X[1] ** 2))
    varnum = -X[0] * X[2] * X[4] + X[0] * X[3] ** 2 + X[1] ** 2 * X[4] - 2 * X[1] * X[2] * X[3] + X[2] ** 3
    if abs(den) < 1e-05:
        return (np.nan, np.nan)
    mean = num / den
    var = varnum / den
    if var < 0:
        return (np.nan, np.nan)
    return (mean, var)

