def handleMethodCallMessage(self, msg):
    if msg.interface == 'org.freedesktop.DBus.Peer' and msg.member == 'Ping':
        r = message.MethodReturnMessage(msg.serial, destination=msg.sender)
        self.conn.sendMessage(r)
        return
    if msg.interface == 'org.freedesktop.DBus.Introspectable' and msg.member == 'Introspect':
        xml = introspection.generateIntrospectionXML(msg.path, self.exports)
        if xml is not None:
            r = message.MethodReturnMessage(msg.serial, body=[xml], destination=msg.sender, signature='s')
            self.conn.sendMessage(r)
            return
    o = self.exports.get(msg.path, None)
    if o is None:
        self._send_err(msg, 'org.freedesktop.DBus.Error.UnknownObject', '%s is not an object provided by this process.' % msg.path)
        return
    if msg.interface == 'org.freedesktop.DBus.ObjectManager' and msg.member == 'GetManagedObjects':
        i_and_p = self.getManagedObjects(o.getObjectPath())
        r = message.MethodReturnMessage(msg.serial, body=[i_and_p], destination=msg.sender, signature='a{oa{sa{sv}}}')
        self.conn.sendMessage(r)
        return
    i = None
    for x in o.getInterfaces():
        if msg.interface:
            if x.name == msg.interface:
                i = x
                break
        elif msg.member in x.methods:
            i = x
            break
    m = None
    if i:
        m = i.methods.get(msg.member, None)
    if m is None:
        self._send_err(msg, 'org.freedesktop.DBus.Error.UnknownMethod', 'Method "%s" with signature "%s" on interface "%s" doesn\'t exist' % (msg.member, msg.signature or '', msg.interface or '(null)'))
        return
    msig = msg.signature if msg.signature is not None else ''
    esig = m.sigIn if m.sigIn is not None else ''
    if esig != msig:
        self._send_err(msg, 'org.freedesktop.DBus.Error.InvalidArgs', 'Call to %s has wrong args (%s, expected %s)' % (msg.member, msg.signature or '', m.sigIn or ''))
        return
    d = defer.maybeDeferred(o.executeMethod, i, msg.member, msg.body, msg.sender)
    if msg.expectReply:

        def send_reply(return_values):
            if isinstance(return_values, (list, tuple)):
                if m.nret == 1:
                    return_values = [return_values]
            else:
                return_values = [return_values]
            r = message.MethodReturnMessage(msg.serial, body=return_values, destination=msg.sender, signature=m.sigOut)
            self.conn.sendMessage(r)

        def send_error(err):
            e = err.value
            errMsg = err.getErrorMessage()
            name = None
            if hasattr(e, 'dbusErrorName'):
                name = e.dbusErrorName
            if name is None:
                name = 'org.txdbus.PythonException.' + e.__class__.__name__
            try:
                marshal.validateErrorName(name)
            except error.MarshallingError:
                errMsg = '!!(Invalid error name "%s")!! ' % name + errMsg
                name = 'org.txdbus.InvalidErrorName'
            r = message.ErrorMessage(name, msg.serial, body=[errMsg], signature='s', destination=msg.sender)
            self.conn.sendMessage(r)
        d.addCallback(send_reply)
        d.addErrback(send_error)

