def andor_tags(self):
    if not self.is_andor:
        return None
    tags = self.tags
    result = {'Id': tags['AndorId'].value}
    for tag in list(self.tags.values()):
        code = tag.code
        if not 4864 < code < 5031:
            continue
        value = tag.value
        name = tag.name[5:] if len(tag.name) > 5 else tag.name
        result[name] = value
        del tags[tag.name]
    return result

def import_modules_from_package(package):
    path = [os.path.dirname(__file__), '..'] + package.split('.')
    path = os.path.join(*path)
    for (root, dirs, files) in os.walk(path):
        for filename in files:
            if filename.startswith('__') or not filename.endswith('.py'):
                continue
            new_package = '.'.join(root.split(os.sep)).split('....')[1]
            module_name = '%s.%s' % (new_package, filename[:-3])
            if module_name not in sys.modules:
                __import__(module_name)

def query_intersections(self, x_terms=None, y_terms=None, symmetric=False):
    if x_terms is None:
        x_terms = []
    if y_terms is None:
        y_terms = []
    xset = set(x_terms)
    yset = set(y_terms)
    zset = xset.union(yset)
    gmap = {}
    for z in zset:
        gmap[z] = []
    for subj in self.subjects:
        ancs = self.inferred_types(subj)
        for a in ancs.intersection(zset):
            gmap[a].append(subj)
    for z in zset:
        gmap[z] = set(gmap[z])
    ilist = []
    for x in x_terms:
        for y in y_terms:
            if not symmetric or x < y:
                shared = gmap[x].intersection(gmap[y])
                union = gmap[x].union(gmap[y])
                j = 0
                if len(union) > 0:
                    j = len(shared) / len(union)
                ilist.append({'x': x, 'y': y, 'shared': shared, 'c': len(shared), 'j': j})
    return ilist

def __get_max_min_time_2(table, terms, exact):
    vals = []
    unit = ''
    try:
        for (k, v) in table['columns'].items():
            if exact:
                if k.lower() in terms:
                    try:
                        vals = v['values']
                        unit = v['units']
                        break
                    except KeyError:
                        pass
            elif not exact:
                for term in terms:
                    if term in k:
                        try:
                            vals = v['values']
                            unit = v['units']
                            break
                        except KeyError:
                            pass
    except Exception as e:
        logger_lpd_noaa.debug('get_max_min_time_3: {}'.format(e))
    return (vals, unit)

def process_args_from_command_line(self):
    opts_to_remove = []
    for (idx, option) in enumerate(sys.argv):
        if not option.startswith('--'):
            continue
        if option == '--static':
            opts_to_remove.append(idx)
            self.static_extension = True
        elif option == '--no-download':
            opts_to_remove.append(idx)
            self.download_igraph_if_needed = False
        elif option == '--no-pkg-config':
            opts_to_remove.append(idx)
            self.use_pkgconfig = False
        elif option == '--no-progress-bar':
            opts_to_remove.append(idx)
            self.show_progress_bar = False
        elif option == '--no-wait':
            opts_to_remove.append(idx)
            self.wait = False
        elif option.startswith('--c-core-version'):
            opts_to_remove.append(idx)
            if option == '--c-core-version':
                value = sys.argv[idx + 1]
                opts_to_remove.append(idx + 1)
            else:
                value = option.split('=', 1)[1]
            self.c_core_versions = [value]
        elif option.startswith('--c-core-url'):
            opts_to_remove.append(idx)
            if option == '--c-core-url':
                value = sys.argv[idx + 1]
                opts_to_remove.append(idx + 1)
            else:
                value = option.split('=', 1)[1]
            self.c_core_url = value
    for idx in reversed(opts_to_remove):
        sys.argv[idx:idx + 1] = []

