def format_item(self, item):
    if not item:
        return None
    ret = self.dict_class()
    ret[TYPE] = self.opts.type_
    attributes = {get_dump_key(self.fields[field]) or field: field for field in self.fields}
    for (field_name, value) in iteritems(item):
        attribute = attributes[field_name]
        if attribute == ID:
            ret[ID] = value
        elif isinstance(self.fields[attribute], DocumentMeta):
            if not self.document_meta:
                self.document_meta = self.dict_class()
            self.document_meta.update(value)
        elif isinstance(self.fields[attribute], ResourceMeta):
            if 'meta' not in ret:
                ret['meta'] = self.dict_class()
            ret['meta'].update(value)
        elif isinstance(self.fields[attribute], BaseRelationship):
            if value:
                if 'relationships' not in ret:
                    ret['relationships'] = self.dict_class()
                ret['relationships'][self.inflect(field_name)] = value
        else:
            if 'attributes' not in ret:
                ret['attributes'] = self.dict_class()
            ret['attributes'][self.inflect(field_name)] = value
    links = self.get_resource_links(item)
    if links:
        ret['links'] = links
    return ret

def pastml_pipeline(tree, data, data_sep='\t', id_index=0, columns=None, prediction_method=MPPA, model=F81, parameters=None, name_column=None, date_column=None, tip_size_threshold=REASONABLE_NUMBER_OF_TIPS, out_data=None, html_compressed=None, html=None, work_dir=None, verbose=False, forced_joint=False, upload_to_itol=False, itol_id=None, itol_project=None, itol_tree_name=None):
    logger = _set_up_pastml_logger(verbose)
    (root, df, years, tip2date, name_column) = _validate_input(columns, data, data_sep, date_column, html, html_compressed, id_index, name_column, tree, copy_only=COPY == prediction_method or (isinstance(prediction_method, list) and all((COPY == _ for _ in prediction_method))))
    if not date_column:
        date_column = 'Dist. to root'
    if parameters:
        if isinstance(parameters, str):
            parameters = [parameters]
        if isinstance(parameters, list):
            parameters = dict(zip(df.columns, parameters))
        elif isinstance(parameters, dict):
            parameters = {col_name2cat(col): params for (col, params) in parameters.items()}
        else:
            raise ValueError('Parameters should be either a list or a dict, got {}.'.format(type(parameters)))
    else:
        parameters = {}
    if not work_dir:
        work_dir = get_pastml_work_dir(tree)
    os.makedirs(work_dir, exist_ok=True)
    acr_results = acr(root, df, prediction_method=prediction_method, model=model, column2parameters=parameters, force_joint=forced_joint)
    column2states = {acr_result[CHARACTER]: acr_result[STATES] for acr_result in acr_results}
    if not out_data:
        out_data = os.path.join(work_dir, get_combined_ancestral_state_file())
    state_df = _serialize_predicted_states(sorted(column2states.keys()), out_data, root)
    if html_compressed and name_column and (name_column not in column2states):
        ml_name_column = get_personalized_feature_name(name_column, get_default_ml_method())
        name_column = ml_name_column if ml_name_column in column2states else get_personalized_feature_name(name_column, get_default_mp_method())
    itol_result = None
    pool = ThreadPool()
    new_tree = os.path.join(work_dir, get_named_tree_file(tree))
    root.write(outfile=new_tree, format_root_node=True, format=3)
    async_result = pool.map_async(func=_serialize_acr, iterable=((acr_res, work_dir) for acr_res in acr_results))
    if upload_to_itol:
        itol_result = pool.apply_async(func=generate_itol_annotations, args=(column2states, work_dir, acr_results, state_df, date_column, tip2date, new_tree, itol_id, itol_project, itol_tree_name))
    if html or html_compressed:
        logger.debug('\n=============VISUALISATION=====================')
        visualize(root, column2states=column2states, html=html, html_compressed=html_compressed, years=years, tip2date=tip2date, name_column=name_column, tip_size_threshold=tip_size_threshold, date_column=date_column)
    async_result.wait()
    if itol_result:
        itol_result.wait()
    pool.close()
    return root

def compile_node(self, node):
    if node.type == self.syms.Matcher:
        node = node.children[0]
    if node.type == self.syms.Alternatives:
        alts = [self.compile_node(ch) for ch in node.children[::2]]
        if len(alts) == 1:
            return alts[0]
        p = pytree.WildcardPattern([[a] for a in alts], min=1, max=1)
        return p.optimize()
    if node.type == self.syms.Alternative:
        units = [self.compile_node(ch) for ch in node.children]
        if len(units) == 1:
            return units[0]
        p = pytree.WildcardPattern([units], min=1, max=1)
        return p.optimize()
    if node.type == self.syms.NegatedUnit:
        pattern = self.compile_basic(node.children[1:])
        p = pytree.NegatedPattern(pattern)
        return p.optimize()
    assert node.type == self.syms.Unit
    name = None
    nodes = node.children
    if len(nodes) >= 3 and nodes[1].type == token.EQUAL:
        name = nodes[0].value
        nodes = nodes[2:]
    repeat = None
    if len(nodes) >= 2 and nodes[-1].type == self.syms.Repeater:
        repeat = nodes[-1]
        nodes = nodes[:-1]
    pattern = self.compile_basic(nodes, repeat)
    if repeat is not None:
        assert repeat.type == self.syms.Repeater
        children = repeat.children
        child = children[0]
        if child.type == token.STAR:
            min = 0
            max = pytree.HUGE
        elif child.type == token.PLUS:
            min = 1
            max = pytree.HUGE
        elif child.type == token.LBRACE:
            assert children[-1].type == token.RBRACE
            assert len(children) in (3, 5)
            min = max = self.get_int(children[1])
            if len(children) == 5:
                max = self.get_int(children[3])
        else:
            assert False
        if min != 1 or max != 1:
            pattern = pattern.optimize()
            pattern = pytree.WildcardPattern([[pattern]], min=min, max=max)
    if name is not None:
        pattern.name = name
    return pattern.optimize()

def elapsed_time(self) -> float:
    current_time = datetime.utcnow()
    start = self.start_time or current_time
    end = self.end_time or current_time
    return (end - start).total_seconds()

def get_extents(self, element, ranges, range_type='combined'):
    if range_type == 'extents':
        return element.nodes.extents
    (xdim, ydim) = element.nodes.kdims[:2]
    xpad = 0.05 if self.label_index is None else 0.25
    (x0, x1) = ranges[xdim.name][range_type]
    (y0, y1) = ranges[ydim.name][range_type]
    xdiff = x1 - x0
    ydiff = y1 - y0
    if self.label_position == 'right':
        (x0, x1) = (x0 - 0.05 * xdiff, x1 + xpad * xdiff)
    else:
        (x0, x1) = (x0 - xpad * xdiff, x1 + 0.05 * xdiff)
    (x0, x1) = max_range([xdim.range, (x0, x1)])
    (y0, y1) = max_range([ydim.range, (y0 - 0.05 * ydiff, y1 + 0.05 * ydiff)])
    return (x0, y0, x1, y1)

