    _args = []
    _kwargs = {}
    for arg in args:
        if isinstance(arg, six.string_types):
            (arg_name, arg_value) = parse_kwarg(arg)
            if arg_name:
                _kwargs[arg_name] = yamlify_arg(arg_value) if arg_name not in no_parse else arg_value
            else:
