def parse(cls, format):
    fmt = cls()
    if not format:
        return fmt
    state = ParseState(fmt, format)
    for (idx, char) in enumerate(format):
        if state.check_ignore():
            continue
        if state == 'string':
            if char == '%':
                if format[idx:idx + 2] == '%%':
                    state.add_text(idx + 1, idx + 2)
                    state.set_ignore(1)
                else:
                    state.add_text(idx)
                    state.conversion(idx)
            elif char == '\\':
                state.add_text(idx)
                state.escape(idx)
        elif state == 'escape':
            state.add_escape(idx + 1, char)
            state.pop_state(idx + 1)
        elif state == 'param':
            if char == '}':
                state.set_param(idx)
                state.pop_state()
        elif state == 'conv':
            if char == ')':
                state.set_conversion(idx)
                state.pop_state()
                state.pop_state(idx + 1)
        else:
            if char in '<>':
                continue
            elif char == '!':
                state.set_reject()
                continue
            elif char == ',' and state.code_last:
                continue
            elif char.isdigit():
                if state.set_code(idx):
                    continue
            elif char == '{' and state.param_begin is None:
                state.param(idx + 1)
                continue
            elif char == '(' and state.conv_begin is None:
                state.conv(idx + 1)
                continue
            state.set_conversion(idx)
            state.pop_state(idx + 1)
    return state.end_state()

def distance(self, other):
