    def __cbFun(snmpEngine, sendRequestHandle, errorIndication, errorStatus, errorIndex, varBinds, cbCtx):
        (lookupMib, deferred) = cbCtx
        if errorIndication:
            deferred.errback(Failure(errorIndication))
        else:
            try:
                varBinds = VB_PROCESSOR.unmakeVarBinds(snmpEngine.cache, varBinds, lookupMib)
            except Exception as e:
                deferred.errback(Failure(e))
            else:
                deferred.callback((errorStatus, errorIndex, varBinds))
    notifyName = LCD.configure(snmpEngine, authData, transportTarget, notifyType, contextData.contextName)

    def __trapFun(deferred):
        deferred.callback((0, 0, []))
    varBinds = VB_PROCESSOR.makeVarBinds(snmpEngine.cache, varBinds)
    deferred = Deferred()
    ntforg.NotificationOriginator().sendVarBinds(snmpEngine, notifyName, contextData.contextEngineId, contextData.contextName, varBinds, __cbFun, (options.get('lookupMib', True), deferred))
    if notifyType == 'trap':
        reactor.callLater(0, __trapFun, deferred)
    return deferred

