        try:
            name = os.path.basename(fp.name)
        except AttributeError:
            name = ''
        for chunk in self.gen_chunks(self.envelope.file_open(name)):
            yield chunk
        for chunk in self.file_chunks(fp):
            yield chunk
        for chunk in self.gen_chunks(self.envelope.file_close()):
