def parse_fasta(data):
    (name, seq) = (None, [])
    for line in data:
        line = line.rstrip()
        if line.startswith('>'):
            if name:
                yield Sequence(name, ''.join(seq))
            (name, seq) = (line, [])
        else:
            seq.append(line)
    if name:
        yield Sequence(name, ''.join(seq))

