def _store_header(self):
    (key, value) = (None, None)
    headers = []
    header_line = (yield)
    while header_line is not None:
        if not header_line.startswith((b' ', b'\t')):
            if key:
                headers.append((key, value))
            (key, value) = self.split_header_key_value(header_line)
            key = key.upper()
        else:
            next_val = header_line.strip().decode()
            if isinstance(value, list):
                value.append(next_val)
            else:
                value = [value, next_val]
        header_line = (yield)
    if key is not None:
        headers.append((key, value))
    yield dict(headers)

def eval_agg_call(self, exp):
    if not isinstance(self.c_row, list):
        raise TypeError('aggregate function expected a list of rows')
    if len(exp.args.children) != 1:
        raise ValueError('aggregate function expected a single value', exp.args)
    (arg,) = exp.args.children
    vals = [Evaluator(c_r, self.nix, self.tables).eval(arg) for c_r in self.c_row]
    if not vals:
        return None
    if exp.f == 'min':
        return min(vals)
    elif exp.f == 'max':
        return max(vals)
    elif exp.f == 'count':
        return len(vals)
    else:
        raise NotImplementedError('unk_func', exp.f)

