def sndwrite(samples: np.ndarray, sr: int, outfile: str, encoding: str='auto') -> None:
    if encoding in ('auto', None):
        encoding = _guessEncoding(samples, outfile)
    clipping = (samples > 1).any() or (samples < -1).any()
    if encoding.startswith('pcm') and clipping:
        maxvalue = max(samples.max(), abs(samples.min()))
        samples = samples / maxvalue
    backend = _getWriteBackend(outfile, encoding)
    if not backend:
        raise SndfileError('No backend found to support the given format')
    logger.debug(f'sndwrite: using backend {backend.name}')
    return backend.write(samples, sr, outfile, encoding)

def fly(cls, conf_path, docname, source, maxdepth=1):
    msg = '``.. articles::`` directive is going to be deprecated. use ``.. autodoctree`` instead.'
    warnings.warn(msg, FutureWarning)
    directive_pattern = '.. articles::'
    if directive_pattern not in source:
        return source
    af = ArticleFolder(dir_path=Path(Path(conf_path).parent, docname).parent.abspath)
    toc_directive = af.toc_directive(maxdepth)
    lines = list()
    for line in source.split('\n'):
        if directive_pattern in line.strip():
            if line.strip().startswith(directive_pattern):
                line = line.replace(directive_pattern, toc_directive, 1)
                lines.append(line)
                continue
        lines.append(line)
    return '\n'.join(lines)

def request(self, command_string):
