def _gatk_apply_bqsr(data):
    in_file = dd.get_align_bam(data) or dd.get_work_bam(data)
    out_file = os.path.join(dd.get_work_dir(data), 'align', dd.get_sample_name(data), '%s-recal.bam' % utils.splitext_plus(os.path.basename(in_file))[0])
    if not utils.file_uptodate(out_file, in_file):
        with file_transaction(data, out_file) as tx_out_file:
            broad_runner = broad.runner_from_config(data['config'])
            gatk_type = broad_runner.gatk_type()
            cores = dd.get_num_cores(data)
            if gatk_type == 'gatk4':
                resources = config_utils.get_resources('gatk-spark', data['config'])
                spark_opts = [str(x) for x in resources.get('options', [])]
                params = ['-T', 'ApplyBQSRSpark', '--input', in_file, '--output', tx_out_file, '--bqsr-recal-file', data['prep_recal'], '--static-quantized-quals', '10', '--static-quantized-quals', '20', '--static-quantized-quals', '30']
                if spark_opts:
                    params += spark_opts
                else:
                    params += ['--spark-master', 'local[%s]' % cores, '--conf', 'spark.local.dir=%s' % os.path.dirname(tx_out_file), '--conf', 'spark.driver.host=localhost', '--conf', 'spark.network.timeout=800']
            else:
                params = ['-T', 'PrintReads', '-R', dd.get_ref_file(data), '-I', in_file, '-BQSR', data['prep_recal'], '-o', tx_out_file]
            if gatk_type == 'gatk4':
                params += ['--jdk-deflater', '--jdk-inflater']
            elif LooseVersion(broad_runner.gatk_major_version()) > LooseVersion('3.7'):
                params += ['-jdk_deflater', '-jdk_inflater']
            memscale = {'magnitude': 0.9 * cores, 'direction': 'increase'} if cores > 1 else None
            broad_runner.run_gatk(params, os.path.dirname(tx_out_file), memscale=memscale, parallel_gc=True)
    bam.index(out_file, data['config'])
    return out_file

def build_act(cls: Type[_Block], node: ast.stmt, test_func_node: ast.FunctionDef) -> _Block:
    add_node_parents(test_func_node)
    act_block_node = node
    while act_block_node.parent != test_func_node:
        act_block_node = act_block_node.parent
    return cls([act_block_node], LineType.act)

def moments(data, n_neighbors=30, n_pcs=30, mode='connectivities', method='umap', metric='euclidean', use_rep=None, recurse_neighbors=False, renormalize=False, copy=False):
    adata = data.copy() if copy else data
    if 'spliced' not in adata.layers.keys() or 'unspliced' not in adata.layers.keys():
        raise ValueError('Could not find spliced / unspliced counts.')
    if any([not_yet_normalized(adata.layers[layer]) for layer in {'spliced', 'unspliced'}]):
        normalize_per_cell(adata)
    if 'neighbors' not in adata.uns.keys() or neighbors_to_be_recomputed(adata, n_neighbors=n_neighbors):
        if use_rep is None:
            use_rep = 'X_pca'
        neighbors(adata, n_neighbors=n_neighbors, use_rep=use_rep, n_pcs=n_pcs, method=method, metric=metric)
    if mode not in adata.uns['neighbors']:
        raise ValueError("mode can only be 'connectivities' or 'distances'")
    logg.info('computing moments based on ' + str(mode), r=True)
    connectivities = get_connectivities(adata, mode, n_neighbors=n_neighbors, recurse_neighbors=recurse_neighbors)
    adata.layers['Ms'] = csr_matrix.dot(connectivities, csr_matrix(adata.layers['spliced'])).astype(np.float32).A
    adata.layers['Mu'] = csr_matrix.dot(connectivities, csr_matrix(adata.layers['unspliced'])).astype(np.float32).A
    if renormalize:
        normalize_per_cell(adata, layers={'Ms', 'Mu'}, enforce=True)
    logg.info('    finished', time=True, end=' ' if settings.verbosity > 2 else '\n')
    logg.hint("added \n    'Ms' and 'Mu', moments of spliced/unspliced abundances (adata.layers)")
    return adata if copy else None

def get_host_from_service_info(service_info):
    host = None
    port = None
    if service_info and service_info.port and (service_info.server or service_info.address):
        if service_info.address:
            host = socket.inet_ntoa(service_info.address)
        else:
            host = service_info.server.lower()
        port = service_info.port
    return (host, port)

def configure_versioned_classes(self):
    for cls in self.pending_classes:
        self.audit_table(cls.__table__, cls.__versioned__.get('exclude'))
    assign_actor(self.base, self.transaction_cls, self.actor_cls)

def execute(self):
    cluster_name = self.params.cluster
    creator = make_creator(self.params.config, storage_path=self.params.storage)
    try:
        cluster = creator.load_cluster(cluster_name)
    except (ClusterNotFound, ConfigurationError) as err:
        log.error('Cannot stop cluster `%s`: %s', cluster_name, err)
        return os.EX_NOINPUT
    if not self.params.yes:
        confirm_or_abort('Do you want really want to stop cluster `{cluster_name}`?'.format(cluster_name=cluster_name), msg='Aborting upon user request.')
    print('Destroying cluster `%s` ...' % cluster_name)
    cluster.stop(force=self.params.force, wait=self.params.wait)

def find(self, func: Callable[[K, T], bool]) -> TOption[T]:
    for (k, v) in self.items():
        if func(k, v):
            return TOption(v)
    return TOption(None)

def apply_filters(stream, filters, lexer=None):

    def _apply(filter_, stream):
        for token in filter_.filter(lexer, stream):
            yield token
    for filter_ in filters:
        stream = _apply(filter_, stream)
    return stream

def wdiff(settings, wrap_with_html=False, fold_breaks=False, hard_breaks=False):
    diff = generate_wdiff(settings.org_file, settings.new_file, fold_breaks)
    if wrap_with_html:
        return wrap_content(diff, settings, hard_breaks)
    else:
        return diff

def _init_name_core(self, name: str):
    self.__regex = re.compile(f'^{self._pattern}$')
    self.name = name

def remove_key(self, store_key):
    if store_key in self._undefined_keys:
        del self._undefined_keys[store_key]
    if store_key in self._reverse_index:
        for value in self._reverse_index[store_key]:
            self._index[value].remove(store_key)
        del self._reverse_index[store_key]

def SmartUnicode(string):
    if isinstance(string, Text):
        return string
    if isinstance(string, bytes):
        return string.decode('utf-8', 'ignore')
    if compatibility.PY2:
        return str(string).__native__()
    else:
        return str(string)

