def _parent_value(children):
    covers = np.array([child['cover'] for child in children])
    covers /= np.sum(covers)
    leafs = np.array([child['leaf'] for child in children])
    return np.sum(leafs * covers)

def from_params(cls, params):
    key_fn = lambda x: id(x[1].owner)
    streams = []
    for (_, group) in groupby(sorted(params.items(), key=key_fn), key_fn):
        group = list(group)
        inst = [p.owner for (_, p) in group][0]
        if not isinstance(inst, param.Parameterized):
            continue
        names = [p.name for (_, p) in group]
        rename = {p.name: n for (n, p) in group}
        streams.append(cls(inst, names, rename=rename))
    return streams

def to_basis(self, basis=None, start=None, stop=None, step=None, undefined=None):
    if basis is None:
        if start is None:
            new_start = self.start
        else:
            new_start = start
        new_step = step or self.step
        new_stop = stop or self.stop
        steps = 1 + (new_stop - new_start) / new_step
        basis = np.linspace(new_start, new_stop, int(steps), endpoint=True)
    else:
        new_start = basis[0]
        new_step = basis[1] - basis[0]
    if undefined is None:
        undefined = np.nan
    else:
        undefined = undefined
    interp = interp1d(self.basis, self, bounds_error=False, fill_value=undefined)
    data = interp(basis)
    params = self.__dict__.copy()
    params['step'] = float(new_step)
    params['start'] = float(new_start)
    return Curve(data, params=params)

