def _parse_plot_quantity(self, quant, **kwargs):
    kwargs['quantity'] = False
    if callable(quant):
        return quant(self.t)

    def _eval(q):
        if q == 't':
            return self.time(self.t, **kwargs)
        elif q == 'Enorm':
            return self.E(self.t, **kwargs) / self.E(0.0, **kwargs)
        elif q == 'Eznorm':
            return self.Ez(self.t, **kwargs) / self.Ez(0.0, **kwargs)
        elif q == 'ERnorm':
            return self.ER(self.t, **kwargs) / self.ER(0.0, **kwargs)
        elif q == 'Jacobinorm':
            return self.Jacobi(self.t, **kwargs) / self.Jacobi(0.0, **kwargs)
        else:
            return self.__getattribute__(q)(self.t, **kwargs)
    try:
        return _eval(quant)
    except AttributeError:
        pass
    try:
        import numexpr
    except ImportError:
        raise ImportError('Parsing the quantity to be plotted failed; if you are trying to plot an expression, please make sure to install numexpr first')
    try:
        vars = numexpr.NumExpr(quant).input_names
    except TypeError as err:
        raise TypeError('Parsing the expression {} failed, with error message:\n"{}"'.format(quant, err))
    vars_dict = {}
    for var in vars:
        vars_dict[var] = _eval(var)
    return numexpr.evaluate(quant, local_dict=vars_dict)

def check_input(input_data, y=None, preprocessor=None, type_of_inputs='classic', tuple_size=None, accept_sparse=False, dtype='numeric', order=None, copy=False, force_all_finite=True, multi_output=False, ensure_min_samples=1, ensure_min_features=1, y_numeric=False, warn_on_dtype=False, estimator=None):
    context = make_context(estimator)
    args_for_sk_checks = dict(accept_sparse=accept_sparse, dtype=dtype, order=order, copy=copy, force_all_finite=force_all_finite, ensure_min_samples=ensure_min_samples, ensure_min_features=ensure_min_features, warn_on_dtype=warn_on_dtype, estimator=estimator)
    if y is None:
        input_data = check_array(input_data, ensure_2d=False, allow_nd=True, copy=False, force_all_finite=False, accept_sparse=True, dtype=None, ensure_min_features=0, ensure_min_samples=0)
