def read(self, length=None):
    if length is None:
        return self.reader.read()
    result = self.reader.read(length)
    if len(result) != length:
        raise BufferError('No more data left to read (need {}, got {}: {}); last read {}'.format(length, len(result), repr(result), repr(self._last)))
    self._last = result
    return result

def time(self, intervals=1, *args, _show_progress=True, _print=True, _collect_garbage=False, **kwargs):
    self.reset()
    self.num_intervals = intervals
    for func in self.progress(self._callables):
        try:
            t = Timer(func, _precision=self.precision, _parent_progressbar=self.progress)
            t.time(intervals, *args, _print=False, _show_progress=_show_progress, _collect_garbage=_collect_garbage, **kwargs)
        except Exception as e:
            print(RuntimeWarning('{} with {}'.format(colorize('{} failed'.format(Look.pretty_objname(func, color='yellow')), 'yellow'), repr(e))))
        self._callable_results.append(t)
        self.progress.update()
    self.info(_print=_print)
    return self.results

