def msg(*msg, v=4, time=False, memory=False, reset=False, end='\n', no_indent=False, t=None, m=None, r=None):
    if t is not None:
        time = t
    if m is not None:
        memory = m
    if r is not None:
        reset = r
    if isinstance(v, str):
        v = _VERBOSITY_LEVELS_FROM_STRINGS[v]
    if v == 3:
        msg = ('-->',) + msg
    if v >= 4 and (not no_indent):
        msg = ('   ',) + msg
    if _settings_verbosity_greater_or_equal_than(v):
        if not time and (not memory) and (len(msg) > 0):
            _write_log(*msg, end=end)
        if reset:
            try:
                (settings._previous_memory_usage, _) = get_memory_usage()
            except:
                pass
            settings._previous_time = get_time()
        if time:
            elapsed = get_passed_time()
            msg = msg + ('({})'.format(_sec_to_str(elapsed)),)
            _write_log(*msg, end=end)
        if memory:
            _write_log(get_memory_usage(), end=end)

def parse_incoming_query(factory, static_conditions=None, include_value=[], model_aggregations=dict()):

    def build_query(value, context, *args, **kwargs):

        def merge_conditions(static_conditions, q):
            subquery = factory(*static_conditions)
            return factory(q, query.Operator.AND, subquery, include_value=[])

        def merge_query_options(query, kwargs):
            if kwargs.get('include_value'):
                query.include_value.extend(kwargs['include_value'])
                query.reset()
            if kwargs.get('aggregate'):
                aggregate = list()
                for name in kwargs['aggregate']:
                    definition = model_aggregations[name]
                    aggregate.append((definition[1], definition[2]))
                query.aggregate = aggregate
            return query

        def store_in_context(query):
            context['query'] = query
            return query
        if static_conditions:
            d = defer.succeed(None)
            d.addCallback(static_conditions, context)
            d.addCallback(merge_conditions, kwargs['query'])
        else:
            d = defer.succeed(kwargs['query'])
        d.addCallback(merge_query_options, kwargs)
        d.addCallback(store_in_context)
        return d
    return build_query

def _generate_namespace_types(self, namespace, jazzy_cfg):
    ns_name = fmt_public_name(namespace.name)
    output_path = os.path.join('ApiObjects', ns_name)
    output_path_headers = os.path.join(output_path, 'Headers')
    for data_type in namespace.linearize_data_types():
        class_name = fmt_class_prefix(data_type)
        if self.args.documentation:
            append_to_jazzy_category_dict(jazzy_cfg, ns_name, class_name)
            append_to_jazzy_category_dict(jazzy_cfg, 'Serializers', '{}Serializer'.format(class_name))
        if is_struct_type(data_type):
            file_path = os.path.join(output_path_headers, class_name + '.h')
            with self.output_to_relative_path(file_path):
                self.emit_raw(base_file_comment)
                self._generate_struct_class_h(data_type)
        elif is_union_type(data_type):
            if self.args.documentation:
                append_to_jazzy_category_dict(jazzy_cfg, 'Tags', '{}Tag'.format(fmt_class_prefix(data_type)))
            file_path = os.path.join(output_path_headers, class_name + '.h')
            with self.output_to_relative_path(file_path):
                self.emit_raw(base_file_comment)
                self._generate_union_class_h(data_type)
        else:
            raise TypeError("Can't handle type %r" % type(data_type))
    file_path = os.path.join(output_path, 'DB{}Objects.m'.format(fmt_camel_upper(namespace.name)))
    with self.output_to_relative_path(file_path):
        self.emit_raw(base_file_comment)
        description = '/// Arguments, results, and errors for the `{}` namespace.'.format(fmt_camel_upper(namespace.name))
        self.emit(description)
        if self.args.exclude_from_analysis:
            self.emit()
            self.emit('#ifndef __clang_analyzer__')
        for data_type in namespace.linearize_data_types():
            if is_struct_type(data_type):
                self._generate_struct_class_m(data_type)
            elif is_union_type(data_type):
                self._generate_union_class_m(data_type)
        if self.args.exclude_from_analysis:
            self.emit('#endif')

def destroy(self, prefix_names=None):
    if prefix_names is None:
        self.destroy(prefix_names=self.prefixes.keys())
        return
    for prefix_name in prefix_names:
        if prefix_name == 'current' and self.current in prefix_names:
            continue
        elif prefix_name == 'current':
            prefix_name = self.current
        self.get_prefix(prefix_name).destroy()
        self.prefixes.pop(prefix_name)
        if self.prefixes:
            self._update_current()
    if not self.prefixes:
        shutil.rmtree(self.path)

