def fetch(self, multithread=True, median_kernel=5, solar_diam=740):

    def func_map(product):
        if 'halpha' in product:
            result = self.fetch_halpha(median_kernel=median_kernel)
        elif 'aia' in product:
            result = self.fetch_aia(product, median_kernel=median_kernel)
        elif 'l1b' in product:
            result = self.fetch_suvi_l1b(product, median_kernel=median_kernel)
        elif 'l2-ci' in product:
            result = self.fetch_suvi_composite(product, median_kernel=median_kernel)
        elif 'limb' in product:
            result = self.fetch_limb(solar_diam)
        else:
            raise ValueError('{} is not a valid product.'.format(product))
        return result
    if multithread:
        pool = ThreadPool()
        results = pool.map(func_map, self.products)
    else:
        results = [func_map(product) for product in self.products]
    results = {product: (head, data) for (product, head, data) in results}
    return results

def ConfigureUrls(config, external_hostname=None):
    print('\n\n-=GRR URLs=-\nFor GRR to work each client has to be able to communicate with the\nserver. To do this we normally need a public dns name or IP address\nto communicate with. In the standard configuration this will be used\nto host both the client facing server and the admin user interface.\n')
    existing_ui_urn = grr_config.CONFIG.Get('AdminUI.url', default=None)
    existing_frontend_urns = grr_config.CONFIG.Get('Client.server_urls')
    if not existing_frontend_urns:
        existing_control_urns = grr_config.CONFIG.Get('Client.control_urls', default=None)
        if existing_control_urns is not None:
            existing_frontend_urns = []
            for existing_control_urn in existing_control_urns:
                if not existing_control_urn.endswith('control'):
                    raise RuntimeError('Invalid existing control URL: %s' % existing_control_urn)
                existing_frontend_urns.append(existing_control_urn.rsplit('/', 1)[0] + '/')
            config.Set('Client.server_urls', existing_frontend_urns)
            config.Set('Client.control_urls', ['deprecated use Client.server_urls'])
    if not existing_frontend_urns or not existing_ui_urn:
        ConfigureHostnames(config, external_hostname=external_hostname)
    else:
        print('Found existing settings:\n  AdminUI URL: %s\n  Frontend URL(s): %s\n' % (existing_ui_urn, existing_frontend_urns))
        if not RetryBoolQuestion('Do you want to keep this configuration?', True):
            ConfigureHostnames(config, external_hostname=external_hostname)

def normalize_per_cell(data, counts_per_cell_after=None, counts_per_cell=None, key_n_counts=None, max_proportion_per_cell=None, use_initial_size=True, layers=['spliced', 'unspliced'], enforce=False, copy=False):
    adata = data.copy() if copy else data
    layers = adata.layers.keys() if layers is 'all' else [layers] if isinstance(layers, str) else [layer for layer in layers if layer in adata.layers.keys()]
    layers = ['X'] + layers
    modified_layers = []
    for layer in layers:
        X = adata.X if layer is 'X' else adata.layers[layer]
        if not_yet_normalized(X) or enforce:
            counts = counts_per_cell if counts_per_cell is not None else get_initial_size(adata, layer) if use_initial_size else get_size(adata, layer)
            if max_proportion_per_cell is not None and 0 < max_proportion_per_cell < 1:
                counts = counts_per_cell_quantile(X, max_proportion_per_cell, counts)
            counts_after = np.median(counts) if counts_per_cell_after is None else counts_per_cell_after
            counts /= counts_after + (counts_after == 0)
            counts += counts == 0
            if issparse(X):
                sparsefuncs.inplace_row_scale(X, 1 / counts)
            else:
                X /= np.array(counts[:, None])
            modified_layers.append(layer)
    adata.obs['n_counts' if key_n_counts is None else key_n_counts] = get_size(adata)
    if len(modified_layers) > 0:
        logg.info('Normalized count data:', ', '.join(modified_layers) + '.')
    return adata if copy else None

