def _builder_reprs(cls, options, namespace=None, ns=None):
    if isinstance(options, basestring):
        from .parser import OptsSpec
        if ns is None:
            try:
                ns = get_ipython().user_ns
            except:
                ns = globals()
        options = options.replace('%%opts', '').replace('%opts', '')
        options = OptsSpec.parse_options(options, ns=ns)
    reprs = []
    ns = '{namespace}.'.format(namespace=namespace) if namespace else ''
    for option in options:
        kws = ', '.join(('%s=%r' % (k, option.kwargs[k]) for k in sorted(option.kwargs)))
        if '.' in option.key:
            element = option.key.split('.')[0]
            spec = repr('.'.join(option.key.split('.')[1:])) + ', '
        else:
            element = option.key
            spec = ''
        opts_format = '{ns}opts.{element}({spec}{kws})'
        reprs.append(opts_format.format(ns=ns, spec=spec, kws=kws, element=element))
    return reprs

def download(self, path, chunksize=None, chunk_callback=lambda _: False):
    chunksize = chunksize or self.chunksize
    (bucket, obj) = self._path_to_bucket_and_key(path)
    with tempfile.NamedTemporaryFile(delete=False) as fp:
        return_fp = _DeleteOnCloseFile(fp.name, 'r')
        result = self.client.objects().get(bucket=bucket, object=obj).execute()
        if int(result['size']) == 0:
            return return_fp
        request = self.client.objects().get_media(bucket=bucket, object=obj)
        downloader = http.MediaIoBaseDownload(fp, request, chunksize=chunksize)
        attempts = 0
        done = False
        while not done:
            error = None
            try:
                (_, done) = downloader.next_chunk()
                if chunk_callback(fp):
                    done = True
            except errors.HttpError as err:
                error = err
                if err.resp.status < 500:
                    raise
                logger.warning('Error downloading file, retrying', exc_info=True)
            except RETRYABLE_ERRORS as err:
                logger.warning('Error downloading file, retrying', exc_info=True)
                error = err
            if error:
                attempts += 1
                if attempts >= NUM_RETRIES:
                    raise error
            else:
                attempts = 0
    return return_fp

