def add_headers(width=80, title='Untitled', subtitle='', author='', email='', description='', tunings=[]):
    result = ['']
    title = str.upper(title)
    result += [str.center('  '.join(title), width)]
    if subtitle != '':
        result += ['', str.center(str.title(subtitle), width)]
    if author != '' or email != '':
        result += ['', '']
        if email != '':
            result += [str.center('Written by: %s <%s>' % (author, email), width)]
        else:
            result += [str.center('Written by: %s' % author, width)]
    if description != '':
        result += ['', '']
        words = description.split()
        lines = []
        line = []
        last = 0
        for word in words:
            if len(word) + last < width - 10:
                line.append(word)
                last += len(word) + 1
            else:
                lines.append(line)
                line = [word]
                last = len(word) + 1
        lines.append(line)
        for line in lines:
            result += [str.center(' '.join(line), width)]
    if tunings != []:
        result += ['', '', str.center('Instruments', width)]
        for (i, tuning) in enumerate(tunings):
            result += ['', str.center('%d. %s' % (i + 1, tuning.instrument), width), str.center(tuning.description, width)]
    result += ['', '']
    return result

def pairwise_distances(dist_list, earth_mover_dist=True, energy_dist=True):
    out = []
    index = []
    for (i, samp_i) in enumerate(dist_list):
        for (j, samp_j) in enumerate(dist_list):
            if j < i:
                index.append(str((i, j)))
                out.append(statistical_distances(samp_i, samp_j, earth_mover_dist=earth_mover_dist, energy_dist=energy_dist))
    columns = ['ks pvalue', 'ks distance']
    if earth_mover_dist:
        columns.append('earth mover distance')
    if energy_dist:
        columns.append('energy distance')
    ser = pd.DataFrame(out, index=index, columns=columns).unstack()
    ser.index.names = ['calculation type', 'run']
    return ser

