def prune(A, threshold):
    if isinstance(A, Poly):
        B = A.A.copy()
        for key in A.keys:
            values = B[key].copy()
            values[numpy.abs(values) < threshold] = 0.0
            B[key] = values
        return Poly(B, A.dim, A.shape, A.dtype)
    A = A.copy()
    A[numpy.abs(A) < threshold] = 0.0
    return A

def _lookahead_token(self, count=1):
    stack = []
    next_token = None
    while count > 0:
        item = self._lexer.get_token()
        if not item:
            break
        stack.append(item)
        count -= 1
    while stack:
        (line_no, token) = stack.pop()
        if not next_token:
            next_token = token
        self._lexer.push_token(line_no, token)
    return next_token

