def _clean_code(code):
    lines = []
    for l in code.splitlines():
        if l.endswith('.'):
            l = l[:-1]
        if 'VALUE' in l:
            l = l[:l.find('VALUE')]
        indent = len(l) - len(l.lstrip())
        tokens = l.split(' ')
        while '' in tokens:
            tokens.remove('')
        if tokens and (not tokens[-1].endswith('.')):
            tokens[-1] += '.'
        lines.append(' ' * indent + ' '.join(tokens))
    return lines

