def _parse_frange_part(frange):
    match = FRANGE_RE.match(frange)
    if not match:
        msg = 'Could not parse "{0}": did not match {1}'
        raise ParseException(msg.format(frange, FRANGE_RE.pattern))
    (start, end, modifier, chunk) = match.groups()
    start = int(start)
    end = int(end) if end is not None else start
    if end > start and chunk is not None and (int(chunk) < 0):
        msg = 'Could not parse "{0}: chunk can not be negative'
        raise ParseException(msg.format(frange))
    chunk = abs(int(chunk)) if chunk is not None else 1
    if chunk == 0:
        msg = 'Could not parse "{0}": chunk cannot be 0'
        raise ParseException(msg.format(frange))
    return (start, end, modifier, chunk)

def getTreeBuilder(treeType, implementation=None, **kwargs):
    treeType = treeType.lower()
    if treeType not in treeBuilderCache:
        if treeType == 'dom':
            from . import dom
            if implementation is None:
                from xml.dom import minidom
                implementation = minidom
            return dom.getDomModule(implementation, **kwargs).TreeBuilder
        elif treeType == 'lxml':
            from . import etree_lxml
            treeBuilderCache[treeType] = etree_lxml.TreeBuilder
        elif treeType == 'etree':
            from . import etree
            if implementation is None:
                implementation = default_etree
            return etree.getETreeModule(implementation, **kwargs).TreeBuilder
        else:
            raise ValueError('Unrecognised treebuilder "%s" ' % treeType)
    return treeBuilderCache.get(treeType)

def _accept_responses(self, expected_header, info_cb, timeout_ms=None):
    while True:
        response = self.usb.read(64, timeout_ms=timeout_ms)
        header = response[:4]
        remaining = response[4:]
        if header == 'INFO':
            info_cb(FastbootMessage(remaining, header))
        elif header in self.FINAL_HEADERS:
            if header != expected_header:
                raise usb_exceptions.FastbootStateMismatch('Expected %s, got %s', expected_header, header)
            if header == 'OKAY':
                info_cb(FastbootMessage(remaining, header))
            return remaining
        elif header == 'FAIL':
            info_cb(FastbootMessage(remaining, header))
            raise usb_exceptions.FastbootRemoteFailure('FAIL: %s', remaining)
        else:
            raise usb_exceptions.FastbootInvalidResponse('Got unknown header %s and response %s', header, remaining)

