def mb_neg_loglik(self, beta, mini_batch):
    rand_int = np.random.randint(low=0, high=self.data.shape[0] - mini_batch - self.max_lag + 1)
    sample = np.arange(start=rand_int, stop=rand_int + mini_batch)
    (_, _, _, F, v) = self._model(self.data[sample], beta)
    loglik = 0.0
    for i in range(0, len(sample)):
        loglik += np.linalg.slogdet(F[:, :, i])[1] + np.dot(v[i], np.dot(np.linalg.pinv(F[:, :, i]), v[i]))
    return -(-(len(sample) / 2 * np.log(2 * np.pi)) - 0.5 * loglik.T[0].sum())

def comparison(self):
    node = self.expr()
    while self.token.nature in (Nature.EQ, Nature.NE, Nature.LE, Nature.GE, Nature.LT, Nature.GT):
        token = self.token
        if token.nature == Nature.EQ:
            self._process(Nature.EQ)
        elif token.nature == Nature.NE:
            self._process(Nature.NE)
        elif token.nature == Nature.LE:
            self._process(Nature.LE)
        elif token.nature == Nature.GE:
            self._process(Nature.GE)
        elif token.nature == Nature.LT:
            self._process(Nature.LT)
        elif token.nature == Nature.GT:
            self._process(Nature.GT)
        else:
            self.error()
        node = BinaryOperation(left=node, op=token, right=self.expr())
    return node

