def transformer_autoencoder(inputs, targets, target_space, hparams, cache=None, predict_mask=1.0):
    original_targets_shape = common_layers.shape_list(targets)
    batch_size = original_targets_shape[0]
    if len(original_targets_shape) == 4:
        compress_fn = compress_encoder_2d
        decompress_fn = decompress_decoder_2d
    else:
        compress_fn = compress_encoder_1d
        decompress_fn = decompress_decoder_1d
    ed_attention_bias = None
    if inputs is not None:
        (inputs, ed_attention_bias) = transformer_text_encoder(inputs, target_space, hparams, name='input_encoder')
    losses = {'extra': 0.0, 'extra_loss': 0.0, 'latent_pred': 0.0}
    if hparams.mode != tf.estimator.ModeKeys.PREDICT:
        targets_compressed = compress_fn(targets, hparams, name='compress')
        if hparams.mode == tf.estimator.ModeKeys.TRAIN:
            scale = common_layers.inverse_exp_decay(hparams.startup_steps)
        else:
            scale = 1.0
        scale = tf.to_float(tf.less(tf.random_uniform([batch_size]), scale))
        (latents_dense, latents_discrete, extra_loss, _) = bottleneck_layer(targets_compressed, hparams)
        extra_loss = scale * tf.reduce_mean(extra_loss)
        (_, latents_pred_loss) = latent_prediction_model(inputs, ed_attention_bias, latents_discrete, latents_dense, hparams, name='latent_pred')
        latent_time = tf.less(hparams.mask_startup_steps, tf.to_int32(tf.train.get_global_step()))
        latents_pred_loss = scale * tf.reduce_mean(latents_pred_loss)
        latents_pred_loss *= tf.to_float(latent_time)
        latents_dense_shape = common_layers.shape_list(latents_dense)
        latents_dense = tf.nn.dropout(latents_dense, keep_prob=1 - hparams.latent_dropout, noise_shape=[latents_dense_shape[0], latents_dense_shape[1], 1])
        losses = {'extra': 0.0, 'extra_loss': extra_loss, 'latent_pred': latents_pred_loss}
    else:
        latent_len = hparams.img_len * hparams.img_len * hparams.num_latents / 2 ** hparams.num_compress_steps
        (_, _, _, embed_fn) = bottleneck_layer(targets_compressed, hparams)
        latents_dense = tf.zeros([batch_size, latent_len, 1, hparams.hidden_size])
        if cache is None:
            cache = ae_latent_sample_beam(latents_dense, inputs, ed_attention_bias, embed_fn, hparams)
        cache_one_hot = tf.one_hot(cache, depth=2 ** hparams.bottleneck_bits)
        latents_dense = embed_fn(cache_one_hot, hparams.hidden_size)
    if len(original_targets_shape) == 4:
        compressed_img_len = hparams.img_len // 2 ** (hparams.num_compress_steps // 2)
        latents_dense = tf.reshape(latents_dense, [batch_size, compressed_img_len, compressed_img_len, hparams.num_latents * hparams.hidden_size])
    latents_dense = decompress_fn(latents_dense, hparams, name='decompress')
    latents_dense = tf.reshape(latents_dense, [-1, hparams.img_len, hparams.img_len, hparams.hidden_size])
    if hparams.use_gold_targets:
        if hparams.mode == tf.estimator.ModeKeys.PREDICT:
            masking = predict_mask
        else:
            masking = common_layers.inverse_exp_decay(hparams.mask_startup_steps)
        (targets, _, _) = cia.maybe_reshape_4d_to_3d(targets)
        mask = tf.less(masking, tf.random_uniform(common_layers.shape_list(targets)[:-1]))
        mask = tf.expand_dims(tf.to_float(mask), 2)
        latents_dense = mask * targets + (1.0 - mask) * latents_dense
    latents_dense = tf.reshape(latents_dense, original_targets_shape)
    if hparams.decode_autoregressive:
        decoder_output = transformer_image_decoder(latents_dense, inputs, ed_attention_bias, hparams, name='decoder')
    else:
        decoder_output = latents_dense
    return (decoder_output, losses, cache)

def apply_cloud_providers_config(overrides, defaults=None):
    if defaults is None:
        defaults = PROVIDER_CONFIG_DEFAULTS
    config = defaults.copy()
    if overrides:
        config.update(overrides)
    for (name, settings) in six.iteritems(config.copy()):
        if '.' in name:
            log.warning('Please switch to the new providers configuration syntax')
            config = old_to_new(config)
            for (prov_name, prov_settings) in six.iteritems(config.pop('providers')):
                config[prov_name] = prov_settings
            break
    providers = {}
    ext_count = 0
    for (key, val) in six.iteritems(config):
        if key in ('conf_file', 'include', 'default_include', 'user'):
            continue
        if not isinstance(val, (list, tuple)):
            val = [val]
        else:
            handled_providers = set()
            for details in val:
                if 'driver' not in details:
                    if 'extends' not in details:
                        log.error("Please check your cloud providers configuration. There's no 'driver' nor 'extends' definition referenced.")
                    continue
                if details['driver'] in handled_providers:
                    log.error("You can only have one entry per cloud provider. For example, if you have a cloud provider configuration section named, 'production', you can only have a single entry for EC2, Joyent, Openstack, and so forth.")
                    raise salt.exceptions.SaltCloudConfigError("The cloud provider alias '{0}' has multiple entries for the '{1[driver]}' driver.".format(key, details))
                handled_providers.add(details['driver'])
        for entry in val:
            if 'driver' not in entry:
                entry['driver'] = '-only-extendable-{0}'.format(ext_count)
                ext_count += 1
            if key not in providers:
                providers[key] = {}
            provider = entry['driver']
            if provider not in providers[key]:
                providers[key][provider] = entry
    while True:
        keep_looping = False
        for (provider_alias, entries) in six.iteritems(providers.copy()):
            for (driver, details) in six.iteritems(entries):
                providers[provider_alias][driver]['profiles'] = {}
                if 'extends' not in details:
                    continue
                extends = details.pop('extends')
                if ':' in extends:
                    (alias, provider) = extends.split(':')
                    if alias not in providers:
                        raise salt.exceptions.SaltCloudConfigError("The '{0}' cloud provider entry in '{1}' is trying to extend data from '{2}' though '{2}' is not defined in the salt cloud providers loaded data.".format(details['driver'], provider_alias, alias))
                    if provider not in providers.get(alias):
                        raise salt.exceptions.SaltCloudConfigError("The '{0}' cloud provider entry in '{1}' is trying to extend data from '{2}:{3}' though '{3}' is not defined in '{1}'".format(details['driver'], provider_alias, alias, provider))
                    details['extends'] = '{0}:{1}'.format(alias, provider)
                    details['driver'] = provider
                elif providers.get(extends):
                    raise salt.exceptions.SaltCloudConfigError("The '{0}' cloud provider entry in '{1}' is trying to extend from '{2}' and no provider was specified. Not extending!".format(details['driver'], provider_alias, extends))
                elif extends not in providers:
                    raise salt.exceptions.SaltCloudConfigError("The '{0}' cloud provider entry in '{1}' is trying to extend data from '{2}' though '{2}' is not defined in the salt cloud providers loaded data.".format(details['driver'], provider_alias, extends))
                elif driver in providers.get(extends):
                    details['extends'] = '{0}:{1}'.format(extends, driver)
                elif '-only-extendable-' in providers.get(extends):
                    details['extends'] = '{0}:{1}'.format(extends, '-only-extendable-{0}'.format(ext_count))
                else:
                    details['extends'] = extends
                    keep_looping = True
        if not keep_looping:
            break
    while True:
        keep_looping = False
        for (alias, entries) in six.iteritems(providers.copy()):
            for (driver, details) in six.iteritems(entries):
                if 'extends' not in details:
                    continue
                if 'extends' in details['extends']:
                    keep_looping = True
                    continue
                extends = details.pop('extends')
                (ext_alias, ext_driver) = extends.split(':')
                extended = providers.get(ext_alias).get(ext_driver).copy()
                extended = salt.utils.dictupdate.update(extended, details)
                providers[alias][driver] = extended
                if driver.startswith('-only-extendable-'):
                    providers[alias][ext_driver] = providers[alias][driver]
                    del providers[alias][driver]
        if not keep_looping:
            break
    for (provider_alias, entries) in six.iteritems(providers.copy()):
        for (driver, details) in six.iteritems(entries.copy()):
            if not driver.startswith('-only-extendable-'):
                continue
            log.info("There's at least one cloud driver under the '%s' cloud provider alias which does not have the required 'driver' setting. Removing it from the available providers listing.", provider_alias)
            providers[provider_alias].pop(driver)
        if not providers[provider_alias]:
            providers.pop(provider_alias)
    return providers

