        self.owner.start_event()
        while True:
            while not self.incoming:
                time.sleep(0.01)
            while self.incoming:
                command = self.incoming.popleft()
                if command is None:
                    raise StopIteration()
                command()
    except StopIteration:
        pass
    self.owner.stop_event()

