def _seconds_to_HHMMSS(seconds):
    less_than_second = seconds - floor(seconds)
    (minutes, seconds) = divmod(floor(seconds), 60)
    (hours, minutes) = divmod(minutes, 60)
    return '{}H{}M{}S.{}'.format(hours, minutes, seconds, less_than_second)

