def searchsorted(arr, value, side='left', sorter=None):
    if sorter is not None:
        sorter = ensure_platform_int(sorter)
    if isinstance(arr, np.ndarray) and is_integer_dtype(arr) and (is_integer(value) or is_integer_dtype(value)):
        from .arrays.array_ import array
        iinfo = np.iinfo(arr.dtype.type)
        value_arr = np.array([value]) if is_scalar(value) else np.array(value)
        if (value_arr >= iinfo.min).all() and (value_arr <= iinfo.max).all():
            dtype = arr.dtype
        else:
            dtype = value_arr.dtype
        if is_scalar(value):
            value = dtype.type(value)
        else:
            value = array(value, dtype=dtype)
    elif not (is_object_dtype(arr) or is_numeric_dtype(arr) or is_categorical_dtype(arr)):
        from pandas.core.series import Series
        value_ser = Series(value)._values
        value = value_ser[0] if is_scalar(value) else value_ser
    result = arr.searchsorted(value, side=side, sorter=sorter)
    return result

def _routes_updated(self, ri):
    new_routes = ri.router['routes']
    old_routes = ri.routes
    (adds, removes) = bc.common_utils.diff_list_of_dict(old_routes, new_routes)
    for route in adds:
        LOG.debug("Added route entry is '%s'", route)
        for del_route in removes:
            if route['destination'] == del_route['destination']:
                removes.remove(del_route)
        driver = self.driver_manager.get_driver(ri.id)
        driver.routes_updated(ri, 'replace', route)
    for route in removes:
        LOG.debug("Removed route entry is '%s'", route)
        driver = self.driver_manager.get_driver(ri.id)
        driver.routes_updated(ri, 'delete', route)
    ri.routes = new_routes

def ebic(self, gamma=0):
    if not self.is_fitted_:
        return
    if not isinstance(self.precision_, list):
        return metrics.ebic(self.sample_covariance_, self.precision_, self.n_samples_, self.n_features_, gamma=gamma)
    ebic_scores = []
    for (lidx, lam) in enumerate(self.path_):
        ebic_scores.append(metrics.ebic(self.sample_covariance_, self.precision_[lidx], self.n_samples_, self.n_features_, gamma=gamma))
    return np.array(ebic_scores)

