def load_fixture(filename, kind, post_processor=None):

    def _load(od, kind, post_processor, parent=None, presets={}):
        if hasattr(kind, 'keys'):
            objtype = kind[od['__kind__']]
        else:
            objtype = kind
        obj_id = od.get('__id__')
        if obj_id is not None:
            obj = objtype(id=obj_id, parent=parent)
        else:
            obj = objtype(parent=parent)
        for attribute_name in [k for k in od.keys() if not k.startswith('__') and (not k.endswith('__'))] + presets.keys():
            attribute_type = objtype.__dict__[attribute_name]
            attribute_value = _sensible_value(attribute_type, presets.get(attribute_name, od.get(attribute_name)))
            obj.__dict__['_values'][attribute_name] = attribute_value
        if post_processor:
            post_processor(obj)
        obj.put()
        loaded = [obj]
        for item in od.get('__children__', []):
            loaded.extend(_load(item, kind, post_processor, parent=obj.key))
        for child_attribute_name in [k for k in od.keys() if k.startswith('__children__') and k != '__children__']:
            attribute_name = child_attribute_name.split('__')[-2]
            for child in od[child_attribute_name]:
                loaded.extend(_load(child, kind, post_processor, presets={attribute_name: obj.key}))
        return loaded
    tree = json.load(open(filename))
    loaded = []
    for item in tree:
        loaded.extend(_load(item, kind, post_processor))
    return loaded

def parse_baxter(reading):
    initial = ''
    medial = ''
    final = ''
    tone = ''
    inienv = True
    medienv = False
    finenv = False
    tonenv = False
    inichars = "pbmrtdnkgnsyhzl'x"
    chars = list(reading)
    for char in chars:
        if char in 'jw' and (not finenv):
            (inienv, medienv, finenv, tonenv) = (False, True, False, False)
        elif char not in inichars or finenv:
            if char in 'XH':
                (inienv, medienv, finenv, tonenv) = (False, False, False, True)
            else:
                (inienv, medienv, finenv, tonenv) = (False, False, True, False)
        if inienv:
            initial += char
        if medienv:
            medial += char
        if finenv:
            final += char
        if tonenv:
            tone += char
    if not tone and final[-1] in 'ptk':
        tone = 'R'
    elif not tone:
        tone = 'P'
    if 'j' not in medial and 'y' in initial:
        medial += 'j'
    if final[0] in 'u' and 'w' not in medial:
        medial = 'w' + medial
    return (initial, medial, final, tone)

