            if old_symbol == DITHER_TYPES[dither][1][0]:
                c2 = c1
            sorted_index = sorted_palette.index(c2)
            if sorted_index > len(sorted_palette) // 2:
                c1 = sorted_palette[0]
            else:
                c1 = sorted_palette[-1]
    cb.put(x, y, symbol, c1(), c2())

