def sign(s, passphrase, sig_format=SER_COMPACT, curve='secp160r1'):
    if isinstance(s, six.text_type):
        raise ValueError('Encode `s` to a bytestring yourself to' + ' prevent problems with different default encodings')
    curve = Curve.by_name(curve)
    privkey = curve.passphrase_to_privkey(passphrase)
    return privkey.sign(hashlib.sha512(s).digest(), sig_format)

def state_likelihood(self, beta, alpha):
    (_, _, _, Q) = self._ss_matrices(beta)
    residuals_1 = alpha[0][1:alpha[0].shape[0]] - alpha[0][0:alpha[0].shape[0] - 1]
    residuals_2 = alpha[1][1:alpha[1].shape[0]] - alpha[1][0:alpha[1].shape[0] - 1]
    return np.sum(ss.norm.logpdf(residuals_1, loc=0, scale=np.power(Q[0][0], 0.5))) + np.sum(ss.norm.logpdf(residuals_2, loc=0, scale=np.power(Q[1][1], 0.5)))

def squish(incs, f):
    incs = np.radians(incs)
    I_o = f * np.tan(incs)
    return np.degrees(np.arctan(I_o))

