def variation_san(self, variation: Iterable[Move]) -> str:
    board = self.copy(stack=False)
    san = []
    for move in variation:
        if not board.is_legal(move):
            raise ValueError('illegal move {} in position {}'.format(move, board.fen()))
        if board.turn == WHITE:
            san.append('{}. {}'.format(board.fullmove_number, board.san(move)))
        elif not san:
            san.append('{}...{}'.format(board.fullmove_number, board.san(move)))
        else:
            san.append(board.san(move))
        board.push(move)
    return ' '.join(san)

def maf(genotypes):
    warnings.warn("deprecated: use 'Genotypes.maf'", DeprecationWarning)
    g = genotypes.genotypes
    maf = np.nansum(g) / (2 * np.sum(~np.isnan(g)))
    if maf > 0.5:
        maf = 1 - maf
        return (maf, False)
    return (maf, True)

