    print('')
    if prompt_ask in ('K', 'k'):
        self.keep()
    elif prompt_ask in ('O', 'o'):
        self._overwrite(n)
    elif prompt_ask in ('R', 'r'):
        self._remove(n)
    elif prompt_ask in ('D', 'd'):
        self.diff(n)
        self.i -= 1
    elif prompt_ask in ('M', 'm'):
        self.merge(n)
    elif prompt_ask in ('Q', 'q', 'quit'):
        self.quit()

