def _lower_non_existent_context_field_filters(match_traversals, visitor_fn):
    new_match_traversals = []
    for match_traversal in match_traversals:
        new_match_traversal = []
        for step in match_traversal:
            if step.where_block is not None:
                new_filter = step.where_block.visit_and_update_expressions(visitor_fn)
                if new_filter.predicate == TrueLiteral:
                    new_filter = None
                new_step = step._replace(where_block=new_filter)
            else:
                new_step = step
            new_match_traversal.append(new_step)
        new_match_traversals.append(new_match_traversal)
    return new_match_traversals

def good_sequences_to_track(flow, motion_threshold=1.0):
    endpoints = []
    in_low = False
    for (i, val) in enumerate(flow):
        if val < motion_threshold:
            if not in_low:
                endpoints.append(i)
                in_low = True
        else:
            if in_low:
                endpoints.append(i - 1)
            in_low = False

    def mean_score_func(m):
        mu = 15
        sigma = 8
        top_val = normpdf(mu, mu, sigma)
        return normpdf(m, mu, sigma) / top_val

    def max_score_func(m):
        mu = 40
        sigma = 8
        if m <= mu:
            return 1.0
        else:
            top_val = normpdf(mu, mu, sigma)
            return normpdf(m, mu, sigma) / top_val

    def length_score_func(l):
        mu = 30
        sigma = 10
        top_val = normpdf(mu, mu, sigma)
        return normpdf(l, mu, sigma) / top_val
    min_length = 5
    sequences = []
    for (k, i) in enumerate(endpoints[:-1]):
        for j in endpoints[k + 1:]:
            length = j - i
            if length < min_length:
                continue
            seq = flow[i:j + 1]
            m_score = mean_score_func(np.mean(seq))
            mx_score = max_score_func(np.max(seq))
            l_score = length_score_func(length)
            logger.debug('%d, %d scores: (mean=%.5f, max=%.5f, length=%.5f)' % (i, j, m_score, mx_score, l_score))
            if min(m_score, mx_score, l_score) < 0.2:
                continue
            score = m_score + mx_score + l_score
            sequences.append((i, j, score))
    return sorted(sequences, key=lambda x: x[2], reverse=True)

