def _process_incoming_iq(self, stanza_obj):
    self._logger.debug('incoming iq: %r', stanza_obj)
    if stanza_obj.type_.is_response:
        self._logger.debug('iq is response')
        keys = [(stanza_obj.from_, stanza_obj.id_)]
        if self._local_jid is not None:
            if keys[0][0] == self._local_jid:
                keys.append((None, keys[0][1]))
            elif keys[0][0] is None:
                keys.append((self._local_jid, keys[0][1]))
        for key in keys:
            try:
                self._iq_response_map.unicast(key, stanza_obj)
                self._logger.debug('iq response delivered to key %r', key)
                break
            except KeyError:
                pass
        else:
            self._logger.warning('unexpected IQ response: from=%r, id=%r', *key)
    else:
        self._logger.debug('iq is request')
        key = (stanza_obj.type_, type(stanza_obj.payload))
        try:
            (coro, with_send_reply) = self._iq_request_map[key]
        except KeyError:
            self._logger.warning('unhandleable IQ request: from=%r, type_=%r, payload=%r', stanza_obj.from_, stanza_obj.type_, stanza_obj.payload)
            response = stanza_obj.make_reply(type_=structs.IQType.ERROR)
            response.error = stanza.Error(condition=errors.ErrorCondition.SERVICE_UNAVAILABLE)
            self._enqueue(response)
            return
        args = [stanza_obj]
        if with_send_reply:

            def send_reply(result=None):
                nonlocal task, stanza_obj, send_reply_callback
                if task.done():
                    raise RuntimeError('send_reply called after the handler is done')
                if task.remove_done_callback(send_reply_callback) == 0:
                    raise RuntimeError('send_reply called more than once')
                task.add_done_callback(self._iq_request_coro_done_check)
                self._send_iq_reply(stanza_obj, result)
            args.append(send_reply)
        try:
            awaitable = coro(*args)
        except Exception as exc:
            awaitable = asyncio.Future()
            awaitable.set_exception(exc)
        task = asyncio.ensure_future(awaitable)
        send_reply_callback = functools.partial(self._iq_request_coro_done_send_reply, stanza_obj)
        task.add_done_callback(self._iq_request_coro_done_remove_task)
        task.add_done_callback(send_reply_callback)
        self._iq_request_tasks.append(task)
        self._logger.debug('started task to handle request: %r', task)

def ingest(self, co, classname=None, code_objects={}, show_asm=None):
    if not show_asm:
        show_asm = self.show_asm
    bytecode = self.build_instructions(co)
    if show_asm in ('both', 'before'):
        for instr in bytecode.get_instructions(co):
            print(instr.disassemble())
    tokens = []
    customize = {}
    if self.is_pypy:
        customize['PyPy'] = 0
    codelen = len(self.code)
    (free, names, varnames) = self.unmangle_code_names(co, classname)
    self.names = names
    self.load_asserts = set()
    for i in self.op_range(0, codelen):
        if self.is_pypy:
            have_pop_jump = self.code[i] in (self.opc.PJIF, self.opc.PJIT)
        else:
            have_pop_jump = self.code[i] == self.opc.PJIT
        if have_pop_jump and self.code[i + 3] == self.opc.LOAD_GLOBAL:
            if names[self.get_argument(i + 3)] == 'AssertionError':
                self.load_asserts.add(i + 3)
    load_asserts_save = copy(self.load_asserts)
    jump_targets = self.find_jump_targets(show_asm)
    self.load_asserts = load_asserts_save
    last_stmt = self.next_stmt[0]
    i = self.next_stmt[last_stmt]
    replace = {}
    while i < codelen - 1:
        if self.lines[last_stmt].next > i:
            if self.code[last_stmt] == self.opc.PRINT_ITEM:
                if self.code[i] == self.opc.PRINT_ITEM:
                    replace[i] = 'PRINT_ITEM_CONT'
                elif self.code[i] == self.opc.PRINT_NEWLINE:
                    replace[i] = 'PRINT_NEWLINE_CONT'
        last_stmt = i
        i = self.next_stmt[i]
    extended_arg = 0
    for offset in self.op_range(0, codelen):
        if offset in jump_targets:
            jump_idx = 0
            for jump_offset in sorted(jump_targets[offset], reverse=True):
                come_from_name = 'COME_FROM'
                op_name = self.opname_for_offset(jump_offset)
                if op_name.startswith('SETUP_') and self.version == 2.7:
                    come_from_type = op_name[len('SETUP_'):]
                    if come_from_type not in ('LOOP', 'EXCEPT'):
                        come_from_name = 'COME_FROM_%s' % come_from_type
                    pass
                tokens.append(Token(come_from_name, jump_offset, repr(jump_offset), offset='%s_%d' % (offset, jump_idx), has_arg=True))
                jump_idx += 1
                pass
        op = self.code[offset]
        op_name = self.op_name(op)
        oparg = None
        pattr = None
        has_arg = op_has_argument(op, self.opc)
        if has_arg:
            oparg = self.get_argument(offset) + extended_arg
            extended_arg = 0
            if op == self.opc.EXTENDED_ARG:
                extended_arg += self.extended_arg_val(oparg)
                continue
            if op in self.opc.CONST_OPS:
                const = co.co_consts[oparg]
                if iscode(const):
                    oparg = const
                    if const.co_name == '<lambda>':
                        assert op_name == 'LOAD_CONST'
                        op_name = 'LOAD_LAMBDA'
                    elif const.co_name == '<genexpr>':
                        op_name = 'LOAD_GENEXPR'
                    elif const.co_name == '<dictcomp>':
                        op_name = 'LOAD_DICTCOMP'
                    elif const.co_name == '<setcomp>':
                        op_name = 'LOAD_SETCOMP'
                    pattr = '<code_object ' + const.co_name + '>'
                else:
                    if oparg < len(co.co_consts):
                        (argval, _) = _get_const_info(oparg, co.co_consts)
                    pattr = const
                    pass
            elif op in self.opc.NAME_OPS:
                pattr = names[oparg]
            elif op in self.opc.JREL_OPS:
                if self.version == 2.7:
                    self.patch_continue(tokens, offset, op)
                pattr = repr(offset + 3 + oparg)
            elif op in self.opc.JABS_OPS:
                if self.version == 2.7:
                    self.patch_continue(tokens, offset, op)
                pattr = repr(oparg)
            elif op in self.opc.LOCAL_OPS:
                pattr = varnames[oparg]
            elif op in self.opc.COMPARE_OPS:
                pattr = self.opc.cmp_op[oparg]
            elif op in self.opc.FREE_OPS:
                pattr = free[oparg]
        if op in self.varargs_ops:
            if op == self.opc.BUILD_TUPLE and self.code[self.prev[offset]] == self.opc.LOAD_CLOSURE:
                continue
            else:
                if self.is_pypy and (not oparg) and (op_name == 'BUILD_MAP'):
                    op_name = 'BUILD_MAP_n'
                else:
                    op_name = '%s_%d' % (op_name, oparg)
                    pass
                customize[op_name] = oparg
        elif op == self.opc.JUMP_ABSOLUTE:
            target = self.get_target(offset)
            if target <= offset:
                op_name = 'JUMP_BACK'
                j = self.offset2inst_index[offset]
                target_index = self.offset2inst_index[target]
                is_continue = self.insts[target_index - 1].opname == 'SETUP_LOOP' and self.insts[j + 1].opname == 'JUMP_FORWARD'
                if is_continue:
                    op_name = 'CONTINUE'
                if offset in self.stmts and self.code[offset + 3] not in (self.opc.END_FINALLY, self.opc.POP_BLOCK):
                    if offset in self.linestarts and self.code[self.prev[offset]] == self.opc.JUMP_ABSOLUTE or self.code[target] == self.opc.FOR_ITER or offset not in self.not_continue:
                        op_name = 'CONTINUE'
        elif op == self.opc.LOAD_GLOBAL:
            if offset in self.load_asserts:
                op_name = 'LOAD_ASSERT'
        elif op == self.opc.RETURN_VALUE:
            if offset in self.return_end_ifs:
                op_name = 'RETURN_END_IF'
        linestart = self.linestarts.get(offset, None)
        if offset not in replace:
            tokens.append(Token(op_name, oparg, pattr, offset, linestart, op, has_arg, self.opc))
        else:
            tokens.append(Token(replace[offset], oparg, pattr, offset, linestart, op, has_arg, self.opc))
            pass
        pass
    if show_asm in ('both', 'after'):
        for t in tokens:
            print(t.format(line_prefix='L.'))
        print()
    return (tokens, customize)

