def fix_line_range(source_code, start, end, options):
    start = max(start, 1)
    options.line_range = [start, end]
    from autopep8 import fix_code
    fixed = fix_code(source_code, options)
    try:
        if options.docformatter:
            from docformatter import format_code
            fixed = format_code(fixed, summary_wrap_length=options.max_line_length - 1, description_wrap_length=options.max_line_length - 2 * options.indent_size, pre_summary_newline=options.pre_summary_newline, post_description_blank=options.post_description_blank, force_wrap=options.force_wrap, line_range=[start, end])
    except AttributeError:
        pass
    return fixed

def sort(self, key, by=None, external=None, offset=0, limit=None, order=None, alpha=False, store_as=None):
    if order and order not in [b'ASC', b'DESC', 'ASC', 'DESC']:
        raise ValueError('invalid sort order "{}"'.format(order))
    command = [b'SORT', key]
    if by:
        command += [b'BY', by]
    if external and isinstance(external, list):
        for entry in external:
            command += [b'GET', entry]
    elif external:
        command += [b'GET', external]
    if limit:
        command += [b'LIMIT', ascii(offset).encode('utf-8'), ascii(limit).encode('utf-8')]
    if order:
        command.append(order)
    if alpha is True:
        command.append(b'ALPHA')
    if store_as:
        command += [b'STORE', store_as]
    return self._execute(command)

