def install_package(package_name, package_version=None, service_name=None, options_file=None, options_json=None, wait_for_completion=False, timeout_sec=600, expected_running_tasks=0):
    start = time.time()
    if options_file:
        options = _get_options(options_file)
    elif options_json:
        options = options_json
    else:
        options = {}
    package_manager = _get_package_manager()
    pkg = package_manager.get_package_version(package_name, package_version)
    if package_version is None:
        package_version = 'auto:{}'.format(pkg.version())
    if service_name is None:
        try:
            labels = pkg.marathon_json(options).get('labels')
            if 'DCOS_SERVICE_NAME' in labels:
                service_name = labels['DCOS_SERVICE_NAME']
        except errors.DCOSException as e:
            pass
    print('\n{}installing {} with service={} version={} options={}'.format(shakedown.cli.helpers.fchr('>>'), package_name, service_name, package_version, options))
    try:
        pre_install_notes = pkg.package_json().get('preInstallNotes')
        if pre_install_notes:
            print(pre_install_notes)
        package_manager.install_app(pkg, options, service_name)
        post_install_notes = pkg.package_json().get('postInstallNotes')
        if post_install_notes:
            print(post_install_notes)
        if wait_for_completion:
            print('\n{}waiting for {} deployment to complete...'.format(shakedown.cli.helpers.fchr('>>'), service_name))
            if expected_running_tasks > 0 and service_name is not None:
                wait_for_service_tasks_running(service_name, expected_running_tasks, timeout_sec)
            app_id = pkg.marathon_json(options).get('id')
            shakedown.deployment_wait(timeout_sec, app_id)
            print('\n{}install completed after {}\n'.format(shakedown.cli.helpers.fchr('>>'), pretty_duration(time.time() - start)))
        else:
            print('\n{}install started after {}\n'.format(shakedown.cli.helpers.fchr('>>'), pretty_duration(time.time() - start)))
    except errors.DCOSException as e:
        print('\n{}{}'.format(shakedown.cli.helpers.fchr('>>'), e))
    if pkg.cli_definition():
        print("{}installing CLI commands for package '{}'".format(shakedown.cli.helpers.fchr('>>'), package_name))
        subcommand.install(pkg)
    return True

