def str_value(self):
    if self._cached_str_val is not None:
        return self._cached_str_val
    if self.orig_type in _BOOL_TRISTATE:
        self._cached_str_val = TRI_TO_STR[self.tri_value]
        return self._cached_str_val
    if not self.orig_type:
        self._cached_str_val = self.name
        return self.name
    val = ''
    vis = self.visibility
    self._write_to_conf = vis != 0
    if self.orig_type in _INT_HEX:
        base = _TYPE_TO_BASE[self.orig_type]
        for (low_expr, high_expr, cond) in self.ranges:
            if expr_value(cond):
                has_active_range = True
                low = int(low_expr.str_value, base) if _is_base_n(low_expr.str_value, base) else 0
                high = int(high_expr.str_value, base) if _is_base_n(high_expr.str_value, base) else 0
                break
        else:
            has_active_range = False
        use_defaults = True
        if vis and self.user_value:
            user_val = int(self.user_value, base)
            if has_active_range and (not low <= user_val <= high):
                num2str = str if base == 10 else hex
                self.kconfig._warn('user value {} on the {} symbol {} ignored due to being outside the active range ([{}, {}]) -- falling back on defaults'.format(num2str(user_val), TYPE_TO_STR[self.orig_type], _name_and_loc(self), num2str(low), num2str(high)))
            else:
                val = self.user_value
                use_defaults = False
        if use_defaults:
            has_default = False
            for (sym, cond) in self.defaults:
                if expr_value(cond):
                    has_default = self._write_to_conf = True
                    val = sym.str_value
                    if _is_base_n(val, base):
                        val_num = int(val, base)
                    else:
                        val_num = 0
                    break
            else:
                val_num = 0
            if has_active_range:
                clamp = None
                if val_num < low:
                    clamp = low
                elif val_num > high:
                    clamp = high
                if clamp is not None:
                    val = str(clamp) if self.orig_type is INT else hex(clamp)
                    if has_default:
                        num2str = str if base == 10 else hex
                        self.kconfig._warn('default value {} on {} clamped to {} due to being outside the active range ([{}, {}])'.format(val_num, _name_and_loc(self), num2str(clamp), num2str(low), num2str(high)))
    elif self.orig_type is STRING:
        if vis and self.user_value is not None:
            val = self.user_value
        else:
            for (sym, cond) in self.defaults:
                if expr_value(cond):
                    val = sym.str_value
                    self._write_to_conf = True
                    break
    if self.env_var is not None or self is self.kconfig.defconfig_list:
        self._write_to_conf = False
    self._cached_str_val = val
    return val

def connect_to_cli(server=None, as_file=True, socket_timeout=1.0, attempts=5, retry_delay=0.3):
    import socket, errno, signal, time
    (s, n) = (None, attempts if attempts > 0 else None)
    try:
        (pid_path, sock_af, sock_t) = (None, socket.AF_UNIX, socket.SOCK_STREAM)
        if not server:
            (server, pid_path) = map(c.pa.runtime_path, ['cli', 'pid'])
        else:
            if not is_list(server):
                server = c.force_str(server)
                if not server.startswith('/'):
                    server = (server, 4712)
            if is_list(server):
                try:
                    addrinfo = socket.getaddrinfo(server[0], server[1], 0, sock_t, socket.IPPROTO_TCP)
                    if not addrinfo:
                        raise socket.gaierror('No addrinfo for socket: {}'.format(server))
                except (socket.gaierror, socket.error) as err:
                    raise PulseError('Failed to resolve socket parameters (address, family) via getaddrinfo: {!r} - {} {}'.format(server, type(err), err))
                (sock_af, sock_t, _, _, server) = addrinfo[0]
        s = socket.socket(sock_af, sock_t)
        s.settimeout(socket_timeout)
        while True:
            ts = c.mono_time()
            try:
                s.connect(server)
            except socket.error as err:
                if err.errno not in [errno.ECONNREFUSED, errno.ENOENT, errno.ECONNABORTED]:
                    raise
            else:
                break
            if n:
                n -= 1
                if n <= 0:
                    raise PulseError('Number of connection attempts ({}) exceeded'.format(attempts))
            if pid_path:
                with open(pid_path) as src:
                    os.kill(int(src.read().strip()), signal.SIGUSR2)
            time.sleep(max(0, retry_delay - (c.mono_time() - ts)))
        if as_file:
            res = s.makefile('rw', 1)
        else:
            (res, s) = (s, None)
        return res
    except Exception as err:
        raise PulseError('Failed to connect to pulse cli socket {!r}: {} {}'.format(server, type(err), err))
    finally:
        if s:
            s.close()

def parse_format(xml_file):
    tree = ElementTree()
    tree.parse(xml_file)
    for param in tree.find('parameters').getchildren():
        VARIABLES[param.get('name')] = param.get('value')
    types_scales = {}
    for prod in tree.find('product'):
        ascii = prod.tag in ['mphr', 'sphr']
        res = []
        for i in prod:
            lres = CASES[i.tag](i, ascii)
            if lres is not None:
                res.append(lres)
        types_scales[prod.tag, int(prod.get('subclass'))] = res
    types = {}
    stypes = {}
    scales = {}
    for (key, val) in types_scales.items():
        types[key] = to_dtype(val)
        stypes[key] = to_scaled_dtype(val)
        scales[key] = to_scales(val)
    return (types, stypes, scales)

