def splitnport(host, defport=-1):
    global _nportprog
    if _nportprog is None:
        import re
        _nportprog = re.compile('^(.*):(.*)$')
    match = _nportprog.match(host)
    if match:
        (host, port) = match.group(1, 2)
        try:
            if not port:
                raise ValueError('no digits')
            nport = int(port)
        except ValueError:
            nport = None
        return (host, nport)
    return (host, defport)

def subtree(self, matcher, create=False):
    if matcher is None:
        return self
    current = self
    for i in range(self.depth, len(matcher.indices)):
        ind = matcher.indices[i]
        if ind is None:
            if hasattr(current, 'any'):
                current = current.any
            elif create:
                cany = MatchTree(current)
                cany.parentIndex = None
                current.any = cany
                current = cany
            else:
                return None
        else:
            current2 = current.index.get(ind)
            if current2 is None:
                if create:
                    cind = MatchTree(current)
                    cind.parentIndex = ind
                    current.index[ind] = cind
                    current = cind
                else:
                    return None
            else:
                current = current2
    return current

