def _fill_file_path(line, data):

    def _find_file(xs, target):
        if isinstance(xs, dict):
            for v in xs.values():
                f = _find_file(v, target)
                if f:
                    return f
        elif isinstance(xs, (list, tuple)):
            for x in xs:
                f = _find_file(x, target)
                if f:
                    return f
        elif isinstance(xs, six.string_types) and os.path.exists(xs) and xs.endswith('/%s' % target):
            return xs
    orig_file = line.split('=')[-1].replace('"', '').strip()
    full_file = _find_file(data, os.path.basename(orig_file))
    if not full_file and os.path.exists(os.path.abspath(orig_file)):
        full_file = os.path.abspath(orig_file)
    assert full_file, 'Did not find vcfanno input file %s' % orig_file
    return 'file="%s"\n' % full_file

def replace_find_selection(self, focus_replace_text=False):
    if self.editor is not None:
        replace_text = to_text_string(self.replace_text.currentText())
        search_text = to_text_string(self.search_text.currentText())
        case = self.case_button.isChecked()
        words = self.words_button.isChecked()
        re_flags = re.MULTILINE if case else re.IGNORECASE | re.MULTILINE
        re_pattern = None
        if self.re_button.isChecked():
            pattern = search_text
        else:
            pattern = re.escape(search_text)
            replace_text = re.escape(replace_text)
        if words:
            pattern = '\\b{pattern}\\b'.format(pattern=pattern)
        try:
            re_pattern = re.compile(pattern, flags=re_flags)
            re_pattern.sub(replace_text, '')
        except re.error as e:
            return
        selected_text = to_text_string(self.editor.get_selected_text())
        replacement = re_pattern.sub(replace_text, selected_text)
        if replacement != selected_text:
            cursor = self.editor.textCursor()
            cursor.beginEditBlock()
            cursor.removeSelectedText()
            if not self.re_button.isChecked():
                replacement = re.sub('\\\\(?![nrtf])(.)', '\\1', replacement)
            cursor.insertText(replacement)
            cursor.endEditBlock()
        if focus_replace_text:
            self.replace_text.setFocus()
        else:
            self.editor.setFocus()

def compare_registries(fs0, fs1, concurrent=False):
