def watermark(img, mark, position=(0, 0), opacity=1, scale=1.0, tile=False, greyscale=False, rotation=0, return_name=False, **kwargs):
    if opacity < 1:
        mark = reduce_opacity(mark, opacity)
    if not isinstance(scale, tuple):
        scale = determine_scale(scale, img, mark)
    mark = mark.resize(scale, resample=Image.ANTIALIAS)
    if greyscale and mark.mode != 'LA':
        mark = mark.convert('LA')
    rotation = determine_rotation(rotation, mark)
    if rotation != 0:
        new_w = int(mark.size[0] * 1.5)
        new_h = int(mark.size[1] * 1.5)
        new_mark = Image.new('RGBA', (new_w, new_h), (0, 0, 0, 0))
        new_l = int((new_w - mark.size[0]) / 2)
        new_t = int((new_h - mark.size[1]) / 2)
        new_mark.paste(mark, (new_l, new_t))
        mark = new_mark.rotate(rotation)
    position = determine_position(position, img, mark)
    if img.mode != 'RGBA':
        img = img.convert('RGBA')
    assert isinstance(position, tuple), 'Invalid position "%s"!' % position
    layer = Image.new('RGBA', img.size, (0, 0, 0, 0))
    if tile:
        first_y = int(position[1] % mark.size[1] - mark.size[1])
        first_x = int(position[0] % mark.size[0] - mark.size[0])
        for y in range(first_y, img.size[1], mark.size[1]):
            for x in range(first_x, img.size[0], mark.size[0]):
                layer.paste(mark, (x, y))
    else:
        layer.paste(mark, position)
    return Image.composite(layer, img, layer)

def _do_config_proposal_vote(args):
    signer = _read_signer(args.key)
    rest_client = RestClient(args.url)
    proposals = _get_proposals(rest_client)
    proposal = None
    for candidate in proposals.candidates:
        if candidate.proposal_id == args.proposal_id:
            proposal = candidate
            break
    if proposal is None:
        raise CliException('No proposal exists with the given id')
    for vote_record in proposal.votes:
        if vote_record.public_key == signer.get_public_key().as_hex():
            raise CliException('A vote has already been recorded with this signing key')
    txn = _create_vote_txn(signer, args.proposal_id, proposal.proposal.setting, args.vote_value)
    batch = _create_batch(signer, [txn])
    batch_list = BatchList(batches=[batch])
    rest_client.send_batches(batch_list)

def next(self) -> mx.io.DataBatch:
    if not self.iter_next():
        raise StopIteration
    (i, j) = self.batch_indices[self.curr_batch_index]
    self.curr_batch_index += 1
    batch_size = self.bucket_batch_sizes[i].batch_size
    source = self.data.source[i][j:j + batch_size]
    target = self.data.target[i][j:j + batch_size]
    if self.preload_features:
        loaded_source = []
        for k in source:
            loaded_source.append(self.loaded_source[k])
    else:
        loaded_source = self.data_loader(source)
    loaded_source = zero_pad_features(loaded_source, self.image_size)
    loaded_source = mx.nd.array(loaded_source)
    label = [self.data.label[i][j:j + batch_size]]
    provide_data = [mx.io.DataDesc(name=self.source_data_name, shape=loaded_source.shape, layout=C.BATCH_MAJOR_IMAGE)]
    if self.with_text:
        provide_data += [mx.io.DataDesc(name=self.target_data_name, shape=target.shape, layout=C.BATCH_MAJOR)]
    provide_label = [mx.io.DataDesc(name=n, shape=x.shape, layout=C.BATCH_MAJOR) for (n, x) in zip(self.label_names, label)]
    data = [loaded_source]
    if self.with_text:
        data += [target]
    return mx.io.DataBatch(data, label, pad=0, index=None, bucket_key=self.buckets[i], provide_data=provide_data, provide_label=provide_label)

def envget(var, default=None):
    if 'pyraf' in sys.modules:
        from pyraf import iraf
    else:
        iraf = None
    try:
        if iraf:
            return iraf.envget(var)
        else:
            raise KeyError
    except KeyError:
        try:
            return _varDict[var]
        except KeyError:
            try:
                return os.environ[var]
            except KeyError:
                if default is not None:
                    return default
                elif var == 'TERM':
                    print('Using default TERM value for session.')
                    return 'xterm'
                else:
                    raise KeyError("Undefined environment variable `%s'" % var)

def get_value_for_expr(self, expr, target):
    if expr in LOGICAL_OPERATORS.values():
        return None
    rvalue = expr['value']
    if rvalue == HISTORICAL:
        history = self.history[target]
        if len(history) < self.history_size:
            return None
        rvalue = sum(history) / float(len(history))
    rvalue = expr['mod'](rvalue)
    return rvalue

