def replace(self, **kw):
    if 'tzinfo' in kw:
        if kw['tzinfo'] is None:
            raise TypeError('Can not remove the timezone use asdatetime()')
        else:
            tzinfo = kw['tzinfo']
            del kw['tzinfo']
    else:
        tzinfo = None
    is_dst = None
    if 'is_dst' in kw:
        is_dst = kw['is_dst']
        del kw['is_dst']
    else:
        is_dst = self.is_dst
    replaced = self.asdatetime().replace(**kw)
    return type(self)(replaced, tzinfo=tzinfo or self.tzinfo.zone, is_dst=is_dst)

def branch(self, name, values=None):
    if isinstance(values, basestring):
        values = [values]
    spec = self.parameter_spec(name)
    if not isinstance(spec, SwitchSpec):
        raise ArcanaUsageError('{} is standard parameter not a switch'.format(spec))
    switch = self._get_parameter(name)
    if spec.is_boolean:
        if values is not None:
            raise ArcanaDesignError("Should not provide values ({}) to boolean switch '{}' in {}".format(values, name, self._param_error_location))
        in_branch = switch.value
    else:
        if values is None:
            raise ArcanaDesignError("Value(s) need(s) to be provided non-boolean switch '{}' in {}".format(name, self._param_error_location))
        unrecognised_values = set(values) - set(spec.choices)
        if unrecognised_values:
            raise ArcanaDesignError("Provided value(s) ('{}') for switch '{}' in {} is not a valid option ('{}')".format("', '".join(unrecognised_values), name, self._param_error_location, "', '".join(spec.choices)))
        in_branch = switch.value in values
    return in_branch

def search_for_parent_dir(start_at: str=None, with_files: set=None, with_dirs: set=None) -> str:
    if not start_at:
        start_at = os.path.abspath(os.curdir)
    if not with_files:
        with_files = set()
    if not with_dirs:
        with_dirs = set()
    exp_hits = len(with_files) + len(with_dirs)
    while start_at:
        num_hits = 0
        for entry in scandir(start_at):
            if entry.is_file() and entry.name in with_files or (entry.is_dir() and entry.name in with_dirs):
                num_hits += 1
            if num_hits == exp_hits:
                return start_at
        cur_level = start_at
        start_at = os.path.split(cur_level)[0]
        if os.path.realpath(cur_level) == os.path.realpath(start_at):
            break

def env_present(name, value=None, user='root'):
    ret = {'changes': {}, 'comment': '', 'name': name, 'result': True}
    if __opts__['test']:
        status = _check_cron_env(user, name, value=value)
        ret['result'] = None
        if status == 'absent':
            ret['comment'] = 'Cron env {0} is set to be added'.format(name)
        elif status == 'present':
            ret['result'] = True
            ret['comment'] = 'Cron env {0} already present'.format(name)
        elif status == 'update':
            ret['comment'] = 'Cron env {0} is set to be updated'.format(name)
        return ret
    data = __salt__['cron.set_env'](user, name, value=value)
    if data == 'present':
        ret['comment'] = 'Cron env {0} already present'.format(name)
        return ret
    if data == 'new':
        ret['comment'] = "Cron env {0} added to {1}'s crontab".format(name, user)
        ret['changes'] = {user: name}
        return ret
    if data == 'updated':
        ret['comment'] = 'Cron env {0} updated'.format(name)
        ret['changes'] = {user: name}
        return ret
    ret['comment'] = 'Cron env {0} for user {1} failed to commit with error \n{2}'.format(name, user, data)
    ret['result'] = False
    return ret

def remove_node(self, node, stop=False):
    if node.kind not in self.nodes:
        raise NodeNotFound('Unable to remove node %s: invalid node type `%s`.', node.name, node.kind)
    else:
        try:
            index = self.nodes[node.kind].index(node)
            if self.nodes[node.kind][index]:
                del self.nodes[node.kind][index]
            if stop:
                node.stop()
            self._naming_policy.free(node.kind, node.name)
            self.repository.save_or_update(self)
            remaining_nodes = self.get_all_nodes()
            self._gather_node_ip_addresses(remaining_nodes, self.start_timeout, self.ssh_probe_timeout, remake=True)
        except ValueError:
            raise NodeNotFound('Node %s not found in cluster' % node.name)

def total_cost_function(self, item_a, item_b, time_a, time_b):
    distances = np.zeros(len(self.weights))
    for (c, component) in enumerate(self.cost_function_components):
        distances[c] = component(item_a, time_a, item_b, time_b, self.max_values[c])
    total_distance = np.sum(self.weights * distances)
    return total_distance

def write_byte(self, addr, data, erase=True):
    if addr < 0 or addr >= 128:
        raise ValueError('invalid byte address')
    log.debug('write byte at address {0} ({0:02X}h)'.format(addr))
    cmd = 'S' if erase is True else '\x1a'
    cmd = cmd + chr(addr) + chr(data) + self.uid
    return self.transceive(cmd)

def support_event_list_simple(fn):

    @wraps(fn)
    def _wrapped(self, event, *args, **kwargs):
        if _is_event_list(event):
            result = []
            for e in event:
                ret = fn(self, e, *args, **kwargs)
                if ret is None:
                    continue
                if isinstance(ret, (tuple, list)):
                    result.extend(ret)
                else:
                    result.append(ret)
            if result:
                if len(result) == 1:
                    return result[0]
                return result
            return None
        else:
            return fn(self, event, *args, **kwargs)
    return _wrapped

