def locate(self, minimum_version=None, maximum_version=None, jdk=False):

    def _get_stricter_version(a, b, name, stricter):
        version_a = _parse_java_version(name, a)
        version_b = _parse_java_version(name, b)
        if version_a is None:
            return version_b
        if version_b is None:
            return version_a
        return stricter(version_a, version_b)
    minimum_version = _get_stricter_version(minimum_version, self._minimum_version, 'minimum_version', max)
    maximum_version = _get_stricter_version(maximum_version, self._maximum_version, 'maximum_version', min)
    key = (minimum_version, maximum_version, jdk)
    dist = self._cache.get(key)
    if not dist:
        dist = self._scan_constraint_match(minimum_version, maximum_version, jdk)
        if not dist:
            dist = self._locate(minimum_version=minimum_version, maximum_version=maximum_version, jdk=jdk)
        self._cache[key] = dist
    return dist

def fill_date_range(start_date, end_date, date_format=None):
    if date_format:
        start_date = datetime.strptime(start_date, date_format).date()
        end_date = datetime.strptime(end_date, date_format).date()
    date_list = []
    while start_date <= end_date:
        date_list.append(start_date)
        start_date = start_date + timedelta(days=1)
    return date_list

def init_cursor(self):
    timestamp = self.read_last_checkpoint()
    if timestamp is None or self.only_dump:
        if self.collection_dump:
            timestamp = self.dump_collection()
            if self.only_dump:
                LOG.info('Finished dump. Exiting.')
                timestamp = None
                self.running = False
            self.update_checkpoint(timestamp)
            if timestamp is None:
                return (None, True)
        else:
            cursor = self.get_oplog_cursor()
            return (cursor, self._cursor_empty(cursor))
    cursor = self.get_oplog_cursor(timestamp)
    cursor_empty = self._cursor_empty(cursor)
    if cursor_empty:
        LOG.debug('OplogThread: Initiating rollback from get_oplog_cursor')
        self.update_checkpoint(self.rollback())
        return self.init_cursor()
    first_oplog_entry = next(cursor)
    oldest_ts_long = util.bson_ts_to_long(self.get_oldest_oplog_timestamp())
    checkpoint_ts_long = util.bson_ts_to_long(timestamp)
    if checkpoint_ts_long < oldest_ts_long:
        return (None, True)
    cursor_ts_long = util.bson_ts_to_long(first_oplog_entry['ts'])
    if cursor_ts_long > checkpoint_ts_long:
        LOG.debug('OplogThread: Initiating rollback from get_oplog_cursor: new oplog entries found but checkpoint is not present')
        self.update_checkpoint(self.rollback())
        return self.init_cursor()
    return (cursor, cursor_empty)

