def read_param_file(FileName, parameters, bp, bp_range, word=False, startBP=1):
    sys.stdout.write('\nReading file : %s\n' % FileName)
    sys.stdout.flush()

    def get_frame_data(block, parameters, bp_idx):
        block = np.array(block).T
        temp_data = block[parameters, :][:, bp_idx].copy()
        return temp_data

    def get_time(line):
        (dummy, temp_time) = line.split('=')
        return float(temp_time)
    infile = open(FileName, 'r')
    data = []
    time = []
    frame_number = 0
    (bp_idx, param_idx) = get_idx_of_bp_parameters(bp, parameters, bp_range, startBP=startBP)
    block = []
    for line in infile:
        line = line.rstrip('\n')
        if not line.strip():
            continue
        if re.match('# Time', line) != None:
            if frame_number < 100 and frame_number % 10 == 0 or (frame_number < 1000 and frame_number % 100 == 0) or (frame_number < 10000 and frame_number % 1000 == 0) or (frame_number < 100000 and frame_number % 10000 == 0) or (frame_number < 1000000 and frame_number % 100000 == 0):
                sys.stdout.write('\rReading frame %d' % frame_number)
                sys.stdout.flush()
            frame_number += 1
            time.append(get_time(line))
            if len(block) > 0:
                data.append(get_frame_data(block, param_idx, bp_idx))
            block = []
            continue
        if re.match('#', line) != None:
            continue
        if not word:
            block.append(list(map(float, line.split())))
        else:
            temp = []
            split_line = line.split()
            for word in split_line:
                if word != '---':
                    temp.append(float(word))
                else:
                    temp.append(None)
            block.append(temp)
    data.append(get_frame_data(block, param_idx, bp_idx))
    block = []
    data_transpose = np.array(data).T
    sys.stdout.write('\nFinished reading.... Total number of frame read =  %d\n' % frame_number)
    sys.stdout.flush()
    return (data_transpose, time)

def get_location(query, format, api_key):
    sleep(1)
    geolocator = OpenCage(api_key=api_key, timeout=10)
    data = {'city': None, 'address_1': None, 'postal_code': None, 'country': None, 'county': None, 'state': None, 'country_code': None, 'latitude': None, 'longitude': None, 'continent': None}
    road = ''
    number = ''
    location_data = {'city': None, 'road': None, 'house_number': None, 'postcode': None, 'country': None, 'county': None, 'state': None, 'ISO_3166-1_alpha-2': None, 'country_code': None, 'lat': None, 'lng': None}
    if format == 'reverse':
        if query is None or len(query) < 3:
            pass
        else:
            location = geolocator.reverse(query)
            if location is not None:
                location_data = location[0].raw[u'components']
                location_data['lat'] = location[0].raw[u'geometry']['lat']
                location_data['lng'] = location[0].raw[u'geometry']['lng']
    if format == 'direct':
        if query is None or len(query) < 3:
            pass
        else:
            location = geolocator.geocode(query)
            if location is not None:
                location_data = location.raw[u'components']
                location_data['lat'] = location.raw[u'geometry']['lat']
                location_data['lng'] = location.raw[u'geometry']['lng']
    for component in location_data:
        if component == 'town' or component == 'city':
            data['city'] = location_data[component]
        if component == 'road':
            road = location_data[component]
        if component == 'house_number':
            number = location_data[component]
        if component == 'postcode':
            data['postal_code'] = location_data[component]
        if component == 'country':
            data['country'] = location_data[component]
        if component == 'county':
            data['county'] = location_data[component]
        if component == 'state':
            data['state'] = location_data[component]
        if component == 'ISO_3166-1_alpha-2':
            data['country_code'] = location_data[component]
    data['address_1'] = unicode(road) + ' ' + unicode(number)
    data['latitude'] = location_data['lat']
    data['longitude'] = location_data['lng']
    try:
        country_data = transformations.cca2_to_ccn(data['country_code'])
        data['country_code'] = transformations.ccn_to_cca3(country_data)
    except:
        data['country_code'] = None
    try:
        country_data = transformations.cc_to_cn(data['country_code'])
        data['continent'] = transformations.cn_to_ctn(country_data)
    except:
