    pga4nl = self._get_pga_on_rock(rup, dists, C)
    if imt == PGA():
        mean = np.log(pga4nl) + self._get_site_amplification_linear(sites.vs30, C_SR) + self._get_site_amplification_non_linear(sites.vs30, pga4nl, C_SR)
    else:
        mean = self._compute_magnitude_scaling(rup, C) + self._compute_distance_scaling(rup, dists, C) + self._get_site_amplification_linear(sites.vs30, C_SR) + self._get_site_amplification_non_linear(sites.vs30, pga4nl, C_SR)
