def _MultiStream(cls, fds):
    missing_chunks_by_fd = {}
    for chunk_fd_pairs in collection.Batch(cls._GenerateChunkPaths(fds), cls.MULTI_STREAM_CHUNKS_READ_AHEAD):
        chunks_map = dict(chunk_fd_pairs)
        contents_map = {}
        for chunk_fd in FACTORY.MultiOpen(chunks_map, mode='r', token=fds[0].token):
            if isinstance(chunk_fd, AFF4Stream):
                fd = chunks_map[chunk_fd.urn]
                contents_map[chunk_fd.urn] = chunk_fd.read()
        for (chunk_urn, fd) in chunk_fd_pairs:
            if chunk_urn not in contents_map or not contents_map[chunk_urn]:
                missing_chunks_by_fd.setdefault(fd, []).append(chunk_urn)
        for (chunk_urn, fd) in chunk_fd_pairs:
            if fd in missing_chunks_by_fd:
                continue
            yield (fd, contents_map[chunk_urn], None)
    for (fd, missing_chunks) in iteritems(missing_chunks_by_fd):
        e = MissingChunksError('%d missing chunks (multi-stream).' % len(missing_chunks), missing_chunks=missing_chunks)
        yield (fd, None, e)

def nucleotide_linkage(residues):
    nuc_covalent = []
    nucleotides = ['A', 'C', 'T', 'G', 'U', 'DA', 'DC', 'DT', 'DG', 'DU']
    dna_rna = {}
    covlinkage = namedtuple('covlinkage', 'id1 chain1 pos1 conf1 id2 chain2 pos2 conf2')
    for ligand in residues:
        (resname, chain, pos) = ligand
        if resname in nucleotides:
            if chain not in dna_rna:
                dna_rna[chain] = [(resname, pos)]
            else:
                dna_rna[chain].append((resname, pos))
    for chain in dna_rna:
        nuc_list = dna_rna[chain]
        for (i, nucleotide) in enumerate(nuc_list):
            if not i == len(nuc_list) - 1:
                (name, pos) = nucleotide
                nextnucleotide = nuc_list[i + 1]
                (nextname, nextpos) = nextnucleotide
                newlink = covlinkage(id1=name, chain1=chain, pos1=pos, conf1='', id2=nextname, chain2=chain, pos2=nextpos, conf2='')
                nuc_covalent.append(newlink)
    return nuc_covalent

