def shift_or_mirror_into_invertible_domain(self, solution_genotype, copy=False):
    assert solution_genotype is not None
    if copy:
        y = [val for val in solution_genotype]
    else:
        y = solution_genotype
    if isinstance(y, np.ndarray) and (not isinstance(y[0], float)):
        y = array(y, dtype=float)
    for i in rglen(y):
        lb = self._lb[self._index(i)]
        ub = self._ub[self._index(i)]
        al = self._al[self._index(i)]
        au = self._au[self._index(i)]
        if y[i] < lb - 2 * al - (ub - lb) / 2.0 or y[i] > ub + 2 * au + (ub - lb) / 2.0:
            r = 2 * (ub - lb + al + au)
            s = lb - 2 * al - (ub - lb) / 2.0
            y[i] -= r * ((y[i] - s) // r)
        if y[i] > ub + au:
            y[i] -= 2 * (y[i] - ub - au)
        if y[i] < lb - al:
            y[i] += 2 * (lb - al - y[i])
    return y

def _read(self):
    while self._rxactive:
        try:
            rv = self._ep_in.read(self._ep_in.wMaxPacketSize)
            if self._isFTDI:
                status = rv[:2]
                if status[0] != 1 or status[1] != 96:
                    log.info('USB Status: 0x{0:02X} 0x{1:02X}'.format(*status))
                rv = rv[2:]
            for rvi in rv:
                self._rxqueue.put(rvi)
        except usb.USBError as e:
            log.warn('USB Error on _read {}'.format(e))
            return
        time.sleep(self._rxinterval)

