def plot_covariance(mean, cov=None, variance=1.0, std=None, interval=None, ellipse=None, title=None, axis_equal=True, show_semiaxis=False, show_center=True, facecolor=None, edgecolor=None, fc='none', ec='#004080', alpha=1.0, xlim=None, ylim=None, ls='solid'):
    from matplotlib.patches import Ellipse
    import matplotlib.pyplot as plt
    if cov is not None and ellipse is not None:
        raise ValueError('You cannot specify both cov and ellipse')
    if cov is None and ellipse is None:
        raise ValueError('Specify one of cov or ellipse')
    if facecolor is None:
        facecolor = fc
    if edgecolor is None:
        edgecolor = ec
    if cov is not None:
        ellipse = covariance_ellipse(cov)
    if axis_equal:
        plt.axis('equal')
    if title is not None:
        plt.title(title)
    ax = plt.gca()
    angle = np.degrees(ellipse[0])
    width = ellipse[1] * 2.0
    height = ellipse[2] * 2.0
    std = _std_tuple_of(variance, std, interval)
    for sd in std:
        e = Ellipse(xy=mean, width=sd * width, height=sd * height, angle=angle, facecolor=facecolor, edgecolor=edgecolor, alpha=alpha, lw=2, ls=ls)
        ax.add_patch(e)
    (x, y) = mean
    if show_center:
        plt.scatter(x, y, marker='+', color=edgecolor)
    if xlim is not None:
        ax.set_xlim(xlim)
    if ylim is not None:
        ax.set_ylim(ylim)
    if show_semiaxis:
        a = ellipse[0]
        (h, w) = (height / 4, width / 4)
        plt.plot([x, x + h * cos(a + np.pi / 2)], [y, y + h * sin(a + np.pi / 2)])
        plt.plot([x, x + w * cos(a)], [y, y + w * sin(a)])

