def model_fn(features, labels, mode, params):
    with tf.variable_scope('model'):
        (inputs, targets) = (features, labels)
        model = transformer.Transformer(params, mode == tf.estimator.ModeKeys.TRAIN)
        output = model(inputs, targets)
        if mode == tf.estimator.ModeKeys.PREDICT:
            return tf.estimator.EstimatorSpec(tf.estimator.ModeKeys.PREDICT, predictions=output)
        logits = output
        (xentropy, weights) = metrics.padded_cross_entropy_loss(logits, targets, params.label_smoothing, params.vocab_size)
        loss = tf.reduce_sum(xentropy * weights) / tf.reduce_sum(weights)
        if mode == tf.estimator.ModeKeys.EVAL:
            return tf.estimator.EstimatorSpec(mode=mode, loss=loss, predictions={'predictions': logits}, eval_metric_ops=metrics.get_eval_metrics(logits, labels, params))
        else:
            train_op = get_train_op(loss, params)
            return tf.estimator.EstimatorSpec(mode=mode, loss=loss, train_op=train_op)

def find_duplicate_items(items, k=2):
    import utool as ut
    duplicate_map = ut.ddict(list)
    for (count, item) in enumerate(items):
        duplicate_map[item].append(count)
    singleton_keys = []
    for key in six.iterkeys(duplicate_map):
        if len(duplicate_map[key]) == 1:
            singleton_keys.append(key)
    for key in singleton_keys:
        del duplicate_map[key]
    duplicate_map = dict(duplicate_map)
    return duplicate_map

