def __watch_file_system(self):
    for (path, data) in self.__paths.items():
        (stored_modified_time, is_file) = data
        try:
            if not foundations.common.path_exists(path):
                LOGGER.warning("!> {0} | '{1}' path has been invalidated and will be unregistered!".format(self.__class__.__name__, path))
                del self.__paths[path]
                if is_file:
                    self.file_invalidated.emit(path)
                else:
                    self.directory_invalidated.emit(path)
                continue
        except KeyError:
            LOGGER.debug("> {0} | '{1}' path has been unregistered while iterating!".format(self.__class__.__name__, path))
            continue
        try:
            modified_time = self.get_path_modified_time(path)
        except OSError:
            LOGGER.debug("> {0} | '{1}' path has been invalidated while iterating!".format(self.__class__.__name__, path))
            continue
        if stored_modified_time != modified_time:
            self.__paths[path] = (modified_time, os.path.isfile(path))
            LOGGER.debug("> {0} | '{1}' path has been changed!".format(self.__class__.__name__, path))
            if is_file:
                self.file_changed.emit(path)
            else:
                self.directory_changed.emit(path)

def _add_operations_bulk(self, chunked_data):
    url = '{}/bulk/context'.format(self._base_url)
    ct_header = {'Content-Type': 'application/json; charset=utf-8'}
    responses = []
    for chunk in chunked_data:
        if len(chunk) > 1:
            try:
                json_pl = json.dumps(chunk)
            except TypeError as err:
                raise CraftAiBadRequestError('Error while dumping the payload into jsonformat when converting it for the bulk request. {}'.format(err.__str__()))
            resp = self._requests_session.post(url, headers=ct_header, data=json_pl)
            resp = self._decode_response(resp)
            responses += resp
        elif chunk:
            message = self.add_operations(chunk[0]['id'], chunk[0]['operations'])
            responses.append({'id': chunk[0]['id'], 'status': 201, 'message': message})
    if responses == []:
        raise CraftAiBadRequestError('Invalid or empty set of operations given')
    return responses

