def lis(seq, indices=False):
    if not seq:
        return []
    prevs = [None] * len(seq)
    tails = [(seq[0], 0)]
    for (i, elem) in enumerate(seq[1:], start=1):
        if elem > tails[-1][0]:
            prevs[i] = tails[-1][1]
            tails.append((elem, i))
            continue
        k = bisect(tails, (elem, -1))
        if tails[k][0] > elem:
            tails[k] = (elem, i)
            if k > 0:
                prevs[i] = tails[k - 1][1]
    (_, i) = tails[-1]
    subseq = []
    while i is not None:
        subseq.append(i if indices else seq[i])
        i = prevs[i]
    return subseq[::-1]

