def declassify(to_remove, *args, **kwargs):

    def argdecorate(fn):

        @wraps(fn)
        def declassed(*args, **kwargs):
            ret = fn(*args, **kwargs)
            try:
                if type(ret) is list:
                    return [r[to_remove] for r in ret]
                return ret[to_remove]
            except KeyError:
                return ret
        return declassed
    return argdecorate

