def translate(self, package, into=None):
    if not isinstance(package, SourcePackage):
        return None
    if not package.local:
        raise ValueError('SourceTranslator cannot translate remote packages.')
    installer = None
    version = self._interpreter.version
    unpack_path = Archiver.unpack(package.local_path)
    into = into or safe_mkdtemp()
    try:
        if self._use_2to3 and version >= (3,):
            with TRACER.timed('Translating 2->3 %s' % package.name):
                self.run_2to3(unpack_path)
        installer = self._installer_impl(unpack_path, interpreter=self._interpreter)
        with TRACER.timed('Packaging %s' % package.name):
            try:
                dist_path = installer.bdist()
            except self._installer_impl.InstallFailure as e:
                TRACER.log('Failed to install package at %s: %s' % (unpack_path, e))
                return None
            target_path = os.path.join(into, os.path.basename(dist_path))
            safe_copy(dist_path, target_path)
            target_package = Package.from_href(target_path)
            if not target_package:
                TRACER.log('Target path %s does not look like a Package.' % target_path)
                return None
            if not target_package.compatible(self._supported_tags):
                TRACER.log('Target package %s is not compatible with %s' % (target_package, self._supported_tags))
                return None
            return DistributionHelper.distribution_from_path(target_path)
    except Exception as e:
        TRACER.log('Failed to translate %s' % package)
        TRACER.log(traceback.format_exc())
    finally:
        if installer:
            installer.cleanup()
        if unpack_path:
            safe_rmtree(unpack_path)

def find(self, resource, req, sub_resource_lookup):
    args = getattr(req, 'args', request.args if request else {}) or {}
    source_config = config.SOURCES[resource]
    if args.get('source'):
        query = json.loads(args.get('source'))
        if 'filtered' not in query.get('query', {}):
            _query = query.get('query')
            query['query'] = {'filtered': {}}
            if _query:
                query['query']['filtered']['query'] = _query
    else:
        query = {'query': {'filtered': {}}}
    if args.get('q', None):
        query['query']['filtered']['query'] = _build_query_string(args.get('q'), default_field=args.get('df', '_all'), default_operator=args.get('default_operator', 'OR'))
    if 'sort' not in query:
        if req.sort:
            sort = ast.literal_eval(req.sort)
            set_sort(query, sort)
        elif self._default_sort(resource) and 'query' not in query['query']['filtered']:
            set_sort(query, self._default_sort(resource))
    if req.max_results:
        query.setdefault('size', req.max_results)
    if req.page > 1:
        query.setdefault('from', (req.page - 1) * req.max_results)
    filters = []
    filters.append(source_config.get('elastic_filter'))
    filters.append(source_config.get('elastic_filter_callback', noop)())
    filters.append({'and': _build_lookup_filter(sub_resource_lookup)} if sub_resource_lookup else None)
    filters.append(json.loads(args.get('filter')) if 'filter' in args else None)
    filters.extend(args.get('filters') if 'filters' in args else [])
    if req.where:
        try:
            filters.append({'term': json.loads(req.where)})
        except ValueError:
            try:
                filters.append({'term': parse(req.where)})
            except ParseError:
                abort(400)
    set_filters(query, filters)
    if 'facets' in source_config:
        query['facets'] = source_config['facets']
    if 'aggregations' in source_config and self.should_aggregate(req):
        query['aggs'] = source_config['aggregations']
    if 'es_highlight' in source_config and self.should_highlight(req):
        query_string = query['query'].get('filtered', {}).get('query', {}).get('query_string')
        highlights = source_config.get('es_highlight', noop)(query_string)
        if highlights:
            query['highlight'] = highlights
            query['highlight'].setdefault('require_field_match', False)
    source_projections = None
    if self.should_project(req):
        source_projections = self.get_projected_fields(req)
    args = self._es_args(resource, source_projections=source_projections)
    try:
        hits = self.elastic(resource).search(body=query, **args)
    except elasticsearch.exceptions.RequestError as e:
        if e.status_code == 400 and 'No mapping found for' in e.error:
            hits = {}
        elif e.status_code == 400 and 'SearchParseException' in e.error:
            raise InvalidSearchString
        else:
            raise
    return self._parse_hits(hits, resource)

def deprecated(message=DEPRECATION_MESSAGE, logger=None):
    if logger is None:
        logger = default_logger

    def _deprecated(f):

        def _wrapper(*args, **kwargs):
            f_name = f.__name__
            logger.warning(message.format(name=f_name))
            result = f(*args, **kwargs)
            return result
        return _wrapper
    return _deprecated

def findFirstPar(theDict, name, _depth=0):
    for key in theDict:
        val = theDict[key]
        if isinstance(val, dict):
            retval = findFirstPar(val, name, _depth=_depth + 1)
            if retval is not None:
                return retval
        elif key == name:
            return (theDict, theDict[name])
    if _depth == 0:
        raise KeyError(name)
    else:
        return None

