    if is_running_from_reloader():
        os.kill(os.getpid(), sig)
    self.server._BaseServer__shutdown_request = True
    self.server._BaseServer__serving = False

def get_plot(self, xlim=None, ylim=None, plot_negative=None, integrated=False, invert_axes=True):
    if self.are_coops:
        cohp_label = 'COOP'
    else:
        cohp_label = 'COHP'
    if plot_negative is None:
        plot_negative = True if not self.are_coops else False
    if integrated:
        cohp_label = 'I' + cohp_label + ' (eV)'
    if plot_negative:
        cohp_label = '-' + cohp_label
    if self.zero_at_efermi:
        energy_label = '$E - E_f$ (eV)'
    else:
        energy_label = '$E$ (eV)'
    ncolors = max(3, len(self._cohps))
    ncolors = min(9, ncolors)
    import palettable
    colors = palettable.colorbrewer.qualitative.Set1_9.mpl_colors
    plt = pretty_plot(12, 8)
    allpts = []
    keys = self._cohps.keys()
    for (i, key) in enumerate(keys):
        energies = self._cohps[key]['energies']
        if not integrated:
            populations = self._cohps[key]['COHP']
        else:
            populations = self._cohps[key]['ICOHP']
        for spin in [Spin.up, Spin.down]:
            if spin in populations:
                if invert_axes:
                    x = -populations[spin] if plot_negative else populations[spin]
                    y = energies
                else:
                    x = energies
                    y = -populations[spin] if plot_negative else populations[spin]
                allpts.extend(list(zip(x, y)))
                if spin == Spin.up:
                    plt.plot(x, y, color=colors[i % ncolors], linestyle='-', label=str(key), linewidth=3)
                else:
                    plt.plot(x, y, color=colors[i % ncolors], linestyle='--', linewidth=3)
    if xlim:
        plt.xlim(xlim)
    if ylim:
        plt.ylim(ylim)
    else:
        xlim = plt.xlim()
        relevanty = [p[1] for p in allpts if xlim[0] < p[0] < xlim[1]]
        plt.ylim((min(relevanty), max(relevanty)))
    xlim = plt.xlim()
    ylim = plt.ylim()
    if not invert_axes:
        plt.plot(xlim, [0, 0], 'k-', linewidth=2)
        if self.zero_at_efermi:
            plt.plot([0, 0], ylim, 'k--', linewidth=2)
        else:
            plt.plot([self._cohps[key]['efermi'], self._cohps[key]['efermi']], ylim, color=colors[i % ncolors], linestyle='--', linewidth=2)
    else:
        plt.plot([0, 0], ylim, 'k-', linewidth=2)
        if self.zero_at_efermi:
            plt.plot(xlim, [0, 0], 'k--', linewidth=2)
        else:
            plt.plot(xlim, [self._cohps[key]['efermi'], self._cohps[key]['efermi']], color=colors[i % ncolors], linestyle='--', linewidth=2)
    if invert_axes:
        plt.xlabel(cohp_label)
        plt.ylabel(energy_label)
    else:
        plt.xlabel(energy_label)
        plt.ylabel(cohp_label)
    plt.legend()
    leg = plt.gca().get_legend()
    ltext = leg.get_texts()
    plt.setp(ltext, fontsize=30)
    plt.tight_layout()
    return plt

