def is_holiday(now=None, holidays='/etc/acct/holidays'):
    now = _Time(now)
    if not os.path.exists(holidays):
        raise Exception('There is no holidays file: %s' % holidays)
    f = open(holidays, 'r')
    line = f.readline()
    while line[0] == '*':
        line = f.readline()
    (year, primestart, primeend) = str.split(line)
    if not year == now.year:
        return 0
    while line != '':
        if line[0] == '*':
            line = f.readline()
            continue
        try:
            (month, day) = str.split(str.split(line)[0], '/')
            if len(day) == 1:
                day = '0' + day
            month = MONTH_MAP[int(month) - 1]
            if month == now.month and day == now.day:
                return 1
            line = f.readline()
        except:
            line = f.readline()
            continue
    return 0

def glob(patterns, parent=None, excludes=None, include_dotfiles=False, ignore_false_excludes=False):
    if not glob2:
        raise glob2_ext
    if isinstance(patterns, str):
        patterns = [patterns]
    if not parent:
        parent = os.getcwd()
    result = []
    for pattern in patterns:
        if not os.path.isabs(pattern):
            pattern = os.path.join(parent, pattern)
        result += glob2.glob(canonical(pattern))
    for pattern in excludes or ():
        if not os.path.isabs(pattern):
            pattern = os.path.join(parent, pattern)
        pattern = canonical(pattern)
        if not isglob(pattern):
            try:
                result.remove(pattern)
            except ValueError as exc:
                if not ignore_false_excludes:
                    raise ValueError('{} ({})'.format(exc, pattern))
        else:
            for item in glob2.glob(pattern):
                try:
                    result.remove(item)
                except ValueError as exc:
                    if not ignore_false_excludes:
                        raise ValueError('{} ({})'.format(exc, pattern))
    return result

def ask_and_eval(self, func, args=(), gradf=None, number=None, xmean=None, sigma_fac=1, evaluations=1, aggregation=np.median, kappa=1):
    popsize = self.sp.popsize
    if number is not None:
        popsize = number
    selective_mirroring = self.opts['CMA_mirrormethod'] > 0
    nmirrors = self.sp.lam_mirr
    if popsize != self.sp.popsize:
        nmirrors = Mh.sround(popsize * self.sp.lam_mirr / self.sp.popsize)
    assert new_injections or self.opts['CMA_mirrormethod'] < 2
    if new_injections and self.opts['CMA_mirrormethod'] != 1:
        nmirrors = 0
    assert nmirrors <= popsize // 2
    self.mirrors_idx = np.arange(nmirrors)
    self.mirrors_rejected_idx = []
    is_feasible = self.opts['is_feasible']
    fit = []
    X_first = self.ask(popsize, xmean=xmean, gradf=gradf, args=args)
    if xmean is None:
        xmean = self.mean
    X = []
    for k in xrange(int(popsize)):
        (x, f) = (X_first.pop(0), None)
        rejected = -1
        while rejected < 0 or not is_feasible(x, f):
            rejected += 1
            if rejected:
                x = self.ask(1, xmean, sigma_fac)[0]
            elif k >= popsize - nmirrors:
                if k == popsize - nmirrors and selective_mirroring:
                    self.mirrors_idx = np.argsort(fit)[-1:-1 - nmirrors:-1]
                x = self.get_mirror(X[self.mirrors_idx[popsize - 1 - k]])
            if rejected == 1 and k >= popsize - nmirrors:
                self.mirrors_rejected_idx.append(k)
            length_normalizer = 1
            f = func(x, *args) if kappa == 1 else func(xmean + kappa * length_normalizer * (x - xmean), *args)
            if is_feasible(x, f) and evaluations > 1:
                f = aggregation([f] + [func(x, *args) if kappa == 1 else func(xmean + kappa * length_normalizer * (x - xmean), *args) for _i in xrange(int(evaluations - 1))])
            if rejected + 1 % 1000 == 0:
                print('  %d solutions rejected (f-value NaN or None) at iteration %d' % (rejected, self.countiter))
        fit.append(f)
        X.append(x)
    self.evaluations_per_f_value = int(evaluations)
    return (X, fit)

def _user_to_rgba(color, expand=True, clip=False):
    if color is None:
        color = np.zeros(4, np.float32)
    if isinstance(color, string_types):
        color = _string_to_rgb(color)
    elif isinstance(color, ColorArray):
        color = color.rgba
    elif isinstance(color, (list, tuple)):
        if any((isinstance(c, string_types) for c in color)):
            color = [_user_to_rgba(c, expand=expand, clip=clip) for c in color]
            if any((len(c) > 1 for c in color)):
                raise RuntimeError('could not parse colors, are they nested?')
            color = [c[0] for c in color]
    color = np.atleast_2d(color).astype(np.float32)
    if color.shape[1] not in (3, 4):
        raise ValueError('color must have three or four elements')
    if expand and color.shape[1] == 3:
        color = np.concatenate((color, np.ones((color.shape[0], 1))), axis=1)
    if color.min() < 0 or color.max() > 1:
        if clip:
            color = np.clip(color, 0, 1)
        else:
            raise ValueError('Color values must be between 0 and 1 (or use clip=True to automatically clip the values).')
    return color

