def get_all_names(offset=None, count=None, include_expired=False, proxy=None, hostport=None):
    assert proxy or hostport, 'Need proxy or hostport'
    if proxy is None:
        proxy = connect_hostport(hostport)
    offset = 0 if offset is None else offset
    if count is None:
        count = get_num_names(proxy=proxy, hostport=hostport)
        if json_is_error(count):
            return count
        count -= offset
    page_size = 100
    all_names = []
    while len(all_names) < count:
        request_size = page_size
        if count - len(all_names) < request_size:
            request_size = count - len(all_names)
        page = get_all_names_page(offset + len(all_names), request_size, include_expired=include_expired, proxy=proxy, hostport=hostport)
        if json_is_error(page):
            return page
        if len(page) > request_size:
            error_str = 'server replied too much data'
            return {'error': error_str, 'http_status': 503}
        elif len(page) == 0:
            break
        all_names += page
    return all_names

def negative_directional_movement(high_data, low_data):
    catch_errors.check_for_input_len_diff(high_data, low_data)
    up_moves = calculate_up_moves(high_data)
    down_moves = calculate_down_moves(low_data)
    ndm = []
    for idx in range(0, len(down_moves)):
        if down_moves[idx] > up_moves[idx] and down_moves[idx] > 0:
            ndm.append(down_moves[idx])
        else:
            ndm.append(0)
    return ndm

def _ubridge_apply_filters(self, bridge_name, filters):
    yield from self._ubridge_send('bridge reset_packet_filters ' + bridge_name)
    for packet_filter in self._build_filter_list(filters):
        cmd = 'bridge add_packet_filter {} {}'.format(bridge_name, packet_filter)
        try:
            yield from self._ubridge_send(cmd)
        except UbridgeError as e:
            match = re.search("Cannot compile filter '(.*)': syntax error", str(e))
            if match:
                message = "Warning: ignoring BPF packet filter '{}' due to syntax error".format(self.name, match.group(1))
                log.warning(message)
                self.project.emit('log.warning', {'message': message})
            else:
                raise

def get_fields_for_exception(self, logger, exception):
    for klass in getmro(exception.__class__):
        if klass in self.registry:
            extractor = self.registry[klass]
            try:
                return extractor(exception)
            except:
                from ._traceback import write_traceback
                write_traceback(logger)
                return {}
    return {}

