def _execute_sbatch(self):
    commands = self.campaign.process.get('commands', {})
    sbatch = find_executable(commands.get('sbatch', 'sbatch'))
    sbatch_command = [sbatch, '--parsable', self.sbatch_filename]
    try:
        self.logger.debug('Executing command: %s', ' '.join(map(six.moves.shlex_quote, sbatch_command)))
        sbatch_out = subprocess.check_output(sbatch_command, universal_newlines=True)
    except subprocess.CalledProcessError as cpe:
        self.logger.error('SBATCH return non-zero exitstatus %d for tag %s', cpe.returncode, self.tag)
        sbatch_out = cpe.output
    jobidre = re.compile('^([\\d]+)(?:;\\S*)?$')
    jobid = None
    for line in sbatch_out.splitlines():
        res = jobidre.match(line)
        if res is not None:
            jobid = res.group(1)
            self.logger.info('Submitted SBATCH job %s for tag %s', jobid, self.tag)
        elif line:
            self.logger.warning('SBATCH: %s', line)
    if jobid is None:
        self.logger.error('SBATCH submission failed for tag %s', self.tag)
        return -1
    else:
        return int(jobid)

def build_wes_request(workflow_file, json_path, attachments=None):
    workflow_file = 'file://' + workflow_file if ':' not in workflow_file else workflow_file
    wfbase = None
    if json_path.startswith('file://'):
        wfbase = os.path.dirname(json_path[7:])
        json_path = json_path[7:]
        with open(json_path) as f:
            wf_params = json.dumps(json.load(f))
    elif json_path.startswith('http'):
        wf_params = modify_jsonyaml_paths(json_path)
    else:
        wf_params = json_path
    (wf_version, wf_type) = wf_info(workflow_file)
    parts = [('workflow_params', wf_params), ('workflow_type', wf_type), ('workflow_type_version', wf_version)]
    if workflow_file.startswith('file://'):
        if wfbase is None:
            wfbase = os.path.dirname(workflow_file[7:])
        parts.append(('workflow_attachment', (os.path.basename(workflow_file[7:]), open(workflow_file[7:], 'rb'))))
        parts.append(('workflow_url', os.path.basename(workflow_file[7:])))
    else:
        parts.append(('workflow_url', workflow_file))
    if wfbase is None:
        wfbase = os.getcwd()
    if attachments:
        for attachment in attachments:
            if attachment.startswith('file://'):
                attachment = attachment[7:]
                attach_f = open(attachment, 'rb')
                relpath = os.path.relpath(attachment, wfbase)
            elif attachment.startswith('http'):
                attach_f = urlopen(attachment)
                relpath = os.path.basename(attach_f)
            parts.append(('workflow_attachment', (relpath, attach_f)))
    return parts

def write_summary(self, global_step, delta_train_start, lesson_num=0):
    if global_step % self.trainer_parameters['summary_freq'] == 0 and global_step != 0:
        is_training = 'Training.' if self.is_training and self.get_step <= self.get_max_steps else 'Not Training.'
        if len(self.stats['Environment/Cumulative Reward']) > 0:
            mean_reward = np.mean(self.stats['Environment/Cumulative Reward'])
            LOGGER.info(' {}: {}: Step: {}. Time Elapsed: {:0.3f} s Mean Reward: {:0.3f}. Std of Reward: {:0.3f}. {}'.format(self.run_id, self.brain_name, min(self.get_step, self.get_max_steps), delta_train_start, mean_reward, np.std(self.stats['Environment/Cumulative Reward']), is_training))
        else:
            LOGGER.info(' {}: {}: Step: {}. No episode was completed since last summary. {}'.format(self.run_id, self.brain_name, self.get_step, is_training))
        summary = tf.Summary()
        for key in self.stats:
            if len(self.stats[key]) > 0:
                stat_mean = float(np.mean(self.stats[key]))
                summary.value.add(tag='{}'.format(key), simple_value=stat_mean)
                self.stats[key] = []
        summary.value.add(tag='Environment/Lesson', simple_value=lesson_num)
        self.summary_writer.add_summary(summary, self.get_step)
        self.summary_writer.flush()

def _folded_slices(self):
    if len(self) == 0:
        return
    prng = None
    istart = None
    m = 0
    for sli in self._contiguous_slices():
        start = sli.start
        stop = sli.stop
        unitary = start + 1 == stop
        if istart is None:
            if unitary:
                istart = start
            else:
                prng = [start, stop, 1]
                istart = stop - 1
            i = k = istart
        elif m == 0:
            if not unitary:
                if prng is not None:
                    yield slice(*prng)
                else:
                    yield slice(istart, istart + 1, 1)
                prng = [start, stop, 1]
                istart = k = stop - 1
                continue
            i = start
        else:
            assert m > 0
            i = start
            if m != i - k or not unitary:
                if m == i - k:
                    j = i
                else:
                    j = k
                stepped = j - istart >= self._autostep * m
                if prng:
                    if stepped:
                        prng[1] -= 1
                    else:
                        istart += m
                    yield slice(*prng)
                    prng = None
            if m != i - k:
                if stepped:
                    yield slice(istart, k + 1, m)
                else:
                    for j in range(istart, k - m + 1, m):
                        yield slice(j, j + 1, 1)
                    if not unitary:
                        yield slice(k, k + 1, 1)
                if unitary:
                    if stepped:
                        istart = i = k = start
                    else:
                        istart = k
                else:
                    prng = [start, stop, 1]
                    istart = i = k = stop - 1
            elif not unitary:
                if stepped:
                    yield slice(istart, i + 1, m)
                    i += 1
                else:
                    for j in range(istart, i - m + 1, m):
                        yield slice(j, j + 1, 1)
                if stop > i + 1:
                    prng = [i, stop, 1]
                istart = i = k = stop - 1
        m = i - k
        k = i
    if m == 0:
        if prng:
            yield slice(*prng)
        else:
            yield slice(istart, istart + 1, 1)
    else:
        assert m > 0
        stepped = k - istart >= self._autostep * m
        if prng:
            if stepped:
                prng[1] -= 1
            else:
                istart += m
            yield slice(*prng)
            prng = None
        if stepped:
            yield slice(istart, i + 1, m)
        else:
            for j in range(istart, i + 1, m):
                yield slice(j, j + 1, 1)

def data_validation(self, in_nc):
    data_nc = Dataset(in_nc)
    dims = list(data_nc.dimensions)
    if dims not in self.dims_oi:
        data_nc.close()
        raise Exception('{0} {1}'.format(self.error_messages[1], dims))
    nc_vars = list(data_nc.variables)
    if nc_vars == self.vars_oi[0]:
        self.runoff_vars = [self.vars_oi[0][-1]]
    elif nc_vars == self.vars_oi[1]:
        self.runoff_vars = [self.vars_oi[1][-1]]
    else:
        data_nc.close()
        raise Exception('{0} {1}'.format(self.error_messages[2], nc_vars))
    data_nc.close()

def _dfs_cycle_detect(graph, node, path, visited_nodes):
    visited_nodes.add(node)
    for target in graph[node]:
        if target in path:
            return path + [target]
        else:
            return _dfs_cycle_detect(graph, target, path + [target], visited_nodes)
    return None

