def _condensation_lil(self):
    condensation_lil = sparse.lil_matrix((self.num_strongly_connected_components, self.num_strongly_connected_components), dtype=bool)
    scc_proj = self.scc_proj
    for (node_from, node_to) in _csr_matrix_indices(self.csgraph):
        (scc_from, scc_to) = (scc_proj[node_from], scc_proj[node_to])
        if scc_from != scc_to:
            condensation_lil[scc_from, scc_to] = True
    return condensation_lil

def _load(self, keyframe=True):
    if self._cached:
        return
    pages = self.pages
    if not pages:
        return
    if not self._indexed:
        self._seek(-1)
    if not self._cache:
        return
    fh = self.parent.filehandle
    if keyframe is not None:
        keyframe = self._keyframe
    for (i, page) in enumerate(pages):
        if isinstance(page, inttypes):
            fh.seek(page)
            page = self._tiffpage(self.parent, index=i, keyframe=keyframe)
            pages[i] = page
    self._cached = True

