def valid_name(name):
    if isinstance(name, bytes):
        name = name.decode('ascii')
    if not Definitions.COOKIE_NAME_RE.match(name):
        return False
    if name[0] == '$':
        return False
    return True

def prepare_files(self, finder, force_root_egg_info=False, bundle=False):
    unnamed = list(self.unnamed_requirements)
    reqs = list(self.requirements.values())
    while reqs or unnamed:
        if unnamed:
            req_to_install = unnamed.pop(0)
        else:
            req_to_install = reqs.pop(0)
        req_version = None
        install = True
        best_installed = False
        if not self.ignore_installed and (not req_to_install.editable):
            req_to_install.check_if_exists()
            if req_to_install.satisfied_by:
                if self.upgrade:
                    if not self.force_reinstall:
                        try:
                            (url, req_version) = finder.find_requirement(req_to_install, self.upgrade)
                        except BestVersionAlreadyInstalled:
                            best_installed = True
                            install = False
                        else:
                            req_to_install.url = url.url
                    if not best_installed:
                        req_to_install.conflicts_with = req_to_install.satisfied_by
                        req_to_install.satisfied_by = None
                else:
                    install = False
            if req_to_install.satisfied_by:
                if best_installed:
                    logger.notify('Requirement already up-to-date: %s' % req_to_install)
                else:
                    logger.notify('Requirement already satisfied (use --upgrade to upgrade): %s' % req_to_install)
        if req_to_install.editable:
            logger.notify('Obtaining %s' % req_to_install)
        elif install:
            if req_to_install.url and req_to_install.url.lower().startswith('file:'):
                logger.notify('Unpacking %s' % display_path(url_to_path(req_to_install.url)))
            else:
                logger.notify('Downloading/unpacking %s' % req_to_install)
        logger.indent += 2
        try:
            is_bundle = False
            if req_to_install.editable:
                if req_to_install.source_dir is None:
                    location = req_to_install.build_location(self.src_dir)
                    req_to_install.source_dir = location
                else:
                    location = req_to_install.source_dir
                if not os.path.exists(self.build_dir):
                    _make_build_dir(self.build_dir)
                req_to_install.update_editable(not self.is_download)
                if self.is_download:
                    req_to_install.run_egg_info()
                    req_to_install.archive(self.download_dir)
                else:
                    req_to_install.run_egg_info()
            elif install:
                location = req_to_install.build_location(self.build_dir, not self.is_download)
                unpack = True
                if not os.path.exists(os.path.join(location, 'setup.py')):
                    if req_to_install.url is None:
                        (url, req_version) = finder.find_requirement(req_to_install, upgrade=self.upgrade)
                    else:
                        url = Link(req_to_install.url)
                        assert url
                    if url:
                        try:
                            self.unpack_url(req_to_install, req_version, url, location, self.is_download)
                        except HTTPError:
                            e = sys.exc_info()[1]
                            logger.fatal('Could not install requirement %s because of error %s' % (req_to_install, e))
                            raise InstallationError('Could not install requirement %s because of HTTP error %s for URL %s' % (req_to_install, e, url))
                    else:
                        unpack = False
                if unpack:
                    is_bundle = req_to_install.is_bundle
                    url = None
                    if is_bundle:
                        req_to_install.move_bundle_files(self.build_dir, self.src_dir)
                        for subreq in req_to_install.bundle_requirements():
                            reqs.append(subreq)
                            self.add_requirement(subreq)
                    elif self.is_download:
                        req_to_install.source_dir = location
                        if url and url.scheme in vcs.all_schemes:
                            req_to_install.run_egg_info()
                            req_to_install.archive(self.download_dir)
                    else:
                        req_to_install.source_dir = location
                        req_to_install.run_egg_info()
                        if force_root_egg_info:
                            req_to_install.run_egg_info(force_root_egg_info=True)
                        req_to_install.assert_source_matches_version()
                        if bundle and req_to_install.url:
                            self.copy_to_build_dir(req_to_install)
                            install = False
                    req_to_install.check_if_exists()
                    if req_to_install.satisfied_by:
                        if self.upgrade or self.ignore_installed:
                            req_to_install.conflicts_with = req_to_install.satisfied_by
                            req_to_install.satisfied_by = None
                        else:
                            install = False
            if not is_bundle and (not self.is_download):
                finder.add_dependency_links(req_to_install.dependency_links)
                if req_to_install.extras:
                    logger.notify('Installing extra requirements: %r' % ','.join(req_to_install.extras))
                if not self.ignore_dependencies:
                    for req in req_to_install.requirements(req_to_install.extras):
                        try:
                            name = pkg_resources.Requirement.parse(req).project_name
                        except ValueError:
                            e = sys.exc_info()[1]
                            logger.error('Invalid requirement: %r (%s) in requirement %s' % (req, e, req_to_install))
                            continue
                        if self.has_requirement(name):
                            continue
                        subreq = InstallRequirement(req, req_to_install)
                        reqs.append(subreq)
                        self.add_requirement(subreq)
                if req_to_install.name not in self.requirements:
                    self.requirements[req_to_install.name] = req_to_install
            else:
                self.reqs_to_cleanup.append(req_to_install)
            if install:
                self.successfully_downloaded.append(req_to_install)
                if bundle and (req_to_install.url and req_to_install.url.startswith('file:///')):
                    self.copy_to_build_dir(req_to_install)
        finally:
            logger.indent -= 2

def nice_report(self):
    if not self.json:
        return '[no CSP report data]'
    try:
        data = json.loads(self.json)
    except ValueError:
        return "Invalid CSP report: '{}'".format(self.json)
    if 'csp-report' not in data:
        return 'Invalid CSP report: ' + json.dumps(data, indent=4, sort_keys=True, separators=(',', ': '))
    return json.dumps(data['csp-report'], indent=4, sort_keys=True, separators=(',', ': '))

def descendants(self, include_clip=True):
    for layer in self:
        yield layer
        if layer.is_group():
            for child in layer.descendants(include_clip):
                yield child
        if include_clip and hasattr(layer, 'clip_layers'):
            for clip_layer in layer.clip_layers:
                yield clip_layer

def _construct_callbacks(self):
    cb_classes = set()
    registry = list(Stream.registry.items())
    callbacks = Stream._callbacks['bokeh']
    for source in self.link_sources:
        streams = [s for (src, streams) in registry for s in streams if src is source or (src._plot_id is not None and src._plot_id == source._plot_id)]
        cb_classes |= {(callbacks[type(stream)], stream) for stream in streams if type(stream) in callbacks and stream.linked and (stream.source is not None)}
    cbs = []
    sorted_cbs = sorted(cb_classes, key=lambda x: id(x[0]))
    for (cb, group) in groupby(sorted_cbs, lambda x: x[0]):
        cb_streams = [s for (_, s) in group]
        cbs.append(cb(self, cb_streams, source))
    return cbs

def _LookUpStack(self, name):
    i = len(self.stack) - 1
    while 1:
        frame = self.stack[i]
        if name == '@index':
            if frame.index != -1:
                return frame.index
        else:
            context = frame.context
            if hasattr(context, 'get'):
                try:
                    return context[name]
                except KeyError:
                    pass
        i -= 1
        if i <= -1:
            return self._Undefined(name)

def i_batch(items, size):
