def status_subversion(path, ignore_set, options):
    subrepos = ()
    if path in ignore_set:
        return (None, subrepos)
    keepers = []
    for line in run(['svn', 'st', '-v'], cwd=path):
        if not line.strip():
            continue
        if line.startswith(b'Performing') or line[0] in b'X?':
            continue
        status = line[:8]
        ignored_states = options.ignore_svn_states
        if ignored_states and status.strip() in ignored_states:
            continue
        filename = line[8:].split(None, 3)[-1]
        ignore_set.add(os.path.join(path, filename))
        if status.strip():
            keepers.append(b' ' + status + filename)
    return (keepers, subrepos)

def read(self, path, ext=None, start=None, stop=None, recursive=False, npartitions=None):
    path = uri_to_path(path)
    files = self.list(path, ext=ext, start=start, stop=stop, recursive=recursive)
    nfiles = len(files)
    self.nfiles = nfiles
    if spark and isinstance(self.engine, spark):
        npartitions = min(npartitions, nfiles) if npartitions else nfiles
        rdd = self.engine.parallelize(enumerate(files), npartitions)
        return rdd.map(lambda kv: (kv[0], readlocal(kv[1]), kv[1]))
    else:
        return [(k, readlocal(v), v) for (k, v) in enumerate(files)]

def restore_bios_config(irmc_info, bios_config):

    def _process_bios_config():
        try:
            if isinstance(bios_config, dict):
                input_data = bios_config
            else:
                input_data = jsonutils.loads(bios_config)
            bios_cfg = input_data['Server']['SystemConfig']['BiosConfig']
            bios_cfg['@Processing'] = 'execute'
            return input_data
        except (TypeError, ValueError, KeyError):
            raise scci.SCCIInvalidInputError('Invalid input bios config "%s".' % bios_config)
    input_data = _process_bios_config()
    try:
        elcm_profile_get(irmc_info=irmc_info, profile_name=PROFILE_BIOS_CONFIG)
        elcm_profile_delete(irmc_info=irmc_info, profile_name=PROFILE_BIOS_CONFIG)
    except ELCMProfileNotFound:
