def pseudo_inv_components(self, maxsing=None, eigthresh=1e-05, truncate=True):
    if maxsing is None:
        maxsing = self.get_maxsing(eigthresh=eigthresh)
    else:
        maxsing = min(self.get_maxsing(eigthresh=eigthresh), maxsing)
    s = self.full_s.copy()
    v = self.v.copy()
    u = self.u.copy()
    if truncate:
        s = s[:maxsing, :maxsing]
        v = v[:, :maxsing]
        u = u[:, :maxsing]
    else:
        new_s = self.full_s.copy()
        s = new_s
        s.x[maxsing:, maxsing:] = 0.0
        v.x[:, maxsing:] = 0.0
        u.x[:, maxsing:] = 0.0
    return (u, s, v)

def imap_unordered(self, jobs, timeout=0.5):
    timeout = max(timeout, 0.5)
    jobs_iter = iter(jobs)
    out_jobs = 0
    job = None
    while True:
        if not self.closed and job is None:
            try:
                job = jobs_iter.next()
            except StopIteration:
                job = None
                self.close()
        if job is not None:
            try:
                self.put(job, True, timeout)
            except Queue.Full:
                pass
            else:
                job = None
        for result in self.get_finished():
            yield result
        if self.closed and self._items == 0:
            break
        sleep(timeout)

