def scp_put(self, src, dst):
    cmd = ['scp', '-B', '-oStrictHostKeyChecking=no', '-oUserKnownHostsFile=/dev/null', '-oLogLevel=ERROR']
    if self._key is not None:
        cmd.extend(['-i', self._key])
    cmd.append(src)
    remote = ''
    if self._user is not None:
        remote += self._user + '@'
    remote += self._ip + ':' + dst
    cmd.append(remote)
    try:
        subprocess.check_output(cmd, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as ex:
        raise RuntimeError('scp returned exit status %d:\n%s' % (ex.returncode, ex.output.strip()))

