def noperiodic(r_array, periodic, reference=None):
    if reference is None:
        center = r_array[0]
    else:
        center = reference
    dr = center - r_array
    drsign = np.sign(dr)
    tomove = np.abs(dr) >= periodic / 2.0
    r_array[tomove] += (drsign * periodic)[tomove]
    return r_array

