def _get_usage(function, *args):
    res = None

    def _get_summaries(function, *args):
        s_before = summary.summarize(get_objects())
        function(*args)
        s_after = summary.summarize(get_objects())
        return (s_before, s_after)

    def _get_usage(function, *args):
        res = []
        (s_before, s_after) = _get_summaries(function, *args)
        ignore = []
        if s_before != s_after:
            ignore.append(s_before)
        for row in s_before:
            if len(gc.get_referrers(row)) == 2:
                ignore.append(row)
            for item in row:
                if len(gc.get_referrers(item)) == 2:
                    ignore.append(item)
        for o in ignore:
            s_after = summary._subtract(s_after, o)
        res = summary.get_diff(s_before, s_after)
        return summary._sweep(res)

    def noop():
        pass
    offset = _get_usage(noop)
    offset = _get_usage(noop)
    tmp = _get_usage(function, *args)
    tmp = _get_usage(function, *args)
    tmp = summary.get_diff(offset, tmp)
    tmp = summary._sweep(tmp)
    if len(tmp) != 0:
        res = tmp
    return res

def process_date_from_to_options(options, to_datetime=False, default_dt_to=False):
    start_time = datetime.datetime.now()
    if options.get('last_week'):
        dt_from = start_time - datetime.timedelta(days=7)
        dt_to = start_time
    elif options.get('last_day'):
        dt_from = start_time - datetime.timedelta(days=1)
        dt_to = start_time
    elif options.get('last_2hours'):
        dt_from = start_time - datetime.timedelta(hours=2)
        dt_to = start_time
    else:
        from_str = options.get('from')
        if from_str:
            try:
                dt_from = iso_to_datetime(from_str)
            except:
                dt_from = iso_to_date(from_str)
        else:
            dt_from = None
        to_str = options.get('to')
        if to_str:
            try:
                dt_to = iso_to_datetime(to_str)
            except:
                dt_to = iso_to_date(to_str)
        else:
            dt_to = None
    if default_dt_to and (not dt_to):
        dt_to = datetime.datetime(2100, 1, 1)
    if to_datetime:
        if isinstance(dt_from, datetime.date):
            dt_from = date_to_datetime(dt_from)
        if isinstance(dt_to, datetime.date):
            dt_to = date_to_datetime_lte(dt_to)
    return (dt_from, dt_to)

