def _make_record(self, level, fmt, args, extra, exc_info, inc_stackinfo, inc_multiproc):
    fn = fname = '(unknown file)'
    lno = 0
    func = '(unknown function)'
    code = '(code not available)'
    cc = []
    sinfo = None
    module = '(unknown module)'
    if _srcfile and inc_stackinfo:
        try:
            (fn, lno, func, code, cc, sinfo) = self._find_caller()
            fname = os.path.basename(fn)
            module = os.path.splitext(fname)[0]
        except ValueError:
            pass
    if not exc_info or not isinstance(exc_info, tuple):
        exc_info = sys.exc_info()
    log_record = {'asctime': time.asctime(), 'code': code, 'codecontext': ''.join(cc), 'excinfo': exc_info, 'filename': fname, 'funcname': func, 'levelname': level, 'levelno': ALL.index(level), 'lineno': lno, 'logmessage': None, 'messagefmt': fmt, 'module': module, 'pathname': fn, 'process': os.getpid(), 'processname': None, 'stackinfo': sinfo, 'threadid': None, 'threadname': None, 'time': time.time(), 'defaultfmt': self.config['defaultfmt']}
    if args:
        if isinstance(args, (tuple, list)) and len(args) == 1 and isinstance(args[0], dict):
            log_record['logmessage'] = fmt.format(**args[0])
        else:
            log_record['logmessage'] = fmt.format(*args)
    else:
        log_record['logmessage'] = fmt
    if extra:
        log_record.update(extra)
    if threading:
        curthread = threading.current_thread()
        log_record.update({'threadid': curthread.ident, 'threadname': curthread.name})
    if not inc_multiproc:
        procname = None
    else:
        procname = 'MainProcess'
        if mp:
            try:
                procname = mp.curent_process().name
            except StandardError:
                pass
    log_record['processname'] = procname
    return log_record

