    (b, s) = (ball_tally, strike_tally)
    if pitch_res == 'B':
        if ball_tally < 4:
            b += 1
    elif pitch_res == 'S' or pitch_res == 'C' or pitch_res == 'X':
        if strike_tally < 3:
            s += 1
    elif pitch_res == 'F':
        if strike_tally < 2:
            s += 1
    return (b, s)

