def start(self):
    if not self._done_event.is_set():
        return
    self._done_event.clear()
    nb_pending_tasks = self._queue.qsize()
    if nb_pending_tasks > self._max_threads:
        nb_threads = self._max_threads
        nb_pending_tasks = self._max_threads
    elif nb_pending_tasks < self._min_threads:
        nb_threads = self._min_threads
    else:
        nb_threads = nb_pending_tasks
    for _ in range(nb_pending_tasks):
        self.__nb_pending_task += 1
        self.__start_thread()
    for _ in range(nb_threads - nb_pending_tasks):
        self.__start_thread()

def finger(self, match, hash_type=None):
    if hash_type is None:
        hash_type = __opts__['hash_type']
    matches = self.name_match(match, True)
    ret = {}
    for (status, keys) in six.iteritems(matches):
        ret[status] = {}
        for key in keys:
            if status == 'local':
                path = os.path.join(self.opts['pki_dir'], key)
            else:
                path = os.path.join(self.opts['pki_dir'], status, key)
            ret[status][key] = salt.utils.crypt.pem_finger(path, sum_type=hash_type)
    return ret

