def _find_closest_trackpointaA(self, Or, Op, Oz, ar, ap, az, interp=True):
    da = numpy.stack(numpy.meshgrid(_TWOPIWRAPS + ar - self._progenitor_angle[0], _TWOPIWRAPS + ap - self._progenitor_angle[1], _TWOPIWRAPS + az - self._progenitor_angle[2], indexing='xy')).T.reshape((len(_TWOPIWRAPS) ** 3, 3))
    dapar = self._sigMeanSign * numpy.dot(da[numpy.argmin(numpy.linalg.norm(numpy.cross(da, self._dsigomeanProgDirection), axis=1))], self._dsigomeanProgDirection)
    if interp:
        dist = numpy.fabs(dapar - self._interpolatedThetasTrack)
    else:
        dist = numpy.fabs(dapar - self._thetasTrack)
    return numpy.argmin(dist)

