def get_option_flags(option_num):
    opt_bytes = array.array('B', '\x00\x00')
    if option_num < 256:
        s = struct.Struct('!B')
        s.pack_into(opt_bytes, 0, option_num)
    else:
        s = struct.Struct('H')
        s.pack_into(opt_bytes, 0, option_num)
    critical = opt_bytes[0] & 1 > 0
    unsafe = opt_bytes[0] & 2 > 0
    nocache = opt_bytes[0] & 30 == 28
    return (critical, unsafe, nocache)

