                class_obj = p[2]
                if not isinstance(class_obj, CIMClass):
                    raise CIMXMLParseError(_format('Expecting CIMClass object in QueryResultClass output parameter, got {0} object', class_obj.__class__.__name__), conn_id=self.conn_id)
                return class_obj
        raise CIMXMLParseError('QueryResultClass output parameter is missing', conn_id=self.conn_id)
    exc = None
    result_tuple = None
    method_name = 'OpenQueryInstances'
    if self._operation_recorders:
        self.operation_recorder_reset(pull_op=True)
        self.operation_recorder_stage_pywbem_args(method=method_name, FilterQueryLanguage=FilterQueryLanguage, FilterQuery=FilterQuery, namespace=namespace, ReturnQueryResultClass=ReturnQueryResultClass, OperationTimeout=OperationTimeout, ContinueOnError=ContinueOnError, MaxObjectCount=MaxObjectCount, **extra)
    try:
        stats = self.statistics.start_timer(method_name)
        namespace = self._iparam_namespace_from_namespace(namespace)
        result = self._imethodcall(method_name, namespace, FilterQuery=FilterQuery, FilterQueryLanguage=FilterQueryLanguage, ReturnQueryResultClass=ReturnQueryResultClass, OperationTimeout=OperationTimeout, ContinueOnError=ContinueOnError, MaxObjectCount=MaxObjectCount, has_out_params=True, **extra)
        (insts, eos, enum_ctxt) = self._get_rslt_params(result, namespace)
        query_result_class = _GetQueryRsltClass(result) if ReturnQueryResultClass else None
        result_tuple = pull_query_result_tuple(insts, eos, enum_ctxt, query_result_class)
        return result_tuple
    except (CIMXMLParseError, XMLParseError) as exce:
        exce.request_data = self.last_raw_request
        exce.response_data = self.last_raw_reply
        exc = exce
        raise
    except Exception as exce:
        exc = exce
        raise
    finally:
        self._last_operation_time = stats.stop_timer(self.last_request_len, self.last_reply_len, self.last_server_response_time, exc)
        if self._operation_recorders:
            self.operation_recorder_stage_result(result_tuple, exc)

def _build_credentials_tuple(mech, source, user, passwd, extra):
    user = _unicode(user) if user is not None else None
    password = passwd if passwd is None else _unicode(passwd)
    if mech == 'GSSAPI':
        properties = extra.get('authmechanismproperties', {})
        service_name = properties.get('SERVICE_NAME', 'mongodb')
        canonicalize = properties.get('CANONICALIZE_HOST_NAME', False)
        service_realm = properties.get('SERVICE_REALM')
        props = GSSAPIProperties(service_name=service_name, canonicalize_host_name=canonicalize, service_realm=service_realm)
        return MongoCredential(mech, '$external', user, password, props)
    elif mech == 'MONGODB-X509':
        return MongoCredential(mech, '$external', user, None, None)
    else:
        if passwd is None:
            raise ConfigurationError('A password is required.')
        return MongoCredential(mech, source, user, password, None)

def grok(cls, value, value_type, visitor):
    is_coll = issubclass(value_type, Collection)
    is_record = issubclass(value_type, Record) and any((not visitor.is_filtered(prop) for prop in value_type.properties.values()))
    if is_record and (not isinstance(value, cls.grok_mapping_types)):
        raise exc.VisitorGrokRecordError(val=repr(value), record_type=value_type, record_type_name=value_type.__name__, field_selector=visitor.field_selector)
    values = value
    if is_coll and is_record:
        try:
            if 'values' in value:
                values = value['values']
        except TypeError:
            pass
    generator = None
    if is_coll:
        if not isinstance(values, cls.grok_coll_types):
            raise exc.VisitorGrokCollectionError(val=repr(values), record_type=value_type, record_type_name=value_type.__name__, field_selector=visitor.field_selector)
        generator = value_type.coll_to_tuples(values)
    propget = None
    if is_record:

        def propget(prop):
            return value[prop.name]
    return (propget, generator)

