def toposort(data):
    if len(data) == 0:
        return
    data = data.copy()
    for (k, v) in data.items():
        v.discard(k)
    extra_items_in_deps = reduce(set.union, data.values()) - set(data.keys())
    data.update(dict(((item, set()) for item in extra_items_in_deps)))
    while True:
        ordered = set((item for (item, dep) in data.items() if len(dep) == 0))
        if not ordered:
            break
        yield ordered
        data = dict(((item, dep - ordered) for (item, dep) in data.items() if item not in ordered))
    if len(data) != 0:
        raise CyclicDependency(data)

def set_job(user, minute, hour, daymonth, month, dayweek, cmd, commented=False, comment=None, identifier=None):
    minute = six.text_type(minute).lower()
    hour = six.text_type(hour).lower()
    daymonth = six.text_type(daymonth).lower()
    month = six.text_type(month).lower()
    dayweek = six.text_type(dayweek).lower()
    lst = list_tab(user)
    for cron in lst['crons']:
        cid = _cron_id(cron)
        if _cron_matched(cron, cmd, identifier):
            test_setted_id = cron['identifier'] is None and SALT_CRON_NO_IDENTIFIER or cron['identifier']
            tests = [(cron['comment'], comment), (cron['commented'], commented), (identifier, test_setted_id), (cron['minute'], minute), (cron['hour'], hour), (cron['daymonth'], daymonth), (cron['month'], month), (cron['dayweek'], dayweek)]
            if cid or identifier:
                tests.append((cron['cmd'], cmd))
            if any([_needs_change(x, y) for (x, y) in tests]):
                rm_job(user, cmd, identifier=cid)
                if not _needs_change(cron['minute'], minute):
                    minute = cron['minute']
                if not _needs_change(cron['hour'], hour):
                    hour = cron['hour']
                if not _needs_change(cron['daymonth'], daymonth):
                    daymonth = cron['daymonth']
                if not _needs_change(cron['month'], month):
                    month = cron['month']
                if not _needs_change(cron['dayweek'], dayweek):
                    dayweek = cron['dayweek']
                if not _needs_change(cron['commented'], commented):
                    commented = cron['commented']
                if not _needs_change(cron['comment'], comment):
                    comment = cron['comment']
                if not _needs_change(cron['cmd'], cmd):
                    cmd = cron['cmd']
                    if cid == SALT_CRON_NO_IDENTIFIER:
                        if identifier:
                            cid = identifier
                        if cid == SALT_CRON_NO_IDENTIFIER and cron['identifier'] is None:
                            cid = None
                        cron['identifier'] = cid
                if not cid or (cid and (not _needs_change(cid, identifier))):
                    identifier = cid
                jret = set_job(user, minute, hour, daymonth, month, dayweek, cmd, commented=commented, comment=comment, identifier=identifier)
                if jret == 'new':
                    return 'updated'
                else:
                    return jret
            return 'present'
    cron = {'cmd': cmd, 'identifier': identifier, 'comment': comment, 'commented': commented}
    cron.update(_get_cron_date_time(minute=minute, hour=hour, daymonth=daymonth, month=month, dayweek=dayweek))
    lst['crons'].append(cron)
    comdat = _write_cron_lines(user, _render_tab(lst))
    if comdat['retcode']:
        return comdat['stderr']
    return 'new'

def lift(data, addr, arch, max_bytes=None, max_inst=None, bytes_offset=0, opt_level=1, traceflags=0, strict_block_end=True, inner=False, skip_stmts=False, collect_data_refs=False):
    if max_bytes is not None and max_bytes <= 0:
        raise PyVEXError('Cannot lift block with no data (max_bytes <= 0)')
    if not data:
        raise PyVEXError('Cannot lift block with no data (data is empty)')
    if isinstance(data, str):
        raise TypeError('Cannot pass unicode string as data to lifter')
    if isinstance(data, bytes):
        py_data = data
        c_data = None
        allow_arch_optimizations = False
    else:
        if max_bytes is None:
            raise PyVEXError('Cannot lift block with ffi pointer and no size (max_bytes is None)')
        c_data = data
        py_data = None
        allow_arch_optimizations = True
    if opt_level < 0:
        allow_arch_optimizations = False
        opt_level = 0
    for lifter in lifters[arch.name]:
        try:
            u_data = data
            if lifter.REQUIRE_DATA_C:
                if c_data is None:
                    u_data = ffi.new('unsigned char [%d]' % (len(py_data) + 8), py_data + b'\x00' * 8)
                    max_bytes = min(len(py_data), max_bytes) if max_bytes is not None else len(py_data)
                else:
                    u_data = c_data
            elif lifter.REQUIRE_DATA_PY:
                if py_data is None:
                    if max_bytes is None:
                        l.debug('Cannot create py_data from c_data when no max length is given')
                        continue
                    u_data = ffi.buffer(c_data, max_bytes)[:]
                else:
                    u_data = py_data
            try:
                final_irsb = lifter(arch, addr)._lift(u_data, bytes_offset, max_bytes, max_inst, opt_level, traceflags, allow_arch_optimizations, strict_block_end, skip_stmts, collect_data_refs)
            except SkipStatementsError:
                assert skip_stmts is True
                final_irsb = lifter(arch, addr)._lift(u_data, bytes_offset, max_bytes, max_inst, opt_level, traceflags, allow_arch_optimizations, strict_block_end, skip_stmts=False, collect_data_refs=collect_data_refs)
            break
        except LiftingException as ex:
            l.debug('Lifting Exception: %s', str(ex))
            continue
    else:
        final_irsb = IRSB.empty_block(arch, addr, size=0, nxt=Const(const.vex_int_class(arch.bits)(addr)), jumpkind='Ijk_NoDecode')
        final_irsb.invalidate_direct_next()
        return final_irsb
    if final_irsb.size > 0 and final_irsb.jumpkind == 'Ijk_NoDecode':
        nodecode_addr_expr = final_irsb.next
        if type(nodecode_addr_expr) is Const:
            nodecode_addr = nodecode_addr_expr.con.value
            next_irsb_start_addr = addr + final_irsb.size
            if nodecode_addr != next_irsb_start_addr:
                final_irsb.jumpkind = 'Ijk_NoDecode'
                final_irsb.next = final_irsb.next
                final_irsb.invalidate_direct_next()
                return final_irsb
        if skip_stmts:
            return lift(data, addr, arch, max_bytes=max_bytes, max_inst=max_inst, bytes_offset=bytes_offset, opt_level=opt_level, traceflags=traceflags, strict_block_end=strict_block_end, skip_stmts=False, collect_data_refs=collect_data_refs)
        next_addr = addr + final_irsb.size
        if max_bytes is not None:
            max_bytes -= final_irsb.size
        if isinstance(data, (str, bytes)):
            data_left = data[final_irsb.size:]
        else:
            data_left = data + final_irsb.size
        if max_inst is not None:
            max_inst -= final_irsb.instructions
        if (max_bytes is None or max_bytes > 0) and (max_inst is None or max_inst > 0) and data_left:
            more_irsb = lift(data_left, next_addr, arch, max_bytes=max_bytes, max_inst=max_inst, bytes_offset=bytes_offset, opt_level=opt_level, traceflags=traceflags, strict_block_end=strict_block_end, inner=True, skip_stmts=False, collect_data_refs=collect_data_refs)
            if more_irsb.size:
                final_irsb.extend(more_irsb)
        elif max_bytes == 0:
            if final_irsb.size > 0 and final_irsb.jumpkind == 'Ijk_NoDecode':
                final_irsb.jumpkind = 'Ijk_Boring'
                final_irsb.next = Const(vex_int_class(arch.bits)(final_irsb.addr + final_irsb.size))
    if not inner:
        for postprocessor in postprocessors[arch.name]:
            try:
                postprocessor(final_irsb).postprocess()
            except NeedStatementsNotification:
                if not skip_stmts:
                    raise TypeError('Bad post-processor %s: NeedStatementsNotification is raised when statements are available.' % postprocessor.__class__)
                return lift(data, addr, arch, max_bytes=max_bytes, max_inst=max_inst, bytes_offset=bytes_offset, opt_level=opt_level, traceflags=traceflags, strict_block_end=strict_block_end, inner=inner, skip_stmts=False, collect_data_refs=collect_data_refs)
            except LiftingException:
                continue
    return final_irsb

