def encode_varint_1(num):
    num = num << 1 ^ num >> 63
    buf = bytearray(10)
    for i in range(10):
        buf[i] = num & 127 | (128 if num > 127 else 0)
        num = num >> 7
        if num == 0:
            break
    else:
        raise ValueError('Out of double range')
    return buf[:i + 1]

