def send_message(self, request: str, response_expected: bool, **kwargs: Any) -> Response:
    payload = str(request) + self.delimiter
    self.socket.send(payload.encode(self.encoding))
    response = bytes()
    decoded = None
    while True:
        response += self.socket.recv(1024)
        decoded = response.decode(self.encoding)
        if len(decoded) < self.delimiter_length:
            continue
        elif decoded[-self.delimiter_length:] == self.delimiter:
            break
    assert decoded is not None
    return Response(decoded[:-self.delimiter_length])

def _wait_for_handles(handles, timeout=-1):
    arrtype = HANDLE * len(handles)
    handle_array = arrtype(*handles)
    ret = windll.kernel32.WaitForMultipleObjects(len(handle_array), handle_array, BOOL(False), DWORD(timeout))
    if ret == WAIT_TIMEOUT:
        return None
    else:
        h = handle_array[ret]
        return h

def _process_query(self, query):
    (key, val) = query
    (field_name, field_action) = split_field_action(key)
    boost = self.field_boosts.get(key)
    if boost is None:
        boost = self.field_boosts.get(field_name)
    handler_name = 'process_query_{0}'.format(field_action)
    if field_action and hasattr(self, handler_name):
        return getattr(self, handler_name)(field_name, val, field_action)
    elif field_action in QUERY_ACTION_MAP:
        return {QUERY_ACTION_MAP[field_action]: _boosted_value(field_name, field_action, key, val, boost)}
    elif field_action == 'query_string':
        return {'query_string': {'default_field': field_name, 'query': val}}
    elif field_action in RANGE_ACTIONS:
        return {'range': {field_name: _boosted_value(field_action, field_action, key, val, boost)}}
    elif field_action == 'range':
        (lower, upper) = val
        value = {'gte': lower, 'lte': upper}
        if boost:
            value['boost'] = boost
        return {'range': {field_name: value}}
    raise InvalidFieldActionError('%s is not a valid field action' % field_action)

def from_bboxes(bboxes):
    north = max([b.north for b in bboxes])
    south = min([b.south for b in bboxes])
    west = min([b.west for b in bboxes])
    east = max([b.east for b in bboxes])
    return BoundingBox(north=north, west=west, south=south, east=east)

def _fused_batch_norm_op(self, input_batch, mean, variance, use_batch_stats):
    mean_shape = mean.get_shape()
    variance_shape = variance.get_shape()
    gamma_flatten = tf.reshape(self._gamma, shape=(-1,))
    beta_flatten = tf.reshape(self._beta, shape=(-1,))
    flatten_mean = tf.reshape(mean, shape=(-1,))
    flatten_variance = tf.reshape(variance, shape=(-1,))
    use_batch_stats = tf.convert_to_tensor(use_batch_stats)
    common_args = {'scale': gamma_flatten, 'offset': beta_flatten, 'epsilon': self._eps, 'data_format': self._infer_fused_data_format(input_batch), 'name': 'batch_norm'}

    def use_batch_stats_fused_batch_norm():
        return tf.nn.fused_batch_norm(input_batch, mean=None, variance=None, is_training=True, **common_args)

    def moving_average_fused_batch_norm():
        return tf.nn.fused_batch_norm(input_batch, mean=flatten_mean, variance=flatten_variance, is_training=False, **common_args)
    (batch_norm_op, mean, variance) = utils.smart_cond(use_batch_stats, use_batch_stats_fused_batch_norm, moving_average_fused_batch_norm)
    mean = tf.reshape(mean, mean_shape)
    variance = tf.reshape(variance, variance_shape)
    return (batch_norm_op, mean, variance)

