def from_bytes(self, raw):
    if len(raw) < Ethernet._MINLEN:
        raise NotEnoughDataError('Not enough bytes ({}) to reconstruct an Ethernet object'.format(len(raw)))
    (dst, src, ethertype) = struct.unpack(Ethernet._PACKFMT, raw[:Ethernet._MINLEN])
    self.src = src
    self.dst = dst
    if ethertype <= 1500:
        self.ethertype = EtherType.NoType
    else:
        self.ethertype = ethertype
    return raw[Ethernet._MINLEN:]

def read(self, filename=None):
    if filename is None:
        filename = self.pathname
    stream = open(filename, 'rb')
    magic = struct.unpack('>H', stream.read(2))[0]
    stream.close()
    if magic == Seq.Magic:
        self.readBinary(filename)
    else:
        self.readText(filename)

