def accept(self, logevent):
    dt = logevent.datetime
    if not dt:
        return False
    mask = next((mask for mask in self.mask_list if mask[0] < dt and mask[1] > dt), None)
    return True if mask else False

def keys_breadth_first(self, include_dicts=False):
    namespaces = []
    for key in self._key_order:
        if isinstance(getattr(self, key), DotDict):
            namespaces.append(key)
            if include_dicts:
                yield key
        else:
            yield key
    for a_namespace in namespaces:
        for key in self[a_namespace].keys_breadth_first(include_dicts):
            yield ('%s.%s' % (a_namespace, key))

def _split_column_and_labels(self, column_or_label):
