    return (column, labels)

def limits(table, field):
    vals = iter(values(table, field))
    try:
        minv = maxv = next(vals)
    except StopIteration:
        return (None, None)
    else:
        for v in vals:
            if v < minv:
                minv = v
            if v > maxv:
                maxv = v
        return (minv, maxv)

