def iso8601_date(d):
    if d == values.unset:
        return d
    elif isinstance(d, datetime.datetime):
        return str(d.date())
    elif isinstance(d, datetime.date):
        return str(d)
    elif isinstance(d, str):
        return d

def upgrade(reboot=False, at_time=None):
    result = __salt__['pkg.install'](name='{0}-{1}'.format(_package_prefix(), latest_available()))
    _needs_reboot = needs_reboot()
    ret = {'upgrades': result, 'active': active(), 'latest_installed': latest_installed(), 'reboot_requested': reboot, 'reboot_required': _needs_reboot}
    if reboot and _needs_reboot:
        log.warning('Rebooting system due to kernel upgrade')
        __salt__['system.reboot'](at_time=at_time)
    return ret

def id(self):
    try:
        return os.environ['BLINKA_FORCEBOARD']
    except KeyError:
        pass
    chip_id = self.detector.chip.id
    board_id = None
    if chip_id == ap_chip.BCM2XXX:
        board_id = self._pi_id()
    elif chip_id == ap_chip.AM33XX:
        board_id = self._beaglebone_id()
    elif chip_id == ap_chip.GENERIC_X86:
        board_id = GENERIC_LINUX_PC
    elif chip_id == ap_chip.SUN8I:
        board_id = self._armbian_id()
    elif chip_id == ap_chip.SAMA5:
        board_id = self._sama5_id()
    elif chip_id == ap_chip.ESP8266:
        board_id = FEATHER_HUZZAH
    elif chip_id == ap_chip.SAMD21:
        board_id = FEATHER_M0_EXPRESS
    elif chip_id == ap_chip.STM32:
        board_id = PYBOARD
    elif chip_id == ap_chip.S805:
        board_id = ODROID_C1
    elif chip_id == ap_chip.S905:
        board_id = ODROID_C2
    elif chip_id == ap_chip.FT232H:
        board_id = FTDI_FT232H
    elif chip_id in (ap_chip.T210, ap_chip.T186, ap_chip.T194):
        board_id = self._tegra_id()
    return board_id

def nla_put(msg, attrtype, datalen, data):
    nla = nla_reserve(msg, attrtype, datalen)
    if not nla:
        return -NLE_NOMEM
    if datalen <= 0:
        return 0
    nla_data(nla)[:datalen] = data[:datalen]
    _LOGGER.debug('msg 0x%x: attr <0x%x> %d: Wrote %d bytes at offset +%d', id(msg), id(nla), nla.nla_type, datalen, nla.bytearray.slice.start - nlmsg_data(msg.nm_nlh).slice.start)
    return 0

