def _build_update_ops(self, mean, variance, is_training):

    def build_update_ops():
        update_mean_op = moving_averages.assign_moving_average(variable=self._moving_mean, value=tf.reshape(mean, (self._num_channels,)), decay=self._decay_rate, zero_debias=False, name='update_moving_mean').op
        update_variance_op = moving_averages.assign_moving_average(variable=self._moving_variance, value=tf.reshape(variance, (self._num_channels,)), decay=self._decay_rate, zero_debias=False, name='update_moving_variance').op
        return (update_mean_op, update_variance_op)

    def build_no_ops():
        return (tf.no_op(), tf.no_op())
    is_training_const = utils.constant_value(is_training)
    if is_training_const is None or is_training_const:
        (update_mean_op, update_variance_op) = utils.smart_cond(is_training, build_update_ops, build_no_ops)
        return (update_mean_op, update_variance_op)
    else:
        return None

def create_items(self, session_items):
    pks = list(session_items.keys())
    items = {}
    item_class = self.item_class
    process_object = self.process_object
    for obj in self.get_queryset(pks):
        pk = str(obj.pk)
        obj = process_object(obj)
        items[pk] = item_class(obj, **session_items[pk])
    if len(items) < len(session_items):
        self._stale_pks = set(session_items).difference(items)
    return items

def _adjust_datetime(self, sampfrom):
    if sampfrom:
        dt_seconds = sampfrom / self.fs
        if self.base_date and self.base_time:
            self.base_datetime = datetime.datetime.combine(self.base_date, self.base_time)
            self.base_datetime += datetime.timedelta(seconds=dt_seconds)
            self.base_date = self.base_datetime.date()
            self.base_time = self.base_datetime.time()
        elif self.base_time:
            tmp_datetime = datetime.datetime.combine(datetime.datetime.today().date(), self.base_time)
            self.base_time = (tmp_datetime + datetime.timedelta(seconds=dt_seconds)).time()

def make_box_pixel_mask_from_col_row(column, row, default=0, value=1):
    col_array = np.array(column) - 1
    row_array = np.array(row) - 1
    if np.any(col_array >= 80) or np.any(col_array < 0) or np.any(row_array >= 336) or np.any(row_array < 0):
        raise ValueError('Column and/or row out of range')
    shape = (80, 336)
    mask = np.full(shape, default, dtype=np.uint8)
    if column and row:
        mask[col_array.min():col_array.max() + 1, row_array.min():row_array.max() + 1] = value
    return mask

def _is_free_link_end(self, this, next):
    (after, ctx) = (self._read(2), self._context)
