def configured_logger(self, name=None):
    log_handlers = self.log_handlers
    if not name:
        basename = 'pulsar'
        name = self.name
        if name and name != basename:
            name = '%s.%s' % (basename, name)
        else:
            name = basename
    namespaces = {}
    for log_level in self.log_level or ():
        bits = log_level.split('.')
        namespaces['.'.join(bits[:-1]) or ''] = bits[-1]
    for namespace in sorted(namespaces):
        if self.daemon:
            handlers = []
            for hnd in log_handlers:
                if hnd != 'console':
                    handlers.append(hnd)
            if not handlers:
                handlers.append('file')
            log_handlers = handlers
        configured_logger(namespace, config=self.log_config, level=namespaces[namespace], handlers=log_handlers)
    return logging.getLogger(name)

