def locality_preserving_projections(self, coordinates, num_dims=None):
    X = np.atleast_2d(coordinates)
    L = self.laplacian(normed=True)
    (u, s, _) = np.linalg.svd(X.T.dot(X))
    Fplus = np.linalg.pinv(u * np.sqrt(s))
    (n, d) = X.shape
    if n >= d:
        T = Fplus.dot(X.T.dot(L.dot(X))).dot(Fplus.T)
    else:
        T = Fplus.dot(X.T).dot(L.dot(X.dot(Fplus.T)))
    L = 0.5 * (T + T.T)
    return _null_space(L, num_vecs=num_dims, overwrite=True)

def fromOctetString(cls, value, internalFormat=False, prepend=None, padding=0):
    value = SizedInteger(integer.from_bytes(value) >> padding).setBitLength(len(value) * 8 - padding)
    if prepend is not None:
        value = SizedInteger(SizedInteger(prepend) << len(value) | value).setBitLength(len(prepend) + len(value))
    if not internalFormat:
        value = cls(value)
    return value

