def parse_datetime(s):
    m = re.match(' ^\n        (?P<year>-?[0-9]{4}) - (?P<month>[0-9]{2}) - (?P<day>[0-9]{2})\n        T (?P<hour>[0-9]{2}) : (?P<minute>[0-9]{2}) : (?P<second>[0-9]{2})\n        (?P<microsecond>\\.[0-9]{1,6})?\n        (?P<tz>\n        Z | (?P<tz_hr>[-+][0-9]{2}) : (?P<tz_min>[0-9]{2})\n        )?\n        $ ', s, re.X)
    if m is not None:
        values = m.groupdict()
        if values['microsecond'] is None:
            values['microsecond'] = 0
        else:
            values['microsecond'] = values['microsecond'][1:]
            values['microsecond'] += '0' * (6 - len(values['microsecond']))
        values = dict(((k, int(v)) for (k, v) in values.items() if not k.startswith('tz')))
        try:
            return datetime(**values)
        except ValueError:
            pass
    return None

