def _build_production_name(self, glyph):
    if self._postscriptNames:
        production_name = self._postscriptNames.get(glyph.name)
        return production_name if production_name else glyph.name
    unicode_val = glyph.unicode
    if glyph.unicode is not None:
        return '%s%04X' % ('u' if unicode_val > 65535 else 'uni', unicode_val)
    parts = glyph.name.rsplit('.', 1)
    if len(parts) == 2 and parts[0] in self.glyphSet:
        return '%s.%s' % (self._build_production_name(self.glyphSet[parts[0]]), parts[1])
    parts = glyph.name.split('.', 1)
    if len(parts) == 2:
        liga_parts = ['%s.%s' % (n, parts[1]) for n in parts[0].split('_')]
    else:
        liga_parts = glyph.name.split('_')
    if len(liga_parts) > 1 and all((n in self.glyphSet for n in liga_parts)):
        unicode_vals = [self.glyphSet[n].unicode for n in liga_parts]
        if all((v and v <= 65535 for v in unicode_vals)):
            return 'uni' + ''.join(('%04X' % v for v in unicode_vals))
        return '_'.join((self._build_production_name(self.glyphSet[n]) for n in liga_parts))
    return glyph.name

def _bits_to_geohash(value):
    ret = []
    for i in (value[i:i + 5] for i in xrange(0, len(value), 5)):
        total = sum([bit * 2 ** count for (count, bit) in enumerate(i[::-1])])
        ret.append(BASE32MAPR[total])
    return ''.join(ret)

def numerical_integration(signal, sampling_frequency):
    integrate = sum(signal[1:]) / sampling_frequency + sum(signal[:-1])
    integrate /= sampling_frequency * 2
    return np.array(integrate)

