                ret['comment'] = 'Virtual machines must be supplied as a list!'
                return ret
            aset_vms = aset.get('virtual_machines', [])
            remote_vms = sorted([vm['id'].split('/')[-1].lower() for vm in aset_vms if 'id' in aset_vms])
            local_vms = sorted([vm.lower() for vm in virtual_machines or []])
            if local_vms != remote_vms:
                ret['changes']['virtual_machines'] = {'old': aset_vms, 'new': virtual_machines}
        if not ret['changes']:
            ret['result'] = True
            ret['comment'] = 'Availability set {0} is already present.'.format(name)
            return ret
        if __opts__['test']:
            ret['result'] = None
            ret['comment'] = 'Availability set {0} would be updated.'.format(name)
            return ret
    else:
        ret['changes'] = {'old': {}, 'new': {'name': name, 'virtual_machines': virtual_machines, 'platform_update_domain_count': platform_update_domain_count, 'platform_fault_domain_count': platform_fault_domain_count, 'sku': sku, 'tags': tags}}
    if __opts__['test']:
        ret['comment'] = 'Availability set {0} would be created.'.format(name)
        ret['result'] = None
        return ret
    aset_kwargs = kwargs.copy()
    aset_kwargs.update(connection_auth)
    aset = __salt__['azurearm_compute.availability_set_create_or_update'](name=name, resource_group=resource_group, virtual_machines=virtual_machines, platform_update_domain_count=platform_update_domain_count, platform_fault_domain_count=platform_fault_domain_count, sku=sku, tags=tags, **aset_kwargs)
    if 'error' not in aset:
        ret['result'] = True
        ret['comment'] = 'Availability set {0} has been created.'.format(name)
        return ret
    ret['comment'] = 'Failed to create availability set {0}! ({1})'.format(name, aset.get('error'))
    return ret

def asRGB(self):
    (width, height, pixels, info) = self.asDirect()
    if info['alpha']:
        raise Error('will not convert image with alpha channel to RGB')
    if not info['greyscale']:
        return (width, height, pixels, info)
    info['greyscale'] = False
    info['planes'] = 3
    if info['bitdepth'] > 8:

        def newarray():
            return array('H', [0])
    else:

        def newarray():
            return bytearray([0])

    def iterrgb():
        for row in pixels:
            a = newarray() * 3 * width
            for i in range(3):
                a[i::3] = row
            yield a
    return (width, height, iterrgb(), info)

