def _deserialize(self, stream):
    readline = stream.readline
    self.tree = Tree(self.repo, hex_to_bin(readline().split()[1]), Tree.tree_id << 12, '')
    self.parents = []
    next_line = None
    while True:
        parent_line = readline()
        if not parent_line.startswith(b'parent'):
            next_line = parent_line
            break
        self.parents.append(type(self)(self.repo, hex_to_bin(parent_line.split()[-1].decode('ascii'))))
    self.parents = tuple(self.parents)
    author_line = next_line
    committer_line = readline()
    next_line = readline()
    while next_line.startswith(b'mergetag '):
        next_line = readline()
        while next_line.startswith(b' '):
            next_line = readline()
    self.encoding = self.default_encoding
    self.gpgsig = None
    enc = next_line
    buf = enc.strip()
    while buf:
        if buf[0:10] == b'encoding ':
            self.encoding = buf[buf.find(' ') + 1:].decode('ascii')
        elif buf[0:7] == b'gpgsig ':
            sig = buf[buf.find(b' ') + 1:] + b'\n'
            is_next_header = False
            while True:
                sigbuf = readline()
                if not sigbuf:
                    break
                if sigbuf[0:1] != b' ':
                    buf = sigbuf.strip()
                    is_next_header = True
                    break
                sig += sigbuf[1:]
            self.gpgsig = sig.rstrip(b'\n').decode('ascii')
            if is_next_header:
                continue
        buf = readline().strip()
    try:
        (self.author, self.authored_date, self.author_tz_offset) = parse_actor_and_date(author_line.decode(self.encoding, 'replace'))
    except UnicodeDecodeError:
        log.error("Failed to decode author line '%s' using encoding %s", author_line, self.encoding, exc_info=True)
    try:
        (self.committer, self.committed_date, self.committer_tz_offset) = parse_actor_and_date(committer_line.decode(self.encoding, 'replace'))
    except UnicodeDecodeError:
        log.error("Failed to decode committer line '%s' using encoding %s", committer_line, self.encoding, exc_info=True)
    self.message = stream.read()
    try:
        self.message = self.message.decode(self.encoding, 'replace')
    except UnicodeDecodeError:
        log.error("Failed to decode message '%s' using encoding %s", self.message, self.encoding, exc_info=True)
    return self

