def _parse_domain_caps(caps):
    result = {'emulator': caps.find('path').text if caps.find('path') is not None else None, 'domain': caps.find('domain').text if caps.find('domain') is not None else None, 'machine': caps.find('machine').text if caps.find('machine') is not None else None, 'arch': caps.find('arch').text if caps.find('arch') is not None else None}
    for child in caps:
        if child.tag == 'vcpu' and child.get('max'):
            result['max_vcpus'] = int(child.get('max'))
        elif child.tag == 'iothreads':
            result['iothreads'] = child.get('supported') == 'yes'
        elif child.tag == 'os':
            result['os'] = {}
            loader_node = child.find('loader')
            if loader_node is not None and loader_node.get('supported') == 'yes':
                loader = _parse_caps_loader(loader_node)
                result['os']['loader'] = loader
        elif child.tag == 'cpu':
            cpu = _parse_caps_cpu(child)
            if cpu:
                result['cpu'] = cpu
        elif child.tag == 'devices':
            devices = _parse_caps_devices_features(child)
            if devices:
                result['devices'] = devices
        elif child.tag == 'features':
            features = _parse_caps_devices_features(child)
            if features:
                result['features'] = features
    return result

def _extract_metric_from_map(self, _m, messages, obj_map, obj_help):
    _obj = metrics_pb2.MetricFamily()
    _obj.name = _m
    _obj.type = self.METRIC_TYPES.index(obj_map[_m])
    if _m in obj_help:
        _obj.help = obj_help[_m]
    _newlbl = _m
    if obj_map[_m] == 'histogram':
        _newlbl = '{}_bucket'.format(_m)
    for _metric in messages[_newlbl]:
        if obj_map[_m] in ['summary', 'histogram'] and len(_obj.metric) > 0:
            _label_exists = False
            _metric_minus = {k: v for (k, v) in list(iteritems(_metric['labels'])) if k not in ['quantile', 'le']}
            _metric_idx = 0
            for mls in _obj.metric:
                _tmp_lbl = {idx.name: idx.value for idx in mls.label}
                if _metric_minus == _tmp_lbl:
                    _label_exists = True
                    break
                _metric_idx = _metric_idx + 1
            if _label_exists:
                _g = _obj.metric[_metric_idx]
            else:
                _g = _obj.metric.add()
        else:
            _g = _obj.metric.add()
        if obj_map[_m] == 'counter':
            _g.counter.value = float(_metric['value'])
        elif obj_map[_m] == 'gauge':
            _g.gauge.value = float(_metric['value'])
        elif obj_map[_m] == 'summary':
            if '{}_count'.format(_m) in messages:
                _g.summary.sample_count = long(self.get_metric_value_by_labels(messages, _metric, _m, 'count'))
            if '{}_sum'.format(_m) in messages:
                _g.summary.sample_sum = self.get_metric_value_by_labels(messages, _metric, _m, 'sum')
        elif obj_map[_m] == 'histogram':
            if '{}_count'.format(_m) in messages:
                _g.histogram.sample_count = long(self.get_metric_value_by_labels(messages, _metric, _m, 'count'))
            if '{}_sum'.format(_m) in messages:
                _g.histogram.sample_sum = self.get_metric_value_by_labels(messages, _metric, _m, 'sum')
        for lbl in _metric['labels']:
            if lbl == 'quantile':
                _q = _g.summary.quantile.add()
                _q.quantile = float(_metric['labels'][lbl])
                _q.value = float(_metric['value'])
            elif obj_map[_m] == 'histogram' and lbl == 'le':
                _q = _g.histogram.bucket.add()
                _q.upper_bound = float(_metric['labels'][lbl])
                _q.cumulative_count = long(float(_metric['value']))
            else:
                is_in_labels = False
                for _existing_lbl in _g.label:
                    if lbl == _existing_lbl.name:
                        is_in_labels = True
                if not is_in_labels:
                    _l = _g.label.add()
                    _l.name = lbl
                    _l.value = _metric['labels'][lbl]
    return _obj

def _parse_chance(self, element):
    try:
        chance = float(element.text)
    except (ValueError, TypeError, AttributeError):
        self._log.warn('Invalid Chance string: {chance}'.format(chance=element.text))
        return
    if not 0 <= chance <= 100:
        self._log.warn('Chance percent must contain an integer or float between 0 and 100')
        return
    self.chance = chance
    self.chance_blocking = bool_attribute(element, 'blocking', self.chance_blocking)

