def calibrate(self, dataset_id, pre_launch_coeffs=False, calib_coeffs=None):
    tic = datetime.now()
    if calib_coeffs is None:
        calib_coeffs = {}
    units = {'reflectance': '%', 'brightness_temperature': 'K', 'counts': '', 'radiance': 'W*m-2*sr-1*cm ?'}
    if dataset_id.name in ('3a', '3b') and self._is3b is None:
        is3b = np.expand_dims(np.bitwise_and(np.right_shift(self._data['scnlinbit'], 0), 1) == 1, 1)
        self._is3b = np.repeat(is3b, self._data['hrpt'][0].shape[0], axis=1)
    try:
        vis_idx = ['1', '2', '3a'].index(dataset_id.name)
        ir_idx = None
    except ValueError:
        vis_idx = None
        ir_idx = ['3b', '4', '5'].index(dataset_id.name)
    if vis_idx is not None:
        coeffs = calib_coeffs.get('ch' + dataset_id.name)
        ds = create_xarray(_vis_calibrate(self._data, vis_idx, dataset_id.calibration, pre_launch_coeffs, coeffs, mask=dataset_id.name == '3a' and self._is3b))
    else:
        ds = create_xarray(_ir_calibrate(self._header, self._data, ir_idx, dataset_id.calibration, mask=dataset_id.name == '3b' and np.logical_not(self._is3b)))
    if dataset_id.name == '3a' and np.all(np.isnan(ds)):
        raise ValueError('Empty dataset for channel 3A')
    if dataset_id.name == '3b' and np.all(np.isnan(ds)):
        raise ValueError('Empty dataset for channel 3B')
    ds.attrs['units'] = units[dataset_id.calibration]
    ds.attrs.update(dataset_id._asdict())
    logger.debug('Calibration time %s', str(datetime.now() - tic))
    return ds

