def _find_im_paths(self, subj_mp, obs_name, target_polarity, max_paths=1, max_path_length=5):
    logger.info('Running path finding with max_paths=%d, max_path_length=%d' % (max_paths, max_path_length))
    if subj_mp is None:
        input_rule_set = None
    else:
        input_rule_set = self._get_input_rules(subj_mp)
        if not input_rule_set:
            return PathResult(False, 'INPUT_RULES_NOT_FOUND', max_paths, max_path_length)
    logger.info('Checking path metrics between %s and %s with polarity %s' % (subj_mp, obs_name, target_polarity))
    if self.do_sampling:
        if not has_pg:
            raise Exception('The paths_graph package could not be imported.')
        return self._sample_paths(input_rule_set, obs_name, target_polarity, max_paths, max_path_length)
    path_lengths = []
    path_metrics = []
    for (source, polarity, path_length) in _find_sources(self.get_im(), obs_name, input_rule_set, target_polarity):
        pm = PathMetric(source, obs_name, polarity, path_length)
        path_metrics.append(pm)
        path_lengths.append(path_length)
    logger.info('Finding paths between %s and %s with polarity %s' % (subj_mp, obs_name, target_polarity))
    paths = []
    if path_metrics and max_paths == 0:
        pr = PathResult(True, 'MAX_PATHS_ZERO', max_paths, max_path_length)
        pr.path_metrics = path_metrics
        return pr
    elif path_metrics:
        if min(path_lengths) <= max_path_length:
            pr = PathResult(True, 'PATHS_FOUND', max_paths, max_path_length)
            pr.path_metrics = path_metrics
            path_iter = enumerate(_find_sources_with_paths(self.get_im(), obs_name, input_rule_set, target_polarity))
            for (path_ix, path) in path_iter:
                flipped = _flip(self.get_im(), path)
                pr.add_path(flipped)
                if len(pr.paths) >= max_paths:
                    break
            return pr
        else:
            pr = PathResult(True, 'MAX_PATH_LENGTH_EXCEEDED', max_paths, max_path_length)
            pr.path_metrics = path_metrics
            return pr
    else:
        return PathResult(False, 'NO_PATHS_FOUND', max_paths, max_path_length)

