def load_training_rasters(response_raster, explanatory_rasters, selected=None):
    with rasterio.open(response_raster) as src:
        response_data = src.read().flatten()
    if selected is None:
        train_y = response_data
    else:
        train_y = response_data[selected]
    selected_data = []
    for rast in explanatory_rasters:
        with rasterio.open(rast) as src:
            explanatory_data = src.read().flatten()
        assert explanatory_data.size == response_data.size
        if selected is None:
            selected_data.append(explanatory_data)
        else:
            selected_data.append(explanatory_data[selected])
    train_xs = np.asarray(selected_data).T
    return (train_xs, train_y)

def _build(self, lexer):
    key = ''
    while key != 'EndOfFile':
        token = next(lexer)
        key = token.__class__.__name__
        if key == 'HeaderBlock':
            self[key].update(token._asdict())
        elif key == 'CtabBlockStart':
            ctab = Ctab()
            ctab._build(lexer)
            self['Ctab'] = ctab
        elif key == 'MolfileStart':
            pass
        elif key in ('MolfileEnd', 'EndOfFile'):
            break
        else:
            raise KeyError('Molfile object does not supposed to have any other information: "{}".'.format(key))
    return self

def cache_key(self, **extra):
    cache_dict = self.to_dict()
    cache_dict.update(extra)
    for k in ['from_dttm', 'to_dttm']:
        del cache_dict[k]
    if self.time_range:
        cache_dict['time_range'] = self.time_range
    json_data = self.json_dumps(cache_dict, sort_keys=True)
    return hashlib.md5(json_data.encode('utf-8')).hexdigest()

def backward(outputs, out_grads=None, retain_graph=False):
    assert isinstance(outputs, (list, tuple)), 'outputs must be a list or tuple of NDArrays'
    if out_grads is None:
        check_call(_LIB.MXAutogradBackward(len(outputs), c_handle_array(outputs), ctypes.c_void_p(0), ctypes.c_int(retain_graph)))
        return
    ograd_handles = []
    for arr in out_grads:
        if arr is not None:
            ograd_handles.append(arr.handle)
        else:
            ograd_handles.append(NDArrayHandle(0))
    assert len(ograd_handles) == len(outputs), 'outputs and out_grads must have the same length'
    check_call(_LIB.MXAutogradBackward(len(outputs), c_handle_array(outputs), c_array(NDArrayHandle, ograd_handles), ctypes.c_int(retain_graph)))

