def _add_element(self, element, parent_node):
    if element.tag == 'unit':
        element_node_id = element.attrib['id'] + ':' + element.attrib['type']
        node_layers = {self.ns, self.ns + ':unit', self.ns + ':' + element.attrib['type']}
    elif element.tag == 'connective':
        element_node_id = element.attrib['id'] + ':connective'
        node_layers = {self.ns, self.ns + ':connective'}
    elif element.tag == 'discourse':
        element_node_id = 'discourse'
        node_layers = {self.ns}
    else:
        element_node_id = element.getparent().attrib['id'] + ':' + element.tag
        node_layers = {self.ns, self.ns + ':modifier'}
    self.add_node(element_node_id, layers=node_layers)
    self.add_edge(parent_node, element_node_id, layers={self.ns}, edge_type=EdgeTypes.dominance_relation)
    if element.text:
        if self.tokenize:
            for token in element.text.split():
                self._add_token(token, element_node_id)
        else:
            element_text = sanitize_string(element.text)
            self.node[element_node_id].update({'label': u'{0}: {1}...'.format(element_node_id, element_text[:20])})
    for child_element in element.iterchildren():
        self._add_element(child_element, element_node_id)
    if element.tail:
        if self.tokenize:
            for token in element.tail.split():
                self._add_token(token, parent_node)
        else:
            tail_text = sanitize_string(element.tail)
            self.node[parent_node].update({'label': u'{0}: {1}...'.format(parent_node, tail_text[:20])})

def join_paired_end_reads_fastqjoin(reads1_infile_path, reads2_infile_path, perc_max_diff=None, min_overlap=None, outfile_label='fastqjoin', params={}, working_dir=tempfile.gettempdir(), SuppressStderr=True, SuppressStdout=True, HALT_EXEC=False):
    abs_r1_path = os.path.abspath(reads1_infile_path)
    abs_r2_path = os.path.abspath(reads2_infile_path)
    infile_paths = [abs_r1_path, abs_r2_path]
    for p in infile_paths:
        if not os.path.exists(p):
            raise IOError('File not found at: %s' % p)
    fastq_join_app = FastqJoin(params=params, WorkingDir=working_dir, SuppressStderr=SuppressStderr, SuppressStdout=SuppressStdout, HALT_EXEC=HALT_EXEC)
    if perc_max_diff is not None:
        if isinstance(perc_max_diff, int) and 0 <= perc_max_diff <= 100:
            fastq_join_app.Parameters['-p'].on(perc_max_diff)
        else:
            raise ValueError('perc_max_diff must be int between 0-100!')
    if min_overlap is not None:
        if isinstance(min_overlap, int) and 0 < min_overlap:
            fastq_join_app.Parameters['-m'].on(min_overlap)
        else:
            raise ValueError('min_overlap must be an int >= 0!')
    if outfile_label is not None:
        if isinstance(outfile_label, str):
            fastq_join_app.Parameters['-o'].on(outfile_label + '.')
        else:
            raise ValueError('outfile_label must be a string!')
    else:
        pass
    result = fastq_join_app(infile_paths)
    path_dict = {}
    path_dict['Assembled'] = result['Assembled'].name
    path_dict['UnassembledReads1'] = result['UnassembledReads1'].name
    path_dict['UnassembledReads2'] = result['UnassembledReads2'].name
    for path in path_dict.values():
        if not os.path.exists(path):
            raise IOError('Output file not found at: %s' % path)
    for (key, file_path) in path_dict.items():
        new_file_path = file_path + '.fastq'
        shutil.move(file_path, new_file_path)
        path_dict[key] = new_file_path
    return path_dict

