def render_q(q, qn, connection):
    joinstr = u' {} '.format(q.connector)
    conditions = []
    params = []
    if DJANGO_MAJOR == 1 and DJANGO_MINOR == 7:
        try:
            qn = qn.__self__
        except AttributeError:
            pass
    for child in q.children:
        if isinstance(child, Q):
            (condition, child_params) = render_q(child, qn, connection)
            conditions.append(u'({})'.format(condition))
            params.extend(child_params)
        else:
            try:
                (child, joins_used) = child
            except TypeError:
                pass
            (condition, child_params) = child.as_sql(qn, connection)
            params.extend(child_params)
            conditions.append(condition)
    rendered = u'({})'.format(joinstr.join(conditions))
    if q.negated:
        rendered = u'NOT {}'.format(rendered)
    return (rendered, params)

def smooth(x, y, degree=3):
    if degree == 1:
        return (x, y)
    elif not isodd(degree):
        raise ValueError('Degree must be an odd number')
    else:
        window_width = int(degree / 2)
        data_size = len(y) - degree + 1
        smoothed_y = np.zeros(data_size)
        for idx in range(degree):
            smoothed_y += y[idx:idx + data_size]
        smoothed_y /= degree
        smoothed_x = x[window_width:-window_width]
        return (smoothed_x, smoothed_y)

