        os.chdir(self.startdir)
        self.sldir = self.inputdir
    for i in range(len(lines)):
        lines[i] = lines[i].strip()
    for i in range(len(lines)):
        if lines[i].startswith('#'):
            lines[i] = lines[i].strip('#')
            tmp = lines[i].split()
            tmp1 = []
            for j in range(len(tmp)):
                if tmp[j] != '=' or '':
                    tmp1.append(tmp[j])
            tmp = tmp1
            for j in range(len(tmp)):
                if tmp[j] == attri:
                    try:
                        if '.' in tmp[j + 1]:
