def _get_adjustments_in_range(self, asset, dts, field):
    sid = int(asset)
    start = normalize_date(dts[0])
    end = normalize_date(dts[-1])
    adjs = {}
    if field != 'volume':
        mergers = self._adjustments_reader.get_adjustments_for_sid('mergers', sid)
        for m in mergers:
            dt = m[0]
            if start < dt <= end:
                end_loc = dts.searchsorted(dt)
                adj_loc = end_loc
                mult = Float64Multiply(0, end_loc - 1, 0, 0, m[1])
                try:
                    adjs[adj_loc].append(mult)
                except KeyError:
                    adjs[adj_loc] = [mult]
        divs = self._adjustments_reader.get_adjustments_for_sid('dividends', sid)
        for d in divs:
            dt = d[0]
            if start < dt <= end:
                end_loc = dts.searchsorted(dt)
                adj_loc = end_loc
                mult = Float64Multiply(0, end_loc - 1, 0, 0, d[1])
                try:
                    adjs[adj_loc].append(mult)
                except KeyError:
                    adjs[adj_loc] = [mult]
    splits = self._adjustments_reader.get_adjustments_for_sid('splits', sid)
    for s in splits:
        dt = s[0]
        if start < dt <= end:
            if field == 'volume':
                ratio = 1.0 / s[1]
            else:
                ratio = s[1]
            end_loc = dts.searchsorted(dt)
            adj_loc = end_loc
            mult = Float64Multiply(0, end_loc - 1, 0, 0, ratio)
            try:
                adjs[adj_loc].append(mult)
            except KeyError:
                adjs[adj_loc] = [mult]
    return adjs

def update_poly_wlcalib(coeff_ini, coeff_residuals, naxis1_ini, debugplot):
    coeff = []
    for fdum in coeff_ini:
        coeff.append(fdum)
    poly_ini = np.polynomial.Polynomial(coeff)
    poldeg_wlcalib = len(coeff) - 1
    if len(coeff_residuals) == 0:
        return poly_ini.coef
    elif np.count_nonzero(poly_ini.coef) == 0:
        return poly_ini.coef
    coeff = []
    for fdum in coeff_residuals:
        coeff.append(fdum)
    poly_residuals = np.polynomial.Polynomial(coeff)
    xfit = np.zeros(naxis1_ini)
    yfit = np.zeros(naxis1_ini)
    for i in range(naxis1_ini):
        xfit[i] = float(i + 1)
        wv_tmp = poly_ini(xfit[i])
        yfit[i] = wv_tmp + poly_residuals(wv_tmp)
    if len(xfit) > poldeg_wlcalib:
        poldeg_effective = poldeg_wlcalib
    else:
        poldeg_effective = len(xfit) - 1
    (poly_updated, ydum) = polfit_residuals(x=xfit, y=yfit, deg=poldeg_effective, debugplot=debugplot)
    return poly_updated.coef

