def _fit_s(D, a0, logp, tol=1e-07, maxiter=1000):
    (N, K) = D.shape
    s1 = a0.sum()
    m = a0 / s1
    mlogp = (m * logp).sum()
    for i in xrange(maxiter):
        s0 = s1
        g = psi(s1) - (m * psi(s1 * m)).sum() + mlogp
        h = _trigamma(s1) - (m ** 2 * _trigamma(s1 * m)).sum()
        if g + s1 * h < 0:
            s1 = 1 / (1 / s0 + g / h / s0 ** 2)
        if s1 <= 0:
            s1 = s0 * exp(-g / (s0 * h + g))
        if s1 <= 0:
            s1 = 1 / (1 / s0 + g / (s0 ** 2 * h + 2 * s0 * g))
        if s1 <= 0:
            s1 = s0 - g / h
        if s1 <= 0:
            raise Exception('Unable to update s from {}'.format(s0))
        a = s1 * m
        if abs(s1 - s0) < tol:
            return a
    raise Exception('Failed to converge after {} iterations, s is {}'.format(maxiter, s1))

