def mock_stream(hamiltonian, prog_orbit, prog_mass, k_mean, k_disp, release_every=1, Integrator=DOPRI853Integrator, Integrator_kwargs=dict(), snapshot_filename=None, output_every=1, seed=None):
    if isinstance(hamiltonian, CPotentialBase):
        warnings.warn('This function now expects a `Hamiltonian` instance instead of a `PotentialBase` subclass instance. If you are using a static reference frame, you just need to pass your potential object in to the Hamiltonian constructor to use, e.g., Hamiltonian(potential).', DeprecationWarning)
        hamiltonian = Hamiltonian(hamiltonian)
    if Integrator not in [LeapfrogIntegrator, DOPRI853Integrator]:
        raise ValueError('Only Leapfrog and dop853 integration is supported for generating mock streams.')
    if not isinstance(hamiltonian, Hamiltonian) or not hamiltonian.c_enabled:
        raise TypeError('Input potential must be a CPotentialBase subclass.')
    if not isinstance(prog_orbit, Orbit):
        raise TypeError('Progenitor orbit must be an Orbit subclass.')
    if snapshot_filename is not None and Integrator != DOPRI853Integrator:
        raise ValueError('If saving snapshots, must use the DOP853Integrator.')
    k_mean = np.atleast_1d(k_mean)
    k_disp = np.atleast_1d(k_disp)
    if k_mean.ndim > 1:
        assert k_mean.shape[0] == prog_orbit.t.size
        assert k_disp.shape[0] == prog_orbit.t.size
    if prog_orbit.t[1] < prog_orbit.t[0]:
        raise ValueError('Progenitor orbit goes backwards in time. Streams can only be generated on orbits that run forwards. Hint: you can reverse the orbit with prog_orbit[::-1], but make sure the array of k_mean values is ordered correctly.')
    c_w = np.squeeze(prog_orbit.w(hamiltonian.units)).T
    prog_w = np.ascontiguousarray(c_w)
    prog_t = np.ascontiguousarray(prog_orbit.t.decompose(hamiltonian.units).value)
    if not hasattr(prog_mass, 'unit'):
        prog_mass = prog_mass * hamiltonian.units['mass']
    if not prog_mass.isscalar:
        if len(prog_mass) != prog_orbit.ntimes:
            raise ValueError('If passing in an array of progenitor masses, it must have the same length as the number of timesteps in the input orbit.')
    prog_mass = prog_mass.decompose(hamiltonian.units).value
    if Integrator == LeapfrogIntegrator:
        stream_w = _mock_stream_leapfrog(hamiltonian, t=prog_t, prog_w=prog_w, release_every=release_every, _k_mean=k_mean, _k_disp=k_disp, G=hamiltonian.potential.G, _prog_mass=prog_mass, seed=seed, **Integrator_kwargs)
    elif Integrator == DOPRI853Integrator:
        if snapshot_filename is not None:
            if os.path.exists(snapshot_filename):
                raise IOError("Mockstream save file '{}' already exists.")
            import h5py
            _mock_stream_animate(snapshot_filename, hamiltonian, t=prog_t, prog_w=prog_w, release_every=release_every, output_every=output_every, _k_mean=k_mean, _k_disp=k_disp, G=hamiltonian.potential.G, _prog_mass=prog_mass, seed=seed, **Integrator_kwargs)
            with h5py.File(str(snapshot_filename), 'a') as h5f:
                h5f['pos'].attrs['unit'] = str(hamiltonian.units['length'])
                h5f['vel'].attrs['unit'] = str(hamiltonian.units['length'] / hamiltonian.units['time'])
                h5f['t'].attrs['unit'] = str(hamiltonian.units['time'])
            return None
        else:
            stream_w = _mock_stream_dop853(hamiltonian, t=prog_t, prog_w=prog_w, release_every=release_every, _k_mean=k_mean, _k_disp=k_disp, G=hamiltonian.potential.G, _prog_mass=prog_mass, seed=seed, **Integrator_kwargs)
    else:
        raise RuntimeError('Should never get here...')
    return PhaseSpacePosition.from_w(w=stream_w.T, units=hamiltonian.units)

def copy(self: 'Model', *, include: 'SetStr'=None, exclude: 'SetStr'=None, update: 'DictStrAny'=None, deep: bool=False) -> 'Model':
    if include is None and exclude is None and (update is None):
        v = self.__values__
    else:
        return_keys = self._calculate_keys(include=include, exclude=exclude, skip_defaults=False)
        if return_keys:
            v = {**{k: v for (k, v) in self.__values__.items() if k in return_keys}, **(update or {})}
        else:
            v = {**self.__values__, **(update or {})}
    if deep:
        v = deepcopy(v)
    m = self.__class__.construct(v, self.__fields_set__.copy())
    return m

