def url_for_s3(endpoint, bucket_name, bucket_domain=None, scheme='', url_style='host', cdn_domain=None, filename=None):
    if not bucket_name:
        raise ValueError('Bucket name is required when calling url_for_s3().')
    if url_style == 'host':
        url_format = '%(bucket_name)s.%(bucket_domain)s'
    elif url_style == 'path':
        url_format = '%(bucket_domain)s/%(bucket_name)s'
    else:
        raise ValueError('Invalid S3 URL style: "%s"' % url_style)
    if bucket_domain == None:
        bucket_domain = u's3.amazonaws.com'
    bucket_path = url_format % {'bucket_name': bucket_name, 'bucket_domain': bucket_domain}
    if cdn_domain:
        bucket_path = '%s' % cdn_domain
    return str('%s//%s/%s%s' % (scheme + (':' if scheme else ''), bucket_path, endpoint + ('/' if endpoint else ''), filename.lstrip('/')))

def action(args):
    log.info('loading reference package')
    pairs = [p.split('=', 1) for p in args.changes]
    if args.metadata:
        rp = refpkg.Refpkg(args.refpkg, create=False)
        rp.start_transaction()
        for (key, value) in pairs:
            rp.update_metadata(key, value)
        rp.commit_transaction('Updated metadata: ' + ', '.join(['%s=%s' % (a, b) for (a, b) in pairs]))
    else:
        for (key, filename) in pairs:
            if not os.path.exists(filename):
                print('No such file: %s' % filename)
                exit(1)
        rp = refpkg.Refpkg(args.refpkg, create=False)
        rp.start_transaction()
        for (key, filename) in pairs:
            if key == 'tree_stats':
                with warnings.catch_warnings():
                    warnings.simplefilter('ignore', refpkg.DerivedFileNotUpdatedWarning)
                    rp.update_file(key, os.path.abspath(filename))
                log.info('Updating phylo_model to match tree_stats')
                rp.update_phylo_model(args.stats_type, filename, args.frequency_type)
            else:
                rp.update_file(key, os.path.abspath(filename))
        rp.commit_transaction('Updates files: ' + ', '.join(['%s=%s' % (a, b) for (a, b) in pairs]))
    return 0

