def _unpad(self, a, axis, out):
    assert a.shape[axis] == self.N
    Npad = self.N - self.Nin
    if out:
        (_Npad, Npad_) = (Npad - Npad // 2, Npad // 2)
    else:
        (_Npad, Npad_) = (Npad // 2, Npad - Npad // 2)
    return np.take(a, range(_Npad, self.N - Npad_), axis=axis)

def format_close(code: int, reason: str) -> str:
    if 3000 <= code < 4000:
        explanation = 'registered'
    elif 4000 <= code < 5000:
        explanation = 'private use'
    else:
        explanation = CLOSE_CODES.get(code, 'unknown')
    result = f'code = {code} ({explanation}), '
    if reason:
        result += f'reason = {reason}'
    else:
        result += 'no reason'
    return result

def url_reverse(request):
    if request.method in ('GET', 'POST'):
        data = getattr(request, request.method)
        url_name = data.get('url_name')
        try:
            path = urls.reverse(url_name, args=data.getlist('args'))
            (view_func, args, kwargs) = urls.resolve(path)
            return http.HttpResponse(path, content_type='text/plain')
        except urls.NoReverseMatch:
            return http.HttpResponse('Error', content_type='text/plain')
    return http.HttpResponseNotAllowed(('GET', 'POST'))

def mjd_obsc(self):
    try:
        utc_end = self['UTCEND']
        exposure_time = float(self['EXPTIME'])
        date_obs = self['DATE-OBS']
    except KeyError as ke:
        raise KeyError('Header missing keyword: {}, required for MJD-OBSC computation'.format(ke.args[0]))
    utc_end = Time(date_obs + 'T' + utc_end)
    utc_cen = utc_end - TimeDelta(0.73, format='sec') - TimeDelta(exposure_time / 2.0, format='sec')
    return round(utc_cen.mjd, 7)

