def _atexit_callback(cls):
    updated_scripts = {}
    for baseline in cls._baselines_to_update:
        if baseline.z__path.endswith('<stdin>'):
            continue
        try:
            script = updated_scripts[baseline.z__path]
        except KeyError:
            script = Script(baseline.z__path)
            updated_scripts[baseline.z__path] = script
        script.add_update(baseline.z__linenum, baseline.z__update)
    for key in sorted(updated_scripts):
        script = updated_scripts[key]
        script.update()
    return updated_scripts

def eval(self, expr, lineno=0, show_errors=True):
    self.lineno = lineno
    self.error = []
    self.start_time = time.time()
    try:
        node = self.parse(expr)
    except:
        errmsg = exc_info()[1]
        if len(self.error) > 0:
            errmsg = '\n'.join(self.error[0].get_error())
        if not show_errors:
            try:
                exc = self.error[0].exc
            except:
                exc = RuntimeError
            raise exc(errmsg)
        print(errmsg, file=self.err_writer)
        return
    try:
        return self.run(node, expr=expr, lineno=lineno)
    except:
        errmsg = exc_info()[1]
        if len(self.error) > 0:
            errmsg = '\n'.join(self.error[0].get_error())
        if not show_errors:
            try:
                exc = self.error[0].exc
            except:
                exc = RuntimeError
            raise exc(errmsg)
        print(errmsg, file=self.err_writer)
        return

