def _get_kafka_consumer_offsets(self, instance, consumer_groups):
    consumer_offsets = {}
    topics = defaultdict(set)
    cli = self._get_kafka_client(instance)
    for (consumer_group, topic_partitions) in iteritems(consumer_groups):
        try:
            coordinator_id = self._get_group_coordinator(cli, consumer_group)
            if coordinator_id:
                offsets = self._get_consumer_offsets(cli, consumer_group, topic_partitions, coordinator_id)
            else:
                offsets = self._get_consumer_offsets(cli, consumer_group, topic_partitions)
                self.log.info('unable to find group coordinator for %s', consumer_group)
            for ((topic, partition), offset) in iteritems(offsets):
                topics[topic].update([partition])
                key = (consumer_group, topic, partition)
                consumer_offsets[key] = offset
        except Exception:
            self.log.exception('Could not read consumer offsets from kafka.')
    return (consumer_offsets, topics)

def munge_source(v):
    lines = v.split('\n')
    if not lines:
        return (tuple(), '')
    firstline = lines[0].lstrip()
    while firstline == '' or firstline[0] == '@':
        del lines[0]
        firstline = lines[0].lstrip()
    if not lines:
        return (tuple(), '')
    params = tuple((parm.strip() for parm in sig_ex.match(lines[0]).group(1).split(',')))
    del lines[0]
    if not lines:
        return (params, '')
    if lines and lines[-1].strip() == 'pass':
        del lines[-1]
    return (params, dedent('\n'.join(lines)))

def wrap(query, container, namespace):
    if is_op(query, QueryOp) or query == None:
        return query
    query = wrap(query)
    table = container.get_table(query['from'])
    schema = table.schema
    output = QueryOp(frum=table, format=query.format, limit=mo_math.min(MAX_LIMIT, coalesce(query.limit, DEFAULT_LIMIT)))
    if query.select or isinstance(query.select, (Mapping, list)):
        output.select = _normalize_selects(query.select, query.frum, schema=schema)
    elif query.edges or query.groupby:
        output.select = DEFAULT_SELECT
    else:
        output.select = _normalize_selects('.', query.frum)
    if query.groupby and query.edges:
        Log.error('You can not use both the `groupby` and `edges` clauses in the same query!')
    elif query.edges:
        output.edges = _normalize_edges(query.edges, limit=output.limit, schema=schema)
        output.groupby = Null
    elif query.groupby:
        output.edges = Null
        output.groupby = _normalize_groupby(query.groupby, limit=output.limit, schema=schema)
    else:
        output.edges = Null
        output.groupby = Null
    output.where = _normalize_where(query.where, schema=schema)
    output.window = [_normalize_window(w) for w in listwrap(query.window)]
    output.having = None
    output.sort = _normalize_sort(query.sort)
    if not mo_math.is_integer(output.limit) or output.limit < 0:
        Log.error('Expecting limit >= 0')
    output.isLean = query.isLean
    return output

