def complete(self, sp_args, line, rl_prefix, rl_begidx, rl_endidx):
    if len(sp_args) == 0 or not line.endswith(sp_args[-1]):
        return self.accepted_flags
    else:
        matches = []
        for arg in self.accepted_flags:
            if arg.startswith(sp_args[-1]):
                matches.append(arg)
        if len(matches) == 1:
            sub = len(sp_args[-1]) - len(rl_prefix)
            return [matches[0][sub:]]
        else:
            return matches

def wait_for_redis_to_start(redis_ip_address, redis_port, password=None, num_retries=5):
    redis_client = redis.StrictRedis(host=redis_ip_address, port=redis_port, password=password)
    counter = 0
    while counter < num_retries:
        try:
            logger.info('Waiting for redis server at {}:{} to respond...'.format(redis_ip_address, redis_port))
            redis_client.client_list()
        except redis.ConnectionError:
            time.sleep(1)
            logger.info('Failed to connect to the redis server, retrying.')
            counter += 1
        else:
            break
    if counter == num_retries:
        raise Exception('Unable to connect to Redis. If the Redis instance is on a different machine, check that your firewall is configured properly.')

