def get_content(cls, abspath: str, start: int=None, end: int=None) -> Generator[bytes, None, None]:
    with open(abspath, 'rb') as file:
        if start is not None:
            file.seek(start)
        if end is not None:
            remaining = end - (start or 0)
        else:
            remaining = None
        while True:
            chunk_size = 64 * 1024
            if remaining is not None and remaining < chunk_size:
                chunk_size = remaining
            chunk = file.read(chunk_size)
            if chunk:
                if remaining is not None:
                    remaining -= len(chunk)
                yield chunk
            else:
                if remaining is not None:
                    assert remaining == 0
                return

def process_directive(self, directive):
    (action, patterns, thedir, dirpattern) = self._parse_directive(directive)
    if action == 'include':
        for pattern in patterns:
            if not self._include_pattern(pattern, anchor=True):
                logger.warning('no files found matching %r', pattern)
    elif action == 'exclude':
        for pattern in patterns:
            found = self._exclude_pattern(pattern, anchor=True)
    elif action == 'global-include':
        for pattern in patterns:
            if not self._include_pattern(pattern, anchor=False):
                logger.warning('no files found matching %r anywhere in distribution', pattern)
    elif action == 'global-exclude':
        for pattern in patterns:
            found = self._exclude_pattern(pattern, anchor=False)
    elif action == 'recursive-include':
        for pattern in patterns:
            if not self._include_pattern(pattern, prefix=thedir):
                logger.warning('no files found matching %r under directory %r', pattern, thedir)
    elif action == 'recursive-exclude':
        for pattern in patterns:
            found = self._exclude_pattern(pattern, prefix=thedir)
    elif action == 'graft':
        if not self._include_pattern(None, prefix=dirpattern):
            logger.warning('no directories found matching %r', dirpattern)
    elif action == 'prune':
        if not self._exclude_pattern(None, prefix=dirpattern):
            logger.warning('no previously-included directories found matching %r', dirpattern)
    else:
        raise DistlibException('invalid action %r' % action)

def get_min_risk(self, weights, cov_matrix):

    def func(weights):
        return np.matmul(np.matmul(weights.transpose(), cov_matrix), weights)

    def func_deriv(weights):
        return np.matmul(weights.transpose(), cov_matrix.transpose()) + np.matmul(weights.transpose(), cov_matrix)
    constraints = {'type': 'eq', 'fun': lambda weights: weights.sum() - 1}
    solution = self.solve_minimize(func, weights, constraints, func_deriv=func_deriv)
    allocation = solution.x
    return allocation

def gt_aware_merge(self, other, reference_seq):
    if self.CHROM != other.CHROM or self.intersects(other) or len(self.ALT) != 1 or (len(other.ALT) != 1):
        return None
    ref_start = min(self.POS, other.POS)
    ref_end = max(self.ref_end_pos(), other.ref_end_pos())
    ref_seq_for_vcf = reference_seq[ref_start:ref_end + 1]
    sorted_records = sorted([self, other], key=operator.attrgetter('POS'))
    alt_seq = []
    all_alt_seq = []
    gt_confs = []
    current_ref_pos = ref_start
    for record in sorted_records:
        assert record.REF != '.' and record.ALT[0] != '.'
        alt_seq.append(reference_seq[current_ref_pos:record.POS])
        all_alt_seq.append(reference_seq[current_ref_pos:record.POS])
        if record.FORMAT is None or 'GT' not in record.FORMAT:
            return None
        called_alleles = list(set(record.FORMAT['GT'].split('/')))
        if len(called_alleles) != 1 or '.' in called_alleles:
            return None
        gt = int(called_alleles[0])
        if gt > 0:
            alt_seq.append(record.ALT[gt - 1])
        else:
            alt_seq.append(record.REF)
        all_alt_seq.append(record.ALT[0])
        current_ref_pos += len(record.REF)
        if record.FORMAT is not None and 'GT_CONF' in record.FORMAT:
            gt_confs.append(record.FORMAT['GT_CONF'])
    alt_seq_for_vcf = ''.join(alt_seq)
    format = 'GT'
    gt_0 = '0/0'
    gt_1 = '1/1'
    if len(gt_confs) > 0:
        gt_conf = min(gt_confs)
        format = 'GT:GT_CONF'
        gt_0 = '0/0:' + str(gt_conf)
        gt_1 = '1/1:' + str(gt_conf)
    if ref_seq_for_vcf == alt_seq_for_vcf:
        return VcfRecord('\t'.join([self.CHROM, str(ref_start + 1), '.', ref_seq_for_vcf, ''.join(all_alt_seq), '.', '.', 'SVTYPE=MERGED', format, gt_0]))
    else:
        return VcfRecord('\t'.join([self.CHROM, str(ref_start + 1), '.', ref_seq_for_vcf, alt_seq_for_vcf, '.', '.', 'SVTYPE=MERGED', format, gt_1]))

def encode(self, value):
    if isinstance(value, Token):
        return value.encoded_value
    elif isinstance(value, bytes):
        return value
    elif isinstance(value, bool):
        raise DataError("Invalid input of type: 'bool'. Convert to a byte, string or number first.")
    elif isinstance(value, float):
        value = repr(value).encode()
    elif isinstance(value, (int, long)):
        value = str(value).encode()
    elif not isinstance(value, basestring):
        typename = type(value).__name__
        raise DataError("Invalid input of type: '%s'. Convert to a byte, string or number first." % typename)
    if isinstance(value, unicode):
        value = value.encode(self.encoding, self.encoding_errors)
    return value

def build_conda_packages(self):
    bldir = './tmp-bld'
    if not os.path.exists(bldir):
        os.makedirs(bldir)
    for pybuild in ['2.7', '3']:
        build = api.build('conda-recipe/{}'.format(self.package), python=pybuild)
        if not self.deploy:
            cmd = ['anaconda', 'upload', build[0], '--label', 'test', '--force']
        else:
            cmd = ['anaconda', 'upload', build[0]]
        err = subprocess.Popen(cmd).communicate()
        api.convert(build[0], output_dir=bldir, platforms=['osx-64'])
        osxdir = os.path.join(bldir, 'osx-64', os.path.basename(build[0]))
        if not self.deploy:
            cmd = ['anaconda', 'upload', osxdir, '--label', 'test', '--force']
        else:
            cmd = ['anaconda', 'upload', osxdir]
        err = subprocess.Popen(cmd).communicate()
    shutil.rmtree(bldir)

def _no_proxy(method):

    @wraps(method)
    def wrapper(self, *args, **kwargs):
        notproxied = _oga(self, '__notproxied__')
        _osa(self, '__notproxied__', True)
        try:
            return method(self, *args, **kwargs)
        finally:
            _osa(self, '__notproxied__', notproxied)
    return wrapper

def _prefix_from_ip_string(self, ip_str):
    try:
        ip_int = self._ip_int_from_string(ip_str)
    except AddressValueError:
        raise NetmaskValueError('%s is not a valid netmask' % ip_str)
    try:
        return self._prefix_from_ip_int(ip_int)
    except NetmaskValueError:
        pass
    ip_int ^= self._ALL_ONES
    try:
        return self._prefix_from_ip_int(ip_int)
    except NetmaskValueError:
        raise NetmaskValueError('%s is not a valid netmask' % ip_str)

