def _download(self, resource):
    if isinstance(resource, six.string_types):
        resource = resource_lib.Resource(url=resource)
    url = resource.url
    if url in self._sizes_checksums:
        expected_sha256 = self._sizes_checksums[url][1]
        download_path = self._get_final_dl_path(url, expected_sha256)
        if not self._force_download and resource.exists_locally(download_path):
            logging.info('URL %s already downloaded: reusing %s.', url, download_path)
            self._recorded_sizes_checksums[url] = self._sizes_checksums[url]
            return promise.Promise.resolve(download_path)
    download_dir_path = os.path.join(self._download_dir, '%s.tmp.%s' % (resource_lib.get_dl_dirname(url), uuid.uuid4().hex))
    tf.io.gfile.makedirs(download_dir_path)
    logging.info('Downloading %s into %s...', url, download_dir_path)

    def callback(val):
        (checksum, dl_size) = val
        return self._handle_download_result(resource, download_dir_path, checksum, dl_size)
    return self._downloader.download(url, download_dir_path).then(callback)

def AssignTasksToClient(self, client_id):
    rules = data_store.REL_DB.ReadAllForemanRules()
    if not rules:
        return 0
    last_foreman_run = self._GetLastForemanRunTime(client_id)
    latest_rule_creation_time = max((rule.creation_time for rule in rules))
    if latest_rule_creation_time <= last_foreman_run:
        return 0
    self._SetLastForemanRunTime(client_id, latest_rule_creation_time)
    relevant_rules = []
    expired_rules = False
    now = rdfvalue.RDFDatetime.Now()
    for rule in rules:
        if rule.expiration_time < now:
            expired_rules = True
            continue
        if rule.creation_time <= last_foreman_run:
            continue
        relevant_rules.append(rule)
    actions_count = 0
    if relevant_rules:
        client_data = data_store.REL_DB.ReadClientFullInfo(client_id)
        if client_data is None:
            return
        for rule in relevant_rules:
            if rule.Evaluate(client_data):
                actions_count += self._RunAction(rule, client_id)
    if expired_rules:
        data_store.REL_DB.RemoveExpiredForemanRules()
    return actions_count

