def bytes(self, count):
    if count < 0:
        raise ValueError
    if self._bits == 0:
        data = self._fileobj.read(count)
        if len(data) != count:
            raise BitReaderError('not enough data')
        return data
    return bytes(bytearray((self.bits(8) for _ in xrange(count))))

def write_raw(self, message_id, data, bus=None, frame_format=None):
    if not isinstance(message_id, numbers.Number):
        try:
            message_id = int(message_id, 0)
        except ValueError:
            raise ValueError('ID must be numerical')
    data = {'id': message_id, 'data': data}
    if bus is not None:
        data['bus'] = bus
    if frame_format is not None:
        data['frame_format'] = frame_format
    message = self.streamer.serialize_for_stream(data)
    bytes_written = self.write_bytes(message)
    assert bytes_written == len(message)
    return bytes_written

