    del parent._values[path.segments[-1]]

def present(name, tag=None, build=None, load=None, force=False, insecure_registry=False, client_timeout=salt.utils.docker.CLIENT_TIMEOUT, dockerfile=None, sls=None, base='opensuse/python', saltenv='base', pillarenv=None, pillar=None, **kwargs):
    ret = {'name': name, 'changes': {}, 'result': False, 'comment': ''}
    if not isinstance(name, six.string_types):
        name = six.text_type(name)
    num_build_args = len([x for x in (build, load, sls) if x is not None])
    if num_build_args > 1:
        ret['comment'] = "Only one of 'build', 'load', or 'sls' is permitted."
        return ret
    elif num_build_args == 1:
        if not tag:
            ret['comment'] = "The 'tag' argument is required if any one of 'build', 'load', or 'sls' is used."
            return ret
        if not isinstance(tag, six.string_types):
            tag = six.text_type(tag)
        full_image = ':'.join((name, tag))
    else:
        if tag:
            name = '{0}:{1}'.format(name, tag)
        full_image = name
    try:
        image_info = __salt__['docker.inspect_image'](full_image)
    except CommandExecutionError as exc:
        msg = exc.__str__()
        if '404' in msg:
            image_info = None
        else:
            ret['comment'] = msg
            return ret
    if image_info is not None:
        if not force:
            ret['result'] = True
            ret['comment'] = 'Image {0} already present'.format(full_image)
            return ret
    if build or sls:
        action = 'built'
    elif load:
        action = 'loaded'
    else:
        action = 'pulled'
    if __opts__['test']:
        ret['result'] = None
        if image_info is not None and force or image_info is None:
            ret['comment'] = 'Image {0} will be {1}'.format(full_image, action)
            return ret
    if build:
        argspec = salt.utils.args.get_function_argspec(__salt__['docker.build'])
        build_args = dict(list(zip(argspec.args, argspec.defaults)))
        for k in build_args:
            if k in kwargs.get('kwargs', {}):
                build_args[k] = kwargs.get('kwargs', {}).get(k)
        try:
            build_args['path'] = build
            build_args['repository'] = name
            build_args['tag'] = tag
            build_args['dockerfile'] = dockerfile
            image_update = __salt__['docker.build'](**build_args)
        except Exception as exc:
            ret['comment'] = 'Encountered error building {0} as {1}: {2}'.format(build, full_image, exc)
            return ret
        if image_info is None or image_update['Id'] != image_info['Id'][:12]:
            ret['changes'] = image_update
    elif sls:
        _locals = locals()
        sls_build_kwargs = {k: _locals[k] for k in ('saltenv', 'pillarenv', 'pillar') if _locals[k] is not None}
        try:
            image_update = __salt__['docker.sls_build'](repository=name, tag=tag, base=base, mods=sls, **sls_build_kwargs)
        except Exception as exc:
            ret['comment'] = 'Encountered error using SLS {0} for building {1}: {2}'.format(sls, full_image, exc)
            return ret
        if image_info is None or image_update['Id'] != image_info['Id'][:12]:
            ret['changes'] = image_update
    elif load:
        try:
            image_update = __salt__['docker.load'](path=load, repository=name, tag=tag)
        except Exception as exc:
            ret['comment'] = 'Encountered error loading {0} as {1}: {2}'.format(load, full_image, exc)
            return ret
        if image_info is None or image_update.get('Layers', []):
            ret['changes'] = image_update
    else:
        try:
            image_update = __salt__['docker.pull'](name, insecure_registry=insecure_registry, client_timeout=client_timeout)
        except Exception as exc:
            ret['comment'] = 'Encountered error pulling {0}: {1}'.format(full_image, exc)
            return ret
        if image_info is not None and image_info['Id'][:12] == image_update.get('Layers', {}).get('Already_Pulled', [None])[0]:
            pass
        elif image_info is None or image_update.get('Layers', {}).get('Pulled'):
            ret['changes'] = image_update
    error = False
    try:
        __salt__['docker.inspect_image'](full_image)
    except CommandExecutionError as exc:
        msg = exc.__str__()
        if '404' not in msg:
            error = "Failed to inspect image '{0}' after it was {1}: {2}".format(full_image, action, msg)
    if error:
        ret['comment'] = error
    else:
        ret['result'] = True
        if not ret['changes']:
