def flipGenotype(genotype):
    newGenotype = set()
    for allele in genotype:
        if allele == 'A':
            newGenotype.add('T')
        elif allele == 'C':
            newGenotype.add('G')
        elif allele == 'T':
            newGenotype.add('A')
        elif allele == 'G':
            newGenotype.add('C')
        else:
            msg = '%(allele)s: unknown allele' % locals()
            raise ProgramError(msg)
    return newGenotype

