def _ActivateBreakpoint(self, module):
    self._RemoveImportHook()
    line = self.definition['location']['line']
    (status, codeobj) = module_explorer.GetCodeObjectAtLine(module, line)
    if not status:
        params = [str(line), os.path.splitext(module.__file__)[0] + '.py']
        alt_lines = (str(l) for l in codeobj if l is not None)
        params += alt_lines
        if len(params) == 4:
            fmt = ERROR_LOCATION_NO_CODE_FOUND_AT_LINE_4
        elif len(params) == 3:
            fmt = ERROR_LOCATION_NO_CODE_FOUND_AT_LINE_3
        else:
            fmt = ERROR_LOCATION_NO_CODE_FOUND_AT_LINE_2
        self._CompleteBreakpoint({'status': {'isError': True, 'refersTo': 'BREAKPOINT_SOURCE_LOCATION', 'description': {'format': fmt, 'parameters': params}}})
        return
    condition = None
    if self.definition.get('condition'):
        try:
            condition = compile(self.definition.get('condition'), '<condition_expression>', 'eval')
        except (TypeError, ValueError) as e:
            self._CompleteBreakpoint({'status': {'isError': True, 'refersTo': 'BREAKPOINT_CONDITION', 'description': {'format': 'Invalid expression', 'parameters': [str(e)]}}})
            return
        except SyntaxError as e:
            self._CompleteBreakpoint({'status': {'isError': True, 'refersTo': 'BREAKPOINT_CONDITION', 'description': {'format': 'Expression could not be compiled: $0', 'parameters': [e.msg]}}})
            return
    native.LogInfo('Creating new Python breakpoint %s in %s, line %d' % (self.GetBreakpointId(), codeobj, line))
    self._cookie = native.SetConditionalBreakpoint(codeobj, line, condition, self._BreakpointEvent)

def map_midc_to_pvlib(variable_map, field_name):
    new_field_name = field_name
    for (midc_name, pvlib_name) in variable_map.items():
        if field_name.startswith(midc_name):
            instrument_units = field_name[len(midc_name):]
            units_index = instrument_units.find('[')
            instrument = instrument_units[:units_index - 1]
            new_field_name = pvlib_name + instrument.replace(' ', '_')
