def merge(a, b, op=None, recurse_list=False, max_depth=None):
    if op is None:
        op = operator.add
    if max_depth is not None:
        if max_depth < 1:
            return op(a, b)
        else:
            max_depth -= 1
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        for key in set(chain(a.keys(), b.keys())):
            if key in a and key in b:
                result[key] = merge(a[key], b[key], op=op, recurse_list=recurse_list, max_depth=max_depth)
            elif key in a:
                result[key] = deepcopy(a[key])
            elif key in b:
                result[key] = deepcopy(b[key])
        return result
    elif isinstance(a, list) and isinstance(b, list):
        if recurse_list and len(a) == len(b):
            result = []
            for idx in range(len(a)):
                result.append(merge(a[idx], b[idx], op=op, recurse_list=recurse_list, max_depth=max_depth))
            return result
        else:
            return op(a, b)
    return op(a, b)

def from_data(data, conv=None, pinf=float('inf'), ninf=float('-inf')):
    intervals = []
    conv = (lambda v: v) if conv is None else conv

    def _convert(bound):
        if bound == pinf:
            return inf
        elif bound == ninf:
            return -inf
        else:
            return conv(bound)
    for item in data:
        (left, lower, upper, right) = item
        intervals.append(AtomicInterval(left, _convert(lower), _convert(upper), right))
    return Interval(*intervals)

