def _changes(name, gid=None, addusers=None, delusers=None, members=None):
    lgrp = __salt__['group.info'](name)
    if not lgrp:
        return False
    if salt.utils.platform.is_windows():
        if lgrp['members']:
            lgrp['members'] = [user.lower() for user in lgrp['members']]
        if members:
            members = [salt.utils.win_functions.get_sam_name(user).lower() for user in members]
        if addusers:
            addusers = [salt.utils.win_functions.get_sam_name(user).lower() for user in addusers]
        if delusers:
            delusers = [salt.utils.win_functions.get_sam_name(user).lower() for user in delusers]
    change = {}
    ret = {}
    if gid:
        try:
            gid = int(gid)
            if lgrp['gid'] != gid:
                change['gid'] = gid
        except (TypeError, ValueError):
            ret['result'] = False
            ret['comment'] = 'Invalid gid'
            return ret
    if members is not None and (not members):
        if set(lgrp['members']).symmetric_difference(members):
            change['delusers'] = set(lgrp['members'])
    elif members:
        if set(lgrp['members']).symmetric_difference(members):
            change['members'] = members
    if addusers:
        users_2add = [user for user in addusers if user not in lgrp['members']]
        if users_2add:
            change['addusers'] = users_2add
    if delusers:
        users_2del = [user for user in delusers if user in lgrp['members']]
        if users_2del:
            change['delusers'] = users_2del
    return change

def find_entry(self, entry, exact=True):
    if exact:
        self.log([u"Finding entry '%s' with exact=True", entry])
        if entry in self.entries:
            self.log([u"Found entry '%s'", entry])
            return entry
    else:
        self.log([u"Finding entry '%s' with exact=False", entry])
        for ent in self.entries:
            if os.path.basename(ent) == entry:
                self.log([u"Found entry '%s'", ent])
                return ent
    self.log([u"Entry '%s' not found", entry])
    return None

