def close(self, reason=None, within=0):
    if self.closed:
        return
    if reason is None:
        reason = ConnectionDone()
    if within > 0:
        channel0 = (yield self.channel(0))
        deferred = channel0.connection_close()
        call = self.clock.callLater(within, deferred.cancel)
        try:
            yield deferred
        except defer.CancelledError:
            pass
        else:
            call.cancel()
    self.do_close(reason)

def split_result_of_axis_func_pandas(axis, num_splits, result, length_list=None):
    if num_splits == 1:
        return result
    if length_list is not None:
        length_list.insert(0, 0)
        sums = np.cumsum(length_list)
        if axis == 0:
            return [result.iloc[sums[i]:sums[i + 1]] for i in range(len(sums) - 1)]
        else:
            return [result.iloc[:, sums[i]:sums[i + 1]] for i in range(len(sums) - 1)]
    chunksize = compute_chunksize(result, num_splits, axis=axis)
    if axis == 0:
        return [result.iloc[chunksize * i:chunksize * (i + 1)] for i in range(num_splits)]
    else:
        return [result.iloc[:, chunksize * i:chunksize * (i + 1)] for i in range(num_splits)]

