def cut_microsoft_quote(html_message):
    ns = {'re': 'http://exslt.org/regular-expressions'}
    splitter = html_message.xpath("//div[@style[re:match(., 'border:none; ?border-top:solid #(E1E1E1|B5C4DF) 1.0pt; ?padding:3.0pt 0(in|cm) 0(in|cm) 0(in|cm)')]]|//div[@style='padding-top: 5px; border-top-color: rgb(229, 229, 229); border-top-width: 1px; border-top-style: solid;']", namespaces=ns)
    if splitter:
        splitter = splitter[0]
        if splitter == splitter.getparent().getchildren()[0]:
            splitter = splitter.getparent()
    else:
        splitter = html_message.xpath("//div/div[@class='MsoNormal' and @align='center' and @style='text-align:center']/font/span/hr[@size='3' and @width='100%' and @align='center' and @tabindex='-1']")
        if len(splitter):
            splitter = splitter[0]
            splitter = splitter.getparent().getparent()
            splitter = splitter.getparent().getparent()
    if len(splitter):
        parent = splitter.getparent()
        after_splitter = splitter.getnext()
        while after_splitter is not None:
            parent.remove(after_splitter)
            after_splitter = splitter.getnext()
        parent.remove(splitter)
        return True
    return False

