def ungroup_gen(grouped_items, groupxs, fill=None):
    import utool as ut
    minpergroup = [min(xs) if len(xs) else 0 for xs in groupxs]
    minval = min(minpergroup) if len(minpergroup) else 0
    flat_groupx = ut.flatten(groupxs)
    sortx = ut.argsort(flat_groupx)
    groupx_sorted = ut.take(flat_groupx, sortx)
    flat_items = ut.iflatten(grouped_items)
    toyeild = {}
    items_yeilded = 0
    current_index = 0
    num_fills_before = [minval] + (np.diff(groupx_sorted) - 1).tolist() + [0]
    fills = num_fills_before[items_yeilded]
    if fills > 0:
        for _ in range(fills):
            yield None
            current_index += 1
    for (yeild_at, item) in zip(flat_groupx, flat_items):
        if yeild_at > current_index:
            toyeild[yeild_at] = item
        elif yeild_at == current_index:
            yield item
            current_index += 1
            items_yeilded += 1
            fills = num_fills_before[items_yeilded]
            if fills > 0:
                for _ in range(fills):
                    yield None
                    current_index += 1
            while current_index in toyeild:
                item = toyeild.pop(current_index)
                yield item
                current_index += 1
                items_yeilded += 1
                fills = num_fills_before[items_yeilded]
                if fills > 0:
                    for _ in range(fills):
                        yield None
                        current_index += 1

def get_quote(self, code, as_json=False):
    code = code.upper()
    if self.is_valid_code(code):
        url = self.build_url_for_quote(code)
        req = Request(url, None, self.headers)
        res = self.opener.open(req)
        res = byte_adaptor(res)
        res = res.read()
        match = re.search('<div\\s+id="responseDiv"\\s+style="display:none">(.*?)</div>', res, re.S)
        try:
            buffer = match.group(1).strip()
            response = self.clean_server_response(json.loads(buffer)['data'][0])
        except SyntaxError as err:
            raise Exception('ill formatted response')
        else:
            return self.render_response(response, as_json)
    else:
        return None

