def shell(cmd, *args, **kwargs):
    if kwargs.get('rel_path') and (not cmd.startswith('/')):
        cmd = os.path.join(kwargs['rel_path'], cmd)
    status = 0
    try:
        output = subprocess.check_output((cmd,) + args, stderr=kwargs.get('stderr'))
    except subprocess.CalledProcessError as e:
        if kwargs.get('raise_on_status', True):
            raise e
        output = e.output
        status = e.returncode
    except OSError as e:
        if kwargs.get('raise_on_status', True):
            raise e
        if 'stderr' in kwargs:
            kwargs['stderr'].write(e.message)
        return (-1, '')
    if six.PY3:
        output = output.decode('utf8')
    return (status, output)

