def igrf_value(lat, lon, alt=0.0, year=2005.0):
    (X, Y, Z, F) = calculate.igrf12syn(0, year, 1, alt, lat, lon)
    D = FACT * np.arctan2(Y, X)
    H = np.sqrt(X * X + Y * Y)
    I = FACT * np.arctan2(Z, H)
    return (D, I, H, X, Y, Z, F)

def _get_bounds(self, ib, dimension):
    sign_ = 2 * ib - 1
    assert sign_ ** 2 == 1
    if self.bounds is None or self.bounds[ib] is None:
        return array(dimension * [sign_ * np.Inf])
    res = []
    for i in xrange(dimension):
        res.append(self.bounds[ib][min([i, len(self.bounds[ib]) - 1])])
        if res[-1] is None:
            res[-1] = sign_ * np.Inf
    return array(res)

