def build_fptree(self, transactions, root_value, root_count, frequent, headers):
    root = FPNode(root_value, root_count, None)
    for transaction in transactions:
        sorted_items = [x for x in transaction if x in frequent]
        sorted_items.sort(key=lambda x: frequent[x], reverse=True)
        if len(sorted_items) > 0:
            self.insert_tree(sorted_items, root, headers)
    return root

def describe(cls, sha1):
    cmd = ['git', 'describe', '--all', '--long', sha1]
    out = None
    try:
        out = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)
    except subprocess.CalledProcessError as e:
        if e.output.find('No tags can describe') != -1:
            return ''
        raise
    out = out.strip()
    out = re.sub('^(heads|tags|remotes)/', '', out)
    out = re.sub('-g[0-9a-f]{7,}$', '', out)
    return out

