def _prepare_abi(self, jsonabi):
    self.signatures = {}
    for element_description in jsonabi:
        abi_e = AbiMethod(element_description)
        if abi_e['type'] == 'constructor':
            self.signatures[b'__constructor__'] = abi_e
        elif abi_e['type'] == 'fallback':
            abi_e.setdefault('inputs', [])
            self.signatures[b'__fallback__'] = abi_e
        elif abi_e['type'] == 'function':
            if abi_e.get('signature'):
                self.signatures[Utils.str_to_bytes(abi_e['signature'])] = abi_e
        elif abi_e['type'] == 'event':
            self.signatures[b'__event__'] = abi_e
        else:
            raise Exception('Invalid abi type: %s - %s - %s' % (abi_e.get('type'), element_description, abi_e))

def visit_boolean_query(self, node):
    left = node.left.accept(self)
    right = node.right.accept(self)
    is_journal_keyword_op = isinstance(left, KeywordOp) and left.left == Keyword('journal')
    if is_journal_keyword_op:
        journal_and_volume_conjunction = _restructure_if_volume_follows_journal(left, right)
        if journal_and_volume_conjunction:
            return journal_and_volume_conjunction
    return AndOp(left, right) if isinstance(node.bool_op, And) else OrOp(left, right)

def get_field_info(model):
    if issubclass(model, mongoengine.EmbeddedDocument):
        pk = None
    else:
        pk = model._fields[model._meta['id_field']]
    fields = OrderedDict()
    references = OrderedDict()
    embedded = OrderedDict()

    def add_field(name, field):
        if isinstance(field, REFERENCING_FIELD_TYPES):
            references[name] = get_relation_info(field)
        elif isinstance(field, EMBEDDING_FIELD_TYPES):
            embedded[name] = get_relation_info(field)
        elif isinstance(field, COMPOUND_FIELD_TYPES):
            fields[name] = field
            if field.field:
                add_field(name + '.child', field.field)
        elif field is pk:
            return
        else:
            fields[name] = field
    for field_name in model._fields_ordered:
        add_field(field_name, model._fields[field_name])
    fields_and_pk = OrderedDict()
    fields_and_pk['pk'] = pk
    fields_and_pk[getattr(pk, 'name', 'pk')] = pk
    fields_and_pk.update(fields)
    return FieldInfo(pk, fields, references, fields_and_pk, embedded)

