def upload(state, host, hostname, filename, remote_filename=None, use_remote_sudo=False, ssh_keyscan=False, ssh_user=None):
    remote_filename = remote_filename or filename
    connection_target = hostname
    if ssh_user:
        connection_target = '@'.join((ssh_user, hostname))
    if ssh_keyscan:
        yield keyscan(state, host, hostname)
    if not use_remote_sudo:
        yield 'scp {0} {1}:{2}'.format(filename, connection_target, remote_filename)
    else:
        temp_remote_filename = state.get_temp_filename()
        upload_cmd = 'scp {0} {1}:{2}'.format(filename, connection_target, temp_remote_filename)
        yield upload_cmd
        yield command(state, host, connection_target, 'sudo mv {0} {1}'.format(temp_remote_filename, remote_filename))

def events_for_onchain_secretreveal(target_state: TargetTransferState, channel_state: NettingChannelState, block_number: BlockNumber, block_hash: BlockHash) -> List[Event]:
    transfer = target_state.transfer
    expiration = transfer.lock.expiration
    (safe_to_wait, _) = is_safe_to_wait(expiration, channel_state.reveal_timeout, block_number)
    secret_known_offchain = channel.is_secret_known_offchain(channel_state.partner_state, transfer.lock.secrethash)
    has_onchain_reveal_started = target_state.state == TargetTransferState.ONCHAIN_SECRET_REVEAL
    if not safe_to_wait and secret_known_offchain and (not has_onchain_reveal_started):
        target_state.state = TargetTransferState.ONCHAIN_SECRET_REVEAL
        secret = channel.get_secret(channel_state.partner_state, transfer.lock.secrethash)
