def detect_plates_vzcheck(step, seuil_memz):
    v_z = step.fields['v3'][0, :, :, 0]
    v_x = step.fields['v2'][0, :, :, 0]
    tcell = step.fields['T'][0, :, :, 0]
    n_z = step.geom.nztot
    nphi = step.geom.nptot
    rcmb = max(0, step.geom.rcmb)
    radius = step.geom.r_coord + rcmb
    radiusgrid = step.geom.rgeom[:, 0] + rcmb
    dphi = 1 / nphi
    vz_mean = 0
    tgrid = np.zeros((nphi, n_z + 1))
    tgrid[:, 0] = 1
    for i_z in range(1, n_z):
        for phi in range(nphi):
            tgrid[phi, i_z] = (tcell[phi, i_z - 1] * (radiusgrid[i_z] - radius[i_z - 1]) + tcell[phi, i_z] * (-radiusgrid[i_z] + radius[i_z])) / (radius[i_z] - radius[i_z - 1])
            vz_mean += abs(v_z[phi, i_z]) / (nphi * n_z)
    flux_c = n_z * [0]
    for i_z in range(1, n_z - 1):
        for phi in range(nphi):
            flux_c[i_z] += (tgrid[phi, i_z] - step.timeinfo.loc['Tmean']) * v_z[phi, i_z] * radiusgrid[i_z] * dphi
    if all((abs(flux_c[i_z]) <= np.max(flux_c) / 50 for i_z in range(n_z - n_z // 20, n_z))):
        raise error.StagnantLidError(step.sdat)
    else:
        dvphi = nphi * [0]
        dvx_thres = 16 * step.timeinfo.loc['vrms']
        for phi in range(0, nphi):
            dvphi[phi] = (v_x[phi, n_z - 1] - v_x[phi - 1, n_z - 1]) / ((1 + rcmb) * dphi)
        limits = []
        for phi in range(0, nphi - nphi // 33):
            mark = all((abs(dvphi[i]) <= abs(dvphi[phi]) for i in range(phi - nphi // 33, phi + nphi // 33)))
            if mark and abs(dvphi[phi]) >= dvx_thres:
                limits.append(phi)
        for phi in range(nphi - nphi // 33 + 1, nphi):
            mark = all((abs(dvphi[i]) <= abs(dvphi[phi]) for i in range(phi - nphi // 33 - nphi, phi + nphi // 33 - nphi)))
            if mark and abs(dvphi[phi]) >= dvx_thres:
                limits.append(phi)
        k = 0
        for i in range(len(limits)):
            vzm = 0
            phi = limits[i - k]
            for i_z in range(1 if phi == nphi - 1 else 0, n_z):
                vzm += (abs(v_z[phi, i_z]) + abs(v_z[phi - 1, i_z]) + abs(v_z[(phi + 1) % nphi, i_z])) / (n_z * 3)
            vz_thres = vz_mean * 0.1 + seuil_memz / 2 if seuil_memz else 0
            if vzm < vz_thres:
                limits.remove(phi)
                k += 1
    return (limits, nphi, dvphi, vz_thres, v_x[:, n_z - 1])

