def check(source, filename='<string>', report_level=docutils.utils.Reporter.INFO_LEVEL, ignore=None, debug=False):
    register_code_directive()
    ignore_sphinx()
    ignore = ignore or {}
    try:
        ignore.setdefault('languages', []).extend(find_ignored_languages(source))
    except Error as error:
        yield (error.line_number, '{}'.format(error))
    writer = CheckWriter(source, filename, ignore=ignore)
    string_io = io.StringIO()
    source = strip_byte_order_mark(source)
    try:
        docutils.core.publish_string(source, writer=writer, source_path=filename, settings_overrides={'halt_level': report_level, 'report_level': report_level, 'warning_stream': string_io})
    except docutils.utils.SystemMessage:
        pass
    except AttributeError:
        if debug:
            raise
    for checker in writer.checkers:
        for error in checker():
            yield error
    rst_errors = string_io.getvalue().strip()
    if rst_errors:
        for message in rst_errors.splitlines():
            try:
                ignore_regex = ignore.get('messages', '')
                if ignore_regex and re.search(ignore_regex, message):
                    continue
                yield parse_gcc_style_error_message(message, filename=filename, has_column=False)
            except ValueError:
                continue

def _colorbar_ticks(minval, maxval):
    if not (np.isfinite(minval) and np.isfinite(maxval)):
        return [0, 0, 0]
    elif minval == maxval:
        return [minval]
    else:
        eps = (maxval - minval) / 100000.0
        return [minval + eps, (maxval + minval) / 2.0, maxval - eps]

def rl_cleanspaces(x):
    patterns = ((' +([\\.,?!\\)]+)', '\\1'), ('([\\.,?!\\)]+)([^\\.!,?\\)]+)', '\\1 \\2'), ('(\\S+)\\s*(\\()\\s*(\\S+)', '\\1 (\\3'))
    return os.linesep.join((' '.join((part for part in line.split(' ') if part)) for line in _sub_patterns(patterns, x).split(os.linesep)))

