def load_model(cls, database, reaction_iter=None, exchange=None, limits=None, v_max=None):
    model_args = {}
    if v_max is not None:
        model_args['v_max'] = v_max
    model = cls(database, **model_args)
    if reaction_iter is None:
        reaction_iter = iter(database.reactions)
    for reaction_id in reaction_iter:
        model.add_reaction(reaction_id)
    if limits is not None:
        for (reaction_id, lower, upper) in limits:
            if lower is not None:
                model.limits[reaction_id].lower = lower
            if upper is not None:
                model.limits[reaction_id].upper = upper
    if exchange is not None:
        for (compound, reaction_id, lower, upper) in exchange:
            if reaction_id is None:
                reaction_id = create_exchange_id(model.database.reactions, compound)
            model.database.set_reaction(reaction_id, Reaction(Direction.Both, {compound: -1}))
            model.add_reaction(reaction_id)
            if lower is not None:
                model.limits[reaction_id].lower = lower
            if upper is not None:
                model.limits[reaction_id].upper = upper
    return model

def detect_stream_mode(stream):
    if hasattr(stream, 'mode'):
        if 'b' in stream.mode:
            return bytes
        elif 't' in stream.mode:
            return str
    if hasattr(stream, 'read'):
        zeroStr = stream.read(0)
        if type(zeroStr) is str:
            return str
        return bytes
    elif hasattr(stream, 'recv'):
        zeroStr = stream.recv(0)
        if type(zeroStr) is str:
            return str
        return bytes
    return bytes

