def _get_temperature(self, decoded):
    temp = (decoded[2] & 127) + decoded[3] / 100
    sign = decoded[2] >> 7 & 1
    if sign == 0:
        return round(temp, 2)
    return round(-1 * temp, 2)

def sha1_digest(instr):
    if six.PY3:
        b = salt.utils.stringutils.to_bytes(instr)
        return hashlib.sha1(b).hexdigest()
    return hashlib.sha1(instr).hexdigest()

