        query = query.offset(page * page_size)
    if page_size:
        query = query.limit(page_size)
    return (count, query.all())

def labelset_heads(self, label):
    _eps = self._eps
    _vars = self._vars
    _hcons = self._hcons
    nodeids = {nodeid: _eps[nodeid][3].get(IVARG_ROLE, None) for nodeid in _vars[label]['refs']['LBL']}
    if len(nodeids) <= 1:
        return list(nodeids)
    scope_sets = {}
    for nid in nodeids:
        scope_sets[nid] = _ivs_in_scope(nid, _eps, _vars, _hcons)
    out = {}
    for n in nodeids:
        out[n] = 0
        for (role, val) in _eps[n][3].items():
            if role == IVARG_ROLE or role == CONSTARG_ROLE:
                continue
            elif any((val in s for (n2, s) in scope_sets.items() if n2 != n)):
                out[n] += 1
    candidates = [n for (n, out_deg) in out.items() if out_deg == 0]
    rank = {}
    for n in candidates:
        iv = nodeids[n]
        pred = _eps[n][1]
        if iv in _vars and self.nodeid(iv, quantifier=True) is not None:
            rank[n] = 0
        elif pred.is_quantifier():
            rank[n] = 0
        elif pred.type == Pred.ABSTRACT:
            rank[n] = 2
        else:
            rank[n] = 1
    return sorted(candidates, key=lambda n: rank[n])

def _get_csv_cells_gen(self, line):
    digest_types = self.digest_types
    for (j, value) in enumerate(line):
        if self.first_line:
            digest_key = None
            digest = lambda x: x.decode(self.encoding)
        else:
            try:
                digest_key = digest_types[j]
            except IndexError:
                digest_key = digest_types[0]
            digest = Digest(acceptable_types=[digest_key], encoding=self.encoding)
        try:
            digest_res = digest(value)
            if digest_res == '\x08':
                digest_res = None
            elif digest_key is not types.CodeType:
                digest_res = repr(digest_res)
        except Exception:
            digest_res = ''
        yield digest_res

def download_ts(self, path, chunk, process_last_line=True):
    import glob
    ret_chunk = []
    partial_chunk = ''
    lines = chunk.strip().split('\n')
    if not process_last_line:
        partial_chunk = lines.pop()
    for line in lines:
        if line.startswith('http:'):
            ts = '%s/%s.ts' % (path, line.split('.ts?')[0].split('/')[-1])
            relative_ts = '%s/%s.ts' % (path.split('/')[-1], line.split('.ts?')[0].split('/')[-1])
            if not os.path.exists(ts):
                gevent.spawn(ApiCall.save_url_to_file, line, ts).start()
                gevent.sleep(0)
                ret_chunk.append('# ' + line)
                ret_chunk.append(relative_ts)
            else:
                ret_chunk = []
        else:
            ret_chunk.append(line)
    if '#EXT-X-ENDLIST' in chunk:
        self.repeat_needed = 0
        gevent.sleep(0)
    elif chunk.strip():
        self.repeat_needed = 1 + len(glob.glob(path + '/*.ts'))
    ret_chunk = ret_chunk and '\n'.join(ret_chunk) + '\n' or ''
    return (ret_chunk, partial_chunk)

