def _create_socks_endpoint(reactor, control_protocol, socks_config=None):
    socks_ports = (yield control_protocol.get_conf('SOCKSPort'))
    if socks_ports:
        socks_ports = list(socks_ports.values())[0]
        if not isinstance(socks_ports, list):
            socks_ports = [socks_ports]
        if socks_ports == ['DEFAULT']:
            default = (yield control_protocol.get_conf_single('__SocksPort'))
            socks_ports = [default]
    else:
        socks_ports = []
    socks_ports = [port.split()[0] for port in socks_ports]
    unix_ports = set([p for p in socks_ports if p.startswith('unix:')])
    tcp_ports = set(socks_ports) - unix_ports
    socks_endpoint = None
    for p in list(unix_ports) + list(tcp_ports):
        if socks_config and p != socks_config:
            continue
        try:
            socks_endpoint = _endpoint_from_socksport_line(reactor, p)
        except Exception as e:
            log.err(Failure(), "failed to process SOCKS port '{}': {}".format(p, e))
    if socks_endpoint is None:
        if socks_config is None:
            port = (yield available_tcp_port(reactor))
            socks_config = str(port)
        socks_ports.append(socks_config)
        args = []
        for p in socks_ports:
            args.append('SOCKSPort')
            args.append(p)
        yield control_protocol.set_conf(*args)
        socks_endpoint = _endpoint_from_socksport_line(reactor, socks_config)
    assert socks_endpoint is not None
    defer.returnValue(socks_endpoint)

def drop(self, labels=None, axis=0, index=None, columns=None, level=None, inplace=False, errors='raise'):
    if level is not None:
        return self._default_to_pandas('drop', labels=labels, axis=axis, index=index, columns=columns, level=level, inplace=inplace, errors=errors)
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if labels is not None:
        if index is not None or columns is not None:
            raise ValueError("Cannot specify both 'labels' and 'index'/'columns'")
        axis = pandas.DataFrame()._get_axis_name(axis)
        axes = {axis: labels}
    elif index is not None or columns is not None:
        (axes, _) = pandas.DataFrame()._construct_axes_from_arguments((index, columns), {})
    else:
        raise ValueError("Need to specify at least one of 'labels', 'index' or 'columns'")
    if 'index' not in axes:
        axes['index'] = None
    elif axes['index'] is not None:
        if not is_list_like(axes['index']):
            axes['index'] = [axes['index']]
        if errors == 'raise':
            non_existant = [obj for obj in axes['index'] if obj not in self.index]
            if len(non_existant):
                raise ValueError('labels {} not contained in axis'.format(non_existant))
        else:
            axes['index'] = [obj for obj in axes['index'] if obj in self.index]
            if not len(axes['index']):
                axes['index'] = None
    if 'columns' not in axes:
        axes['columns'] = None
    elif axes['columns'] is not None:
        if not is_list_like(axes['columns']):
            axes['columns'] = [axes['columns']]
        if errors == 'raise':
            non_existant = [obj for obj in axes['columns'] if obj not in self.columns]
            if len(non_existant):
                raise ValueError('labels {} not contained in axis'.format(non_existant))
        else:
            axes['columns'] = [obj for obj in axes['columns'] if obj in self.columns]
            if not len(axes['columns']):
                axes['columns'] = None
    new_query_compiler = self._query_compiler.drop(index=axes['index'], columns=axes['columns'])
    return self._create_or_update_from_compiler(new_query_compiler, inplace)

