def all_enclosing_scopes(scope, allow_global=True):
    _validate_full_scope(scope)

    def scope_within_range(tentative_scope):
        if tentative_scope is None:
            return False
        if not allow_global and tentative_scope == GLOBAL_SCOPE:
            return False
        return True
    while scope_within_range(scope):
        yield scope
        scope = None if scope == GLOBAL_SCOPE else enclosing_scope(scope)

def versional(a, b):
    stra = nstr(a).lower()
    strb = nstr(b).lower()
    aresults = EXPR_VERSIONAL.findall(stra)
    bresults = EXPR_VERSIONAL.findall(strb)
    bcount = len(bresults)
    for i in range(len(aresults)):
        if bcount <= i:
            break
        (atext, anum) = aresults[i]
        (btext, bnum) = bresults[i]
        if atext != btext:
            return cmp(atext, btext)
        if not anum:
            anum = 0
        if not bnum:
            bnum = 0
        if atext == '.':
            anum = int(float('.' + anum) * 10000)
            bnum = int(float('.' + bnum) * 10000)
        else:
            anum = int(anum)
            bnum = int(bnum)
        if anum != bnum:
            return cmp(anum, bnum)
    return 1

