def _read2(self, length=None, use_compression=None, project=None, **kwargs):
    if self._file_length == None:
        desc = self.describe(**kwargs)
        if desc['state'] != 'closed':
            raise DXFileError('Cannot read from file until it is in the closed state')
        self._file_length = int(desc['size'])
    get_first_chunk_sequentially = self._file_length > 128 * 1024 and self._pos == 0 and dxpy.JOB_ID
    if self._pos == self._file_length:
        return b''
    if length == None or length > self._file_length - self._pos:
        length = self._file_length - self._pos
    buf = self._read_buf
    buf_remaining_bytes = dxpy.utils.string_buffer_length(buf) - buf.tell()
    if length <= buf_remaining_bytes:
        self._pos += length
        return buf.read(length)
    else:
        orig_buf_pos = buf.tell()
        orig_file_pos = self._pos
        buf.seek(0, os.SEEK_END)
        self._pos += buf_remaining_bytes
        while self._pos < orig_file_pos + length:
            remaining_len = orig_file_pos + length - self._pos
            if self._response_iterator is None:
                self._request_iterator = self._generate_read_requests(start_pos=self._pos, project=project, **kwargs)
            content = self._next_response_content(get_first_chunk_sequentially=get_first_chunk_sequentially)
            if len(content) < remaining_len:
                buf.write(content)
                self._pos += len(content)
            else:
                buf.write(content[:remaining_len])
                self._pos += remaining_len
                self._read_buf = BytesIO()
                self._read_buf.write(content[remaining_len:])
                self._read_buf.seek(0)
        buf.seek(orig_buf_pos)
        return buf.read()

def update_items(portal_type=None, uid=None, endpoint=None, **kw):
    req.disable_csrf_protection()
    records = req.get_request_data()
    obj = get_object_by_uid(uid)
    if obj:
        record = records[0]
        obj = update_object_with_data(obj, record)
        return make_items_for([obj], endpoint=endpoint)
    results = []
    for record in records:
        obj = get_object_by_record(record)
        if obj is None:
            continue
        obj = update_object_with_data(obj, record)
        results.append(obj)
    if not results:
        fail(400, 'No Objects could be updated')
    return make_items_for(results, endpoint=endpoint)

def select(self, fields=['rowid', '*'], offset=None, limit=None):
    SQL = 'SELECT %s FROM %s' % (','.join(fields), self._table)
    if self._selectors:
        SQL = ' '.join([SQL, 'WHERE', self._selectors]).strip()
    if self._modifiers:
        SQL = ' '.join([SQL, self._modifiers])
    if limit is not None and isinstance(limit, int):
        SQL = ' '.join((SQL, 'LIMIT %s' % limit))
    if limit is not None and offset is not None and isinstance(offset, int):
        SQL = ' '.join((SQL, 'OFFSET %s' % offset))
    return ''.join((SQL, ';'))

def _results(self, product, path, cls=Results, **kwargs):
    if product != 'account-information' and self.rate_limit and (not self.limits_set) and (not self.limits):
        self._rate_limit()
    uri = '/'.join(('{0}://api.domaintools.com'.format('https' if self.https else 'http'), path.lstrip('/')))
    parameters = self.default_parameters.copy()
    parameters['api_username'] = self.username
    if self.https:
        parameters['api_key'] = self.key
    else:
        parameters['timestamp'] = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
        parameters['signature'] = hmac(self.key.encode('utf8'), ''.join([self.username, parameters['timestamp'], path]).encode('utf8'), digestmod=sha1).hexdigest()
    parameters.update(dict(((key, str(value).lower() if value in (True, False) else value) for (key, value) in kwargs.items() if value is not None)))
    return cls(self, product, uri, **parameters)

