    if self.config:
        self.prefix = self.config.get('config_prefix', None)
    if not self.prefix:
        if os.getenv(self.config_prefix):
            self.prefix = os.getenv(self.config_prefix)
        else:
            for path in [os.path.join(self.basepath, self.default_file), os.path.join(self.config_root, self.default_file)]:
                if os.path.exists(path):
                    with open(path) as conf:
                        config = yaml.load(conf)
                        prefix = config.get(self.config_prefix.lower(), None)
                        if prefix:
                            self.prefix = prefix
                            break

def detect_protocol(cls, message):
    main = cls._message_to_payload(message)

    def protocol_for_payload(payload):
        if not isinstance(payload, dict):
            return JSONRPCLoose
        version = payload.get('jsonrpc')
        if version == '2.0':
            return JSONRPCv2
        if version == '1.0':
            return JSONRPCv1
        if 'result' in payload and 'error' in payload:
            return JSONRPCv1
        return JSONRPCLoose
    if isinstance(main, list):
        parts = set((protocol_for_payload(payload) for payload in main))
        if len(parts) == 1:
            return parts.pop()
        for protocol in (JSONRPCv2, JSONRPCv1):
            if protocol in parts:
                return protocol
        return JSONRPCLoose
    return protocol_for_payload(main)

