def index(self, item, minindex=0, maxindex=None):
    if maxindex is None:
        maxindex = len(self)
    minindex = max(0, minindex) - 1
    maxindex = min(len(self), maxindex)
    if not isinstance(item, str):
        raise TypeError('Members of this object must be strings. You supplied "%s"' % type(item))
    index = minindex
    while index < maxindex:
        index += 1
        if item.lower() == self[index].lower():
            return index
    raise ValueError(': list.index(x): x not in list')

