def oboTermParser(filepath):
    with io.open(filepath) as openfile:
        lineIter = iter([i.rstrip() for i in openfile.readlines()])
    try:
        line = next(lineIter)
        while line != '[Term]':
            line = next(lineIter)
        header = line
        entryLines = list()
    except StopIteration:
        errorText = 'File does not contain obo "[Term]" entries.'
        raise maspy.errors.FileFormatError(errorText)
    for line in lineIter:
        if not line:
            continue
        if line == '[Term]':
            yield entryLines
            header = line
            entryLines = list()
        else:
            entryLines.append(line)
    if entryLines:
        yield entryLines

def assign(self, object_type, object_uuid, overwrite=False):
    if self.is_deleted():
        raise PIDInvalidAction('You cannot assign objects to a deleted/redirected persistent identifier.')
    if not isinstance(object_uuid, uuid.UUID):
        object_uuid = uuid.UUID(object_uuid)
    if self.object_type or self.object_uuid:
        if object_type == self.object_type and object_uuid == self.object_uuid:
            return True
        if not overwrite:
            raise PIDObjectAlreadyAssigned(object_type, object_uuid)
        self.unassign()
    try:
        with db.session.begin_nested():
            self.object_type = object_type
            self.object_uuid = object_uuid
            db.session.add(self)
    except SQLAlchemyError:
        logger.exception('Failed to assign {0}:{1}'.format(object_type, object_uuid), extra=dict(pid=self))
        raise
    logger.info('Assigned object {0}:{1}'.format(object_type, object_uuid), extra=dict(pid=self))
    return True

