        if s.find('\n') == -1:
            if isinstance(s, unicode):
                s = s.encode(vim_encoding)
            b.append(s)
        else:
            try:
                b.append(s.splitlines())
            except Exception:
                b.append([l.encode(vim_encoding) for l in s.splitlines()])
        update_occured = True
    if status_blank_lines:
        if b[-1] != '':
            b.append([''])
    if update_occured or force:
        vim.command('normal! G')
    if not startedin_vimipython:
        vim.command('normal! \x17p')
    return update_occured

def ParseFileObject(self, parser_mediator, file_object):
    data = file_object.read(self._HEADER_READ_SIZE)
    if not data.startswith(b'<?xml'):
        raise errors.UnableToParseFile('Not an Opera typed history file [not a XML]')
    (_, _, data) = data.partition(b'\n')
    if not data.startswith(b'<typed_history'):
        raise errors.UnableToParseFile('Not an Opera typed history file [wrong XML root key]')
    file_object.seek(0, os.SEEK_SET)
    xml = ElementTree.parse(file_object)
    for history_item in xml.iterfind('typed_history_item'):
        event_data = OperaTypedHistoryEventData()
        event_data.entry_type = history_item.get('type', None)
        event_data.url = history_item.get('content', None)
        if event_data.entry_type == 'selected':
            event_data.entry_selection = 'Filled from autocomplete.'
        elif event_data.entry_type == 'text':
            event_data.entry_selection = 'Manually typed.'
        last_typed_time = history_item.get('last_typed', None)
        if last_typed_time is None:
            parser_mediator.ProduceExtractionWarning('missing last typed time.')
            continue
        date_time = dfdatetime_time_elements.TimeElements()
        try:
            date_time.CopyFromStringISO8601(last_typed_time)
        except ValueError as exception:
            parser_mediator.ProduceExtractionWarning('unsupported last typed time: {0:s} with error: {1!s}.'.format(last_typed_time, exception))
            continue
        event = time_events.DateTimeValuesEvent(date_time, definitions.TIME_DESCRIPTION_LAST_VISITED)
        parser_mediator.ProduceEventWithEventData(event, event_data)

def refresh_session_if_necessary(f):

    @functools.wraps(f)
    def wrapped(self, *args, **kwargs):
        try:
            result = f(self, *args, **kwargs)
        except Exception as ex:
            if hasattr(ex, 'code') and ex.code in (401, 403):
                self.refresh_session()
                result = f(self, *args, **kwargs)
            else:
                raise ex
        return result
    return wrapped

