def get_libsodium():
    __SONAMES = (13, 10, 5, 4)
    sys_sodium = ctypes.util.find_library('sodium')
    if sys_sodium is None:
        sys_sodium = ctypes.util.find_library('libsodium')
    if sys_sodium:
        try:
            return ctypes.CDLL(sys_sodium)
        except OSError:
            pass
    if sys.platform.startswith('win'):
        try:
            return ctypes.cdll.LoadLibrary('libsodium')
        except OSError:
            pass
        for soname_ver in __SONAMES:
            try:
                return ctypes.cdll.LoadLibrary('libsodium-{0}'.format(soname_ver))
            except OSError:
                pass
    elif sys.platform.startswith('darwin'):
        try:
            return ctypes.cdll.LoadLibrary('libsodium.dylib')
        except OSError:
            try:
                libidx = __file__.find('lib')
                if libidx > 0:
                    libpath = __file__[0:libidx + 3] + '/libsodium.dylib'
                    return ctypes.cdll.LoadLibrary(libpath)
            except OSError:
                pass
    else:
        try:
            return ctypes.cdll.LoadLibrary('libsodium.so')
        except OSError:
            pass
        for soname_ver in __SONAMES:
            try:
                return ctypes.cdll.LoadLibrary('libsodium.so.{0}'.format(soname_ver))
            except OSError:
                pass

def wait(self, timeout_s: float=None) -> int:
    if not self.running:
        return 0
    retcode = self.process.wait(timeout=timeout_s)
    if retcode is None:
        self.error('Subprocess finished, but return code was None')
        retcode = 1
    elif retcode == 0:
        self.info('Subprocess finished cleanly (return code 0).')
    else:
        self.error('Subprocess finished, but FAILED (return code {}). Logs were: {} (stdout), {} (stderr)'.format(retcode, self.details.logfile_out, self.details.logfile_err))
    self.running = False
    return retcode

