def _R2deriv(self, R, z, phi=0.0, t=0.0):
    r = numpy.sqrt(R ** 2.0 + z ** 2.0)
    x = r / self.a
    return -numpy.pi / x ** 3.0 / r ** 2.0 * (-4.0 * R ** 2.0 * r ** 3.0 / (self.a ** 2.0 + r ** 2.0) / (self.a + r) + (z ** 2.0 - 2.0 * R ** 2.0) * (numpy.pi - 2.0 * numpy.arctan(1.0 / x) - 2.0 * numpy.log(1.0 + x) - numpy.log(1.0 + x ** 2.0)))

