def draw_mask(im, mask, alpha=0.5, color=None):
    if color is None:
        color = PALETTE_RGB[np.random.choice(len(PALETTE_RGB))][::-1]
    im = np.where(np.repeat((mask > 0)[:, :, None], 3, axis=2), im * (1 - alpha) + color * alpha, im)
    im = im.astype('uint8')
    return im

def eeg_to_df(eeg, index=None, include='all', exclude=None, hemisphere='both', central=True):
    if isinstance(eeg, mne.Epochs):
        data = {}
        if index is None:
            index = range(len(eeg))
        for (epoch_index, epoch) in zip(index, eeg.get_data()):
            epoch = pd.DataFrame(epoch.T)
            epoch.columns = eeg.ch_names
            epoch.index = eeg.times
            selection = eeg_select_electrodes(eeg, include=include, exclude=exclude, hemisphere=hemisphere, central=central)
            data[epoch_index] = epoch[selection]
    else:
        data = eeg.get_data().T
        data = pd.DataFrame(data)
        data.columns = eeg.ch_names
        data.index = eeg.times
    return data

def tsiterator(ts, dateconverter=None, desc=None, clean=False, start_value=None, **kwargs):
    dateconverter = dateconverter or default_converter
    yield (['Date'] + ts.names())
    if clean == 'full':
        for (dt, value) in full_clean(ts, dateconverter, desc, start_value):
            yield ((dt,) + tuple(value))
    else:
        if clean:
            ts = ts.clean()
        for (dt, value) in ts.items(desc=desc, start_value=start_value):
            dt = dateconverter(dt)
            yield ((dt,) + tuple(value))

