def get_all_subclasses(typ, recursive: bool=True, _memo=None) -> Sequence[Type[Any]]:
    _memo = _memo or set()
    if typ in _memo:
        return []
    _memo.add(typ)
    if is_generic_type(typ):
        sub_list = get_origin(typ).__subclasses__()
    else:
        sub_list = typ.__subclasses__()
    result = []
    for t in sub_list:
        to = get_origin(t) or t
        try:
            if to is not typ and to not in result and is_subtype(to, typ, bound_typevars={}):
                result.append(to)
        except:
            pass
    if recursive:
        for typpp in sub_list:
            for t in get_all_subclasses(typpp, recursive=True, _memo=_memo):
                if t not in sub_list and is_subtype(t, typ, bound_typevars={}):
                    result.append(t)
    return result

def shuffled_batches(self, batch_size):
    if batch_size >= self.num_envs * self.num_steps:
        yield self
    else:
        rollouts_in_batch = batch_size // self.num_steps
        batch_splits = math_util.divide_ceiling(self.num_envs, rollouts_in_batch)
        indices = list(range(self.num_envs))
        np.random.shuffle(indices)
        for sub_indices in np.array_split(indices, batch_splits):
            yield Trajectories(num_steps=self.num_steps, num_envs=len(sub_indices), environment_information=None, transition_tensors={k: x[:, sub_indices] for (k, x) in self.transition_tensors.items()}, rollout_tensors={k: x[sub_indices] for (k, x) in self.rollout_tensors.items()})

