def get_cached(self, path, cache_name, **kwargs):
    if gw2api.cache_dir and gw2api.cache_time and cache_name:
        cache_file = os.path.join(gw2api.cache_dir, cache_name)
        if mtime(cache_file) >= time.time() - gw2api.cache_time:
            with open(cache_file, 'r') as fp:
                tmp = json.load(fp)
            return self.make_response(tmp['data'], tmp['meta'])
    else:
        cache_file = None
    (meta, data) = self._get(path, **kwargs)
    if cache_file:
        with open(cache_file, 'w') as fp:
            json.dump({'meta': meta, 'data': data}, fp, indent=2)
    return self.make_response(data, meta)

def update_host_password(host, username, password, new_password, protocol=None, port=None):
    service_instance = salt.utils.vmware.get_service_instance(host=host, username=username, password=password, protocol=protocol, port=port)
    account_manager = salt.utils.vmware.get_inventory(service_instance).accountManager
    user_account = vim.host.LocalAccountManager.AccountSpecification()
    user_account.id = username
    user_account.password = new_password
    try:
        account_manager.UpdateUser(user_account)
    except vmodl.fault.SystemError as err:
        raise CommandExecutionError(err.msg)
    except vim.fault.UserNotFound:
        raise CommandExecutionError("'vsphere.update_host_password' failed for host {0}: User was not found.".format(host))
    except vim.fault.AlreadyExists:
        pass
    return True

def FetchCompletedResponses(self, session_id, timestamp=None, limit=10000):
    if timestamp is None:
        timestamp = (0, self.frozen_timestamp or rdfvalue.RDFDatetime.Now())
    completed_requests = collections.deque(self.FetchCompletedRequests(session_id, timestamp=timestamp))
    total_size = 0
    while completed_requests:
        projected_total_size = total_size
        request_list = []
        while completed_requests:
            (request, status) = completed_requests.popleft()
            request_list.append(request)
            projected_total_size += status.response_id
            if projected_total_size > limit:
                break
        for (request, responses) in self.data_store.ReadResponses(request_list):
            yield (request, responses)
            total_size += len(responses)
            if total_size > limit:
                raise MoreDataException()

