def iterfiles(self, pattern=None, abspath=False):
    if pattern is not None:
        globster = Globster([pattern])
    for (root, dirs, files) in self.walk():
        for f in files:
            if pattern is None or (pattern is not None and globster.match(f)):
                if abspath:
                    yield os.path.join(root, f)
                else:
                    yield self.relpath(os.path.join(root, f))

def attached(self, worker, commands):
    for w in self.attaching_workers + self.workers:
        if w.worker == worker:
            return defer.succeed(self)
    wfb = workerforbuilder.WorkerForBuilder()
    wfb.setBuilder(self)
    self.attaching_workers.append(wfb)
    try:
        wfb = (yield wfb.attached(worker, commands))
        self.attaching_workers.remove(wfb)
        self.workers.append(wfb)
        return self
    except Exception as e:
        log.err(e, 'worker failed to attach')
        return None

