def reciprocal_rank(model, test_interactions, train_interactions=None, user_features=None, item_features=None, preserve_rows=False, num_threads=1, check_intersections=True):
    if num_threads < 1:
        raise ValueError('Number of threads must be 1 or larger.')
    ranks = model.predict_rank(test_interactions, train_interactions=train_interactions, user_features=user_features, item_features=item_features, num_threads=num_threads, check_intersections=check_intersections)
    ranks.data = 1.0 / (ranks.data + 1.0)
    ranks = np.squeeze(np.array(ranks.max(axis=1).todense()))
    if not preserve_rows:
        ranks = ranks[test_interactions.getnnz(axis=1) > 0]
    return ranks

def uninstall_package_and_data(package_name, service_name=None, role=None, principal=None, zk_node=None, timeout_sec=600):
