    if service_name is None:
        pkg = _get_package_manager().get_package_version(package_name, None)
        service_name = _get_service_name(package_name, pkg)
    print('\n{}uninstalling/deleting {}'.format(shakedown.cli.helpers.fchr('>>'), service_name))
    try:
        uninstall_package_and_wait(package_name, service_name=service_name, timeout_sec=timeout_sec)
    except (errors.DCOSException, ValueError) as e:
        print('Got exception when uninstalling package, ' + 'continuing with janitor anyway: {}'.format(e))
    data_start = time.time()
    if (not role or not principal or (not zk_node)) and service_name is None:
        raise DCOSException("service_name must be provided when data params are missing AND the package isn't installed")
    if not role:
        role = '{}-role'.format(service_name)
    if not zk_node:
        zk_node = 'dcos-service-{}'.format(service_name)
    delete_persistent_data(role, zk_node)
    finish = time.time()
    print('\n{}uninstall/delete done after pkg({}) + data({}) = total({})\n'.format(shakedown.cli.helpers.fchr('>>'), pretty_duration(data_start - start), pretty_duration(finish - data_start), pretty_duration(finish - start)))

def from_file(cls, filename, source):
    _logger.info('Loading theme %s', filename)
    try:
        config = configparser.ConfigParser()
        config.optionxform = six.text_type
        with codecs.open(filename, encoding='utf-8') as fp:
            config.readfp(fp)
    except configparser.ParsingError as e:
        raise ConfigError(e.message)
    if not config.has_section('theme'):
        raise ConfigError('Error loading {0}:\n    missing [theme] section'.format(filename))
    theme_name = os.path.basename(filename)
    (theme_name, _) = os.path.splitext(theme_name)
    elements = {}
    for (element, line) in config.items('theme'):
        if element not in cls.DEFAULT_ELEMENTS:
            _logger.info('Skipping element %s', element)
            continue
        elements[element] = cls._parse_line(element, line, filename)
    return cls(name=theme_name, source=source, elements=elements)

def _get_dicts_from_redis(self, name, index_name, redis_prefix, item):
    r = self._redis
    data_dict = {}
    data_index_dict = {}
    if redis_prefix is None:
        raise KeyError('redis_prefix is missing')
    if r.scard(redis_prefix + index_name + str(item)) > 0:
        data_index_dict[str(item)] = r.smembers(redis_prefix + index_name + str(item))
        for i in data_index_dict[item]:
            json_data = r.get(redis_prefix + name + str(int(i)))
            data_dict[i] = self._deserialize_data(json_data)
        return (data_dict, data_index_dict)
    raise KeyError('No Data found in Redis for ' + item)

def _build_split_filenames(self, split_info_list):
