            return 'Required parameter "subscription" not passed'
    elif trigger_types[trigger_type] == TASK_TRIGGER_TIME:
        trigger.Id = 'Once_ID1'
    elif trigger_types[trigger_type] == TASK_TRIGGER_DAILY:
