def fric_rect(FlowRate, Width, DistCenter, Nu, PipeRough, openchannel):
    ut.check_range([PipeRough, '0-1', 'Pipe roughness'])
    if re_rect(FlowRate, Width, DistCenter, Nu, openchannel) >= RE_TRANSITION_PIPE:
        return 0.25 / np.log10(PipeRough / (3.7 * 4 * radius_hydraulic(Width, DistCenter, openchannel).magnitude) + 5.74 / re_rect(FlowRate, Width, DistCenter, Nu, openchannel) ** 0.9) ** 2
    else:
        return 64 / re_rect(FlowRate, Width, DistCenter, Nu, openchannel)

def send_with_data_passthrough(self, event):
    if self.our_state is ERROR:
        raise LocalProtocolError("Can't send data when our state is ERROR")
    try:
        if type(event) is Response:
            self._clean_up_response_headers_for_sending(event)
        writer = self._writer
        self._process_event(self.our_role, event)
        if type(event) is ConnectionClosed:
            return None
        else:
            assert writer is not None
            data_list = []
            writer(event, data_list.append)
            return data_list
    except:
        self._process_error(self.our_role)
        raise

def _col_type_set(self, col, df):
    type_set = set()
    if df[col].dtype == np.dtype(object):
        unindexed_col = list(df[col])
        for i in range(0, len(df[col])):
            if unindexed_col[i] == np.nan:
                continue
            else:
                type_set.add(type(unindexed_col[i]))
        return type_set
    else:
        type_set.add(df[col].dtype)
        return type_set

