def set(self, keyword, value):
    if not keyword.startswith(':'):
        keyword = ':' + keyword
    if isinstance(value, str):
        value = KQMLToken(value)
    if isinstance(keyword, str):
        keyword = KQMLToken(keyword)
    found = False
    for (i, key) in enumerate(self.data):
        if key.to_string().lower() == keyword.lower():
            found = True
            if i < len(self.data) - 1:
                self.data[i + 1] = value
            break
    if not found:
        self.data.append(keyword)
        self.data.append(value)

def _str_dtype(dtype):
    assert dtype.byteorder != '>'
    if dtype.kind == 'i':
        assert dtype.itemsize == 8
        return 'int64'
    elif dtype.kind == 'f':
        assert dtype.itemsize == 8
        return 'float64'
    elif dtype.kind == 'U':
        return 'U%d' % (dtype.itemsize / 4)
    else:
        raise UnhandledDtypeException("Bad dtype '%s'" % dtype)

def _call(self, x, out=None):
    if out is None:
        out = self.range.zero()
        for (i, j, op) in zip(self.ops.row, self.ops.col, self.ops.data):
            out[i] += op(x[j])
    else:
        has_evaluated_row = np.zeros(len(self.range), dtype=bool)
        for (i, j, op) in zip(self.ops.row, self.ops.col, self.ops.data):
            if not has_evaluated_row[i]:
                op(x[j], out=out[i])
            else:
                out[i] += op(x[j])
            has_evaluated_row[i] = True
        for (i, evaluated) in enumerate(has_evaluated_row):
            if not evaluated:
                out[i].set_zero()
    return out

