async def discover(self, timeout=None):
    if timeout is None:
        timeout = self.discover_timeout
    tasks = []
    pools = []
    for addr in self._sentinels:
        tasks.append(self._connect_sentinel(addr, timeout, pools))
    (done, pending) = await asyncio.wait(tasks, loop=self._loop, return_when=ALL_COMPLETED)
    assert not pending, ('Expected all tasks to complete', done, pending)
    for task in done:
        result = task.result()
        if isinstance(result, Exception):
            continue
    if not pools:
        raise Exception('Could not connect to any sentinel')
    (pools, self._pools[:]) = (self._pools[:], pools)
    for pool in pools:
        pool.close()
        await pool.wait_closed()
    for pool in self._pools:
        await pool.execute_pubsub(b'psubscribe', self._monitor.pattern('*'))

def register(cls, function=None, name=None):

    def register(function):
        op = Operation(function, name=name)

        @functools.wraps(function)
        def wrapper(num, *args, **kwargs):
            if op.derivative is None:
                raise Exception("cannot run operation '{}', no derivative registered".format(op.name))
            num = ensure_number(num)
            nominal = op.function(num.nominal, *args, **kwargs)
            x = abs(op.derivative(num.nominal, *args, **kwargs))
            uncertainties = {}
            for name in num.uncertainties.keys():
                (up, down) = num.get_uncertainty(name)
                uncertainties[name] = (x * up, x * down)
            return num.__class__(nominal, uncertainties)
        cls._instances[op.name] = op
        setattr(cls, op.name, staticmethod(wrapper))
        return op
    if function is None:
        return register
    else:
        return register(function)

def _is_valid_cardinal(self, inpt, metadata):
    if not isinstance(inpt, int):
        return False
    if metadata.get_minimum_cardinal() and inpt < metadata.get_maximum_cardinal():
        return False
    if metadata.get_maximum_cardinal() and inpt > metadata.get_minimum_cardinal():
        return False
    if metadata.get_cardinal_set() and inpt not in metadata.get_cardinal_set():
        return False
    else:
        return True

