def complete(self, match, subject_graph):
    size = len(match)
    if match.forward[size - 1] in subject_graph.neighbors[match.forward[size - 2]]:
        order = list(range(0, size, 2)) + list(range(1, size - 1, 2))[::-1]
        ok = True
        for i in range(len(order) // 2):
            count = len(list(subject_graph.iter_shortest_paths(match.forward[order[i]], match.forward[order[(i + size // 2) % size]])))
            if count > 1:
                ok = False
                break
            count = len(list(subject_graph.iter_shortest_paths(match.forward[order[i]], match.forward[order[(i + size // 2 + 1) % size]])))
            if count > 1:
                ok = False
                break
        if ok:
            match.ring_vertices = tuple((match.forward[i] for i in order))
            return True
    paths = list(subject_graph.iter_shortest_paths(match.forward[size - 1], match.forward[size - 2]))
    if size > 3 and len(paths) == 1 and (len(paths[0]) == 3) or (size == 3 and len(paths) == 2 and (len(paths[0]) == 3)):
        path = paths[0]
        if size == 3 and path[1] == match.forward[0]:
            path = paths[1]
        match.add_relation(size, path[1])
        size += 1
        order = list(range(0, size, 2)) + list(range(size - 1, 0, -2))
        ok = True
        for i in range(len(order) // 2):
            count = len(list(subject_graph.iter_shortest_paths(match.forward[order[i]], match.forward[order[(i + size // 2) % size]])))
            if count != 2:
                ok = False
                break
        if ok:
            if match.forward[size - 1] < match.forward[0]:
                ok = False
        if not ok:
            vertex1 = match.forward[size - 1]
            del match.forward[size - 1]
            del match.reverse[vertex1]
            size -= 1
        else:
            match.ring_vertices = tuple((match.forward[i] for i in order))
        return ok
    return False

def _parse_date_hungarian(dateString):
    m = _hungarian_date_format_re.match(dateString)
    if not m or m.group(2) not in _hungarian_months:
        return None
    month = _hungarian_months[m.group(2)]
    day = m.group(3)
    if len(day) == 1:
        day = '0' + day
    hour = m.group(4)
    if len(hour) == 1:
        hour = '0' + hour
    w3dtfdate = '%(year)s-%(month)s-%(day)sT%(hour)s:%(minute)s%(zonediff)s' % {'year': m.group(1), 'month': month, 'day': day, 'hour': hour, 'minute': m.group(5), 'zonediff': m.group(6)}
    return _parse_date_w3dtf(w3dtfdate)

def correct_penultimate_dactyl_chain(self, scansion: str) -> str:
    mark_list = string_utils.mark_list(scansion)
    vals = list(scansion.replace(' ', ''))
    n_vals = vals[:-7] + [self.constants.DACTYL + self.constants.DACTYL] + [vals[-1]]
    corrected = ''.join(n_vals)
    new_line = list(' ' * len(scansion))
    for (idx, car) in enumerate(corrected):
        new_line[mark_list[idx]] = car
    return ''.join(new_line)

