        parsed_doctree[expected_pyfile] = filename
    pypackages = {name + '.py' for name in pypackages}
    return {elem: parsed_doctree[elem] for elem in parsed_doctree if elem not in pypackages}

def cast(self, value, **opts):
    if isinstance(value, self.result_type):
        return value
    if self._is_null(value):
        return None
    try:
        opts_ = self.opts.copy()
        opts_.update(opts)
        return self._cast(value, **opts_)
    except Exception as e:
        if not isinstance(e, ConverterError):
            e = ConverterError(None, exc=e)
        e.converter = self.__class__
        raise e

