def select_segment(self, segs, segs_tips, segs_undecided) -> Tuple[int, int]:
    scores_tips = np.zeros((len(segs), 4))
    allindices = np.arange(self._adata.shape[0], dtype=int)
    for (iseg, seg) in enumerate(segs):
        if segs_tips[iseg][0] == -1:
            continue
        if not isinstance(self.distances_dpt, OnFlySymMatrix):
            Dseg = self.distances_dpt[np.ix_(seg, seg)]
        else:
            Dseg = self.distances_dpt.restrict(seg)
        third_maximizer = None
        if segs_undecided[iseg]:
            for jseg in range(len(segs)):
                if jseg != iseg:
                    for itip in range(2):
                        if self.distances_dpt[segs_tips[jseg][1], segs_tips[iseg][itip]] < 0.5 * self.distances_dpt[segs_tips[iseg][~itip], segs_tips[iseg][itip]]:
                            third_maximizer = itip
        tips = [np.where(allindices[seg] == tip)[0][0] for tip in segs_tips[iseg]]
        dseg = Dseg[tips[0]] + Dseg[tips[1]]
        if not np.isfinite(dseg).any():
            continue
        third_tip = np.argmax(dseg)
        if third_maximizer is not None:
            dseg += Dseg[third_tip]
            fourth_tip = np.argmax(dseg)
            if fourth_tip != tips[0] and fourth_tip != third_tip:
                tips[1] = fourth_tip
                dseg -= Dseg[tips[1]]
            else:
                dseg -= Dseg[third_tip]
        tips3 = np.append(tips, third_tip)
        score = dseg[tips3[2]] / Dseg[tips3[0], tips3[1]]
        score = len(seg) if self.choose_largest_segment else score
        logg.m('    group', iseg, 'score', score, 'n_points', len(seg), '(too small)' if len(seg) < self.min_group_size else '', v=4)
        if len(seg) <= self.min_group_size:
            score = 0
        scores_tips[iseg, 0] = score
        scores_tips[iseg, 1:] = tips3
    iseg = np.argmax(scores_tips[:, 0])
    if scores_tips[iseg, 0] == 0:
        return (-1, None)
    tips3 = scores_tips[iseg, 1:].astype(int)
    return (iseg, tips3)

def eval(expr, parser='pandas', engine=None, truediv=True, local_dict=None, global_dict=None, resolvers=(), level=0, target=None, inplace=False):
    from pandas.core.computation.expr import Expr
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if isinstance(expr, str):
        _check_expression(expr)
        exprs = [e.strip() for e in expr.splitlines() if e.strip() != '']
    else:
        exprs = [expr]
    multi_line = len(exprs) > 1
    if multi_line and target is None:
        raise ValueError('multi-line expressions are only valid in the context of data, use DataFrame.eval')
    ret = None
    first_expr = True
    target_modified = False
    for expr in exprs:
        expr = _convert_expression(expr)
        engine = _check_engine(engine)
        _check_parser(parser)
        _check_resolvers(resolvers)
        _check_for_locals(expr, level, parser)
        env = _ensure_scope(level + 1, global_dict=global_dict, local_dict=local_dict, resolvers=resolvers, target=target)
        parsed_expr = Expr(expr, engine=engine, parser=parser, env=env, truediv=truediv)
        eng = _engines[engine]
        eng_inst = eng(parsed_expr)
        ret = eng_inst.evaluate()
        if parsed_expr.assigner is None:
            if multi_line:
                raise ValueError('Multi-line expressions are only valid if all expressions contain an assignment')
            elif inplace:
                raise ValueError('Cannot operate inplace if there is no assignment')
        assigner = parsed_expr.assigner
        if env.target is not None and assigner is not None:
            target_modified = True
            if not inplace and first_expr:
                try:
                    target = env.target.copy()
                except AttributeError:
                    raise ValueError('Cannot return a copy of the target')
            else:
                target = env.target
            try:
                with warnings.catch_warnings(record=True):
                    target[assigner] = ret
            except (TypeError, IndexError):
                raise ValueError('Cannot assign expression output to target')
            if not resolvers:
                resolvers = ({assigner: ret},)
            else:
                for resolver in resolvers:
                    if assigner in resolver:
                        resolver[assigner] = ret
                        break
                else:
                    resolvers += ({assigner: ret},)
            ret = None
            first_expr = False
    if inplace is False:
        return target if target_modified else ret

