def get_current(self, item=None, raw=False, start=None, end=None):
    item_indexer = slice(None)
    if item:
        item_indexer = self.items.get_loc(item)
    start_index = self._start_index
    end_index = self._pos
    where = slice(start_index, end_index)
    current_dates = self.date_buf[where]

    def convert_datelike_to_long(dt):
        if isinstance(dt, pd.Timestamp):
            return dt.asm8
        if isinstance(dt, datetime.datetime):
            return np.datetime64(dt)
        return dt
    if start:
        start = convert_datelike_to_long(start)
        start_index += current_dates.searchsorted(start)
    if end:
        end = convert_datelike_to_long(end)
        _end = current_dates.searchsorted(end, 'right')
        end_index -= len(current_dates) - _end
    where = slice(start_index, end_index)
    values = self.buffer.values[item_indexer, where, :]
    current_dates = self.date_buf[where]
    if raw:
        return values.copy()
    major_axis = pd.DatetimeIndex(deepcopy(current_dates), tz='utc')
    if values.ndim == 3:
        return pd.Panel(values, self.items, major_axis, self.minor_axis, dtype=self.dtype)
    elif values.ndim == 2:
        return pd.DataFrame(values, major_axis, self.minor_axis, dtype=self.dtype)

def update_log_entry(self, log_entry_form):
    collection = JSONClientValidated('logging', collection='LogEntry', runtime=self._runtime)
    if not isinstance(log_entry_form, ABCLogEntryForm):
        raise errors.InvalidArgument('argument type is not an LogEntryForm')
    if not log_entry_form.is_for_update():
        raise errors.InvalidArgument('the LogEntryForm is for update only, not create')
    try:
        if self._forms[log_entry_form.get_id().get_identifier()] == UPDATED:
            raise errors.IllegalState('log_entry_form already used in an update transaction')
    except KeyError:
        raise errors.Unsupported('log_entry_form did not originate from this session')
    if not log_entry_form.is_valid():
        raise errors.InvalidArgument('one or more of the form elements is invalid')
    collection.save(log_entry_form._my_map)
    self._forms[log_entry_form.get_id().get_identifier()] = UPDATED
    return objects.LogEntry(osid_object_map=log_entry_form._my_map, runtime=self._runtime, proxy=self._proxy)

def metric_calculator(tpf, fpf, P, N, metric_list, anal=True):
    metrics = {}
    for vs_metric in [float(x) for x in metric_list if '.' in x]:
        if N >= 1 / vs_metric:
            metrics[round(vs_metric * N)] = [vs_metric, 0]
    for vs_metric in [x for x in metric_list if '.' not in x]:
        metrics[vs_metric] = [vs_metric, 0, 0, 0]
    metrics['AUC'][1] = 0
    for index in range(len(tpf)):
        if N * fpf[index] in metrics.keys() and N * fpf[index] > 0:
            ef = tpf[index] / fpf[index]
            metrics[N * fpf[index]][1] = ef
        if fpf[index] != fpf[index - 1]:
            metrics['AUC'][1] = tpf[index] + metrics['AUC'][1]
    metrics['AUC'][1] = metrics['AUC'][1] / N
    reshaped = {}
    for (k, v) in metrics.iteritems():
        if type(v) is float or type(v) is int:
            reshaped[k] = v
        else:
            reshaped[v[0]] = v[1:]
    return reshaped

