def ask_bool(self, question, default=True):
    if self.script.options.yes:
        return True
    elif self.script.options.dry_run or not self.script.options.interactive:
        return default
    else:
        choice = '*'
        while choice not in 'YNAQ':
            choice = raw_input('%s? [%s)es, %s)o, a)ll yes, q)uit]: ' % (fmt.to_console(question), 'yY'[int(default)], 'Nn'[int(default)]))
            choice = choice[:1].upper() or 'NY'[int(default)]
        if choice == 'Q':
            self.quit()
        if choice == 'A':
            self.script.options.yes = True
            choice = 'Y'
        return choice == 'Y'

def get_vlan_from_query_reply(self, reply, vsiid, mac):
    (hints_ret, fail_reason) = self.check_hints(reply)
    if not hints_ret:
        LOG.error('Incorrect hints found %s', reply)
        return (constants.INVALID_VLAN, fail_reason)
    (check_filter, fail_reason) = self.check_filter_validity(reply, 'filter')
    if not check_filter:
        return (constants.INVALID_VLAN, fail_reason)
    try:
        (verify_flag, fail_reason) = self.crosscheck_query_vsiid_mac(reply, vsiid, mac)
        if not verify_flag:
            return (constants.INVALID_VLAN, fail_reason)
        filter_val = reply.partition('filter')[2]
        len_fil = len(filter_val)
        vlan_val = filter_val[4:len_fil].split('-')[0]
        vlan = int(vlan_val)
    except ValueError:
        fail_reason = vdp_const.format_failure_reason % reply
        LOG.error('%s', fail_reason)
        return (constants.INVALID_VLAN, fail_reason)
    return (vlan, None)

def hash_nanopub(nanopub: Mapping[str, Any]) -> str:
    hash_list = []
    hash_list.append(nanopub['nanopub']['type'].get('name', '').strip())
    hash_list.append(nanopub['nanopub']['type'].get('version', '').strip())
    if nanopub['nanopub']['citation'].get('database', False):
        hash_list.append(nanopub['nanopub']['citation']['database'].get('name', '').strip())
        hash_list.append(nanopub['nanopub']['citation']['database'].get('id', '').strip())
    elif nanopub['nanopub']['citation'].get('uri', False):
        hash_list.append(nanopub['nanopub']['citation'].get('uri', '').strip())
    elif nanopub['nanopub']['citation'].get('reference', False):
        hash_list.append(nanopub['nanopub']['citation'].get('reference', '').strip())
    assertions = []
    for assertion in nanopub['nanopub']['assertions']:
        if assertion.get('relation') is None:
            assertion['relation'] = ''
        if assertion.get('object') is None:
            assertion['object'] = ''
        assertions.append(' '.join((assertion['subject'].strip(), assertion.get('relation', '').strip(), assertion.get('object', '').strip())).strip())
    assertions = sorted(assertions)
    hash_list.extend(assertions)
    annotations = []
    for anno in nanopub['nanopub']['annotations']:
        annotations.append(' '.join((anno.get('type', '').strip(), anno.get('id', '').strip())).strip())
    annotations = sorted(annotations)
    hash_list.extend(annotations)
    np_string = ' '.join([l.lower() for l in hash_list])
    return '{:x}'.format(CityHash64(np_string))

