def include(self, spec, *, basePath=None, operationId_mapping=None, name=None):
    data = self._file_loader.load(spec)
    if basePath is None:
        basePath = data.get('basePath', '')
    if name is not None:
        d = dict(data)
        d['basePath'] = basePath
        self._swagger_data[name] = d
    swagger_data = {k: v for (k, v) in data.items() if k != 'paths'}
    swagger_data['basePath'] = basePath
    for (url, methods) in data.get('paths', {}).items():
        url = basePath + url
        methods = dict(methods)
        location_name = methods.pop(self.NAME, None)
        parameters = methods.pop('parameters', [])
        for (method, body) in methods.items():
            if method == self.VIEW:
                view = utils.import_obj(body)
                view.add_routes(self, prefix=url, encoding=self._encoding)
                continue
            body = dict(body)
            if parameters:
                body['parameters'] = parameters + body.get('parameters', [])
            handler = body.pop(self.HANDLER, None)
            name = location_name or handler
            if not handler:
                op_id = body.get('operationId')
                if op_id and operationId_mapping:
                    handler = operationId_mapping.get(op_id)
                    if handler:
                        name = location_name or op_id
            if handler:
                validate = body.pop(self.VALIDATE, self._default_validate)
                self.add_route(method.upper(), utils.url_normolize(url), handler=handler, name=name, swagger_data=body, validate=validate)
    self._swagger_data[basePath] = swagger_data
    for route in self.routes():
        if isinstance(route, SwaggerRoute) and (not route.is_built):
            route.build_swagger_data(self._file_loader)

def set_border_attr(self, attr, value, borders):
    selection = self.grid.selection
    if not selection:
        selection.cells.append(self.grid.actions.cursor[:2])
    if 'inner' in borders:
        if 'top' in borders:
            adj_selection = selection + (-1, 0)
            self.set_attr(attr + '_bottom', value, adj_selection)
        if 'bottom' in borders:
            self.set_attr(attr + '_bottom', value)
        if 'left' in borders:
            adj_selection = selection + (0, -1)
            self.set_attr(attr + '_right', value, adj_selection)
        if 'right' in borders:
            self.set_attr(attr + '_right', value)
    else:
        (bbox_tl, bbox_lr) = selection.get_bbox()
        if 'top' in borders:
            adj_selection = Selection([bbox_tl], [(bbox_tl[0], bbox_lr[1])], [], [], []) + (-1, 0)
            self.set_attr(attr + '_bottom', value, adj_selection)
        if 'bottom' in borders:
            adj_selection = Selection([(bbox_lr[0], bbox_tl[1])], [bbox_lr], [], [], [])
            self.set_attr(attr + '_bottom', value, adj_selection)
        if 'left' in borders:
            adj_selection = Selection([bbox_tl], [(bbox_lr[0], bbox_tl[1])], [], [], []) + (0, -1)
            self.set_attr(attr + '_right', value, adj_selection)
        if 'right' in borders:
            adj_selection = Selection([(bbox_tl[0], bbox_lr[1])], [bbox_lr], [], [], [])
            self.set_attr(attr + '_right', value, adj_selection)

def enrollments(db, uuid=None, organization=None, from_date=None, to_date=None):
    if not from_date:
        from_date = MIN_PERIOD_DATE
    if not to_date:
        to_date = MAX_PERIOD_DATE
    if from_date < MIN_PERIOD_DATE or from_date > MAX_PERIOD_DATE:
        raise InvalidValueError("'from_date' %s is out of bounds" % str(from_date))
    if to_date < MIN_PERIOD_DATE or to_date > MAX_PERIOD_DATE:
        raise InvalidValueError("'to_date' %s is out of bounds" % str(to_date))
    if from_date and to_date and (from_date > to_date):
        raise InvalidValueError("'from_date' %s cannot be greater than %s" % (from_date, to_date))
    enrollments = []
    with db.connect() as session:
        query = session.query(Enrollment).join(UniqueIdentity, Organization).filter(Enrollment.start >= from_date, Enrollment.end <= to_date)
        if uuid:
            uidentity = find_unique_identity(session, uuid)
            if not uidentity:
                raise NotFoundError(entity=uuid)
            query = query.filter(Enrollment.uidentity == uidentity)
        if organization:
            org = find_organization(session, organization)
            if not org:
                raise NotFoundError(entity=organization)
            query = query.filter(Enrollment.organization == org)
        enrollments = query.order_by(UniqueIdentity.uuid, Organization.name, Enrollment.start, Enrollment.end).all()
        session.expunge_all()
    return enrollments

