def parse_implicit_response(uri, state=None, scope=None):
    if not is_secure_transport(uri):
        raise InsecureTransportError()
    fragment = urlparse.urlparse(uri).fragment
    params = dict(urlparse.parse_qsl(fragment, keep_blank_values=True))
    for key in ('expires_in',):
        if key in params:
            params[key] = int(params[key])
    if 'scope' in params:
        params['scope'] = scope_to_list(params['scope'])
    if 'expires_in' in params:
        params['expires_at'] = time.time() + int(params['expires_in'])
    if state and params.get('state', None) != state:
        raise ValueError('Mismatching or missing state in params.')
    params = OAuth2Token(params, old_scope=scope)
    validate_token_parameters(params)
    return params

def route_acl(self, *acl, **options):

    def _route_acl(func):
        func.__acl__ = acl

        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            permission = 'http.' + request.method.lower()
            local_opts = options.copy()
            local_opts.setdefault('default', current_app.config['ACL_ROUTE_DEFAULT_STATE'])
            self.assert_can(permission, func, **local_opts)
            return func(*args, **kwargs)
        return wrapped
    return _route_acl

def operation(self, other, function, **kwargs):
    result = TimeSeries(**kwargs)
    if isinstance(other, TimeSeries):
        for (time, value) in self:
            result[time] = function(value, other[time])
        for (time, value) in other:
            result[time] = function(self[time], value)
    else:
        for (time, value) in self:
            result[time] = function(value, other)
    return result

