def make_conditional(self, request_or_environ, accept_ranges=False, complete_length=None):
    environ = _get_environ(request_or_environ)
    if environ['REQUEST_METHOD'] in ('GET', 'HEAD'):
        if 'date' not in self.headers:
            self.headers['Date'] = http_date()
        accept_ranges = _clean_accept_ranges(accept_ranges)
        is206 = self._process_range_request(environ, complete_length, accept_ranges)
        if not is206 and (not is_resource_modified(environ, self.headers.get('etag'), None, self.headers.get('last-modified'))):
            if parse_etags(environ.get('HTTP_IF_MATCH')):
                self.status_code = 412
            else:
                self.status_code = 304
        if self.automatically_set_content_length and 'content-length' not in self.headers:
            length = self.calculate_content_length()
            if length is not None:
                self.headers['Content-Length'] = length
    return self

def _update_states(self, uid, states):
    if self.controllers[uid]:
        if len(states) == 14:
            old_states = self.controllers[uid][2]
            if old_states != states:
                for key in range(14):
                    if int(old_states[key]) > int(states[key]):
                        e = Event(uid, E_KEYUP, key)
                        self.queue.put_nowait(e)
                    elif int(old_states[key]) < int(states[key]):
                        e = Event(uid, E_KEYDOWN, key)
                        self.queue.put_nowait(e)
            self.controllers[uid][2] = states
        self.controllers[uid][3] = time.time()

