def init_argparser(self, argparser):

    def prepare_argparser():
        if argparser in self.argparser_details:
            return False
        result = self.argparser_details[argparser] = ArgumentParserDetails({}, {}, {})
        return result

    def to_module_attr(ep):
        return '%s:%s' % (ep.module_name, '.'.join(ep.attrs))

    def register(name, runtime, entry_point):
        subparser = commands.add_parser(name, help=inst.description)
        subparser.description = inst.description
        setattr(subparser, ATTR_ROOT_PKG, getattr(argparser, ATTR_ROOT_PKG, self.package_name))
        subp_info = []
        subp_info.extend(getattr(argparser, ATTR_INFO, []))
        subp_info.append((subparser.prog, entry_point.dist))
        setattr(subparser, ATTR_INFO, subp_info)
        try:
            try:
                runtime.init_argparser(subparser)
            except RuntimeError as e:
                frame = currentframe()
                if not frame or 'maximum recursion depth' not in str(e.args):
                    raise
                if not isinstance(runtime, Runtime) or type(runtime).entry_point_load_validated.__code__ is Runtime.entry_point_load_validated.__code__:
                    raise
                cls = type(runtime)
                logger.critical("Runtime subclass at entry_point '%s' has override 'entry_point_load_validated' without filtering out its parent classes; this can be addressed by calling super(%s.%s, self).entry_point_load_validated(entry_point) in its implementation, or simply don't override that method to avoid infinite recursion.", entry_point, cls.__module__, cls.__name__)
                exc = RuntimeError("%r has an invalid 'entry_point_load_validated' implementation: insufficient protection against infinite recursion into self not provided" % runtime)
                exc.__suppress_context__ = True
                raise exc
        except Exception as e:
            self.log_debug_error("cannot register entry_point '%s' from '%s' as a subcommand to '%s': %s: %s", entry_point, entry_point.dist, argparser.prog, e.__class__.__name__, e)
            commands._choices_actions.pop()
            commands._name_parser_map.pop(name)
        else:
            subparsers[name] = subparser
            runtimes[name] = runtime
            entry_points[name] = entry_point
    details = prepare_argparser()
    if not details:
        logger.debug('argparser %r has already been initialized against runner %r', argparser, self)
        return
    (subparsers, runtimes, entry_points) = details
    super(Runtime, self).init_argparser(argparser)
    commands = argparser.add_subparsers(dest=self.action_key, metavar='<command>')
    commands.required = False
    for entry_point in self.iter_entry_points():
        inst = self.entry_point_load_validated(entry_point)
        if not inst:
            continue
        if entry_point.name in runtimes:
            reg_ep = entry_points[entry_point.name]
            reg_rt = runtimes[entry_point.name]
            if reg_rt is inst:
                logger.debug("duplicated registration of command '%s' via entry point '%s' ignored; registered '%s', confict '%s'", entry_point.name, entry_point, reg_ep.dist, entry_point.dist)
                continue
            logger.error("a calmjs runtime command named '%s' already registered.", entry_point.name)
            logger.info('conflicting entry points are:')
            logger.info("'%s' from '%s' (registered)", reg_ep, reg_ep.dist)
            logger.info("'%s' from '%s' (conflict)", entry_point, entry_point.dist)
            name = to_module_attr(entry_point)
            if name in runtimes:
                if runtimes[name] is not inst:
                    logger.critical("'%s' is already registered but points to a completely different instance; please try again with verbose logging and note which packages are reported as conflicted; alternatively this is a forced situation where this Runtime instance has been used or initialized improperly.", name)
                else:
                    logger.debug("fallback command '%s' is already registered.", name)
                continue
            logger.error("falling back to using full instance path '%s' as command name, also registering alias for registered command", name)
            register(to_module_attr(reg_ep), reg_rt, reg_ep)
        else:
            name = entry_point.name
        register(name, inst, entry_point)

def read_mtx(filename: PathLike, dtype: str='float32') -> AnnData:
    from scipy.io import mmread
    X = mmread(fspath(filename)).astype(dtype)
    from scipy.sparse import csr_matrix
    X = csr_matrix(X)
    return AnnData(X, dtype=dtype)

def run_gap_k_selection(data, k_min=1, k_max=50, B=5, skip=5, **kwargs):
    if k_min == k_max:
        return k_min
    gap_vals = []
    sk_vals = []
    k_range = list(range(k_min, k_max, skip))
    min_k = 0
    min_i = 0
    for (i, k) in enumerate(k_range):
        km = KMeans(k)
        clusters = km.fit_predict(data)
        (gap, sk) = calculate_gap(data, clusters, km, B=B)
        if len(gap_vals) > 1:
            if gap_vals[-1] >= gap - (skip + 1) * sk:
                min_i = i
                min_k = k_range[i - 1]
                break
        gap_vals.append(gap)
        sk_vals.append(sk)
    if min_k == 0:
        min_k = k_max
    if skip == 1:
        return (min_k, gap_vals, sk_vals)
    gap_vals = []
    sk_vals = []
    for k in range(min_k - skip, min_k + skip):
        km = KMeans(k)
        clusters = km.fit_predict(data)
        (gap, sk) = calculate_gap(data, clusters, km, B=B)
        if len(gap_vals) > 1:
            if gap_vals[-1] >= gap - sk:
                min_k = k - 1
                return (min_k, gap_vals, sk_vals)
        gap_vals.append(gap)
        sk_vals.append(sk)
    return (k, gap_vals, sk_vals)

