def from_files(cls, *glyphdata_files):
    name_mapping = {}
    alt_name_mapping = {}
    production_name_mapping = {}
    for glyphdata_file in glyphdata_files:
        glyph_data = xml.etree.ElementTree.parse(glyphdata_file).getroot()
        for glyph in glyph_data:
            glyph_name = glyph.attrib['name']
            glyph_name_alternatives = glyph.attrib.get('altNames')
            glyph_name_production = glyph.attrib.get('production')
            name_mapping[glyph_name] = glyph.attrib
            if glyph_name_alternatives:
                alternatives = glyph_name_alternatives.replace(' ', '').split(',')
                for glyph_name_alternative in alternatives:
                    alt_name_mapping[glyph_name_alternative] = glyph.attrib
            if glyph_name_production:
                production_name_mapping[glyph_name_production] = glyph.attrib
    return cls(name_mapping, alt_name_mapping, production_name_mapping)

def build_knowledge_graph(self, json_ontology: dict) -> List:
    nested_docs = list()
    if json_ontology:
        for key in list(json_ontology):
            j_values = json_ontology[key]
            if not isinstance(j_values, list):
                j_values = [j_values]
            for j_value in j_values:
                if not isinstance(j_value, dict):
                    if self.kg:
                        if key not in ['doc_id', 'uri']:
                            self.kg.add_value(key, value=j_value)
                else:
                    "Now we have to create a nested document, assign it a doc_id and \n                           add the doc_id to parent document's knowledge graph"
                    child_doc_id = None
                    if 'uri' in j_value:
                        child_doc_id = j_value['uri']
                    elif 'doc_id' in j_value:
                        child_doc_id = j_value['doc_id']
                    child_doc = Document(self.etk, cdr_document=dict(), mime_type='json', url='')
                    nested_docs.extend(child_doc.build_knowledge_graph(j_value))
                    if not child_doc_id:
                        child_doc_id = Utility.create_doc_id_from_json(child_doc.kg._kg)
                    if self.kg:
                        self.kg.add_value(key, value=child_doc_id)
                    child_doc.cdr_document['doc_id'] = child_doc_id
                    nested_docs.append(child_doc)
    return nested_docs

