def find_class(self, cls):
    for doc_cls in self.classes():
        if cls is doc_cls.cls:
            return doc_cls
    for module in self.submodules():
        doc_cls = module.find_class(cls)
        if not isinstance(doc_cls, External):
            return doc_cls
    return External('%s.%s' % (cls.__module__, cls.__name__))

def publish(self, topic, messages, key=None):
    if not isinstance(messages, list):
        messages = [messages]
    first = True
    success = False
    if key is None:
        key = int(time.time() * 1000)
    messages = [encodeutils.to_utf8(m) for m in messages]
    key = bytes(str(key), 'utf-8') if PY3 else str(key)
    while not success:
        try:
            self._producer.send_messages(topic, key, *messages)
            success = True
        except Exception:
            if first:
                log.warn('Failed send on topic {}, clear metadata and retry'.format(topic))
                self._kafka.reset_topic_metadata(topic)
                first = False
                continue
            log.exception('Error publishing to {} topic.'.format(topic))
            raise

