def compile_args(args, kwargs, sep, prefix):
    processed_args = []
    encode = encode_to_py3bytes_or_py2str
    for arg in args:
        if isinstance(arg, (list, tuple)):
            if isinstance(arg, GlobResults) and (not arg):
                arg = [arg.path]
            for sub_arg in arg:
                processed_args.append(encode(sub_arg))
        elif isinstance(arg, dict):
            processed_args += aggregate_keywords(arg, sep, prefix, raw=True)
        else:
            processed_args.append(encode(arg))
    processed_args += aggregate_keywords(kwargs, sep, prefix)
    return processed_args

def _build(self, inputs, prev_state, **kwargs):
    current_input = inputs
    next_states = []
    outputs = []
    recurrent_idx = 0
    concatenate = lambda *args: tf.concat(args, axis=-1)
    for (i, core) in enumerate(self._cores):
        if self._skip_connections and i > 0:
            current_input = nest.map_structure(concatenate, inputs, current_input)
        if self._is_recurrent_list[i]:
            (current_input, next_state) = core(current_input, prev_state[recurrent_idx], **kwargs)
            next_states.append(next_state)
            recurrent_idx += 1
        else:
            current_input = core(current_input, **kwargs)
        if self._skip_connections:
            outputs.append(current_input)
    if self._skip_connections and self._concat_final_output_if_skip:
        output = nest.map_structure(concatenate, *outputs)
    else:
        output = current_input
    self._last_output_size = _get_shape_without_batch_dimension(output)
    return (output, tuple(next_states))

