def split_bel_stmt(stmt: str, line_num) -> tuple:
    m = re.match(f'^(.*?\\))\\s+([a-zA-Z=\\->\\|:]+)\\s+([\\w(]+.*?)$', stmt, flags=0)
    if m:
        return (m.group(1), m.group(2), m.group(3))
    else:
        log.info(f'Could not parse bel statement into components at line number: {line_num} assertion: {stmt}')
        return (stmt, None, None)

def get_context(lines, backwards=False):
    tex_tag = re.compile('.*\\\\(\\w+).*')
    sentence = re.compile('(?<=[.?!])[\\s]+(?=[A-Z])')
    context = []
    word_list = lines.split()
    if backwards:
        word_list.reverse()
    for word in word_list:
        if len(context) >= CFG_PLOTEXTRACTOR_CONTEXT_WORD_LIMIT:
            break
        match = tex_tag.match(word)
        if match and match.group(1) in CFG_PLOTEXTRACTOR_DISALLOWED_TEX:
            if backwards:
                temp_word = ''
                while len(context):
                    temp_word = context.pop()
                    if '}' in temp_word:
                        break
            break
        context.append(word)
    if backwards:
        context.reverse()
    text = ' '.join(context)
    sentence_list = sentence.split(text)
    if backwards:
        sentence_list.reverse()
    if len(sentence_list) > CFG_PLOTEXTRACTOR_CONTEXT_SENTENCE_LIMIT:
        return ' '.join(sentence_list[:CFG_PLOTEXTRACTOR_CONTEXT_SENTENCE_LIMIT])
    else:
        return ' '.join(sentence_list)

