def tag(self, tokens):
    tags = []
    for token in tokens:
        normalized = self.lexicon[token].normalized
        for (regex, tag) in self.regexes:
            if regex.match(normalized):
                tags.append((token, tag))
                break
        else:
            tags.append((token, None))
    return tags

def get_option_chain(self, code, start=None, end=None, option_type=OptionType.ALL, option_cond_type=OptionCondType.ALL):
    if code is None or is_str(code) is False:
        error_str = ERROR_STR_PREFIX + 'the type of code param is wrong'
        return (RET_ERROR, error_str)
    (ret_code, msg, start, end) = normalize_start_end_date(start, end, delta_days=29, default_time_end='00:00:00', prefer_end_now=False)
    if ret_code != RET_OK:
        return (ret_code, msg)
    query_processor = self._get_sync_query_processor(OptionChain.pack_req, OptionChain.unpack_rsp)
    kargs = {'code': code, 'conn_id': self.get_sync_conn_id(), 'start_date': start, 'end_date': end, 'option_cond_type': option_cond_type, 'option_type': option_type}
    (ret_code, msg, option_chain_list) = query_processor(**kargs)
    if ret_code == RET_ERROR:
        return (ret_code, msg)
    col_list = ['code', 'name', 'lot_size', 'stock_type', 'option_type', 'stock_owner', 'strike_time', 'strike_price', 'suspension', 'stock_id']
    option_chain = pd.DataFrame(option_chain_list, columns=col_list)
    option_chain.sort_values(by=['strike_time', 'strike_price'], axis=0, ascending=True, inplace=True)
    option_chain.index = range(len(option_chain))
    return (RET_OK, option_chain)

