        date = ''
    else:
        (mod, ghfile) = ('cals10k', '')
    if '-age' in sys.argv:
        ind = sys.argv.index('-age')
        date = float(sys.argv[ind + 1])
    if '-alt' in sys.argv:
        ind = sys.argv.index('-alt')
        alt = float(sys.argv[ind + 1])
