def find_in_sorted_index(dts, dt):
    ix = dts.searchsorted(dt)
    if ix == len(dts) or dts[ix] != dt:
        raise LookupError('{dt} is not in {dts}'.format(dt=dt, dts=dts))
    return ix

def this_and_prev(iterable):
    try:
        item = next(iterable)
        while True:
            next_item = next(iterable)
            yield (item, next_item)
            item = next_item
    except StopIteration:
        return

def pop(self):
    data = self.backend.pop(self.queue_name)
    if data:
        task = self.task_class.deserialize(data)
        return self.execute(task)

def get_last_traded_dt(self, asset, dt):
    sid_ix = self.sids.searchsorted(asset.sid)
    dt_limit_ix = self.dates.searchsorted(dt.asm8, side='right')
    nonzero_volume_ixs = np.ravel(np.nonzero(self._country_group[DATA][VOLUME][sid_ix, :dt_limit_ix]))
    if len(nonzero_volume_ixs) == 0:
        return pd.NaT
    return pd.Timestamp(self.dates[nonzero_volume_ixs][-1], tz='UTC')

def calculate_totals(self, children, local_children=None):
    for (field, local_field) in (('recursive', 'calls'), ('cumulative', 'local')):
        values = []
        for child in children:
            if isinstance(child, PStatGroup) or not self.LOCAL_ONLY:
                values.append(getattr(child, field, 0))
            elif isinstance(child, PStatRow) and self.LOCAL_ONLY:
                values.append(getattr(child, local_field, 0))
        value = sum(values)
        setattr(self, field, value)
    if self.recursive:
        self.cumulativePer = self.cumulative / float(self.recursive)
    else:
        self.recursive = 0
    if local_children:
        for field in ('local', 'calls'):
            value = sum([getattr(child, field, 0) for child in children])
            setattr(self, field, value)
        if self.calls:
            self.localPer = self.local / self.calls
    else:
        self.local = 0
        self.calls = 0
        self.localPer = 0

def sar(computation: BaseComputation) -> None:
    (shift_length, value) = computation.stack_pop(num_items=2, type_hint=constants.UINT256)
    value = unsigned_to_signed(value)
    if shift_length >= 256:
        result = 0 if value >= 0 else constants.UINT_255_NEGATIVE_ONE
    else:
        result = value >> shift_length & constants.UINT_256_MAX
    computation.stack_push(result)

