def set_iscsi_boot_info(self, mac, target_name, lun, ip_address, port='3260', auth_method=None, username=None, password=None):
    LOG.warning("'set_iscsi_boot_info' is deprecated. The 'MAC' parameterpassed in is ignored. Use 'set_iscsi_info' instead.")
    return self._call_method('set_iscsi_info', target_name, lun, ip_address, port, auth_method, username, password)

def options(self, parser, env=os.environ):
    parser.add_option('--%s-record' % self.name, action='store', metavar='FILE', dest='record_filename', help='Record actions to this file.')
    parser.add_option('--%s-playback' % self.name, action='store', metavar='FILE', dest='playback_filename', help='Playback actions from this file.')

def get_resource(self, path):
    response = self._http_request(path)
    try:
        return response.json()
    except ValueError:
        raise exception.ServiceException('Invalid service response.')

def funda(self, fields=None, min_volume=0, min_discount=0, ignore_nodown=False, forever=False):
    if fields is None:
        fields = []
    self.__funda_url = self.__funda_url.format(ctime=int(time.time()))
    rep = requests.get(self.__funda_url)
    fundajson = json.loads(rep.text)
    data = self.formatfundajson(fundajson)
    if min_volume:
        data = {k: data[k] for k in data if float(data[k]['funda_volume']) > min_volume}
    if len(fields):
        data = {k: data[k] for k in data if data[k]['coupon_descr_s'] in ''.join(fields)}
    if ignore_nodown:
        data = {k: data[k] for k in data if data[k]['fund_descr'].find('无下折') == -1}
    if forever:
        data = {k: data[k] for k in data if data[k]['funda_left_year'].find('永续') != -1}
    if min_discount:
        data = {k: data[k] for k in data if float(data[k]['funda_discount_rt'][:-1]) > min_discount}
    self.__funda = data
    return self.__funda

def _verify_download_complete(self):
    if self.actual_bytes_read > self.bytes_to_read:
        raise TooLargeChunkDownloadError(self.actual_bytes_read, self.bytes_to_read, self.local_path)
    elif self.actual_bytes_read < self.bytes_to_read:
        raise PartialChunkDownloadError(self.actual_bytes_read, self.bytes_to_read, self.local_path)

def reinforce(self, **kwargs):
    results = reinforce_grid(self, max_while_iterations=kwargs.get('max_while_iterations', 10), copy_graph=kwargs.get('copy_graph', False), timesteps_pfa=kwargs.get('timesteps_pfa', None), combined_analysis=kwargs.get('combined_analysis', False))
    if not kwargs.get('copy_graph', False):
        self.network.results.measures = 'grid_expansion'
    return results

def ReadSystemConfigurationArtifact(self, system_configuration, session_identifier=CURRENT_SESSION):
    if system_configuration.code_page:
        try:
            self.SetCodepage(system_configuration.code_page)
        except ValueError:
            logger.warning('Unsupported codepage: {0:s}, defaulting to {1:s}'.format(system_configuration.code_page, self._codepage))
    self._hostnames[session_identifier] = system_configuration.hostname
    self.SetValue('keyboard_layout', system_configuration.keyboard_layout)
