def batch_normalization(x, beta, gamma, mean, variance, axes=[1], decay_rate=0.9, eps=1e-05, batch_stat=True, output_stat=False, n_outputs=None):
    from .function_bases import batch_normalization as batch_normalization_base
    n_outputs = 3 if output_stat else 1
    assert batch_stat or not output_stat
    if batch_stat and (mean.parent or variance.parent) is not None:
        raise ValueError('if batch_stat is True, mean and variable must not have a parent function')
    if len(axes) == 1:
        return batch_normalization_base(x, beta, gamma, mean, variance, axes=axes, decay_rate=decay_rate, eps=eps, batch_stat=batch_stat, n_outputs=n_outputs)

    def transpose_and_reshape(x, axes):
        transposed = transpose(x, transpose_axes)
        return (reshape(transposed, [rd(lambda x, y: x * y, transposed.shape[:len(axes)])] + list(transposed.shape[len(axes):])), transposed.shape)

    def inverse_transpose_and_reshape(x, axes, variable_shape):
        un_reshaped = reshape(x, list(variable_shape[:len(axes)] + variable_shape[len(axes):]))
        return transpose(un_reshaped, inv_transpose_axes)

    def get_tranpose_args(ndim, axes):
        transpose_axes = [i for i in list(axes)] + [i for i in range(ndim) if i not in list(axes)]
        inv_transpose_axes = np.argsort(transpose_axes).tolist()
        return (transpose_axes, inv_transpose_axes)
    (transpose_axes, inv_transpose_axes) = get_tranpose_args(len(x.shape), axes)
    (inp, transposed_inp_shape) = transpose_and_reshape(x, axes)
    (beta, transposed_beta_shape) = transpose_and_reshape(beta, axes)
    (gamma, transposed_gamma_shape) = transpose_and_reshape(gamma, axes)
    (mean, transposed_mean_shape) = transpose_and_reshape(mean, axes)
    (variance, transposed_variance_shape) = transpose_and_reshape(variance, axes)
    if n_outputs == 1:
        out = batch_normalization_base(inp, beta, gamma, mean, variance, axes=[0], decay_rate=decay_rate, eps=eps, batch_stat=batch_stat, n_outputs=n_outputs)
        return inverse_transpose_and_reshape(out, axes, transposed_inp_shape)
    (out, mean, variance) = batch_normalization_base(inp, beta, gamma, mean, variance, axes=[0], decay_rate=decay_rate, eps=eps, batch_stat=batch_stat, n_outputs=n_outputs)
    out = inverse_transpose_and_reshape(out, axes, transposed_inp_shape)
    mean = inverse_transpose_and_reshape(mean, axes, transposed_mean_shape)
    variance = inverse_transpose_and_reshape(variance, axes, transposed_variance_shape)
    return (out, mean, variance)

def sort_index(self, axis=0, level=None, ascending=True, inplace=False, kind='quicksort', na_position='last', sort_remaining=True):
    inplace = validate_bool_kwarg(inplace, 'inplace')
    self._get_axis_number(axis)
    index = self.index
    if level is not None:
        (new_index, indexer) = index.sortlevel(level, ascending=ascending, sort_remaining=sort_remaining)
    elif isinstance(index, MultiIndex):
        from pandas.core.sorting import lexsort_indexer
        labels = index._sort_levels_monotonic()
        indexer = lexsort_indexer(labels._get_codes_for_sorting(), orders=ascending, na_position=na_position)
    else:
        from pandas.core.sorting import nargsort
        if ascending and index.is_monotonic_increasing or (not ascending and index.is_monotonic_decreasing):
            if inplace:
                return
            else:
                return self.copy()
        indexer = nargsort(index, kind=kind, ascending=ascending, na_position=na_position)
    indexer = ensure_platform_int(indexer)
    new_index = index.take(indexer)
    new_index = new_index._sort_levels_monotonic()
    new_values = self._values.take(indexer)
    result = self._constructor(new_values, index=new_index)
    if inplace:
        self._update_inplace(result)
    else:
        return result.__finalize__(self)

