def compress_pdf(filepath, output_path, ghostscript_binary):
    if not filepath.endswith(PDF_EXTENSION):
        raise ValueError('Filename must end with .pdf!\n%s does not.' % filepath)
    try:
        file_size = os.stat(filepath).st_size
        if file_size < FILE_SIZE_LOWER_LIMIT:
            LOGGER.info(NOT_COMPRESSING.format(filepath, file_size, FILE_SIZE_LOWER_LIMIT))
            process = subprocess.Popen(['cp', filepath, output_path])
        else:
            LOGGER.info(COMPRESSING.format(filepath))
            process = subprocess.Popen([ghostscript_binary, '-sDEVICE=pdfwrite', '-dCompatabilityLevel=1.4', '-dPDFSETTINGS=/ebook', '-dNOPAUSE', '-dQUIET', '-dBATCH', '-sOutputFile=%s' % output_path, filepath])
    except FileNotFoundError:
        msg = GS_NOT_INSTALLED.format(ghostscript_binary)
        raise FileNotFoundError(msg)
    process.communicate()
    LOGGER.info(FILE_DONE.format(output_path))

def _run_nb_cmd(self, cmd):
    try:
        proc = salt.utils.nb_popen.NonBlockingPopen(cmd, shell=True, stderr=subprocess.PIPE, stdout=subprocess.PIPE)
        while True:
            time.sleep(0.1)
            out = proc.recv()
            err = proc.recv_err()
            rcode = proc.returncode
            if out is None and err is None:
                break
            if err:
                err = self.get_error(err)
            yield (out, err, rcode)
    except Exception:
        yield ('', 'Unknown Error', None)

def early_warning(iterable, name='this generator'):
    nxt = None
    prev = next(iterable)
    while 1:
        try:
            nxt = next(iterable)
        except:
            warning(' {} is now empty'.format(name))
            yield prev
            break
        else:
            yield prev
            prev = nxt

def GDTF(self):
    H = self.H()
    tmp = H / np.sqrt(np.einsum('ia..., aa..., ia..., j... ->ij...', H.conj(), self.c, H, 1 / self.c.diagonal()))
    return np.abs(tmp)

def split_calls(func):

    def wrapper(*args, **kwargs):
        size_limit = 8000
        encoded_url = urllib.urlencode(kwargs)
        if len(encoded_url) > size_limit:
            for (key, value) in kwargs.iteritems():
                if key in ('logical_file_name', 'block_name', 'lumi_list', 'run_num') and isinstance(value, list):
                    ret_val = []
                    for splitted_param in list_parameter_splitting(data=dict(kwargs), key=key, size_limit=size_limit):
                        try:
                            ret_val.extend(func(*args, **splitted_param))
                        except (TypeError, AttributeError):
                            ret_val = []
                    return ret_val
            raise dbsClientException('Invalid input', 'The lenght of the urlencoded parameters to API %s                                      is exceeding %s bytes and cannot be splitted.' % (func.__name__, size_limit))
        else:
            return func(*args, **kwargs)
    return wrapper

