    elif url.startswith('wss:'):
        reprotocoled = 'https' + url[3:]
    else:
        raise ValueError('URL has non-websocket protocol ' + url)
    if not reprotocoled.endswith('/ws'):
        raise ValueError('websocket URL does not end in /ws')
    return reprotocoled[:-2]

def groupby(self, io_select):
    offsets = []
    new_dim = []
    acc = 1
    for (i, d) in reversed(enumerate(self.dims)):
        if not io_select[i]:
            new_dim.insert(0, d)
        offsets.insert(0, acc * io_select[i])
        acc *= d
    if not new_dim:
        return ((c, self[c]) for c in self._all_combos())
    else:
        output = [[None, Matrix(dims=new_dim)] for i in range(acc)]
        _groupby(self.cube, 0, offsets, 0, output, tuple(), [])
    return output

