def _sort_by_indep(self, func='get_value', i=None, iunit=None, unit=None, uncover=None, trail=None, linebreak=None, sort_by_indep=None):
    if sort_by_indep is None:
        sort_by_indep = True
    indep_array = self.call.i.get_value(i=i, unit=iunit, uncover=uncover, trail=trail, linebreak=False, sort_by_indep=False)
    this_array = getattr(self, func)(i=i, unit=unit, uncover=uncover, trail=trail, linebreak=False, sort_by_indep=False)
    if not (isinstance(indep_array, np.ndarray) and len(indep_array) == len(this_array)):
        sort_by_indep = False
    if sort_by_indep:
        sort_inds = indep_array.argsort()
        return this_array[sort_inds]
    else:
        return this_array

