        hex_value = hex_value.replace('#', '')
    if len(hex_value) < 6:
        return '0000/0000/0000'
    r = hex_value[:2]
    g = hex_value[2:4]
    b = hex_value[4:]
    return r + '00/' + g + '00/' + b + '00'

