def localize(self, ps=None):
    from filelock import FileLock
    from ambry.util import ensure_dir_exists
    from ambry_sources import MPRowsFile
    from fs.errors import ResourceNotFoundError
    if self.is_local:
        return
    local = self._bundle.build_fs
    b = self._bundle.library.bundle(self.identity.as_dataset().vid)
    remote = self._bundle.library.remote(b)
    lock_path = local.getsyspath(self.cache_key + '.lock')
    ensure_dir_exists(lock_path)
    lock = FileLock(lock_path)
    if ps:
        ps.add_update(message='Localizing {}'.format(self.identity.name), partition=self, item_type='bytes', state='downloading')
    if ps:

        def progress(bts):
            if ps.rec.item_total is None:
                ps.rec.item_count = 0
            if not ps.rec.data:
                ps.rec.data = {}
                return self
            item_count = ps.rec.item_count + bts
            ps.rec.data['updates'] = ps.rec.data.get('updates', 0) + 1
            if ps.rec.data['updates'] % 32 == 1:
                ps.update(message='Localizing {}'.format(self.identity.name), item_count=item_count)
    else:
        from ambry.bundle.process import call_interval

        @call_interval(5)
        def progress(bts):
            self._bundle.log('Localizing {}. {} bytes downloaded'.format(self.vname, bts))

    def exception_cb(e):
        raise e
    with lock:
        if self.is_local:
            return self
        try:
            with remote.fs.open(self.cache_key + MPRowsFile.EXTENSION, 'rb') as f:
                event = local.setcontents_async(self.cache_key + MPRowsFile.EXTENSION, f, progress_callback=progress, error_callback=exception_cb)
                event.wait()
                if ps:
                    ps.update_done()
        except ResourceNotFoundError as e:
            from ambry.orm.exc import NotFoundError
            raise NotFoundError("Failed to get MPRfile '{}' from {}: {} ".format(self.cache_key, remote.fs, e))
    return self

def grasstruth(args):
    p = OptionParser(grasstruth.__doc__)
    (opts, args) = p.parse_args(args)
    if len(args) != 1:
        sys.exit(not p.print_help())
    (james,) = args
    fp = open(james)
    pairs = set()
    for row in fp:
        atoms = row.split()
        genes = []
        idx = {}
        for (i, a) in enumerate(atoms):
            aa = a.split('||')
            for ma in aa:
                idx[ma] = i
            genes.extend(aa)
        genes = [x for x in genes if ':' not in x]
        Os = [x for x in genes if x.startswith('Os')]
        for o in Os:
            for g in genes:
                if idx[o] == idx[g]:
                    continue
                pairs.add(tuple(sorted((o, g))))
    for (a, b) in sorted(pairs):
        print('\t'.join((a, b)))

def chimera_elimination_order(m, n=None, t=None):
    if n is None:
        n = m
    if t is None:
        t = 4
    index_flip = m > n
    if index_flip:
        (m, n) = (n, m)

    def chimeraI(m0, n0, k0, l0):
        if index_flip:
            return m * 2 * t * n0 + 2 * t * m0 + t * (1 - k0) + l0
        else:
            return n * 2 * t * m0 + 2 * t * n0 + t * k0 + l0
    order = []
    for n_i in range(n):
        for t_i in range(t):
            for m_i in range(m):
                order.append(chimeraI(m_i, n_i, 0, t_i))
    for n_i in range(n):
        for m_i in range(m):
            for t_i in range(t):
                order.append(chimeraI(m_i, n_i, 1, t_i))
    return order

def simulate_values(cls, num_events, schedulers, durations, param_names=None, **kwargs):
    if param_names is not None and (not isinstance(param_names, (list, tuple))):
        raise ValueError('Argument param_names should be list or tuple of strings')
    output = []
    opt_copy_map = {id(s.optimizer_param_groups): deepcopy(s.optimizer_param_groups) for s in schedulers}
    copy_schedulers = [_replicate_scheduler(s, opt_copy_map) for s in schedulers]
    scheduler = cls(copy_schedulers, durations, save_history=False)
    if param_names is None:
        param_names = [scheduler.param_name]
    for i in range(num_events):
        scheduler(engine=None)
        values = [scheduler.optimizer_param_groups[0][param_name] for param_name in param_names]
        output.append([i] + values)
    return output

