    key_value_pairs = {}
    ' Match reaction gas species with their atomic structure '
    for (key, mollist) in self.reaction_atoms.items():
        for (i, molecule) in enumerate(mollist):
            if self.states[key][i] == 'gas':
                assert molecule in self.ase_ids_gas.keys(), 'Molecule {molecule} is missing in folder {gas_folder}'.format(molecule=clear_prefactor(self.reaction[key][i]), gas_folder=self.gas_folder)
                self.structures[key][i] = self.gas[molecule]
                species = clear_prefactor(self.reaction[key][i])
                key_value_pairs.update({'species': clear_state(species)})
                self.ase_ids.update({species: self.ase_ids_gas[molecule]})
    ' Add empty slab to structure dict'
    for (key, mollist) in self.reaction_atoms.items():
        if '' in mollist:
            n = mollist.index('')
            self.structures[key][n] = self.empty

def open(image):
    if isinstance(image, six.string_types):
        name = image
        if name.startswith('data:image/'):
            return _open_data_url(name)
        if re.match('^https?://', name):
            return url_to_image(name)
        if os.path.isfile(name):
            img = cv2.imread(name)
            if img is None:
                raise IOError('Image format error: %s' % name)
            return img
        raise IOError('Open image(%s) not found' % name)
    return image

