def iscoplanar(coords):
    coords = sp.array(coords, ndmin=1)
    if sp.shape(coords)[0] < 3:
        raise Exception('At least 3 input pores are required')
    Px = coords[:, 0]
    Py = coords[:, 1]
    Pz = coords[:, 2]
    if sp.shape(sp.unique(Px))[0] == 1:
        return True
    if sp.shape(sp.unique(Py))[0] == 1:
        return True
    if sp.shape(sp.unique(Pz))[0] == 1:
        return True
    n1 = sp.array((Px[1] - Px[0], Py[1] - Py[0], Pz[1] - Pz[0])).T
    n2 = sp.array((Px[2] - Px[1], Py[2] - Py[1], Pz[2] - Pz[1])).T
    n = sp.cross(n1, n2)
    r = sp.array((Px[1:-1] - Px[0], Py[1:-1] - Py[0], Pz[1:-1] - Pz[0]))
    n_dot = sp.dot(n, r)
    if sp.sum(n_dot) == 0:
        return True
    else:
        return False

def add_execution_profile(self, name, profile, pool_wait_timeout=5):
    if not isinstance(profile, ExecutionProfile):
        raise TypeError('profile must be an instance of ExecutionProfile')
    if self._config_mode == _ConfigMode.LEGACY:
        raise ValueError('Cannot add execution profiles when legacy parameters are set explicitly.')
    if name in self.profile_manager.profiles:
        raise ValueError('Profile {} already exists'.format(name))
    contact_points_but_no_lbp = self._contact_points_explicit and (not profile._load_balancing_policy_explicit)
    if contact_points_but_no_lbp:
        log.warning('Tried to add an ExecutionProfile with name {name}. {self} was explicitly configured with contact_points, but {ep} was not explicitly configured with a load_balancing_policy. In the next major version, trying to add an ExecutionProfile without an explicitly configured LBP to a cluster with explicitly configured contact_points will raise an exception; please specify a load-balancing policy in the ExecutionProfile.'.format(name=repr(name), self=self, ep=profile))
    self.profile_manager.profiles[name] = profile
    profile.load_balancing_policy.populate(self, self.metadata.all_hosts())
    for host in filter(lambda h: h.is_up, self.metadata.all_hosts()):
        profile.load_balancing_policy.on_up(host)
    futures = set()
    for session in tuple(self.sessions):
        futures.update(session.update_created_pools())
    (_, not_done) = wait_futures(futures, pool_wait_timeout)
    if not_done:
        raise OperationTimedOut('Failed to create all new connection pools in the %ss timeout.')

def _get_ca_certs_paths():
    ca_certs = []
    embedded_root = os.path.dirname(os.path.abspath(__file__))
    for _ in range(10):
        if os.path.basename(embedded_root) == 'embedded':
            ca_certs.append(os.path.join(embedded_root, 'ssl', 'certs', 'cacert.pem'))
            break
        embedded_root = os.path.dirname(embedded_root)
    else:
        raise OSError('Unable to locate `embedded` directory. Please specify ca_certs in your http yaml configuration file.')
    try:
        import tornado
    except ImportError:
        pass
    else:
        ca_certs.append(os.path.join(os.path.dirname(tornado.__file__), 'ca-certificates.crt'))
    ca_certs.append('/etc/ssl/certs/ca-certificates.crt')
    return ca_certs

