def solve_semi_dual_entropic(a, b, M, reg, method, numItermax=10000, lr=None, log=False):
    if method.lower() == 'sag':
        opt_beta = sag_entropic_transport(a, b, M, reg, numItermax, lr)
    elif method.lower() == 'asgd':
        opt_beta = averaged_sgd_entropic_transport(a, b, M, reg, numItermax, lr)
    else:
        print('Please, select your method between SAG and ASGD')
        return None
    opt_alpha = c_transform_entropic(b, M, reg, opt_beta)
    pi = np.exp((opt_alpha[:, None] + opt_beta[None, :] - M[:, :]) / reg) * a[:, None] * b[None, :]
    if log:
        log = {}
        log['alpha'] = opt_alpha
        log['beta'] = opt_beta
        return (pi, log)
    else:
        return pi

def _transform_prefix(cls, root_node, create_group_func):

    def transform(node):
        if isinstance(node, Any):
            for c in node.children:
                for r in transform(c):
                    yield ('(?:%s)?' % r)
        elif isinstance(node, Sequence):
            for i in range(len(node.children)):
                a = [cls._transform(c, create_group_func) for c in node.children[:i]]
                for c in transform(node.children[i]):
                    yield ('(?:%s)' % (''.join(a) + c))
        elif isinstance(node, Regex):
            yield ('(?:%s)?' % node.regex)
        elif isinstance(node, Lookahead):
            if node.negative:
                yield ('(?!%s)' % cls._transform(node.childnode, create_group_func))
            else:
                raise Exception('Positive lookahead not yet supported.')
        elif isinstance(node, Variable):
            for c in transform(node.childnode):
                yield ('(?P<%s>%s)' % (create_group_func(node), c))
        elif isinstance(node, Repeat):
            prefix = cls._transform(node.childnode, create_group_func)
            for c in transform(node.childnode):
                if node.max_repeat:
                    repeat_sign = '{,%i}' % (node.max_repeat - 1)
                else:
                    repeat_sign = '*'
                yield ('(?:%s)%s%s(?:%s)?' % (prefix, repeat_sign, '' if node.greedy else '?', c))
        else:
            raise TypeError('Got %r' % node)
    for r in transform(root_node):
        yield ('^%s$' % r)

def set_dns(name, dnsservers=None, searchdomains=None, path=None):
    if dnsservers is None:
        dnsservers = ['8.8.8.8', '4.4.4.4']
    elif not isinstance(dnsservers, list):
        try:
            dnsservers = dnsservers.split(',')
        except AttributeError:
            raise SaltInvocationError("Invalid input for 'dnsservers' parameter")
    if searchdomains is None:
        searchdomains = []
    elif not isinstance(searchdomains, list):
        try:
            searchdomains = searchdomains.split(',')
        except AttributeError:
            raise SaltInvocationError("Invalid input for 'searchdomains' parameter")
    dns = ['nameserver {0}'.format(x) for x in dnsservers]
    dns.extend(['search {0}'.format(x) for x in searchdomains])
    dns = '\n'.join(dns) + '\n'
    rstr = __salt__['test.random_hash']()
    script = '/sbin/{0}_dns.sh'.format(rstr)
    DNS_SCRIPT = '\n'.join(['#!/usr/bin/env bash', 'if [ -h /etc/resolv.conf ];then', ' if [ "x$(readlink /etc/resolv.conf)" = "x../run/resolvconf/resolv.conf" ];then', '  if [ ! -d /run/resolvconf/ ];then', '   mkdir -p /run/resolvconf', '  fi', '  cat > /etc/resolvconf/resolv.conf.d/head <<EOF', dns, 'EOF', '', ' fi', 'fi', 'cat > /etc/resolv.conf <<EOF', dns, 'EOF', ''])
    result = run_all(name, 'tee {0}'.format(script), path=path, stdin=DNS_SCRIPT, python_shell=True)
    if result['retcode'] == 0:
        result = run_all(name, 'sh -c "chmod +x {0};{0}"'.format(script), path=path, python_shell=True)
    run_all(name, 'sh -c \'if [ -f "{0}" ];then rm -f "{0}";fi\''.format(script), path=path, python_shell=True)
    if result['retcode'] != 0:
        error = "Unable to write to /etc/resolv.conf in container '{0}'".format(name)
        if result['stderr']:
            error += ': {0}'.format(result['stderr'])
        raise CommandExecutionError(error)
    return True

