def get_pytwis(epilog):
    parser = argparse.ArgumentParser(conflict_handler='resolve', formatter_class=argparse.RawDescriptionHelpFormatter, description='Connect to the Redis database of a Twitter clone and then run commands to access and update the database.', epilog=epilog)
    parser.add_argument('-h', '--hostname', nargs='?', default='127.0.0.1', help='the Redis server hostname. If the option is not specified,\n                             will be defaulted to 127.0.0.1. If the option is specified but\n                             no value is given after the option, then the help information\n                             is displayed instead.\n                             ')
    parser.add_argument('-p', '--port', default=6379, help='the Redis server port. If the option is not specified, will\n                             be defaulted to 6379.\n                             ')
    parser.add_argument('-s', '--socket', default='', help='the Redis server socket (usually /tmp/redis.sock). If it is\n                             given, it will override hostname and port. Make sure that the\n                             unixsocket parameter is defined in your redis.conf file. It’s\n                             commented out by default.\n                             ')
    parser.add_argument('-n', '--db', default=0, help='the Redis server database. If the option is not specified,\n                             will be defaulted to 0.\n                             ')
    parser.add_argument('-a', '--password', default='', help='the Redis server password. If the option not specified,\n                             will be defaulted to an empty string.\n                             ')
    args = parser.parse_args()
    if args.hostname is None:
        parser.print_help()
        return 0
    if args.socket:
        print('The input Redis server socket is {}'.format(args.socket))
        prompt = args.socket
    else:
        print('The input Redis server hostname is {}.'.format(args.hostname))
        print('The input Redis server port is {}.'.format(args.port))
        prompt = '{}:{}'.format(args.hostname, args.port)
    print('The input Redis server database is {}.'.format(args.db))
    if args.password != '':
        print('The input Redis server password is "{}".'.format(args.password))
    else:
        print('The input Redis server password is empty.')
    try:
        if args.socket:
            twis = pytwis.Pytwis(socket=args.socket, db=args.db, password=args.password)
        else:
            twis = pytwis.Pytwis(hostname=args.hostname, port=args.port, db=args.db, password=args.password)
        return (twis, prompt)
    except ValueError as excep:
        print('Failed to connect to the Redis server: {}'.format(str(excep)), file=sys.stderr)
        return (None, None)

def from_url(cls, url, show_host=True):
    if six.PY2:
        if isinstance(url, six.text_type):
            url = url.encode('utf-8')
        parsed = urlparse(url)
        netloc = parsed.netloc.decode('utf-8')
    else:
        if isinstance(url, six.binary_type):
            url = url.decode('utf-8', errors='replace')
        parsed = urlparse(url)
        netloc = parsed.netloc
    query = _parse_qs(parsed.query)
    host = netloc.split(':', 1)[0] if ':' in netloc else netloc
    port = netloc.split(':')[1] if ':' in netloc else ''
    path = unquote(parsed.path)
    fragment = unquote(parsed.fragment)
    if not fragment and (not url.endswith('#')):
        fragment = None
    return cls(path, query, host, port, parsed.scheme, fragment, show_host)

