def _guess_package(self, path):
    supported_prefixes = ('com', 'org', 'net')
    package = ''
    slash = path.rfind(os.path.sep)
    prefix_with_slash = max((path.rfind(os.path.join('', prefix, '')) for prefix in supported_prefixes))
    if prefix_with_slash < 0:
        package = path[:slash]
    elif prefix_with_slash >= 0:
        package = path[prefix_with_slash:slash]
    package = package.replace(os.path.sep, ' ')
    package = package.strip().replace(' ', '.')
    return package

def write_node(node, writer=None, encoding='utf-8', indent=0, newline='', omit_declaration=False, node_depth=0, quote_char='"'):

    def _sanitize_write_value(value):
        if not value:
            return value
        return value.replace('&', '&amp;').replace('<', '&lt;').replace('"', '&quot;').replace('>', '&gt;')

    def _write_node_impl(node, node_depth):
        if node.is_document:
            if not omit_declaration:
                writer.write('<?xml version=%s1.0%s' % (quote_char, quote_char))
                if encoding:
                    writer.write(' encoding=%s%s%s' % (quote_char, encoding, quote_char))
                writer.write('?>%s' % newline)
            for child in node.children:
                _write_node_impl(child, node_depth)
            writer.write(newline)
        elif node.is_document_type:
            writer.write('<!DOCTYPE %s SYSTEM %s%s%s' % (node.name, quote_char, node.public_id))
            if node.system_id is not None:
                writer.write(' %s%s%s' % (quote_char, node.system_id, quote_char))
            if node.children:
                writer.write('[')
                for child in node.children:
                    _write_node_impl(child, node_depth + 1)
                writer.write(']')
            writer.write('>')
        elif node.is_text:
            writer.write(_sanitize_write_value(node.value))
        elif node.is_cdata:
            if ']]>' in node.value:
                raise ValueError("']]>' is not allowed in CDATA node value")
            writer.write('<![CDATA[%s]]>' % node.value)
        elif node.is_entity:
            writer.write(newline + indent * node_depth)
            writer.write('<!ENTITY ')
            if node.is_paremeter_entity:
                writer.write('%% ')
            writer.write('%s %s%s%s>' % (node.name, quote_char, node.value, quote_char))
        elif node.is_processing_instruction:
            writer.write(newline + indent * node_depth)
            writer.write('<?%s %s?>' % (node.target, node.data))
        elif node.is_comment:
            if '--' in node.value:
                raise ValueError("'--' is not allowed in COMMENT node value")
            writer.write('<!--%s-->' % node.value)
        elif node.is_notation:
            writer.write(newline + indent * node_depth)
            writer.write('<!NOTATION %s' % node.name)
            if node.is_system_identifier:
                writer.write(' system %s%s%s>' % (quote_char, node.external_id, quote_char))
            elif node.is_system_identifier:
                writer.write(' system %s%s%s %s%s%s>' % (quote_char, node.external_id, quote_char, quote_char, node.uri, quote_char))
        elif node.is_attribute:
            writer.write(' %s=%s' % (node.name, quote_char))
            writer.write(_sanitize_write_value(node.value))
            writer.write(quote_char)
        elif node.is_element:
            if node_depth > 0:
                writer.write(newline)
            writer.write(indent * node_depth)
            writer.write('<' + node.name)
            for attr in node.attribute_nodes:
                _write_node_impl(attr, node_depth)
            if node.children:
                found_indented_child = False
                writer.write('>')
                for child in node.children:
                    _write_node_impl(child, node_depth + 1)
                    if not (child.is_text or child.is_comment or child.is_cdata):
                        found_indented_child = True
                if found_indented_child:
                    writer.write(newline + indent * node_depth)
                writer.write('</%s>' % node.name)
            else:
                writer.write('/>')
        else:
            raise exceptions.Xml4hImplementationBug('Cannot write node with class: %s' % node.__class__)
    if indent is True:
        indent = ' ' * 4
    elif indent is False:
        indent = ''
    elif isinstance(indent, int):
        indent = ' ' * indent
    if indent and (not newline):
        newline = True
    if newline is None or newline is False:
        newline = ''
    elif newline is True:
        newline = '\n'
    if writer is None:
        writer = sys.stdout
    if encoding is None:
        writer = writer
