def convert_regex_to_flask_path(url_path):
    for token in ['$']:
        url_path = url_path.replace(token, '')

    def caller(reg):
        (match_name, match_pattern) = reg.groups()
        return '<regex("{0}"):{1}>'.format(match_pattern, match_name)
    url_path = re.sub('\\(\\?P<(.*?)>(.*?)\\)', caller, url_path)
    if url_path.endswith('/?'):
        url_path = url_path.rstrip('/?')
    return url_path

def move(src, dst):
    src = os.path.expanduser(src)
    dst = os.path.expanduser(dst)
    if not os.path.isabs(src):
        raise SaltInvocationError('Source path must be absolute.')
    if not os.path.isabs(dst):
        raise SaltInvocationError('Destination path must be absolute.')
    ret = {'result': True, 'comment': "'{0}' moved to '{1}'".format(src, dst)}
    try:
        shutil.move(src, dst)
    except (OSError, IOError) as exc:
        raise CommandExecutionError("Unable to move '{0}' to '{1}': {2}".format(src, dst, exc))
    return ret

