def decrypt(data, _key):
    if _key is None:
        Log.error('Expecting a key')
    _input = get_module('mo_json').json2value(data.decode('utf8'), leaves=False, flexible=False)
    key_expander_256 = key_expander.KeyExpander(256)
    expanded_key = key_expander_256.expand(_key)
    aes_cipher_256 = aes_cipher.AESCipher(expanded_key)
    aes_cbc_256 = cbc_mode.CBCMode(aes_cipher_256, 16)
    aes_cbc_256.set_iv(base642bytearray(_input.salt))
    raw = base642bytearray(_input.data)
    out_data = bytearray()
    for (_, e) in _groupby16(raw):
        out_data.extend(aes_cbc_256.decrypt_block(e))
    if _input.encoding:
        return binary_type(out_data[:_input.length]).decode(_input.encoding)
    else:
        return binary_type(out_data[:_input.length])

def _get_tbl_numpy_dtype(self, colnum, include_endianness=True):
    table_type = self._info['hdutype']
    table_type_string = _hdu_type_map[table_type]
    try:
        ftype = self._info['colinfo'][colnum]['eqtype']
        if table_type == ASCII_TBL:
            npy_type = _table_fits2npy_ascii[abs(ftype)]
        else:
            npy_type = _table_fits2npy[abs(ftype)]
    except KeyError:
        raise KeyError('unsupported %s fits data type: %d' % (table_type_string, ftype))
    istbit = False
    if ftype == 1:
        istbit = True
    isvar = False
    if ftype < 0:
        isvar = True
    if include_endianness:
        if table_type == ASCII_TBL:
            addstr = ''
        else:
            addstr = '>'
        if npy_type not in ['u1', 'i1', 'S', 'U']:
            npy_type = addstr + npy_type
    if npy_type == 'S':
        width = self._info['colinfo'][colnum]['width']
        npy_type = 'S%d' % width
    elif npy_type == 'U':
        width = self._info['colinfo'][colnum]['width']
        npy_type = 'U%d' % width
    return (npy_type, isvar, istbit)

def jacobi(n, alpha, beta, standardization, symbolic=False):
    gamma = sympy.gamma if symbolic else lambda x: scipy.special.gamma(float(x))

    def rational(x, y):
        return sympy.Rational(x, y) if all([isinstance(val, int) for val in [x, y]]) else x / y
    frac = rational if symbolic else lambda x, y: x / y
    sqrt = sympy.sqrt if symbolic else numpy.sqrt
    int_1 = 2 ** (alpha + beta + 1) * gamma(alpha + 1) * gamma(beta + 1) / gamma(alpha + beta + 2)
    if standardization == 'monic':
        p0 = 1
        a = numpy.ones(n, dtype=int)
        if isinstance(alpha, numpy.int64):
            alpha = int(alpha)
        if isinstance(beta, numpy.int64):
            beta = int(beta)
        b = [frac(beta - alpha, alpha + beta + 2) if N == 0 else frac(beta ** 2 - alpha ** 2, (2 * N + alpha + beta) * (2 * N + alpha + beta + 2)) for N in range(n)]
        c = [int_1 if N == 0 else frac(4 * (1 + alpha) * (1 + beta), (2 + alpha + beta) ** 2 * (3 + alpha + beta)) if N == 1 else frac(4 * (N + alpha) * (N + beta) * N * (N + alpha + beta), (2 * N + alpha + beta) ** 2 * (2 * N + alpha + beta + 1) * (2 * N + alpha + beta - 1)) for N in range(n)]
    elif standardization == 'p(1)=(n+alpha over n)' or (alpha == 0 and standardization == 'p(1)=1'):
        p0 = 1
        if isinstance(alpha, numpy.int64):
            alpha = int(alpha)
        if isinstance(beta, numpy.int64):
            beta = int(beta)
        a = [frac(alpha + beta + 2, 2) if N == 0 else frac((2 * N + alpha + beta + 1) * (2 * N + alpha + beta + 2), 2 * (N + 1) * (N + alpha + beta + 1)) for N in range(n)]
        b = [frac(beta - alpha, 2) if N == 0 else frac((beta ** 2 - alpha ** 2) * (2 * N + alpha + beta + 1), 2 * (N + 1) * (N + alpha + beta + 1) * (2 * N + alpha + beta)) for N in range(n)]
        c = [int_1 if N == 0 else frac((N + alpha) * (N + beta) * (2 * N + alpha + beta + 2), (N + 1) * (N + alpha + beta + 1) * (2 * N + alpha + beta)) for N in range(n)]
    else:
        assert standardization == 'normal', "Unknown standardization '{}'.".format(standardization)
        p0 = sqrt(1 / int_1)
        a = [frac(alpha + beta + 2, 2) * sqrt(frac(alpha + beta + 3, (alpha + 1) * (beta + 1))) if N == 0 else frac(2 * N + alpha + beta + 2, 2) * sqrt(frac((2 * N + alpha + beta + 1) * (2 * N + alpha + beta + 3), (N + 1) * (N + alpha + 1) * (N + beta + 1) * (N + alpha + beta + 1))) for N in range(n)]
        b = [(frac(beta - alpha, 2) if N == 0 else frac(beta ** 2 - alpha ** 2, 2 * (2 * N + alpha + beta))) * sqrt(frac((2 * N + alpha + beta + 3) * (2 * N + alpha + beta + 1), (N + 1) * (N + alpha + 1) * (N + beta + 1) * (N + alpha + beta + 1))) for N in range(n)]
        c = [int_1 if N == 0 else frac(4 + alpha + beta, 2 + alpha + beta) * sqrt(frac((1 + alpha) * (1 + beta) * (5 + alpha + beta), 2 * (2 + alpha) * (2 + beta) * (2 + alpha + beta))) if N == 1 else frac(2 * N + alpha + beta + 2, 2 * N + alpha + beta) * sqrt(frac(N * (N + alpha) * (N + beta) * (N + alpha + beta) * (2 * N + alpha + beta + 3), (N + 1) * (N + alpha + 1) * (N + beta + 1) * (N + alpha + beta + 1) * (2 * N + alpha + beta - 1))) for N in range(n)]
    return (p0, numpy.array(a), numpy.array(b), numpy.array(c))

def import_module(name):
    parts = name.split('.')
    path = None
    module_name = ''
    fhandle = None
    for (index, part) in enumerate(parts):
        module_name = part if index == 0 else '%s.%s' % (module_name, part)
        path = [path] if path is not None else path
        try:
            (fhandle, path, descr) = imp.find_module(part, path)
            if module_name in sys.modules:
                mod = sys.modules[module_name]
            else:
                mod = imp.load_module(module_name, fhandle, path, descr)
        finally:
            if fhandle:
                fhandle.close()
    return mod

