def fix_text(s, ignore_sym_pat=False):
    if not ignore_sym_pat:
        s = re.sub('([A-Z0-9]){6} \\(', '', s)
        s = s.split(';')[0]
    s = s.translate(None, '[]')
    s = s.replace('(-)', '[-]')
    s = s.replace('(+)', '[+]')
    s = s.replace('(Uncharacterized protein)', '')
    if not ignore_sym_pat:
        s = s.translate(None, '()')
    if 'protei ' in s:
        s = s.replace('protei ', 'protein ')
    if 'hypthetical' in s:
        s = s.replace('hypthetical', 'hypothetical')
    if s.startswith('ytochrome'):
        s = s.replace('ytochrome', 'cytochrome')
    m = re.findall(glycosidic_link_pat, s)
    if m and ';' in s:
        s = re.sub(';\\s*', '-', s)
    s = re.sub('_', ' ', s)
    for pat in (loc_pat, osg_pat, frag_pat, upf_pat, ddb_pat):
        s = s.strip() + ' '
        s = re.sub(pat, '', s)
    s = re.sub(apos_pat, "'", s)
    s = re.sub(gt_pat, '', s)
    s = re.sub('[-]+', '-', s)
    s = re.sub("[']+", "'", s)
    s = s.strip()
    s = re.sub(like_pat, '-like protein', s)
    if re.search(repeat_pat, s):
        s += '-containing protein'
    if re.search(binding_pat, s):
        s += ' protein'
        if re.match(Protein_pat, s):
            s = re.sub(Protein_pat, '', s)
    if re.search(domain_pat, s):
        s += '-containing protein'
        if re.search('-domain', s):
            s = re.sub('-domain', ' domain', s)
        if re.match(Protein_pat, s):
            s = re.sub(Protein_pat, '', s)
    if re.search(related_pat, s):
        s = re.sub(related_pat, '-like protein', s)
        if re.match(Protein_pat, s) and (not re.match('Protein kinase', s)):
            s = re.sub(Protein_pat, '', s)
    if re.search(homolog_pat1, s):
        s = re.sub(homolog_pat1, '-like protein', s)
        if re.match(Protein_pat, s):
            s = re.sub(Protein_pat, '', s)
    match = re.search(homolog_pat2, s)
    if match and (not re.match('Protein kinase', s)):
        ret = match.group(1)
        s = re.sub(homolog_pat2, ret + '-like protein', s)
        s = re.sub('^\\s+', '', s)
        s = s.capitalize()
    for pat in (homolog_pat3, homolog_pat5, homolog_pat6):
        if re.search(pat, s):
            s = re.sub(pat, '-like protein', s)
    if re.search(agenet_pat, s):
        s = re.sub(agenet_pat, 'Agenet and ', s)
    if re.search(plural_pat, s):
        if s.find('biogenesis') == -1 and s.find('Topors') == -1 or not re.search(with_and_pat, s):
            s = re.sub('s$', '', s)
    if re.search(tbp_pat, s):
        s = re.sub(tbp_pat, 'like TBP', s)
    if re.search(prot_pat, s):
        s = re.sub(prot_pat, 'protein', s)
    if re.search(dimer_pat, s):
        s = re.sub(dimer_pat, 'dimerization', s)
    for pat in (atg_pat, athila_pat1):
        if re.search(pat, s):
            s = Unknown
    for pat in (atg_id_pat, athila_pat2, athila_pat3, athila_pat4):
        s = s.strip() + ' '
        s = re.sub(pat, '', s)
    if re.search(length_pat, s):
        s = re.sub(length_pat, '', s)
    if re.search('\\. ', s):
        if re.search(',', s):
            s = s.split(',')[0]
    for pat in (disallow_pat, organism_pat):
        if re.search(pat, s):
            s = re.sub(pat, '', s)
    s = s.strip()
    if not ignore_sym_pat:
        if re.search(homolog_pat4, s):
            s = re.sub(homolog_pat4, '', s)
        if re.search(trail_pat, s):
            s = re.sub(trail_pat, '', s)
        if (re.search(sym_pat, s) or re.search(lc_sym_pat, s)) and (not re.search(spada_pat, s)):
            s = s + '-like protein'
        if re.search(eol_sym_pat, s):
            s = re.sub(eol_sym_pat, '', s)
        if re.search('\\W{1,}$', s) and (not re.search('\\)$', s)):
            s = re.sub('\\W{1,}$', '', s)
        if 'uncharacterized' in s:
            s = 'uncharacterized protein'
    if re.search(sulfer_pat, s):
        s = re.sub(sulfer_pat, 'sulfur', s)
    if re.search(sulph_pat, s):
        s = re.sub(sulph_pat, 'sulf', s)
    if re.search(monoxy_pat, s):
        s = re.sub(monoxy_pat, 'monooxy', s)
    if re.search(proteine_pat, s):
        s = re.sub(proteine_pat, 'protein', s)
    if re.search(signalling_pat, s):
        s = re.sub(signalling_pat, 'signaling', s)
    if re.search(aluminium_pat, s):
        s = re.sub(aluminium_pat, 'aluminum', s)
    if re.search(haem_pat, s):
        s = re.sub(haem_pat, 'heme', s)
    if re.search(haemo_pat, s):
        s = re.sub(haemo_pat, 'hemo', s)
    if re.search(assessory_pat, s):
        s = re.sub(assessory_pat, 'accessory', s)
    match = re.search(ise_pat, s)
    if match:
        ret = match.group(1)
        if match.group(2):
            suff = match.group(2)
            s = re.sub(ise_pat, '{0}ize{1}'.format(ret, suff), s)
        else:
            s = re.sub(ise_pat, '{0}ize'.format(ret), s)
    match = re.search(isation_pat, s)
    if match:
        ret = match.group(1)
        s = re.sub(isation_pat, '{0}ization'.format(ret), s)
    match = re.search(bre_pat, s)
    if match:
        ret = match.group(1)
        s = re.sub(bre_pat, '{0}ber'.format(ret), s)
    if not s.startswith(Hypothetical):
        if s.startswith('Uncharacterized') and any((pat in s for pat in ('UCP', 'UPF', 'protein'))):
            pass
        elif re.search(put_pat, s):
            s = re.sub(put_pat, 'Putative', s)
    '\n    case (qr/^Histone-lysine/) { $ahrd =~ s/,\\s+H\\d{1}\\s+lysine\\-\\d+//gs; }\n    '
    sl = s.lower()
    if 'clone' in sl or 'contig' in sl:
        s = Unknown
    if sl in ('protein', 'protein, putative', ''):
        s = Unknown
    if Unknown.lower() in sl:
        s = Unknown
    if 'FUNCTIONS IN'.lower() in sl and 'unknown' in sl:
        s = Unknown
    if 'LOCATED IN'.lower() in sl:
        s = Unknown
    s = re.sub('[,]*\\s+putative$', '', s)
    if s == Unknown or s.strip() == 'protein':
        s = Hypothetical
    s = ' '.join(s.split())
    assert s.strip()
    return s

def estimator_spec_predict(self, features, use_tpu=False):
    decode_hparams = self._decode_hparams
    top_beams = decode_hparams.beam_size if decode_hparams.return_beams else 1
    infer_out = self.infer(features, beam_size=decode_hparams.beam_size, top_beams=top_beams, alpha=decode_hparams.alpha, decode_length=decode_hparams.extra_length, use_tpu=use_tpu)
    if isinstance(infer_out, dict):
        outputs = infer_out['outputs']
        scores = infer_out['scores']
    else:
        outputs = infer_out
        scores = None
    inputs = features.get('inputs')
    if inputs is None:
        inputs = features['targets']
    predictions = {'outputs': outputs, 'scores': scores, 'inputs': inputs, 'targets': features.get('infer_targets')}
    for (name, feature) in features.items():
        if name not in list(predictions.keys()) + ['infer_targets']:
            if name == 'decode_loop_step':
                continue
            if not feature.shape.as_list():
                batch_size = common_layers.shape_list(outputs)[0]
                feature = tf.tile(tf.expand_dims(feature, 0), [batch_size])
            predictions[name] = feature
    _del_dict_non_tensors(predictions)
    export_out = {'outputs': predictions['outputs']}
    if 'scores' in predictions:
        export_out['scores'] = predictions['scores']
    if 'batch_prediction_key' in predictions:
        export_out['batch_prediction_key'] = predictions['batch_prediction_key']
    export_outputs = {tf.saved_model.signature_constants.DEFAULT_SERVING_SIGNATURE_DEF_KEY: tf.estimator.export.PredictOutput(export_out)}
    if use_tpu:
        if self.hparams.tpu_enable_host_call:
            host_call = self.create_eval_host_call()
        else:
            host_call = None
        remove_summaries()
        return tf.contrib.tpu.TPUEstimatorSpec(tf.estimator.ModeKeys.PREDICT, predictions=predictions, host_call=host_call, export_outputs=export_outputs)
    else:
        return tf.estimator.EstimatorSpec(tf.estimator.ModeKeys.PREDICT, predictions=predictions, export_outputs=export_outputs)

def get_namespace(attribute, namespace_splitter=NAMESPACE_SPLITTER, root_only=False):
    attribute_tokens = attribute.split(namespace_splitter)
    if len(attribute_tokens) == 1:
        LOGGER.debug("> Attribute: '{0}', namespace: '{1}'.".format(attribute, Constants.null_object))
    else:
        namespace = foundations.common.get_first_item(attribute_tokens) if root_only else namespace_splitter.join(attribute_tokens[0:-1])
        LOGGER.debug("> Attribute: '{0}', namespace: '{1}'.".format(attribute, namespace))
        return namespace

def check_rules_dict(rules):
    from qnet.algebra.pattern_matching import Pattern, ProtoExpr
    if hasattr(rules, 'items'):
        items = rules.items()
    else:
        items = rules
    keys = set()
    for key_rule in items:
        try:
            (key, rule) = key_rule
        except ValueError:
            raise TypeError('rules does not contain (key, rule) tuples')
        if not isinstance(key, str):
            raise TypeError("Key '%s' is not a string" % key)
        if key in keys:
            raise ValueError("Duplicate key '%s'" % key)
        else:
            keys.add(key)
        try:
            (pat, replacement) = rule
        except TypeError:
            raise TypeError("Rule in '%s' is not a (pattern, replacement) tuple" % key)
        if not isinstance(pat, Pattern):
            raise TypeError("Pattern in '%s' is not a Pattern instance" % key)
        if pat.head is not ProtoExpr:
            raise ValueError("Pattern in '%s' does not match a ProtoExpr" % key)
        if not callable(replacement):
            raise ValueError("replacement in '%s' is not callable" % key)
        else:
            arg_names = inspect.signature(replacement).parameters.keys()
            if not arg_names == pat.wc_names:
                raise ValueError('arguments (%s) of replacement function differ from the wildcard names (%s) in pattern' % (', '.join(sorted(arg_names)), ', '.join(sorted(pat.wc_names))))
    return OrderedDict(rules)

def _getnode(self, curie):
    node = None
    if curie[0] == '_':
        if self.are_bnodes_skized is True:
            node = self.skolemizeBlankNode(curie)
        else:
            node = BNode(re.sub('^_:|^_', '', curie, 1))
    elif curie[:4] == 'http' or curie[:3] == 'ftp':
        node = URIRef(curie)
    else:
        iri = RDFGraph.curie_util.get_uri(curie)
        if iri is not None:
            node = URIRef(RDFGraph.curie_util.get_uri(curie))
            prefix = curie.split(':')[0]
            if prefix not in self.namespace_manager.namespaces():
                mapped_iri = self.curie_map[prefix]
                self.bind(prefix, Namespace(mapped_iri))
        else:
            LOG.error("couldn't make URI for %s", curie)
    return node

def images(self, type):
    images = []
    res = (yield from self.http_query('GET', '/{}/images'.format(type), timeout=None))
    images = res.json
    try:
        if type in ['qemu', 'dynamips', 'iou']:
            for local_image in list_images(type):
                if local_image['filename'] not in [i['filename'] for i in images]:
                    images.append(local_image)
            images = sorted(images, key=itemgetter('filename'))
        else:
            images = sorted(images, key=itemgetter('image'))
    except OSError as e:
        raise ComputeError("Can't list images: {}".format(str(e)))
    return images

