def main(self):
    while True:
        while self.ready:
            (task, a) = self.ready.popleft()
            self.run_task(task, *a)
        if self.scheduled:
            timeout = self.scheduled.timeout()
            if timeout < 0:
                (task, a) = self.scheduled.pop()
                self.run_task(task, *a)
                continue
            if not self.registered:
                time.sleep(timeout)
                (task, a) = self.scheduled.pop()
                self.run_task(task, *a)
                continue
        else:
            timeout = -1
        if not self.registered:
            self.stopped.send(True)
            return
        events = None
        try:
            events = self.poll.poll(timeout=timeout)
        except IOError:
            pass
        if events:
            self.spawn(self.dispatch_events, events)

def getReportTable(reportzipfile, tablefilename, inReportsDir=True, verbose=False):
    import zipfile, io, re
    if not reportzipfile.endswith('.zip'):
        reportzipfile += '.zip'
    if inReportsDir:
        reportzipfile = os.path.join(reportsDir, reportzipfile)
    with zipfile.ZipFile(reportzipfile) as z:
        if not tablefilename:
            for f in z.filelist:
                if 'table' in f.filename:
                    print(f.filename)
            return
        if isinstance(tablefilename, list):
            tablelocation = tablefilename
            tablefilename = None
            location = re.compile('(s|table)(\\d+)_')
            for f in z.filelist:
                if 'table' not in f.filename or f.filename.count('/') != len(tablelocation) - 1:
                    continue
                if [int(location.match(s).groups()[1]) for s in f.filename.split('/')] == tablelocation:
                    tablefilename = f.filename
                    if verbose:
                        print('Loading', tablefilename)
                    break
            if tablefilename is None:
                raise FileNotFoundError('Table location not found in zip folder.')
        with z.open(tablefilename) as f:
            ft = io.TextIOWrapper(f)
            return pd.read_csv(ft, index_col=0, sep=csvsep, decimal=csvdec)

