def _pastorestr(ins):
    output = _paddr(ins.quad[1])
    temporal = False
    value = ins.quad[2]
    indirect = value[0] == '*'
    if indirect:
        value = value[1:]
    immediate = value[0]
    if immediate:
        value = value[1:]
    if value[0] == '_':
        if indirect:
            if immediate:
                output.append('ld de, (%s)' % value)
            else:
                output.append('ld de, (%s)' % value)
                output.append('call __LOAD_DE_DE')
                REQUIRES.add('lddede.asm')
        elif immediate:
            output.append('ld de, %s' % value)
        else:
            output.append('ld de, (%s)' % value)
    else:
        output.append('pop de')
        temporal = True
        if indirect:
            output.append('call __LOAD_DE_DE')
            REQUIRES.add('lddede.asm')
    if not temporal:
        output.append('call __STORE_STR')
        REQUIRES.add('storestr.asm')
    else:
        output.append('call __STORE_STR2')
        REQUIRES.add('storestr2.asm')
    return output

