def _extract_metrics(self, wmi_sampler, tag_by, tag_queries, constant_tags):
    if len(wmi_sampler) > 1 and (not tag_by):
        raise MissingTagBy(u'WMI query returned multiple rows but no `tag_by` value was given. class={wmi_class} - properties={wmi_properties} - filters={filters}'.format(wmi_class=wmi_sampler.class_name, wmi_properties=wmi_sampler.property_names, filters=wmi_sampler.filters))
    metrics = []
    tag_by = tag_by.lower()
    for wmi_obj in wmi_sampler:
        tags = list(constant_tags) if constant_tags else []
        for query in tag_queries:
            try:
                tags.append(self._get_tag_query_tag(wmi_sampler, wmi_obj, query))
            except TagQueryUniquenessFailure:
                continue
        for (wmi_property, wmi_value) in iteritems(wmi_obj):
            if wmi_property.lower() not in (s.lower() for s in wmi_sampler.property_names):
                continue
            if wmi_property == tag_by:
                tag_value = str(wmi_value).lower()
                if tag_queries and tag_value.find('#') > 0:
                    tag_value = tag_value[:tag_value.find('#')]
                tags.append('{name}:{value}'.format(name=tag_by, value=tag_value))
                continue
            if wmi_property == 'name':
                continue
            try:
                metrics.append(WMIMetric(wmi_property, float(wmi_value), tags))
            except ValueError:
                self.log.warning(u"When extracting metrics with WMI, found a non digit value for property '{0}'.".format(wmi_property))
                continue
            except TypeError:
                self.log.warning(u"When extracting metrics with WMI, found a missing property '{0}'".format(wmi_property))
                continue
    return metrics

