def _bulk_history_create(self, model, batch_size):
    instances = []
    history = utils.get_history_manager_for_model(model)
    if self.verbosity >= 1:
        self.stdout.write('Starting bulk creating history models for {} instances {}-{}'.format(model, 0, batch_size))
    iterator_kwargs = {'chunk_size': batch_size} if django.VERSION >= (2, 0, 0) else {}
    for (index, instance) in enumerate(model._default_manager.iterator(**iterator_kwargs)):
        if index % batch_size == 0:
            history.bulk_history_create(instances, batch_size=batch_size)
            instances = []
            if self.verbosity >= 1:
                self.stdout.write('Finished bulk creating history models for {} instances {}-{}, starting next {}'.format(model, index - batch_size, index, batch_size))
        instances.append(instance)
    if instances:
        history.bulk_history_create(instances, batch_size=batch_size)

def all_resource_urls(query):
    urls = []
    next = True
    while next:
        response = requests.get(query)
        json_data = json.loads(response.content)
        for resource in json_data['results']:
            urls.append(resource['url'])
        if bool(json_data['next']):
            query = json_data['next']
        else:
            next = False
    return urls

def set_chat_photo(self, chat_id: Union[int, str], photo: str) -> bool:
    peer = self.resolve_peer(chat_id)
    if os.path.exists(photo):
        photo = types.InputChatUploadedPhoto(file=self.save_file(photo))
    else:
        s = unpack('<qq', b64decode(photo + '=' * (-len(photo) % 4), '-_'))
        photo = types.InputChatPhoto(id=types.InputPhoto(id=s[0], access_hash=s[1], file_reference=b''))
    if isinstance(peer, types.InputPeerChat):
        self.send(functions.messages.EditChatPhoto(chat_id=peer.chat_id, photo=photo))
    elif isinstance(peer, types.InputPeerChannel):
        self.send(functions.channels.EditPhoto(channel=peer, photo=photo))
    else:
        raise ValueError('The chat_id "{}" belongs to a user'.format(chat_id))
    return True

