def _createGsshaPyObjects(self, mapTables, indexMaps, replaceParamFile, directory, session, spatial, spatialReferenceID):
    for mt in mapTables:
        try:
            if mt['indexMapName'] is not None:
                indexMaps[mt['indexMapName']]
            mapTable = MapTable(name=mt['name'], numIDs=mt['numVars']['NUM_IDS'], maxNumCells=mt['numVars']['MAX_NUMBER_CELLS'], numSed=mt['numVars'].get('NUM_SED'), numContam=mt['numVars'].get('NUM_CONTAM'), maxSoilID=mt['numVars'].get('MAX_SOIL_ID'))
            mapTable.mapTableFile = self
            if mt['indexMapName']:
                mapTable.indexMap = indexMaps[mt['indexMapName']]
            if mt['name'] == 'CONTAMINANT_TRANSPORT':
                for contam in mt['contaminants']:
                    outputBaseFilename = self._preprocessContaminantOutFilePath(contam['outPath'])
                    contaminant = MTContaminant(name=contam['name'], outputFilename=outputBaseFilename, precipConc=vrp(contam['contamVars']['PRECIP_CONC'], replaceParamFile), partition=vrp(contam['contamVars']['PARTITION'], replaceParamFile), numIDs=contam['contamVars']['NUM_IDS'])
                    indexMap = indexMaps[contam['indexMapName']]
                    contaminant.indexMap = indexMap
                    self._createValueObjects(contam['valueList'], contam['varList'], mapTable, indexMap, contaminant, replaceParamFile)
                    self._readContaminantOutputFiles(directory, outputBaseFilename, session, spatial, spatialReferenceID)
            elif mt['name'] == 'SEDIMENTS':
                for line in mt['valueList']:
                    sediment = MTSediment(description=line[0], specificGravity=vrp(line[1], replaceParamFile), particleDiameter=vrp(line[2], replaceParamFile), outputFilename=line[3])
                    sediment.mapTable = mapTable
            else:
                indexMap = indexMaps[mt['indexMapName']]
                self._createValueObjects(mt['valueList'], mt['varList'], mapTable, indexMap, None, replaceParamFile)
        except KeyError:
            log.info('Index Map "%s" for Mapping Table "%s" not found in list of index maps in the mapping table file. The Mapping Table was not read into the database.' % (mt['indexMapName'], mt['name']))

def pack_epub(directory, file):
    with zipfile.ZipFile(file, 'w', zipfile.ZIP_DEFLATED) as zippy:
        base_path = os.path.abspath(directory)
        for (root, dirs, filenames) in os.walk(directory):
            archive_path = os.path.relpath(root, base_path)
            for filename in filenames:
                filepath = os.path.join(root, filename)
                archival_filepath = os.path.join(archive_path, filename)
                zippy.write(filepath, archival_filepath)

def mag_data(hemi, retinotopy='any', surface='midgray', mask=None, weights=Ellipsis, weight_min=0, weight_transform=Ellipsis, visual_area=None, visual_area_mask=Ellipsis, eccentricity_range=None, polar_angle_range=None):
    if is_mag_data(hemi):
        return hemi
    elif pimms.is_lazy_map(hemi) and pimms.is_vector(hemi.keys(), 'int'):
        return hemi
    if mri.is_subject(hemi):
        hemi = hemi.lh.hemi.rh
    if pimms.is_vector(hemi):
        return tuple([mag_data(h, retinotopy=retinotopy, surface=surface, mask=mask, weights=weights, weight_min=weight_min, weight_transform=weight_transform, visual_area=visual_area, visual_area_mask=visual_area_mask, eccentricity_range=eccentricity_range, polar_angle_range=polar_angle_range) for h in hemi])
    mesh = geo.to_mesh((hemi, surface))
    retino = retinotopy_data(hemi, retinotopy)
    if weights is Ellipsis:
        weights = retino.get('variance_explained', None)
    mask = hemi.mask(mask, indices=True)
    (arng, erng) = (polar_angle_range, eccentricity_range)
    (ang, ecc) = (retino['polar_angle'], retino['eccentricity'])
    if pimms.is_str(arng):
        tmp = to_hemi_str(arng)
        arng = (-180, 0) if tmp == 'rh' else (0, 180) if tmp == 'lh' else (-180, 180)
    elif arng is None:
        tmp = ang[mask]
        tmp = tmp[np.isfinite(tmp)]
        arng = (np.min(tmp), np.max(tmp))
    if erng is None:
        tmp = ecc[mask]
        tmp = tmp[np.isfinite(tmp)]
        erng = (0, np.max(tmp))
    elif pimms.is_scalar(erng):
        erng = (0, erng)
    (ang, wgt) = hemi.property(retino['polar_angle'], weights=weights, weight_min=weight_min, weight_transform=weight_transform, yield_weight=True)
    ecc = hemi.property(retino['eccentricity'], weights=weights, weight_min=weight_min, weight_transform=weight_transform, data_range=erng)
    ((mn, mx), mid) = (arng, np.mean(arng))
    oks = mask[np.isfinite(ang[mask])]
    u = ang[oks]
    u = np.mod(u + 180 - mid, 360) - 180 + mid
    ang[oks[np.where((mn <= u) & (u < mx))[0]]] = np.inf
    bad = np.where(np.isinf(ang) | np.isinf(ecc))[0]
    ang[bad] = np.inf
    ecc[bad] = np.inf
    wgt[bad] = 0
    wgt *= zinv(np.sum(wgt[mask]))
    vcoords = np.asarray(as_retinotopy(retino, 'geographical'))
    scoords = mesh.coordinates
    if visual_area is Ellipsis:
        visual_area = retino.get('visual_area', None)
    if visual_area is not None:
        retino['visual_area'] = visual_area
    if wgt is not None:
        retino['weights'] = wgt
    rdata = pimms.persist(retino)
    (tmn, tmx) = [np.pi / 180.0 * u for u in arng]
    if tmx - tmn >= 2 * np.pi:
        (tmn, tmx) = (-np.pi, np.pi)
    (emn, emx) = erng
    rarea = 0.5 * (emx * emx - emn * emn) * (tmx - tmn)

    def finish_mag_data(mask):
        if len(mask) == 0:
            return None
        submesh = mesh.submesh(mask)
        mdata = pyr.pmap({k: v[mask] if pimms.is_vector(v) else v[:, mask] if pimms.is_matrix(v) else None for (k, v) in six.iteritems(rdata)})
        fs = submesh.tess.indexed_faces
        (vx, sx) = [x[:, mask] for x in (vcoords, scoords)]
        (vfx, sfx) = [np.asarray([x[:, f] for f in fs]) for x in (vx, sx)]
        (va, sa) = [geo.triangle_area(*x) for x in (vfx, sfx)]
        return pyr.m(surface_coordinates=sx, visual_coordinates=vx, surface_areas=sa, visual_areas=va, mesh=mesh, submesh=submesh, retinotopy_data=rdata, masked_data=mdata, mask=mask, area_of_range=rarea)
    if visual_area is None:
        return finish_mag_data(mask)
    visual_area = hemi.property(visual_area, mask=mask, null=0, dtype=np.int)
    vam = np.unique(visual_area) if visual_area_mask is None else np.setdiff1d(np.unique(visual_area), [0]) if visual_area_mask is Ellipsis else np.unique(list(visual_area_mask))
    return pimms.lazy_map({va: curry(finish_mag_data, mask[visual_area[mask] == va]) for va in vam})

def _check_remote_command(self, destination, timeout_ms, success_msgs=None):
    timeout = timeouts.PolledTimeout.from_millis(timeout_ms)
    stream = self._adb_connection.open_stream(destination, timeout)
    if not stream:
        raise usb_exceptions.AdbStreamUnavailableError('Service %s not supported', destination)
    try:
        message = stream.read(timeout_ms=timeout)
        if any([m in message for m in success_msgs]):
            return
    except usb_exceptions.CommonUsbError:
        if destination.startswith('reboot:'):
            return
        raise
    raise usb_exceptions.AdbRemoteError('Device message: %s', message)

def get_object_by_natural_key(self, app_label, model_name, object_id):
    try:
        model_type = ContentType.objects.get_by_natural_key(app_label, model_name)
    except ContentType.DoesNotExist:
        return None
    ModelClass = model_type.model_class()
    if not hasattr(ModelClass, 'get_absolute_url'):
        return None
    try:
        return model_type.get_object_for_this_type(pk=object_id)
    except ObjectDoesNotExist:
        return None

def any2utf8(text, errors='strict', encoding='utf8'):
    if isinstance(text, unicode):
        return text.encode('utf8')
    return unicode(text, encoding, errors=errors).encode('utf8')

