def check_format(cls, tags):
    (common, _, _) = tags
    for tag in common:
        if tag.get_type() != 0:
            return False
    return True

def request(method='GET'):

    def decorator(func):

        @functools.wraps(func)
        def action(self, *args, **kwargs):
            f = furl(self.server)
            (path, body) = func(self, *args, **kwargs)
            query = dict()
            if isinstance(path, tuple):
                (path, query) = path
            f.path.add(path)
            f.query.set(query)
            (status_code, result) = send_rest(f.url, method=method.upper(), body=body, session=self.session, headers=self.headers)
            if status_code != httplib.OK:
                self.logger.error('{impl} {url} headers: {headers}, code: {code}'.format(impl=method, url=f.url, headers=self.headers, code=status_code))
            return (status_code, result)
        return action
    return decorator

def update(self, table, values, identifier):
    assert isinstance(values, dict)
    assert isinstance(identifier, dict)
    sb = self.sql_builder().update(table)
    for (column, value) in values.iteritems():
        sb.set(column, sb.create_positional_parameter(value))
    for (column, value) in identifier.iteritems():
        func = self._expr.in_ if isinstance(value, (list, tuple)) else self._expr.eq
        sb.and_where(func(column, sb.create_positional_parameter(value)))
    return sb.execute()

def exec_cluster(config_file, cmd, docker, screen, tmux, stop, start, override_cluster_name, port_forward):
    assert not (screen and tmux), 'Can specify only one of `screen` or `tmux`.'
    config = yaml.load(open(config_file).read())
    if override_cluster_name is not None:
        config['cluster_name'] = override_cluster_name
    config = _bootstrap_config(config)
    head_node = _get_head_node(config, config_file, override_cluster_name, create_if_needed=start)
    provider = get_node_provider(config['provider'], config['cluster_name'])
    try:
        updater = NodeUpdaterThread(node_id=head_node, provider_config=config['provider'], provider=provider, auth_config=config['auth'], cluster_name=config['cluster_name'], file_mounts=config['file_mounts'], initialization_commands=[], setup_commands=[], runtime_hash='')

        def wrap_docker(command):
            container_name = config['docker']['container_name']
            if not container_name:
                raise ValueError('Docker container not specified in config.')
            return with_docker_exec([command], container_name=container_name)[0]
        cmd = wrap_docker(cmd) if docker else cmd
        if stop:
            shutdown_cmd = 'ray stop; ray teardown ~/ray_bootstrap_config.yaml --yes --workers-only'
            if docker:
                shutdown_cmd = wrap_docker(shutdown_cmd)
            cmd += '; {}; sudo shutdown -h now'.format(shutdown_cmd)
        _exec(updater, cmd, screen, tmux, expect_error=stop, port_forward=port_forward)
        if tmux or screen:
            attach_command_parts = ['ray attach', config_file]
            if override_cluster_name is not None:
                attach_command_parts.append('--cluster-name={}'.format(override_cluster_name))
            if tmux:
                attach_command_parts.append('--tmux')
            elif screen:
                attach_command_parts.append('--screen')
            attach_command = ' '.join(attach_command_parts)
            attach_info = 'Use `{}` to check on command status.'.format(attach_command)
            logger.info(attach_info)
    finally:
        provider.cleanup()

