def split_points(self, point_cloud):
    if not isinstance(point_cloud, PointCloud):
        raise ValueError('Can only split point clouds')
    above_plane = point_cloud._data - np.tile(self._x0.data, [1, point_cloud.num_points]).T.dot(self._n) > 0
    above_plane = point_cloud.z_coords > 0 & above_plane
    below_plane = point_cloud._data - np.tile(self._x0.data, [1, point_cloud.num_points]).T.dot(self._n) <= 0
    below_plane = point_cloud.z_coords > 0 & below_plane
    above_data = point_cloud.data[:, above_plane]
    below_data = point_cloud.data[:, below_plane]
    return (PointCloud(above_data, point_cloud.frame), PointCloud(below_data, point_cloud.frame))

def _merge_data(dat1, dat2):
    cnt = 0
    for key in dat1:
        flg1 = len(dat1[key]) > 0
        flg2 = len(dat2[key]) > 0
        if flg1 != flg2:
            cnt += 1
    if cnt:
        raise Warning('Cannot merge catalogues with different' + ' attributes')
        return None
    else:
        for key in dat1:
            if isinstance(dat1[key], np.ndarray):
                dat1[key] = np.concatenate((dat1[key], dat2[key]), axis=0)
            elif isinstance(dat1[key], list):
                dat1[key] += dat2[key]
            else:
                raise ValueError('Unknown type')
        return dat1

def RgbToHsl(r, g, b):
    minVal = min(r, g, b)
    maxVal = max(r, g, b)
    l = (maxVal + minVal) / 2.0
    if minVal == maxVal:
        return (0.0, 0.0, l)
    d = maxVal - minVal
    if l < 0.5:
        s = d / (maxVal + minVal)
    else:
        s = d / (2.0 - maxVal - minVal)
    (dr, dg, db) = [(maxVal - val) / d for val in (r, g, b)]
    if r == maxVal:
        h = db - dg
    elif g == maxVal:
        h = 2.0 + dr - db
    else:
        h = 4.0 + dg - dr
    h = h * 60.0 % 360.0
    return (h, s, l)

