    elif not isinstance(path, bytes):
        return six.text_type(path)
    try:
        return path.decode(_fsencoding(), 'ignore')
    except (UnicodeError, LookupError):
        return path.decode('utf8', 'ignore')

def connectToDebugger(self, debuggerPort, debugger_options=None):
    if debugger_options is None:
        debugger_options = {}
    env_key = 'PYDEVD_EXTRA_ENVS'
    if env_key in debugger_options:
        for (env_name, value) in dict_iter_items(debugger_options[env_key]):
            existing_value = os.environ.get(env_name, None)
            if existing_value:
                os.environ[env_name] = '%s%c%s' % (existing_value, os.path.pathsep, value)
            else:
                os.environ[env_name] = value
            if env_name == 'PYTHONPATH':
                sys.path.append(value)
        del debugger_options[env_key]

    def do_connect_to_debugger():
        try:
            import pydevd
            from _pydev_imps._pydev_saved_modules import threading
        except:
            traceback.print_exc()
            sys.stderr.write('pydevd is not available, cannot connect\n')
        from _pydevd_bundle.pydevd_constants import set_thread_id
        from _pydev_bundle import pydev_localhost
        set_thread_id(threading.currentThread(), 'console_main')
        VIRTUAL_FRAME_ID = '1'
        VIRTUAL_CONSOLE_ID = 'console_main'
        f = FakeFrame()
        f.f_back = None
        f.f_globals = {}
        f.f_locals = self.get_namespace()
        self.debugger = pydevd.PyDB()
        self.debugger.add_fake_frame(thread_id=VIRTUAL_CONSOLE_ID, frame_id=VIRTUAL_FRAME_ID, frame=f)
        try:
            pydevd.apply_debugger_options(debugger_options)
            self.debugger.connect(pydev_localhost.get_localhost(), debuggerPort)
            self.debugger.prepare_to_run()
            self.debugger.disable_tracing()
        except:
            traceback.print_exc()
            sys.stderr.write('Failed to connect to target debugger.\n')
        self.debugrunning = False
        try:
            import pydevconsole
            pydevconsole.set_debug_hook(self.debugger.process_internal_commands)
        except:
            traceback.print_exc()
            sys.stderr.write('Version of Python does not support debuggable Interactive Console.\n')
    self.exec_queue.put(do_connect_to_debugger)
    return ('connect complete',)

def expect_file_line_regex_match_count_to_be_between(self, regex, expected_min_count=0, expected_max_count=None, skip=None, mostly=None, null_lines_regex='^\\s*$', result_format=None, include_config=False, catch_exceptions=None, meta=None, _lines=None):
    try:
        comp_regex = re.compile(regex)
    except:
        raise ValueError('Must enter valid regular expression for regex')
    if expected_min_count != None:
        try:
            assert float(expected_min_count).is_integer()
            assert float(expected_min_count) >= 0
        except:
            raise ValueError('expected_min_count must be a non-negative                                  integer or None')
    if expected_max_count != None:
        try:
            assert float(expected_max_count).is_integer()
            assert float(expected_max_count) >= 0
        except:
            raise ValueError('expected_max_count must be a non-negative                                  integer or None')
    if expected_max_count != None and expected_min_count != None:
        try:
            assert expected_max_count >= expected_min_count
        except:
            raise ValueError('expected_max_count must be greater than or                                  equal to expected_min_count')
    if expected_max_count != None and expected_min_count != None:
        truth_list = [True if len(comp_regex.findall(line)) >= expected_min_count and len(comp_regex.findall(line)) <= expected_max_count else False for line in _lines]
    elif expected_max_count != None:
        truth_list = [True if len(comp_regex.findall(line)) <= expected_max_count else False for line in _lines]
    elif expected_min_count != None:
        truth_list = [True if len(comp_regex.findall(line)) >= expected_min_count else False for line in _lines]
    else:
        truth_list = [True for line in _lines]
    return truth_list

