def integer_entry(self, prompt, message=None, min=None, max=None, rofi_args=None, **kwargs):
    if min is not None and max is not None and (not max > min):
        raise ValueError('Maximum limit has to be more than the minimum limit.')

    def integer_validator(text):
        error = None
        try:
            value = int(text)
        except ValueError:
            return (None, 'Please enter an integer value.')
        if min is not None and value < min:
            return (None, 'The minimum allowable value is {0:d}.'.format(min))
        if max is not None and value > max:
            return (None, 'The maximum allowable value is {0:d}.'.format(max))
        return (value, None)
    return self.generic_entry(prompt, integer_validator, message, rofi_args, **kwargs)

def handleTickSize(self, msg):
    if msg.size < 0:
        return
    df2use = self.marketData
    if self.contracts[msg.tickerId].m_secType in ('OPT', 'FOP'):
        df2use = self.optionsData
    if msg.tickerId not in df2use.keys():
        df2use[msg.tickerId] = df2use[0].copy()
    if msg.field == dataTypes['FIELD_BID_SIZE']:
        df2use[msg.tickerId]['bidsize'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_ASK_SIZE']:
        df2use[msg.tickerId]['asksize'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_LAST_SIZE']:
        df2use[msg.tickerId]['lastsize'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_OPEN_INTEREST']:
        df2use[msg.tickerId]['oi'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_OPTION_CALL_OPEN_INTEREST'] and self.contracts[msg.tickerId].m_right == 'CALL':
        df2use[msg.tickerId]['oi'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_OPTION_PUT_OPEN_INTEREST'] and self.contracts[msg.tickerId].m_right == 'PUT':
        df2use[msg.tickerId]['oi'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_VOLUME']:
        df2use[msg.tickerId]['volume'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_OPTION_CALL_VOLUME'] and self.contracts[msg.tickerId].m_right == 'CALL':
        df2use[msg.tickerId]['volume'] = int(msg.size)
    elif msg.field == dataTypes['FIELD_OPTION_PUT_VOLUME'] and self.contracts[msg.tickerId].m_right == 'PUT':
        df2use[msg.tickerId]['volume'] = int(msg.size)
    self.ibCallback(caller='handleTickSize', msg=msg)

