def ph_supconj(b, orbit, solve_for=None, **kwargs):
    orbit_ps = _get_system_ps(b, orbit)
    ph_supconj = orbit_ps.get_parameter(qualifier='ph_supconj')
    per0 = orbit_ps.get_parameter(qualifier='per0')
    ecc = orbit_ps.get_parameter(qualifier='ecc')
    period = orbit_ps.get_parameter(qualifier='period')
    if solve_for in [None, ph_supconj]:
        lhs = ph_supconj
        true_anom_supconj = -1 * (per0 - 360 * u.deg)
        rhs = _true_anom_to_phase(true_anom_supconj, period, ecc, per0)
    else:
        raise NotImplementedError
    return (lhs, rhs, {'orbit': orbit})

def has_transition_perm(bound_method, user):
    if not hasattr(bound_method, '_django_fsm'):
        im_func = getattr(bound_method, 'im_func', getattr(bound_method, '__func__'))
        raise TypeError('%s method is not transition' % im_func.__name__)
    meta = bound_method._django_fsm
    im_self = getattr(bound_method, 'im_self', getattr(bound_method, '__self__'))
    current_state = meta.field.get_state(im_self)
    return meta.has_transition(current_state) and meta.conditions_met(im_self, current_state) and meta.has_transition_perm(im_self, current_state, user)

def compare_electron_shells(shell1, shell2, compare_meta=False, rel_tol=0.0):
    if shell1['angular_momentum'] != shell2['angular_momentum']:
        return False
    tmp1 = list(zip(shell1['exponents'], *shell1['coefficients']))
    tmp2 = list(zip(shell2['exponents'], *shell2['coefficients']))
    tmp1 = sorted(tmp1)
    tmp2 = sorted(tmp2)
    if not _compare_matrix(tmp1, tmp2, rel_tol):
        return False
    if compare_meta:
        if shell1['region'] != shell2['region']:
            return False
        if shell1['function_type'] != shell2['function_type']:
            return False
        return True
    else:
        return True

