def mill(self):
    reap_vars_string = ''
    for name in self.reap_vars:
        reap_vars_string += " '" + name + "' : self." + name + ','
    const_vars_string = ''
    for name in self.const_vars:
        const_vars_string += " '" + name + "' : self." + name + ','
    mill_dict = eval('{' + reap_vars_string + const_vars_string + '}')
    product = self.millRule(**mill_dict)
