    cmd_args = [self.python, '-c', 'import json, sys; print(json.dumps(sys.path))']
    (path, _) = vistir.misc.run(cmd_args, return_object=False, nospin=True, block=True, combine_stderr=False, write_to_stdout=False)
    try:
        path = json.loads(path.strip())
    except JSONDecodeError:
        path = sys.path
    return path

def check_partition_status(method, uri, partition, valid_statuses=None, invalid_statuses=None):
    status = partition.properties.get('status', None)
    if status is None:
        return
    if valid_statuses and status not in valid_statuses or (invalid_statuses and status in invalid_statuses):
        if uri.startswith(partition.uri):
            raise ConflictError(method, uri, reason=1, message='The operation cannot be performed because the targeted partition {} has a status that is not valid for the operation: {}'.format(partition.name, status))
        else:
            raise ConflictError(method, uri, reason=1, message='The operation cannot be performed because partition {} hosting the targeted resource has a status that is not valid for the operation: {}'.format(partition.name, status))

