    if rup.mag <= C['Mh']:
        return C['e1'] * U + C['e2'] * SS + C['e3'] * NS + C['e4'] * RS + C['e5'] * (rup.mag - C['Mh']) + C['e6'] * (rup.mag - C['Mh']) ** 2
