    def adjoin(attrs):
        return txt.write('\n'.join((x.get_normalized_definition() for x in attrs)) + '\n')
    if self.kind == CompoundType.KIND_SERVICE:
        if self.request_union:
            txt.write('\n@union\n')
        adjoin(self.request_fields)
        txt.write('\n---\n')
        if self.response_union:
            txt.write('\n@union\n')
        adjoin(self.response_fields)
    elif self.kind == CompoundType.KIND_MESSAGE:
        if self.union:
            txt.write('\n@union\n')
        adjoin(self.fields)
    else:
        error('Compound type of unknown kind [%s]', self.kind)
    return txt.getvalue().strip().replace('\n\n\n', '\n').replace('\n\n', '\n')

def canon_ref(did: str, ref: str, delimiter: str=None):
    if not ok_did(did):
        raise BadIdentifier('Bad DID {} cannot act as DID document identifier'.format(did))
    if ok_did(ref):
        return 'did:sov:{}'.format(did)
    if ok_did(resource(ref, delimiter)):
        return 'did:sov:{}'.format(ref)
    if ref.startswith('did:sov:'):
        rv = ref[8:]
        if ok_did(resource(rv, delimiter)):
            return ref
        raise BadIdentifier('Bad URI {} does not correspond to a sovrin DID'.format(ref))
    if urlparse(ref).scheme:
        return ref
    return 'did:sov:{}{}{}'.format(did, delimiter if delimiter else '#', ref)

