def _parse_date_perforce(aDateString):
    _my_date_pattern = re.compile('(\\w{,3}), (\\d{,4})/(\\d{,2})/(\\d{2}) (\\d{,2}):(\\d{2}):(\\d{2}) (\\w{,3})')
    m = _my_date_pattern.search(aDateString)
    if m is None:
        return None
    (dow, year, month, day, hour, minute, second, tz) = m.groups()
    months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    dateString = '%s, %s %s %s %s:%s:%s %s' % (dow, day, months[int(month) - 1], year, hour, minute, second, tz)
    tm = rfc822.parsedate_tz(dateString)
    if tm:
        return time.gmtime(rfc822.mktime_tz(tm))

def get_arch_string():
    (rc, stdout, stderr) = exec_command('uname -sm')
    if rc > 0:
        raise AssertionError('Error checking OS')
    stdout = stdout.lower().strip()
    if not 'linux' in stdout:
        raise AssertionError('Unsupported OS')
    if 'armv7l' in stdout:
        return 'arm'
    if 'x86_64' in stdout:
        (nv_rc, nv_stdout, nv_stderr) = exec_command('nvidia-smi')
        nv_stdout = nv_stdout.lower().strip()
        if 'NVIDIA-SMI' in nv_stdout:
            return 'gpu'
        else:
            return 'cpu'
    raise AssertionError('Unsupported arch:', stdout)

def _transform(self, node):
    cls = node.__class__
    if cls not in self.transforms:
        return node
    transforms = self.transforms[cls]
    for (transform_func, predicate) in transforms:
        if predicate is None or predicate(node):
            ret = transform_func(node)
            if ret is not None:
                node = ret
            if ret.__class__ != cls:
                break
    return node

def _run_macro(self, statement: Statement) -> bool:
    from itertools import islice
    if statement.command not in self.macros.keys():
        raise KeyError('{} is not a macro'.format(statement.command))
    macro = self.macros[statement.command]
    if len(statement.arg_list) < macro.minimum_arg_count:
        self.perror("The macro '{}' expects at least {} argument(s)".format(statement.command, macro.minimum_arg_count), traceback_war=False)
        return False
    resolved = macro.value
    reverse_arg_list = sorted(macro.arg_list, key=lambda ma: ma.start_index, reverse=True)
    for arg in reverse_arg_list:
        if arg.is_escaped:
            to_replace = '{{' + arg.number_str + '}}'
            replacement = '{' + arg.number_str + '}'
        else:
            to_replace = '{' + arg.number_str + '}'
            replacement = statement.argv[int(arg.number_str)]
        parts = resolved.rsplit(to_replace, maxsplit=1)
        resolved = parts[0] + replacement + parts[1]
    for arg in islice(statement.arg_list, macro.minimum_arg_count, None):
        resolved += ' ' + arg
    return self.onecmd_plus_hooks(resolved)

