def nmltostring(nml):
    if not isinstance(nml, dict):
        raise ValueError('nml should be a dict !')
    curstr = ''
    for (key, group) in nml.items():
        namelist = ['&' + key]
        for (k, v) in group.items():
            if isinstance(v, list) or isinstance(v, tuple):
                namelist.append(k + ' = ' + ','.join(map(str, v)) + ',')
            elif is_string(v):
                namelist.append(k + " = '" + str(v) + "',")
            else:
                namelist.append(k + ' = ' + str(v) + ',')
        namelist.append('/')
        curstr = curstr + '\n'.join(namelist) + '\n'
    return curstr

def create_runscript(self, default='/bin/bash', force=False):
    entrypoint = default
    if force is False:
        if self.entrypoint is not None:
            entrypoint = ''.join(self.entrypoint)
        elif self.cmd is not None:
            entrypoint = ''.join(self.cmd)
    if not entrypoint.startswith('exec'):
        entrypoint = 'exec %s' % entrypoint
    if not re.search('"?[$]@"?', entrypoint):
        entrypoint = '%s "$@"' % entrypoint
    return entrypoint

