            tr.save()
            this_invoice = Invoice.get_or_create_from_registration(tr, submissionUser=submissionUser)
            this_description = _('Registration Payment: #%s' % tr_id)
            if not amount:
                amount = this_invoice.outstandingBalance
        elif not transactionType or not amount:
            logger.error('Insufficient information passed to createSquarePayment view.')
            messages.error(request, format_html('<p>{}</p><ul><li>{}</li></ul>', str(_('ERROR: Error with Square checkout transaction attempt.')), str(_('Insufficient information passed to createSquarePayment view.'))))
            return HttpResponseRedirect(sourceUrl)
        else:
            if transactionType == 'Gift Certificate':
                this_description = _('Gift Certificate Purchase')
            else:
                this_description = transactionType
            this_invoice = Invoice.create_from_item(float(amount), this_description, submissionUser=submissionUser, calculate_taxes=taxable is not False, transactionType=transactionType)
    except (ValueError, ObjectDoesNotExist) as e:
        logger.error('Invalid registration information passed to createSquarePayment view: (%s, %s, %s)' % (invoice_id, tr_id, amount))
        messages.error(request, format_html('<p>{}</p><ul><li>{}</li></ul>', str(_('ERROR: Error with Square checkout transaction attempt.')), str(_('Invalid registration information passed to createSquarePayment view: (%s, %s, %s)' % (invoice_id, tr_id, amount)))))
        return HttpResponseRedirect(sourceUrl)
    this_currency = getConstant('general__currencyCode')
    this_total = min(this_invoice.outstandingBalance, amount)
    api_instance = TransactionsApi()
    api_instance.api_client.configuration.access_token = getattr(settings, 'SQUARE_ACCESS_TOKEN', '')
    idempotency_key = str(uuid.uuid1())
    location_id = getattr(settings, 'SQUARE_LOCATION_ID', '')
    amount = {'amount': int(100 * this_total), 'currency': this_currency}
    body = {'idempotency_key': idempotency_key, 'card_nonce': nonce_id, 'amount_money': amount}
    errors_list = []
    try:
        api_response = api_instance.charge(location_id, body)
        if api_response.errors:
            logger.error('Error in charging Square transaction: %s' % api_response.errors)
            errors_list = api_response.errors
    except ApiException as e:
        logger.error('Exception when calling TransactionApi->charge: %s\n' % e)
        errors_list = json.loads(e.body).get('errors', [])
    if errors_list:
        this_invoice.status = Invoice.PaymentStatus.error
        this_invoice.save()
        errors_string = ''
        for err in errors_list:
            errors_string += '<li><strong>CODE:</strong> %s, %s</li>' % (err.get('code', str(_('Unknown'))), err.get('detail', str(_('Unknown'))))
        messages.error(request, format_html('<p>{}</p><ul>{}</ul>', str(_('ERROR: Error with Square checkout transaction attempt.')), mark_safe(errors_list)))
        return HttpResponseRedirect(sourceUrl)
    else:
        logger.info('Square charge successfully created.')
    transaction = api_response.transaction
    paymentRecord = SquarePaymentRecord.objects.create(invoice=this_invoice, transactionId=transaction.id, locationId=transaction.location_id)
    this_invoice.processPayment(amount=this_total, fees=0, paidOnline=True, methodName='Square Checkout', methodTxn=transaction.id, notify=customerEmail)
    updateSquareFees.schedule(args=(paymentRecord,), delay=60)
    if addSessionInfo:
        paymentSession = request.session.get(INVOICE_VALIDATION_STR, {})
        paymentSession.update({'invoiceID': str(this_invoice.id), 'amount': this_total, 'successUrl': successUrl})
        request.session[INVOICE_VALIDATION_STR] = paymentSession
    return HttpResponseRedirect(successUrl)

def read_csv(self, file_path, use_whole_file=False, names=None, skiprows=0, *args, **kwargs):

    def csv_file(partition_number, files):
        file_count = 0
        for (_, contents) in files:
            if partition_number == 0 and file_count == 0 and (_skiprows > 0):
                yield pandas.read_csv(sio(contents), *args, header=None, names=mynames, skiprows=_skiprows, **kwargs)
            else:
                file_count += 1
                yield pandas.read_csv(sio(contents), *args, header=None, names=mynames, **kwargs)

    def csv_rows(partition_number, rows):
        in_str = '\n'.join(rows)
        if partition_number == 0:
            return iter([pandas.read_csv(sio(in_str), *args, header=None, names=mynames, skiprows=_skiprows, **kwargs)])
        else:
            return iter([pandas.read_csv(sio(in_str), *args, header=None, names=mynames, **kwargs)])
    mynames = None
    _skiprows = skiprows
    if names:
        mynames = names
    else:
        first_line = self.spark_ctx.textFile(file_path).first()
        frame = pandas.read_csv(sio(first_line), **kwargs)
        mynames = list(frame.columns)
        _skiprows += 1
    if use_whole_file:
        return self.from_pandas_rdd(self.spark_ctx.wholeTextFiles(file_path).mapPartitionsWithIndex(csv_file))
    else:
        return self.from_pandas_rdd(self.spark_ctx.textFile(file_path).mapPartitionsWithIndex(csv_rows))

def supports_py3(project_name):
    log = logging.getLogger('ciu')
    log.info('Checking {} ...'.format(project_name))
    request = requests.get('https://pypi.org/pypi/{}/json'.format(project_name))
    if request.status_code >= 400:
        log = logging.getLogger('ciu')
        log.warning('problem fetching {}, assuming ported ({})'.format(project_name, request.status_code))
        return True
    response = request.json()
    return any((c.startswith('Programming Language :: Python :: 3') for c in response['info']['classifiers']))

