def get_Sb(data):
    (Sb, N) = (0.0, 0.0)
    for rec in data:
        delta = 90.0 - abs(rec['vgp_lat'])
        if rec['average_k'] != 0:
            k = rec['average_k']
            L = rec['average_lat'] * np.pi / 180.0
            Nsi = rec['average_nn']
            K = old_div(k, 2.0 * (1.0 + 3.0 * np.sin(L) ** 2) / (5.0 - 3.0 * np.sin(L) ** 2))
            Sw = old_div(81.0, np.sqrt(K))
        else:
            (Sw, Nsi) = (0, 1.0)
        Sb += delta ** 2.0 - old_div(Sw ** 2, Nsi)
        N += 1.0
    return np.sqrt(old_div(Sb, float(N - 1.0)))

def loadable(func_name):

    def inner(func):
        cached_name = '_' + func.__name__

        @functools.wraps(func)
        def _decorator(self, *args, **kwargs):
            if getattr(self, cached_name) is None:
                getattr(self, func_name)()
            return func(self, *args, **kwargs)
        return _decorator
    return inner

