def autofocus_stack(fieldstack, nm, res, ival, roi=None, metric='average gradient', padding=True, same_dist=False, ret_ds=False, ret_grads=False, num_cpus=_cpu_count, copy=True):
    dopt = list()
    grad = list()
    M = fieldstack.shape[0]
    stackargs = list()
    for s in range(M):
        stackargs.append([fieldstack[s].copy(copy), nm, res, ival, roi, metric, padding, True, True, 1])
    p = mp.Pool(num_cpus)
    result = p.map_async(_autofocus_wrapper, stackargs).get()
    p.close()
    p.terminate()
    p.join()
    newstack = np.zeros(fieldstack.shape, dtype=fieldstack.dtype)
    for s in range(M):
        (field, ds, gs) = result[s]
        dopt.append(ds)
        grad.append(gs)
        newstack[s] = field
    if same_dist:
        davg = np.average(dopt)
        newstack = refocus_stack(fieldstack, davg, nm, res, num_cpus=num_cpus, copy=copy, padding=padding)
    ret_list = [newstack]
    if ret_ds:
        ret_list += [dopt]
    if ret_grads:
        ret_list += [grad]
    if len(ret_list) == 1:
        return ret_list[0]
    else:
        return tuple(ret_list)

