def sort_dict(d: dict, by: str='key', allow_duplicates: bool=True) -> collections.OrderedDict:
    if by == 'key':
        i = 0
    elif by == 'value':
        values = list(d.values())
        if len(values) != len(set(values)) and (not allow_duplicates):
            duplicates = find_duplicates(values)
            raise ValueError('There are duplicates in the values: {}'.format(duplicates))
        i = 1
    else:
        raise ValueError("by can be 'key' or 'value'.")
    return collections.OrderedDict(sorted(d.items(), key=lambda t: t[i]))

def retry_until_valid_or_limit_reached(method, limit, validation_fn, sleep_s=1, catch_exceptions=()):
    assert limit > 0, 'Limit must be greater than 0'

    def _execute_method(helper):
        try:
            return method()
        except catch_exceptions:
            if not helper.remaining:
                raise
            return None
    helper = RetryHelper(limit - 1)
    result = _execute_method(helper)
    while not validation_fn(result) and helper.retry_if_possible():
        time.sleep(sleep_s)
        result = _execute_method(helper)
    return result

