def commit(self):
    if self._meta.path:
        with open(self._meta.path, 'wb') as fd:
            raw = deepcopy(self.raw)
            lazy_indexes = self.lazy_indexes
            if not self._meta.lazy_indexes:
                for idx_name in lazy_indexes:
                    del raw['indexes'][idx_name]
                for (index_name, values) in raw['indexes'].items():
                    for (value, keys) in values.items():
                        raw['indexes'][index_name][value] = list(keys)
            if not raw['indexes'] or self._meta.lazy_indexes:
                del raw['indexes']
            try:
                fd.write(six.u(self.serialize(raw)))
            except TypeError:
                fd.write(six.b(self.serialize(raw)))

def resolve(self, pid_value):
    pid = PersistentIdentifier.get(self.pid_type, pid_value)
    if pid.is_new() or pid.is_reserved():
        raise PIDUnregistered(pid)
    if pid.is_deleted():
        obj_id = pid.get_assigned_object(object_type=self.object_type)
        try:
            obj = self.object_getter(obj_id) if obj_id else None
        except NoResultFound:
            obj = None
        raise PIDDeletedError(pid, obj)
    if pid.is_redirected():
        raise PIDRedirectedError(pid, pid.get_redirect())
    obj_id = pid.get_assigned_object(object_type=self.object_type)
    if not obj_id:
        raise PIDMissingObjectError(self.pid_type, pid_value)
    return (pid, self.object_getter(obj_id))

def __recieve_chunk(self):
    if self.__response == const.CMD_DATA:
        if self.tcp:
            if self.verbose:
                print('_rc_DATA! is {} bytes, tcp length is {}'.format(len(self.__data), self.__tcp_length))
            if len(self.__data) < self.__tcp_length - 8:
                need = self.__tcp_length - 8 - len(self.__data)
                if self.verbose:
                    print('need more data: {}'.format(need))
                more_data = self.__recieve_raw_data(need)
                return b''.join([self.__data, more_data])
            else:
                if self.verbose:
                    print('Enough data')
                return self.__data
        else:
            if self.verbose:
                print('_rc len is {}'.format(len(self.__data)))
            return self.__data
    elif self.__response == const.CMD_PREPARE_DATA:
        data = []
        size = self.__get_data_size()
        if self.verbose:
            print('recieve chunk: prepare data size is {}'.format(size))
        if self.tcp:
            if len(self.__data) >= 8 + size:
                data_recv = self.__data[8:]
            else:
                data_recv = self.__data[8:] + self.__sock.recv(size + 32)
            (resp, broken_header) = self.__recieve_tcp_data(data_recv, size)
            data.append(resp)
            if len(broken_header) < 16:
                data_recv = broken_header + self.__sock.recv(16)
            else:
                data_recv = broken_header
            if len(data_recv) < 16:
                print('trying to complete broken ACK %s /16' % len(data_recv))
                if self.verbose:
                    print(data_recv.encode('hex'))
                data_recv += self.__sock.recv(16 - len(data_recv))
            if not self.__test_tcp_top(data_recv):
                if self.verbose:
                    print('invalid chunk tcp ACK OK')
                return None
            response = unpack('HHHH', data_recv[8:16])[0]
            if response == const.CMD_ACK_OK:
                if self.verbose:
                    print('chunk tcp ACK OK!')
                return b''.join(data)
            if self.verbose:
                print('bad response %s' % data_recv)
            if self.verbose:
                print(codecs.encode(data, 'hex'))
            return None
            return resp
        while True:
            data_recv = self.__sock.recv(1024 + 8)
            response = unpack('<4H', data_recv[:8])[0]
            if self.verbose:
                print('# packet response is: {}'.format(response))
            if response == const.CMD_DATA:
                data.append(data_recv[8:])
                size -= 1024
            elif response == const.CMD_ACK_OK:
                break
            else:
                if self.verbose:
                    print('broken!')
                break
            if self.verbose:
                print('still needs %s' % size)
        return b''.join(data)
    else:
        if self.verbose:
            print('invalid response %s' % self.__response)
        return None

