def read_tex(src):
    c = next(src)
    if c.startswith('%'):
        return c
    elif c.startswith('$'):
        name = '$$' if c.startswith('$$') else '$'
        expr = TexEnv(name, [], nobegin=True)
        return read_math_env(src, expr)
    elif c.startswith('\\[') or c.startswith('\\('):
        if c.startswith('\\['):
            name = 'displaymath'
            begin = '\\['
            end = '\\]'
        else:
            name = 'math'
            begin = '\\('
            end = '\\)'
        expr = TexEnv(name, [], nobegin=True, begin=begin, end=end)
        return read_math_env(src, expr)
    elif c.startswith('\\'):
        command = TokenWithPosition(c[1:], src.position)
        if command == 'item':
            (contents, arg) = read_item(src)
            (mode, expr) = ('command', TexCmd(command, contents, arg))
        elif command == 'begin':
            (mode, expr, _) = ('begin', TexEnv(src.peek(1)), src.forward(3))
        else:
            (mode, expr) = ('command', TexCmd(command))
        expr.args = read_args(src, expr.args)
        if mode == 'begin':
            read_env(src, expr)
        return expr
    if c in ARG_START_TOKENS:
        return read_arg(src, c)
    return c

def UnitToLNode(u: Unit, node: Optional[LNode]=None, toL: Optional[dict]=None, optimizations=[]) -> LNode:
    if toL is None:
        toL = {}
    if node is None:
        root = LNode(name=u._name, originObj=u, node2lnode=toL)
    else:
        root = node
    stmPorts = {}
    netCtx = NetCtxs(root)
    for su in u._units:
        n = root.addNode(name=su._name, originObj=su)
        UnitToLNode(su, n, toL, optimizations)
    for stm in u._ctx.statements:
        n = addStmAsLNode(root, stm, stmPorts, netCtx)
    for intf in u._interfaces:
        addPort(root, intf)
    for stm in u._ctx.statements:
        n = toL.get(stm, None)
        if n is not None:
            if isinstance(n, VirtualLNode):
                p = None
            else:
                p = stmPorts[n]
            r = StatementRenderer(n, toL, p, netCtx)
            r.renderContent()
    for s in u._ctx.signals:
        if not s.hidden:
            (net, _) = netCtx.getDefault(s)
            for e in s.endpoints:
                if isinstance(e, PortItem):
                    net.addEndpoint(toL[e])
            for d in s.drivers:
                if isinstance(d, PortItem):
                    net.addDriver(toL[d])
    netCtx.applyConnections(root)
    for opt in optimizations:
        opt(root)
    isRootOfWholeGraph = root.parent is None
    if not isRootOfWholeGraph:
        for intf in u._interfaces:
            ext_p = toL[originObjOfPort(intf)].parentNode
            nodePort = addPortToLNode(root, intf)
            if intf._direction == INTF_DIRECTION.SLAVE:
                src = nodePort
                dst = ext_p.addPort('', PortType.INPUT, PortSide.WEST)
            else:
                src = ext_p.addPort('', PortType.OUTPUT, PortSide.EAST)
                dst = nodePort
            root.addEdge(src, dst, name=repr(intf), originObj=intf)
    return root

def inventory(self, source_id, fetch=False, fmt='table'):
    data_tables = {}
    t = self.query("SELECT * FROM sqlite_master WHERE type='table'", fmt='table')
    all_tables = t['name'].tolist()
    for table in ['sources'] + [t for t in all_tables if t not in ['sources', 'sqlite_sequence']]:
        try:
            t = self.query('PRAGMA table_info({})'.format(table), fmt='table')
            columns = np.array(t['name'])
            types = np.array(t['type'])
            if table == 'sources' or 'source_id' in columns:
                if not fetch:
                    columns = columns[((types == 'REAL') | (types == 'INTEGER') | (types == 'TEXT')) & (columns != 'source_id')]
                try:
                    id = 'id' if table.lower() == 'sources' else 'source_id'
                    data = self.query('SELECT {} FROM {} WHERE {}={}'.format(','.join(columns), table, id, source_id), fmt='table')
                    if not data and table.lower() == 'sources':
                        print('No source with id {}. Try db.search() to search the database for a source_id.'.format(source_id))
                except:
                    data = None
                if data:
                    if fetch:
                        data_tables[table] = self.query('SELECT {} FROM {} WHERE {}={}'.format(','.join(columns), table, id, source_id), fetch=True, fmt=fmt)
                    else:
                        data = data[[c.lower() for c in columns]]
                        pprint(data, title=table.upper())
            else:
                pass
        except:
            print('Could not retrieve data from {} table.'.format(table.upper()))
    if fetch:
        return data_tables

def pyquil_to_circuit(program: pyquil.Program) -> Circuit:
    circ = Circuit()
    for inst in program.instructions:
        if isinstance(inst, pyquil.Declare):
            continue
        if isinstance(inst, pyquil.Halt):
            continue
        if isinstance(inst, pyquil.Pragma):
            continue
        elif isinstance(inst, pyquil.Measurement):
            circ += Measure(inst.qubit.index)
        elif isinstance(inst, pyquil.Gate):
            defgate = STDGATES[inst.name]
            gate = defgate(*inst.params)
            qubits = [q.index for q in inst.qubits]
            gate = gate.relabel(qubits)
            circ += gate
        else:
            raise ValueError('PyQuil program is not protoquil')
    return circ

