def update(cls, content, dependency, version, spec='==', hashes=()):
    new_line = '{name}{spec}{version}'.format(name=dependency.full_name, spec=spec, version=version)
    appendix = ''
    if ';' in dependency.line:
        new_line += ';' + dependency.line.splitlines()[0].split(';', 1)[1].split('#')[0].split('--hash')[0].rstrip()
    if '#' in dependency.line:
        parts = dependency.line.split('#')
        (requirement, comment) = (parts[0], '#'.join(parts[1:]))
        whitespaces = (hex(ord('\t')), hex(ord(' ')))
        trailing_whitespace = ''
        for c in requirement[::-1]:
            if hex(ord(c)) in whitespaces:
                trailing_whitespace += c
            else:
                break
        appendix += trailing_whitespace + '#' + comment
    if dependency.hashes and (not new_line.endswith('\\')):
        new_line += ' \\'
    if hashes:
        for (n, new_hash) in enumerate(hashes):
            new_line += '\n    --hash={method}:{hash}'.format(method=new_hash['method'], hash=new_hash['hash'])
            if len(hashes) > n + 1:
                new_line += ' \\'
    new_line += appendix
    regex = cls.SUB_REGEX.format(re.escape(dependency.line))
    return re.sub(regex, new_line, content, flags=re.MULTILINE)

def bind(self, ctx, args, args_grad=None, grad_req='write', aux_states=None, group2ctx=None, shared_exec=None):
    if not isinstance(ctx, Context):
        raise TypeError('Context type error')
    listed_arguments = self.list_arguments()
    (args_handle, args) = self._get_ndarray_inputs('args', args, listed_arguments, False)
    if args_grad is None:
        args_grad_handle = c_array(NDArrayHandle, [None] * len(args))
    else:
        (args_grad_handle, args_grad) = self._get_ndarray_inputs('args_grad', args_grad, listed_arguments, True)
    if aux_states is None:
        aux_states = []
    (aux_args_handle, aux_states) = self._get_ndarray_inputs('aux_states', aux_states, self.list_auxiliary_states(), False)
    if isinstance(grad_req, string_types):
        if grad_req not in _GRAD_REQ_MAP:
            raise ValueError('grad_req must be in %s' % str(_GRAD_REQ_MAP))
        reqs_array = c_array_buf(mx_uint, array('I', [_GRAD_REQ_MAP[grad_req]] * len(listed_arguments)))
    elif isinstance(grad_req, list):
        reqs_array = c_array_buf(mx_uint, array('I', [_GRAD_REQ_MAP[item] for item in grad_req]))
    elif isinstance(grad_req, dict):
        req_array = []
        for name in listed_arguments:
            if name in grad_req:
                req_array.append(_GRAD_REQ_MAP[grad_req[name]])
            else:
                req_array.append(0)
        reqs_array = c_array_buf(mx_uint, array('I', req_array))
    ctx_map_keys = []
    ctx_map_dev_types = []
    ctx_map_dev_ids = []
    if group2ctx:
        for (key, val) in group2ctx.items():
            ctx_map_keys.append(key)
            ctx_map_dev_types.append(val.device_typeid)
            ctx_map_dev_ids.append(val.device_id)
    handle = ExecutorHandle()
    shared_handle = shared_exec.handle if shared_exec is not None else ExecutorHandle()
    check_call(_LIB.MXExecutorBindEX(self.handle, ctypes.c_int(ctx.device_typeid), ctypes.c_int(ctx.device_id), mx_uint(len(ctx_map_keys)), c_str_array(ctx_map_keys), c_array_buf(ctypes.c_int, array('i', ctx_map_dev_types)), c_array_buf(ctypes.c_int, array('i', ctx_map_dev_ids)), mx_uint(len(args)), args_handle, args_grad_handle, reqs_array, mx_uint(len(aux_states)), aux_args_handle, shared_handle, ctypes.byref(handle)))
    executor = Executor(handle, self, ctx, grad_req, group2ctx)
    executor.arg_arrays = args
    executor.grad_arrays = args_grad
    executor.aux_arrays = aux_states
    return executor

