def _mmc_loop(self, rounds, temp=298.15, verbose=True):
    current_round = 0
    while current_round < rounds:
        modifiable = list(filter(lambda p: p.parameter_type is not MMCParameterType.STATIC_VALUE, self.current_parameters))
        chosen_parameter = random.choice(modifiable)
        if chosen_parameter.parameter_type is MMCParameterType.UNIFORM_DIST:
            chosen_parameter.randomise_proposed_value()
        else:
            chosen_parameter.randomise_proposed_value()
        proposed_parameters = [p.current_value if p.proposed_value is None else p.proposed_value for p in self.current_parameters]
        model = self.specification(*proposed_parameters)
        model.pack_new_sequences(self.sequences)
        proposed_energy = self.eval_function(model)
        if verbose:
            sys.stdout.write('\rRound: {}, Current energy: {}, Proposed energy: {} (best {}), {}.       '.format(current_round, float_f(self.current_energy), float_f(proposed_energy), float_f(self.best_energy), 'ACCEPTED' if self.check_move(proposed_energy, self.current_energy, t=temp) else 'DECLINED'))
            sys.stdout.flush()
        if self.check_move(proposed_energy, self.current_energy, t=temp):
            for p in self.current_parameters:
                p.accept_proposed_value()
            self.current_energy = proposed_energy
            if self.current_energy < self.best_energy:
                self.best_energy = copy.deepcopy(self.current_energy)
                self.best_parameters = copy.deepcopy(self.current_parameters)
                self.best_model = model
        else:
            for p in self.current_parameters:
                p.reject_proposed_value()
        current_round += 1
    return

def run(self):
    document = self.state.document
    if not document.settings.file_insertion_enabled:
        return [document.reporter.warning('File insertion disabled', line=self.lineno)]
    try:
        location = self.state_machine.get_source_and_line(self.lineno)
        url = self.arguments[0]
        reader = RemoteCodeBlockReader(url, self.options, self.config)
        (text, lines) = reader.read(location=location)
        retnode = nodes.literal_block(text, text)
        set_source_info(self, retnode)
        if self.options.get('diff'):
            retnode['language'] = 'udiff'
        elif 'language' in self.options:
            retnode['language'] = self.options['language']
        retnode['linenos'] = 'linenos' in self.options or 'lineno-start' in self.options or 'lineno-match' in self.options
        retnode['classes'] += self.options.get('class', [])
        extra_args = retnode['highlight_args'] = {}
        if 'emphasize-lines' in self.options:
            hl_lines = parselinenos(self.options['emphasize-lines'], lines)
            if any((i >= lines for i in hl_lines)):
                logger.warning('line number spec is out of range(1-%d): %r' % (lines, self.options['emphasize-lines']), location=location)
            extra_args['hl_lines'] = [x + 1 for x in hl_lines if x < lines]
        extra_args['linenostart'] = reader.lineno_start
        if 'caption' in self.options:
            caption = self.options['caption'] or self.arguments[0]
            retnode = container_wrapper(self, retnode, caption)
        self.add_name(retnode)
        return [retnode]
    except Exception as exc:
        return [document.reporter.warning(str(exc), line=self.lineno)]

def _determineLength(self, fObj):
    try:
        seek = fObj.seek
        tell = fObj.tell
    except AttributeError:
        return UNKNOWN_LENGTH
    originalPosition = tell()
    seek(0, self._SEEK_END)
    end = tell()
    seek(originalPosition, self._SEEK_SET)
    return end - originalPosition

def get_api_key(client, username, secret):
    if len(secret) == 64:
        try:
            client['Account'].getCurrentUser()
            return secret
        except SoftLayer.SoftLayerAPIError as ex:
            if 'invalid api token' not in ex.faultString.lower():
                raise
    else:
        client.authenticate_with_password(username, secret)
        user_record = client['Account'].getCurrentUser(mask='id, apiAuthenticationKeys')
        api_keys = user_record['apiAuthenticationKeys']
        if len(api_keys) == 0:
            return client['User_Customer'].addApiAuthenticationKey(id=user_record['id'])
        return api_keys[0]['authenticationKey']

def execute_streaming_ingest(self, database, table, stream, stream_format, mapping_name=None, accept=None, accept_encoding='gzip,deflate', connection='Keep-Alive', content_length=None, content_encoding=None, expect=None):
    request_params = {'streamFormat': stream_format}
    if stream_format in self._mapping_required_formats and mapping_name is not None:
        request_params['mappingName'] = mapping_name
    request_headers = {'Accept-Encoding': accept_encoding, 'Connection': connection, 'x-ms-client-version': 'Kusto.Python.StreamingClient:' + VERSION, 'x-ms-client-request-id': 'KPSC.execute;' + str(uuid.uuid4()), 'Host': self._streaming_ingest_endpoint.split('/')[2]}
    if accept is not None:
        request_headers['Accept'] = accept
    if content_encoding is not None:
        request_headers['Content-Encoding'] = content_encoding
    if expect is not None:
        request_headers['Expect'] = expect
    if content_length is not None:
        request_headers['Content-Length'] = str(content_length)
    if self._auth_provider:
        request_headers['Authorization'] = self._auth_provider.acquire_authorization_header()
    response = self._session.post(self._streaming_ingest_endpoint + database + '/' + table, params=request_params, headers=request_headers, data=stream, timeout=KustoClient._query_default_timeout)
    if response.status_code == 200:
        return KustoResponseDataSetV1(response.json())
    raise KustoServiceError([response.content], response)

