def _permute_two_sample_iscs(iscs, group_parameters, i, pairwise=False, summary_statistic='median', exact_permutations=None, prng=None):
    if exact_permutations:
        group_shuffler = np.array(exact_permutations[i])
    elif not exact_permutations and pairwise:
        group_shuffler = prng.permutation(np.arange(len(np.array(group_parameters['group_assignment'])[group_parameters['sorter']])))
    elif not exact_permutations and (not pairwise):
        group_shuffler = prng.permutation(np.arange(len(group_parameters['group_assignment'])))
    if pairwise:
        group_shuffled = group_parameters['group_matrix'][group_shuffler, :][:, group_shuffler]
        group_selector = squareform(group_shuffled[group_parameters['unsorter'], :][:, group_parameters['unsorter']], checks=False)
    elif not pairwise:
        group_selector = np.array(group_parameters['group_assignment'])[group_shuffler]
    isc_sample = compute_summary_statistic(iscs[group_selector == group_parameters['group_labels'][0], :], summary_statistic=summary_statistic, axis=0) - compute_summary_statistic(iscs[group_selector == group_parameters['group_labels'][1], :], summary_statistic=summary_statistic, axis=0)
    return isc_sample

