def iter_poll(self, query_id=None, sequence_no=None, params=None, **kwargs):
    while True:
        r = self.poll(query_id, sequence_no, params, enforce_json=True, **kwargs)
        if r.json()['queryStatus'] == 'FINISHED':
            if sequence_no is not None:
                sequence_no += 1
            else:
                sequence_no = 1
            yield r
        elif r.json()['queryStatus'] == 'JOB_FINISHED':
            yield r
            break
        elif r.json()['queryStatus'] == 'JOB_FAILED':
            yield r
            break
        elif r.json()['queryStatus'] == 'RUNNING':
            yield r
            time.sleep(1)
        else:
            raise PanCloudError('Bad queryStatus: %s' % r.json()['queryStatus'])

