def schema(ds):
    (tables, ref_tables) = ({}, {})
    table_lookup = {t.url.string: t for t in ds.tables if ds.get_tabletype(t)}
    for table in table_lookup.values():
        spec = TableSpec(ds.get_tabletype(table))
        spec.primary_key = [c for c in table.tableSchema.columns if c.propertyUrl and c.propertyUrl.uri == term_uri('id')][0].name
        if spec.name in PROPERTY_URL_TO_COL:
            spec.primary_key = PROPERTY_URL_TO_COL[spec.name][term_uri('id')]
        for c in table.tableSchema.columns:
            if c.propertyUrl and c.propertyUrl.uri == term_uri('source'):
                otype = ds.get_tabletype(table).replace('Table', '')
                ref_tables[ds.get_tabletype(table)] = TableSpec('{0}Source'.format(otype), [ColSpec(otype + '_ID'), ColSpec('Source_ID'), ColSpec('Context')], [(['dataset_ID', otype + '_ID'], ds.get_tabletype(table), ['dataset_ID', spec.primary_key]), (['dataset_ID', 'Source_ID'], 'SourceTable', ['dataset_ID', 'ID'])], c.name)
            else:
                cname = c.header
                if c.propertyUrl and spec.name in PROPERTY_URL_TO_COL:
                    if c.propertyUrl.uri in PROPERTY_URL_TO_COL[spec.name]:
                        cname = PROPERTY_URL_TO_COL[spec.name][c.propertyUrl.uri]
                spec.columns.append(ColSpec(cname, c.datatype.base if c.datatype else c.datatype, c.separator, cname == spec.primary_key, cldf_name=c.header))
        for fk in table.tableSchema.foreignKeys:
            if fk.reference.schemaReference:
                continue
            ref = table_lookup[fk.reference.resource.string]
            ref_type = ds.get_tabletype(ref)
            if ref_type:
                colRefs = sorted(fk.columnReference)
                if spec.name in PROPERTY_URL_TO_COL:
                    colRefs = []
                    for c in sorted(fk.columnReference):
                        c = ds[spec.name, c]
                        if c.propertyUrl and c.propertyUrl.uri in PROPERTY_URL_TO_COL[spec.name]:
                            colRefs.append(PROPERTY_URL_TO_COL[spec.name][c.propertyUrl.uri])
                        else:
                            colRefs.append(c.header)
                rcolRefs = sorted(fk.reference.columnReference)
                if ref_type in PROPERTY_URL_TO_COL:
                    rcolRefs = []
                    for c in sorted(fk.reference.columnReference):
                        c = ds[ref_type, c]
                        if c.propertyUrl and c.propertyUrl.uri in PROPERTY_URL_TO_COL[ref_type]:
                            rcolRefs.append(PROPERTY_URL_TO_COL[ref_type][c.propertyUrl.uri])
                        else:
                            rcolRefs.append(c.header)
                spec.foreign_keys.append((tuple(['dataset_ID'] + colRefs), ds.get_tabletype(table_lookup[fk.reference.resource.string]), tuple(['dataset_ID'] + rcolRefs)))
        tables[spec.name] = spec
    ordered = OrderedDict()
    i = 0
    while tables and i < 100:
        i += 1
        for table in list(tables.keys()):
            if all((ref[1] in ordered for ref in tables[table].foreign_keys)):
                ordered[table] = tables.pop(table)
                break
    if tables:
        raise ValueError('there seem to be cyclic dependencies between the tables')
    return (list(ordered.values()), ref_tables)

def analyze(problem, Y, M=4, print_to_console=False, seed=None):
    if seed:
        np.random.seed(seed)
    D = problem['num_vars']
    if Y.size % D == 0:
        N = int(Y.size / D)
    else:
        print('\n            Error: Number of samples in model output file must be a multiple of D,\n            where D is the number of parameters in your parameter file.\n          ')
        exit()
    omega = np.zeros([D])
    omega[0] = math.floor((N - 1) / (2 * M))
    m = math.floor(omega[0] / (2 * M))
    if m >= D - 1:
        omega[1:] = np.floor(np.linspace(1, m, D - 1))
    else:
        omega[1:] = np.arange(D - 1) % m + 1
    if print_to_console:
        print('Parameter First Total')
    Si = ResultDict(((k, [None] * D) for k in ['S1', 'ST']))
    Si['names'] = problem['names']
    for i in range(D):
        l = np.arange(i * N, (i + 1) * N)
        Si['S1'][i] = compute_first_order(Y[l], N, M, omega[0])
        Si['ST'][i] = compute_total_order(Y[l], N, omega[0])
        if print_to_console:
            print('%s %f %f' % (problem['names'][i], Si['S1'][i], Si['ST'][i]))
    return Si

def update(self, data, ed):
    if ed == 'e':
        encrypted_blocks = b''
        self.cache += data
        if len(self.cache) < self.blocksize:
            return b''
        for i in range(0, len(self.cache) - self.blocksize + 1, self.blocksize):
            self.IV = self.codebook.encrypt(strxor(self.cache[i:i + self.blocksize], self.IV))
            encrypted_blocks += self.IV
        self.cache = self.cache[i + self.blocksize:]
        return encrypted_blocks
    else:
        decrypted_blocks = b''
        self.cache += data
        if len(self.cache) < self.blocksize:
            return b''
        for i in range(0, len(self.cache) - self.blocksize + 1, self.blocksize):
            plaintext = strxor(self.IV, self.codebook.decrypt(self.cache[i:i + self.blocksize]))
            self.IV = self.cache[i:i + self.blocksize]
            decrypted_blocks += plaintext
        self.cache = self.cache[i + self.blocksize:]
        return decrypted_blocks

