def download(tickers, start=None, end=None, actions=False, threads=False, group_by='column', auto_adjust=False, progress=True, period='max', interval='1d', prepost=False, **kwargs):
    global _PROGRESS_BAR, _DFS
    tickers = tickers if isinstance(tickers, list) else tickers.split()
    if progress:
        _PROGRESS_BAR = _ProgressBar(len(tickers), 'downloaded')
    _DFS = {}
    if threads is True:
        threads = min([len(tickers), _multitasking.cpu_count()])
    if isinstance(threads, int):
        _multitasking.set_max_threads(threads)
        for (i, ticker) in enumerate(tickers):
            _download_one_threaded(ticker, period=period, interval=interval, start=start, end=end, prepost=prepost, actions=actions, auto_adjust=auto_adjust, progress=progress and i > 0)
        while len(_DFS) < len(tickers):
            _time.sleep(0.01)
    else:
        for (i, ticker) in enumerate(tickers):
            data = _download_one(ticker, period=period, interval=interval, start=start, end=end, prepost=prepost, actions=actions, auto_adjust=auto_adjust)
            _DFS[ticker.upper()] = data
            if progress:
                _PROGRESS_BAR.animate()
    if progress:
        _PROGRESS_BAR.completed()
    data = _pd.concat(_DFS.values(), axis=1, keys=_DFS.keys())
    if group_by == 'column':
        data.columns = data.columns.swaplevel(0, 1)
        data.sort_index(level=0, axis=1, inplace=True)
    if len(tickers) == 1:
        data = _DFS[tickers[0]]
    return data

