def orthogonal_basis(self):
    if self.dim == 3:
        x_arr = np.array([-self.data[1], self.data[0], 0])
        if np.linalg.norm(x_arr) == 0:
            x_arr = np.array([self.data[2], 0, 0])
        x_arr = x_arr / np.linalg.norm(x_arr)
        y_arr = np.cross(self.data, x_arr)
        return (Direction(x_arr, frame=self.frame), Direction(y_arr, frame=self.frame))
    raise NotImplementedError('Orthogonal basis only supported for 3 dimensions')

def _validate_relations(relations, services, add_error):
    if not relations:
        return
    for relation in relations:
        if not islist(relation):
            add_error('relation {} is malformed'.format(relation))
            continue
        relation_str = ' -> '.join(('{}'.format(i) for i in relation))
        for endpoint in relation:
            if not isstring(endpoint):
                add_error('relation {} has malformed endpoint {}'.format(relation_str, endpoint))
                continue
            try:
                (service, _) = endpoint.split(':')
            except ValueError:
                service = endpoint
            if service not in services:
                add_error('relation {} endpoint {} refers to a non-existent service {}'.format(relation_str, endpoint, service))

