def sg_vgg_19(tensor, opt):
    opt += tf.sg_opt(num_class=1000, conv_only=False, squeeze=True, act='relu')
    with tf.sg_context(name=opt.name, act=opt.act, bn=opt.bn, reuse=opt.reuse):
        conv = tensor.sg_conv(dim=64, name='conv1_1').sg_conv(name='conv1_2').sg_pool().sg_conv(dim=128, name='conv2_1').sg_conv(name='conv2_2').sg_pool().sg_conv(dim=256, name='conv3_1').sg_conv(name='conv3_2').sg_conv(name='conv3_3').sg_conv(name='conv3_4').sg_pool().sg_conv(dim=512, name='conv4_1').sg_conv(name='conv4_2').sg_conv(name='conv4_3').sg_conv(name='conv4_4').sg_pool().sg_conv(dim=512, name='conv5_1').sg_conv(name='conv5_2').sg_conv(name='conv5_3').sg_conv(name='conv5_4').sg_pool()
    with tf.sg_context(name=opt.name, act=opt.act, pad='VALID', bn=opt.bn, reuse=opt.reuse):
        fc = conv.sg_conv(dim=4096, size=7, dout=opt.dout, name='fc1').sg_conv(dim=4096, size=1, dout=opt.dout, name='fc2').sg_conv(dim=opt.num_class, size=1, act='linear', name='fc3')
    if opt.conv_only:
        return conv
    elif opt.squeeze:
        return fc.sg_squeeze(axis=(1, 2))
    else:
        return fc

