def _get_timeframe_bounds(self, timeframe, bucket_width):
    if bucket_width:
        bucket_width_seconds = bucket_width
        bucket_width = epoch_time_to_kronos_time(bucket_width)
    if timeframe['mode']['value'] == 'recent':
        end_time = kronos_time_now()
        original_end_time = end_time
        duration = get_seconds(timeframe['value'], timeframe['scale']['name'])
        duration = epoch_time_to_kronos_time(duration)
        start_time = original_end_time - duration
        if bucket_width:
            if end_time % bucket_width != 0:
                end_time += bucket_width - end_time % bucket_width
            if start_time % bucket_width != 0:
                start_time -= start_time % bucket_width
        start = kronos_time_to_datetime(start_time)
        end = kronos_time_to_datetime(end_time)
    elif timeframe['mode']['value'] == 'range':
        end = datetime.datetime.strptime(timeframe['to'], DT_FORMAT)
        end_seconds = datetime_to_epoch_time(end)
        start = datetime.datetime.strptime(timeframe['from'], DT_FORMAT)
        start_seconds = datetime_to_epoch_time(start)
        if bucket_width:
            start_bump = start_seconds % bucket_width_seconds
            start -= datetime.timedelta(seconds=start_bump)
            if end_seconds % bucket_width_seconds != 0:
                end_bump = bucket_width_seconds - end_seconds % bucket_width_seconds
                end += datetime.timedelta(seconds=end_bump)
    else:
        raise ValueError("Timeframe mode must be 'recent' or 'range'")
    return (start, end)

def boundary_stawiaski_directed(graph, label_image, xxx_todo_changeme):
    (gradient_image, directedness) = xxx_todo_changeme
    label_image = scipy.asarray(label_image)
    gradient_image = scipy.asarray(gradient_image)
    if label_image.flags['F_CONTIGUOUS']:
        label_image = scipy.ascontiguousarray(label_image)
    __check_label_image(label_image)
    beta = abs(directedness)

    def addition_directed_ltd(key1, key2, v1, v2, dic):
        if not key1 == key2:
            weight = math.pow(1.0 / (1.0 + max(abs(v1), abs(v2))), 2)
            weight = max(weight, sys.float_info.min)
            if v1 > v2:
                graph.set_nweight(key1 - 1, key2 - 1, min(1, weight + beta), weight)
            else:
                graph.set_nweight(key1 - 1, key2 - 1, weight, min(1, weight + beta))

    def addition_directed_dtl(key1, key2, v1, v2):
        if not key1 == key2:
            weight = math.pow(1.0 / (1.0 + max(abs(v1), abs(v2))), 2)
            weight = max(weight, sys.float_info.min)
            if v1 > v2:
                graph.set_nweight(key1 - 1, key2 - 1, weight, min(1, weight + beta))
            else:
                graph.set_nweight(key1 - 1, key2 - 1, min(1, weight + beta), weight)
    if 0 > directedness:
        vaddition = scipy.vectorize(addition_directed_dtl)
    else:
        vaddition = scipy.vectorize(addition_directed_ltd)
    for dim in range(label_image.ndim):
        slices_x = []
        slices_y = []
        for di in range(label_image.ndim):
            slices_x.append(slice(None, -1 if di == dim else None))
            slices_y.append(slice(1 if di == dim else None, None))
        vaddition(label_image[slices_x], label_image[slices_y], gradient_image[slices_x], gradient_image[slices_y])

def clip_by_norm(x, clip_norm, axis=None):
    from .function_bases import pow_scalar as pow_scalar_base
    from .function_bases import maximum2 as maximum2_base
    from .function_bases import maximum_scalar as maximum_scalar_base
    from .function_bases import sum as sum_base
    from ._variable import Variable as Variable_base
    from ._nd_array import NdArray as NdArray_base
    if axis is None:
        axis = range(x.ndim)
    elif not hasattr(axis, '__iter__'):
        axis = [axis]
    x_norm = pow_scalar_base(sum_base(x ** 2.0, axis, True), 0.5)
    if isinstance(clip_norm, (Variable_base, NdArray_base)):
        y = x * clip_norm / maximum2_base(x_norm, clip_norm)
    else:
        if clip_norm <= 0:
            raise ValueError('clip_norm must be positive.')
        y = x * clip_norm / maximum_scalar_base(x_norm, clip_norm)
    return y

