def close(self):
    if self.done:
        return self.result
    self.done = True
    if not self._got_data:
        self.logger.debug('no data received!')
    elif self._input_state == InputState.PURE_ASCII:
        self.result = {'encoding': 'ascii', 'confidence': 1.0, 'language': ''}
    elif self._input_state == InputState.HIGH_BYTE:
        prober_confidence = None
        max_prober_confidence = 0.0
        max_prober = None
        for prober in self._charset_probers:
            if not prober:
                continue
            prober_confidence = prober.get_confidence()
            if prober_confidence > max_prober_confidence:
                max_prober_confidence = prober_confidence
                max_prober = prober
        if max_prober and max_prober_confidence > self.MINIMUM_THRESHOLD:
            charset_name = max_prober.charset_name
            lower_charset_name = max_prober.charset_name.lower()
            confidence = max_prober.get_confidence()
            if lower_charset_name.startswith('iso-8859'):
                if self._has_win_bytes:
                    charset_name = self.ISO_WIN_MAP.get(lower_charset_name, charset_name)
            self.result = {'encoding': charset_name, 'confidence': confidence, 'language': max_prober.language}
    if self.logger.getEffectiveLevel() == logging.DEBUG:
        if self.result['encoding'] is None:
            self.logger.debug('no probers hit minimum threshold')
            for group_prober in self._charset_probers:
                if not group_prober:
                    continue
                if isinstance(group_prober, CharSetGroupProber):
                    for prober in group_prober.probers:
                        self.logger.debug('%s %s confidence = %s', prober.charset_name, prober.language, prober.get_confidence())
                else:
                    self.logger.debug('%s %s confidence = %s', prober.charset_name, prober.language, prober.get_confidence())
    return self.result

def sniff_hosts(self, initial=False):
    node_info = (yield from self._get_sniff_data(initial))
    hosts = list(filter(None, (self._get_host_info(n) for n in node_info)))
    if not hosts:
        raise TransportError('N/A', 'Unable to sniff hosts - no viable hosts found.')
    orig_connections = self.connection_pool.connections[:]
    self.set_connections(hosts)
    for c in orig_connections:
        if c not in self.connection_pool.connections:
            yield from c.close()

def hash(self, *args, **kwargs):
    joiner = kwargs.get('joiner', '').encode('utf-8')
    as_bytes = kwargs.get('as_bytes', False)

    def conv(arg):
        if isinstance(arg, integer_types):
            arg = int_to_bytes(arg)
        if PY3:
            if isinstance(arg, str):
                arg = arg.encode('utf-8')
            return arg
        return str(arg)
    digest = joiner.join(map(conv, args))
    hash_obj = self._hash_func(digest)
    if as_bytes:
        return hash_obj.digest()
    return int_from_hex(hash_obj.hexdigest())

