def avail_images(call=None):
    if call == 'action':
        raise SaltCloudSystemExit('The avail_images function must be called with -f or --function, or with the --list-images option')
    fetch = True
    page = 1
    ret = {}
    while fetch:
        items = query(method='images', command='?page=' + six.text_type(page) + '&per_page=200')
        for image in items['images']:
            ret[image['name']] = {}
            for item in six.iterkeys(image):
