def _check_submodule_status(root, submodules):
    if hasattr(sys, 'frozen'):
        return 'clean'
    if not os.path.exists(os.path.join(root, '.git')):
        return 'clean'
    for submodule in submodules:
        if not os.path.exists(submodule):
            return 'missing'
    if sys.platform == 'win32' and sys.version_info[0] < 3 and (not isinstance(root, bytes)):
        root = root.encode(sys.getfilesystemencoding() or 'ascii')
    proc = subprocess.Popen('git submodule status', stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True, cwd=root)
    (status, _) = proc.communicate()
    status = status.decode('ascii', 'replace')
    for line in status.splitlines():
        if line.startswith('-'):
            return 'missing'
        elif line.startswith('+'):
            return 'unclean'
    return 'clean'

def system_information():

    def system_version():
        lin_ver = linux_distribution()
        mac_ver = platform.mac_ver()
        win_ver = platform.win32_ver()
        if lin_ver[0]:
            return ' '.join(lin_ver)
        elif mac_ver[0]:
            if isinstance(mac_ver[1], (tuple, list)) and ''.join(mac_ver[1]):
                return ' '.join([mac_ver[0], '.'.join(mac_ver[1]), mac_ver[2]])
            else:
                return ' '.join([mac_ver[0], mac_ver[2]])
        elif win_ver[0]:
            return ' '.join(win_ver)
        else:
            return ''
    if platform.win32_ver()[0]:
        import win32api
        import win32con
        hkey = win32con.HKEY_LOCAL_MACHINE
        key = 'SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion'
        value_name = 'ProductName'
        reg_handle = win32api.RegOpenKey(hkey, key)
        (product_name, _) = win32api.RegQueryValueEx(reg_handle, value_name)
        version = 'Unknown'
        release = ''
        if 'Server' in product_name:
            for item in product_name.split(' '):
                if re.match('\\d+', item):
                    version = item
                if re.match('^R\\d+$', item):
                    release = item
            release = '{0}Server{1}'.format(version, release)
        else:
            for item in product_name.split(' '):
                if re.match('^(\\d+(\\.\\d+)?)|Thin|Vista$', item):
                    version = item
            release = version
        (_, ver, sp, extra) = platform.win32_ver()
        version = ' '.join([release, ver, sp, extra])
    else:
        version = system_version()
        release = platform.release()
    system = [('system', platform.system()), ('dist', ' '.join(linux_distribution(full_distribution_name=False))), ('release', release), ('machine', platform.machine()), ('version', version), ('locale', __salt_system_encoding__)]
    for (name, attr) in system:
        yield (name, attr)
        continue

