def deprecated(removal_version, hint_message=None, subject=None, ensure_stderr=False):
    validate_deprecation_semver(removal_version, 'removal version')

    def decorator(func):
        if not inspect.isfunction(func):
            raise BadDecoratorNestingError('The @deprecated decorator must be applied innermost of all decorators.')
        func_full_name = '{}.{}'.format(func.__module__, func.__name__)

        @wraps(func)
        def wrapper(*args, **kwargs):
            warn_or_error(removal_version, subject or func_full_name, hint_message, ensure_stderr=ensure_stderr)
            return func(*args, **kwargs)
        return wrapper
    return decorator

