def _ffn_layer_multi_inputs(inputs_list, hparams, ffn_layer_type='dense', name='ffn', kernel_initializer=None, bias_initializer=None, activation=None, pad_remover=None, preprocess=False, postprocess=False):
    num_inputs = len(inputs_list)
    assert num_inputs > 0
    if preprocess and num_inputs == 1:
        inputs_list[0] = common_layers.layer_preprocess(inputs_list[0], hparams)
    if postprocess:
        original_inputs = inputs_list[0]
    main_input = inputs_list[0]
    original_shape = common_layers.shape_list(main_input)
    assert hparams.hidden_size == common_layers.shape_list(main_input)[-1]
    for inputs in inputs_list:
        main_input.get_shape().assert_is_compatible_with(inputs.get_shape())

    def remove_pads(x):
        original_shape = common_layers.shape_list(x)
        x = tf.reshape(x, tf.concat([[-1], original_shape[2:]], axis=0))
        x = tf.expand_dims(pad_remover.remove(x), axis=0)
        return x
    if pad_remover:
        for (i, inputs) in enumerate(inputs_list):
            inputs_list[i] = remove_pads(inputs)
    ffn_inputs = inputs_list[0]
    if len(inputs_list) != 1:
        ffn_inputs = tf.concat(inputs_list, axis=-1)
    if ffn_layer_type == 'dense':
        output = common_layers.dense(ffn_inputs, hparams.hidden_size, name=name, activation=activation, use_bias=True, kernel_initializer=kernel_initializer, bias_initializer=bias_initializer)
    elif ffn_layer_type == 'dense_dropconnect':
        output = common_layers.dense_dropconnect(ffn_inputs, hparams.hidden_size, name=name, dropconnect_dropout=hparams.dropconnect_dropout, output_activation=activation)
        postprocess = False
    elif ffn_layer_type == 'dense_relu_dense':
        output = common_layers.dense_relu_dense(ffn_inputs, hparams.filter_size, hparams.hidden_size, name=name, dropout=hparams.relu_dropout, output_activation=activation)
    else:
        raise ValueError('Unknown ffn_layer type: %s' % ffn_layer_type)
    if pad_remover:
        output = tf.reshape(pad_remover.restore(tf.squeeze(output, axis=0)), original_shape)
    if postprocess:
        if num_inputs == 1:
            output = common_layers.layer_postprocess(original_inputs, output, hparams)
        else:
            hp = copy.copy(hparams)
            hp.layer_postprocess_sequence = hp.layer_postprocess_sequence.replace('a', '')
            output = common_layers.layer_postprocess(original_inputs, output, hp)
    return output

