def pvcreate(devices, override=True, **kwargs):
    if not devices:
        return 'Error: at least one device is required'
    if isinstance(devices, six.string_types):
        devices = devices.split(',')
    cmd = ['pvcreate', '-y']
    for device in devices:
        if not os.path.exists(device):
            raise CommandExecutionError('{0} does not exist'.format(device))
        if not pvdisplay(device, quiet=True):
            cmd.append(device)
        elif not override:
            raise CommandExecutionError('Device "{0}" is already an LVM physical volume.'.format(device))
    if not cmd[2:]:
        return True
    valid = ('metadatasize', 'dataalignment', 'dataalignmentoffset', 'pvmetadatacopies', 'metadatacopies', 'metadataignore', 'restorefile', 'norestorefile', 'labelsector', 'setphysicalvolumesize')
    no_parameter = ('force', 'norestorefile')
    for var in kwargs:
        if kwargs[var] and var in valid:
            cmd.extend(['--{0}'.format(var), kwargs[var]])
        elif kwargs[var] and var in no_parameter:
            cmd.append('--{0}'.format(var))
    out = __salt__['cmd.run_all'](cmd, python_shell=False)
    if out.get('retcode'):
        raise CommandExecutionError(out.get('stderr'))
    for device in devices:
        if not pvdisplay(device):
            raise CommandExecutionError('Device "{0}" was not affected.'.format(device))
    return True

def _fastp_trim(fastq_files, adapters, out_dir, data):
    report_file = os.path.join(out_dir, '%s-report.json' % utils.splitext_plus(os.path.basename(fastq_files[0]))[0])
    out_files = [os.path.join(out_dir, '%s-trimmed.fq.gz' % utils.splitext_plus(os.path.basename(x))[0]) for x in fastq_files]
    if not utils.file_exists(out_files[0]):
        with file_transaction(data, *[report_file] + out_files) as tx_out:
            tx_report = tx_out[0]
            tx_out_files = tx_out[1:]
            cmd = ['fastp', '--thread', dd.get_num_cores(data)]
            if dd.get_quality_format(data).lower() == 'illumina':
                cmd += ['--phred64']
            for (i, (inf, outf)) in enumerate(zip(fastq_files, tx_out_files)):
                if i == 0:
                    cmd += ['-i', inf, '-o', outf]
                else:
                    cmd += ['-I', inf, '-O', outf]
            cmd += ['--cut_by_quality3', '--cut_mean_quality', '5', '--length_required', str(dd.get_min_read_length(data)), '--disable_quality_filtering']
            if 'polyx' in dd.get_adapters(data):
                cmd += ['--trim_poly_x', '--poly_x_min_len', '8']
            if 'polyx' in dd.get_adapters(data) or 'polyg' in dd.get_adapters(data):
                cmd += ['--trim_poly_g', '--poly_g_min_len', '8']
            for a in adapters:
                cmd += ['--adapter_sequence', a]
            if not adapters:
                cmd += ['--disable_adapter_trimming']
            cmd += ['--json', report_file, '--report_title', dd.get_sample_name(data)]
            do.run(cmd, 'Trimming with fastp: %s' % dd.get_sample_name(data))
    return (out_files, report_file)

def Nu_horizontal_cylinder(Pr, Gr, Method=None, AvailableMethods=False):

    def list_methods():
        methods = []
        for (key, values) in horizontal_cylinder_correlations.items():
            methods.append(key)
        if 'Morgan' in methods:
            methods.remove('Morgan')
            methods.insert(0, 'Morgan')
        return methods
    if AvailableMethods:
        return list_methods()
    if not Method:
        Method = list_methods()[0]
    if Method in horizontal_cylinder_correlations:
        return horizontal_cylinder_correlations[Method](Pr=Pr, Gr=Gr)
    else:
        raise Exception('Correlation name not recognized; see the documentation for the available options.')

def altitude(msg):
    tc = common.typecode(msg)
    if tc < 9 or tc == 19 or tc > 22:
        raise RuntimeError('%s: Not a airborn position message' % msg)
    mb = common.hex2bin(msg)[32:]
    if tc < 19:
        q = mb[15]
        if q:
            n = common.bin2int(mb[8:15] + mb[16:20])
            alt = n * 25 - 1000
        else:
            alt = None
    else:
        alt = common.bin2int(mb[8:20]) * 3.28084
    return alt

def gaussian_filter(self, sigma=2, order=0):
