def build_address_distance(number=None, street=None, city=None, state=None, zip_code=None):
    for param in [number, street, city, state, zip_code]:
        if param is not None and (not isinstance(param, str)):
            raise TypeError('All inputs must be strings. Each parameter is ' + 'intended to be the name of an SFrame column.')
    string_features = []
    if city:
        string_features.append(city)
    if zip_code:
        string_features.append(zip_code)
    dist = []
    if number:
        dist.append([[number], 'jaccard', 1])
    if street:
        dist.append([[street], 'jaccard', 5])
    if state:
        dist.append([[state], 'jaccard', 5])
    if len(string_features) > 0:
        dist.append([string_features, 'levenshtein', 1])
    return dist

def convert_to_match_query(ir_blocks):
    output_block = ir_blocks[-1]
    if not isinstance(output_block, ConstructResult):
        raise AssertionError(u'Expected last IR block to be ConstructResult, found: {} {}'.format(output_block, ir_blocks))
    ir_except_output = ir_blocks[:-1]
    (folds, ir_except_output_and_folds) = extract_folds_from_ir_blocks(ir_except_output)
    global_operation_ir_blocks_tuple = _extract_global_operations(ir_except_output_and_folds)
    (global_operation_blocks, pruned_ir_blocks) = global_operation_ir_blocks_tuple
    if len(global_operation_blocks) > 1:
        raise AssertionError(u'Received IR blocks with multiple global operation blocks. Only one is allowed: {} {}'.format(global_operation_blocks, ir_blocks))
    if len(global_operation_blocks) == 1:
        if not isinstance(global_operation_blocks[0], Filter):
            raise AssertionError(u'Received non-Filter global operation block. {}'.format(global_operation_blocks[0]))
        where_block = global_operation_blocks[0]
    else:
        where_block = None
    match_steps = _split_ir_into_match_steps(pruned_ir_blocks)
    match_traversals = _split_match_steps_into_match_traversals(match_steps)
    return MatchQuery(match_traversals=match_traversals, folds=folds, output_block=output_block, where_block=where_block)

