def strip(self, data, strip_newlines=False):
    text = []
    for (token_type, tag_name, tag_opts, token_text) in self.tokenize(data):
        if token_type == self.TOKEN_DATA:
            text.append(token_text)
        elif token_type == self.TOKEN_NEWLINE and (not strip_newlines):
            text.append(token_text)
    return ''.join(text)

def _adium_status(status, message):
    code = ADIUM_CODE_MAP[status]
    if not message:
        default_messages = {'busy': 'Busy', 'long_away': 'Extended away'}
        message = default_messages.get(status, '')
    else:
        message = message.replace('"', '\\"')
    script = '\n     tell application "System Events"\n      if exists process "Adium" then\n       tell application "Adium" to go {0}'.format(code)
    if message:
        script += ' with message "{0}"'.format(message)
    script += '\n      end if\n     end tell'
    common.shell_process(['osascript', '-e', script])

