def findUselessCheckers(self, allowedMessages):
    uselessCheckers = []
    for checkerName in self.linter._checkers:
        for checker in list(self.linter._checkers[checkerName]):
            messagesOfChecker = set(checker.msgs)
            if not messagesOfChecker.intersection(allowedMessages):
                uselessCheckers.append(checker)
    return uselessCheckers

def language(self, language):
    if language is None:
        raise ValueError('Invalid value for `language`, must not be `None`')
    allowed_values = ['python', 'r', 'rmarkdown']
    if language not in allowed_values:
        raise ValueError('Invalid value for `language` ({0}), must be one of {1}'.format(language, allowed_values))
    self._language = language

def form_node(cls):
    assert issubclass(cls, FormNode)
    res = attrs(init=False, slots=True)(cls)
    res._args = []
    res._required_args = 0
    res._rest_arg = None
    state = _FormArgMode.REQUIRED
    for field in fields(res):
        if 'arg_mode' in field.metadata:
            if state is _FormArgMode.REST:
                raise RuntimeError('rest argument must be last')
            if field.metadata['arg_mode'] is _FormArgMode.REQUIRED:
                if state is _FormArgMode.OPTIONAL:
                    raise RuntimeError('required arg after optional arg')
                res._args.append(field)
                res._required_args += 1
            elif field.metadata['arg_mode'] is _FormArgMode.OPTIONAL:
                state = _FormArgMode.OPTIONAL
                res._args.append(field)
            elif field.metadata['arg_mode'] is _FormArgMode.REST:
                state = _FormArgMode.REST
                res._rest_arg = field
            else:
                assert 0
    return res

def join(self, timeout=None):
    if self.__wait_for_finishing_thread:
        if not timeout:
            while True:
                self.__wait_for_finishing_thread.join(0.5)
                if not self.__wait_for_finishing_thread.isAlive():
                    break
        else:
            self.__wait_for_finishing_thread.join(timeout)
        return not self.__wait_for_finishing_thread.is_alive()
