def headers_to_str_headers(headers):
    ret = []
    if isinstance(headers, collections_abc.Mapping):
        h = headers.items()
    else:
        h = headers
    if six.PY2:
        return h
    for tup in h:
        (k, v) = tup
        if isinstance(k, six.binary_type):
            k = k.decode('iso-8859-1')
        if isinstance(v, six.binary_type):
            v = v.decode('iso-8859-1')
        ret.append((k, v))
    return ret

