def write_globalattrs(self, globalAttrs):
    if not isinstance(globalAttrs, dict):
        print('Global attribute(s) not in dictionary form.... Stop')
        return
    dataType = None
    numElems = None
    with self.path.open('rb+') as f:
        f.seek(0, 2)
        for (attr, entry) in globalAttrs.items():
            if attr in self.gattrs:
                raise ValueError('Global attribute: {} already exists.'.format(attr))
            if attr in self.vattrs:
                logging.warning('Attribute: {} already defined as a variable attribute.'.format(attr))
                continue
            (attrNum, offsetADR) = self._write_adr(f, True, attr)
            entries = 0
            if entry == None:
                continue
            entryNumMaX = -1
            poffset = -1
            for (entryNum, value) in entry.items():
                if entryNumMaX < entryNum:
                    entryNumMaX = entryNum
                if isinstance(value, list) or isinstance(value, tuple):
                    if len(value) == 2:
                        value2 = value[1]
                        dataType = CDF._datatype_token(value2)
                        if dataType > 0:
                            data = value[0]
                            if dataType == CDF.CDF_CHAR or dataType == CDF.CDF_UCHAR:
                                if isinstance(data, list) or isinstance(data, tuple):
                                    print('Invalid global attribute value.... Skip')
                                    return
                                numElems = len(data)
                            elif dataType == CDF.CDF_EPOCH or dataType == CDF.CDF_EPOCH16 or dataType == CDF.CDF_TIME_TT2000:
                                cvalue = []
                                if isinstance(data, list) or isinstance(data, tuple):
                                    numElems = len(data)
                                    for x in range(0, numElems):
                                        if isinstance(data[x], str):
                                            cvalue.append(cdfepoch.CDFepoch.parse(data[x]))
                                        else:
                                            cvalue.append(data[x])
                                    data = cvalue
                                else:
                                    if isinstance(data, str):
                                        data = cdfepoch.CDFepoch.parse(data)
                                    numElems = 1
                            elif isinstance(data, list) or isinstance(data, tuple):
                                numElems = len(data)
                            else:
                                numElems = 1
                        else:
                            data = value
                            (numElems, dataType) = CDF._datatype_define(value[0])
                            numElems = len(value)
                    else:
                        data = value
                        (numElems, dataType) = CDF._datatype_define(value[0])
                        numElems = len(value)
                else:
                    data = value
                    (numElems, dataType) = CDF._datatype_define(value)
                    if numElems is None:
                        print('Unknown data.... Skip')
                        return
                offset = self._write_aedr(f, True, attrNum, entryNum, data, dataType, numElems, None)
                if entries == 0:
                    self._update_offset_value(f, offsetADR + 20, 8, offset)
                else:
                    self._update_offset_value(f, poffset + 12, 8, offset)
                poffset = offset
                entries = entries + 1
            self._update_offset_value(f, offsetADR + 36, 4, entries)
            self._update_offset_value(f, offsetADR + 40, 4, entryNumMaX)

def parse(self, source, update=True, **params):
    scanner = INIScanner(source)
    scanner.scan()
    section = self.default_section
    name = None
    for token in scanner.tokens:
        if token[0] == 'KEY_VALUE':
            (name, value) = re.split('[=:]', token[1], 1)
            (name, value) = (name.strip(), value.strip())
            if not update and name in self[section]:
                continue
            self[section][name] = value
        elif token[0] == 'SECTION':
            section = token[1].strip('[]')
        elif token[0] == 'CONTINUATION':
            if not name:
                raise SyntaxError('SyntaxError[@char {0}: {1}]'.format(token[2], 'Bad continuation.'))
            self[section][name] += '\n' + token[1].strip()

def get_layers(self, Psurf=1013.25, Ptop=0.01, **kwargs):
    Psurf = np.asarray(Psurf)
    output_ndims = Psurf.ndim + 1
    if output_ndims > 3:
        raise ValueError('`Psurf` argument must be a float or an array with <= 2 dimensions (or None)')
    SIGe = None
    SIGc = None
    ETAe = None
    ETAc = None
    if self.hybrid:
        try:
            Ap = broadcast_1d_array(self.Ap, output_ndims)
            Bp = broadcast_1d_array(self.Bp, output_ndims)
        except KeyError:
            raise ValueError('Impossible to compute vertical levels, data is missing (Ap, Bp)')
        Cp = 0.0
    else:
        try:
            Bp = SIGe = broadcast_1d_array(self.esig, output_ndims)
            SIGc = broadcast_1d_array(self.csig, output_ndims)
        except KeyError:
            raise ValueError('Impossible to compute vertical levels, data is missing (esig, csig)')
        Ap = Cp = Ptop
    Pe = Ap + Bp * (Psurf - Cp)
    Pc = 0.5 * (Pe[0:-1] + Pe[1:])
    if self.hybrid:
        ETAe = (Pe - Ptop) / (Psurf - Ptop)
        ETAc = (Pc - Ptop) / (Psurf - Ptop)
    else:
        SIGe = SIGe * np.ones_like(Psurf)
        SIGc = SIGc * np.ones_like(Psurf)
    Ze = prof_altitude(Pe, **kwargs)
    Zc = prof_altitude(Pc, **kwargs)
    all_vars = {'eta_edges': ETAe, 'eta_centers': ETAc, 'sigma_edges': SIGe, 'sigma_centers': SIGc, 'pressure_edges': Pe, 'pressure_centers': Pc, 'altitude_edges': Ze, 'altitude_centers': Zc}
    return all_vars

def build_filter_stack(stack, options):
    if options.get('keyword_case'):
        stack.preprocess.append(filters.KeywordCaseFilter(options['keyword_case']))
    if options.get('identifier_case'):
        stack.preprocess.append(filters.IdentifierCaseFilter(options['identifier_case']))
    if options.get('truncate_strings'):
        stack.preprocess.append(filters.TruncateStringFilter(width=options['truncate_strings'], char=options['truncate_char']))
    if options.get('use_space_around_operators', False):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.SpacesAroundOperatorsFilter())
    if options.get('strip_comments'):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.StripCommentsFilter())
    if options.get('strip_whitespace') or options.get('reindent'):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.StripWhitespaceFilter())
    if options.get('reindent'):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.ReindentFilter(char=options['indent_char'], width=options['indent_width'], indent_after_first=options['indent_after_first'], indent_columns=options['indent_columns'], wrap_after=options['wrap_after'], comma_first=options['comma_first']))
    if options.get('reindent_aligned', False):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.AlignedIndentFilter(char=options['indent_char']))
    if options.get('right_margin'):
        stack.enable_grouping()
        stack.stmtprocess.append(filters.RightMarginFilter(width=options['right_margin']))
    if options.get('output_format'):
        frmt = options['output_format']
        if frmt.lower() == 'php':
            fltr = filters.OutputPHPFilter()
        elif frmt.lower() == 'python':
            fltr = filters.OutputPythonFilter()
        else:
            fltr = None
        if fltr is not None:
            stack.postprocess.append(fltr)
    return stack

def variant_filtration(call_file, ref_file, vrn_files, data, items):
    caller = data['config']['algorithm'].get('variantcaller')
    if 'gvcf' not in dd.get_tools_on(data):
        call_file = ploidy.filter_vcf_by_sex(call_file, items)
    if caller in ['freebayes']:
        return vfilter.freebayes(call_file, ref_file, vrn_files, data)
    elif caller in ['platypus']:
        return vfilter.platypus(call_file, data)
    elif caller in ['samtools']:
        return vfilter.samtools(call_file, data)
    elif caller in ['gatk', 'gatk-haplotype', 'haplotyper']:
        if dd.get_analysis(data).lower().find('rna-seq') >= 0:
