def EvacuateNode(r, node, iallocator=None, remote_node=None, dry_run=False, early_release=False, mode=None, accept_old=False):
    if iallocator and remote_node:
        raise GanetiApiError('Only one of iallocator or remote_node can be used')
    query = {'dry-run': dry_run}
    if iallocator:
        query['iallocator'] = iallocator
    if remote_node:
        query['remote_node'] = remote_node
    if NODE_EVAC_RES1 in r.features:
        body = {'early_release': early_release}
        if iallocator is not None:
            body['iallocator'] = iallocator
        if remote_node is not None:
            body['remote_node'] = remote_node
        if mode is not None:
            body['mode'] = mode
    else:
        body = None
        if not accept_old:
            raise GanetiApiError('Server is version 2.4 or earlier and caller does not accept old-style results (parameter accept_old)')
        if mode is not None and mode != NODE_EVAC_SEC:
            raise GanetiApiError('Server can only evacuate secondary instances')
        if iallocator is not None:
            query['iallocator'] = iallocator
        if remote_node is not None:
            query['remote_node'] = remote_node
        if query:
            query['early_release'] = 1
    return r.request('post', '/2/nodes/%s/evacuate' % node, query=query, content=body)

