def _get_domain(conn, *vms, **kwargs):
    ret = list()
    lookup_vms = list()
    all_vms = []
    if kwargs.get('active', True):
        for id_ in conn.listDomainsID():
            all_vms.append(conn.lookupByID(id_).name())
    if kwargs.get('inactive', True):
        for id_ in conn.listDefinedDomains():
            all_vms.append(id_)
    if not all_vms:
        raise CommandExecutionError('No virtual machines found.')
    if vms:
        for name in vms:
            if name not in all_vms:
                raise CommandExecutionError('The VM "{name}" is not present'.format(name=name))
            else:
                lookup_vms.append(name)
    else:
        lookup_vms = list(all_vms)
    for name in lookup_vms:
        ret.append(conn.lookupByName(name))
    return len(ret) == 1 and (not kwargs.get('iterable')) and ret[0] or ret

def cli(env, volume_id, schedule_type, retention_count, minute, hour, day_of_week):
    file_manager = SoftLayer.FileStorageManager(env.client)
    valid_schedule_types = {'INTERVAL', 'HOURLY', 'DAILY', 'WEEKLY'}
    valid_days = {'SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'}
    if schedule_type not in valid_schedule_types:
        raise exceptions.CLIAbort('--schedule-type must be INTERVAL, HOURLY, ' + 'DAILY, or WEEKLY, not ' + schedule_type)
    if schedule_type == 'INTERVAL' and (minute < 30 or minute > 59):
        raise exceptions.CLIAbort('--minute value must be between 30 and 59')
    if minute < 0 or minute > 59:
        raise exceptions.CLIAbort('--minute value must be between 0 and 59')
    if hour < 0 or hour > 23:
        raise exceptions.CLIAbort('--hour value must be between 0 and 23')
    if day_of_week not in valid_days:
        raise exceptions.CLIAbort('--day_of_week value must be a valid day (ex: SUNDAY)')
    enabled = file_manager.enable_snapshots(volume_id, schedule_type, retention_count, minute, hour, day_of_week)
    if enabled:
        click.echo('%s snapshots have been enabled for volume %s' % (schedule_type, volume_id))

def draw(canvas, mol):
    mol.require('ScaleAndCenter')
    mlb = mol.size2d[2]
    if not mol.atom_count():
        return
    bond_type_fn = {1: {0: single_bond, 1: wedged_single, 2: dashed_wedged_single, 3: wave_single}, 2: {0: cw_double, 1: counter_cw_double, 2: double_bond, 3: cross_double}, 3: {0: triple_bond}}
    for (u, v, bond) in mol.bonds_iter():
        if not bond.visible:
            continue
        if (u < v) == bond.is_lower_first:
            (f, s) = (u, v)
        else:
            (s, f) = (u, v)
        p1 = mol.atom(f).coords
        p2 = mol.atom(s).coords
        if p1 == p2:
            continue
        if mol.atom(f).visible:
            p1 = gm.t_seg(p1, p2, F_AOVL, 2)[0]
        if mol.atom(s).visible:
            p2 = gm.t_seg(p1, p2, F_AOVL, 1)[1]
        color1 = mol.atom(f).color
        color2 = mol.atom(s).color
        bond_type_fn[bond.order][bond.type](canvas, p1, p2, color1, color2, mlb)
    for (n, atom) in mol.atoms_iter():
        if not atom.visible:
            continue
        p = atom.coords
        color = atom.color
        if atom.H_count:
            cosnbrs = []
            hrzn = (p[0] + 1, p[1])
            for nbr in mol.graph.neighbors(n):
                pnbr = mol.atom(nbr).coords
                try:
                    cosnbrs.append(gm.dot_product(hrzn, pnbr, p) / gm.distance(p, pnbr))
                except ZeroDivisionError:
                    pass
            if not cosnbrs or min(cosnbrs) > 0:
                text = atom.formula_html(True)
                canvas.draw_text(p, text, color, 'right')
                continue
            elif max(cosnbrs) < 0:
                text = atom.formula_html()
                canvas.draw_text(p, text, color, 'left')
                continue
        text = atom.formula_html()
        canvas.draw_text(p, text, color, 'center')

def AnalyzeAPK(_file, session=None, raw=False):
    log.debug('AnalyzeAPK')
    if session:
        log.debug('Using existing session {}'.format(session))
        if raw:
            data = _file
            filename = hashlib.md5(_file).hexdigest()
        else:
            with open(_file, 'rb') as fd:
                data = fd.read()
                filename = _file
        digest = session.add(filename, data)
        return session.get_objects_apk(filename, digest)
    else:
        log.debug('Analysing without session')
        a = APK(_file, raw=raw)
        d = []
        dx = Analysis()
        for dex in a.get_all_dex():
            df = DalvikVMFormat(dex, using_api=a.get_target_sdk_version())
            dx.add(df)
            d.append(df)
            df.set_decompiler(decompiler.DecompilerDAD(d, dx))
        dx.create_xref()
        return (a, d, dx)

