def run_script(input_file, script_name, interpreter='python', include_prefix=True, ignore_error=False, trailing_newlines=True, break_lines_at=0, line_break_mode='break', adjust_python_for_version=True, line_cleanups=[]):
    rundir = path(input_file).dirname()
    if adjust_python_for_version and interpreter == 'python' and (sys.version_info[0] == 3):
        interpreter = 'python3'
    cmd_list = script_name
    if isinstance(script_name, list):
        script_name = ' '.join(cmd_list)
    if interpreter:
        cmd = '%(interpreter)s %(script_name)s' % {'interpreter': interpreter, 'script_name': script_name}
    else:
        cmd = script_name
    real_cmd = 'cd %(rundir)s; %(cmd)s 2>&1' % {'rundir': rundir, 'cmd': cmd}
    try:
        print()
        output_text = sh(real_cmd, capture=True, ignore_error=ignore_error)
        print(output_text)
    except Exception as err:
        print('*' * 50)
        print('ERROR run_script(%s) => %s' % (real_cmd, err))
        print('*' * 50)
        output_text = sh(real_cmd, capture=True, ignore_error=True)
        print(output_text)
        print('*' * 50)
        if not ignore_error:
            raise
    if include_prefix:
        response = '\n.. code-block:: none\n\n'
    else:
        response = ''
    lines = []
    if isinstance(cmd_list, list):
        if interpreter:
            lines.append('\t$ {} {}'.format(interpreter, cmd_list[0] + ' \\'))
        else:
            lines.append('\t$ {}'.format(cmd_list[0] + ' \\'))
        lines.extend((l + ' \\' for l in cmd_list[1:-1]))
        lines.append(cmd_list[-1])
    else:
        raw_command_line = '\t$ %s' % cmd
        for cleanup in line_cleanups:
            raw_command_line = cleanup(input_file, raw_command_line)
        command_line = adjust_line_widths([raw_command_line], break_lines_at - 1 if break_lines_at else 64, 'continue')
        lines.extend(command_line)
    lines.append('')
    lines.extend(output_text.splitlines())
    clean_lines = []
    for line in lines:
        for cleanup in line_cleanups:
            line = cleanup(input_file, line)
        clean_lines.append(line)
    lines = clean_lines
    if break_lines_at:
        lines = adjust_line_widths(lines, break_lines_at, line_break_mode)
    response += '\n\t'.join(lines)
    if trailing_newlines:
        while not response.endswith('\n\n'):
            response += '\n'
    else:
        response = response.rstrip()
        response += '\n'
    return response

