def trmm(L, B, alpha=1.0, trans='N', nrhs=None, offsetB=0, ldB=None):
    assert isinstance(L, cspmatrix) and L.is_factor is True, 'L must be a cspmatrix factor'
    assert isinstance(B, matrix), 'B must be a matrix'
    if ldB is None:
        ldB = B.size[0]
    if nrhs is None:
        nrhs = B.size[1]
    assert trans in ['N', 'T']
    n = L.symb.n
    snpost = L.symb.snpost
    snptr = L.symb.snptr
    snode = L.symb.snode
    chptr = L.symb.chptr
    chidx = L.symb.chidx
    relptr = L.symb.relptr
    relidx = L.symb.relidx
    blkptr = L.symb.blkptr
    blkval = L.blkval
    p = L.symb.p
    if p is None:
        p = range(n)
    stack = []
    if trans is 'N':
        for k in snpost:
            nn = snptr[k + 1] - snptr[k]
            na = relptr[k + 1] - relptr[k]
            nj = na + nn
            Uk = matrix(0.0, (nj, nrhs))
            for j in range(nrhs):
                for (i, ir) in enumerate(snode[snptr[k]:snptr[k + 1]]):
                    Uk[i, j] = alpha * B[offsetB + j * ldB + p[ir]]
            blas.trmm(blkval, Uk, m=nn, n=nrhs, offsetA=blkptr[k], ldA=nj)
            if na > 0:
                blas.gemm(blkval, Uk, Uk, m=na, n=nrhs, k=nn, alpha=1.0, offsetA=blkptr[k] + nn, ldA=nj, offsetC=nn)
            for _ in range(chptr[k], chptr[k + 1]):
                (Ui, i) = stack.pop()
                r = relidx[relptr[i]:relptr[i + 1]]
                Uk[r, :] += Ui
            if na > 0:
                stack.append((Uk[nn:, :], k))
            for j in range(nrhs):
                for (i, ir) in enumerate(snode[snptr[k]:snptr[k + 1]]):
                    B[offsetB + j * ldB + p[ir]] = Uk[i, j]
    else:
        for k in reversed(list(snpost)):
            nn = snptr[k + 1] - snptr[k]
            na = relptr[k + 1] - relptr[k]
            nj = na + nn
            Uk = matrix(0.0, (nj, nrhs))
            for j in range(nrhs):
                for (i, ir) in enumerate(snode[snptr[k]:snptr[k + 1]]):
                    Uk[i, j] = alpha * B[offsetB + j * ldB + p[ir]]
            if na > 0:
                Uk[nn:, :] = stack.pop()
            for ii in range(chptr[k], chptr[k + 1]):
                i = chidx[ii]
                stack.append(Uk[relidx[relptr[i]:relptr[i + 1]], :])
            if na > 0:
                blas.gemm(blkval, Uk, Uk, alpha=1.0, beta=1.0, m=nn, n=nrhs, k=na, transA='T', offsetA=blkptr[k] + nn, ldA=nj, offsetB=nn)
            blas.trmm(blkval, Uk, transA='T', m=nn, n=nrhs, offsetA=blkptr[k], ldA=nj)
            for j in range(nrhs):
                for (i, ir) in enumerate(snode[snptr[k]:snptr[k + 1]]):
                    B[offsetB + j * ldB + p[ir]] = Uk[i, j]
    return

def aggregate_variable(estimate, id):
    estimates = [variable.estimates.get(division__id=id).estimate for variable in estimate.variable.label.variables.all()]
    method = estimate.variable.label.aggregation
    if method == 's':
        aggregate = sum(estimates)
    elif method == 'a':
        aggregate = statistics.mean(estimates)
    elif method == 'm':
        aggregate = statistics.median(estimates)
    else:
        aggregate = None
    return aggregate

def get_bundle_by_name(self, bundle_name):
