def do_build(self):
    shutit_global.shutit_global_object.yield_to_draw()
    cfg = self.cfg
    self.log('PHASE: build, repository work', level=logging.DEBUG)
    module_id_list = self.module_ids()
    if self.build['deps_only']:
        module_id_list_build_only = filter(lambda x: cfg[x]['shutit.core.module.build'], module_id_list)
    for module_id in module_id_list:
        module = self.shutit_map[module_id]
        self.log('Considering whether to build: ' + module.module_id, level=logging.INFO)
        if cfg[module.module_id]['shutit.core.module.build']:
            if self.build['delivery'] not in module.ok_delivery_methods:
                self.fail('Module: ' + module.module_id + ' can only be built with one of these --delivery methods: ' + str(module.ok_delivery_methods) + '\nSee shutit build -h for more info, or try adding: --delivery <method> to your shutit invocation')
            if self.is_installed(module):
                self.build['report'] = self.build['report'] + '\nBuilt already: ' + module.module_id + ' with run order: ' + str(module.run_order)
            elif self.build['deps_only'] and module_id == module_id_list_build_only[-1]:
                self.build['report'] = self.build['report'] + '\nSkipping: ' + module.module_id + ' with run order: ' + str(module.run_order) + '\n\tas this is the final module and we are building dependencies only'
            else:
                revert_dir = os.getcwd()
                self.get_current_shutit_pexpect_session_environment().module_root_dir = os.path.dirname(self.shutit_file_map[module_id])
                self.chdir(self.get_current_shutit_pexpect_session_environment().module_root_dir)
                self.login(prompt_prefix=module_id, command=shutit_global.shutit_global_object.bash_startup_command, echo=False)
                self.build_module(module)
                self.logout(echo=False)
                self.chdir(revert_dir)
        if self.is_installed(module):
            self.log('Starting module', level=logging.DEBUG)
            if not module.start(self):
                self.fail(module.module_id + ' failed on start', shutit_pexpect_child=self.get_shutit_pexpect_session_from_id('target_child').pexpect_child)

def perform(self):
    if self.data is None:
        return
    context.log.debug('Starting %s(%s)' % (self.data['path'], self.data['params']))
    task_class = load_class_by_path(self.data['path'])
    self.task = task_class()
    self.task.is_main_task = True
    if not self.task.max_concurrency:
        result = self.task.run_wrapped(self.data['params'])
    else:
        if self.task.max_concurrency > 1:
            raise NotImplementedError()
        lock = None
        try:
            lock = context.connections.redis.lock(self.redis_max_concurrency_key, timeout=self.timeout + 5)
            if not lock.acquire(blocking=True, blocking_timeout=0):
                raise MaxConcurrencyInterrupt()
            result = self.task.run_wrapped(self.data['params'])
        finally:
            try:
                if lock:
                    lock.release()
            except LockError:
                pass
    self.save_success(result)
    if context.get_current_config().get('trace_greenlets'):
        gevent.sleep(0)
        current_greenlet = gevent.getcurrent()
        t = (datetime.datetime.utcnow() - self.datestarted).total_seconds()
        context.log.debug('Job %s success: %0.6fs total, %0.6fs in greenlet, %s switches' % (self.id, t, current_greenlet._trace_time, current_greenlet._trace_switches - 1))
    else:
        context.log.debug('Job %s success: %0.6fs total' % (self.id, (datetime.datetime.utcnow() - self.datestarted).total_seconds()))
    return result

def as_ti_txt(self):
    lines = []
    for segment in self._segments:
        lines.append('@{:04X}'.format(segment.address))
        for (_, data) in segment.chunks(TI_TXT_BYTES_PER_LINE):
            lines.append(' '.join(('{:02X}'.format(byte) for byte in data)))
    lines.append('q')
    return '\n'.join(lines) + '\n'

