def load_vint(buf, pos):
    limit = min(pos + 11, len(buf))
    res = ofs = 0
    while pos < limit:
        b = _byte_code(buf[pos])
        res += (b & 127) << ofs
        pos += 1
        ofs += 7
        if b < 128:
            return (res, pos)
    raise BadRarFile('cannot load vint')

