def enforce_validation_rules(settings_view, expected_signer, batches):
    rules = settings_view.get_setting('sawtooth.validator.block_validation_rules')
    if rules is None:
        return True
    transactions = []
    for batch in batches:
        transactions += batch.transactions
    rules = rules.split(';')
    valid = True
    for rule in rules:
        try:
            (rule_type, arguments) = rule.split(':')
        except ValueError:
            LOGGER.warning('Validation Rule Ignored, not in the correct format: %s', rule)
            continue
        rule_type = rule_type.strip()
        if rule_type == 'NofX':
            valid = _do_nofx(transactions, arguments)
        elif rule_type == 'XatY':
            valid = _do_xaty(transactions, arguments)
        elif rule_type == 'local':
            valid = _do_local(transactions, expected_signer, arguments)
        if not valid:
            return False
    return valid

