def register_gwf_api(library):
    try:
        lib = import_gwf_library(library)
    except ImportError:
        pass
    else:
        libread_ = lib.read
        libwrite_ = lib.write
    fmt = 'gwf.%s' % library

    def read_timeseriesdict(source, channels, start=None, end=None, dtype=None, resample=None, gap=None, pad=None, nproc=1, series_class=TimeSeries, **kwargs):
        import_gwf_library(library)
        if start:
            start = to_gps(start)
        if end:
            end = to_gps(end)
        if resample is not None:
            warnings.warn('the resample keyword for is deprecated, instead you should manually resample after reading', DeprecationWarning)
        if not isinstance(resample, dict):
            resample = dict(((c, resample) for c in channels))
        if dtype is not None:
            warnings.warn('the dtype keyword for is deprecated, instead you should manually call astype() after reading', DeprecationWarning)
        if not isinstance(dtype, dict):
            dtype = dict(((c, dtype) for c in channels))
        if gap is None and pad is not None:
            gap = 'pad'
        elif gap is None:
            gap = 'raise'
        if isinstance(source, string_types) and source.endswith(('.lcf', '.cache')) or (isinstance(source, io_cache.FILE_LIKE) and source.name.endswith(('.lcf', '.cache'))):
            source = io_cache.read_cache(source)
        if io_cache.is_cache(source):
            if start is not None and end is not None:
                source = io_cache.sieve(source, segment=Segment(start, end))
            source = list(io_cache.find_contiguous(source))
        if not isinstance(source, (list, tuple)):
            source = [source]
        out = series_class.DictClass()
        for (i, src) in enumerate(source):
            if i == 1:
                for name in out:
                    out[name] = numpy.require(out[name], requirements=['O'])
            out.append(libread_(src, channels, start=start, end=end, series_class=series_class, **kwargs), gap=gap, pad=pad, copy=False)
        for name in out:
            if resample.get(name) and resample[name] != out[name].sample_rate.value:
                out[name] = out[name].resample(resample[name])
            if dtype.get(name) is not None and numpy.dtype(dtype[name]) != out[name].dtype:
                out[name] = out[name].astype(dtype[name])
        return out

    def read_timeseries(source, channel, *args, **kwargs):
        return read_timeseriesdict(source, [channel], *args, **kwargs)[channel]

    def read_statevector(source, channel, *args, **kwargs):
        bits = kwargs.pop('bits', None)
        kwargs.setdefault('series_class', StateVector)
        statevector = read_timeseries(source, channel, *args, **kwargs)
        statevector.bits = bits
        return statevector

    def read_statevectordict(source, channels, *args, **kwargs):
        bitss = channel_dict_kwarg(kwargs.pop('bits', {}), channels)
        kwargs.setdefault('series_class', StateVector)
        svd = StateVectorDict(read_timeseriesdict(source, channels, *args, **kwargs))
        for (channel, bits) in bitss.items():
            svd[channel].bits = bits
        return svd

    def write_timeseriesdict(data, outfile, start=None, end=None, name='gwpy', run=0):
        import_gwf_library(library)
        return libwrite_(data, outfile, start=start, end=end, name=name, run=run)

    def write_timeseries(series, *args, **kwargs):
        return write_timeseriesdict({None: series}, *args, **kwargs)
    register_reader(fmt, TimeSeriesDict, read_timeseriesdict)
    register_reader(fmt, TimeSeries, read_timeseries)
    register_reader(fmt, StateVectorDict, read_statevectordict)
    register_reader(fmt, StateVector, read_statevector)
    register_writer(fmt, TimeSeriesDict, write_timeseriesdict)
    register_writer(fmt, TimeSeries, write_timeseries)
    register_writer(fmt, StateVectorDict, write_timeseriesdict)
    register_writer(fmt, StateVector, write_timeseries)

def probe_dtm(self, board: chess.Board) -> int:
    if board.castling_rights:
        raise KeyError('gaviota tables do not contain positions with castling rights: {}'.format(board.fen()))
    if chess.popcount(board.occupied) > 5:
        raise KeyError('gaviota tables support up to 5 pieces, not {}: {}'.format(chess.popcount(board.occupied), board.fen()))
    if board.occupied == board.kings:
        return 0
    white_squares = list(chess.SquareSet(board.occupied_co[chess.WHITE]))
    white_types = [typing.cast(chess.PieceType, board.piece_type_at(sq)) for sq in white_squares]
    black_squares = list(chess.SquareSet(board.occupied_co[chess.BLACK]))
    black_types = [typing.cast(chess.PieceType, board.piece_type_at(sq)) for sq in black_squares]
    side = 0 if board.turn == chess.WHITE else 1
    epsq = board.ep_square if board.ep_square else NOSQUARE
    req = Request(white_squares, white_types, black_squares, black_types, side, epsq)
    dtm = self.egtb_get_dtm(req)
    (ply, res) = unpackdist(dtm)
    if res == iWMATE:
        if req.realside == 1:
            if req.is_reversed:
                return ply
            else:
                return -ply
        elif req.is_reversed:
            return -ply
        else:
            return ply
    elif res == iBMATE:
        if req.realside == 0:
            if req.is_reversed:
                return ply
            else:
                return -ply
        elif req.is_reversed:
            return -ply
        else:
            return ply
    else:
        return 0

