def _run_operation_with_response(self, operation, unpack_res, exhaust=False, address=None):
    if operation.exhaust_mgr:
        server = self._select_server(operation.read_preference, operation.session, address=address)
        with self._reset_on_error(server.description.address, operation.session):
            return server.run_operation_with_response(operation.exhaust_mgr.sock, operation, True, self._event_listeners, exhaust, unpack_res)

    def _cmd(session, server, sock_info, slave_ok):
        return server.run_operation_with_response(sock_info, operation, slave_ok, self._event_listeners, exhaust, unpack_res)
    return self._retryable_read(_cmd, operation.read_preference, operation.session, address=address, retryable=isinstance(operation, message._Query), exhaust=exhaust)

def command_exists(command, noop_invocation, exc_msg):
    try:
        found = bool(shutil.which(command))
    except AttributeError:
        try:
            p = subprocess.Popen(noop_invocation, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except OSError:
            found = False
        else:
            (stdout, stderr) = p.communicate()
            found = p.returncode == 0
            if not found:
                logger.error('`%s` exited with a non-zero return code (%s)', noop_invocation, p.returncode)
                logger.error('command stdout = %s', stdout)
                logger.error('command stderr = %s', stderr)
    if not found:
        raise CommandDoesNotExistException(exc_msg)
    return True

def lookup_blob(hash_value):
    try:
