def slot_definition_for(self, slotname: SlotDefinitionName, cls: ClassDefinition) -> Optional[SlotDefinition]:
    if cls.is_a:
        for sn in self.schema.classes[cls.is_a].slots:
            slot = self.schema.slots[sn]
            if slot.alias and slotname == slot.alias or slotname == slot.name:
                return slot
    for mixin in cls.mixins:
        for sn in self.schema.classes[mixin].slots:
            slot = self.schema.slots[sn]
            if slot.alias and slotname == slot.alias or slotname == slot.name:
                return slot
    if cls.is_a:
        defn = self.slot_definition_for(slotname, self.schema.classes[cls.is_a])
        if defn:
            return defn
    for mixin in cls.mixins:
        defn = self.slot_definition_for(slotname, self.schema.classes[mixin])
        if defn:
            return defn
    return None

def expand_braces(pattern):
    res = set()

    def remove_outer_braces(s):
        if s[0] == '{' and s[-1] == '}':
            return s[1:-1]
        return s
    match = EXPAND_BRACES_RE.search(pattern)
    if match is not None:
        sub = match.group(1)
        (v1, v2) = match.span(1)
        if ',' in sub:
            for pat in sub.strip('{}').split(','):
                subpattern = pattern[:v1] + pat + pattern[v2:]
                res.update(expand_braces(subpattern))
        else:
            subpattern = pattern[:v1] + remove_outer_braces(sub) + pattern[v2:]
            res.update(expand_braces(subpattern))
    else:
        res.add(pattern.replace('\\}', '}'))
    return list(res)

def should_raptorize(self, req, resp):
    if resp.status != '200 OK':
        return False
    content_type = resp.headers.get('Content-Type', 'text/plain').lower()
    if not 'html' in content_type:
        return False
    if random.random() > self.random_chance:
        return False
    if self.only_on_april_1st:
        now = datetime.datetime.now()
        if now.month != 20 and now.day != 1:
            return False
    return True

def cleanup_params_files(output_folder: str, max_to_keep: int, checkpoint: int, best_checkpoint: int, keep_first: bool):
    if max_to_keep <= 0:
        return
    existing_files = glob.glob(os.path.join(output_folder, C.PARAMS_PREFIX + '*'))
    params_name_with_dir = os.path.join(output_folder, C.PARAMS_NAME)
    for n in range(1 if keep_first else 0, max(1, checkpoint - max_to_keep + 1)):
        if n != best_checkpoint:
            param_fname_n = params_name_with_dir % n
            if param_fname_n in existing_files:
                os.remove(param_fname_n)

def handleErrorEvents(self, msg):
    if msg.errorCode is not None and msg.errorCode != -1 and (msg.errorCode not in dataTypes['BENIGN_ERROR_CODES']):
        log = True
        if msg.errorCode in dataTypes['DISCONNECT_ERROR_CODES']:
            log = False
            if msg.errorCode not in self.connection_tracking['errors']:
                self.connection_tracking['errors'].append(msg.errorCode)
