def create_tarfile(self):
    floyd_logger.info('Compressing data...')
    self.__compression_bar = ProgressBar(expected_size=self.__files_to_compress, filled_char='=')

    def dfilter_file_counter(tarinfo):
        self.__compression_bar.show(self.__files_compressed)
        self.__files_compressed += 1
        return tarinfo

    def warn_purge_exit(info_msg, filename, progress_bar, exit_msg):
        progress_bar.done()
        floyd_logger.info(info_msg)
        rmtree(os.path.dirname(filename))
        sys.exit(exit_msg)
    try:
        signal.signal(signal.SIGINT, signal.default_int_handler)
        with tarfile.open(self.filename, 'w:gz') as tar:
            tar.add(self.source_dir, arcname=os.path.basename(self.source_dir), filter=dfilter_file_counter)
        self.__compression_bar.done()
    except (OSError, IOError) as e:
        if e.errno == errno.EACCES:
            self.source_dir = os.getcwd() if self.source_dir == '.' else self.source_dir
            warn_purge_exit(info_msg='Permission denied. Removing compressed data...', filename=self.filename, progress_bar=self.__compression_bar, exit_msg='Permission denied. Make sure to have read permission for all the files and directories in the path: %s' % self.source_dir)
        elif e.errno == errno.ENOSPC:
            dir_path = os.path.dirname(self.filename)
            warn_purge_exit(info_msg='No space left. Removing compressed data...', filename=self.filename, progress_bar=self.__compression_bar, exit_msg='No space left when compressing your data in: %s.\nMake sure to have enough space before uploading your data.' % os.path.abspath(dir_path))
    except KeyboardInterrupt:
        warn_purge_exit(info_msg='Ctrl-C signal detected: Removing compressed data...', filename=self.filename, progress_bar=self.__compression_bar, exit_msg='Stopped the data upload gracefully.')

