def calc_qvr_v1(self):
    con = self.parameters.control.fastaccess
    flu = self.sequences.fluxes.fastaccess
    for i in range(2):
        if flu.avr[i] > 0.0 and flu.uvr[i] > 0.0:
            flu.qvr[i] = con.ekv[i] * con.skv[i] * flu.avr[i] ** (5.0 / 3.0) / flu.uvr[i] ** (2.0 / 3.0) * con.gef ** 0.5
        else:
            flu.qvr[i] = 0.0

def _grow_to(self, width, height, top_tc=None):

