def _flip_feature(self, feature, parent_len):
    copy = feature.copy()
    if copy.strand == 0:
        copy.strand = 1
    else:
        copy.strand = 0
    copy.start = parent_len - copy.start
    copy.stop = parent_len - copy.stop
    (copy.start, copy.stop) = (copy.stop, copy.start)
    return copy

