def _VarintEncoder():

    def EncodeVarint(write, value):
        bits = value & 127
        value >>= 7
        while value:
            write(six.int2byte(128 | bits))
            bits = value & 127
            value >>= 7
        return write(six.int2byte(bits))
    return EncodeVarint

