def _save_table(self, raw=False, cls=None, force_insert=None, force_update=None, using=None, update_fields=None):
    connection = connections[using]
    create = bool(force_insert or not self.dn)
    if update_fields:
        target_fields = [self._meta.get_field(name) for name in update_fields]
    else:
        target_fields = [field for field in cls._meta.get_fields(include_hidden=True) if field.concrete and (not field.primary_key)]

    def get_field_value(field, instance):
        python_value = getattr(instance, field.attname)
        return field.get_db_prep_save(python_value, connection=connection)
    if create:
        old = None
    else:
        old = cls.objects.using(using).get(dn=self._saved_dn)
    changes = {field.db_column: (None if old is None else get_field_value(field, old), get_field_value(field, self)) for field in target_fields}
    old_dn = self.dn
    new_dn = self.build_dn()
    updated = False
    if create:
        hidden_values = [('objectClass', [obj_class.encode('utf-8') for obj_class in self.object_classes])]
        new_values = hidden_values + [(colname, change[1]) for (colname, change) in sorted(changes.items()) if change[1] != []]
        new_dn = self.build_dn()
        logger.debug('Creating new LDAP entry %s', new_dn)
        connection.add_s(new_dn, new_values)
    else:
        modlist = []
        for (colname, change) in sorted(changes.items()):
            (old_value, new_value) = change
            if old_value == new_value:
                continue
            modlist.append((ldap.MOD_DELETE if new_value == [] else ldap.MOD_REPLACE, colname, new_value))
        if new_dn != old_dn:
            logger.debug('renaming ldap entry %s to %s', old_dn, new_dn)
            connection.rename_s(old_dn, self.build_rdn())
        if modlist:
            logger.debug('Modifying existing LDAP entry %s', new_dn)
            connection.modify_s(new_dn, modlist)
        updated = True
    self.dn = new_dn
    self._saved_dn = self.dn
    return updated

