def chainable(fn):

    @functools.wraps(fn)
    def wrapper(nxt=lambda x: x):
        if hasattr(nxt, '__call__'):
            return lambda x: nxt(fn(x))
        return fn(nxt)
    return wrapper

def doControl(self, controlCode, bytes=[]):
    CardConnection.doControl(self, controlCode, bytes)
    (hresult, response) = SCardControl(self.hcard, controlCode, bytes)
    if hresult != 0:
        raise SmartcardException('Failed to control ' + SCardGetErrorMessage(hresult))
    data = [(x + 256) % 256 for x in response]
    return list(data)

def join_state(self, state, history_index, concurrency_history_item):
    state.join()
    if state.backward_execution:
        self.backward_execution = True
    state.state_execution_status = StateExecutionStatus.INACTIVE
    if not self.backward_execution:
        state.concurrency_queue = None
        state.execution_history.push_return_history_item(state, CallType.EXECUTE, self, state.output_data)
    else:
        last_history_item = concurrency_history_item.execution_histories[history_index].pop_last_item()
        assert isinstance(last_history_item, CallItem)

def _parse_vertex_tuple(s):
    vt = [0, 0, 0]
    for (i, c) in enumerate(s.split('/')):
        if c:
            vt[i] = int(c)
    return tuple(vt)

def chunklentype(self):
    x = self.file.read(8)
    if not x:
        return None
    if len(x) != 8:
        raise FormatError('End of file whilst reading chunk length and type.')
    (length, type) = struct.unpack('!I4s', x)
    type = bytestostr(type)
    if length > 2 ** 31 - 1:
        raise FormatError('Chunk %s is too large: %d.' % (type, length))
    return (length, type)

