def install_signal_trap(signums=(signal.SIGTERM, signal.SIGTSTP), retval=1):
    signums = set(signums) - set(origactions)

    def temporary_file_cleanup_on_signal(signum, frame):
        with temporary_files_lock:
            temporary_files.clear()
        if callable(origactions[signum]):
            return origactions[signum](signum, frame)
        sys.exit(retval)
    for signum in signums:
        origactions[signum] = signal.getsignal(signum)
        if origactions[signum] != signal.SIG_IGN:
            signal.signal(signum, temporary_file_cleanup_on_signal)

def normalize(data):
    out_data = data.copy()
    for (i, sample) in enumerate(out_data):
        out_data[i] /= sum(out_data[i])
    return out_data

def _funds_remaining(self) -> int:
    if self.funds > 0:
        token = self.raiden.chain.token(self.token_address)
        token_balance = token.balance_of(self.raiden.address)
        sum_deposits = views.get_our_capacity_for_token_network(views.state_from_raiden(self.raiden), self.registry_address, self.token_address)
        return min(self.funds - sum_deposits, token_balance)
    return 0

def scan(s):
    line = 1
    linepos = 1
    pos = 0
    toks = []
    while pos < len(s):
        matched = False
        for (tokname, r) in patterns:
            m = r.match(s, pos)
            if m is not None:
                v = m.group(0)
                prec = _preceding_token(toks)
                if tokname == 'STAR' and prec is not None and _is_special(prec):
                    tok = XPathTok('wildcard', v, line, linepos)
                elif tokname == 'name' and prec is not None and (not _is_special(prec)) and (v in operators):
                    tok = XPathTok(operators[v], v, line, linepos)
                elif tokname == 'name':
                    if re_open_para.match(s, pos + len(v)):
                        if v in node_types:
                            tok = XPathTok('node_type', v, line, linepos)
                        else:
                            tok = XPathTok('function_name', v, line, linepos)
                    elif re_axis.match(s, pos + len(v)):
                        if v in axes:
                            tok = XPathTok('axis', v, line, linepos)
                        else:
                            e = 'unknown axis %s' % v
                            raise XPathError(e, line, linepos)
                    else:
                        tok = XPathTok('name', v, line, linepos)
                else:
                    tok = XPathTok(tokname, v, line, linepos)
                if tokname == '_whitespace':
                    n = v.count('\n')
                    if n > 0:
                        line = line + n
                        linepos = len(v) - v.rfind('\n')
                    else:
                        linepos += len(v)
                else:
                    linepos += len(v)
                pos += len(v)
                toks.append(tok)
                matched = True
                break
        if matched == False:
            raise XPathError('syntax error', line, linepos)
    return toks

def _to_dict(self):
    _dict = {}
    if hasattr(self, 'text') and self.text is not None:
        _dict['text'] = self.text
    if hasattr(self, 'user') and self.user is not None:
        _dict['user'] = self.user
    return _dict

def parse_line(self, line):
    logger.debug('Parsing line %s', line)
    OUT_FIELD = 0
    IN_FIELD_KIND = 1
    IN_FIELD_OPTION_NAME = 2
    IN_FIELD_OPTION_VALUE = 3

    class ParserState(object):

        def __init__(self, logger=None):
            self.quote = None
            self.escaping = False
            self.block = []
            self.kind = ''
            self.option_name = ''
            self.options = {}
            self.state = OUT_FIELD
            self.fields = []
            if not logger:
                logger = logging.getLogger('%s.parser' % __name__)
            self.logger = logger

        def _reset(self):
            self.quote = None
            self.escaping = False
            self.block = []

        def _register_field(self, kind, options):
            self.fields.append((kind, dict(options)))

        def debug(self, msg, *args, **kwargs):
            self.logger.debug(msg, *args, **kwargs)

        def save_fixed_text(self):
            assert self.state == OUT_FIELD
            self._register_field(FIXED_TEXT_FIELD, {'text': ''.join(self.block)})

        def enter_field(self):
            self.debug('Entering new field')
            self.state = IN_FIELD_KIND
            self.kind = ''
            self.options = {}
            self.option_name = ''
            self._reset()

        def leave_kind(self):
            self.state = IN_FIELD_OPTION_NAME
            self.kind = ''.join(self.block)
            self.debug("Got widget kind '%s'", self.kind)
            self._reset()

        def leave_option_name(self):
            self.state = IN_FIELD_OPTION_VALUE
            self.option_name = ''.join(self.block)
            self.debug("Got option name '%s' for '%s'", self.option_name, self.kind)
            self._reset()

        def leave_option_value(self):
            self.state = IN_FIELD_OPTION_NAME
            option_value = ''.join(self.block)
            self.options[self.option_name] = option_value
            self.debug("Got option '%s=%s' for '%s'", self.option_name, option_value, self.kind)
            self._reset()

        def leave_field(self):
            self.state = OUT_FIELD
            self._register_field(self.kind, self.options)
            self.debug("Got widget '%s(%s)'", self.kind, ', '.join(('%s=%r' % it for it in self.options.items())))
            self._reset()
    st = ParserState()
    for (pos, char) in enumerate(line):
        if st.escaping:
            st.escaping = False
            st.block.append(char)
        elif char == '\\':
            st.escaping = True
        elif char in ['"', "'"]:
            if st.state == IN_FIELD_OPTION_VALUE:
                if st.quote:
                    if char == st.quote:
                        st.leave_option_value()
                    else:
                        st.block.append(char)
                elif not st.block:
                    st.quote = char
                    continue
                else:
                    raise FormatError("Unexpected '%s' at %d in %s" % (char, pos, line))
            elif st.state == OUT_FIELD:
                st.block.append(char)
            else:
                raise FormatError("Unexpected '%s' at %d in %s" % (char, pos, line))
        elif char == '{':
            if st.state == OUT_FIELD:
                if st.block:
                    st.save_fixed_text()
                st.enter_field()
            elif st.state == IN_FIELD_OPTION_VALUE and st.quote:
                st.block.append(char)
            else:
                raise FormatError("Unexpected '{' at %d in %s" % (pos, line))
        elif char == '}':
            if st.state == IN_FIELD_KIND:
                st.leave_kind()
                st.leave_field()
            elif st.state == IN_FIELD_OPTION_NAME:
                raise FormatError('Missing option value for %s at %d in %s' % (''.join(st.block), pos, line))
            elif st.state == IN_FIELD_OPTION_VALUE:
                if st.quote:
                    st.block.append(char)
                else:
                    st.leave_option_value()
                    st.leave_field()
            elif st.state == OUT_FIELD:
                raise FormatError("Unexpected '}' at %d in %s" % (pos, line))
        elif char == ' ':
            if st.state == IN_FIELD_KIND:
                if not st.block:
                    raise FormatError('Missing field kind at %s in %s' % (pos, line))
                st.leave_kind()
            elif st.state == IN_FIELD_OPTION_VALUE and st.quote:
                st.block.append(char)
            elif st.state == OUT_FIELD:
                st.block.append(char)
            else:
                raise FormatError("Unexpected ' ' at %d in %s" % (pos, line))
        elif char == ',':
            if st.state == IN_FIELD_OPTION_NAME:
                if st.block:
                    raise FormatError('Missing option value for %s at %d in %s' % (''.join(st.block), pos, line))
                else:
                    continue
            elif st.state == IN_FIELD_KIND:
                raise FormatError("Unexpected ',' in field definition %s at %d in %s" % (st.kind, pos, line))
            elif st.state == IN_FIELD_OPTION_VALUE:
                if st.quote:
                    st.block.append(char)
                elif st.block:
                    st.leave_option_value()
                else:
                    raise FormatError('Missing option value for %s at %d in %s' % (st.option_name, pos, line))
            else:
                st.block.append(char)
        elif char == '=':
            if st.state == IN_FIELD_OPTION_NAME:
                if st.block:
                    st.leave_option_name()
                else:
                    raise FormatError('Missing option name at %d in %s' % (pos, line))
            elif st.state == OUT_FIELD:
                st.block.append(char)
            elif st.state == IN_FIELD_OPTION_VALUE:
                if st.quote:
                    st.block.append(char)
                elif not st.block:
                    continue
                else:
                    raise FormatError("Unexpected '=' in option value for %s at %d in %s" % (st.option_name, pos, line))
            else:
                raise FormatError("Unexpected '=' at %d in %s" % (pos, line))
        else:
            st.block.append(char)
    if st.state != OUT_FIELD:
        raise FormatError("Unclosed field at %d in '%s'; block: '%s'" % (pos, line, ''.join(st.block)))
    if st.block:
        st.save_fixed_text()
    return st.fields

def data_spec(cls, name):
    if isinstance(name, BaseData):
        name = name.name
    try:
        return cls._data_specs[name]
    except KeyError:
        raise ArcanaNameError(name, "No fileset spec named '{}' in {}, available:\n{}".format(name, cls.__name__, '\n'.join(list(cls._data_specs.keys()))))

