def _get_data_dtype(self):
    pkhrec = [('GP_PK_HEADER', GSDTRecords.gp_pk_header), ('GP_PK_SH1', GSDTRecords.gp_pk_sh1)]
    pk_head_dtype = np.dtype(pkhrec)

    def get_lrec(cols):
        lrec = [('gp_pk', pk_head_dtype), ('version', np.uint8), ('satid', np.uint16), ('time', (np.uint16, 5)), ('lineno', np.uint32), ('chan_id', np.uint8), ('acq_time', (np.uint16, 3)), ('line_validity', np.uint8), ('line_rquality', np.uint8), ('line_gquality', np.uint8), ('line_data', (np.uint8, cols))]
        return lrec
    visir_rec = get_lrec(int(self.mda['number_of_columns'] * 1.25))
    number_of_visir_channels = len([s for s in self.mda['channel_list'] if not s == 'HRV'])
    drec = [('visir', (visir_rec, number_of_visir_channels))]
    if self.mda['available_channels']['HRV']:
        hrv_rec = get_lrec(int(self.mda['hrv_number_of_columns'] * 1.25))
        drec.append(('hrv', (hrv_rec, 3)))
    return np.dtype(drec)

def get_composition_lookup_session_for_repository(self, repository_id, proxy):
    if repository_id is None:
        raise NullArgument()
    if not self.supports_composition_lookup():
        raise Unimplemented()
    try:
        from . import sessions
    except ImportError:
        raise
    proxy = self._convert_proxy(proxy)
    try:
        session = sessions.CompositionLookupSession(repository_id, proxy, runtime=self._runtime)
    except AttributeError:
        raise
    return session

def put(self, filename, encoding=None):
    from . import LocalFile
    if os.path.isdir(filename) and self.source is None:
        raise ValueError('Cannot write this object to directory %s without an explicit filename.' % filename)
    target = get_target_path(filename, self.source)
    if encoding is None:
        encoding = self.encoding
    if self._isbytes:
        kwargs = {'mode': 'wb'}
    else:
        kwargs = {'mode': 'w', 'encoding': encoding}
    with open(target, **kwargs) as outfile:
        outfile.write(self._contents)
    return LocalFile(target, encoded_with=encoding)

def update(self, enabled):
