def __buttonEvent(event=None, buttons=None, virtual_event=None):
    global boxRoot, __replyButtonText
    m = re.match('(\\d+)x(\\d+)([-+]\\d+)([-+]\\d+)', boxRoot.geometry())
    if not m:
        raise ValueError('failed to parse geometry string: {}'.format(boxRoot.geometry()))
    (width, height, xoffset, yoffset) = [int(s) for s in m.groups()]
    st.rootWindowPosition = '{0:+g}{1:+g}'.format(xoffset, yoffset)
    if virtual_event == 'cancel':
        for (button_name, button) in list(buttons.items()):
            if 'cancel_choice' in button:
                __replyButtonText = button['original_text']
        __replyButtonText = None
        boxRoot.quit()
        return
    if virtual_event == 'select':
        text = event.widget.config('text')[-1]
        if not isinstance(text, ut.str):
            text = ' '.join(text)
        for (button_name, button) in list(buttons.items()):
            if button['clean_text'] == text:
                __replyButtonText = button['original_text']
                boxRoot.quit()
                return
    if buttons:
        for (button_name, button) in list(buttons.items()):
            hotkey_pressed = event.keysym
            if event.keysym != event.char:
                hotkey_pressed = '<{}>'.format(event.keysym)
            if button['hotkey'] == hotkey_pressed:
                __replyButtonText = button_name
                boxRoot.quit()
                return
    print('Event not understood')

def is_correct(self):
    state = True
    cls = self.__class__
    hname = getattr(self, 'host_name', '')
    hgname = getattr(self, 'hostgroup_name', '')
    sdesc = getattr(self, 'service_description', '')
    if not sdesc:
        self.add_error('a %s has been defined without service_description, from: %s' % (cls, self.imported_from))
    elif not hname:
        self.add_error('[%s::%s] not bound to any host.' % (self.my_type, self.get_name()))
    elif not hname and (not hgname):
        self.add_error('a %s has been defined without host_name nor hostgroup_name, from: %s' % (self.my_type, self.imported_from))
    elif self.host is None:
        self.add_error("[%s::%s] unknown host_name '%s'" % (self.my_type, self.get_name(), self.host_name))
    if not getattr(self, 'display_name', ''):
        self.display_name = '%s/%s' % (hname, sdesc)
    for char in cls.illegal_object_name_chars:
        if char not in self.service_description:
            continue
        self.add_error('[%s::%s] service_description got an illegal character: %s' % (self.my_type, self.get_name(), char))
    return super(Service, self).is_correct() and state

