    for index in np.ndindex(*[len(slices) for slices in all_slices]):
        keys = tuple((slices[i] for (slices, i) in zip(all_slices, index)))
        if masked:
            target[keys] = array[keys].masked_array()
        else:
            target[keys] = array[keys].ndarray()

def robust_mean(log_values):
    if log_values.shape[1] <= 3:
        return numpy.nanmean(log_values, axis=1)
    without_nans = numpy.nan_to_num(log_values)
    mask = ~numpy.isnan(log_values) & (without_nans <= numpy.nanpercentile(log_values, 75, axis=1).reshape((-1, 1))) & (without_nans >= numpy.nanpercentile(log_values, 25, axis=1).reshape((-1, 1)))
    return (without_nans * mask.astype(float)).sum(1) / mask.sum(1)

