def infer_ast_from_something(self, obj, context=None):
    if hasattr(obj, '__class__') and (not isinstance(obj, type)):
        klass = obj.__class__
    else:
        klass = obj
    try:
        modname = klass.__module__
    except AttributeError as exc:
        raise exceptions.AstroidBuildingError('Unable to get module for {class_repr}.', cls=klass, class_repr=safe_repr(klass)) from exc
    except Exception as exc:
        raise exceptions.AstroidImportError('Unexpected error while retrieving module for {class_repr}:\n{error}', cls=klass, class_repr=safe_repr(klass)) from exc
    try:
        name = klass.__name__
    except AttributeError as exc:
        raise exceptions.AstroidBuildingError('Unable to get name for {class_repr}:\n', cls=klass, class_repr=safe_repr(klass)) from exc
    except Exception as exc:
        raise exceptions.AstroidImportError('Unexpected error while retrieving name for {class_repr}:\n{error}', cls=klass, class_repr=safe_repr(klass)) from exc
    modastroid = self.ast_from_module_name(modname)
    if klass is obj:
        for inferred in modastroid.igetattr(name, context):
            yield inferred
    else:
        for inferred in modastroid.igetattr(name, context):
            yield inferred.instantiate_class()

def smeft_evolve_continuous(C_in, scale_in, scale_out, newphys=True, **kwargs):
    sol = _smeft_evolve(C_in, scale_in, scale_out, newphys=newphys, dense_output=True, **kwargs)

    @np.vectorize
    def _rge_solution(scale):
        t = log(scale)
        y = sol.sol(t).view(complex)
        yd = C_array2dict(y)
        yw = arrays2wcxf_nonred(yd)
        return yw

    def rge_solution(scale):
        return _rge_solution(scale)[()]
    return rge_solution

def update(self, forecasts, observations):
    for (t, threshold) in enumerate(self.thresholds):
        tp = np.count_nonzero((forecasts >= threshold) & (observations >= self.obs_threshold))
        fp = np.count_nonzero((forecasts >= threshold) & (observations < self.obs_threshold))
        fn = np.count_nonzero((forecasts < threshold) & (observations >= self.obs_threshold))
        tn = np.count_nonzero((forecasts < threshold) & (observations < self.obs_threshold))
        self.contingency_tables.iloc[t] += [tp, fp, fn, tn]

