def findAndHandleDeadJobs(cls, nodeInfo, batchSystemShutdown=False):
    for jobState in cls._getAllJobStates(nodeInfo):
        if not cls._pidExists(jobState['jobPID']):
            myPID = str(os.getpid())
            cleanupFile = os.path.join(jobState['jobDir'], '.cleanup')
            with open(os.path.join(jobState['jobDir'], '.' + myPID), 'w') as f:
                f.write(myPID)
            while True:
                try:
                    os.rename(f.name, cleanupFile)
                except OSError as err:
                    if err.errno == errno.ENOTEMPTY:
                        with open(cleanupFile, 'r') as f:
                            cleanupPID = f.read()
                        if cls._pidExists(int(cleanupPID)):
                            os.remove(f.name)
                            break
                        else:
                            os.remove(cleanupFile)
                            continue
                    else:
                        raise
                else:
                    logger.warning('Detected that job (%s) prematurely terminated.  Fixing the state of the job on disk.', jobState['jobName'])
                    if not batchSystemShutdown:
                        logger.debug('Deleting the stale working directory.')
                        shutil.rmtree(jobState['jobDir'])
                    logger.debug('Running user-defined deferred functions.')
                    cls._runDeferredFunctions(jobState['deferredFunctions'])
                    break

def put(self, local, remote, contents=None, quiet=False):
    remote_dir = os.path.dirname(remote)
    remote_file = os.path.basename(local) if remote.endswith('/') else os.path.basename(remote)
    if contents:
        local_file = buffer_type(contents)
    elif isinstance(local, file_type):
        local_file = local
    else:
        local_file = open(local, 'rb')
    current = self.conn.pwd()
    self.descend(remote_dir, force=True)
    size = 0
    try:
        self.conn.storbinary('STOR %s' % remote_file, local_file)
        size = self.conn.size(remote_file)
    except:
        if not quiet:
            raise
