        raise ValueError('1D and 2D arrays supported only')
    bindat = serialize_numpy(m, 'd')
    return _java.jvm.nben.util.Numpy.double2FromBytes(bindat) if dims == 2 else _java.jvm.nben.util.Numpy.double1FromBytes(bindat)

def interact(self):
    if sys.platform == 'win32':
        self.mt_interact()
        return
    while True:
        (rfd, wfd, xfd) = select.select([self, sys.stdin], [], [])
        if self in rfd:
            try:
                text = self.read_eager()
            except EOFError:
                print('*** Connection closed by remote host ***')
                break
            if text:
                self.stdout.write(text)
                self.stdout.flush()
        if sys.stdin in rfd:
            line = sys.stdin.readline()
            if not line:
                break
            self.write(line)

def count_collisions(Collisions):
    CollisionCount = 0
    CollisionIndicies = []
    lastval = True
    for (i, val) in enumerate(Collisions):
        if val == True and lastval == False:
            CollisionIndicies.append(i)
            CollisionCount += 1
        lastval = val
    return (CollisionCount, CollisionIndicies)

