def FromString(cls, string_rep):
    rep = str(string_rep)
    parts = rep.split()
    if len(parts) > 3:
        raise ArgumentError('Too many whitespace separated parts of stream designator', input_string=string_rep)
    elif len(parts) == 3 and parts[0] != u'system':
        raise ArgumentError('Too many whitespace separated parts of stream designator', input_string=string_rep)
    elif len(parts) < 2:
        raise ArgumentError('Too few components in stream designator', input_string=string_rep)
    if len(parts) == 3:
        system = True
        stream_type = parts[1]
        stream_id = parts[2]
    else:
        system = False
        stream_type = parts[0]
        stream_id = parts[1]
    try:
        stream_id = int(stream_id, 0)
    except ValueError as exc:
        raise ArgumentError('Could not convert stream id to integer', error_string=str(exc), stream_id=stream_id)
    try:
        stream_type = cls.StringToType[stream_type]
    except KeyError:
        raise ArgumentError('Invalid stream type given', stream_type=stream_type, known_types=cls.StringToType.keys())
    return DataStream(stream_type, stream_id, system)

def fit(self, inputs=None, wait=True, logs=True, job_name=None, run_tensorboard_locally=False):

    def fit_super():
        super(TensorFlow, self).fit(inputs, wait, logs, job_name)
    if run_tensorboard_locally and wait is False:
        raise ValueError('Tensorboard is not supported with async fit')
    if self._script_mode_enabled() and run_tensorboard_locally:
        LOGGER.warning(_SCRIPT_MODE_TENSORBOARD_WARNING.format(self.model_dir))
        fit_super()
    elif run_tensorboard_locally:
        tensorboard = Tensorboard(self)
        tensorboard.validate_requirements()
        try:
            tensorboard.start()
            fit_super()
        finally:
            time.sleep(20)
            tensorboard.event.set()
            tensorboard.join()
    else:
        fit_super()

