def select_actions(root, action_space, max_episode_steps):
    node = root
    acts = []
    steps = 0
    while steps < max_episode_steps:
        if node is None:
            act = action_space.sample()
        else:
            epsilon = EXPLORATION_PARAM / np.log(node.visits + 2)
            if random.random() < epsilon:
                act = action_space.sample()
            else:
                act_value = {}
                for act in range(action_space.n):
                    if node is not None and act in node.children:
                        act_value[act] = node.children[act].value
                    else:
                        act_value[act] = -np.inf
                best_value = max(act_value.values())
                best_acts = [act for (act, value) in act_value.items() if value == best_value]
                act = random.choice(best_acts)
            if act in node.children:
                node = node.children[act]
            else:
                node = None
        acts.append(act)
        steps += 1
    return acts

def _get_raw_xsrf_token(self) -> Tuple[Optional[int], bytes, float]:
    if not hasattr(self, '_raw_xsrf_token'):
        cookie = self.get_cookie('_xsrf')
        if cookie:
            (version, token, timestamp) = self._decode_xsrf_token(cookie)
        else:
            (version, token, timestamp) = (None, None, None)
        if token is None:
            version = None
            token = os.urandom(16)
            timestamp = time.time()
        assert token is not None
        assert timestamp is not None
        self._raw_xsrf_token = (version, token, timestamp)
    return self._raw_xsrf_token

def _container_handler(ion_type, ctx):
    transition = None
    first = True
    at_top = ctx.depth == 0
    while True:
        (data_event, self) = (yield transition)
        if data_event is not None and data_event.type is ReadEventType.SKIP:
            yield ctx.read_data_transition(ctx.remaining, self, skip=True)
        if ctx.queue.position == ctx.limit:
            yield Transition(IonEvent(IonEventType.CONTAINER_END, ion_type, depth=ctx.depth - 1), ctx.whence)
        if ion_type is IonType.STRUCT:
            self_handler = _create_delegate_handler(self)
            ((field_sid, _), _) = (yield ctx.immediate_transition(_var_uint_field_handler(self_handler, ctx)))
            field_name = SymbolToken(None, field_sid)
        else:
            field_name = None
        expects_ivm = first and at_top
        transition = ctx.immediate_transition(_start_type_handler(field_name, self, ctx, expects_ivm, at_top=at_top))
        first = False

