def _fetch_router_info(self, router_ids=None, device_ids=None, all_routers=False):
    try:
        if all_routers:
            LOG.debug('Fetching all routers')
            router_ids = self.plugin_rpc.get_router_ids(self.context)
            routers = self._fetch_router_chunk_data(router_ids)
        elif router_ids:
            routers = self._fetch_router_chunk_data(router_ids)
        elif device_ids:
            return self.plugin_rpc.get_routers(self.context, hd_ids=device_ids)
    except oslo_messaging.MessagingTimeout:
        if self.sync_routers_chunk_size > SYNC_ROUTERS_MIN_CHUNK_SIZE:
            self.sync_routers_chunk_size = max(int(round(self.sync_routers_chunk_size / 2)), SYNC_ROUTERS_MIN_CHUNK_SIZE)
            LOG.warning('Server failed to return info for routers in required time, decreasing chunk size to: %s', self.sync_routers_chunk_size)
        else:
            LOG.warning('Server failed to return info for routers in required time even with min chunk size: %s. It might be under very high load or just inoperable', self.sync_routers_chunk_size)
        raise
    except oslo_messaging.MessagingException:
        LOG.exception('RPC Error in fetching routers from plugin')
        self.fullsync = True
        raise n_exc.AbortSyncRouters()
    LOG.debug('Periodic_sync_routers_task successfully completed')
    if self.sync_routers_chunk_size < cfg.CONF.cfg_agent.max_device_sync_batch_size:
        self.sync_routers_chunk_size = min(self.sync_routers_chunk_size + SYNC_ROUTERS_MIN_CHUNK_SIZE, cfg.CONF.cfg_agent.max_device_sync_batch_size)
    return routers

