def _Backward2_T_Ps(P, s):
    if P <= 4:
        T = _Backward2a_T_Ps(P, s)
    elif s >= 5.85:
        T = _Backward2b_T_Ps(P, s)
    else:
        T = _Backward2c_T_Ps(P, s)
    if P <= 22.064:
        Tsat = _TSat_P(P)
        T = max(Tsat, T)
    return T

def hyphenify(self, ascii=False):
    s = str(self)
    s = re.sub('[\'"‘’“”]', '', s)
    s = re.sub('(?:\\s|%20)+', '-', s)
    if ascii == True:
        s = s.encode('ascii', 'xmlcharrefreplace').decode('ascii')
    s = re.sub('&?([^;]*?);', '.\\1-', s)
    s = s.replace('#', 'u')
    s = re.sub('\\W+', '-', s).strip(' -')
    return String(s)

