                        float(check_name)
                        is_string_cat = False
                    except:
                        is_string_cat = True
                    if is_string_cat == True:
                        if ': ' in check_name:
                            check_name = check_name.split(': ')[1]
                        if 'False' in check_name or 'false' in check_name:
                            inst_color = '#eee'
                        if 'Not ' in check_name:
                            inst_color = '#eee'
                    if tmp_name not in cat_colors[inst_rc][cat_index] and is_string_cat:
                        cat_colors[inst_rc][cat_index][tmp_name] = inst_color
                    cat_number = cat_number + 1
        net.viz['cat_colors'] = cat_colors

def _install_interrupt_handler():
    import os
    import sys
    import signal
    import pkg_resources
    from .tools import const
    quilt = pkg_resources.get_distribution('quilt')
    executable = os.path.basename(sys.argv[0])
    entry_points = quilt.get_entry_map().get('console_scripts', [])
    if executable == '-c':
        if len(sys.argv) > 1 and sys.argv[1] == 'quilt testing':
            entry_points['-c'] = 'blah'
            sys.argv.pop(1)
    if executable not in entry_points:
        return

    def handle_interrupt(signum, stack):
        if _DEV_MODE is None:
            dev_mode = True if len(sys.argv) > 1 and sys.argv[1] == '--dev' else False
            dev_mode = True if os.environ.get('QUILT_DEV_MODE', '').strip().lower() == 'true' else dev_mode
        else:
            dev_mode = _DEV_MODE
        if dev_mode:
            raise KeyboardInterrupt()
        print()
        exit(const.EXIT_KB_INTERRUPT)
    return signal.signal(signal.SIGINT, handle_interrupt)

def join_options(options):
    rv = []
    any_prefix_is_slash = False
    for opt in options:
        prefix = split_opt(opt)[0]
        if prefix == '/':
            any_prefix_is_slash = True
        rv.append((len(prefix), opt))
    rv.sort(key=lambda x: x[0])
    rv = ', '.join((x[1] for x in rv))
    return (rv, any_prefix_is_slash)

