def probabilities(self, choosers, alternatives, filter_tables=True):
    logger.debug('start: calculate probabilities for LCM model {}'.format(self.name))
    self.assert_fitted()
    if filter_tables:
        (choosers, alternatives) = self.apply_predict_filters(choosers, alternatives)
    if self.prediction_sample_size is not None:
        sample_size = self.prediction_sample_size
    else:
        sample_size = len(alternatives)
    if self.probability_mode == 'single_chooser':
        (_, merged, _) = interaction.mnl_interaction_dataset(choosers.head(1), alternatives, sample_size)
    elif self.probability_mode == 'full_product':
        (_, merged, _) = interaction.mnl_interaction_dataset(choosers, alternatives, sample_size)
    else:
        raise ValueError('Unrecognized probability_mode option: {}'.format(self.probability_mode))
    merged = util.apply_filter_query(merged, self.interaction_predict_filters)
    model_design = dmatrix(self.str_model_expression, data=merged, return_type='dataframe')
    if len(merged) != model_design.as_matrix().shape[0]:
        raise ModelEvaluationError('Simulated data does not have the same length as input.  This suggests there are null values in one or more of the input columns.')
    coeffs = [self.fit_parameters['Coefficient'][x] for x in model_design.columns]
    if self.probability_mode == 'single_chooser':
        numalts = len(merged)
    else:
        numalts = sample_size
    probabilities = mnl.mnl_simulate(model_design.as_matrix(), coeffs, numalts=numalts, returnprobs=True)
    mi = pd.MultiIndex.from_arrays([merged['join_index'].values, merged.index.values], names=('chooser_id', 'alternative_id'))
    probabilities = pd.Series(probabilities.flatten(), index=mi)
    logger.debug('finish: calculate probabilities for LCM model {}'.format(self.name))
    return probabilities

def do_types_overlap(schema, type_a, type_b):
    if type_a is type_b:
        return True
    if is_abstract_type(type_a):
        if is_abstract_type(type_b):
            return any((schema.is_possible_type(type_b, type_) for type_ in schema.get_possible_types(type_a)))
        return schema.is_possible_type(type_a, type_b)
    if is_abstract_type(type_b):
        return schema.is_possible_type(type_b, type_a)
    return False

def read(key, root=''):
    if not isinstance(key, six.string_types):
        res = {}
        for akey in key:
            ares = read(os.path.join(root, akey))
            if ares is not False:
                res[akey] = ares
        return res
    key = target(os.path.join(root, key))
    if key is False:
        return False
    elif os.path.isdir(key):
        keys = interfaces(key)
        result = {}
        for subkey in keys['r'] + keys['rw']:
            subval = read(os.path.join(key, subkey))
            if subval is not False:
                subkeys = subkey.split('/')
                subkey = subkeys.pop()
                subresult = result
                if subkeys:
                    for skey in subkeys:
                        if skey not in subresult:
                            subresult[skey] = {}
                        subresult = subresult[skey]
                subresult[subkey] = subval
        return result
    else:
        try:
            log.trace('Reading %s...', key)
            with os.fdopen(os.open(key, os.O_RDONLY | os.O_NONBLOCK)) as treader:
                val = treader.read().strip()
                if not val:
                    return False
                try:
                    val = int(val)
                except Exception:
                    try:
                        val = float(val)
                    except Exception:
                        pass
                return val
        except Exception:
            return False

