def retry_request(method, url, headers=None, payload=None, auth=None, tries=10, initial_interval=5, callback=None):
    method = method.lower()
    attempt = 1
    while True:
        if method == 'get':
            resp = requests.get(url, headers=headers, params=payload, auth=auth)
        elif method == 'put' or method == 'post':
            resp = requests.put(url, headers=headers, json=payload, auth=auth)
        else:
            raise_ise("Bad method %s: must be 'get', 'put', or 'post" % method)
        if resp.status_code < 400:
            break
        delay = initial_interval * attempt
        if attempt >= tries:
            raise_ise("Failed to '%s' %s after %d attempts." % (method, url, tries) + "  Last response was '%d %s' [%s]" % (resp.status_code, resp.reason, resp.text.strip()))
        if callback is not None:
            callback(n=attempt, remaining=tries - attempt, status=resp.status_code, content=resp.text.strip())
        time.sleep(delay)
        attempt += 1
    return resp

