def isolcss(prefix, css):
    try:
        all((True for m in matchiter(selrule_or_atom_re, css)))
    except ValueError as e:
        logger.warning('Strict parse failed at char {}'.format(e.args[0]))
        splits = matchiter(selrule_or_any_re, css)
    else:
        splits = matchiter(selrule_or_atom_re, css)
    css = []
    for m in splits:
        if not m.groupdict()['sels']:
            css.extend(m.group(0))
            continue
        sels = matchall(sel_re, m.group('sels'))
        assert sels, 'Failed to split selectors: {!r}'.format(m.group('sels'))
        for sel in sels:
            atoms = matchall(atom_re, sel)
            if '&' in atoms:
                sel = ''.join((prefix if a == '&' else a for a in atoms))
            else:
                sel = '%s %s' % (prefix, sel)
            css.append(sel)
        css.append(m.group('ruleset'))
    return ''.join(css)

def _rest_request(self, url, object_path, service_name, requests_config, tags, *args, **kwargs):
    service_check_tags = ['url:%s' % self._get_url_base(url)] + tags
    if object_path:
        url = self._join_url_dir(url, object_path)
    if isinstance(requests_config.ssl_verify, bool) or isinstance(requests_config.ssl_verify, str):
        verify = requests_config.ssl_verify
    else:
        verify = None
    if requests_config.ssl_cert and requests_config.ssl_key:
        cert = (requests_config.ssl_cert, requests_config.ssl_key)
    elif requests_config.ssl_cert:
        cert = requests_config.ssl_cert
    else:
        cert = None
    if args:
        for directory in args:
            url = self._join_url_dir(url, directory)
    if kwargs:
        query = '&'.join(['{0}={1}'.format(key, value) for (key, value) in iteritems(kwargs)])
        url = urljoin(url, '?' + query)
    old_keytab_path = None
    if requests_config.kerberos_keytab:
        old_keytab_path = os.getenv('KRB5_CLIENT_KTNAME')
        os.environ['KRB5_CLIENT_KTNAME'] = requests_config.kerberos_keytab
    try:
        self.log.debug('Spark check URL: %s' % url)
        response = requests.get(url, auth=requests_config.auth, verify=verify, cert=cert)
        response.raise_for_status()
    except Timeout as e:
        self.service_check(service_name, AgentCheck.CRITICAL, tags=service_check_tags, message='Request timeout: {0}, {1}'.format(url, e))
        raise
    except (HTTPError, InvalidURL, ConnectionError) as e:
        self.service_check(service_name, AgentCheck.CRITICAL, tags=service_check_tags, message='Request failed: {0}, {1}'.format(url, e))
        raise
    except ValueError as e:
        self.service_check(service_name, AgentCheck.CRITICAL, tags=service_check_tags, message=str(e))
        raise
    else:
        return response
    finally:
        if old_keytab_path is not None:
            os.environ['KRB5_CLIENT_KTNAME'] = old_keytab_path

def exists_using_casper(self, filename):
    casper_results = casper.Casper(self.connection['jss'])
    distribution_servers = casper_results.find('distributionservers')
    all_packages = []
    for distribution_server in distribution_servers:
        packages = set()
        for package in distribution_server.findall('packages/package'):
            packages.add(os.path.basename(package.find('fileURL').text))
        all_packages.append(packages)
    base_set = all_packages.pop()
    for packages in all_packages:
        base_set = base_set.intersection(packages)
    return filename in base_set

