def find_nearest_conn_objects(node_shp, branches, proj, conn_dist_weight, debug, branches_only=False):
    conn_diff_tolerance = cfg_ding0.get('mv_routing', 'conn_diff_tolerance')
    conn_objects_min_stack = []
    for branch in branches:
        stations = branch['adj_nodes']
        station1_shp = transform(proj, stations[0].geo_data)
        station2_shp = transform(proj, stations[1].geo_data)
        line_shp = LineString([station1_shp, station2_shp])
        if not branches_only:
            conn_objects = {'s1': {'obj': stations[0], 'shp': station1_shp, 'dist': node_shp.distance(station1_shp) * conn_dist_weight * 0.999}, 's2': {'obj': stations[1], 'shp': station2_shp, 'dist': node_shp.distance(station2_shp) * conn_dist_weight * 0.999}, 'b': {'obj': branch, 'shp': line_shp, 'dist': node_shp.distance(line_shp)}}
            if abs(conn_objects['s1']['dist'] - conn_objects['b']['dist']) < conn_diff_tolerance or abs(conn_objects['s2']['dist'] - conn_objects['b']['dist']) < conn_diff_tolerance:
                del conn_objects['b']
            if isinstance(conn_objects['s1']['obj'], MVStationDing0):
                del conn_objects['s1']
            elif isinstance(conn_objects['s2']['obj'], MVStationDing0):
                del conn_objects['s2']
        else:
            conn_objects = {'b': {'obj': branch, 'shp': line_shp, 'dist': node_shp.distance(line_shp)}}
        conn_objects_min = min(conn_objects.values(), key=lambda v: v['dist'])
        conn_objects_min_stack.append(conn_objects_min)
    conn_objects_min_stack = [_ for _ in sorted(conn_objects_min_stack, key=lambda x: x['dist'])]
    if debug:
        logger.debug('Stack length: {}'.format(len(conn_objects_min_stack)))
    return conn_objects_min_stack

def get_consensus_at(block_height, proxy=None, hostport=None):
    assert proxy or hostport, 'Need either proxy or hostport'
    if proxy is None:
        proxy = connect_hostport(hostport)
    consensus_schema = {'type': 'object', 'properties': {'consensus': {'anyOf': [{'type': 'string', 'pattern': OP_CONSENSUS_HASH_PATTERN}, {'type': 'null'}]}}, 'required': ['consensus']}
    resp_schema = json_response_schema(consensus_schema)
    resp = {}
    try:
        resp = proxy.get_consensus_at(block_height)
        resp = json_validate(resp_schema, resp)
        if json_is_error(resp):
            return resp
    except ValidationError as ve:
        if BLOCKSTACK_DEBUG:
            log.exception(ve)
        resp = {'error': 'Server response did not match expected schema.  You are likely communicating with an out-of-date Blockstack node.', 'http_status': 502}
        return resp
    except socket.timeout:
        log.error('Connection timed out')
        resp = {'error': 'Connection to remote host timed out.', 'http_status': 503}
        return resp
    except socket.error as se:
        log.error('Connection error {}'.format(se.errno))
        resp = {'error': 'Connection to remote host failed.', 'http_status': 502}
        return resp
    except Exception as ee:
        if BLOCKSTACK_DEBUG:
            log.exception(ee)
        log.error('Caught exception while connecting to Blockstack node: {}'.format(ee))
        resp = {'error': 'Failed to contact Blockstack node.  Try again with `--debug`.', 'http_status': 500}
        return resp
    if resp['consensus'] is None:
        return {'error': 'The node has not processed block {}'.format(block_height), 'http_status': 503}
    return resp['consensus']

