def process(self):
    subscription = None
    result = None
    try:
        subscription = self.socket.recv()
    except AuthenticateError as exception:
        logging.error('Subscriber error while authenticating request: {}'.format(exception), exc_info=1)
    except AuthenticatorInvalidSignature as exception:
        logging.error('Subscriber error while authenticating request: {}'.format(exception), exc_info=1)
    except DecodeError as exception:
        logging.error('Subscriber error while decoding request: {}'.format(exception), exc_info=1)
    except RequestParseError as exception:
        logging.error('Subscriber error while parsing request: {}'.format(exception), exc_info=1)
    else:
        logging.debug('Subscriber received payload: {}'.format(subscription))
    (_tag, message, fun) = self.parse(subscription)
    message = self.verify(message)
    message = self.decode(message)
    try:
        result = fun(message)
    except Exception as exception:
        logging.error(exception, exc_info=1)
    return result

def isordinal(x):
    import numpy as np
    if len(x) == len(np.unique(x)):
        return (False, 'number of observations equals the number of unique values.')
    if not isinstance(x[0], str):
        if not np.all(np.equal(np.mod(x, 1), 0)):
            return (False, 'elements are not integer or strings.')
    return (True, 'is ordinal')

def receive_messages(self, on_message_received):
    self.open()
    self._received_messages = None
    self._message_received_callback = on_message_received
    receiving = True
    try:
        while receiving:
            receiving = self.do_work()
    except:
        receiving = False
        raise
    finally:
        if not receiving:
            self.close()

def guess_url_vcs(url):
    parsed = urllib.parse.urlsplit(url)
    if parsed.scheme in ('git', 'svn'):
        return parsed.scheme
    elif parsed.path.endswith('.git'):
        return 'git'
    elif parsed.hostname == 'github.com':
        return 'git'
    if parsed.scheme in ('http', 'https'):
        resp = requests.get(url)
        if re.match('basehttp.*python.*', resp.headers.get('server').lower()):
            return 'hg'
    return None

