def __command_queue_listener(self):
    self.log.debug('Queue listener thread started')
    counter = itertools.count()
    while not self.__shutdown:
        if self.__pipe_commands.poll(1):
            try:
                message = self.__pipe_commands.recv()
            except EOFError:
                self.__shutdown = True
                self.log.error('Pipe closed by frontend, shutting down service', exc_info=True)
                break
            queue_item = (Priority.COMMAND, next(counter), message)
            try:
                self.__queue.put(queue_item, True, 60)
            except queue.Full:
                self.__shutdown = True
                self.log.error('Write to service priority queue failed, shutting down service', exc_info=True)
                break
    self.log.debug('Queue listener thread terminating')

def logs(ctx, services, num, follow):
    logger.debug('running command %s (%s)', ctx.command.name, ctx.params, extra={'command': ctx.command.name, 'params': ctx.params})
    home = ctx.obj['HOME']
    services_path = os.path.join(home, SERVICES)
    tail_threads = []
    for service in services:
        logpath = os.path.join(services_path, service, LOGS_DIR, STDOUTLOG)
        if os.path.exists(logpath):
            logger.debug('tailing %s', logpath)
            t = threading.Thread(target=Tailer, kwargs={'name': service, 'nlines': num, 'filepath': logpath, 'follow': follow})
            t.daemon = True
            t.start()
            tail_threads.append(t)
    if tail_threads:
        while tail_threads[0].isAlive():
            tail_threads[0].join(0.1)

def bin_spikes(spike_times, binsz):
    bins = np.empty((len(spike_times),), dtype=int)
    for (i, stime) in enumerate(spike_times):
        bins[i] = np.floor(np.around(stime / binsz, 5))
    return bins

def export(self, folder_path, format=None):
    if format is None:
        raise ValueError('Must export to a specific format, no format specified.')
    format = format.lower()
    if format == 'trackline' or format[-4:] == 'trkl':
        ex.Trackline.export(folder=folder_path, particles=self.particles, datetimes=self.datetimes)
    elif format == 'shape' or format == 'shapefile' or format[-3:] == 'shp':
        ex.GDALShapefile.export(folder=folder_path, particles=self.particles, datetimes=self.datetimes)
    elif format == 'netcdf' or format[-2:] == 'nc':
        ex.NetCDF.export(folder=folder_path, particles=self.particles, datetimes=self.datetimes, summary=str(self))
    elif format == 'pickle' or format[-3:] == 'pkl' or format[-6:] == 'pickle':
        ex.Pickle.export(folder=folder_path, particles=self.particles, datetimes=self.datetimes)

def communicate(self, input=None):
    if [self.stdin, self.stdout, self.stderr].count(None) >= 2:
        stdout = None
        stderr = None
        if self.stdin:
            if input:
                try:
                    self.stdin.write(input)
                except IOError as e:
                    if e.errno != errno.EPIPE and e.errno != errno.EINVAL:
                        raise
            self.stdin.close()
        elif self.stdout:
            stdout = _eintr_retry_call(self.stdout.read)
            self.stdout.close()
        elif self.stderr:
            stderr = _eintr_retry_call(self.stderr.read)
            self.stderr.close()
        self.wait()
        return (stdout, stderr)
    return self._communicate(input)

