def transition_matrix_non_reversible(C):
    rowsums = 1.0 * np.sum(C, axis=1)
    if np.min(rowsums) <= 0:
        raise ValueError('Transition matrix has row sum of ' + str(np.min(rowsums)) + '. Must have strictly positive row sums.')
    return np.divide(C, rowsums[:, np.newaxis])

def format_errors(errors):

    def _get_message(node):
        messages = set()
        try:
            messages.update([node['message']])
        except KeyError:
            pass
        for check_group in ['any', 'all', 'none']:
            try:
                for check in node[check_group]:
                    messages.update([check.get('message')])
            except KeyError:
                pass
        messages = messages.difference([''])
        return '; '.join(messages)
    lines = []
    for error_type in errors:
        lines.append(u'Severity: {}'.format(error_type.get('impact')))
        lines.append(u'Rule ID: {}'.format(error_type.get('id')))
        lines.append(u'Help URL: {}\n'.format(error_type.get('helpUrl')))
        for node in error_type['nodes']:
            msg = u'Message: {}'.format(_get_message(node))
            html = u'Html: {}'.format(node.get('html').encode('utf-8'))
            target = u'Target: {}'.format(node.get('target'))
            fill_opts = {'width': 100, 'initial_indent': '\t', 'subsequent_indent': '\t\t'}
            lines.append(fill(msg, **fill_opts))
            lines.append(fill(html, **fill_opts))
            lines.append(fill(target, **fill_opts))
            lines.append('\n')
    return '\n'.join(lines)

