def _find_executables(name):
    exe_name = name + '.exe' * sys.platform.startswith('win')
    env_path = os.environ.get(name.upper() + '_PATH', '')
    possible_locations = []

    def add(*dirs):
        for d in dirs:
            if d and d not in possible_locations and os.path.isdir(d):
                possible_locations.append(d)
    add(env_path)
    try:
        add(os.path.dirname(os.path.abspath(__file__)))
    except NameError:
        pass
    add(os.path.dirname(sys.executable))
    add(os.path.expanduser('~'))
    if sys.platform.startswith('win'):
        add('c:\\program files', os.environ.get('PROGRAMFILES'), 'c:\\program files (x86)', os.environ.get('PROGRAMFILES(x86)'))
    else:
        possible_locations.extend(['/usr/bin', '/usr/local/bin', '/opt/local/bin'])

    def do_check_version(exe):
        try:
            return subprocess.check_output([exe, '--version']).decode().strip()
        except Exception:
            return False
    if os.path.isfile(env_path):
        ver = do_check_version(env_path)
        if ver:
            return (env_path, ver)
    for d in possible_locations:
        for exe in [os.path.join(d, exe_name), os.path.join(d, name, exe_name)]:
            if os.path.isfile(exe):
                ver = do_check_version(exe)
                if ver:
                    return (exe, ver)
    ver = do_check_version(exe_name)
    if ver:
        return (exe_name, ver)
    for d in possible_locations:
        for sub in reversed(sorted(os.listdir(d))):
            if sub.startswith(name):
                exe = os.path.join(d, sub, exe_name)
                if os.path.isfile(exe):
                    ver = do_check_version(exe)
                    if ver:
                        return (exe, ver)
    return (None, None)

def _update_mask(self, mask: np.ndarray, polygons: Iterable, separate_instances: bool=False) -> None:
    for (i, p) in enumerate(polygons):
        if isinstance(p, geometry.MultiPolygon):
            self._update_mask(mask=mask, polygons=p.geoms, separate_instances=True)
            continue
        elif not isinstance(p, geometry.Polygon):
            continue
        poly_area = Image.fromarray(np.zeros(mask.shape, dtype=np.uint8))
        holes = Image.fromarray(np.zeros(mask.shape, dtype=np.uint8))
        outline_color = 0 if separate_instances else 255
        ImageDraw.Draw(poly_area).polygon(p.exterior.coords, fill=255, outline=outline_color)
        for h in p.interiors:
            ImageDraw.Draw(holes).polygon(h.coords, fill=255, outline=255)
        mask[np.nonzero(np.array(poly_area, dtype=np.uint8))] = 255
        mask[np.nonzero(np.array(holes, dtype=np.uint8))] = 0

