def encoded_datastream(self):
    size = 0
    if self.verify:
        md5 = hashlib.md5()
    leftover = None
    while self.within_file:
        content = self.get_next_section()
        if content == BINARY_CONTENT_END:
            if self.verify:
                logger.info('Decoded content size %s (%s) MD5 %s', size, humanize_file_size(size), md5.hexdigest())
            self.within_file = False
        elif self.within_file:
            if leftover is not None:
                content = b''.join([leftover, content])
                leftover = None
            try:
                decoded_content = binascii.a2b_base64(content)
            except binascii.Error:
                lines = content.split(b'\n')
                decoded_content = binascii.a2b_base64(b''.join(lines[:-1]))
                leftover = lines[-1]
            if decoded_content is not None:
                if self.verify:
                    md5.update(decoded_content)
                size += len(decoded_content)
                yield decoded_content

async def dispatch(request):
    if session:
        message = ''
        data = await request.json()
        try:
            log.info('Dispatching {}'.format(data))
            _id = data.get('token')
            if not _id:
                message = '"token" field required for calibration requests'
                raise AssertionError
            command = data.get('command')
            if not command:
                message = '"command" field required for calibration requests'
                raise AssertionError
            if _id == session.id:
                res = await router[command](data)
            else:
                res = web.json_response({'message': 'Invalid token: {}'.format(_id)}, status=403)
        except AssertionError:
            res = web.json_response({'message': message}, status=400)
        except Exception as e:
            res = web.json_response({'message': 'Exception {} raised by dispatch of {}: {}'.format(type(e), data, e)}, status=500)
    else:
        res = web.json_response({'message': 'Session must be started before issuing commands'}, status=418)
    return res

def Jkpw(dW, h, n=5):
    m = dW.shape[1]
    (A, I) = Ikpw(dW, h, n)
    J = I + 0.5 * h * np.eye(m).reshape((1, m, m))
    return (A, J)

