def phenotypes_to_scored(self, phenotypes=None, overwrite=False):
    if not self.is_uniform():
        raise ValueError('inconsistent phenotypes')
    if phenotypes is None:
        phenotypes = self.phenotypes
    elif isinstance(phenotypes, str):
        phenotypes = [phenotypes]

    def _post(binary, phenotype_label, phenotypes, overwrite):
        d = binary.copy()
        if len(set(phenotypes) & set(list(binary.keys()))) > 0 and overwrite == False:
            raise ValueError('Error, phenotype already exists as a scored type')
        for label in phenotypes:
            d[label] = 0
        if phenotype_label == phenotype_label and phenotype_label in phenotypes:
            d[phenotype_label] = 1
        return d
    output = self.copy()
    output['scored_calls'] = output.apply(lambda x: _post(x['scored_calls'], x['phenotype_label'], phenotypes, overwrite), 1)
    return output

def _load_recursive(self, shape, gen):
    if len(shape) > 0:
        ans = []
        for i in range(shape[0]):
            ans.append(self._load_recursive(shape[1:], gen))
    else:
        fields = []
        for (code, length) in self.format:
            field = None
            raw = gen.send(length)
            if code == 'u':
                field = raw
            elif code == 'i':
                field = raw
                if field >= 1 << length - 1:
                    field -= 1 << length
            elif code == 'b':
                field = bool(raw)
            elif code == 'c':
                field = six.int2byte(raw)
            elif code == 'f':
                if length == 32:
                    field = _np.uint32(raw).view(_np.float32)
                elif length == 64:
                    field = _np.uint64(raw).view(_np.float64)
                else:
                    raise ValueError('unhandled float length {0}'.format((code, length)))
            else:
                raise ValueError('unhandled format {0}'.format((code, length)))
            fields.append(field)
        if len(fields) == 1:
            ans = fields[0]
        else:
            ans = tuple(fields)
    return ans

