def pad_length(s):
    padding_chars = [u'﹎', u'Ѝ', u'א', u'ǆ', u'ᾏ', u'Ⅷ', u'㈴', u'㋹', u'퓛', u'ﺏ', u'𝟘', u'🚦']
    padding_generator = itertools.cycle(padding_chars)
    target_lengths = {six.moves.range(1, 11): 3, six.moves.range(11, 21): 2, six.moves.range(21, 31): 1.8, six.moves.range(31, 51): 1.6, six.moves.range(51, 71): 1.4}
    if len(s) > 70:
        target_length = int(math.ceil(len(s) * 1.3))
    else:
        for (r, v) in target_lengths.items():
            if len(s) in r:
                target_length = int(math.ceil(len(s) * v))
    diff = target_length - len(s)
    pad = u''.join([next(padding_generator) for _ in range(diff)])
    return s + pad

def regularizer(name, regularization_fn, name_filter='weights'):
    regex = re.compile(name_filter)

    def fn(var_name, variable, phase):
        if phase is pt.Phase.train and regex.search(var_name):
            with tf.name_scope(None, name, [variable]):
                loss = regularization_fn(variable)
            if loss is not None:
                tf.add_to_collection(tf.GraphKeys.REGULARIZATION_LOSSES, loss)
        return variable
    return fn

def read(self, n=None):
    response = ''
    while n is None or n > 0:
        c = self.stream.read(1)
        if c == '':
            break
        elif c == '<':
            c += self.stream.read(1)
            if c == '<?':
                while True:
                    q = self.stream.read(1)
                    if q == '>':
                        break
            else:
                response += c
                if n is not None:
                    n -= len(c)
        else:
            response += c
            if n is not None:
                n -= 1
    return response

