def check_writing(i):
    dl = i.get('delete', '')
    if dl == 'yes' and cfg.get('forbid_global_delete', '') == 'yes':
        return {'return': 1, 'error': 'delete/rename operations are forbidden'}
    if cfg.get('forbid_global_writing', '') == 'yes':
        return {'return': 1, 'error': 'global writing is forbidden'}
    if len(i) == 0:
        return {'return': 0}
    if cfg.get('forbid_writing_modules', '') == 'yes':
        muoa = i.get('module_uoa', '')
        muid = i.get('module_uid', '')
        if muoa == cfg['module_name'] or (muid != '' and muid in cfg['module_uids']):
            return {'return': 1, 'error': 'writing/changing modules is forbidden'}
    ruoa = i.get('repo_uoa', '')
    ruid = i.get('repo_uid', '')
    if cfg.get('forbid_writing_to_default_repo', '') == 'yes':
        if ruoa == cfg['repo_name_default'] or ruid == cfg['repo_uid_default']:
            return {'return': 1, 'error': 'writing to default repo is forbidden'}
    if cfg.get('forbid_writing_to_local_repo', '') == 'yes':
        if ruoa == cfg['repo_name_local'] or ruid == cfg['repo_uid_local']:
            return {'return': 1, 'error': 'writing to local repo is forbidden'}
    rr = {'return': 0}
    rd = {}
    if ruoa != '':
        if 'repo_dict' in i:
            rd = i['repo_dict']
        else:
            rx = load_repo_info_from_cache({'repo_uoa': ruoa})
            if rx['return'] > 0:
                return rx
            rd = rx.get('dict', {})
        rr['repo_dict'] = rd
    if cfg.get('allow_writing_only_to_allowed', '') == 'yes':
        if rd.get('allow_writing', '') != 'yes':
            return {'return': 1, 'error': 'writing to this repo is forbidden'}
    if rd.get('forbid_deleting', '') == 'yes' and dl == 'yes':
        return {'return': 1, 'error': 'deleting in this repo is forbidden'}
    return rr

def _file_stats(file_path, enforce_fastx=True):
    if isinstance(file_path, tuple):
        assert len(file_path) == 2
        file_size = sum((_file_size(f, uncompressed=True) for f in file_path))
        file_path = interleaved_filename(file_path)
        paired = True
    else:
        file_size = _file_size(file_path, uncompressed=False)
        paired = False
    (new_filename, ext) = os.path.splitext(os.path.basename(file_path))
    if ext in {'.gz', '.gzip', '.bz', '.bz2', '.bzip'}:
        compressed = ext
        (new_filename, ext) = os.path.splitext(new_filename)
    else:
        compressed = ''
    if paired and compressed:
        final_filename = new_filename + ext
    else:
        final_filename = new_filename + ext + compressed
    if enforce_fastx:
        if ext in {'.fa', '.fna', '.fasta'}:
            file_format = 'fasta'
        elif ext in {'.fq', '.fastq'}:
            file_format = 'fastq'
        else:
            raise UploadException('{}: extension must be one of .fa, .fna, .fasta, .fq, .fastq'.format(final_filename))
    else:
        file_format = None
    if file_size == 0:
        raise UploadException('{}: empty files can not be uploaded'.format(final_filename))
    return (final_filename, file_size, file_format)

async def iter(self, url: Union[str, methods], data: Optional[MutableMapping]=None, headers: Optional[MutableMapping]=None, *, limit: int=200, iterkey: Optional[str]=None, itermode: Optional[str]=None, minimum_time: Optional[int]=None, as_json: Optional[bool]=None) -> AsyncIterator[dict]:
    itervalue = None
    if not data:
        data = {}
    last_request_time = None
    while True:
        current_time = time.time()
        if minimum_time and last_request_time and (last_request_time + minimum_time > current_time):
            await self.sleep(last_request_time + minimum_time - current_time)
        (data, iterkey, itermode) = sansio.prepare_iter_request(url, data, iterkey=iterkey, itermode=itermode, limit=limit, itervalue=itervalue)
        last_request_time = time.time()
        response_data = await self.query(url, data, headers, as_json)
        itervalue = sansio.decode_iter_request(response_data)
        for item in response_data[iterkey]:
            yield item
        if not itervalue:
            break

