def certify_int(value, min_value=None, max_value=None, required=True):
    certify_params((_certify_int_param, 'max_length', max_value, dict(negative=True, required=False)), (_certify_int_param, 'min_length', min_value, dict(negative=True, required=False)))
    if certify_required(value=value, required=required):
        return
    if not isinstance(value, six.integer_types):
        raise CertifierTypeError(message='expected integer, but value is of type {cls!r}'.format(cls=value.__class__.__name__), value=value, required=required)
    if min_value is not None and value < min_value:
        raise CertifierValueError(message='{value} is less than minimum acceptable {min}'.format(value=value, min=min_value), value=value, required=required)
    if max_value is not None and value > max_value:
        raise CertifierValueError(message='{value} is more than the maximum acceptable {max}'.format(value=value, max=max_value), value=value, required=required)

def _reconstruct_object(typ, obj, axes, dtype):
    try:
        typ = typ.type
    except AttributeError:
        pass
    res_t = np.result_type(obj.dtype, dtype)
    if not isinstance(typ, partial) and issubclass(typ, pd.core.generic.PandasObject):
        return typ(obj, dtype=res_t, **axes)
    if hasattr(res_t, 'type') and typ == np.bool_ and (res_t != np.bool_):
        ret_value = res_t.type(obj)
    else:
        ret_value = typ(obj).astype(res_t)
        if len(obj.shape) == 1 and len(obj) == 1:
            if not isinstance(ret_value, np.ndarray):
                ret_value = np.array([ret_value]).astype(res_t)
    return ret_value

