def _get_grounding(entity):
    db_refs = {'TEXT': entity['text']}
    groundings = entity.get('grounding')
    if not groundings:
        return db_refs

    def get_ont_concept(concept):
        if concept.startswith('/'):
            concept = concept[1:]
            concept = concept.replace(' ', '_')
            while concept not in hume_onto_entries:
                parts = concept.split('/')
                if len(parts) == 1:
                    break
                concept = '/'.join(parts[:-1])
        return concept
    raw_grounding_entries = [(get_ont_concept(g['ontologyConcept']), g['value']) for g in groundings]
    grounding_dict = {}
    for (cat, score) in raw_grounding_entries:
        if cat not in grounding_dict or score > grounding_dict[cat]:
            grounding_dict[cat] = score
    grounding_entries = sorted(list(set(grounding_dict.items())), key=lambda x: (x[1], x[0].count('/'), x[0]), reverse=True)
    if grounding_entries:
        db_refs['HUME'] = grounding_entries
    return db_refs

def pop(self, name: str, default: Any=_sentinel) -> Any:
    if default is _sentinel:
        return self.__dict__.pop(name)
    else:
        return self.__dict__.pop(name, default)

def make_form_field(field, model=None, field_cls=None, use_default_value=True, builds_args_map=None):
    import uliweb.form as form
    from uliweb.form.validators import TEST_MAXLENGTH
    builds_args_map = builds_args_map or {}
    if model:
        model = get_model(model)
    if isinstance(field, BaseField):
        return field
    if isinstance(field, dict) and 'field' in field and isinstance(field['field'], BaseField):
        return field['field']
    field_type = None
    prop = None
    if isinstance(field, (str, unicode)):
        field = {'name': field}
    if isinstance(field, dict):
        prop = field.get('prop')
        if not prop and model:
            field_name = field.get('field_name') or field['name']
            prop = get_model_property(model, field_name)
            if not prop and (not field_cls):
                raise UliwebError("Can't find property %s in Model(%r)" % (field_name, model.__name__))
    else:
        raise UliwebError("Can't support this field %r type in make_form_field" % type(field))
    default_kwargs = {}
    if prop:
        default_kwargs = {'label': prop.label or prop.property_name, 'help_string': prop.hint, 'placeholder': prop.placeholder, 'html_attrs': prop.extra.get('html_attrs', {}), 'required': prop.required}
    kwargs = {'label': field.get('label') or field.get('verbose_name') or default_kwargs.get('label'), 'help_string': field.get('hint') or field.get('help_string') or default_kwargs.get('help_string'), 'placeholder': field.get('placeholder') or default_kwargs.get('placeholder'), 'html_attrs': field.get('extra', {}).get('html_attrs', {}) or default_kwargs.get('html_attrs'), 'required': field.get('required', False) if 'required' in field else default_kwargs.get('required', False)}
    if 'data-url' in field:
        kwargs['html_attrs']['data-url'] = field['data-url']
    if use_default_value:
        v = prop.default_value()
        kwargs['default'] = v
    if field.get('static'):
        field_type = form.StringField
        kwargs['required'] = False
        kwargs['static'] = True
        if prop.choices is not None:
            kwargs['choices'] = prop.get_choices()
    if field.get('hidden'):
        field_type = form.HiddenField
    if field_cls:
        field_type = field_cls
    elif not field_type:
        cls = prop.__class__
        type_name = prop.type_name
        if type_name == 'BLOG':
            pass
        elif type_name in ('TEXT', 'JSON'):
            field_type = form.TextField
        elif type_name in ('CHAR', 'VARCHAR', 'UUID'):
            if prop.choices is not None:
                field_type = form.SelectField
                kwargs['choices'] = prop.get_choices()
            elif cls.__name__ == 'FileProperty':
                field_type = form.FileField
                kwargs['upload_to'] = prop.upload_to
                kwargs['upload_to_sub'] = prop.upload_to_sub
            else:
                field_type = form.UnicodeField
        elif type_name == 'BOOL':
            field_type = form.BooleanField
        elif type_name == 'DATE':
            field_type = form.DateField
        elif type_name == 'TIME':
            field_type = form.TimeField
        elif type_name == 'DATETIME':
            field_type = form.DateTimeField
        elif type_name == 'DECIMAL':
            field_type = form.StringField
            if prop.choices is not None:
                field_type = form.SelectField
                kwargs['choices'] = prop.get_choices()
        elif type_name == 'FLOAT':
            field_type = form.FloatField
        elif type_name == 'INTEGER':
            if prop.choices is not None:
                field_type = form.SelectField
                kwargs['choices'] = prop.get_choices()
                kwargs['datetype'] = int
            else:
                field_type = form.IntField
        elif type_name == 'ManyToMany':
            kwargs['model'] = prop.reference_class
            field_type = ManyToManySelectField
        elif type_name in ('Reference', 'OneToOne'):
            kwargs['model'] = prop.reference_class
            kwargs['value_field'] = prop.reference_fieldname
            field_type = ReferenceSelectField
        else:
            raise ValueError("Can't support the Property [%s=%s]" % (field['name'], prop.__class__.__name__))
    if field_type:
        build_args = builds_args_map.get(field_type, {})
        if not build_args:
            build_args = get_fileds_builds().get(field_type, {})
        kwargs.update(build_args)
        if issubclass(prop.__class__, (orm.StringProperty, orm.CharProperty, orm.UnicodeProperty)):
            v = kwargs.setdefault('validators', [])
            if isinstance(prop.max_length, int):
                v.append(TEST_MAXLENGTH(prop.max_length))
        f = field_type(**kwargs)
        return f

def get_normalized_variable_map(scope_or_module, collection=tf.GraphKeys.GLOBAL_VARIABLES, context=None, group_sliced_variables=True):
    scope_name = get_variable_scope_name(scope_or_module)
    if context is None:
        context = scope_or_module
    prefix = get_variable_scope_name(context)
    prefix_length = len(prefix) + 1 if prefix else 0
    if not _is_scope_prefix(scope_name, prefix):
        raise ValueError("Scope '{}' is not prefixed by '{}'.".format(scope_name, prefix))
    variables = get_variables_in_scope(scope_name, collection)
    if not group_sliced_variables:
        single_vars = variables
        grouped_vars = dict()
    else:
        (single_vars, grouped_vars) = _get_sliced_variables(variables)
    var_map = {var.op.name[prefix_length:]: var for var in single_vars}
    for (full_name, var_group) in grouped_vars.items():
        name = full_name[prefix_length:]
        if name in var_map:
            raise ValueError('Mixing slices and non-slices with the same name: ' + str(name))
        var_map[name] = var_group
    return var_map

def select(cls, dataset, selection_mask=None, **selection):
    import iris
    constraint = cls.select_to_constraint(dataset, selection)
    pre_dim_coords = [c.name() for c in dataset.data.dim_coords]
    indexed = cls.indexed(dataset, selection)
    extracted = dataset.data.extract(constraint)
    if indexed and (not extracted.dim_coords):
        return extracted.data.item()
    post_dim_coords = [c.name() for c in extracted.dim_coords]
    dropped = [c for c in pre_dim_coords if c not in post_dim_coords]
    for d in dropped:
        extracted = iris.util.new_axis(extracted, d)
    return extracted

def taf_line(line: TafLineData, units: Units) -> str:
    speech = []
    start = type_and_times(line.type, line.start_time, line.end_time, line.probability)
    if line.wind_direction and line.wind_speed:
        speech.append(wind(line.wind_direction, line.wind_speed, line.wind_gust, unit=units.wind_speed))
    if line.wind_shear:
        speech.append(wind_shear(line.wind_shear, units.altimeter, units.wind_speed))
    if line.visibility:
        speech.append(visibility(line.visibility, units.visibility))
    if line.altimeter:
        speech.append(altimeter(line.altimeter, units.altimeter))
    if line.other:
        speech.append(other(line.other))
    speech.append(translate.clouds(line.clouds, units.altitude).replace(' - Reported AGL', ''))
    if line.turbulance:
        speech.append(translate.turb_ice(line.turbulance, units.altitude))
    if line.icing:
        speech.append(translate.turb_ice(line.icing, units.altitude))
    return start + ' ' + '. '.join([l for l in speech if l]).replace(',', '.')

def _check_ubridge_version(self, env=None):
    try:
        output = (yield from subprocess_check_output(self._path, '-v', cwd=self._working_dir, env=env))
        match = re.search('ubridge version ([0-9a-z\\.]+)', output)
        if match:
            self._version = match.group(1)
            if sys.platform.startswith('win') or sys.platform.startswith('darwin'):
                minimum_required_version = '0.9.12'
            else:
                minimum_required_version = '0.9.14'
            if parse_version(self._version) < parse_version(minimum_required_version):
                raise UbridgeError('uBridge executable version must be >= {}'.format(minimum_required_version))
        else:
            raise UbridgeError('Could not determine uBridge version for {}'.format(self._path))
    except (OSError, subprocess.SubprocessError) as e:
        raise UbridgeError('Error while looking for uBridge version: {}'.format(e))

def _get_device_methods(self, device):
    if device.is_filesystem:
        if device.is_mounted:
            if self._mounter._browser:
                yield 'browse'
            if self._mounter._terminal:
                yield 'terminal'
            yield 'unmount'
        else:
            yield 'mount'
    elif device.is_crypto:
        if device.is_unlocked:
            yield 'lock'
        else:
            yield 'unlock'
        cache = self._mounter._cache
        if cache and device in cache:
            yield 'forget_password'
    if device.is_ejectable and device.has_media:
        yield 'eject'
    if device.is_detachable:
        yield 'detach'
    if device.is_loop:
        yield 'delete'

def weights(self, other):
    try:
        return self._wdata(other)
    except AttributeError:
        frequency_dim = other.dimensions[-1]
        return self._wdata(frequency_dim.scale)

def verify_document(self, document: Document) -> bool:
    signature = base64.b64decode(document.signatures[0])
    prepended = signature + bytes(document.raw(), 'ascii')
    try:
        self.verify(prepended)
        return True
    except ValueError:
        return False
